"""
tinyllama_programs.py -- generated by make_programs.ipynb

Model:     TinyLlama/TinyLlama-1.1B-intermediate-step-1431k-3T
Shape:     22 layers x 32 heads = 704 programs
Signature: (sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]
Scoring:   soft IoU (min/max), higher is better

Self-contained: every helper the programs call is defined below. Generated
programs are written out verbatim -- there is no text-rewriting conversion step.
"""
from typing import Tuple

from transformers import PreTrainedTokenizerBase

import numpy as np

_MODEL_ID = 'TinyLlama/TinyLlama-1.1B-intermediate-step-1431k-3T'
_nlp = None
_emb = None


def _get_nlp():
    global _nlp
    if _nlp is None:
        import spacy
        _nlp = spacy.load("en_core_web_sm")
    return _nlp


def _get_embeddings():
    """Input-embedding matrix of the model under study, loaded once."""
    global _emb
    if _emb is None:
        from transformers import AutoModel
        m = AutoModel.from_pretrained(_MODEL_ID)
        _emb = m.get_input_embeddings().weight.detach().to("cpu").float().numpy()
    return _emb


def tokenize(sentence, tokenizer):
    """Model tokens for `sentence`, as strings. This is the tokenization every
    program must use -- the attention matrix is aligned to it."""
    ids = tokenizer(sentence, return_tensors="pt").input_ids[0]
    return tokenizer.convert_ids_to_tokens(ids)


def spacy_parse(sentence):
    """spaCy Doc: .pos_, .dep_, .head, .ent_type_, .lemma_ ..."""
    return _get_nlp()(sentence)


def _char_spans(sentence, tokenizer):
    """(start, end) char span per model token. Uses fast-tokenizer offsets when
    available, else falls back to cumulative decoded length."""
    try:
        enc = tokenizer(sentence, return_offsets_mapping=True)
        om = enc["offset_mapping"]
        if om and any(e > s for s, e in om):
            return [tuple(x) for x in om]
    except Exception:
        pass
    spans, pos = [], 0
    for t in tokenize(sentence, tokenizer):
        clean = t.lstrip("\u0120").lstrip("##").lstrip()
        idx = sentence.find(clean, pos) if clean else pos
        if idx < 0:
            idx = pos
        spans.append((idx, idx + len(clean)))
        pos = idx + max(len(clean), 1)
    return spans


def align_tokens_to_spacy(sentence, tokens, tokenizer):
    """For each model token, the indices of spaCy tokens it overlaps."""
    doc = _get_nlp()(sentence)
    spans = _char_spans(sentence, tokenizer)
    out = []
    for (s, e) in spans[:len(tokens)]:
        out.append([k for k, w in enumerate(doc)
                    if not (w.idx + len(w.text) <= s or w.idx >= e)])
    while len(out) < len(tokens):
        out.append([])
    return out


def align_spacy_to_tokens(sentence, tokens, tokenizer):
    """Inverse map: for each spaCy token, the model-token indices covering it."""
    doc = _get_nlp()(sentence)
    fwd = align_tokens_to_spacy(sentence, tokens, tokenizer)
    out = [[] for _ in doc]
    for ti, sids in enumerate(fwd):
        for si in sids:
            if si < len(out):
                out[si].append(ti)
    return out


def get_modifying_adjectives(token):
    """spaCy children of `token` that are adjectival modifiers."""
    return [c for c in token.children if c.dep_ in ("amod", "advmod")]


def embedding_similarity(tokens, i, j, tokenizer):
    """Cosine similarity between tokens[i] and tokens[j] in the model's own
    input-embedding space. Use this instead of string equality to catch
    morphological and semantic relatives ("heard"/"hear", "cat"/"kitten")."""
    emb = _get_embeddings()
    try:
        a = emb[tokenizer.convert_tokens_to_ids(tokens[i])]
        b = emb[tokenizer.convert_tokens_to_ids(tokens[j])]
    except Exception:
        return 0.0
    na, nb = np.linalg.norm(a), np.linalg.norm(b)
    if na == 0 or nb == 0:
        return 0.0
    return float(np.dot(a, b) / (na * nb))


def make_row_stochastic(matrix):
    """Normalize each row to sum to 1; uniform-causal fallback for dead rows."""
    m = np.asarray(matrix, dtype=np.float64).copy()
    m[m < 0] = 0.0
    for i in range(m.shape[0]):
        s = m[i].sum()
        if s <= 0:
            m[i, : i + 1] = 1.0 / (i + 1)
        else:
            m[i] /= s
    return m


def apply_causal_mask(matrix):
    """Zero the strict upper triangle: token i may only attend to j <= i."""
    return np.tril(np.asarray(matrix, dtype=np.float64))



def prog_L0H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal-prefix averaging; punctuation discounts within-word suffix keys.
    The special case redistributes prefix mass without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_prefix_with_suffix_discount", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    bos_token = tokenizer.bos_token
    has_bos = tokens[0] == bos_token

    pos = []
    punctuation = []
    continuation = []
    for i, token in enumerate(tokens):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos.append(word.pos_ if word is not None else "")
        surface = token.lstrip("▁Ġ").strip()
        punctuation.append(
            token not in special_tokens
            and bool(surface)
            and all(not c.isalnum() and not c.isspace() for c in surface)
        )
        continuation.append(
            i > 0
            and token not in special_tokens
            and not token.startswith(("▁", "Ġ"))
            and bool(surface)
            and surface.isalnum()
            and word is not None
            and word.pos_ not in ("PUNCT", "SPACE", "SYM")
            and bool(set(aligned).intersection(alignment[i - 1]))
        )

    for i in range(n):
        weights = np.ones(i + 1, dtype=np.float64)
        query_pos = pos[i]

        if has_bos and i > 0:
            if query_pos in ("DET", "ADP"):
                weights[0] = 0.72
            elif query_pos == "AUX":
                weights[0] = 0.64
            elif query_pos == "VERB":
                weights[0] = 0.90
            elif query_pos in ("NOUN", "PROPN"):
                weights[0] = 1.07
            elif query_pos == "CCONJ":
                weights[0] = 0.88
            else:
                weights[0] = 1.00

            if query_pos == "DET":
                weights[i] *= 1.06
            elif query_pos == "AUX":
                weights[i] *= 1.04

            if i >= 2:
                weights[1] *= 1.025

            if i == 1:
                if query_pos in ("DET", "ADP"):
                    weights[:] = (0.44, 0.56)
                elif query_pos == "PROPN":
                    weights[:] = (0.535, 0.465)
                else:
                    weights[:] = (0.508, 0.492)

        if punctuation[i] and tokens[i] not in special_tokens:
            surface = tokens[i].lstrip("▁Ġ").strip()
            is_quote = bool(surface) and all(c in "\"'“”‘’«»" for c in surface)
            if not is_quote:
                distances = i - np.arange(i + 1, dtype=np.float64)
                weights = np.exp(-1.05 * distances / (i + 1.0))
                if has_bos and i > 0:
                    weights[0] *= 0.20
            elif has_bos and i > 0:
                weights[0] = 0.82

            # Punctuation overweights suffix pieces under plain recency.
            # Redistribute only non-BOS, non-self mass, preserving both anchors.
            if not is_quote and i > 1 and any(continuation[1:i]):
                prefix_mass = weights[1:i].sum()
                for j in range(1, i):
                    if continuation[j]:
                        weights[j] *= 0.50
                weights[1:i] *= prefix_mass / weights[1:i].sum()

        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_prefix_with_suffix_discount", attention


def prog_L0H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Broad causal averaging with mild rotary-like recency, self preference,
    reduced BOS attention, and a small determiner-key bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "broad_causal_positional_average", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    key_bias = np.zeros(n, dtype=np.float64)
    self_bias = np.zeros(n, dtype=np.float64)
    for j in range(n):
        for sid in aligned[j]:
            word = doc[sid]
            if word.pos_ == "DET":
                key_bias[j] = 0.16
                self_bias[j] = 0.08
            elif word.pos_ == "PUNCT":
                self_bias[j] = -0.05

    special_tokens = tokenizer.all_special_tokens
    has_bos = tokens[0] in special_tokens

    for i in range(n):
        positions = np.arange(i + 1)
        distance = i - positions

        # A broad, weakly oscillatory kernel rather than a narrow local window.
        logits = (
            0.10 * np.cos(0.95 * distance)
            + 0.08 * np.cos(0.25 * distance)
            + 0.10 * np.exp(-distance / 2.0)
            + key_bias[:i + 1]
        )
        logits[i] += 0.04 + self_bias[i]

        if has_bos:
            # BOS is visible but is not an attention sink in this head.
            logits[0] = -0.16
            if i == 0:
                logits[0] = 0.0

        weights = np.exp(logits - np.max(logits))
        attention[i, :i + 1] = weights / weights.sum()

    return "broad_causal_positional_average", attention


def prog_L0H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging with weak primacy.
    In dialogue, opening quotes act as persistent anchors; preserve baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_causal_with_quote_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens
    positions = np.arange(n, dtype=np.float64)

    # A weak, bounded primacy bias rather than a local-attention window.
    key_bias = -0.45 * (1.0 - np.exp(-positions / 30.0))
    pos_tags = [""] * n
    punctuation = np.zeros(n, dtype=bool)

    for j in range(n):
        if tokens[j] in special_tokens:
            continue
        matches = alignment[j]
        if not matches:
            continue

        word = doc[matches[0]]
        pos_tags[j] = word.pos_
        punctuation[j] = word.is_punct

        if word.is_punct:
            key_bias[j] -= 0.42
        elif word.pos_ in ("NOUN", "PROPN"):
            key_bias[j] += 0.055
        elif word.pos_ == "AUX":
            key_bias[j] -= 0.055
        elif word.pos_ in ("CCONJ", "SCONJ"):
            key_bias[j] -= 0.22
        elif word.pos_ == "DET":
            key_bias[j] -= 0.025

    has_bos = tokens[0] == tokenizer.bos_token

    # Detect standalone opening quotes, including closing quotes fused to punctuation.
    opening_quotes = np.zeros(n, dtype=bool)
    in_quote = False
    for j, token in enumerate(tokens):
        if token in special_tokens:
            continue
        text = token.lstrip("▁Ġ").strip()
        for char in text:
            if char in ('"', "“", "”", "«", "»"):
                if char in ("“", "«"):
                    opens = True
                elif char in ("”", "»"):
                    opens = False
                else:
                    opens = not in_quote
                if opens and text == char:
                    opening_quotes[j] = True
                in_quote = opens
    has_dialogue = bool(np.any(opening_quotes))

    for i in range(n):
        logits = key_bias[:i + 1].copy()

        if has_bos:
            # The BOS advantage is strongest in the first few rows.
            logits[0] = 0.24 * np.exp(-max(i - 1, 0) / 4.5)
            if punctuation[i]:
                logits[0] -= 0.34

        if punctuation[i]:
            logits[i] -= 0.20
        elif pos_tags[i] in ("CCONJ", "SCONJ"):
            logits[i] -= 0.16
        elif pos_tags[i] == "AUX":
            logits[i] -= 0.025

        weights = np.exp(logits - np.max(logits))
        attention[i, :i + 1] = weights / weights.sum()

        # Dialogue-only correction: redistribute off-diagonal mass, leaving
        # the original diagonal and all baseline decay parameters unchanged.
        if has_dialogue and i > 0:
            boosts = np.ones(i, dtype=np.float64)
            boosts[opening_quotes[:i]] = 1.45
            if has_bos and (punctuation[i] or opening_quotes[i]):
                boosts[0] *= 1.30
            if np.any(boosts != 1.0):
                off_diagonal = attention[i, :i]
                original_mass = off_diagonal.sum()
                adjusted = off_diagonal * boosts
                attention[i, :i] = adjusted * (original_mass / adjusted.sum())

    return "diffuse_causal_with_quote_anchors", attention


def prog_L0H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Near-uniform causal averaging, with quotation marks exempt from the
    usual punctuation-key and punctuation-query BOS discounts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "near_uniform_causal_quotes", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = tokenizer.all_special_tokens
    has_bos = tokens[0] in special

    pos_tags = []
    punctuation = np.zeros(n, dtype=bool)
    quotation = np.zeros(n, dtype=bool)
    for j, token in enumerate(tokens):
        overlaps = alignment[j]
        if token in special:
            pos_tags.append("")
        elif overlaps:
            word = doc[overlaps[0]]
            pos_tags.append(word.pos_)
            punctuation[j] = all(doc[k].is_punct for k in overlaps)
        else:
            clean = token.lstrip("▁Ġ").strip()
            pos_tags.append("")
            punctuation[j] = bool(clean) and all(
                not c.isalnum() and not c.isspace() for c in clean
            )

        if token not in special:
            clean = token.lstrip("▁Ġ").strip()
            quotation[j] = bool(clean) and any(c in '"“”«»' for c in clean) and all(
                not c.isalnum() and not c.isspace() for c in clean
            )

    for i in range(n):
        weights = np.ones(i + 1, dtype=np.float64)
        weights[punctuation[:i + 1]] = 0.83

        # Quotation-bearing keys retain ordinary key weight.
        weights[quotation[:i + 1]] = 1.00

        if punctuation[i]:
            weights[i] = 0.58
        else:
            weights[i] = 0.99

        if has_bos and i > 0:
            bos_weight = 0.91
            if punctuation[i]:
                bos_weight = 0.46
            elif pos_tags[i] == "CCONJ":
                bos_weight = 0.64
                weights[i] = 0.80
            elif pos_tags[i] in ("ADP", "DET", "PART"):
                bos_weight = 0.81

            if i == 1:
                bos_weight = 0.95
                if pos_tags[i] == "DET":
                    bos_weight = 0.87
                elif pos_tags[i] == "PROPN":
                    bos_weight = 1.00

            # Quote queries keep ordinary BOS weight; self-weight is unchanged.
            if quotation[i]:
                bos_weight = 0.91

            weights[0] = bos_weight

        attention[i, :i + 1] = weights / weights.sum()

    return "near_uniform_causal_quotes", attention


def prog_L0H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Nearly uniform causal attention, with a weak persistent opening-quote bias.
    Quote corrections redistribute only non-self attention, preserving self weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "near_uniform_causal", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    key_logits = np.zeros(n, dtype=np.float64)
    positions = []

    for j, token in enumerate(tokens):
        aligned = alignment[j]
        pos = doc[aligned[0]].pos_ if aligned else ""
        positions.append(pos)

        if token in special_tokens:
            key_logits[j] = -0.09
        elif pos == "PUNCT":
            key_logits[j] = -0.12
        elif pos == "DET":
            key_logits[j] = 0.025
        elif pos == "NOUN":
            key_logits[j] = 0.035
        elif pos in ("VERB", "ADJ"):
            key_logits[j] = 0.015
        elif pos == "AUX":
            key_logits[j] = -0.035
        elif pos in ("CCONJ", "SCONJ"):
            key_logits[j] = -0.045

    # Track closing quotes even when merged with sentence punctuation.
    opening_quotes = np.zeros(n, dtype=bool)
    inside_quote = False
    for j, token in enumerate(tokens):
        if token in special_tokens:
            continue
        clean = token.lstrip("▁Ġ").strip()
        for char in clean:
            if char == '"':
                if not inside_quote and clean == '"':
                    opening_quotes[j] = True
                inside_quote = not inside_quote
            elif char == "“":
                if clean == "“":
                    opening_quotes[j] = True
                inside_quote = True
            elif char == "”":
                inside_quote = False

    for i in range(n):
        logits = key_logits[:i + 1].copy()
        logits[i] += 0.01

        # Function-word and punctuation queries show a weaker BOS discount.
        if tokens[0] in special_tokens:
            if positions[i] == "ADP":
                logits[0] += 0.07
            elif positions[i] == "PUNCT":
                logits[0] += 0.09
            elif positions[i] == "AUX":
                logits[0] += 0.035

        weights = np.exp(logits - np.max(logits))
        attention[i, :i + 1] = weights / weights.sum()

        # Leave the baseline untouched unless an opening quote precedes the query.
        if i > 0 and np.any(opening_quotes[:i]):
            prefix = attention[i, :i]
            original_mass = prefix.sum()
            adjusted = prefix * np.exp(0.15 * opening_quotes[:i])
            attention[i, :i] = adjusted * (original_mass / adjusted.sum())

    return "near_uniform_causal_quote_bias", attention


def prog_L0H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging with weak primacy and reduced comma-key salience.
    A comma remains salient across an immediately following opening quote.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = tokenizer.all_special_tokens

    comma_keys = [
        j for j, token in enumerate(tokens)
        if token not in specials and token.lstrip("▁Ġ") == ","
    ]

    for i in range(n):
        positions = np.arange(i + 1, dtype=np.float64)
        weights = 1.0 + 0.06 * np.exp(-np.maximum(positions - 1.0, 0.0) / 6.0)

        if tokens[0] in specials:
            weights[0] = 1.0 - 0.10 * (1.0 - np.exp(-i / 2.0))

        mapped = alignment[i]
        if mapped and tokens[i] not in specials:
            word = doc[mapped[0]]
            if word.is_punct:
                weights[i] *= 0.64
            elif word.pos_ == "CCONJ":
                weights[i] *= 0.80
            else:
                weights[i] *= 0.98

        # With only BOS and one word, the distribution is almost exactly flat.
        if i == 1 and tokens[0] in specials:
            self_probability = 0.505
            if mapped:
                pos = doc[mapped[0]].pos_
                if pos in ("DET", "ADP", "PROPN"):
                    self_probability = 0.515
                elif pos == "PRON":
                    self_probability = 0.502
            weights[0] = 1.0 - self_probability
            weights[1] = self_probability

        # Adjust only earlier comma keys; leave the original self-weight intact.
        for j in comma_keys:
            if j >= i:
                break
            distance = i - j
            if distance == 2 and tokens[j + 1].strip("▁Ġ \t\r\n") in (
                '"', "'", "“", "‘"
            ):
                weights[j] *= 1.12
            else:
                weights[j] *= 0.84 if distance <= 2 else 0.74

        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_causal_average_with_comma_key_suppression", attention


def prog_L0H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging, with mild recency preference and reduced BOS
    and punctuation weights rather than strong syntactic selectivity.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_causal_with_punctuation_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    punctuation = np.zeros(n, dtype=bool)
    key_weight = np.ones(n, dtype=np.float64)

    for j, token in enumerate(tokens):
        clean = token.lstrip("▁Ġ").strip()
        aligned = [doc[k] for k in alignment[j]]
        punctuation[j] = (
            bool(clean)
            and all(c in ",.;:!?" for c in clean)
            and token not in special_tokens
        )

        if punctuation[j]:
            key_weight[j] = 0.80
        elif aligned:
            pos = aligned[0].pos_
            if pos in ("CCONJ", "SCONJ"):
                key_weight[j] = 0.96
            elif pos == "DET":
                key_weight[j] = 1.02

    has_bos = tokens[0] in special_tokens

    for i in range(n):
        distances = i - np.arange(i + 1)
        weights = key_weight[:i + 1].copy()
        weights *= 1.0 + 0.035 * np.exp(-distances / 3.0)

        if has_bos:
            weights[0] = 0.76 + 0.17 * np.exp(-max(i - 1, 0) / 1.3)

        if punctuation[i]:
            # Delimiters favor preceding lexical material over themselves.
            weights *= np.exp(-0.035 * np.minimum(distances, 8))
            weights[i] = 0.48
            if has_bos and i > 0:
                weights[0] = 0.48

        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_causal_with_punctuation_bias", attention


def prog_L0H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Approximately uniform causal attention, with a weak first-token preference.
    BOS and punctuation are slightly downweighted; quotation tokens favor themselves.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    special_tokens = set(tokenizer.all_special_tokens)

    key_weights = np.ones(n, dtype=np.float64)
    is_punctuation = np.zeros(n, dtype=bool)
    is_quote = np.zeros(n, dtype=bool)

    for j, token in enumerate(tokens):
        if token in special_tokens:
            key_weights[j] = 0.90
            continue

        clean = token.lstrip("▁Ġ").strip()
        if clean:
            is_punctuation[j] = all(
                not character.isalnum() and not character.isspace()
                for character in clean
            )
            is_quote[j] = all(character in "\"'“”‘’«»" for character in clean)
            if is_punctuation[j]:
                key_weights[j] = 1.02 if is_quote[j] else 0.84

    first_content = None
    for j, token in enumerate(tokens):
        if token not in special_tokens:
            first_content = j
            key_weights[j] *= 1.06
            break

    for i in range(n):
        weights = key_weights[:i + 1].copy()

        if tokens[i] not in special_tokens:
            weights[i] *= 1.02

        if is_quote[i]:
            weights[i] *= 1.13
            if first_content is not None:
                weights[:first_content] *= 0.80

        attention[i, :i + 1] = weights / weights.sum()

    return "near_uniform_causal_with_weak_initial_bias", attention


def prog_L0H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Broad causal averaging with modest lexical-class salience.
    Punctuation, conjunctions, and auxiliaries become soft attention anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "causal_average_with_soft_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    anchor = np.zeros(n, dtype=np.float64)
    immediate = np.ones(n, dtype=np.float64)

    for j, token in enumerate(tokens):
        if token in special_tokens:
            immediate[j] = 1.02
            continue

        aligned = alignment[j]
        if not aligned:
            continue

        word = doc[aligned[0]]
        pos = word.pos_
        dep = word.dep_

        if pos == "PUNCT":
            if any(c in token for c in ",;:"):
                immediate[j] = 1.40
                anchor[j] = 0.35
            elif any(c in token for c in ".!?"):
                immediate[j] = 1.20
                anchor[j] = 0.25
            else:
                immediate[j] = 1.02
        elif pos == "CCONJ":
            immediate[j] = 1.20
            anchor[j] = 0.40
        elif pos == "AUX" or dep in ("aux", "auxpass", "cop"):
            immediate[j] = 1.10
            anchor[j] = 0.35
        elif pos in ("ADP", "SCONJ"):
            immediate[j] = 1.07
            anchor[j] = 0.08

        # Avoid multiplying a word's salience across all of its subword pieces.
        if j > 0 and aligned[0] in alignment[j - 1]:
            immediate[j] = 1.0
            anchor[j] = 0.0

    for i in range(n):
        positions = np.arange(i + 1)
        distance = i - positions
        maturation = 1.0 - np.exp(-distance / 1.6)
        weights = immediate[:i + 1] + anchor[:i + 1] * maturation

        # Most of the distribution remains close to uniform over the prefix.
        weights *= 1.0 + 0.025 * np.exp(-distance / 2.0)
        attention[i, :i + 1] = weights / weights.sum()

    return "causal_average_with_soft_anchors", attention


def prog_L0H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging; punctuation favors the first piece of a split
    preceding word over its final continuation, without changing other weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_causal_split_word_punctuation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    features = []
    for i, token in enumerate(tokens):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        special = token in special_tokens
        clean = token.lstrip("▁Ġ")
        punct = (
            not special
            and (
                (word is not None and word.is_punct)
                or (bool(clean) and all(not c.isalnum() and not c.isspace()
                                        for c in clean))
            )
        )
        features.append((
            word.pos_ if word is not None else "",
            word.dep_ if word is not None else "",
            punct,
            special,
        ))

    for i in range(n):
        positions = np.arange(i + 1)
        distance = i - positions
        logits = -0.002 * distance.astype(np.float64)
        pos, dep, punct, special = features[i]

        # The head is nearly uniform, not a strong attention-sink head.
        if features[0][3]:
            logits[0] += 0.10
        if i > 0:
            logits[i] -= 0.035

        for j in range(1, i + 1):
            key_pos, key_dep, key_punct, key_special = features[j]
            if key_special:
                continue
            if key_punct and j < i:
                logits[j] += 0.12
            if key_pos == "CCONJ" and j < i:
                logits[j] += 0.10
            if key_pos in ("NOUN", "PROPN") and 0 < i - j <= 2:
                logits[j] += 0.045

        # Punctuation mostly pools preceding content and downweights itself.
        if punct and i > 0:
            logits[i] -= 1.05
            logits[i - 1] += 0.24
            if i > 1 and not features[i - 1][2]:
                logits[i - 2] += 0.16

        # Auxiliaries weakly favor the immediately preceding subject region.
        if pos == "AUX" and i > 0:
            logits[i] -= 0.20
            logits[i - 1] += 0.16

        # Continuation pieces slightly favor the beginning of their own word.
        if alignment[i] and not special:
            for j in range(max(1, i - 3), i):
                if alignment[j] and alignment[j][0] == alignment[i][0]:
                    logits[j] += 0.10

        if i == 1 and features[0][3] and not punct:
            if pos == "DET":
                logits[1] += 0.09
            elif pos == "ADP":
                logits[0] += 0.06

        weights = np.exp(logits - np.max(logits))
        attention[i, :i + 1] = weights / weights.sum()

        # Correct only punctuation immediately following a split lexical word.
        # Transfer mass rather than renormalizing: self and unrelated edges
        # remain exactly as in the original prediction.
        if (
            punct
            and i > 2
            and not features[i - 1][2]
            and not features[i - 1][3]
            and alignment[i - 1]
        ):
            word_id = alignment[i - 1][0]
            if not doc[word_id].is_space and not doc[word_id].is_punct:
                start = i - 1
                while (
                    start > 1
                    and alignment[start - 1]
                    and alignment[start - 1][0] == word_id
                    and not features[start - 1][3]
                ):
                    start -= 1
                if start < i - 1:
                    transfer = 0.50 * attention[i, i - 1]
                    attention[i, i - 1] -= transfer
                    attention[i, start] += transfer

    return "diffuse_causal_split_word_punctuation", attention


def prog_L0H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse structural anchors, with word-final subtoken anchors in dialogue.
    Redistribute only off-diagonal dialogue attention, preserving self weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    word_index = [-1] * n
    clean = [""] * n
    first_piece = [False] * n
    seen = set()

    for i, token in enumerate(tokens):
        clean[i] = token.lstrip("▁Ġ").strip()
        if token in special:
            continue
        candidates = alignment[i]
        if candidates:
            k = candidates[0]
            word_index[i] = k
            pos[i] = doc[k].pos_
            dep[i] = doc[k].dep_
            first_piece[i] = k not in seen
            seen.add(k)

    anchor = np.zeros(n, dtype=np.float64)
    for j in range(n):
        if tokens[j] in special:
            continue
        if clean[j] in (",", ";", ":"):
            anchor[j] = 1.05
        elif any(c in clean[j] for c in ".!?"):
            anchor[j] = 0.65
        elif first_piece[j]:
            if pos[j] == "AUX":
                anchor[j] = 0.66
            elif pos[j] == "CCONJ":
                anchor[j] = 0.76
            elif pos[j] in ("ADP", "SCONJ"):
                anchor[j] = 0.48
            elif dep[j] in ("aux", "auxpass", "cop", "mark", "cc"):
                anchor[j] = 0.55

    # Dialogue exposes word-final fragments as anchors that POS-only scoring
    # misses. The punctuation fallback also handles damaged quotation marks.
    dialogue = (
        any(c in sentence for c in ('"', "“", "”", "«", "»"))
        or ("," in sentence and any(c in sentence for c in "!?"))
    )
    correction = np.zeros(n, dtype=np.float64)
    if dialogue:
        for j in range(n):
            if tokens[j] in special:
                continue
            k = word_index[j]
            final_piece = (
                k >= 0
                and not first_piece[j]
                and clean[j].isalnum()
                and (j + 1 == n or word_index[j + 1] != k)
            )
            if final_piece and pos[j] in (
                "NOUN", "PROPN", "VERB", "AUX", "PRON", "PART"
            ):
                correction[j] += 0.55
                if j + 1 < n and clean[j + 1] == ",":
                    correction[j] += 0.25
            if clean[j] == ",":
                correction[j] -= 0.25
            elif first_piece[j] and pos[j] == "AUX":
                correction[j] -= 0.35
            elif any(c in clean[j] for c in "!?"):
                correction[j] += 0.25

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        if pos[i] in ("NOUN", "PROPN", "VERB", "ADJ", "ADV"):
            strength = 1.0
        elif pos[i] == "PRON":
            strength = 0.80
        elif pos[i] in ("AUX", "ADP", "SCONJ", "CCONJ", "DET", "PART"):
            strength = 0.30
        elif pos[i] == "PUNCT":
            strength = 0.40
        else:
            strength = 0.65

        distances = i - np.arange(i + 1)
        logits = -0.0025 * distances.astype(np.float64)
        logits += strength * anchor[:i + 1]

        # A structural token becomes an anchor for subsequent queries,
        # rather than strongly preferring itself.
        logits[i] -= strength * anchor[i]
        logits[i] += 0.055

        if clean[i] in (",", ";", ":"):
            logits[i] -= 0.95
        elif pos[i] == "PUNCT":
            logits[i] += 0.04

        # The first two positions are almost uniformly mixed; initial
        # prepositional tokens exhibit a modest self preference.
        if i == 1 and tokens[0] in special:
            logits[0] = 0.0
            if pos[i] in ("ADP", "SCONJ"):
                logits[i] = 0.29
            elif pos[i] == "DET":
                logits[i] = 0.028
            elif pos[i] == "PRON":
                logits[i] = -0.04
            else:
                logits[i] = 0.0

        weights = np.exp(logits - np.max(logits))
        attention[i, :i + 1] = weights / weights.sum()

        # Keep the original diagonal and total historical mass exactly.
        if dialogue and np.any(correction[:i]):
            history_mass = attention[i, :i].sum()
            adjusted = attention[i, :i] * np.exp(
                strength * correction[:i]
            )
            attention[i, :i] = adjusted * (history_mass / adjusted.sum())

    return "diffuse_dialogue_anchors", attention


def prog_L0H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging with punctuation landmarks and POS-dependent
    self-attention, especially on commas, auxiliaries, and conjunctions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_causal_with_punctuation_landmarks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos = []
    dep = []
    punctuation = []
    commas = []
    special = []

    for i, token in enumerate(tokens):
        is_special = token in special_tokens
        special.append(is_special)

        aligned = alignment[i]
        if aligned and not is_special:
            word = doc[aligned[0]]
            pos.append(word.pos_)
            dep.append(word.dep_)
            punctuation.append(word.is_punct)
        else:
            pos.append("")
            dep.append("")
            punctuation.append(False)

        commas.append(not is_special and "," in token)

    for i in range(n):
        distances = i - np.arange(i + 1)
        weights = np.exp(-0.002 * distances)

        for j in range(i):
            if special[j]:
                continue

            if commas[j]:
                # Commas remain landmarks after the immediate quote/opening.
                weights[j] *= 1.75 if not punctuation[i] else 1.35
                if i - j == 1:
                    weights[j] *= 0.65
            elif pos[j] == "AUX":
                weights[j] *= 1.22
            elif pos[j] == "CCONJ":
                weights[j] *= 1.30

        if special[i]:
            self_gain = 1.0
        elif commas[i]:
            self_gain = 5.6
        elif punctuation[i]:
            self_gain = 1.8
        elif pos[i] == "AUX":
            self_gain = 2.0
        elif pos[i] == "CCONJ":
            self_gain = 2.2
        elif pos[i] == "ADP":
            self_gain = 1.55
        elif pos[i] == "SCONJ":
            self_gain = 1.45
        elif pos[i] == "PRON":
            self_gain = 1.11
        elif pos[i] == "DET":
            self_gain = 0.97
        elif pos[i] in ("NOUN", "PROPN", "ADJ"):
            self_gain = 1.10
        elif pos[i] == "VERB":
            self_gain = 1.12
        else:
            self_gain = 1.03

        if dep[i] in ("aux", "auxpass", "cop") and not punctuation[i]:
            self_gain = max(self_gain, 1.95)

        weights[i] *= self_gain
        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_causal_with_punctuation_landmarks", attention


def prog_L0H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse lexical anchors, with punctuation-anchor bonuses gated in dialogue.
    Preserve local nominal boundary cues, but avoid carrying them across quotations.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_dialogue_boundary_gate", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    punctuation = np.zeros(n, dtype=bool)
    boundary = np.zeros(n, dtype=bool)
    quote = np.zeros(n, dtype=bool)
    continuation = np.zeros(n, dtype=bool)
    dialogue_quote = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        if token in specials:
            continue
        indices = alignment[i]
        if indices:
            # Prefer a lexical overlap when an offset also includes punctuation.
            candidates = [k for k in indices if not doc[k].is_space]
            lexical = [k for k in candidates if not doc[k].is_punct]
            if lexical or candidates:
                word = doc[(lexical or candidates)[0]]
                pos[i] = word.pos_
                dep[i] = word.dep_
                punctuation[i] = word.is_punct
            if i > 0 and alignment[i - 1]:
                continuation[i] = bool(set(indices) & set(alignment[i - 1]))

        clean = token.lstrip("▁Ġ").strip()
        quote[i] = bool(clean) and all(c in "\"'“”‘’«»" for c in clean)
        boundary[i] = any(c in ",;:!?." for c in clean)
        dialogue_quote[i] = any(c in "\"“”«»" for c in clean)
        if clean and all(not c.isalnum() for c in clean):
            punctuation[i] = True

    has_dialogue = bool(np.any(dialogue_quote))
    quote_count = np.cumsum(dialogue_quote)

    key_strength = np.ones(n, dtype=np.float64)
    for j in range(n):
        if pos[j] == "AUX" or dep[j] in ("aux", "auxpass", "cop"):
            key_strength[j] = 1.45
        elif pos[j] in ("CCONJ", "SCONJ"):
            key_strength[j] = 1.65
        elif pos[j] == "ADP":
            key_strength[j] = 1.25
        elif pos[j] in ("PRON", "DET"):
            key_strength[j] = 0.97

        if boundary[j]:
            key_strength[j] = 1.85
        elif quote[j]:
            key_strength[j] = 0.85
        elif punctuation[j]:
            key_strength[j] = 0.85

        if continuation[j]:
            key_strength[j] *= 0.88

    has_bos = tokens[0] in specials
    if has_bos:
        key_strength[0] = 1.15

    for i in range(n):
        distance = i - np.arange(i + 1)
        weights = key_strength[:i + 1].copy()
        weights *= np.exp(-0.007 * distance)

        predicate = pos[i] in ("VERB", "AUX", "ADJ", "ADV")
        nominal = pos[i] in ("NOUN", "PROPN")
        for j in range(i):
            auxiliary = pos[j] == "AUX" or dep[j] in ("aux", "auxpass", "cop")
            if auxiliary:
                if pos[i] == "ADJ":
                    weights[j] *= 3.0
                elif pos[i] == "VERB":
                    weights[j] *= 1.5

            if pos[j] in ("CCONJ", "SCONJ"):
                if predicate:
                    weights[j] *= 2.0
                elif nominal or boundary[i]:
                    weights[j] *= 1.35

            if boundary[j]:
                if predicate:
                    weights[j] *= 2.1
                elif nominal:
                    weights[j] *= 1.45
                elif boundary[i]:
                    weights[j] *= 1.25

                # In dialogue, punctuation is usually an ordinary key rather
                # than a persistent clause anchor. Keep the original bonus
                # for nominal queries that have not crossed a quotation mark.
                crossed_quote = (
                    quote_count[i] - (quote_count[j - 1] if j > 0 else 0)
                ) > 0
                if has_dialogue and (not nominal or crossed_quote):
                    weights[j] /= 1.85
                    if predicate:
                        weights[j] /= 2.1
                    elif nominal:
                        weights[j] /= 1.45
                    elif boundary[i]:
                        weights[j] /= 1.25

        # A token does not receive its own full anchor-key bonus immediately.
        weights[i] = 1.0
        if pos[i] in ("VERB", "AUX"):
            weights[i] = 1.65
        elif pos[i] == "ADP":
            weights[i] = 1.35
        elif punctuation[i]:
            weights[i] = 0.58
        if continuation[i]:
            weights[i] *= 0.9

        # Boundary queries prefer the just-completed phrase.
        if punctuation[i] and not quote[i] and i > 0:
            weights[i - 1] *= 1.55

        # Isolated quotation marks are relatively unselective queries.
        if quote[i]:
            weights = 0.55 * weights + 0.45

        if has_bos and i == 1:
            weights[0] = 1.0
            weights[1] = 1.6 if pos[i] in ("ADP", "SCONJ") else 0.81
        elif has_bos and i == 2:
            weights[0] *= 1.08

        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_dialogue_boundary_gate", attention


def prog_L0H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal attention with delimiter anchors and weak recency.
    Comma anchors are weaker and less persistent than other salient keys.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_causal_weaker_comma_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    punctuation = np.zeros(n, dtype=bool)
    comma = np.zeros(n, dtype=bool)
    quote = np.zeros(n, dtype=bool)
    special = np.zeros(n, dtype=bool)

    for j, token in enumerate(tokens):
        special[j] = token in tokenizer.all_special_tokens
        clean = token.lstrip("▁Ġ")
        comma[j] = clean in (",", "，", "、")
        quote[j] = clean in ('"', "'", "“", "”", "‘", "’", "«", "»")

        if special[j]:
            continue

        punctuation[j] = bool(clean) and all(
            not char.isalnum() and not char.isspace() for char in clean
        )

        if alignment[j]:
            word = doc[alignment[j][0]]
            pos[j] = word.pos_
            punctuation[j] = punctuation[j] or word.pos_ == "PUNCT"

    for i in range(n):
        scores = np.zeros(i + 1, dtype=np.float64)

        for j in range(i + 1):
            distance = i - j

            # Most of the distribution remains close to uniform over the prefix.
            scores[j] = -0.055 * np.log1p(distance) - 0.003 * distance

            if distance == 1:
                scores[j] += 0.11
            elif distance == 0:
                scores[j] += 0.035

            if j < i and not special[j]:
                if comma[j]:
                    scores[j] += 1.02
                elif punctuation[j]:
                    scores[j] += -0.04 if quote[j] else 0.30
                elif pos[j] == "AUX":
                    scores[j] += 0.52
                elif pos[j] == "CCONJ":
                    scores[j] += 0.43
                elif pos[j] in ("ADP", "SCONJ"):
                    scores[j] += 0.10

            # Delimiters summarize preceding material rather than themselves.
            if j == i:
                if comma[i]:
                    scores[j] -= 1.75
                elif punctuation[i] and not quote[i]:
                    scores[j] -= 0.85
                elif pos[i] == "AUX":
                    scores[j] -= 0.34

            if j == i - 1 and comma[i]:
                scores[j] += 0.22

            # The immediately following token selects a comma boundary.
            if j == i - 1 and comma[j]:
                scores[j] += 0.28

            # Only comma keys need correction: their original anchor bonus
            # is too strong immediately and persists too far into the prefix.
            if j < i and comma[j] and not special[j]:
                scores[j] -= 0.75 + 0.12 * np.log1p(distance - 1)
                if distance == 1:
                    scores[j] -= 0.10

        scores -= np.max(scores)
        attention[i, :i + 1] = np.exp(scores)

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "diffuse_causal_weaker_comma_anchors", attention


def prog_L0H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging; clause-boundary queries shift recent auxiliary
    and punctuation mass toward nearby content, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    for i in range(n):
        distance = i - np.arange(i + 1)
        weights = 1.0 + 0.06 * np.exp(-((distance - 2.0) / 1.8) ** 2)

        if tokens[0] == tokenizer.bos_token:
            weights[0] = 1.06

        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        if word is not None and tokens[i] != tokenizer.bos_token:
            if word.pos_ == "AUX":
                weights[i] *= 0.65
                if i >= 1:
                    weights[i - 1] *= 1.25
                if i >= 2 and i - 2 != 0:
                    weights[i - 2] *= 1.12

            elif word.is_punct:
                weights[i] *= 0.72
                if i >= 1:
                    weights[i - 1] *= 1.10
                if i >= 2 and i - 2 != 0:
                    weights[i - 2] *= 1.28

            elif word.pos_ == "CCONJ":
                weights[i] *= 0.80
                if i >= 2 and i - 2 != 0:
                    weights[i - 2] *= 1.15
                if i >= 3 and i - 3 != 0:
                    weights[i - 3] *= 1.25

        # A narrow correction for auxiliary-containing clause endings and
        # their adjacent quote/whitespace queries. Transfer mass, rather than
        # adding it, so the original normalized self-attention stays intact.
        boundary = (
            tokens[i] != tokenizer.bos_token
            and (
                (word is not None and word.is_punct)
                or not tokens[i].replace("▁", "").strip()
            )
        )
        if boundary:
            recent = []
            for j in range(max(1, i - 5), i):
                if alignment[j]:
                    recent.append((j, doc[alignment[j][0]]))

            has_aux = any(w.pos_ == "AUX" for j, w in recent)
            recipients = [
                (j, 1.0 if w.pos_ in ("NOUN", "PROPN") else 0.6)
                for j, w in recent
                if w.pos_ in ("NOUN", "PROPN", "VERB", "ADJ")
            ]

            if has_aux and recipients:
                transferred = 0.0
                for j, w in recent:
                    fraction = (
                        0.60 if w.pos_ == "AUX"
                        else 0.45 if w.is_punct
                        else 0.0
                    )
                    amount = fraction * weights[j]
                    weights[j] -= amount
                    transferred += amount

                total = sum(strength for j, strength in recipients)
                for j, strength in recipients:
                    weights[j] += transferred * strength / total

        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_average_with_boundary_content_transfer", attention


def prog_L0H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging, with dialogue-specific boundary retrieval.
    Quote/whitespace queries also retrieve older punctuation and pre-quote endpoints.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_prefix_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    pos = []
    punctuation = []
    quotes = []
    commas = []

    for i, token in enumerate(tokens):
        text = token.lstrip("▁Ġ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos.append(word.pos_ if word is not None else "")
        punctuation.append(
            token not in special
            and (
                (word is not None and word.is_punct)
                or (bool(text) and all(not c.isalnum() for c in text))
            )
        )
        quotes.append(
            token not in special
            and bool(text)
            and all(c in "\"'“”‘’«»" for c in text)
        )
        commas.append(text in (",", ";", ":"))

    has_bos = tokens[0] in special
    boundaries = []
    for q in range(1, n):
        if quotes[q] and commas[q - 1]:
            boundaries.append((q - 1, q))

    # Restrict the new path to dialogue, including mojibake quotation marks.
    clean = [token.lstrip("▁Ġ").strip() for token in tokens]
    malformed_quotes = "â€" in sentence
    dialogue = malformed_quotes or any(
        any(c in "\"“”«»" for c in text) for text in clean
    )
    dialogue_boundaries = []
    quote_queries = []
    quote_endpoints = []
    if dialogue:
        for q, text in enumerate(clean):
            if tokens[q] in special:
                continue
            if any(c in ",;:!?" for c in text):
                dialogue_boundaries.append(q)
            is_quote = quotes[q] or (
                malformed_quotes and text in ("â", "€", "œ")
            )
            if is_quote or not text:
                quote_queries.append(q)
            if is_quote:
                b = q - 1
                while b >= 0 and not clean[b] and tokens[b] not in special:
                    b -= 1
                if b >= 1 and commas[b]:
                    quote_endpoints.append((b - 1, q))

    for i in range(n):
        keys = np.arange(i + 1)
        distance = i - keys
        weights = 1.0 + 0.04 * np.exp(-distance / 3.0)

        for j in range(i + 1):
            if punctuation[j]:
                weights[j] *= 0.86 if commas[j] else 0.78

        weights[i] = 0.98
        if pos[i] == "AUX":
            weights[i] *= 0.86
        elif pos[i] in ("ADJ", "ADV"):
            weights[i] *= 0.97

        if i > 0:
            if pos[i] == "AUX":
                weights[i - 1] *= 1.15
            elif pos[i] in ("DET", "ADP", "CCONJ", "SCONJ"):
                weights[i - 1] *= 1.06

        if punctuation[i] and not quotes[i]:
            weights[i] = 0.52
            if i > 0:
                weights[i - 1] *= 1.16

        if has_bos:
            weights[0] = 1.12
            if i == 1:
                weights[0] = 1.24
                weights[i] = 0.98
                if pos[i] == "ADP":
                    weights[0] = 0.98
                    weights[i] = 1.10
            elif i == 2:
                weights[0] = 1.15
                if not punctuation[i]:
                    weights[i] = 1.03 if pos[i] != "AUX" else 0.90

        for boundary, opening in boundaries:
            if opening > i:
                break
            age = i - opening
            if age <= 12:
                weights[boundary] += 2.30 * np.exp(-age / 1.45)

        if dialogue:
            structural_query = i in quote_queries
            for boundary in dialogue_boundaries:
                if boundary >= i:
                    break
                extra = 0.12 + 0.65 * np.exp(-(i - boundary) / 5.0)
                if structural_query:
                    extra += 0.80

                # Do not stack a second boundary bonus on the original one.
                existing = 0.0
                for old_boundary, opening in boundaries:
                    if old_boundary == boundary and 0 <= i - opening <= 12:
                        existing += 2.30 * np.exp(-(i - opening) / 1.45)
                weights[boundary] += max(0.0, extra - existing)

            for endpoint, opening in quote_endpoints:
                age = i - opening
                if 0 <= age <= 3:
                    weights[endpoint] += 1.10 * np.exp(-age / 1.5)

        attention[i, :i + 1] = weights / weights.sum()

    return "diffuse_prefix_dialogue_boundaries", attention


def prog_L0H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Recent structural anchors, with quotation marks and apostrophes excluded
    as persistent anchors; retain the original self-attention exactly.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "quote_filtered_structural_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    word_index = [-1] * n
    first_piece = [True] * n
    punctuation = [False] * n
    terminal = [False] * n
    whitespace = [False] * n
    seen = set()

    for i, token in enumerate(tokens):
        clean = token.lstrip("▁Ġ")
        whitespace[i] = token not in special and not clean.strip()
        punctuation[i] = bool(clean) and all(
            c in ",.;:!?\"'“”‘’—–-()[]{}…" for c in clean
        )
        terminal[i] = any(c in ".!?" for c in clean)

        if alignment[i] and token not in special:
            wi = alignment[i][0]
            word_index[i] = wi
            pos[i] = doc[wi].pos_
            dep[i] = doc[wi].dep_
            first_piece[i] = wi not in seen
            seen.add(wi)
            punctuation[i] = punctuation[i] or pos[i] == "PUNCT"

    # Only quote-only pieces are affected, not punctuation fused with a
    # sentence boundary, such as a question mark followed by a closing quote.
    quote_only = [
        t not in special
        and bool(t.lstrip("▁Ġ"))
        and all(c in "\"'“”‘’«»„‟‹›" for c in t.lstrip("▁Ġ"))
        for t in tokens
    ]

    first = next((i for i, t in enumerate(tokens) if t not in special), 0)
    key_strength = np.zeros(n, dtype=np.float64)

    for j in range(n):
        p = pos[j]
        strength = -0.15
        if p == "VERB":
            strength = 0.65
        elif p == "AUX":
            strength = 1.65
        elif p == "ADP":
            strength = 1.45
        elif p == "CCONJ":
            strength = 1.65
        elif p == "SCONJ":
            strength = 0.95
        elif p in ("DET", "PRON", "PART"):
            strength = -0.05

        if dep[j] in ("aux", "auxpass", "cop", "prep", "mark"):
            strength += 0.20
        if punctuation[j]:
            strength = 2.15 if terminal[j] else 1.90
        if whitespace[j]:
            strength = -1.80
        if not first_piece[j] and not punctuation[j]:
            strength -= 0.70
        if tokens[j] in special:
            strength = -1.50
        key_strength[j] = strength

    for i in range(n):
        if tokens[i] in special:
            attention[i, i] = 1.0
            continue

        if i == first:
            self_mass = 0.84
            if pos[i] == "DET":
                self_mass = 0.90
            elif pos[i] == "PRON":
                self_mass = 0.80
            elif pos[i] == "PROPN":
                self_mass = 0.75
            if i == 0:
                attention[i, i] = 1.0
            else:
                attention[i, :i] = (1.0 - self_mass) / i
                attention[i, i] = self_mass
            continue

        distances = i - np.arange(i + 1)
        scores = key_strength[:i + 1].copy()
        scores -= 0.075 * distances + 0.22 * np.log1p(distances)

        # The initial token is an anchor before stronger boundaries emerge.
        first_bonus = 1.65 if pos[first] == "DET" else 1.20
        scores[first] += first_bonus - 0.055 * (i - first)

        early = np.exp(-max(0, i - first - 2) / 5.0)
        self_bonus = 0.20 + 1.05 * early
        if pos[i] in ("VERB", "AUX"):
            self_bonus += 0.30 * early
        if pos[i] in ("CCONJ", "SCONJ"):
            self_bonus -= 0.90
        if punctuation[i]:
            self_bonus = -0.65 + 0.95 * early
        if whitespace[i]:
            self_bonus = -1.20
        scores[i] += self_bonus

        boundary_query = punctuation[i] or pos[i] in ("CCONJ", "SCONJ")
        for j in range(first, i):
            structural = (
                punctuation[j]
                or pos[j] in ("AUX", "ADP", "CCONJ", "SCONJ")
                or dep[j] in ("aux", "auxpass", "cop", "prep", "mark")
            )
            if boundary_query and structural:
                scores[j] += 0.85
                scores[j] -= 0.055 * (i - j)
            if punctuation[j]:
                scores[j] += 0.45 * np.exp(-(i - j - 1) / 5.0)
                if whitespace[i]:
                    scores[j] += 1.10
                if punctuation[i] and not terminal[i]:
                    scores[j] += 0.55
            if word_index[i] >= 0 and word_index[i] == word_index[j]:
                scores[j] += 0.15

        scores -= np.max(scores)
        weights = np.exp(scores)
        attention[i, :i + 1] = weights / weights.sum()

        # A quote/apostrophe is not a persistent clause anchor. Transfer only
        # its historical mass, leaving the diagonal and all baseline decay
        # calculations intact. Rows without such keys remain unchanged.
        quote_keys = [j for j in range(first, i) if quote_only[j]]
        if quote_keys:
            recipients = [
                j for j in range(first, i)
                if not quote_only[j] and not whitespace[j]
                and tokens[j] not in special
            ]
            recipient_mass = attention[i, recipients].sum()
            if recipient_mass > 0.0:
                released = 0.85 * attention[i, quote_keys].sum()
                attention[i, quote_keys] *= 0.15
                attention[i, recipients] *= 1.0 + released / recipient_mass

    return "quote_filtered_structural_anchors", attention


def prog_L0H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict local onset/boundary attention, with quoted-clause onset retrieval.
    Inside quotes, distinguish lexical onsets from punctuation retrieval anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_onset_and_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
    special = [t in special_tokens for t in tokens]
    pos = []
    deps = []
    word_ids = []
    punctuation = []
    whitespace = []

    for i in range(n):
        ids = alignment[i]
        word = doc[ids[0]] if ids else None
        pos.append(word.pos_ if word is not None else "")
        deps.append(word.dep_ if word is not None else "")
        word_ids.append(ids[0] if ids else -1)
        whitespace.append(not clean[i] and not special[i])
        punctuation.append(
            not special[i]
            and bool(clean[i])
            and (
                (word is not None and word.is_punct)
                or all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in clean[i])
            )
        )

    lexical = [
        i for i in range(n)
        if not special[i] and not punctuation[i] and not whitespace[i]
    ]
    first = lexical[0] if lexical else None

    strengths = np.ones(n, dtype=np.float64)
    for j in range(n):
        if special[j]:
            strengths[j] = 0.16
        elif whitespace[j]:
            strengths[j] = 0.25
        elif punctuation[j]:
            strengths[j] = 2.6
        elif pos[j] in ("VERB", "AUX"):
            strengths[j] = 2.4
        elif pos[j] == "DET":
            strengths[j] = 1.65
        elif pos[j] in ("CCONJ", "SCONJ"):
            strengths[j] = 1.35
        elif pos[j] in ("ADJ", "ADV"):
            strengths[j] = 1.05
        else:
            strengths[j] = 0.95

        if (
            j > 0
            and word_ids[j] >= 0
            and word_ids[j] == word_ids[j - 1]
            and not punctuation[j]
        ):
            strengths[j] *= 0.65

    if first is not None:
        if pos[first] == "DET":
            strengths[first] = 4.0
        elif pos[first] == "PRON":
            strengths[first] = 1.7
        else:
            strengths[first] = 2.4

    opening_quote = None
    quote_matches = {}
    quote_chars = "\"“”"

    for i in range(n):
        if special[i]:
            continue
        if any(c in quote_chars for c in clean[i]):
            explicitly_closing = (
                "”" in clean[i]
                or any(c in ".!?" for c in clean[i])
            )
            if opening_quote is not None:
                quote_matches[i] = opening_quote
                opening_quote = None
            elif not explicitly_closing:
                opening_quote = i
        elif opening_quote is not None:
            quote_matches[i] = opening_quote

    # Record only the actual first lexical token, not a later function word.
    quote_onsets = {}
    for i, anchor in quote_matches.items():
        if (
            anchor not in quote_onsets
            and not special[i]
            and not punctuation[i]
            and not whitespace[i]
        ):
            quote_onsets[anchor] = i

    for i in range(n):
        distance = i - np.arange(i + 1)
        row = strengths[:i + 1] * np.exp(-distance / 7.5)

        if first is not None and first <= i:
            row[first] = strengths[first] * np.exp(-(i - first) / 13.0)

        if i == first:
            row[i] = strengths[i]
            if i > 0:
                row[:i] = 0.23 / i
        elif not punctuation[i] and not special[i]:
            row[i] *= 1.12

        if whitespace[i]:
            row[i] *= 0.2

        if punctuation[i]:
            row[i] *= 0.035
            previous = [
                j for j in range(max(0, i - 5), i)
                if not special[j] and not punctuation[j] and not whitespace[j]
            ]
            if previous:
                last = previous[-1]
                row[last] *= 2.25
                if len(previous) > 1:
                    before = previous[-2]
                    row[before] *= 1.45
                if word_ids[last] >= 0:
                    for j in previous:
                        if word_ids[j] == word_ids[last] and j != last:
                            row[j] *= 1.6

        for j in range(max(0, i - 8), i):
            if punctuation[j]:
                row[j] *= 1.25
            if clean[j] and any(c in quote_chars for c in clean[j]):
                row[j] *= 1.35

        if i in quote_matches:
            anchor = quote_matches[i]
            gap = i - anchor
            boost = 1.8 * np.exp(-gap / 20.0)
            if punctuation[i]:
                boost *= 3.0
            row[anchor] += boost

            # Special case: quoted function-word onsets compete with the
            # opening quote for lexical queries, but not punctuation queries.
            # Transfers preserve row mass and the original diagonal weight.
            onset = quote_onsets.get(anchor)
            if (
                onset is not None
                and onset < i
                and not punctuation[i]
                and not special[i]
                and not whitespace[i]
                and pos[onset] in ("PRON", "DET", "ADV")
            ):
                transfer = 0.60 * row[anchor]
                row[anchor] -= transfer
                row[onset] += transfer

            # A contraction apostrophe inside dialogue retrieves the opening
            # quote rather than inheriting the preceding lexical-token boost.
            elif (
                onset is not None
                and onset < i
                and clean[i] in ("'", "’")
                and i > 0
                and not punctuation[i - 1]
                and not special[i - 1]
                and not whitespace[i - 1]
            ):
                transfer = 0.65 * row[i - 1]
                row[i - 1] -= transfer
                row[anchor] += transfer

        attention[i, :i + 1] = row

    return (
        "local_onset_and_boundary_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L0H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse lexical anchors, with content-focused attention at clause punctuation.
    Boundary queries downweight function words and redundant subword continuations.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "causal_lexical_boundary_content", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos = [""] * n
    dep = [""] * n
    word_index = [-1] * n
    continuation = np.zeros(n, dtype=bool)
    punctuation = np.zeros(n, dtype=bool)
    quote = np.zeros(n, dtype=bool)
    weights = np.ones(n, dtype=np.float64)

    category_weights = {
        "DET": 2.45,
        "PRON": 2.0,
        "AUX": 3.0,
        "VERB": 2.65,
        "ADP": 2.7,
        "CCONJ": 2.9,
        "SCONJ": 2.5,
        "PART": 2.5,
        "ADV": 2.15,
        "ADJ": 1.35,
        "NOUN": 1.05,
        "PROPN": 1.55,
        "NUM": 1.8,
        "PUNCT": 2.45,
        "SPACE": 1.0,
    }

    for j, token in enumerate(tokens):
        if alignment[j]:
            sid = alignment[j][0]
            word_index[j] = sid
            pos[j] = doc[sid].pos_
            dep[j] = doc[sid].dep_
            punctuation[j] = doc[sid].is_punct
            quote[j] = doc[sid].is_quote
        else:
            clean = token.replace("▁", "").replace("Ġ", "")
            punctuation[j] = bool(clean) and all(
                not c.isalnum() and not c.isspace() for c in clean
            )
            quote[j] = any(c in "\"“”«»" for c in clean)

        weights[j] = category_weights.get(pos[j], 1.6)

        if dep[j] in ("npadvmod", "advmod") and pos[j] == "NOUN":
            weights[j] = 2.35

        if j > 0 and word_index[j] >= 0:
            continuation[j] = (
                word_index[j] == word_index[j - 1]
                and not punctuation[j]
                and not punctuation[j - 1]
            )
        if continuation[j]:
            weights[j] = 3.2
        if quote[j]:
            weights[j] = 3.7
        if token in special_tokens:
            weights[j] = 0.45

    has_bos = tokens[0] in special_tokens
    first = 1 if has_bos else 0
    if first < n:
        if pos[first] == "DET":
            weights[first] = 5.0
        elif pos[first] == "PRON":
            weights[first] = 1.95
        elif pos[first] in ("NUM", "ADJ"):
            weights[first] = 3.2
        else:
            weights[first] = 2.9

    for i in range(n):
        distances = i - np.arange(i + 1)
        row = weights[:i + 1] * (
            0.65 + 0.35 * np.exp(-distances / 7.0)
        )
        row += 0.08

        if has_bos:
            row[0] = 0.45

        row[i] *= 1.08
        if i > first:
            row[i - 1] *= 1.12

        if continuation[i]:
            row[i] *= 1.45

        if i > 0 and quote[i - 1] and not punctuation[i]:
            row[i - 1] *= 1.75

        if pos[i] in ("VERB", "ADJ") and i > 0:
            if pos[i - 1] in ("AUX", "CCONJ", "SCONJ"):
                row[i - 1] *= 1.45

        if pos[i] in ("NOUN", "PROPN", "ADJ"):
            sid = word_index[i]
            if sid >= 0:
                nominal = doc[sid].head if pos[i] == "ADJ" else doc[sid]
                for j in range(first, i):
                    other = word_index[j]
                    if other < 0 or continuation[j]:
                        continue
                    if (
                        doc[other].head.i == nominal.i
                        and dep[j] in ("det", "poss")
                    ):
                        row[j] *= 1.25

        # Boundary queries summarize content rather than function-word anchors.
        # Keep the original BOS and unnormalized self-attention weights intact.
        if punctuation[i] and any(c in ",.!?;:" for c in tokens[i]):
            for j in range(first, i):
                if tokens[j] in special_tokens:
                    continue
                row[j] *= 1.6 if pos[j] in (
                    "NOUN", "PROPN", "ADJ", "PRON"
                ) else 0.3
                if continuation[j]:
                    row[j] *= 0.5

        if i == first and has_bos:
            self_probability = 0.85 if pos[i] == "PRON" else 0.895
            row[:] = 0.0
            row[0] = 1.0 - self_probability
            row[i] = self_probability

        attention[i, :i + 1] = row / row.sum()

    return "causal_lexical_boundary_content", attention


def prog_L0H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink mixed with persistent content-word anchors and mild recency.
    Nouns, verbs, and adjectives attract attention, with small syntactic corrections.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_content_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    special = set(tokenizer.all_special_tokens)
    pos_weights = {
        "NOUN": 3.4,
        "PROPN": 2.9,
        "VERB": 3.1,
        "ADJ": 2.8,
        "AUX": 1.15,
        "ADV": 0.95,
        "PRON": 1.0,
        "DET": 0.49,
        "ADP": 0.85,
        "CCONJ": 0.65,
        "SCONJ": 0.85,
        "PART": 0.65,
        "NUM": 1.4,
        "INTJ": 1.0,
        "PUNCT": 0.16,
        "SPACE": 0.10,
    }

    word_index = np.full(n, -1, dtype=int)
    salience = np.full(n, 0.45, dtype=np.float64)
    for j in range(n):
        if tokens[j] in special:
            salience[j] = 0.08
            continue
        if not alignment[j]:
            continue

        si = alignment[j][0]
        word_index[j] = si
        word = doc[si]
        weight = pos_weights.get(word.pos_, 0.8)

        # Preserve a word's leading piece as its main attention anchor.
        pieces = inverse[si]
        if pieces and j != pieces[0]:
            weight *= 0.42

        if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
            weight *= 1.12
        if word.dep_ in ("dobj", "obj", "attr", "acomp"):
            weight *= 1.08
        salience[j] = weight

    bos = tokens[0] in special
    if not bos:
        salience[0] *= 1.1

    for i in range(n):
        positions = np.arange(i + 1)
        distances = i - positions

        # Content anchors persist beyond their immediate neighborhood.
        decay = 0.30 + 0.70 * np.exp(-distances / 24.0)
        primacy = 0.65 + 0.35 * np.exp(-positions / 18.0)
        row = salience[:i + 1] * decay * primacy
        row[-1] *= 1.10

        if i > 0:
            row[i - 1] *= 1.10

        si = word_index[i]
        if si >= 0:
            query = doc[si]

            # Use only already-visible pieces of a syntactic head.
            if query.head.i != si:
                head_pieces = inverse[query.head.i]
                if head_pieces:
                    head = head_pieces[0]
                    if head <= i and (not bos or head != 0):
                        row[head] *= 1.18

            # Predicates can retain an earlier nominal subject as an anchor.
            if query.pos_ in ("VERB", "AUX", "ADJ"):
                for child in query.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        pieces = inverse[child.i]
                        if pieces and pieces[0] <= i:
                            row[pieces[0]] *= 1.28

            if query.is_punct and i > 0:
                row[i - 1] *= 1.22

        if bos:
            row[0] = 3.0 * np.exp(-i / 65.0)
            if si >= 0 and doc[si].is_punct:
                row[0] *= 0.90

        attention[i, :i + 1] = row

    return "bos_content_anchors", make_row_stochastic(attention)


def prog_L0H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local boundary anchors, with clause-ending punctuation pooling over
    preceding context rather than locking onto the immediately previous token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_boundary_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    first = next(
        (i for i, token in enumerate(tokens) if token not in special), None
    )

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        # A weak causal recency floor supplies the less concentrated edges.
        attention[i, :i + 1] = 0.025 * np.exp(
            -np.arange(i, -1, -1, dtype=np.float64) / 2.5
        )
        for j in range(i + 1):
            if tokens[j] in special:
                attention[i, j] *= 0.1

        if i == first:
            attention[i, i] += 1.0
            attention[i, :i] += 0.06 / max(i, 1)
            continue

        current = words[i]
        previous = words[i - 1]
        pos = current.pos_ if current is not None else ""
        ppos = previous.pos_ if previous is not None else ""

        self_weight = 0.24
        previous_weight = 0.34

        if pos == "VERB":
            self_weight = 0.65
            previous_weight = 0.23
        elif pos == "AUX":
            self_weight = 0.38
        elif pos in ("PRON", "DET"):
            self_weight = 0.28
        elif pos == "PUNCT":
            self_weight = 0.28
            previous_weight = 0.46

        previous_surface = tokens[i - 1].replace("▁", "").replace("Ġ", "")
        previous_punctuation = (
            previous is not None and previous.is_punct
        ) or (
            bool(previous_surface)
            and all(
                not char.isalnum() and not char.isspace()
                for char in previous_surface
            )
            and tokens[i - 1] not in special
        )

        shared_word = (
            current is not None
            and previous is not None
            and current.i == previous.i
        )

        if shared_word:
            self_weight = 0.27
            previous_weight = 0.58
        elif previous_punctuation:
            self_weight = 0.20 if pos != "PUNCT" else 0.28
            previous_weight = 2.0
        elif ppos in ("ADP", "SCONJ", "CCONJ", "PART", "AUX"):
            self_weight = 0.21
            previous_weight = 1.55
        elif ppos == "DET":
            self_weight = 0.23
            previous_weight = 0.68
            if i - 1 == first:
                previous_weight = 1.8
        elif ppos == "VERB" and pos in (
            "DET", "PRON", "NOUN", "PROPN", "NUM"
        ):
            self_weight = 0.24
            previous_weight = 0.86

        attention[i, i] += self_weight
        attention[i, i - 1] += previous_weight

        # Retain the introducer across a short intervening subject or modifier.
        if not shared_word and not previous_punctuation:
            for j in range(i - 2, max(-1, i - 5), -1):
                anchor = words[j]
                if anchor is None:
                    continue

                intervening = [
                    words[k] for k in range(j + 1, i)
                    if words[k] is not None
                ]
                if not intervening:
                    continue

                distance = i - j
                strength = 0.0

                if anchor.pos_ in ("ADP", "AUX", "PART", "SCONJ"):
                    if all(
                        w.pos_ in ("DET", "ADJ", "ADV", "PRON", "NUM")
                        for w in intervening
                    ):
                        strength = 0.68 * (0.62 ** (distance - 2))
                elif anchor.pos_ == "VERB":
                    if all(
                        w.pos_ in ("DET", "ADJ", "ADV", "NUM")
                        for w in intervening
                    ) and pos in ("NOUN", "PROPN", "ADJ"):
                        strength = 0.55 * (0.60 ** (distance - 2))

                if strength:
                    attention[i, j] += strength
                    break

        if tokens[i] in special:
            attention[i, i] += 0.5

        # Only clause/terminal punctuation queries receive contextual pooling.
        # Standalone quotes and apostrophes retain the original behavior.
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if (
            tokens[i] not in special
            and any(char in ",.;:!?" for char in surface)
            and all(
                not char.isalnum() and not char.isspace()
                for char in surface
            )
        ):
            context = np.exp(
                -np.arange(i, 0, -1, dtype=np.float64) / 12.0
            )
            context[-1] *= 0.4
            for j in range(i):
                if tokens[j] in special:
                    context[j] *= 0.4

            # Add context mass without changing the default weight formulas.
            row_mass = attention[i, :i + 1].sum()
            attention[i, :i] += (
                (0.94 / 0.06) * row_mass * context / context.sum()
            )

    return "local_boundary_anchor", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L0H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Lexical anchors with boundary sinks, except expressive punctuation:
    question/exclamation boundaries are weak anchors rather than persistent sinks."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "lexical_anchors_weak_expressive_sinks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    word_id = [-1] * n
    word_start = list(range(n))
    clean = [t.lstrip("▁Ġ") for t in tokens]
    first_piece = {}

    for i, sids in enumerate(alignment):
        if tokens[i] in special:
            continue
        if sids:
            sid = max(
                sids,
                key=lambda k: (
                    not doc[k].is_space,
                    not doc[k].is_punct,
                    len(doc[k].text),
                ),
            )
            word_id[i] = sid
            pos[i] = doc[sid].pos_
            dep[i] = doc[sid].dep_
            if sid not in first_piece:
                first_piece[sid] = i
            word_start[i] = first_piece[sid]

    first = next(
        (i for i in range(n)
         if tokens[i] not in special and clean[i].strip()),
        None,
    )

    salience = np.ones(n, dtype=np.float64)
    terminal = np.zeros(n, dtype=bool)
    comma = np.zeros(n, dtype=bool)
    interrogative = np.zeros(n, dtype=bool)

    for j in range(n):
        text = clean[j]
        terminal[j] = any(c in text for c in ".!?")
        comma[j] = any(c in text for c in ",;:")
        if tokens[j] in special:
            salience[j] = 0.65
            continue

        p = pos[j]
        if p in ("NOUN", "PROPN", "PRON"):
            salience[j] = 1.45
        elif p in ("VERB", "ADJ", "ADV", "NUM"):
            salience[j] = 1.30
        elif p in ("DET", "ADP", "AUX", "CCONJ", "SCONJ", "PART"):
            salience[j] = 0.80
        elif p == "PUNCT":
            salience[j] = 0.65

        if dep[j] in ("nsubj", "nsubjpass", "csubj"):
            salience[j] *= 1.16
        if word_start[j] != j:
            salience[j] *= 0.65
        if word_id[j] >= 0:
            interrogative[j] = doc[word_id[j]].tag_ in (
                "WDT", "WP", "WP$", "WRB"
            )
        if interrogative[j]:
            salience[j] *= 2.15
        if comma[j]:
            salience[j] = 1.65

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        for j in range(i + 1):
            distance = i - j
            weight = salience[j] * (
                0.55 + 0.45 * np.exp(-distance / 12.0)
            )

            if j == first:
                weight = max(weight, 1.80)

            if j == i and tokens[j] not in special:
                if pos[i] in ("NOUN", "PROPN", "VERB", "ADJ", "ADV", "NUM"):
                    weight *= 1.90
                elif pos[i] == "PRON":
                    weight *= 1.65
                elif pos[i] != "PUNCT":
                    weight *= 1.45

            if distance == 1:
                weight *= 1.25
                if pos[i] in ("ADP", "AUX", "CCONJ", "SCONJ"):
                    weight *= 1.25

            if (
                0 < distance <= 4
                and pos[i] in ("DET", "ADP", "AUX", "PART")
                and pos[j] in ("NOUN", "PROPN", "PRON", "VERB")
            ):
                weight *= 1.22

            if j == word_start[i] and j < i:
                weight *= 2.10

            if (
                distance == 1
                and any(c in clean[j] for c in "'’")
                and word_start[i] == i
            ):
                weight *= 2.00

            # Preserve period sinks, but prevent expressive boundaries from
            # monopolizing attention throughout subsequent dialogue/narration.
            if terminal[j] and j < i:
                strength = 10.0 if any(c in clean[j] for c in "?!") else 6.0
                if any(c in clean[j] for c in "?!"):
                    strength *= 0.08
                weight += strength * (
                    0.55 + 0.45 * np.exp(-distance / 48.0)
                )

            attention[i, j] = weight

        # The opening lexical token competes primarily with the BOS token.
        if i == first and i > 0:
            self_mass = 0.75
            if pos[i] == "DET":
                self_mass = 0.712
            elif pos[i] == "PROPN":
                self_mass = 0.80
            elif pos[i] == "PRON":
                self_mass = 0.75
            attention[i, :i] = (1.0 - self_mass) / i
            attention[i, i] = self_mass

    return (
        "lexical_anchors_weak_expressive_sinks",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L0H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local lexical-anchor attention: word starts, noun-phrase anchors,
    and nearby clause subjects, with quote and apostrophe boundary effects.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_lexical_and_subject_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    special = [t in special_tokens for t in tokens]
    clean = [t.lstrip("▁Ġ").removeprefix("##") for t in tokens]

    # Group tokenizer fragments independently of spaCy's treatment of contractions.
    starts = list(range(n))
    for i in range(1, n):
        current = clean[i]
        previous = clean[i - 1]
        boundary = tokens[i].startswith(("▁", "Ġ"))
        if (
            not special[i]
            and not special[i - 1]
            and not boundary
            and current
            and previous
            and current[0].isalnum()
            and previous[-1].isalnum()
        ):
            starts[i] = starts[i - 1]

    model_to_spacy = [None] * n
    spacy_to_model = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        if special[i]:
            continue
        valid = [k for k in indices if 0 <= k < len(doc)]
        if valid:
            # Prefer lexical overlap when a tokenizer piece also covers whitespace.
            lexical = [k for k in valid if not doc[k].is_space]
            k = (lexical or valid)[0]
            model_to_spacy[i] = k
            for k in valid:
                spacy_to_model[k].append(i)

    def anchor(k, limit):
        candidates = spacy_to_model[k]
        available = [j for j in candidates if j <= limit and not special[j]]
        return starts[min(available)] if available else None

    def add(row, j, weight, limit):
        if j is not None and 0 <= j <= limit:
            row[j] += weight

    salience = np.ones(n, dtype=np.float64)
    for i, k in enumerate(model_to_spacy):
        if special[i]:
            salience[i] = 0.65
        elif k is not None:
            w = doc[k]
            if w.pos_ in ("NOUN", "PROPN", "PRON"):
                salience[i] = 2.1
            elif w.pos_ in ("ADJ", "DET"):
                salience[i] = 1.35
            elif w.is_punct:
                salience[i] = 0.7
        if starts[i] != i:
            salience[i] *= 0.3

    first = next((i for i in range(n) if not special[i]), None)
    quote_marks = {'"', "“", "”", "«", "»", "„"}
    apostrophes = {"'", "’"}
    last_wh = None

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        distance = i - np.arange(i + 1)
        background = salience[:i + 1] * (
            0.10 + np.exp(-distance / 7.0)
        )
        background[0] += 0.7
        row = attention[i]
        row[:i + 1] = 0.9 * background / background.sum()
        row[i] += 0.28
        row[i - 1] += 0.12

        k = model_to_spacy[i]
        word = doc[k] if k is not None else None
        previous = clean[i - 1].strip()

        # Strong boundary-conditioned associations are characteristic of this head.
        if previous in apostrophes and clean[i] and clean[i][0].isalnum():
            row[i - 1] += 7.0
            continue

        if starts[i] < i:
            row[starts[i]] += 4.0
            continue

        if previous and all(c in quote_marks for c in previous):
            if clean[i] and any(c.isalnum() for c in clean[i]):
                row[i - 1] += 3.6

        if clean[i] and clean[i].isspace():
            row[i] += 0.35

        if word is None:
            if clean[i] and all(not c.isalnum() for c in clean[i]):
                row[i] += 0.6
            continue

        pos = word.pos_
        dep = word.dep_

        if word.tag_.startswith("W"):
            last_wh = i
            row[i] += 0.65

        if last_wh is not None and 0 < i - last_wh <= 6:
            intervening = tokens[last_wh + 1:i]
            if not any(any(c in ".!?" for c in t) for t in intervening):
                add(row, last_wh, 1.5 * np.exp(-(i - last_wh - 1) / 3.0), i)

        if pos == "PUNCT":
            row[i] += 0.8
            if any(c in ".!?" for c in word.text):
                last_wh = None
            continue

        if pos in ("NOUN", "PROPN"):
            modifiers = [
                c for c in word.children
                if c.i < word.i and c.dep_ in ("amod", "poss", "nummod")
            ]
            available = [(c, anchor(c.i, i)) for c in modifiers]
            available = [(c, j) for c, j in available if j is not None]
            if available:
                modifier, j = min(available, key=lambda pair: pair[0].i)
                add(row, j, 1.8 if modifier.dep_ != "nummod" else 1.1, i)
                row[i] += 0.22
            else:
                row[i] += 1.15

        elif pos == "PRON":
            row[i] += 0.8

        elif pos == "ADJ":
            earlier = [
                c for c in word.head.children
                if c.i < word.i and c.dep_ == "amod"
            ]
            if earlier and dep == "amod":
                add(row, anchor(min(earlier, key=lambda c: c.i).i, i), 1.6, i)
            else:
                row[i] += 0.75

        elif pos == "DET":
            row[i] += 0.6

        # Predicates and intervening function words retain the local subject anchor.
        governor = word
        subject = None
        for _ in range(4):
            subjects = [
                c for c in governor.children
                if c.dep_ in ("nsubj", "nsubjpass", "csubj") and c.i < word.i
            ]
            if subjects:
                subject = min(subjects, key=lambda c: abs(word.i - c.i))
                break
            if governor.head.i == governor.i:
                break
            governor = governor.head

        if subject is not None:
            j = anchor(subject.i, i)
            if j is not None:
                gap = i - j
                strength = 2.8 * np.exp(-max(0, gap - 1) / 5.5)
                if pos in ("VERB", "AUX", "ADV", "ADJ"):
                    add(row, j, strength, i)
                elif pos in ("DET", "ADP"):
                    add(row, j, 0.65 * strength, i)
                elif pos in ("NOUN", "PROPN") and dep in ("dobj", "obj", "dative"):
                    add(row, j, 0.4 * strength, i)

        if pos in ("ADP", "CCONJ", "SCONJ", "PART"):
            add(row, starts[i - 1], 0.65, i)

        # The first lexical token has a particularly stable self-attention prior.
        if i == first:
            self_mass = 0.9
            if pos == "ADP":
                self_mass = 0.6
            elif pos == "DET":
                self_mass = 0.865
            row[:] = 0.0
            row[i] = self_mass
            row[0] += 1.0 - self_mass

    return (
        "local_lexical_and_subject_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L0H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local phrase anchors with a delayed local channel across function-word,
    subword, and punctuation bridges."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_phrase_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    pieces = [
        token.replace("▁", "").replace("Ġ", "").removeprefix("##")
        for token in tokens
    ]
    punctuation = [
        bool(piece) and all(not c.isalnum() and not c.isspace() for c in piece)
        and tokens[i] not in special
        for i, piece in enumerate(pieces)
    ]

    matrix[0, 0] = 1.0
    first_content = next(
        (i for i, token in enumerate(tokens) if token not in special), None
    )

    for i in range(1, n):
        if i == first_content:
            matrix[i, i] = 0.90
            matrix[i, :i] = 0.10 / i
            continue

        distances = i - np.arange(i + 1)
        row = 0.38 * np.exp(-distances / 5.5)

        # BOS is not the principal sink of this head.
        for j in range(i + 1):
            if tokens[j] in special:
                row[j] = 0.08 * np.exp(-(i - j) / 12.0)

        row[i] += 1.05
        row[i - 1] += 0.90

        current = words[i]
        previous = words[i - 1]
        pos = current.pos_ if current is not None else ""
        previous_pos = previous.pos_ if previous is not None else ""

        # Function words often introduce a new, self-attending local unit.
        if pos in ("DET", "ADP", "CCONJ", "SCONJ", "AUX"):
            row[i] += 0.35
        if pos == "ADV":
            row[i] += 0.20

        same_word = bool(set(alignment[i]).intersection(alignment[i - 1]))
        if same_word and not punctuation[i]:
            row[i - 1] += 0.55
            row[i] += 0.10

        if current is not None and previous is not None and not same_word:
            # Phrase-initial determiners and possessives anchor following pieces.
            if previous_pos == "DET" or previous.dep_ == "poss":
                if pos in ("NOUN", "PROPN", "ADJ", "NUM"):
                    row[i - 1] += 0.90

            if previous.dep_ in ("nsubj", "nsubjpass", "csubj"):
                if pos == "VERB":
                    row[i - 1] += 0.65
                elif pos == "AUX":
                    row[i - 1] += 0.15

            if previous_pos in ("ADJ", "ADV") and pos in ("ADJ", "NOUN"):
                row[i - 1] += 0.35

            if pos == "PART" and previous_pos in ("VERB", "ADJ"):
                row[i - 1] += 0.70

            if pos == "ADP" and previous_pos in ("VERB", "NOUN", "ADV"):
                row[i - 1] += 0.20

        # A phrase-start anchor can remain visible beyond the immediately
        # preceding piece, including through a split noun or modifier.
        if pos in ("NOUN", "PROPN", "ADJ", "VERB", "AUX"):
            for j in range(max(0, i - 5), i - 1):
                anchor = words[j]
                if anchor is None or punctuation[j]:
                    continue
                if anchor.pos_ == "DET" or anchor.dep_ == "poss":
                    if not any(punctuation[k] for k in range(j + 1, i)):
                        row[j] += 0.55 * np.exp(-(i - j - 2) / 2.0)

        # Apostrophe-separated endings distinguish possessive self-attention
        # from contractions that reconnect to the pre-apostrophe stem.
        if i >= 2 and pieces[i - 1] in ("'", "’"):
            if current is not None and current.tag_ == "POS":
                row[i] += 1.10
            else:
                row[i - 2] += 1.80
                row[i - 1] *= 0.35

        if punctuation[i]:
            if any(c in pieces[i] for c in "?!"):
                row[i] += 0.65

        # Opening quotation marks provide a local boundary anchor.
        if punctuation[i - 1] and not punctuation[i]:
            if any(c in pieces[i - 1] for c in "\"“‘"):
                row[i - 1] += 0.90

        row /= row.sum()

        # Comma-plus-coordinator is an especially strong boundary bigram.
        if pos == "CCONJ" and "," in pieces[i - 1]:
            row *= 0.22
            row[i - 1] += 0.78
        elif pos == "ADP" and punctuation[i - 1]:
            if any(c in pieces[i - 1] for c in ".!?"):
                row *= 0.35
                row[i - 1] += 0.65

        # Bridge tokens can expose a two-/three-token-back local channel.
        # Preserve explicit boundary bigrams and opening-quote anchors.
        if i >= 3 and all(tokens[j] not in special for j in range(i - 2, i + 1)):
            boundary_bigram = (
                (pos == "CCONJ" and "," in pieces[i - 1])
                or (pos == "ADP" and punctuation[i - 1]
                    and any(c in pieces[i - 1] for c in ".!?"))
            )
            opening_quote = (
                punctuation[i - 1]
                and any(c in pieces[i - 1] for c in "\"“‘")
            )
            split_previous = bool(
                set(alignment[i - 1]).intersection(alignment[i - 2])
            )
            bridge = (
                previous_pos in ("AUX", "ADP", "CCONJ", "SCONJ", "PART")
                or punctuation[i - 1]
                or not pieces[i - 1].strip()
                or same_word
                or split_previous
            )
            if bridge and not boundary_bigram and not opening_quote:
                if punctuation[i - 1] and pieces[i - 1] not in ("'", "’"):
                    row[i - 1] *= 0.20
                    row /= row.sum()
                row *= 0.68
                row[i - 2] += 0.24
                if tokens[i - 3] not in special:
                    row[i - 3] += 0.08
                else:
                    row[i - 2] += 0.08

        matrix[i, :i + 1] = row

    return "local_phrase_anchors", make_row_stochastic(apply_causal_mask(matrix))


def prog_L0H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse clause attention; in quoted dialogue, punctuation and auxiliaries
    are weaker historical anchors, while standalone quotation marks remain salient."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_dialogue_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    words = [doc[ids[0]] if ids else None for ids in alignment]
    pos = [w.pos_ if w is not None else "" for w in words]
    dep = [w.dep_ if w is not None else "" for w in words]
    special = [t in tokenizer.all_special_tokens for t in tokens]
    punctuation = [
        (w is not None and w.is_punct)
        or (
            bool(t.replace("▁", "").replace("Ġ", "").strip())
            and all(
                not c.isalnum() and not c.isspace()
                for c in t.replace("▁", "").replace("Ġ", "")
            )
            and not special[i]
        )
        for i, (t, w) in enumerate(zip(tokens, words))
    ]
    boundary = [
        punctuation[i] and any(c in tokens[i] for c in ",;:.!?")
        for i in range(n)
    ]

    # Restrict the correction to quoted dialogue, leaving unquoted inputs unchanged.
    quote = [
        punctuation[i] and any(c in tokens[i] for c in '"“”')
        for i in range(n)
    ]
    dialogue = sum(quote) >= 2

    has_bos = special[0]
    matrix[0, 0] = 1.0

    for i in range(1, n):
        distances = i - np.arange(i + 1)
        weights = np.exp(-distances / 24.0)

        for j in range(i + 1):
            key_weight = 1.0

            if pos[j] == "AUX":
                key_weight = 2.8
            elif pos[j] == "ADP":
                key_weight = 1.25
            elif pos[j] == "CCONJ":
                key_weight = 1.45
            elif pos[j] == "SCONJ":
                key_weight = 1.65
            elif pos[j] == "VERB":
                key_weight = 1.2
            elif pos[j] in ("DET", "PRON"):
                key_weight = 0.95

            if punctuation[j]:
                key_weight = 2.7 if boundary[j] else 0.65

            if j == i:
                key_weight = 1.0
                if pos[i] == "VERB":
                    key_weight = 1.65
                elif pos[i] == "AUX":
                    key_weight = 0.60
                elif punctuation[i]:
                    key_weight = 0.20

            if j < i:
                distance = i - j

                if pos[j] == "AUX" and distance <= 3:
                    key_weight *= 1.30

                if pos[i] == "AUX":
                    if pos[j] in ("NOUN", "PROPN", "PRON"):
                        key_weight *= 1.45
                    elif pos[j] == "DET":
                        key_weight *= 1.15

                if punctuation[i] and not punctuation[j]:
                    key_weight *= 1.0 + 1.05 * np.exp(
                        -((distance - 1.8) / 1.7) ** 2
                    )

                if boundary[j]:
                    key_weight *= 1.0 + 0.55 * np.exp(
                        -((distance - 2.0) / 2.5) ** 2
                    )

                if (
                    words[i] is not None
                    and words[j] is not None
                    and words[i].i != words[j].i
                ):
                    if (
                        words[i].head.i == words[j].i
                        and pos[j] in ("AUX", "ADP", "SCONJ")
                    ):
                        key_weight *= 1.15

                if (
                    words[i] is not None
                    and words[j] is not None
                    and words[i].i == words[j].i
                ):
                    key_weight *= 0.85

                # Adjust only historical anchors in dialogue. Self weights,
                # distance decay, and the original BOS logic remain untouched.
                if dialogue:
                    if boundary[j]:
                        key_weight *= 0.38
                    elif quote[j]:
                        key_weight *= 2.4
                    elif pos[j] == "AUX":
                        key_weight *= 0.62

            weights[j] *= key_weight

        if has_bos:
            weights[0] = 1.55 * np.exp(-i / 32.0)
            if punctuation[i]:
                weights[0] *= 0.53
            elif pos[i] == "AUX":
                weights[0] *= 0.64

            if i == 1:
                bos_share = 0.60
                if pos[i] == "DET":
                    bos_share = 0.56
                elif pos[i] == "PROPN":
                    bos_share = 0.65
                elif pos[i] in ("NUM", "ADV", "CCONJ", "SCONJ"):
                    bos_share = 0.65
                elif pos[i] == "ADP":
                    bos_share = 0.52
                elif pos[i] == "PRON" and dep[i] == "poss":
                    bos_share = 0.62
                weights[0] = bos_share
                weights[1] = 1.0 - bos_share

        matrix[i, :i + 1] = weights / weights.sum()

    return "diffuse_dialogue_anchors", matrix


def prog_L0H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal attention with delayed grammatical anchors:
    immediate function-word predecessors donate mass to earlier context."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_peaks_with_delayed_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[a[0]] if a else None for a in alignment]
    positions = [w.pos_ if w is not None else "" for w in words]

    salience = np.ones(n, dtype=np.float64)
    for j in range(1, n):
        w = words[j]
        pos = positions[j]
        if pos == "AUX":
            salience[j] = 1.55
        elif pos == "CCONJ":
            salience[j] = 1.65
        elif pos == "SCONJ":
            salience[j] = 1.20
        elif pos in ("DET", "PRON"):
            salience[j] = 1.05
        elif pos == "PUNCT":
            text = w.text if w is not None else tokens[j]
            salience[j] = 1.85 if any(c in text for c in ",;:!?") else 1.05
        elif pos in ("NOUN", "PROPN", "ADJ"):
            salience[j] = 0.96

    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = positions[i]
        w = words[i]

        if i == 1:
            self_mass = 0.64
            if pos == "ADP":
                self_mass = 0.28
            elif pos == "SCONJ":
                self_mass = 0.29
            elif pos == "DET":
                self_mass = 0.611
            elif pos == "PROPN":
                self_mass = 0.67
            elif pos == "PRON":
                self_mass = 0.65
            elif pos == "NUM":
                self_mass = 0.623
            elif pos == "ADV":
                self_mass = 0.56
            attention[i, 0] = 1.0 - self_mass
            attention[i, i] = self_mass
            continue

        distance = i - np.arange(i + 1)
        row = 0.65 * salience[:i + 1] * np.exp(-distance / 40.0)
        row[0] = 0.86 * np.exp(-(i - 2) / 55.0)

        self_weight = {
            "NOUN": 1.12,
            "PROPN": 1.12,
            "PRON": 1.10,
            "DET": 1.10,
            "ADJ": 1.12,
            "ADV": 1.25,
            "VERB": 0.97,
            "AUX": 0.39,
            "ADP": 0.78,
            "SCONJ": 0.78,
            "CCONJ": 0.75,
            "PUNCT": 0.38,
        }.get(pos, 0.95)
        row[i] = self_weight

        previous_weight = 1.20
        if pos in ("VERB", "AUX"):
            previous_weight = 1.62
        elif pos in ("NOUN", "PROPN", "ADJ"):
            previous_weight = 1.27
        elif pos == "PUNCT":
            previous_weight = 1.28
        elif pos == "CCONJ":
            previous_weight = 1.24

        if words[i - 1] is not None and w is not None:
            if words[i - 1].i == w.i:
                previous_weight += 0.35
            elif positions[i - 1] == "PUNCT" and pos != "PUNCT":
                previous_weight += 0.22

        row[i - 1] = previous_weight

        # Clause-ending punctuation emphasizes earlier grammatical anchors.
        if pos == "PUNCT":
            for j in range(1, i - 1):
                if positions[j] in ("AUX", "CCONJ"):
                    row[j] *= 1.35

        # Function words remain useful distant anchors, but their immediate
        # successor often looks past them. Preserve total mass and self weight.
        if (
            i > 2
            and w is not None
            and words[i - 1] is not None
            and words[i - 1].i != w.i
            and positions[i - 1] in ("AUX", "CCONJ", "SCONJ", "PART", "ADP")
        ):
            retained = 0.30 if positions[i - 1] in ("AUX", "CCONJ", "PART") else 0.45
            transferred = row[i - 1] * (1.0 - retained)
            earlier_mass = row[1:i - 1].sum()
            if earlier_mass > 0.0:
                row[i - 1] *= retained
                row[1:i - 1] += transferred * row[1:i - 1] / earlier_mass

        attention[i, :i + 1] = row / row.sum()

    return "local_peaks_with_delayed_anchors", attention


def prog_L0H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a diffuse phrase-onset head favoring determiners, pronouns,
    modifiers, and word starts, with mild recency and syntactic reinforcement.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "salient_phrase_onsets", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    word_ids = [-1] * n
    first_piece = {}
    for i, aligned in enumerate(alignment):
        if tokens[i] in special_tokens:
            continue
        if aligned:
            sid = aligned[0]
            word_ids[i] = sid
            if sid not in first_piece:
                first_piece[sid] = i

    strengths = np.ones(n, dtype=np.float64)
    pos_strength = {
        "DET": 5.0,
        "PRON": 5.0,
        "PROPN": 3.2,
        "NOUN": 3.0,
        "ADJ": 3.2,
        "ADV": 5.2,
        "NUM": 4.2,
        "VERB": 1.0,
        "AUX": 0.7,
        "ADP": 0.28,
        "PART": 0.8,
        "CCONJ": 0.65,
        "SCONJ": 0.75,
        "INTJ": 3.5,
        "PUNCT": 0.55,
        "SPACE": 2.5,
    }

    for i in range(n):
        sid = word_ids[i]
        if tokens[i] in special_tokens:
            strengths[i] = 0.05
        elif sid >= 0:
            word = doc[sid]
            strengths[i] = pos_strength.get(word.pos_, 1.5)
            if word.dep_ in ("poss", "det"):
                strengths[i] = max(strengths[i], 5.0)
            if word.is_punct and any(c in word.text for c in "\"“”«»"):
                strengths[i] = 3.8
            if first_piece[sid] != i:
                strengths[i] = 0.85
        else:
            clean = tokens[i].replace("▁", " ").replace("Ġ", " ")
            strengths[i] = 2.5 if not clean.strip() else 1.0

    strengths[0] = 1.0
    if n > 1 and word_ids[1] >= 0:
        first_word = doc[word_ids[1]]
        if first_word.pos_ in ("PRON", "DET", "PROPN", "NUM", "ADV", "CCONJ"):
            strengths[1] = 4.55
        elif first_word.pos_ in ("ADP", "SCONJ"):
            strengths[1] = 0.25

    for i in range(n):
        distances = i - np.arange(i + 1)
        row = strengths[:i + 1] * np.exp(-0.018 * distances)
        row[0] = 1.0

        sid = word_ids[i]
        if sid >= 0:
            word = doc[sid]
            start = first_piece[sid]

            # Continuations favor the beginning of their own word.
            if start < i:
                row[start] *= 1.35

            # Noun-phrase material mildly reinforces its left determiner
            # or possessive, without requiring a completed future phrase.
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                head = word.head if word.dep_ == "amod" else word
                for child in head.children:
                    if child.dep_ in ("det", "poss"):
                        j = first_piece.get(child.i, -1)
                        if 0 <= j <= i:
                            row[j] *= 1.12

            if word.pos_ in ("VERB", "AUX"):
                for child in word.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        j = first_piece.get(child.i, -1)
                        if 0 <= j < i:
                            row[j] *= 1.08

            if word.pos_ == "ADJ":
                for child in word.children:
                    if child.dep_ == "advmod":
                        j = first_piece.get(child.i, -1)
                        if 0 <= j < i:
                            row[j] *= 1.2

        attention[i, :i + 1] = row

    return "salient_phrase_onsets", make_row_stochastic(attention)


def prog_L0H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse causal averaging; initial prepositional frames favor following
    determiners/adverbials over the opening preposition as persistent keys.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_causal_initial_adp", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos = []
    punct = []
    for i, token in enumerate(tokens):
        matches = alignment[i]
        if token in special_tokens or not matches:
            pos.append("")
            punct.append(False)
        else:
            word = doc[matches[0]]
            pos.append(word.pos_)
            punct.append(word.is_punct)

    has_bos = tokens[0] in special_tokens
    first = 1 if has_bos else 0

    # Restrict the correction to sentences opening with a prepositional frame.
    initial_adp = first < n and pos[first] == "ADP"

    key_bias = {
        "DET": 1.14,
        "PRON": 1.13,
        "PROPN": 1.05,
        "NOUN": 1.04,
        "ADJ": 1.00,
        "ADV": 0.96,
        "VERB": 0.95,
        "AUX": 0.91,
        "ADP": 1.04,
        "CCONJ": 0.94,
        "SCONJ": 1.02,
        "PART": 0.94,
        "PUNCT": 0.94,
    }
    self_bias = {
        "DET": 0.80,
        "PRON": 0.85,
        "PROPN": 0.78,
        "NOUN": 0.80,
        "ADJ": 0.83,
        "ADV": 1.03,
        "VERB": 1.16,
        "AUX": 1.42,
        "ADP": 1.40,
        "CCONJ": 1.48,
        "SCONJ": 1.14,
        "PART": 1.12,
        "PUNCT": 1.75,
    }

    for i in range(n):
        for j in range(i + 1):
            distance = i - j
            weight = key_bias.get(pos[j], 1.0)

            # A shallow positional modulation preserves broad distributions.
            weight *= (
                1.0
                + 0.15 * np.exp(-((distance - 3.5) / 2.5) ** 2)
            )
            weight *= 0.85 + 0.15 * np.exp(-distance / 32.0)

            # Initial lexical tokens are modest anchors, not fixed-mass sinks.
            if j == first and j != i:
                strength = 0.40
                if pos[j] in ("DET", "PRON"):
                    strength = 0.58
                weight *= 1.0 + strength * np.exp(-i / 20.0)

            if has_bos and j == 0:
                weight = 0.95 * (
                    0.80 + 0.20 * np.exp(-i / 16.0)
                )

            if j == i:
                weight = self_bias.get(pos[i], 1.10)
                if punct[i]:
                    weight = 1.75

            # Opening quotation marks act as weak local anchors.
            if j != i and tokens[j].strip("▁Ġ \t\r\n") in (
                '"', "“", "‘", "«"
            ):
                weight *= 1.0 + 0.55 * np.exp(-distance / 10.0)

            # Opening prepositions are not persistent lexical anchors.
            # Leave self-attention and BOS weights untouched.
            if initial_adp and j != i:
                if j == first:
                    weight *= 0.80 if distance == 1 else 0.60
                elif j > first and pos[j] == "DET":
                    weight *= 1.45
                elif j == first + 1 and pos[j] == "ADV":
                    weight *= 1.35

            matrix[i, j] = weight

    if has_bos:
        matrix[0, 0] = 1.0
        if n > 1:
            bos_share = {
                "PRON": 0.562,
                "DET": 0.531,
                "PROPN": 0.575,
                "ADP": 0.440,
                "SCONJ": 0.470,
            }.get(pos[1], 0.530)
            matrix[1, 0] = bos_share
            matrix[1, 1] = 1.0 - bos_share

    return "diffuse_causal_initial_adp", make_row_stochastic(matrix)


def prog_L0H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS and grammatical anchors, with subword continuations as additional anchors.
    Continuation queries rely less on inherited grammatical-anchor preferences.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_anchors_with_subword_support", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos = [""] * n
    dep = [""] * n
    word_index = [-1] * n
    is_special = [False] * n
    is_punctuation = [False] * n
    key_strength = np.ones(n, dtype=np.float64)
    is_continuation = [False] * n

    for j in range(n):
        is_special[j] = tokens[j] in special_tokens
        if alignment[j] and not is_special[j]:
            word = doc[alignment[j][0]]
            pos[j] = word.pos_
            dep[j] = word.dep_
            word_index[j] = word.i
            is_punctuation[j] = word.is_punct

            if word.pos_ == "AUX":
                key_strength[j] = 6.5
            elif word.pos_ == "ADP":
                key_strength[j] = 3.5
            elif word.pos_ in ("CCONJ", "SCONJ"):
                key_strength[j] = 4.7
            elif word.pos_ == "PART":
                key_strength[j] = 2.2
            elif word.pos_ == "VERB":
                key_strength[j] = 2.0
            elif word.is_punct:
                key_strength[j] = 3.8
            else:
                key_strength[j] = 1.0

            if j > 0 and word_index[j] == word_index[j - 1]:
                key_strength[j] *= 0.65
                is_continuation[j] = (
                    not word.is_punct and not word.is_space
                )
        elif is_special[j]:
            key_strength[j] = 0.6

    # A fixed BOS mass naturally becomes less dominant as the prefix grows.
    key_strength[0] = 2.9
    attention[0, 0] = 1.0

    for i in range(1, n):
        weights = key_strength[:i + 1].copy()
        query_is_boundary = (
            is_punctuation[i] or pos[i] in ("CCONJ", "SCONJ")
        )

        for j in range(1, i + 1):
            distance = i - j

            # Mostly diffuse, with a modest local preference rather than a
            # sharply previous-token pattern.
            weights[j] *= 0.82 + 0.18 * np.exp(-distance / 6.0)

            if query_is_boundary:
                if pos[j] in ("AUX", "ADP", "PART", "CCONJ", "SCONJ"):
                    weights[j] *= 0.24
                elif pos[j] == "VERB":
                    weights[j] *= 0.55
                elif is_punctuation[j]:
                    weights[j] *= 0.22
                else:
                    weights[j] *= 1.35
            else:
                # Predicative and adverbial material particularly favors
                # the auxiliary anchoring its clause.
                if pos[j] == "AUX" and pos[i] in ("ADJ", "ADV"):
                    weights[j] *= 1.35

                if (
                    pos[j] == "CCONJ"
                    and pos[i] == "VERB"
                    and distance <= 3
                ):
                    weights[j] *= 1.35

            if j == i:
                if pos[i] == "VERB":
                    weights[j] *= 1.55
                elif pos[i] == "AUX":
                    weights[j] *= 0.43
                elif is_punctuation[i]:
                    weights[j] *= 0.45
                elif pos[i] in ("CCONJ", "SCONJ"):
                    weights[j] *= 0.65

        if query_is_boundary:
            weights[0] *= 0.38

        # Preserve the characteristic strong first-token-to-BOS behavior.
        if i == 1:
            if pos[i] == "ADP":
                weights[1] = 3.4
            elif pos[i] == "DET":
                weights[1] = 1.38
            elif not is_punctuation[i]:
                weights[1] = 1.05

        # Split-word fragments are useful keys, not merely discounted copies
        # of their parent word. Leave the original self-weight untouched.
        for j in range(1, i):
            if is_continuation[j]:
                weights[j] *= 2.6

        # A continuation query is not a new grammatical word: temper only
        # its inherited preference for BOS and preceding function anchors.
        if is_continuation[i]:
            weights[0] *= 0.65
            for j in range(1, i):
                if (
                    not is_continuation[j]
                    and pos[j] in ("AUX", "ADP", "PART", "CCONJ", "SCONJ")
                ):
                    weights[j] *= 0.45

        attention[i, :i + 1] = weights / weights.sum()

    return "bos_anchors_with_subword_support", attention


def prog_L0H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Broad causal attention with early-token anchoring and a mild positional wave.
    Function words and punctuation receive enhanced self and nearby attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_anchor_function_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    positions = []
    punctuation = []
    whitespace = []
    for i, token in enumerate(tokens):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        positions.append(word.pos_ if word is not None else "")
        clean = token.replace("▁", " ").replace("Ġ", " ")
        punctuation.append(
            token not in specials
            and bool(clean.strip())
            and all(not c.isalnum() and not c.isspace() for c in clean)
        )
        whitespace.append(token not in specials and not clean.strip())

    key_strength = np.ones(n, dtype=np.float64)
    self_strength = np.ones(n, dtype=np.float64)

    for i in range(n):
        pos = positions[i]
        if pos in ("NOUN", "PROPN", "ADJ"):
            self_strength[i] = 0.72
        elif pos == "VERB":
            self_strength[i] = 1.20
        elif pos == "AUX":
            self_strength[i] = 2.55
        elif pos in ("ADP", "PART"):
            self_strength[i] = 2.05
            key_strength[i] = 1.28
        elif pos in ("CCONJ", "SCONJ"):
            self_strength[i] = 2.05
            key_strength[i] = 1.08
        elif pos == "DET":
            self_strength[i] = 0.66
            key_strength[i] = 0.88
        elif pos == "PRON":
            self_strength[i] = 0.88
        elif pos == "ADV":
            self_strength[i] = 0.95

        if punctuation[i]:
            self_strength[i] = 2.25
            key_strength[i] = 1.35
        elif whitespace[i]:
            self_strength[i] = 0.55
            key_strength[i] = 0.70

    has_bos = tokens[0] in specials
    first = 1 if has_bos else 0
    attention[0, 0] = 1.0

    for i in range(1, n):
        distance = i - np.arange(i + 1, dtype=np.float64)

        # A shallow lag-3 hump, not a sharp previous-token lookup.
        kernel = (
            0.94
            + 0.36 * np.exp(-0.5 * ((distance - 3.0) / 1.55) ** 2)
            + 0.10 * np.exp(-distance / 16.0)
        )
        weights = kernel * key_strength[:i + 1]
        weights[i] = self_strength[i]

        if i > first:
            weights[first] *= 1.25

        if has_bos:
            weights[0] = 1.05 + 0.40 * np.exp(-(i - 1.0) / 3.5)

        # A comma or opening delimiter remains salient to the following token.
        if punctuation[i - 1]:
            weights[i - 1] *= 1.25
        if whitespace[i]:
            weights[i - 1] *= 1.35

        # First-token competition with BOS is primarily a lexical-class effect.
        if has_bos and i == first:
            pos = positions[i]
            if pos in ("ADP", "SCONJ"):
                own_probability = 0.61
            elif pos == "DET":
                own_probability = 0.375
            elif pos in ("PRON", "PROPN", "NUM"):
                own_probability = 0.41
            else:
                own_probability = 0.44
            weights[0] = 1.0 - own_probability
            weights[i] = own_probability

        attention[i, :i + 1] = weights / weights.sum()

    return "early_anchor_function_self", attention


def prog_L0H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a persistent boundary-anchor head with strong self-attention.
    Function words, punctuation, and subword endings become salient causal keys.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    key_strength = np.ones(n, dtype=np.float64)
    self_strength = np.ones(n, dtype=np.float64)
    anchor = np.zeros(n, dtype=bool)
    poses = [""] * n
    blank = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        if token in specials:
            key_strength[i] = 4.0 if i == 0 else 0.5
            self_strength[i] = key_strength[i]
            continue

        clean = token.lstrip("▁Ġ")
        blank[i] = not clean.strip()
        mapped = alignment[i]
        word = None
        if mapped:
            # Prefer the lexical token when an offset also overlaps punctuation.
            word = doc[mapped[0]]
            for k in mapped:
                if not doc[k].is_space and not doc[k].is_punct:
                    word = doc[k]
                    break

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        poses[i] = pos

        key, diagonal = 1.0, 2.0
        if pos in ("NOUN", "PROPN"):
            key, diagonal = 1.4, 2.8
        elif pos == "PRON":
            key, diagonal = 1.3, 2.6
        elif pos == "DET":
            key, diagonal = 0.7, 1.3
        elif pos in ("ADJ", "ADV", "NUM"):
            key, diagonal = 1.0, 2.2
        elif pos == "VERB":
            key, diagonal = 2.5, 7.5

        if pos == "AUX" or dep in ("aux", "auxpass", "cop"):
            key, diagonal = 10.0, 43.0
            anchor[i] = True
        elif pos == "ADP" or dep in ("prep", "agent"):
            key, diagonal = 11.0, 43.0
            anchor[i] = True
        elif pos == "PART" and dep == "aux":
            key, diagonal = 11.0, 43.0
            anchor[i] = True
        elif pos == "CCONJ":
            key, diagonal = 12.0, 43.0
            anchor[i] = True
        elif pos == "SCONJ" or dep == "mark":
            key, diagonal = 8.0, 26.0
            anchor[i] = True

        # SentencePiece continuations often act as additional local anchors.
        continuation = (
            i > 0
            and bool(clean)
            and not token.startswith(("▁", "Ġ"))
            and any(c.isalnum() for c in clean)
            and bool(mapped)
            and bool(set(mapped).intersection(alignment[i - 1]))
        )
        if continuation:
            key = max(key, 7.0)
            diagonal = max(diagonal, 27.0)
            anchor[i] = True

        # Opening quotes inherit the preceding boundary rather than replacing it.
        if any(c in ",;:.!?" for c in clean):
            key, diagonal = 20.0, 65.0
            anchor[i] = True
        elif clean and all(not c.isalnum() for c in clean):
            key, diagonal = 0.5, 0.8
        if blank[i]:
            key, diagonal = 0.2, 0.4

        key_strength[i] = key
        self_strength[i] = diagonal

    for i in range(n):
        distances = i - np.arange(i + 1)
        row = key_strength[:i + 1] * np.exp(-0.008 * distances)
        row = row.copy()
        row[i] = self_strength[i]

        # A nearby lexical predicate can anchor its following argument phrase.
        if poses[i] in ("DET", "ADJ", "NOUN", "PRON"):
            for j in range(i - 1, max(-1, i - 5), -1):
                if anchor[j]:
                    break
                if poses[j] == "VERB":
                    row[j] *= 3.5 if poses[i] == "DET" else 1.6
                    break

        if blank[i] and i > 0:
            row[i - 1] *= 1.25

        attention[i, :i + 1] = row

    return "persistent_boundary_anchors", make_row_stochastic(attention)


def prog_L0H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Diffuse lexical locality with delayed adpositional landmarks when the
    sentence opens with a prepositional frame.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "diffuse_prepositional_landmarks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    words = []
    positions = []
    starts = []
    for i in range(n):
        candidates = alignment[i]
        sid = candidates[0] if candidates and tokens[i] not in specials else None
        words.append(doc[sid] if sid is not None else None)
        positions.append(sid)
        if sid is None:
            starts.append(i)
        elif i > 0 and positions[i - 1] == sid:
            starts.append(starts[i - 1])
        else:
            starts.append(i)

    # Restrict the added behavior to sentence-initial prepositional frames.
    opening_index = next(
        (j for j, word in enumerate(words)
         if word is not None and not word.is_punct),
        None,
    )
    prepositional_frame = (
        opening_index is not None
        and words[opening_index].pos_ == "ADP"
    )

    self_strength = {
        "NOUN": 1.65, "PROPN": 1.65, "PRON": 1.70,
        "DET": 1.80, "ADJ": 1.50, "ADV": 1.65,
        "VERB": 1.25, "AUX": 0.65, "ADP": 0.48,
        "PART": 0.85, "CCONJ": 0.85, "SCONJ": 1.10,
        "NUM": 1.70, "PUNCT": 0.55,
    }
    key_strength = {
        "NOUN": 1.00, "PROPN": 1.00, "PRON": 0.95,
        "DET": 0.92, "ADJ": 1.00, "ADV": 1.00,
        "VERB": 1.05, "AUX": 1.25, "ADP": 0.80,
        "PART": 0.85, "CCONJ": 1.25, "SCONJ": 1.05,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        distances = i - np.arange(i + 1)
        row = 0.82 + 0.18 * np.exp(-distances / 8.0)

        for j in range(1, i):
            key = words[j]
            if key is not None:
                strength = key_strength.get(key.pos_, 1.0)
                if key.is_punct:
                    strength = 1.35 if key.text in (",", ";", ":", ".", "!", "?") else 0.90
                row[j] *= strength
                if starts[j] != j:
                    row[j] *= 0.82

        row[0] = 1.08
        row[i] = self_strength.get(pos, 1.35)

        if i == 1:
            row[0] = 1.0
            row[i] = 0.36 if pos == "ADP" else (
                0.65 if pos == "SCONJ" else 1.62
            )
        elif starts[i] < i:
            row[i] *= 0.65
            row[starts[i]] += 0.65
        else:
            previous = words[i - 1]
            previous_pos = previous.pos_ if previous is not None else ""
            multiplier = 1.12

            if pos in ("VERB", "AUX") and previous_pos in (
                "PRON", "NOUN", "PROPN"
            ):
                multiplier = 1.65 if pos == "VERB" else 1.90
            elif pos in ("NOUN", "PROPN") and previous_pos in ("DET", "ADJ"):
                multiplier = 1.22
            elif pos == "PUNCT":
                multiplier = 1.65
            elif pos == "CCONJ":
                multiplier = 1.35

            row[i - 1] *= multiplier

            # Weak syntactic correction: this is not a sharply focused
            # dependency head, so only nearby, already-visible heads matter.
            if word is not None:
                head_sid = word.head.i
                if head_sid != word.i:
                    for j in range(max(1, i - 4), i):
                        if positions[j] == head_sid and starts[j] == j:
                            row[j] *= 1.08
                            break

        # Adpositions become persistent landmarks after the immediate next
        # token. Leave self, previous-token, BOS, and other raw weights intact.
        if prepositional_frame:
            for j in range(1, i - 1):
                key = words[j]
                if key is not None and key.pos_ == "ADP" and starts[j] == j:
                    row[j] *= 2.20 if j == opening_index else 1.90

        attention[i, :i + 1] = row / row.sum()

    return "diffuse_prepositional_landmarks", attention


def prog_L1H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS/function-word anchors, with persistent lexical continuation anchors.
    Genuine split-word suffixes remain salient; punctuation is not a word piece.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_and_lexical_piece_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    clean = [t.lstrip("▁Ġ").removeprefix("##") for t in tokens]
    pos = []
    dep = []
    tag = []
    for indices in alignment:
        if indices:
            word = doc[indices[0]]
            pos.append(word.pos_)
            dep.append(word.dep_)
            tag.append(word.tag_)
        else:
            pos.append("")
            dep.append("")
            tag.append("")

    # Key salience: ordinary content is mostly local; function-word anchors
    # remain useful to queries well beyond their immediate phrase.
    strength = np.zeros(n, dtype=np.float64)
    lifetime = np.full(n, 5.0, dtype=np.float64)
    first_piece = [True] * n
    for j in range(1, n):
        shared_word = bool(set(alignment[j]) & set(alignment[j - 1]))
        lexical_continuation = (
            not tokens[j].startswith(("▁", "Ġ"))
            and clean[j].isalnum()
            and clean[j - 1].isalnum()
            and tokens[j] not in special
            and tokens[j - 1] not in special
        )
        first_piece[j] = not (shared_word or lexical_continuation)

        if not first_piece[j]:
            strength[j] = 0.35
        elif pos[j] == "ADP" or tag[j] == "TO":
            strength[j], lifetime[j] = 8.0, 24.0
        elif pos[j] == "AUX":
            strength[j], lifetime[j] = 3.8, 17.0
        elif pos[j] == "VERB":
            strength[j], lifetime[j] = 0.9, 9.0
        elif pos[j] in ("NOUN", "PROPN"):
            strength[j], lifetime[j] = 1.35, 5.0
        elif pos[j] in ("ADJ", "ADV"):
            strength[j] = 0.65
        elif pos[j] == "PUNCT":
            strength[j], lifetime[j] = 0.65, 6.0
        else:
            strength[j] = 0.24

        # Sentence-initial function words generally do not displace BOS.
        if j == 1:
            strength[j] = (
                1.5 if pos[j] == "ADP"
                else 0.9 if pos[j] == "PROPN"
                else 0.25
            )

    # Additional path: distinguish genuine lexical suffixes from overlap
    # caused by quotation marks, punctuation, or malformed character pieces.
    piece_anchor = np.zeros(n, dtype=np.float64)
    lexical_piece = [False] * n
    for j in range(2, n):
        if tokens[j] in special or not clean[j].isalpha():
            continue

        shared = set(alignment[j]) & set(alignment[j - 1])
        lexical_piece[j] = (
            not first_piece[j]
            and clean[j - 1].isalpha()
            and any(
                doc[k].is_alpha
                and doc[k].pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "ADV")
                for k in shared
            )
        )
        contraction_suffix = (
            clean[j - 1] in ("'", "’")
            and not tokens[j].startswith(("▁", "Ġ"))
            and pos[j] in ("AUX", "PART", "PRON")
        )
        if lexical_piece[j] or contraction_suffix:
            piece_anchor[j] = 5.0

    has_piece_anchors = bool(np.any(piece_anchor))

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 8.0 * np.exp(-(i - 1) / 16.0) + 0.35

        for j in range(1, i + 1):
            distance = i - j
            attention[i, j] = (
                0.16 * np.exp(-distance / 22.0)
                + strength[j] * np.exp(-distance / lifetime[j])
            )
        attention[i, i - 1] += 0.12

        if not first_piece[i]:
            # Continuation pieces often favor the immediately preceding piece.
            boost = 14.0 if len(clean[i]) == 1 else 5.5
            if pos[i] == "VERB":
                boost += 4.0
            attention[i, i - 1] += boost
            attention[i, i] += 0.65

        if clean[i - 1] in ("'", "’"):
            attention[i, i - 1] += 6.0
            attention[i, i] += 0.8

        # Commas can serve as local clause-boundary anchors, especially
        # for the beginning of quoted speech.
        for j in range(max(1, i - 3), i):
            if clean[j] in (",", ";", ":") and pos[i] in ("PRON", "ADV"):
                attention[i, j] += 2.3 * np.exp(-(i - j - 1) / 3.0)

        if tokens[i] in special or clean[i].isspace() or not clean[i]:
            attention[i, 0] += 1.0

        if has_piece_anchors:
            # Add only past-key salience: retain every original diagonal
            # weight and every original decay schedule.
            for j in range(2, i):
                if piece_anchor[j]:
                    attention[i, j] += (
                        piece_anchor[j] * np.exp(-(i - j - 1) / 40.0)
                    )

            # Alignment overlap alone must not create a large punctuation
            # continuation edge. Undo only that extra off-diagonal boost.
            if not first_piece[i] and not lexical_piece[i]:
                if not clean[i].isalpha() or not clean[i - 1].isalpha():
                    boost = 14.0 if len(clean[i]) == 1 else 5.5
                    if pos[i] == "VERB":
                        boost += 4.0
                    attention[i, i - 1] -= boost

            if piece_anchor[i] and clean[i - 1] in ("'", "’"):
                attention[i, i - 1] -= 4.0

    return "bos_and_lexical_piece_anchors", make_row_stochastic(attention)


def prog_L1H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink and phrase boundaries, with a coordination-specific backward anchor.
    Coordinators retrieve the preceding predicate or the earlier list delimiter.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_coordination_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    special_tokens = set(tokenizer.all_special_tokens)
    continuation = np.zeros(n, dtype=bool)

    for i in range(1, n):
        if alignment[i] and alignment[i - 1]:
            continuation[i] = bool(
                set(alignment[i]).intersection(alignment[i - 1])
            )

    # These are key-side priors, not predictions of a particular dependency.
    salience = np.full(n, 0.16, dtype=np.float64)
    for j in range(1, n):
        word = words[j]
        if word is not None:
            if word.pos_ == "ADP" or word.dep_ == "mark":
                salience[j] = 1.65
            elif word.pos_ == "AUX":
                salience[j] = 1.15
            elif word.pos_ == "DET":
                salience[j] = 0.60
            elif word.pos_ == "PART":
                salience[j] = 0.75
        if continuation[j]:
            salience[j] = max(salience[j], 0.85)
        if tokens[j].strip() in (",", ";", ":"):
            salience[j] = 1.05

    attention[0, 0] = 1.0
    last_preposition = None

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        punctuation = (
            bool(surface)
            and all(not c.isalnum() for c in surface)
            and tokens[i] not in special_tokens
        )
        separator = surface in (",", ";", ":")
        terminal = bool(surface) and any(c in ".!?" for c in surface)
        preposition = (
            not continuation[i]
            and (pos == "ADP" or dep == "mark")
        )

        bos = 0.10 + 0.82 * np.exp(-(i - 1) / 6.7)
        if i == 1:
            if pos in ("ADP", "SCONJ"):
                bos = 0.66
            elif pos == "DET":
                bos = 0.94
            elif pos == "PRON":
                bos = 0.91
            else:
                bos = 0.87
        elif pos in ("AUX", "DET", "PART"):
            bos *= 0.72

        if last_preposition is not None:
            bos *= 0.64
        if preposition:
            bos *= 0.25
        if separator:
            bos *= 0.25
        elif terminal:
            bos *= 0.55
        if not surface or tokens[i] in special_tokens:
            bos = max(bos, 0.28)

        bos = float(np.clip(bos, 0.035, 0.97))
        row = np.zeros(n, dtype=np.float64)
        positions = np.arange(1, i + 1)
        row[1:i + 1] = (
            salience[1:i + 1] * np.exp(-(i - positions) / 15.0)
        )

        row[i] += 0.65
        if i > 1:
            row[i - 1] += 0.80
        if i > 2:
            row[i - 2] += 0.25

        if pos in ("AUX", "PART"):
            row[i] += 1.8

        if continuation[i]:
            row[i] += 3.0
            if i > 1:
                row[i - 1] += 0.35

        # Objects and determiners retain the opening preposition as an anchor.
        if last_preposition is not None:
            distance = i - last_preposition
            if distance <= 6 and pos in (
                "DET", "ADJ", "NOUN", "PROPN", "PRON"
            ):
                row[last_preposition] += 2.7 * np.exp(-distance / 6.0)

        if pos == "CCONJ":
            for j in range(i - 1, max(0, i - 9), -1):
                if tokens[j].strip() in (",", ";", ":"):
                    row[j] += 4.0
                    break
            for j in range(i - 1, max(0, i - 7), -1):
                if words[j] is not None and words[j].pos_ == "AUX":
                    row[j] += 2.3
                    break

        if separator and i > 1:
            row[i - 1] += 3.8
            for j in range(i - 2, max(0, i - 6), -1):
                if tokens[j].strip() in (",", ";", ":"):
                    row[j] += 3.0
                    break

        if terminal:
            row[i] += 3.2
            if i > 1 and continuation[i - 1]:
                row[i - 1] += 3.2

        # Reserve a dominant backward edge at a new prepositional boundary.
        if preposition and i > 1:
            previous = words[i - 1]
            strength = 0.60
            if previous is not None and previous.pos_ in ("NOUN", "PRON"):
                strength = 0.64
            if pos == "SCONJ":
                strength = 0.38

            row[i - 1] = 0.0
            total = row.sum()
            if total > 0:
                row *= max(0.0, 1.0 - bos - strength) / total
            row[i - 1] = strength
        else:
            total = row.sum()
            if total > 0:
                row *= (1.0 - bos) / total

        row[0] = bos

        # Only coordinators take this path; retain their original self weight.
        if pos == "CCONJ" and not continuation[i] and i > 2:
            anchor = None
            list_coordination = False
            previous_surface = tokens[i - 1].replace(
                "▁", ""
            ).replace("Ġ", "").strip()

            if previous_surface in (",", ";", ":"):
                for j in range(i - 2, max(0, i - 9), -1):
                    candidate = tokens[j].replace(
                        "▁", ""
                    ).replace("Ġ", "").strip()
                    if candidate in (",", ";", ":"):
                        anchor = j
                        list_coordination = True
                        break
                    if any(c in candidate for c in ".!?"):
                        break
            else:
                for j in range(i - 1, max(0, i - 7), -1):
                    candidate = tokens[j].replace(
                        "▁", ""
                    ).replace("Ġ", "").strip()
                    if any(c in candidate for c in ",;:.!?"):
                        break
                    if words[j] is not None and words[j].pos_ in ("AUX", "VERB"):
                        anchor = j
                        break

            if anchor is not None:
                target = 0.55 if list_coordination else 0.43
                target = min(target, 1.0 - row[i])
                row[anchor] = 0.0
                if list_coordination:
                    row[i - 1] *= 0.20
                else:
                    row[0] = min(row[0], 0.03)
                remainder = row[:i].sum()
                if remainder > 0:
                    row[:i] *= (1.0 - row[i] - target) / remainder
                    row[anchor] = target
                else:
                    row[anchor] = 1.0 - row[i]

        attention[i] = row

        if preposition:
            last_preposition = i

    return (
        "bos_sink_with_coordination_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L1H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-backed local anchoring, with persistent phrase anchors in quoted discourse.
    Prepositions, auxiliaries, and split reporting verbs can remain visible across clauses."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_and_persistent_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    words = []
    for i, sids in enumerate(alignment):
        candidates = [doc[k] for k in sids if not doc[k].is_space]
        words.append(candidates[0] if candidates and tokens[i] not in specials else None)

    content_pos = {"NOUN", "PROPN", "VERB", "AUX", "ADJ", "ADV"}
    function_pos = {"DET", "PRON", "ADP", "PART", "CCONJ", "SCONJ"}
    subject_deps = {"nsubj", "nsubjpass", "csubj", "csubjpass"}
    possessive_deps = {"poss", "det:poss"}
    wh_tags = {"WDT", "WP", "WP$", "WRB"}

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        q = words[i]
        pos = q.pos_ if q is not None else ""
        dep = q.dep_ if q is not None else ""
        raw = tokens[i]
        text = raw.replace("▁", " ").replace("Ġ", " ").strip()
        punctuation = bool(text) and all(
            not c.isalnum() and not c.isspace() for c in text
        )
        whitespace = not text

        # A sparse local prior with a weak, decaying causal background.
        indices = np.arange(i + 1)
        distance = i - indices
        row = 0.025 * np.exp(-distance / 14.0)
        row[i] += 0.20
        row[i - 1] += 0.24
        if i >= 2:
            row[i - 2] += 0.22
        if i >= 3:
            row[i - 3] += 0.10

        sink = 0.55 + 3.2 * np.exp(-(i - 1) / 11.0)
        if pos in content_pos:
            sink *= 1.22
        elif pos in function_pos:
            sink *= 0.65
        if i <= 2:
            sink = 3.6
        row[0] += sink

        if pos in {"ADP", "PART"}:
            row[i] += 2.4 if pos == "ADP" else 1.6
            if q is not None and q.dep_ == "mark":
                row[i] *= 0.65

        if pos == "AUX" and i > 2:
            row[i] += 0.55

        if pos == "DET" or dep in possessive_deps:
            row[0] *= 0.42
            for j in range(max(1, i - 4), i):
                k = words[j]
                if k is None:
                    continue
                d = i - j
                strength = 0.0
                if k.pos_ in {"VERB", "AUX"}:
                    strength += 2.5
                if k.pos_ in {"PRON", "DET", "ADV", "ADJ"}:
                    strength += 1.6
                if k.pos_ in {"NOUN", "PROPN"}:
                    strength += 0.65
                if k.pos_ == "ADP":
                    strength += 1.2
                if k.idx == q.idx:
                    strength *= 0.15
                row[j] += strength * np.exp(-(d - 1) / 1.5)

                # Possessives often look across a verb to its subject.
                if dep in possessive_deps and k.dep_ in subject_deps:
                    row[j] += 2.4 * np.exp(-max(0, d - 2) / 3.0)

        if pos == "PRON" and dep not in possessive_deps:
            row[0] *= 0.62 if i > 2 else 1.0
            if i >= 2:
                row[i - 2] += 1.25
            for j in range(max(1, i - 7), i):
                k = words[j]
                if k is None:
                    continue
                d = i - j
                strength = 0.0
                if k.tag_ in wh_tags:
                    strength += 5.0
                if k.pos_ in {"CCONJ", "SCONJ", "INTJ"}:
                    strength += 2.2
                if k.dep_ in subject_deps and dep not in subject_deps:
                    strength += 2.0
                if k.pos_ == "ADP":
                    strength += 0.7
                row[j] += strength * np.exp(-max(0, d - 2) / 3.0)

        if pos in {"NOUN", "PROPN", "ADJ", "VERB", "ADV", "PUNCT"}:
            # Preserve nearby prepositional and infinitival phrase anchors.
            for j in range(max(1, i - 8), i):
                k = words[j]
                if k is None:
                    continue
                d = i - j
                if k.pos_ in {"ADP", "PART"}:
                    row[j] += 0.95 * np.exp(-(d - 1) / 4.0)
                if k.pos_ in {"VERB", "AUX"} and d <= 3:
                    row[j] += 0.24 * np.exp(-(d - 1) / 2.0)

        # A continuation subtoken can form its own local anchor.
        if (
            i > 1
            and not raw.startswith(("▁", "Ġ"))
            and q is not None
            and words[i - 1] is not None
            and q.idx == words[i - 1].idx
        ):
            row[i] += 1.2
            row[i - 1] += 0.55

        if punctuation:
            row[i] += 0.65
            if any(c in text for c in "\"'“”‘’"):
                row[i - 1] += 2.5
                if i >= 2:
                    k = words[i - 2]
                    if k is not None and k.pos_ in {"VERB", "AUX"}:
                        row[i - 2] += 1.4

        if whitespace:
            row[0] *= 0.25
            row[i - 1] += 4.0

        if q is not None and (pos in {"DET", "PRON", "CCONJ", "SCONJ"}):
            for j in range(max(1, i - 2), i):
                k = words[j]
                if k is not None and k.is_punct:
                    row[j] += 0.9 / (i - j)

        # Only quoted prefixes activate the additional long-range pathway.
        # Existing self weights and all original decay terms remain untouched.
        if not whitespace and any(
            any(c in t for c in "\"“”„«»€") for t in tokens[1:i + 1]
        ):
            for j in range(1, i - 2):
                k = words[j]
                if k is None:
                    continue
                # Represent each word once, at its final model subtoken.
                if words[j + 1] is not None and words[j + 1].idx == k.idx:
                    continue
                split_reporting_verb = (
                    k.pos_ == "VERB"
                    and words[j - 1] is not None
                    and words[j - 1].idx == k.idx
                    and words[j + 1] is not None
                    and words[j + 1].is_punct
                )
                if k.pos_ in {"ADP", "AUX"} or split_reporting_verb:
                    row[j] += 0.9 * np.exp(-(i - j - 3) / 48.0)

        attention[i, :i + 1] = row / row.sum()

    return "bos_and_persistent_dialogue_anchors", attention


def prog_L1H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict local constituent starts; split-word interiors inherit the
    first piece's left context rather than sending excess mass to BOS."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_constituent_starts", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    first = [None] * len(doc)
    primary = [None] * n
    for i, overlaps in enumerate(alignment):
        if tokens[i] in special:
            continue
        if overlaps:
            primary[i] = overlaps[0]
        for s in overlaps:
            if first[s] is None:
                first[s] = i

    # The left edge of a nominal is usually its determiner or possessor,
    # rather than its lexical head.
    nominal_start = list(range(len(doc)))
    nominal_kind = [""] * len(doc)
    for word in doc:
        candidates = [
            child for child in word.children
            if child.i < word.i
            and (
                child.dep_ in ("det", "poss", "nummod")
                or child.pos_ == "DET"
            )
        ]
        if candidates:
            edge = min(candidates, key=lambda child: child.i)
            nominal_start[word.i] = edge.i
            nominal_kind[word.i] = edge.dep_

    quote_open = None

    for i, token in enumerate(tokens):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        # A diffuse causal fallback leaves room for both a sink and self.
        distance = i - np.arange(i + 1)
        prior = np.exp(-distance / 4.0)
        prior /= prior.sum()
        row = 0.19 * prior
        row[0] += 0.40
        row[i] += 0.25
        row[i - 1] += 0.16

        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        s = primary[i]
        anchor = None
        strength = 0.0
        secondary = None
        secondary_strength = 0.0

        if token in special:
            anchor, strength = 0, 0.80

        elif not clean:
            anchor, strength = i - 1, 0.40

        elif s is not None:
            word = doc[s]
            start = first[s]
            continuation = start is not None and start < i

            if continuation:
                # Split-word interiors are less syntactically selective.
                row *= 0.65
                row[i] += 0.20
                row[start] += 0.15
                if nominal_start[s] != s:
                    anchor = first[nominal_start[s]]
                    strength = 0.18

            elif word.is_punct:
                if any(mark in clean for mark in ('"', "“", "”", "«", "»")):
                    if quote_open is None:
                        quote_open = i
                        anchor, strength = i - 1, 0.18
                    else:
                        anchor, strength = quote_open, 0.38
                        quote_open = None
                elif any(mark in clean for mark in (".", "!", "?")):
                    anchor, strength = i, 0.20
                else:
                    anchor, strength = i - 1, 0.14

            else:
                # Nominals and their prenominal modifiers share an anchor.
                nominal = s
                if word.pos_ in ("ADJ", "NUM") and word.head.i > s:
                    nominal = word.head.i
                elif word.dep_ in ("amod", "compound") and word.head.i > s:
                    nominal = word.head.i

                edge = nominal_start[nominal]
                if edge < s and first[edge] is not None:
                    anchor = first[edge]
                    early = 0.20 * np.exp(-i / 7.0)
                    strength = 0.48 + early
                    if nominal_kind[nominal] == "poss":
                        strength = 0.73 + 0.12 * np.exp(-i / 12.0)
                    intervening = s - edge - 1
                    strength *= np.exp(-0.16 * max(0, intervening))

                # Predicates and preverbal modifiers look toward the
                # subject's left edge, including through auxiliaries.
                predicate = word
                if word.pos_ == "AUX" or word.dep_ in ("aux", "auxpass", "cop"):
                    if word.head != word:
                        predicate = word.head
                elif word.dep_ == "advmod" and word.head.pos_ in ("VERB", "AUX"):
                    predicate = word.head

                if (
                    word.pos_ in ("VERB", "AUX")
                    or word.dep_ == "advmod"
                    or word.pos_ == "ADJ"
                ):
                    subjects = [
                        child for child in predicate.children
                        if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                        and child.i < s
                    ]
                    if subjects:
                        subject = max(subjects, key=lambda child: child.i)
                        edge = nominal_start[subject.i]
                        target = first[edge]
                        if target is not None and target < i:
                            anchor = target
                            strength = 0.46 + 0.35 * np.exp(-i / 6.0)
                            if word.pos_ == "AUX":
                                strength *= 0.82
                            if word.pos_ == "ADJ":
                                strength *= 0.52
                            if subject.pos_ not in ("PRON", "PROPN"):
                                strength *= 0.83
                    elif word.pos_ == "VERB":
                        coordinators = [
                            child for child in word.children
                            if child.dep_ == "cc" and child.i < s
                        ]
                        if coordinators:
                            target = first[coordinators[-1].i]
                            if target is not None:
                                anchor, strength = target, 0.43

                # Short function-word-led spans often have the same
                # left-edge behavior even without a dependency edge.
                if anchor is None and s > 0:
                    previous = doc[s - 1]
                    target = first[s - 1]
                    if target is not None:
                        if previous.pos_ in ("ADP", "SCONJ", "CCONJ"):
                            anchor, strength = target, 0.32
                        elif word.pos_ == "ADP" and previous.pos_ in (
                            "NOUN", "PROPN", "PRON"
                        ):
                            anchor = first[nominal_start[s - 1]]
                            strength = 0.30

                # Commas and sentence boundaries seed the next short span.
                for back in range(s - 1, max(-1, s - 4), -1):
                    boundary = doc[back]
                    if boundary.is_punct and any(
                        mark in boundary.text for mark in (",", ";", ":", "!", "?")
                    ):
                        target = first[back]
                        if target is not None and target < i:
                            if anchor is None or word.pos_ in (
                                "DET", "PRON", "CCONJ", "SCONJ"
                            ):
                                anchor = target
                                strength = 0.47 * np.exp(-0.23 * (s - back - 1))
                            else:
                                secondary = target
                                secondary_strength = 0.10
                        break

        # The initial token has a particularly strong BOS preference.
        if i == 1 and token not in special:
            pos = doc[s].pos_ if s is not None else ""
            strength = (
                0.87 if pos in ("PRON", "DET")
                else 0.58 if pos == "PROPN"
                else 0.50
            )
            anchor = 0
            secondary_strength = 0.0

        if anchor is not None and 0 <= anchor <= i:
            row *= 1.0 - strength
            row[anchor] += strength
        if secondary is not None and 0 <= secondary <= i:
            row *= 1.0 - secondary_strength
            row[secondary] += secondary_strength

        # Targeted exception: a later piece retains the first piece's
        # external context. Redistribute only BOS mass, preserving the
        # original self-attention and all baseline decay parameters.
        if token not in special and clean and s is not None:
            start = first[s]
            if start is not None and 1 < start < i and not doc[s].is_punct:
                context = matrix[start, 1:start].copy()
                context_mass = context.sum()
                if context_mass > 0.0:
                    transfer = 0.80 * row[0]
                    row[0] -= transfer
                    row[1:start] += transfer * context / context_mass

        matrix[i, :i + 1] = row / row.sum()

    return "local_constituent_starts", make_row_stochastic(matrix)


def prog_L1H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS and function-word anchors, with sentence-initial prepositions
    treated as weak keys rather than persistent dominant anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_and_function_word_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            if 0 <= si < len(doc):
                inverse[si].append(ti)

    strength = np.full(n, 0.35, dtype=np.float64)
    persistence = np.full(n, 9.0, dtype=np.float64)
    self_gain = np.full(n, 1.5, dtype=np.float64)

    for j, token in enumerate(tokens):
        if j == 0:
            continue

        clean = token.lstrip("▁Ġ")
        if not clean or clean.isspace():
            strength[j] = 0.10
            continue

        indices = aligned[j]
        if not indices:
            strength[j] = 0.25
            continue

        word = doc[indices[-1]]
        pos = word.pos_
        dep = word.dep_
        tag = word.tag_

        if pos == "PRON":
            strength[j] = 0.035
        elif pos == "DET":
            strength[j] = 0.18
        elif pos in ("NOUN", "PROPN"):
            strength[j] = 0.85
        elif pos == "ADJ":
            strength[j] = 0.38
        elif pos == "ADV":
            strength[j] = 0.30
        elif pos == "VERB":
            strength[j] = 0.65
        elif pos in ("CCONJ", "SCONJ"):
            strength[j] = 0.25
        elif pos == "PUNCT":
            strength[j] = 0.48
            self_gain[j] = 1.8

        if pos == "ADP":
            strength[j] = 7.5
            persistence[j] = 30.0
            self_gain[j] = 1.35
        elif pos == "PART":
            strength[j] = 8.5 if tag == "TO" else 3.8
            persistence[j] = 28.0
            self_gain[j] = 1.35
        elif pos == "AUX":
            strength[j] = 2.5 if tag == "MD" else 4.8
            persistence[j] = 27.0
            self_gain[j] = 1.6
        elif dep == "poss" and tag == "POS":
            strength[j] = 4.5
            persistence[j] = 28.0

        # A completed split word can itself become a persistent key.
        pieces = inverse[word.i]
        lexical_pieces = [
            k for k in pieces
            if k > 0 and any(c.isalpha() for c in tokens[k])
        ]
        if (
            len(lexical_pieces) > 1
            and j == lexical_pieces[-1]
            and any(c.isalpha() for c in clean)
        ):
            strength[j] = max(strength[j], 5.5)
            persistence[j] = max(persistence[j], 30.0)
            self_gain[j] = 1.6
        elif len(lexical_pieces) > 1 and j in lexical_pieces:
            strength[j] *= 0.65

        # Initial prepositions do not acquire the strong medial-ADP anchor.
        # Keep the original decay and self-gain parameters unchanged.
        if word.i == 0 and pos == "ADP":
            strength[j] *= 0.08

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 4.0 * np.exp(-(i - 1) / 28.0)
        for j in range(1, i + 1):
            distance = i - j
            weight = strength[j] * np.exp(-distance / persistence[j])
            if j == i:
                weight *= self_gain[j]
            elif distance == 1:
                weight *= 1.10
            attention[i, j] = weight

    return "bos_and_function_word_anchors", make_row_stochastic(attention)


def prog_L1H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with decaying predicate/preposition anchors and modest self-attention.
    Punctuation boundaries and compatible earlier pronouns provide secondary anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_and_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_ids = [ids[-1] if ids else -1 for ids in alignment]
    representatives = {}
    for i, wi in enumerate(word_ids):
        if wi >= 0:
            representatives[wi] = i

    special = set(tokenizer.all_special_tokens)
    positions = np.arange(n, dtype=np.float64)
    key_strength = np.full(n, 0.12, dtype=np.float64)
    self_strength = np.full(n, 0.45, dtype=np.float64)
    first_predicate = True

    for j in range(1, n):
        wi = word_ids[j]
        if wi < 0:
            if not tokens[j].strip("▁Ġ \t\r\n"):
                key_strength[j] = 0.65
            continue

        word = doc[wi]
        pos = word.pos_
        is_last_piece = representatives[wi] == j

        if pos in ("VERB", "AUX"):
            strength = 3.1 if first_predicate else 1.65
            first_predicate = False
            key_strength[j] = strength
            self_strength[j] = strength
        elif pos in ("ADP", "PART"):
            key_strength[j] = 3.0
            self_strength[j] = 3.0
        elif pos == "PUNCT":
            terminal = any(c in ".?!" for c in word.text)
            key_strength[j] = 1.7 if terminal else 1.35
            self_strength[j] = 2.4 if terminal else 0.8
        elif pos == "PRON" or word.dep_ == "poss":
            key_strength[j] = 0.75
            self_strength[j] = 0.5
        elif pos in ("NOUN", "PROPN"):
            key_strength[j] = 0.28
            self_strength[j] = 0.8
        elif pos == "DET":
            key_strength[j] = 0.25
            self_strength[j] = 0.32
        elif pos in ("ADJ", "ADV"):
            key_strength[j] = 0.2
            self_strength[j] = 0.4

        if not is_last_piece:
            key_strength[j] *= 0.65
            self_strength[j] *= 0.65

    attention[0, 0] = 1.0
    for i in range(1, n):
        distances = i - positions[:i + 1]
        row = 0.07 + 0.09 * np.exp(-distances / 12.0)
        row += key_strength[:i + 1] * np.exp(-distances / 11.0)
        row[i] = self_strength[i]

        wi = word_ids[i]
        word = doc[wi] if wi >= 0 else None

        row[0] = 4.8 * np.exp(-(i - 1) / 5.5) + 0.28
        if i == 1:
            row[0] = 4.0
            if word is not None and word.pos_ in ("ADP", "PART"):
                row[i] = 2.1
            elif word is not None and word.pos_ == "PRON":
                row[i] = 0.92

        if word is not None:
            previous_same_word = i > 1 and word_ids[i - 1] == wi
            if previous_same_word:
                row[0] += 1.1 * np.exp(-i / 24.0)

            head_index = representatives.get(word.head.i, -1)
            if 0 < head_index < i and word.head.i != wi:
                row[head_index] += 0.45 * np.exp(-(i - head_index) / 18.0)

            if word.pos_ == "PRON" or word.dep_ == "poss":
                for j in range(1, i):
                    wj = word_ids[j]
                    if wj < 0 or wj == wi or representatives[wj] != j:
                        continue
                    earlier = doc[wj]
                    if earlier.pos_ != "PRON" and earlier.dep_ != "poss":
                        continue
                    compatible = True
                    evidence = 0
                    for feature in ("Gender", "Number", "Person"):
                        a = word.morph.get(feature)
                        b = earlier.morph.get(feature)
                        if a and b:
                            if not set(a).intersection(b):
                                compatible = False
                                break
                            evidence += 1
                    if compatible and evidence:
                        row[j] += (
                            1.7 * evidence * np.exp(-(i - j) / 35.0)
                        )

        if tokens[i] in special:
            row[i] += 0.5
        attention[i, :i + 1] = row

    return "bos_and_clause_anchors", make_row_stochastic(attention)


def prog_L1H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent phrase anchors dominate ordinary queries; coordinating
    conjunctions instead pool the preceding clause, emphasizing its predicate.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "phrase_anchors_with_coordination_pooling", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    special = set(tokenizer.all_special_tokens)

    for i, indices in enumerate(alignment):
        if tokens[i] not in special:
            for k in indices:
                inverse[k].append(i)

    owners = [None] * n
    for i, indices in enumerate(alignment):
        if tokens[i] not in special and indices:
            owners[i] = max(
                indices,
                key=lambda k: len(doc[k].text) if not doc[k].is_space else -1
            )

    strengths = np.zeros(n, dtype=np.float64)
    for i in range(1, n):
        k = owners[i]
        if k is None:
            continue
        word = doc[k]
        pieces = inverse[k]
        first_piece = bool(pieces) and i == pieces[0]
        last_piece = bool(pieces) and i == pieces[-1]

        if first_piece:
            if word.pos_ == "ADP":
                strengths[i] = 7.5 if i > 1 else 0.25
            elif word.pos_ == "PART" and word.dep_ in ("aux", "mark"):
                strengths[i] = 7.8
            elif word.pos_ == "AUX":
                strengths[i] = 2.4
            elif word.pos_ == "SCONJ":
                strengths[i] = 1.8
            elif word.dep_ == "case":
                strengths[i] = 5.0

        if last_piece and len(pieces) > 1 and not word.is_punct:
            visible = tokens[i].lstrip("▁Ġ")
            suffix_strength = 5.5 if len(visible) <= 3 else 2.5
            strengths[i] = max(strengths[i], suffix_strength)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(i + 1)
        distance = i - positions

        # Diffuse causal background and a modest diagonal component.
        row = 0.13 + 0.10 * np.exp(-distance / 5.0)
        row[i] += 0.55

        # The initial sink is gradually diluted by newly available keys.
        row[0] = 1.5 + 8.0 * np.exp(-i / 7.0)
        row += strengths[:i + 1] * np.exp(-distance / 32.0)

        k = owners[i]
        if k is not None:
            word = doc[k]

            # Give the opening preposition a little extra weight throughout
            # its complement, without requiring future tokens to be visible.
            head = word
            for _ in range(3):
                if head.head.i == head.i:
                    break
                head = head.head
                if head.pos_ == "ADP":
                    candidates = inverse[head.i]
                    if candidates and 0 < candidates[0] <= i:
                        row[candidates[0]] += 0.9
                    break

            if word.is_punct:
                if "," in word.text or ";" in word.text or ":" in word.text:
                    candidates = []
                    for j in range(1, i):
                        owner = owners[j]
                        if owner is None:
                            continue
                        previous = doc[owner]
                        if previous.pos_ in ("ADP", "VERB", "SCONJ", "CCONJ"):
                            candidates.append(j)
                        elif previous.pos_ == "ADV" and previous.dep_ == "advmod":
                            candidates.append(j)
                    if candidates:
                        row[candidates[-1]] += 5.0
                    row[i] += 2.6
                    row[0] *= 0.65
                else:
                    row[i] += 0.7

            # Coordination is a clause-summary query, not another anchor
            # query. Redistribute only off-diagonal mass, preserving both
            # the original row total and its normalized self-attention.
            if (
                i > 1
                and word.pos_ == "CCONJ"
                and word.dep_ == "cc"
                and inverse[k]
                and i == inverse[k][0]
            ):
                pool = np.zeros(i, dtype=np.float64)
                for j in range(i - 1, 0, -1):
                    owner = owners[j]
                    if owner is None:
                        continue
                    previous = doc[owner]
                    if previous.is_punct and any(
                        mark in previous.text for mark in ",;:.!?"
                    ):
                        break
                    if previous.is_space or previous.is_punct:
                        continue
                    weight = (
                        3.0 if previous.pos_ in ("VERB", "AUX")
                        else 0.5 if previous.pos_ == "ADP"
                        else 1.0
                    )
                    pool[j] = weight / max(1, len(inverse[owner]))
                if pool.sum() > 0:
                    mass = row[:i].sum()
                    row[:i] = (
                        0.15 * row[:i]
                        + 0.85 * mass * pool / pool.sum()
                    )

        if i == 1:
            initial_mass = 0.98
            if k is not None:
                if doc[k].pos_ == "PRON":
                    initial_mass = 0.997
                elif doc[k].pos_ == "ADP":
                    initial_mass = 0.88
                elif doc[k].pos_ == "PROPN":
                    initial_mass = 0.92
            row[0] = initial_mass
            row[1] = 1.0 - initial_mass

        matrix[i, :i + 1] = row / row.sum()

    return "phrase_anchors_with_coordination_pooling", matrix


def prog_L1H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS, subject, and preposition anchors, with persistent clause-punctuation
    landmarks in quoted speech.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_subject_preposition_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_pieces = [[] for _ in doc]
    primary = [None] * n

    for i, indices in enumerate(alignment):
        if tokens[i] in tokenizer.all_special_tokens:
            continue
        if indices:
            primary[i] = indices[0]
        for k in indices:
            if 0 <= k < len(doc):
                word_pieces[k].append(i)

    anchor = np.full(n, 0.12, dtype=np.float64)
    preposition = np.zeros(n, dtype=bool)

    for i in range(1, n):
        k = primary[i]
        if k is None:
            anchor[i] = 0.04
            continue

        word = doc[k]
        pieces = word_pieces[k]
        last_piece = bool(pieces) and i == pieces[-1]
        finite = word.tag_ in ("VBD", "VBP", "VBZ", "MD")
        is_prep = word.pos_ == "ADP" or (
            word.pos_ == "PART" and word.tag_ == "TO"
        )

        if is_prep and last_piece:
            preposition[i] = True
            anchor[i] = 2.7
        elif finite and last_piece:
            anchor[i] = 0.65
        elif (
            last_piece
            and len(pieces) > 1
            and word.pos_ in ("NOUN", "PROPN", "VERB", "AUX")
        ):
            anchor[i] = 1.8
        elif word.is_punct:
            anchor[i] = 0.09

    attention[0, 0] = 1.0

    for i in range(1, n):
        row = attention[i]
        row[0] = 4.8 * np.exp(-i / 15.0) + 0.22

        for j in range(1, i + 1):
            distance = i - j
            row[j] = anchor[j] * (
                0.35 + 0.65 * np.exp(-distance / 13.0)
            )

        row[i] += 0.08 if i == 1 else 0.22
        k = primary[i]
        if k is None:
            continue

        word = doc[k]
        pieces = word_pieces[k]
        last_piece = bool(pieces) and i == pieces[-1]

        if word.pos_ in ("NOUN", "PROPN", "ADJ") and i > 1:
            row[i] += 0.33
        if word.pos_ == "PRON":
            row[0] *= 1.25
        if word.is_punct:
            row[0] *= 1.10

        if preposition[i]:
            row[i] += 3.0 * np.exp(-i / 65.0)

        # Phrase members favor the preposition introducing their phrase.
        ancestor = word
        for _ in range(4):
            if ancestor.pos_ == "ADP":
                candidates = [
                    j for j in word_pieces[ancestor.i] if 0 < j <= i
                ]
                if candidates:
                    j = candidates[-1]
                    if j != i:
                        row[j] += 1.8 * np.exp(-(i - j) / 16.0)
                break
            if ancestor.head.i == ancestor.i:
                break
            ancestor = ancestor.head

        finite = word.tag_ in ("VBD", "VBP", "VBZ", "MD")
        if word.pos_ in ("VERB", "AUX") and finite:
            governor = word.head if word.dep_ in (
                "aux", "auxpass", "cop"
            ) else word

            subjects = [
                child for child in governor.children
                if child.dep_ in ("nsubj", "nsubjpass", "csubj", "expl")
            ]
            if not subjects and governor.i != word.i:
                subjects = [
                    child for child in word.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj", "expl")
                ]

            for subject in subjects:
                available = [
                    j for j in word_pieces[subject.i] if 0 < j < i
                ]
                if not available:
                    continue

                j = available[-1]
                proximity = np.exp(-max(0, i - j - 1) / 5.0)
                auxiliary = word.pos_ == "AUX"
                if subject.pos_ in ("PRON", "DET"):
                    strength = 42.0 if auxiliary else 6.0
                    row[j] += strength * proximity
                else:
                    row[j] += (6.0 if auxiliary else 3.6) * proximity
                    determiners = [
                        child for child in subject.children
                        if child.dep_ == "det"
                    ]
                    for determiner in determiners:
                        positions = [
                            p for p in word_pieces[determiner.i]
                            if 0 < p < i
                        ]
                        if positions:
                            row[positions[0]] += (
                                9.0 if auxiliary else 4.0
                            ) * proximity

        # Infinitival markers remain salient at their following predicate.
        if word.pos_ == "VERB":
            for child in word.children:
                if child.tag_ == "TO":
                    positions = [
                        j for j in word_pieces[child.i] if 0 < j <= i
                    ]
                    if positions:
                        row[positions[-1]] += 2.6

        # Possessive clitics point back to the possessor, not the apostrophe.
        if word.dep_ == "case" and last_piece:
            positions = [
                j for j in word_pieces[word.head.i] if 0 < j < i
            ]
            if positions:
                row[positions[-1]] += 5.5

    # Dialogue retains clause separators as cross-clause landmarks.
    # Add only backward edges; the original diagonal weights are untouched.
    if any(mark in sentence for mark in ('"', '“', '”', '„', '«', '»')):
        boundaries = set()
        for word in doc:
            if word.is_punct and any(mark in word.text for mark in ",;:!?"):
                positions = [j for j in word_pieces[word.i] if j > 0]
                if positions:
                    boundaries.add(positions[0])

        for j in boundaries:
            for i in range(j + 1, n):
                attention[i, j] += 1.8 * np.exp(-(i - j - 1) / 24.0)

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "bos_subject_preposition_dialogue_anchors", attention


def prog_L1H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors, with internal sentence endings and following
    sentence-initial determiners acting as additional anchors in dialogue.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    matrix = np.zeros((n, n), dtype=np.float64)

    special = set(tokenizer.all_special_tokens)
    pos = [""] * n
    dep = [""] * n
    starts_word = [False] * n
    seen = set()

    for j, indices in enumerate(alignment):
        if tokens[j] in special or not indices:
            continue
        k = indices[0]
        pos[j] = doc[k].pos_
        dep[j] = doc[k].dep_
        starts_word[j] = k not in seen
        seen.update(indices)

    clean = [t.replace("▁", "").replace("Ġ", "").strip() for t in tokens]
    commas = ["," in t or ";" in t or ":" in t for t in clean]
    terminals = [any(c in t for c in ".!?") for t in clean]
    quotes = [any(c in t for c in "\"“”«»") for t in clean]

    first = 0
    while first < n and tokens[first] in special:
        first += 1

    strength = np.full(n, 0.24, dtype=np.float64)
    for j in range(n):
        if starts_word[j]:
            if pos[j] == "DET":
                strength[j] = 1.05
            elif pos[j] == "ADP":
                strength[j] = 0.90
            elif pos[j] == "CCONJ":
                strength[j] = 1.35
            elif pos[j] == "SCONJ":
                strength[j] = 0.85
            elif pos[j] == "AUX":
                strength[j] = 0.80
            elif pos[j] == "VERB":
                strength[j] = 0.52
            elif pos[j] == "PRON":
                strength[j] = 0.38

            if dep[j] in ("mark", "cc", "prep"):
                strength[j] *= 1.10

        if j == first:
            if pos[j] == "DET":
                strength[j] = 1.725
            elif pos[j] == "PRON":
                strength[j] = 0.85
            elif pos[j] in ("ADP", "SCONJ"):
                strength[j] = 1.15
            else:
                strength[j] = 0.60

        if commas[j]:
            strength[j] = 2.85
        elif terminals[j]:
            strength[j] = 0.85
        elif quotes[j]:
            strength[j] = 0.65

    for i in range(n):
        for j in range(i + 1):
            distance = i - j
            if tokens[j] in special:
                weight = (0.12 + 0.88 * np.exp(-i / 10.0)) if j == 0 else 0.08
            else:
                decay = 36.0 if commas[j] or j == first else 23.0
                weight = strength[j] * np.exp(-distance / decay)
                weight *= (1.0 + max(0, j - first) / 24.0) ** -0.30

                if j == first and pos[j] == "DET":
                    if pos[i] in ("AUX", "VERB", "ADJ"):
                        weight *= 1.22

                if j == i and i != first:
                    weight += 0.22 if starts_word[i] else 0.10
                    if pos[i] == "VERB":
                        weight += 0.35
                    if terminals[i]:
                        weight += 0.65

                weight += 0.04 * np.exp(-distance / 4.0)

            matrix[i, j] = weight

        if quotes[i] and terminals[i]:
            for j in range(i - 1, -1, -1):
                if quotes[j] and not terminals[j]:
                    matrix[i, j] += 1.1
                    break

    # Only internal sentence boundaries activate this path. Keep the original
    # diagonal weights and decay rates; adjust subsequent anchor competition.
    boundaries = []
    sentence_starts = set()
    for j in range(n):
        if not terminals[j] or clean[j].strip(".!?\"“”«»'’"):
            continue
        for k in range(j + 1, n):
            if starts_word[k] and pos[k] not in ("", "PUNCT", "SPACE", "SYM", "X"):
                boundaries.append(j)
                if pos[k] == "DET":
                    sentence_starts.add(k)
                break

    if boundaries:
        boundary_set = set(boundaries)
        for i in range(n):
            for j in range(i):
                if j in boundary_set:
                    matrix[i, j] *= 3.4
                elif j in sentence_starts:
                    matrix[i, j] *= 3.5
                elif commas[j] and j > boundaries[0]:
                    matrix[i, j] *= 0.60

    return "persistent_anchors_with_internal_sentence_boundaries", make_row_stochastic(matrix)


def prog_L1H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-attention with persistent boundary anchors; in comma-rich dialogue,
    later commas compete less strongly with the initial boundary.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_with_dialogue_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    special_tokens = set(tokenizer.all_special_tokens)
    punctuation = []
    for i, token in enumerate(tokens):
        word = words[i]
        if word is not None and word.is_punct:
            punctuation.append(word.text)
        else:
            clean = token.replace("▁", "").replace("Ġ", "").strip()
            punctuation.append(clean if clean and all(
                not c.isalnum() for c in clean
            ) else "")

    # Restrict the correction to quoted discourse with repeated comma boundaries.
    comma_indices = [j for j in range(1, n) if punctuation[j] == ","]
    dialogue_boundaries = (
        len(comma_indices) >= 3
        and any(
            any(mark in p for mark in ('"', "“", "”", "«", "»"))
            for p in punctuation
        )
    )

    attention[0, 0] = 1.0

    for i in range(1, n):
        current = words[i]
        pos = current.pos_ if current is not None else ""
        dep = current.dep_ if current is not None else ""

        # The first lexical token is almost entirely diagonal.
        if i == 1:
            diagonal = 0.966 if pos == "DET" else 0.978
            attention[i, 0] = 1.0 - diagonal
            attention[i, i] = diagonal
            continue

        diagonal_prior = 0.27 + 0.73 * np.exp(-(i - 1) / 3.3)
        self_weight = 1.0
        if pos in ("PROPN", "VERB"):
            self_weight *= 1.18
        elif pos == "NOUN":
            self_weight *= 1.10
        elif pos in ("PRON", "DET", "ADP", "PART"):
            self_weight *= 0.88
        if punctuation[i] == ",":
            self_weight *= 1.10
        elif punctuation[i]:
            self_weight *= 0.75

        # Diffuse causal background, with no privileged BOS sink.
        distances = i - np.arange(i, dtype=np.float64)
        background = 0.25 + np.exp(-distances / 22.0)
        for j in range(i):
            if tokens[j] in special_tokens:
                background[j] *= 0.12
        background /= background.sum()
        attention[i, :i] = background * (1.0 / diagonal_prior - 1.0)
        attention[i, i] = self_weight

        # Commas act as durable boundary keys, especially early in a sequence.
        for j in range(1, i):
            if punctuation[j] != ",":
                continue
            distance = i - j
            strength = 1.15 * np.exp(-(distance - 1) / 19.0)
            if j <= 5:
                strength *= 2.0
            intervening = sum(
                punctuation[k] == "," for k in range(j + 1, i)
            )
            strength *= 0.42 ** intervening
            if distance == 1 and punctuation[i]:
                strength *= 1.35

            # Repeated dialogue commas are weaker anchors, not repeated resets.
            # Preserve the initial boundary through intervening dialogue commas.
            if dialogue_boundaries:
                if j == comma_indices[0]:
                    strength *= (0.80 / 0.42) ** intervening
                else:
                    strength *= 0.30

            attention[i, j] += strength

        # Local grammatical keys explain the non-comma off-diagonal stripes.
        for j in range(max(1, i - 5), i):
            previous = words[j]
            if previous is None or current is None:
                continue
            if previous.i == current.i:
                continue
            if any(punctuation[k] == "," for k in range(j + 1, i)):
                continue

            distance = i - j
            strength = 0.0

            if previous.pos_ == "DET" and distance <= 3:
                same_phrase = (
                    previous.head.i == current.i
                    or previous.head.i == current.head.i
                )
                if same_phrase and pos in ("NOUN", "PROPN", "ADJ"):
                    strength += 0.95 * np.exp(-(distance - 1) / 2.0)

            if previous.pos_ in ("AUX", "VERB") and distance <= 2:
                linked = (
                    current.head.i == previous.i
                    or previous.head.i == current.i
                    or previous.head.i == current.head.i
                )
                if linked and (
                    pos in ("ADV", "ADJ")
                    or dep in ("advmod", "acomp", "attr")
                ):
                    strength += 1.05 * np.exp(-(distance - 1) / 1.7)

            if previous.pos_ == "CCONJ":
                strength += 1.15 * np.exp(-(distance - 1) / 3.0)

            # Split anchor words should not receive the same bonus repeatedly.
            if j > 0 and words[j - 1] is not None:
                if words[j - 1].i == previous.i:
                    strength *= 0.25

            attention[i, j] += strength

    return "self_with_dialogue_boundary_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L1H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent early-boundary anchors, with punctuation-anchor refresh
    across internal sentence breaks and repeated comma boundaries."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_boundary_refresh", matrix

    special = set(tokenizer.all_special_tokens)
    word_ids = []
    first_piece = {}
    for i, ids in enumerate(aligned):
        valid = [k for k in ids if k < len(doc)]
        sid = valid[0] if valid else -1
        if tokens[i] in special:
            sid = -1
        word_ids.append(sid)
        if sid >= 0 and sid not in first_piece:
            first_piece[sid] = i

    anchors = np.zeros(n, dtype=np.float64)
    kinds = [""] * n
    first_content = next(
        (i for i in range(n) if word_ids[i] >= 0), 1
    )
    comma_seen = False
    initial_det = -1

    for i in range(n):
        if i == 0:
            matrix[0, 0] = 1.0
            continue

        sid = word_ids[i]
        word = doc[sid] if sid >= 0 else None
        is_start = word is not None and first_piece[sid] == i
        kind = ""
        strength = 0.0

        if is_start:
            pos = word.pos_
            dep = word.dep_
            early = np.exp(-0.105 * max(0, i - first_content - 3))

            if word.is_punct and "," in word.text:
                kind = "comma"
                strength = 9.0 * early
            elif pos == "CCONJ":
                kind = "conjunction"
                strength = 5.5 * early
            elif pos == "SCONJ" or dep == "mark":
                kind = "clause"
                strength = 5.0 * early
            elif pos == "DET" and dep != "poss":
                kind = "determiner"
                strength = (8.0 if i == first_content else 3.8) * early
                if i == first_content:
                    initial_det = i
            elif pos == "ADP":
                kind = "preposition"
                strength = 3.5 * early
            elif pos == "AUX":
                kind = "auxiliary"
                strength = 3.7 * early
                if initial_det >= 0 and not comma_seen:
                    strength *= 0.72
            elif pos == "VERB":
                kind = "verb"
                strength = 1.7 * early
            elif i == first_content:
                kind = "initial"
                if pos == "PRON":
                    strength = 2.2 if dep != "poss" else 0.9
                elif pos == "PROPN" or pos == "NUM":
                    strength = 0.12
                else:
                    strength = 0.8
            elif pos in ("NOUN", "ADV") and dep in (
                "npadvmod", "advmod", "obl:tmod"
            ) and i <= first_content + 2:
                kind = "temporal"
                strength = 1.7

            if strength > 0:
                if not comma_seen:
                    if kind == "comma":
                        anchors[:i] *= 0.68
                    elif kind in ("conjunction", "clause"):
                        anchors[:i] *= 0.58
                    elif kind in ("determiner", "preposition"):
                        anchors[:i] *= 0.80
                    elif kind == "auxiliary" and initial_det < 0:
                        anchors[:i] *= 0.62
                else:
                    # Once a comma has formed a sink, later boundaries are
                    # competitors rather than wholesale attention resets.
                    strength *= 0.30 if kind != "comma" else 0.48

                    # Repeated commas renew the boundary signal instead of
                    # vanishing solely because they occur late in the passage.
                    if kind == "comma":
                        strength = max(strength, 1.8)
                        for j in range(i):
                            if kinds[j] == "comma":
                                anchors[j] *= 0.75

                anchors[i] = strength
                kinds[i] = kind
                if kind == "comma":
                    comma_seen = True

            # An internal sentence ending weakens old comma sinks. Defer
            # this adjustment until the next row, preserving this row.
            internal_end = (
                comma_seen
                and word.is_punct
                and any(c in word.text for c in ".!?")
                and any(
                    not w.is_punct and not w.is_space
                    for w in doc[sid + 1:]
                )
            )
        else:
            internal_end = False

        weights = np.zeros(i + 1, dtype=np.float64)
        distances = i - np.arange(i + 1)
        weights[:] = 0.025 + 0.08 * np.exp(-distances / 3.0)
        weights[0] += 0.80 if i == first_content else 0.42
        weights[i] += 0.28
        if i > 0:
            weights[i - 1] += 0.12

        for j in range(i + 1):
            if anchors[j] <= 0:
                continue

            distance = i - j
            persistence = (1.0 + distance / 18.0) ** -0.30
            gain = 1.0

            if kinds[j] == "determiner" and distance > 0:
                gain = 1.30 if distance <= 4 else 1.0
            elif kinds[j] == "comma" and distance > 0:
                gain = 1.30 if distance <= 3 else 1.0
            elif kinds[j] in ("preposition", "clause") and 0 < distance <= 3:
                gain = 1.18

            # Split word pieces retain the boundary preference of the word.
            if sid >= 0 and word_ids[j] == sid and j < i:
                gain *= 0.85

            weights[j] += anchors[j] * persistence * gain

        matrix[i, :i + 1] = weights

        if internal_end:
            for j in range(i):
                if kinds[j] == "comma":
                    anchors[j] *= 0.45

    return (
        "persistent_boundary_refresh",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L1H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-anchor head with additional persistent clause-marker anchors
    and determiner anchors inside an initial comma-delimited phrase.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_and_function_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    features = []
    for indices in alignment:
        features.append(doc[indices[0]] if indices else None)

    bos = tokens[0] in special
    start = 1 if bos else 0

    # A determiner in the opening comma-delimited phrase can remain an
    # anchor alongside the comma. Use only that phrase's first determiner.
    opening_determiner = None
    for j in range(start, n):
        if "," in tokens[j]:
            break
        source = features[j]
        if (
            opening_determiner is None
            and source is not None
            and source.pos_ == "DET"
            and source.dep_ == "det"
        ):
            opening_determiner = source.i
    else:
        opening_determiner = None

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        for j in range(i + 1):
            distance = i - j
            weight = 0.85 + 0.55 * np.exp(-distance / 5.0)
            source = features[j]
            query = features[i]

            if bos and j == 0:
                weight = 0.18 + 3.7 * np.exp(-0.62 * (i - 2))
            else:
                if j == i:
                    weight += 1.3
                elif j == i - 1:
                    weight += 0.9

                # Delimiters retain salience well beyond their immediate clause.
                if "," in tokens[j]:
                    weight += 6.5 * np.exp(-0.025 * (j - start))

                if source is not None:
                    # Treat a split word's first piece as its linguistic anchor.
                    first_piece = (
                        j == start
                        or not alignment[j - 1]
                        or alignment[j - 1][0] != source.i
                    )
                    if first_piece:
                        if source.pos_ == "CCONJ":
                            weight += 3.8 * np.exp(-0.035 * (j - start))
                        elif source.pos_ == "AUX":
                            weight += 1.1 * np.exp(-distance / 10.0)

                        if source.dep_ in ("amod", "advmod"):
                            weight += 1.1 * np.exp(-distance / 4.0)

                        if (
                            query is not None
                            and j < i
                            and distance <= 5
                            and source.i != query.i
                        ):
                            if source.head.i == query.i and source.dep_ in (
                                "amod", "advmod", "det", "compound"
                            ):
                                weight += 0.9 * np.exp(-distance / 4.0)
                            elif query.head.i == source.i:
                                weight += 0.35 * np.exp(-distance / 4.0)

                        # Add only missed historical anchors; leave all
                        # original self-attention and decay terms intact.
                        if j < i:
                            if (
                                source.dep_ in ("mark", "aux")
                                and source.pos_ in ("PART", "SCONJ")
                            ):
                                weight += 1.8
                            if (
                                source.i == opening_determiner
                                and distance >= 2
                            ):
                                weight += 2.4

            attention[i, j] = weight

        # With just one lexical token, the initial sink dominates strongly.
        if bos and i == start:
            source = features[i]
            pos = source.pos_ if source is not None else ""
            sink_probability = 0.73
            if pos == "PRON":
                sink_probability = 0.88
            elif pos == "DET":
                sink_probability = 0.81
            elif pos == "ADP":
                sink_probability = 0.78
            elif pos == "PROPN":
                sink_probability = 0.71
            attention[i, :] = 0.0
            attention[i, 0] = sink_probability
            attention[i, i] = 1.0 - sink_probability

    return "boundary_and_function_anchors", make_row_stochastic(attention)


def prog_L1H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Quoted discourse spreads comma-anchor attention over clause context,
    especially conjunctions, rather than retaining a dominant comma sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_left_boundary_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    word_ids = []
    for token, indices in zip(tokens, aligned):
        candidates = [k for k in indices if not doc[k].is_space]
        word_ids.append(candidates[0] if candidates and token not in special else None)

    first_piece = {}
    for i, wid in enumerate(word_ids):
        if wid is not None and wid not in first_piece:
            first_piece[wid] = i

    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
    comma_positions = []
    anchors = []
    first_content = None

    # Restrict the correction to quoted or expressive comma-bearing discourse.
    # Exclamation/question marks also cover incorrectly decoded quotation marks.
    dialogue = (
        any("," in t for t in clean)
        and any(any(ch in t for ch in '"“”!?') for t in clean)
    )

    anchor_strength = {
        "DET": 1.45,
        "ADP": 1.00,
        "AUX": 1.15,
        "CCONJ": 1.10,
        "SCONJ": 0.95,
    }

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        wid = word_ids[i]
        word = doc[wid] if wid is not None else None
        pos = word.pos_ if word is not None else ""
        is_start = wid is not None and first_piece[wid] == i
        is_special = tokens[i] in special
        is_punctuation = bool(clean[i]) and all(
            not ch.isalnum() for ch in clean[i]
        )

        if first_content is None and not is_special and clean[i]:
            first_content = i

        if i == first_content and i == 1:
            self_mass = {
                "DET": 0.83,
                "PRON": 0.79,
                "PROPN": 0.64,
                "NUM": 0.57,
                "ADP": 0.76,
                "ADV": 0.73,
            }.get(pos, 0.68)
            attention[i, 0] = 1.0 - self_mass
            attention[i, i] = self_mass
        else:
            distances = i - np.arange(i + 1)
            row = 0.035 + 0.035 * np.exp(-distances / 7.0)
            row[0] += 0.22 * np.exp(-i / 8.0) + 0.025

            row[i] += 0.62
            row[i - 1] += 0.42

            if is_start and pos in ("VERB", "AUX", "DET", "ADP", "PROPN"):
                row[i] += 0.40
            if not is_start and word is not None:
                row[i] *= 0.70

            has_comma = bool(comma_positions)
            phrase_scale = 0.48 if has_comma else 1.0

            if first_content is not None and first_content < i:
                first_wid = word_ids[first_content]
                first_pos = doc[first_wid].pos_ if first_wid is not None else ""
                strength = 1.15 if first_pos in ("DET", "PRON", "ADP") else 0.50
                row[first_content] += (
                    phrase_scale * strength
                    * np.exp(-(i - first_content - 1) / 8.0)
                )

            for j, anchor_pos, strength in anchors:
                distance = i - j
                if distance <= 12:
                    decay = np.exp(-(distance - 1) / 3.8)
                    compatibility = 1.0
                    if anchor_pos == "DET" and pos in ("NOUN", "PROPN", "ADJ"):
                        compatibility = 1.30
                    elif anchor_pos == "AUX" and pos in ("ADJ", "ADV", "VERB"):
                        compatibility = 1.20
                    row[j] += phrase_scale * strength * decay * compatibility

            for rank, j in enumerate(comma_positions):
                comma_mass = (
                    2.65 * np.exp(-(i - j - 1) / 32.0)
                    / ((rank + 1) ** 0.65)
                )
                row[j] += comma_mass

                if dialogue:
                    crossed_terminal = any(
                        any(ch in clean[k] for ch in ".!?")
                        for k in range(j + 1, i + 1)
                    )
                    retained = 0.20 if crossed_terminal else 0.55

                    # Redistribute only the comma bonus. Keeping its total mass
                    # preserves the original normalized self-attention exactly.
                    context = np.zeros(i, dtype=np.float64)
                    for k in range(max(1, i - 4), i):
                        if k != j and tokens[k] not in special:
                            context[k] += 0.40 / (i - k)

                    for k, anchor_pos, _ in anchors:
                        if anchor_pos == "CCONJ" and k != j:
                            context[k] += 0.90 * np.exp(-(i - k) / 32.0)

                    for k in range(max(1, i - 16), i):
                        if k != j and tokens[k] not in special:
                            context[k] += 0.025

                    context_sum = context.sum()
                    if context_sum > 0:
                        moved_mass = comma_mass * (1.0 - retained)
                        row[j] -= moved_mass
                        row[:i] += moved_mass * context / context_sum

            if is_punctuation:
                row[i] += 0.24
                row[i - 1] += 0.25
                if clean[i] in ("'", "’"):
                    row[i - 1] += 0.55
            elif not clean[i]:
                row[i - 1] += 0.70

            attention[i, :i + 1] = row / row.sum()

        if "," in clean[i] and is_punctuation:
            comma_positions.append(i)

        if is_start and pos in anchor_strength:
            anchors.append((i, pos, anchor_strength[pos]))

    return "persistent_left_boundary_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L1H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early boundary anchors, with distributed phrase and quotation anchors
    in dialogue rather than an overly dominant initial token and comma.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_boundary_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    positions = []
    dependencies = []
    word_starts = []
    punctuation = []
    previous_word = None

    for j, token in enumerate(tokens):
        matches = alignment[j]
        word_index = matches[0] if matches else None
        word = doc[word_index] if word_index is not None else None
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()

        positions.append(word.pos_ if word is not None else "")
        dependencies.append(word.dep_ if word is not None else "")
        punctuation.append(
            clean if clean and all(c in ",;:.!?—–-()[]{}\"'“”‘’" for c in clean)
            else ""
        )
        word_starts.append(
            token not in special_tokens
            and bool(clean)
            and (word_index is None or word_index != previous_word)
        )
        if word_index is not None:
            previous_word = word_index

    content_indices = [
        j for j in range(n)
        if tokens[j] not in special_tokens
        and bool(tokens[j].replace("▁", " ").replace("Ġ", " ").strip())
    ]
    first = content_indices[0] if content_indices else 0

    # Restrict the correction to quoted speech or internal exclamations/questions.
    # The latter also catches dialogue with corrupted quotation characters.
    dialogue = (
        any(c in sentence for c in "\"“”«»")
        or any(
            any(c in punctuation[j] for c in "!?")
            and any(
                word_starts[k] and positions[k] not in ("", "PUNCT", "SPACE")
                for k in range(j + 1, n)
            )
            for j in range(n)
        )
    )

    strength = np.zeros(n, dtype=np.float64)
    for j in range(n):
        if tokens[j] in special_tokens:
            continue

        pos = positions[j]
        dep = dependencies[j]
        punc = punctuation[j]

        if "," in punc:
            strength[j] = 5.0
        elif ";" in punc or ":" in punc:
            strength[j] = 2.3
        elif any(c in punc for c in ".!?"):
            strength[j] = 0.75
        elif word_starts[j]:
            if pos == "DET":
                strength[j] = 1.35
            elif pos == "ADP":
                strength[j] = 1.35
            elif pos in ("CCONJ", "SCONJ"):
                strength[j] = 1.60
            elif pos == "AUX":
                strength[j] = 1.25
            elif dep in ("poss", "mark", "case"):
                strength[j] = 1.05
            else:
                strength[j] = 0.12

        if j == first:
            strength[j] = 2.45 if pos == "DET" else 1.05

        # Dialogue distributes anchor mass across clause and quotation boundaries.
        # Leave the original decay and query-side self-attention rules untouched.
        if dialogue:
            clean = tokens[j].replace("▁", " ").replace("Ġ", " ").strip()
            if j == first:
                strength[j] *= 0.65
            elif "," in punc:
                strength[j] *= 0.55
            elif any(c in punc for c in ".!?"):
                strength[j] = 2.5
            elif any(c in punc for c in "\"“”"):
                strength[j] = 1.0
            elif not clean:
                strength[j] = 0.85
            elif word_starts[j] and pos == "CCONJ":
                strength[j] *= 1.55
            elif word_starts[j] and pos == "VERB":
                strength[j] = max(strength[j], 0.65)
            elif word_starts[j] and pos in ("NOUN", "PROPN") and j < first + 4:
                strength[j] = max(strength[j], 0.45)
            elif not word_starts[j] and pos in ("NOUN", "PROPN", "VERB"):
                if j + 1 == n or not (
                    alignment[j] and alignment[j + 1]
                    and alignment[j][0] == alignment[j + 1][0]
                ):
                    strength[j] = max(strength[j], 0.65)

        strength[j] *= np.exp(-0.065 * max(0, j - first))

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        if i == first and first > 0:
            self_mass = (
                0.69 if positions[i] == "DET"
                else 0.645 if positions[i] == "PRON"
                else 0.60
            )
            matrix[i, 0] = 1.0 - self_mass
            matrix[i, i] = self_mass
            continue

        js = np.arange(i + 1)
        distances = i - js

        # A diffuse causal floor prevents old anchors from remaining exclusive.
        row = 0.018 + 0.025 * np.exp(-distances / 8.0)
        row += strength[:i + 1] * np.exp(-distances / 42.0)
        row[0] += 0.57 * np.exp(-i / 32.0)

        if i != first:
            self_weight = 0.55
            if positions[i] == "AUX":
                self_weight = 0.25
            elif positions[i] in ("VERB", "NOUN", "PROPN"):
                self_weight = 0.68
            elif punctuation[i]:
                self_weight = 0.12

            # Subword continuations inherit the phrase anchor, not a new one.
            if not word_starts[i] and not punctuation[i]:
                self_weight *= 0.45
            row[i] += self_weight * np.exp(-i / 18.0)

        if i > 0:
            row[i - 1] += 0.10 * np.exp(-i / 24.0)

        matrix[i, :i + 1] = row

    return "early_boundary_anchors", make_row_stochastic(matrix)


def prog_L1H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary anchors with weak decay; quoted-dialogue restarts additionally
    anchor on standalone whitespace and opening quotation marks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_anchors_with_dialogue_restarts", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = np.array([t in tokenizer.all_special_tokens for t in tokens])
    positions = np.arange(n)
    pos_tags = [""] * n
    dep_tags = [""] * n
    word_ids = [-1] * n
    punctuation = np.zeros(n, dtype=bool)
    quotes = np.zeros(n, dtype=bool)
    strengths = np.full(n, 0.65, dtype=np.float64)

    first = -1
    for j, token in enumerate(tokens):
        if special[j]:
            strengths[j] = 0.85
            continue

        clean = token.lstrip("▁Ġ")
        quotes[j] = bool(clean) and all(c in "\"'“”‘’«»" for c in clean)
        punctuation[j] = any(c in ",.;:!?" for c in clean)

        for k in alignment[j]:
            if not doc[k].is_space:
                word_ids[j] = k
                pos_tags[j] = doc[k].pos_
                dep_tags[j] = doc[k].dep_
                if not doc[k].is_punct:
                    break

        if first < 0 and clean and not quotes[j] and not punctuation[j]:
            first = j

        p = pos_tags[j]
        if p == "DET":
            strengths[j] = 1.75
        elif p == "CCONJ":
            strengths[j] = 2.15
        elif p == "SCONJ":
            strengths[j] = 1.35
        elif p == "AUX":
            strengths[j] = 1.40
        elif p == "VERB":
            strengths[j] = 1.05
        elif p == "ADP":
            strengths[j] = 0.95
        elif p == "PRON":
            strengths[j] = 0.85

        if dep_tags[j] == "poss":
            strengths[j] = max(strengths[j], 1.10)

        # Subword fragments should not each become a fresh syntactic anchor.
        if j > 0 and word_ids[j] >= 0 and word_ids[j] == word_ids[j - 1]:
            strengths[j] *= 0.65

        if quotes[j]:
            strengths[j] = 1.65
        if punctuation[j]:
            strengths[j] = 3.35

    if first >= 0:
        p = pos_tags[first]
        if p == "DET":
            strengths[first] = 2.23
        elif p == "ADP":
            strengths[first] = 1.60
        elif p == "PROPN":
            strengths[first] = 1.23
        else:
            strengths[first] = 1.08

    # Standalone whitespace after a completed quotation marks a dialogue restart.
    restart = np.zeros(n, dtype=bool)
    for j in range(1, n):
        if special[j] or tokens[j].strip("▁Ġ \t\r\n"):
            continue
        k = j - 1
        if quotes[k]:
            k -= 1
        if k >= 0:
            previous = tokens[k]
            restart[j] = (
                any(c in ".!?" for c in previous)
                and any(c in "\"“”«»" for c in tokens[j - 1])
            )

    dialogue_anchors = np.zeros(n, dtype=np.float64)
    if np.any(restart):
        dialogue_anchors[restart] = 2.4
        for j in range(1, n):
            if quotes[j] and not special[j] and punctuation[j - 1]:
                previous = tokens[j - 1]
                if any(c in ",:" for c in previous):
                    dialogue_anchors[j] = 2.2

    for i in range(n):
        distance = i - positions[:i + 1]
        row = strengths[:i + 1] * np.exp(-0.012 * distance)

        if first >= 0 and i > first:
            if pos_tags[first] == "DET":
                boost = 1.28
                if i <= first + 2 and pos_tags[i] in ("NOUN", "PROPN", "ADJ"):
                    boost = 1.60
                row[first] *= boost
            else:
                row[first] *= 1.32

        if not special[i] and not punctuation[i] and not quotes[i] and i != first:
            row[i] += 0.35 * np.exp(-0.075 * i)

        # Only preceding dialogue anchors receive extra mass; retain the
        # original diagonal weights and the original baseline decay.
        if i > 0 and np.any(dialogue_anchors[:i]):
            d = i - positions[:i]
            row[:i] += dialogue_anchors[:i] * np.exp(-0.09 * (d - 1))

        attention[i, :i + 1] = row

    return "boundary_anchors_with_dialogue_restarts", make_row_stochastic(attention)


def prog_L1H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent early boundary anchors, including standalone whitespace after
    sentence-ending punctuation; retain the original self-attention prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    positions = []
    dependencies = []
    first_piece = []
    punctuation = []
    seen_words = set()

    for j, token in enumerate(tokens):
        candidates = alignment[j]
        word = doc[candidates[0]] if candidates else None
        positions.append(word.pos_ if word is not None else "")
        dependencies.append(word.dep_ if word is not None else "")

        clean = token.lstrip("▁Ġ").strip()
        punctuation.append(clean)
        is_first = word is not None and word.i not in seen_words
        first_piece.append(is_first)
        if word is not None:
            seen_words.add(word.i)

    ordinary = [
        j for j in range(n)
        if tokens[j] not in special_tokens and punctuation[j]
    ]
    first = ordinary[0] if ordinary else 0
    comma_count = 0
    salience = np.zeros(n, dtype=np.float64)

    for j in range(n):
        pos = positions[j]
        dep = dependencies[j]
        clean = punctuation[j]

        if tokens[j] in special_tokens:
            salience[j] = 1.0 if j == 0 else 0.12
            continue

        value = 0.48
        if not clean:
            value = 0.16
        elif clean == ",":
            value = 8.0 if comma_count == 0 else 4.2
            comma_count += 1
        elif clean in (";", ":"):
            value = 4.0
        elif pos == "PUNCT":
            value = 0.45
        elif first_piece[j]:
            if pos == "CCONJ" or dep == "cc":
                value = 4.2
            elif pos == "DET":
                value = 2.9
            elif pos == "ADP":
                value = 2.1
            elif pos == "AUX" or dep in ("aux", "auxpass", "cop"):
                value = 2.0
            elif pos == "SCONJ" or dep == "mark":
                value = 1.7
            elif pos == "PRON" and dep in ("poss", "nmod:poss"):
                value = 1.65
            elif pos == "PROPN":
                value = 0.95

        if j == first:
            value = 1.65

        salience[j] = value / (1.0 + 0.045 * max(0, j - first))

    # A separate whitespace token after a sentence boundary is a persistent
    # key, not ordinary low-salience whitespace. Only boost later queries.
    whitespace_anchors = [
        j for j in range(1, n)
        if tokens[j] not in special_tokens
        and not punctuation[j]
        and (tokens[j].isspace() or tokens[j].strip("▁Ġ") == "")
        and any(c in punctuation[j - 1] for c in ".!?")
    ]

    for i in range(n):
        distances = i - np.arange(i + 1)
        weights = salience[:i + 1] * (
            0.78 + 0.22 * np.exp(-distances / 5.0)
        )

        if i > first:
            weights[0] *= 0.90
            if tokens[i] not in special_tokens:
                weights[i] += 0.35
                if positions[i] == "PROPN" and first_piece[i]:
                    weights[i] += 1.5

        if i == first and tokens[i] not in special_tokens:
            pos = positions[i]
            if pos == "DET":
                weights[i] = 1.12
            elif pos == "PRON":
                weights[i] = 1.85
            elif pos == "PROPN":
                weights[i] = 2.7
            elif pos == "ADP":
                weights[i] = 2.15
            else:
                weights[i] = 2.0

        for j in whitespace_anchors:
            if j < i:
                weights[j] += (
                    3.6 / (1.0 + 0.045 * max(0, j - first))
                    * (0.78 + 0.22 * np.exp(-(i - j) / 5.0))
                )

        attention[i, :i + 1] = weights

    return "early_boundary_anchors", make_row_stochastic(attention)


def prog_L1H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors: commas and coordinators dominate, with
    shorter-range determiner/preposition anchors and an initial BOS sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    first_piece = {}
    owners = []
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if 0 <= k < len(doc)]
        owner = valid[0] if valid else None
        owners.append(owner)
        for k in valid:
            if k not in first_piece:
                first_piece[k] = i

    # Anchor strength and persistence are key properties; no lexical lookup
    # is needed. Later boundaries compete with, rather than erase, earlier ones.
    strength = np.full(n, -2.4, dtype=np.float64)
    decay = np.full(n, 0.85, dtype=np.float64)
    clean = [t.lstrip("▁Ġ") for t in tokens]

    for j in range(n):
        if tokens[j] in special_tokens:
            continue

        k = owners[j]
        word = doc[k] if k is not None else None
        is_first = k is not None and first_piece[k] == j

        if "," in clean[j]:
            strength[j] = 4.7 - 0.055 * j
            decay[j] = 0.20
        elif clean[j] and all(c in ".!?;:" for c in clean[j]):
            strength[j] = 2.2 - 0.025 * j
            decay[j] = 0.65
        elif is_first:
            if word.pos_ == "CCONJ":
                strength[j] = 4.3 - 0.04 * j
                decay[j] = 0.33
            elif word.pos_ == "DET" and word.dep_ != "poss":
                strength[j] = 3.1 - 0.035 * j
                decay[j] = 0.70
            elif word.pos_ == "ADP":
                strength[j] = 2.95 - 0.035 * j
                decay[j] = 0.75
            elif word.pos_ == "SCONJ":
                strength[j] = 2.9 - 0.035 * j
                decay[j] = 0.65
            elif word.pos_ == "AUX":
                strength[j] = 1.65 - 0.025 * j
                decay[j] = 0.95

    has_bos = tokens[0] in special_tokens

    for i in range(n):
        positions = np.arange(i + 1)
        distances = i - positions
        logits = strength[:i + 1] - decay[:i + 1] * np.log1p(distances)

        # Modest local background, including a self-attention component.
        logits = np.maximum(logits, -2.5 - 0.10 * distances)
        logits[i] = max(logits[i] - 0.25, 0.05)
        if i > 0:
            logits[i - 1] = max(logits[i - 1], -0.8)

        if has_bos:
            logits[0] = 1.65 - 0.12 * i
        elif i == 0:
            logits[0] = 0.0

        # Clitic suffixes often recover the host across an apostrophe,
        # instead of following the usual clause-boundary distribution.
        if i >= 2 and clean[i - 1] in ("'", "’"):
            k = owners[i]
            if k is not None and doc[k].pos_ in ("AUX", "PART"):
                host = i - 2
                host_owner = owners[host]
                if host_owner is not None:
                    host = first_piece[host_owner]
                target_mass = 0.92 if doc[k].pos_ == "AUX" else 0.66
                other = np.delete(logits, host)
                if len(other):
                    peak = np.max(other)
                    log_other_mass = peak + np.log(np.exp(other - peak).sum())
                    logits[host] = (
                        log_other_mass
                        + np.log(target_mass / (1.0 - target_mass))
                    )

        weights = np.exp(logits - np.max(logits))
        attention[i, :i + 1] = weights / weights.sum()

    return "persistent_boundary_anchors", attention


def prog_L1H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict left boundaries and comma sinks, with an early definite
    prepositional phrase acting as a persistent sink in comma-free clauses.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "left_boundary_with_prepositional_det_sink", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            inverse[si].append(ti)

    first = [indices[0] if indices else -1 for indices in inverse]
    last = [indices[-1] if indices else -1 for indices in inverse]
    special = set(tokenizer.all_special_tokens)

    commas = []
    boundaries = []
    for si, word in enumerate(doc):
        j = first[si]
        if j < 0:
            continue
        if "," in word.text and word.is_punct:
            commas.append(j)
        if word.pos_ in ("CCONJ", "SCONJ", "ADP"):
            boundaries.append((j, word.pos_))

    initial = next(
        (si for si in range(len(doc)) if first[si] >= 0 and not doc[si].is_space),
        None,
    )

    # Restrict the additional sink to early prepositional definite NPs
    # without comma sinks; all other inputs retain the original behavior.
    prep_det_sink = -1
    prep_det_strength = 0.0
    if not commas and initial is not None:
        for si in range(initial, min(len(doc), initial + 9)):
            word = doc[si]
            if word.is_punct or word.pos_ == "CCONJ":
                break
            if (
                first[si] >= 0
                and word.pos_ == "DET"
                and word.dep_ == "det"
                and "Def" in word.morph.get("Definite")
                and word.head.pos_ in ("NOUN", "PROPN")
                and word.head.head.pos_ == "ADP"
                and word.head.head.i < si
            ):
                prep_det_sink = first[si]
                prep_det_strength = (
                    8.0 if doc[initial].pos_ == "ADP" else 3.5
                )
                break

    for i in range(n):
        if i == 0 or tokens[i] in special:
            matrix[i, 0] = 1.0
            continue

        row = matrix[i]
        row[:i + 1] = 0.002 * np.exp(
            -(i - np.arange(i + 1)) / 18.0
        )
        row[0] += 0.8 * np.exp(-i / 14.0)
        row[i] += 0.28
        row[i - 1] += 0.16

        past_commas = [j for j in commas if j <= i]
        for rank, j in enumerate(past_commas):
            strength = 7.0 if rank == 0 else 2.7
            decay = 65.0 if rank == 0 else 18.0
            row[j] += strength * np.exp(-(i - j) / decay)

        for j, pos in boundaries:
            if j > i:
                continue
            distance = i - j
            if pos == "CCONJ":
                strength = 5.0 if not past_commas else 2.8
                row[j] += strength * np.exp(-distance / 20.0)
            elif pos == "SCONJ":
                row[j] += 3.0 * np.exp(-distance / 9.0)
            else:
                row[j] += 1.8 * np.exp(-distance / 6.0)

        if 0 <= prep_det_sink < i:
            row[prep_det_sink] += prep_det_strength * np.exp(
                -(i - prep_det_sink) / 65.0
            )

        indices = aligned[i]
        if not indices:
            if past_commas:
                row[past_commas[0]] += 1.0
            continue

        si = indices[-1]
        word = doc[si]
        previous = doc[si - 1] if si > 0 else None
        pj = last[si - 1] if si > 0 else -1

        if initial is not None:
            initial_word = doc[initial]
            ij = first[initial]
            if si == initial:
                if word.pos_ == "DET":
                    row[0] += 4.4
                    row[ij] += 4.8
                elif word.pos_ in ("ADP", "SCONJ"):
                    row[0] += 4.5
                    row[ij] += 2.7
                else:
                    row[0] += 7.0
            elif not past_commas and i - ij < 10:
                if initial_word.pos_ == "DET":
                    row[ij] += 4.0 * np.exp(-(i - ij) / 14.0)
                elif si <= initial + 2 and word.pos_ in ("VERB", "AUX"):
                    row[0] += 2.4

        if previous is not None and 0 <= pj <= i:
            if word.pos_ in ("DET", "PRON"):
                if previous.pos_ in (
                    "VERB", "AUX", "ADP", "SCONJ", "CCONJ", "ADV", "NOUN"
                ):
                    strength = 30.0
                    if word.pos_ == "DET" and previous.pos_ == "AUX":
                        strength = 13.0
                    if previous.pos_ == "CCONJ" and past_commas:
                        strength = 12.0
                    row[pj] += strength
            elif word.pos_ in ("ADJ", "NOUN", "PROPN"):
                if previous.pos_ == "DET":
                    row[pj] += 8.0
                elif previous.pos_ in ("ADP", "CCONJ"):
                    row[pj] += 13.0
            elif word.pos_ in ("VERB", "AUX", "ADV"):
                if previous.pos_ == "CCONJ":
                    row[pj] += 15.0
                elif previous.pos_ == "SCONJ":
                    row[pj] += 7.0

        if word.pos_ in ("NOUN", "PROPN", "ADJ"):
            noun = word.head if word.dep_ == "amod" else word
            for child in noun.children:
                cj = first[child.i]
                if child.dep_ == "det" and 0 <= cj <= i:
                    row[cj] += 5.0 if not past_commas else 2.0
            if noun.head.pos_ == "ADP":
                hj = first[noun.head.i]
                if 0 <= hj <= i:
                    row[hj] += 5.0

        if word.pos_ == "CCONJ":
            row[first[si]] += 9.0 if not past_commas else 3.0
        elif word.pos_ == "ADP" and word.dep_ in ("prep", "agent"):
            row[first[si]] += 1.5

        if word.is_punct:
            if "," in word.text:
                row[first[si]] += 2.0
            elif past_commas:
                row[past_commas[0]] += 1.0

    return "left_boundary_with_prepositional_det_sink", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L1H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent early phrase-boundary anchors, especially commas and coordinators,
    compete with shorter-lived determiner, preposition, and auxiliary anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_phrase_onsets", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    kinds = [""] * n
    strengths = np.zeros(n, dtype=np.float64)
    owners = [-1] * n
    first_piece = np.ones(n, dtype=bool)

    for i, aligned in enumerate(alignment):
        if aligned:
            sid = aligned[0]
            owners[i] = sid
            if inverse[sid]:
                first_piece[i] = i == inverse[sid][0]

    initial_determiner = False
    for i, token in enumerate(tokens):
        if token in special:
            continue

        clean = token.replace("▁", "").replace("Ġ", "").strip()
        sid = owners[i]
        word = doc[sid] if sid >= 0 else None

        if "," in clean:
            kinds[i] = "boundary"
            strengths[i] = 25.0 * np.exp(-0.085 * max(0, i - 2))
            if initial_determiner:
                strengths[i] *= 0.52
            continue

        if word is None or not first_piece[i]:
            continue

        pos, dep = word.pos_, word.dep_
        if pos == "CCONJ" or dep == "cc":
            kinds[i] = "coordination"
            strengths[i] = 20.0 * np.exp(-0.075 * max(0, i - 2))
        elif pos == "SCONJ" or dep == "mark":
            kinds[i] = "subordination"
            strengths[i] = 12.0 * np.exp(-0.075 * max(0, i - 3))
        elif pos == "DET":
            kinds[i] = "determiner"
            strengths[i] = 12.0 * np.exp(-0.075 * max(0, i - 2))
            if i <= 3:
                initial_determiner = True
        elif pos == "ADP" or dep in ("prep", "agent"):
            kinds[i] = "preposition"
            strengths[i] = 7.0 * np.exp(-0.065 * max(0, i - 2))
        elif pos == "AUX" or dep in ("aux", "auxpass", "cop"):
            kinds[i] = "auxiliary"
            strengths[i] = 3.2 * np.exp(-0.085 * max(0, i - 2))

    persistent = {"boundary", "coordination", "subordination"}
    local = {"determiner", "preposition", "auxiliary"}

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        # Modest BOS and diagonal defaults; structural keys can overwhelm both.
        attention[i, 0] = 0.65 / (1.0 + 0.025 * i)
        attention[i, i] += 0.55
        if i > 1:
            attention[i, i - 1] += 0.14

        sid = owners[i]
        query = doc[sid] if sid >= 0 else None
        if query is not None and first_piece[i]:
            if query.pos_ in ("VERB", "PROPN"):
                attention[i, i] += 0.45
            elif query.pos_ == "PRON":
                attention[i, i] += 0.10

        for j in range(1, i + 1):
            kind = kinds[j]
            if not kind:
                continue

            distance = i - j
            if kind in persistent:
                # Early structural boundaries remain available across clauses.
                decay = 0.022 if kind == "boundary" else 0.035
                weight = strengths[j] * np.exp(-decay * distance)
            else:
                decay = 0.13 if kind != "auxiliary" else 0.24
                weight = strengths[j] * np.exp(-decay * distance)

                # New phrase onsets replace local anchors, not persistent ones.
                for k in range(j + 1, i + 1):
                    newer = kinds[k]
                    if newer in persistent:
                        weight *= 0.48
                    elif newer in local:
                        weight *= 0.88 if newer == "auxiliary" else 0.48

            if query is not None:
                if kind == "determiner" and query.pos_ in (
                    "NOUN", "PROPN", "ADJ"
                ):
                    weight *= 1.12
                elif kind in persistent and query.pos_ in ("VERB", "AUX"):
                    weight *= 1.08

            # All pieces of a word can retrieve its initial structural piece.
            if sid >= 0 and owners[j] == sid and j < i:
                weight *= 1.10

            attention[i, j] += weight

        # Retain a small diffuse causal component rather than a hard selection.
        attention[i, :i + 1] += 0.08 / (i + 1)

    return "persistent_phrase_onsets", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L1H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict sticky attention to early clause/phrase boundaries, with strong
    previous-piece attention inside subword-tokenized words."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "sticky_boundary_and_subword", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    word_ids = [None] * n
    clean = [t.lstrip("▁Ġ") for t in tokens]
    first_piece = [True] * n

    for i, ids in enumerate(alignment):
        if ids and tokens[i] not in specials:
            k = ids[0]
            word_ids[i] = k
            pos[i] = doc[k].pos_
            dep[i] = doc[k].dep_

    for i in range(1, n):
        same_word = (
            word_ids[i] is not None
            and word_ids[i] == word_ids[i - 1]
        )
        contiguous = (
            i < len(spans)
            and spans[i][0] == spans[i - 1][1]
            and spans[i][1] > spans[i][0]
        )
        lexical_join = (
            bool(clean[i])
            and bool(clean[i - 1])
            and clean[i][0].isalnum()
            and clean[i - 1][-1].isalnum()
            and not tokens[i].startswith(("▁", "Ġ"))
        )
        if lexical_join and (same_word or contiguous):
            first_piece[i] = False

    strength = np.zeros(n, dtype=np.float64)
    decay = np.zeros(n, dtype=np.float64)

    for j in range(n):
        if tokens[j] in specials or not first_piece[j]:
            continue

        early = np.exp(-0.065 * j)
        if clean[j] in (",", ";", ":"):
            strength[j] = 25.0 * np.exp(-0.10 * j)
            decay[j] = 0.018
        elif pos[j] == "CCONJ":
            strength[j] = 18.0 * early
            decay[j] = 0.060
        elif pos[j] == "SCONJ" or dep[j] == "mark":
            strength[j] = 14.0 * early
            decay[j] = 0.065
        elif pos[j] == "DET":
            strength[j] = 12.0 * np.exp(-0.055 * j)
            decay[j] = 0.19
        elif pos[j] == "ADP" or pos[j] == "PART":
            strength[j] = 10.0 * early
            decay[j] = 0.20
        elif pos[j] == "AUX":
            strength[j] = 5.0 * early
            decay[j] = 0.36

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        distances = i - np.arange(i + 1)
        row = 0.025 * np.exp(-distances / 12.0)
        row += strength[:i + 1] * np.exp(
            -decay[:i + 1] * distances
        )

        row[0] += 1.1 * np.exp(-0.055 * i)
        row[i] += 1.4
        row[i - 1] += 0.65

        if pos[i] in ("VERB", "AUX", "PROPN"):
            row[i] += 0.7

        if clean[i] in (".", "!", "?", "?!", '?"', '!"'):
            row[i] += 3.5

        if tokens[i] in specials:
            row[i] += 8.0

        if i == 1 and tokens[0] in specials:
            if pos[i] in ("PRON", "PROPN", "ADV", "ADP"):
                bos_mass = {
                    "PRON": 0.69,
                    "PROPN": 0.59,
                    "ADV": 0.72,
                    "ADP": 0.51,
                }[pos[i]]
                row[:] = 0.0
                row[0] = bos_mass
                row[i] = 1.0 - bos_mass

        row /= row.sum()

        if not first_piece[i]:
            root = i - 1
            while root > 0 and not first_piece[root]:
                root -= 1

            row *= 0.06
            if root == i - 1:
                row[i - 1] += 0.94
            else:
                row[i - 1] += 0.80
                row[root] += 0.14

        elif (
            clean[i].isalnum()
            and i >= 2
            and clean[i - 1] in ("'", "’")
            and not tokens[i].startswith(("▁", "Ġ"))
        ):
            row *= 0.55
            row[i - 2] += 0.45

        attention[i, :i + 1] = row

    return "sticky_boundary_and_subword", make_row_stochastic(attention)


def prog_L1H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict local phrase-onset attention mixed with persistent comma and
    coordination anchors, rather than direct syntactic-head attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "phrase_onsets_and_punctuation_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_ids = [indices[0] if indices else -1 for indices in alignment]

    first_piece = {}
    last_piece = {}
    for i, sid in enumerate(word_ids):
        if sid >= 0:
            if sid not in first_piece:
                first_piece[sid] = i
            last_piece[sid] = i

    commas = []
    coordinators = []
    structural_anchor = None

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        sid = word_ids[i]
        word = doc[sid] if sid >= 0 else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        start = first_piece.get(sid, i)
        continuation = sid >= 0 and start < i

        previous_sid = -1
        for k in range(start - 1, 0, -1):
            if word_ids[k] >= 0 and word_ids[k] != sid:
                previous_sid = word_ids[k]
                break

        previous = doc[previous_sid] if previous_sid >= 0 else None
        previous_pos = previous.pos_ if previous is not None else ""
        previous_index = last_piece.get(previous_sid, max(0, start - 1))

        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        is_comma = "," in clean
        is_punctuation = pos == "PUNCT"
        is_coordinator = pos == "CCONJ" or dep == "cc"

        row = matrix[i]
        row[:i + 1] = 0.018 * np.exp(
            -(i - np.arange(i + 1)) / 12.0
        )
        row[0] += 0.45 / (1.0 + 0.045 * i)
        row[i] += 0.50

        if i == 1:
            row[:] = 0.0
            self_mass = 0.455 if pos == "DET" else 0.20
            row[0] = 1.0 - self_mass
            row[i] = self_mass
        else:
            local_weight = 1.0
            if pos in ("NOUN", "PROPN", "ADJ", "ADV", "NUM"):
                local_weight = 2.8
            if previous_pos in ("DET", "ADJ", "NUM"):
                if pos in ("NOUN", "PROPN", "ADJ", "NUM"):
                    local_weight = 4.0
            if previous_pos in ("ADP", "AUX", "SCONJ"):
                local_weight = 3.4
            if pos in ("VERB", "AUX") and previous_pos in (
                "NOUN", "PROPN", "PRON"
            ):
                local_weight = 0.75
            if pos in ("DET", "ADP", "CCONJ", "SCONJ"):
                local_weight = 0.55
            if is_punctuation:
                local_weight = 0.35

            row[previous_index] += local_weight

            if continuation:
                row[start] += 1.6
                row[i] *= 0.55

            if pos in ("DET", "ADP", "SCONJ") and not continuation:
                row[i] += 3.3
                if previous_pos == "ADP":
                    row[i] *= 0.35
                    row[previous_index] += 2.0

            if pos == "AUX" and not continuation:
                row[i] += 1.8

        if structural_anchor is not None:
            anchor_index, anchor_strength = structural_anchor
            distance = i - anchor_index
            if 0 < distance <= 10:
                row[anchor_index] += (
                    anchor_strength * np.exp(-(distance - 1) / 3.5)
                )

        for rank, comma_index in enumerate(commas):
            distance = i - comma_index
            strength = 7.5 if rank == 0 else 3.2
            row[comma_index] += strength / (1.0 + 0.065 * distance)

        for coordinator_index in coordinators:
            distance = i - coordinator_index
            row[coordinator_index] += 5.5 * np.exp(
                -max(0, distance - 1) / 5.0
            )

        if is_comma:
            row[i] += 7.0 if not commas else 3.4
            commas.append(i)

        if is_coordinator and not continuation:
            row[i] += 5.5
            coordinators.append(i)

        if not continuation and pos in ("DET", "ADP", "AUX", "SCONJ"):
            strength = {
                "DET": 1.6,
                "ADP": 2.3,
                "AUX": 2.0,
                "SCONJ": 3.2,
            }[pos]
            if not (pos == "DET" and previous_pos == "ADP"):
                structural_anchor = (i, strength)

    matrix = make_row_stochastic(apply_causal_mask(matrix))
    return "phrase_onsets_and_punctuation_anchors", matrix


def prog_L1H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sticky phrase boundaries, with whitespace resets in multi-quote dialogue.
    Within dialogue, later grammatical anchors weaken while commas remain salient.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "sticky_dialogue_boundaries", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    # Only the first model piece of a linguistic token becomes an anchor.
    first_piece = {}
    owners = []
    for i, indices in enumerate(alignment):
        owner = indices[0] if indices else None
        owners.append(owner)
        for k in indices:
            if k not in first_piece and tokens[i] not in specials:
                first_piece[k] = i

    # Restrict the new behavior to passages containing multiple quoted spans.
    dialogue = sum(1 for word in doc if word.is_quote) >= 4
    dialogue_start = n
    if dialogue:
        dialogue_start = next(
            (i for i, k in enumerate(owners)
             if k is not None and doc[k].is_quote),
            n,
        )

    anchors = []
    comma_count = 0
    coordinator_count = 0
    determiner_count = 0

    for i in range(n):
        if tokens[i] in specials:
            continue

        k = owners[i]
        if k is None or first_piece.get(k) != i:
            continue

        word = doc[k]
        pos = word.pos_
        dep = word.dep_
        punctuation = word.text.strip()

        if punctuation == ",":
            strength = 16.0 / (1.0 + 0.12 * i)
            strength *= 0.55 ** comma_count
            anchors.append((i, "comma", strength))
            comma_count += 1

        elif pos == "CCONJ" or dep == "cc":
            strength = 10.0 * (0.85 ** coordinator_count)
            anchors.append((i, "coord", strength))
            coordinator_count += 1

        elif pos == "DET" and dep in ("det", "predet"):
            strength = 7.5 if determiner_count == 0 else 5.0
            anchors.append((i, "det", strength))
            determiner_count += 1

        elif pos == "SCONJ" or dep == "mark":
            anchors.append((i, "mark", 7.0))

        elif pos == "ADP":
            anchors.append((i, "prep", 4.2))

        elif pos == "AUX":
            anchors.append((i, "aux", 3.4))

        elif i == 1 and pos in ("ADV", "VERB"):
            anchors.append((i, "start", 2.3))

    if dialogue:
        # Preserve the opening context; only recalibrate anchors inside dialogue.
        scales = {"coord": 0.25, "det": 0.18, "mark": 0.20,
                  "prep": 0.45, "aux": 0.20}
        anchors = [
            (
                j,
                kind,
                strength if j < dialogue_start else (
                    max(strength, 6.0 / (1.0 + 0.03 * j))
                    if kind == "comma"
                    else strength * scales.get(kind, 1.0)
                ),
            )
            for j, kind, strength in anchors
        ]
        # Standalone whitespace pieces after quoted sentences act as reset sinks.
        for j in range(dialogue_start + 1, n):
            if tokens[j] in specials:
                continue
            whitespace = tokens[j].replace("▁", " ").replace("Ġ", " ")
            if whitespace and not whitespace.strip():
                anchors.append((j, "reset", 3.5))
        anchors.sort(key=lambda anchor: anchor[0])

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        # Weak causal background, self-attention, and the initial sink.
        distance = i - np.arange(i + 1)
        matrix[i, :i + 1] = 0.035 * np.exp(-distance / 10.0)
        matrix[i, 0] += 1.0
        matrix[i, i] += 0.45

        k = owners[i]
        if k is not None:
            word = doc[k]
            if word.pos_ == "VERB":
                matrix[i, i] += 0.45
            if word.is_punct and word.text.strip() in (".", "!", "?", ";", ":"):
                matrix[i, i] += 1.5

        active = False
        for j, kind, strength in anchors:
            if j > i:
                break

            d = i - j
            if kind == "comma":
                decay = 0.58 * np.exp(-d / 8.0) + 0.42 * np.exp(-d / 85.0)
            elif kind == "coord":
                decay = 0.72 * np.exp(-d / 4.5) + 0.28 * np.exp(-d / 35.0)
            elif kind == "det":
                decay = np.exp(-d / 3.2)
                if j <= 2:
                    decay = 0.82 * decay + 0.18 * np.exp(-d / 20.0)
            elif kind == "mark":
                decay = 0.8 * np.exp(-d / 5.0) + 0.2 * np.exp(-d / 25.0)
            elif kind == "prep":
                decay = np.exp(-d / 2.4)
            elif kind == "aux":
                decay = np.exp(-d / 1.8)
            elif kind == "reset":
                decay = 0.65 * np.exp(-d / 6.0) + 0.35 * np.exp(-d / 45.0)
            else:
                decay = np.exp(-d / 2.5)

            matrix[i, j] += strength * decay
            if strength * decay > 1.0:
                active = True

        if active:
            matrix[i, 0] *= 0.65

        # Continuation pieces inherit the same boundary preference rather
        # than introducing a new anchor.
        if k is not None:
            first = first_piece.get(k, i)
            if first < i:
                matrix[i, first] += 0.15

    return "sticky_dialogue_boundaries", make_row_stochastic(matrix)


def prog_L1H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict left-boundary attention: persistent comma/conjunction sinks,
    phrase-initial determiners, and local links at prepositions and subwords.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "phrase_boundary_and_local_links", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    specials = tokenizer.all_special_tokens

    words = []
    first_piece = []
    for i in range(n):
        ids = alignment[i]
        word = doc[ids[-1]] if ids else None
        words.append(word)
        first_piece.append(
            word is not None
            and (i == 0 or word.i not in alignment[i - 1])
        )

    comma_positions = []
    conjunction_positions = []
    determiner_positions = []
    preposition_positions = []

    for i in range(n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        if i == 0:
            matrix[0, 0] = 1.0
            continue

        is_comma = clean == ","
        is_conjunction = first_piece[i] and pos == "CCONJ"
        is_determiner = first_piece[i] and pos == "DET"
        is_preposition = first_piece[i] and (
            pos == "ADP"
            or (pos == "PART" and dep != "neg")
            or dep == "prt"
        )

        if is_comma:
            comma_positions.append(i)
        if is_conjunction:
            conjunction_positions.append(i)
        if is_determiner:
            determiner_positions.append(i)
        if is_preposition:
            preposition_positions.append(i)

        row = matrix[i]
        row[:i + 1] = 0.015
        row[0] += 5.0 * np.exp(-(i - 1) / 6.0)
        row[i] += 0.55
        row[i - 1] += 0.60

        # Commas remain accessible across subsequent clauses and quotations.
        for rank, j in enumerate(comma_positions):
            persistence = 1.0 if rank == 0 else 0.82
            row[j] += 10.0 * persistence * np.exp(-(i - j) / 38.0)

        # Coordination supplies another left-edge anchor, usually more local.
        for j in conjunction_positions:
            row[j] += 11.0 * np.exp(-(i - j) / 12.0)

        # Articles introduce compact nominal spans.
        for j in determiner_positions:
            distance = i - j
            strength = 4.0 if distance == 0 else 7.0
            row[j] += strength * np.exp(-distance / 4.0)

        # A preposition can become the anchor of its following complement.
        for j in preposition_positions:
            if j < i:
                row[j] += 5.0 * np.exp(-(i - j) / 4.5)

        # Immediate left links dominate at prepositions, infinitival markers,
        # and verbal particles, rather than following the syntactic head.
        if is_preposition:
            row[i - 1] += 30.0
            row[i] *= 0.35

        # Strengthen the left edge of a noun phrase when it is identifiable.
        if word is not None and pos in ("NOUN", "PROPN", "ADJ"):
            candidates = []
            for j in determiner_positions:
                if j >= i or i - j > 10:
                    continue
                det = words[j]
                if det is not None and (
                    det.head.i == word.i
                    or det.head.i == word.head.i
                ):
                    candidates.append(j)
            if candidates:
                row[candidates[-1]] += 5.0

        # Model-token continuations usually point to the preceding piece.
        shared_word = (
            word is not None
            and word.i in alignment[i - 1]
        )
        contiguous = (
            i < len(spans)
            and spans[i][0] == spans[i - 1][1]
            and spans[i][1] > spans[i][0]
        )
        continuation = (
            raw not in specials
            and bool(clean)
            and not raw.startswith(("▁", "Ġ"))
            and any(c.isalnum() for c in clean)
            and (shared_word or contiguous)
        )
        if continuation:
            previous_is_continuation = (
                i > 1
                and not tokens[i - 1].startswith(("▁", "Ġ"))
                and words[i - 1] is not None
                and words[i - 2] is not None
                and words[i - 1].i == words[i - 2].i
            )
            row[i - 1] += 10.0 if previous_is_continuation else 35.0
            row[i] *= 0.3

        if clean in ("'", "’"):
            row[i - 1] += 16.0

        if word is not None and word.is_punct and not is_comma:
            if clean in (".", "!", "?"):
                row[i] += 5.0
            else:
                row[i] += 0.5

        # Sentence-initial lexical material primarily uses the BOS sink.
        if i == 1 and not is_determiner and not is_preposition:
            row[0] += 1.5

    return (
        "phrase_boundary_and_local_links",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L1H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors, with dialogue whitespace and later commas
    sharing attention that otherwise collapses onto the earliest comma.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "dialogue_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    word_for_token = [-1] * n
    first_piece = {}
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if k < len(doc) and not doc[k].is_space]
        if valid and tokens[i] not in special_tokens:
            k = valid[0]
            word_for_token[i] = k
            if k not in first_piece:
                first_piece[k] = i

    kinds = ["ordinary"] * n
    strengths = np.full(n, 0.035, dtype=np.float64)

    for j, token in enumerate(tokens):
        if token in special_tokens:
            kinds[j] = "special"
            strengths[j] = 1.0 if j == 0 else 0.1
            continue

        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        k = word_for_token[j]

        if "," in clean:
            kinds[j] = "comma"
            strengths[j] = 55.0 / (1.0 + (0.30 * j) ** 2)
            continue

        if k < 0:
            if clean and all(c in ".!?;:" for c in clean):
                kinds[j] = "punctuation"
                strengths[j] = 1.2
            continue

        word = doc[k]
        if first_piece.get(k) != j:
            continue

        pos = word.pos_
        if pos == "DET":
            kinds[j] = "determiner"
            definite = "Def" in word.morph.get("Definite")
            strengths[j] = 12.0 if definite else 3.1
            if j == 1:
                strengths[j] = 5.25 if definite else 2.0
        elif pos == "CCONJ":
            kinds[j] = "coordinator"
            strengths[j] = 9.0
        elif pos == "SCONJ" or word.dep_ == "mark":
            kinds[j] = "subordinator"
            strengths[j] = 11.0
        elif pos == "ADP":
            kinds[j] = "preposition"
            strengths[j] = 6.0 if j > 1 else 1.3
        elif pos == "AUX":
            kinds[j] = "auxiliary"
            strengths[j] = 3.4
        elif word.is_punct:
            if clean and any(c in ".!?;:" for c in clean):
                kinds[j] = "punctuation"
                strengths[j] = 1.2
        elif pos == "PRON":
            strengths[j] = 0.375
        elif pos == "PROPN":
            strengths[j] = 0.145
        elif pos == "VERB":
            strengths[j] = 0.65
        elif pos in ("ADV", "NUM"):
            strengths[j] = 0.22
        else:
            strengths[j] = 0.14

    # Restrict the exception to quoted text with explicit whitespace pieces.
    # These pieces act as boundaries rather than ordinary, unaligned tokens.
    clean_tokens = [
        token.replace("▁", " ").replace("Ġ", " ").strip()
        for token in tokens
    ]
    whitespace_boundaries = {
        j for j, token in enumerate(tokens)
        if token not in special_tokens and token and not clean_tokens[j]
    }
    dialogue_boundaries = bool(whitespace_boundaries) and any(
        clean and all(c in "\"“”«»" for c in clean)
        for clean in clean_tokens
    )

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        wi = word_for_token[i]
        for j in range(i + 1):
            wj = word_for_token[j]
            distance = max(0, wi - wj) if wi >= 0 and wj >= 0 else i - j
            kind = kinds[j]
            value = strengths[j]

            if kind == "special":
                value *= np.exp(-0.035 * (i - j))
            elif kind == "comma":
                value *= np.exp(-0.026 * distance)
            elif kind in ("coordinator", "subordinator"):
                value *= np.exp(-0.025 * distance)
            elif kind == "determiner":
                value *= np.exp(
                    -0.05 * distance - 0.30 * max(0, distance - 2)
                )
            elif kind == "preposition":
                value *= np.exp(
                    -0.07 * distance - 0.23 * max(0, distance - 2)
                )
            elif kind == "auxiliary":
                value *= np.exp(-0.28 * distance)
            elif kind == "punctuation":
                value *= np.exp(-0.22 * distance)
            else:
                value *= np.exp(-0.50 * distance)
                if j < i:
                    value *= 0.45

            attention[i, j] = value

        if dialogue_boundaries:
            # Adjust only retrieval edges: retain all original diagonal
            # weights and all original decay calculations.
            for j in range(i):
                if kinds[j] == "comma":
                    attention[i, j] *= (
                        8.0 / (1.0 + 0.015 * j)
                    ) / strengths[j]
                elif j in whitespace_boundaries:
                    attention[i, j] += 6.0 * np.exp(-0.026 * (i - j))
                elif (
                    kinds[j] == "determiner"
                    and j - 1 in whitespace_boundaries
                ):
                    attention[i, j] *= 0.08
                elif kinds[j] == "coordinator":
                    attention[i, j] *= (
                        0.04 if j > 0 and kinds[j - 1] == "comma" else 0.35
                    )

        # Bound negative contraction fragments preferentially retrieve their
        # auxiliary rather than establishing a new structural anchor.
        if wi >= 0 and doc[wi].dep_ == "neg":
            fragment = tokens[i]
            if not fragment.startswith(("▁", "Ġ")):
                head = doc[wi].head.i
                anchor = first_piece.get(head, -1)
                if 0 <= anchor < i and doc[head].pos_ in ("AUX", "VERB"):
                    total = attention[i, :i + 1].sum()
                    attention[i, anchor] += 24.0 * max(total, 1.0)

    return "dialogue_boundary_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L1H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent comma sink, except in dialogue where sentence boundaries
    and earlier grammatical anchors compete with the comma."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "comma_sink_with_dialogue_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos = []
    dep = []
    clean = []
    for i, token in enumerate(tokens):
        clean.append(token.replace("▁", " ").replace("Ġ", " ").strip())
        overlaps = alignment[i]
        if overlaps and token not in special_tokens:
            word = doc[overlaps[-1]]
            pos.append(word.pos_)
            dep.append(word.dep_)
        else:
            pos.append("")
            dep.append("")

    commas = []
    anchors = []
    quote_history = []
    active_quote = None
    opening_quotes = "\"“«"
    closing_quotes = "\"”»"

    # Dialogue-specific state; ordinary comma-containing prose is unchanged.
    dialogue_seen = False
    dialogue_boundaries = []
    dialogue_anchors = []

    for i, token in enumerate(tokens):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        text = clean[i]
        is_comma = text == ","
        has_open_quote = any(c in text for c in opening_quotes)
        has_close_quote = any(c in text for c in closing_quotes)
        terminal = any(c in text for c in ".!?")
        closing_quote = has_close_quote and active_quote is not None
        opening_quote = has_open_quote and not closing_quote
        comma_context = bool(commas) or is_comma

        # The euro glyph also occurs in mojibake quotation punctuation.
        # Look ahead one piece to recognize its initial fragment as well.
        if (
            has_open_quote
            or has_close_quote
            or "€" in text
            or (i + 1 < n and "€" in clean[i + 1])
        ):
            dialogue_seen = True

        row = attention[i]
        row[0] = (
            0.14 / (1.0 + i / 20.0)
            if comma_context
            else 1.55 * np.exp(-i / 8.0) + 0.12
        )

        self_weight = 0.48
        if pos[i] in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
            self_weight = 0.85
        elif pos[i] == "AUX":
            self_weight = 1.25
        elif pos[i] == "VERB":
            self_weight = 0.70
        elif pos[i] == "PUNCT":
            self_weight = 0.75
        if comma_context:
            self_weight *= 0.65
        row[i] += self_weight
        row[i - 1] += 0.10

        for j in anchors[-5:]:
            distance = i - j
            strength = 0.95 if pos[j] == "DET" else 0.75
            strength *= np.exp(-distance / 8.0)
            if comma_context:
                strength *= 0.22
            if pos[i] in ("NOUN", "PROPN", "ADJ") and pos[j] == "DET":
                strength *= 1.5
            row[j] += strength

        # A small diffuse component represents the less selective background.
        for j in range(1, i):
            row[j] += 0.12 * np.exp(-(i - j) / 8.0)

        for rank, j in enumerate(commas):
            strength = 5.8 if rank == 0 else 2.8
            strength /= (1.0 + (i - j) / 35.0) ** 0.35
            row[j] += strength

        if is_comma:
            row[i] += 6.5 if not commas else 2.8

        if terminal:
            row[i] += 3.2 if not comma_context else 1.9

        if closing_quote:
            row[active_quote] += 10.0
            for j in quote_history:
                if j != active_quote:
                    row[j] += 1.2
            quote_history.append(i)
            active_quote = None
        elif opening_quote:
            row[i] += 1.1
            for j in quote_history[-2:]:
                row[j] += 3.6
            active_quote = i
            quote_history.append(i)

        # Only dialogue releases the persistent comma sink. Preserve the
        # original self weights and modify only competing, earlier keys.
        if dialogue_seen and comma_context:
            for rank, j in enumerate(commas):
                if rank == 0:
                    row[j] *= 0.22 if dialogue_boundaries else 0.35
                else:
                    row[j] *= 0.70

            row[0] += 0.60
            for j in dialogue_anchors[-6:]:
                strength = 0.90 if pos[j] in ("VERB", "AUX") else 0.55
                row[j] += strength * np.exp(-(i - j) / 40.0)
            for j in dialogue_boundaries[-3:]:
                row[j] += 1.60 * np.exp(-(i - j) / 40.0)

            # Repeated apostrophes and corrupted quote pieces can retrieve
            # their previous occurrence without treating them as words.
            if text in ("'", "’", "€"):
                for j in range(i - 1, 0, -1):
                    if clean[j] == text:
                        row[j] += 2.5
                        break

        if i == 1 and not is_comma and not terminal:
            bos_weight = 0.80
            if pos[i] == "DET":
                bos_weight = 0.53
            elif pos[i] == "PRON":
                bos_weight = 0.74
            elif pos[i] == "PROPN":
                bos_weight = 0.85
            row[:] = 0.0
            row[0] = bos_weight
            row[i] = 1.0 - bos_weight

        if is_comma:
            commas.append(i)
        if pos[i] in ("DET", "AUX", "CCONJ", "SCONJ") or dep[i] == "mark":
            if not anchors or alignment[i] != alignment[anchors[-1]]:
                anchors.append(i)

        if pos[i] in ("DET", "AUX", "VERB", "CCONJ", "SCONJ"):
            if (
                not dialogue_anchors
                or alignment[i] != alignment[dialogue_anchors[-1]]
            ):
                dialogue_anchors.append(i)
        if dialogue_seen and terminal:
            dialogue_boundaries.append(i)

    return (
        "comma_sink_with_dialogue_competition",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L1H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local phrase-anchor attention with a persistent first-comma discourse sink.
    A distant clause-opening comma remains available after local anchors fade."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_anchors_persistent_comma", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for wi in indices:
            if wi < len(doc):
                inverse[wi].append(ti)

    specials = set(tokenizer.all_special_tokens)
    word_ids = [
        next((wi for wi in indices if not doc[wi].is_space), None)
        for indices in alignment
    ]
    starts = [
        min(indices) if indices else None
        for indices in inverse
    ]
    boundaries = []
    for i, token in enumerate(tokens):
        wi = word_ids[i]
        text = doc[wi].text if wi is not None else token.strip("▁Ġ ")
        if text and any(c in text for c in ",;:.!?"):
            boundaries.append(i)

    # Use the actual model piece, not its aligned word: an aligned punctuation
    # span can include several pieces that should not all become comma sinks.
    first_comma = next(
        (
            i for i, token in enumerate(tokens)
            if token not in specials and "," in token.strip("▁Ġ ")
        ),
        None,
    )

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        # A broad local prior, with the strongest positional preference at -2.
        distances = i - np.arange(i + 1)
        matrix[i, :i + 1] = 0.10 * np.exp(-distances / 6.0)
        matrix[i, i] += 0.20
        matrix[i, i - 1] += 0.32
        if i >= 2:
            matrix[i, i - 2] += 0.70
        if i >= 3:
            matrix[i, i - 3] += 0.22

        # The initial attention sink decays rapidly as local structure appears.
        matrix[i, 0] += 7.5 * np.exp(-(i - 1) / 1.55) + 0.08

        wi = word_ids[i]
        if wi is not None and tokens[i] not in specials:
            word = doc[wi]
            start = starts[wi]

            # Find the preceding phrase anchor, skipping intervening light
            # grammatical material rather than blindly following dependencies.
            previous = wi - 1
            skipped = 0
            while previous >= 0 and skipped < 4:
                candidate = doc[previous]
                light = candidate.pos_ in ("DET", "PART")
                light = light or candidate.dep_ in (
                    "poss", "possessive", "predet", "neg"
                )
                light = light or (
                    candidate.pos_ == "ADV"
                    and candidate.dep_ == "advmod"
                    and word.pos_ in ("ADJ", "ADV", "VERB")
                )
                light = light or (
                    candidate.pos_ == "PRON"
                    and word.pos_ in ("VERB", "AUX")
                )
                if candidate.is_space or light:
                    previous -= 1
                    skipped += 1
                else:
                    break

            if previous >= 0 and starts[previous] is not None:
                target = starts[previous]
                candidate = doc[previous]
                if target < i and i - target <= 9:
                    strength = 0.75
                    if word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB", "ADV"):
                        strength = 1.45
                    if candidate.pos_ in ("VERB", "AUX", "ADP", "SCONJ"):
                        strength += 0.60
                    if candidate.pos_ == "PUNCT":
                        strength = 0.25
                    matrix[i, target] += strength * np.exp(
                        -max(0, i - target - 3) / 3.0
                    )

            # Backward syntactic governors reinforce, but do not replace,
            # the local phrase-start mechanism.
            head = word.head
            if head.i != wi and starts[head.i] is not None:
                target = starts[head.i]
                if target < i and i - target <= 10:
                    strength = 0.45
                    if word.dep_ in (
                        "dobj", "obj", "pobj", "xcomp", "acomp", "attr"
                    ):
                        strength = 0.95
                    matrix[i, target] += strength * np.exp(
                        -max(0, i - target - 3) / 3.5
                    )

            # Multi-piece words retain a weaker connection to their own onset.
            if start is not None and start < i:
                matrix[i, start] += 0.45 if i - start == 1 else 1.65

        # Recent clause punctuation behaves like a temporary attention sink.
        boundary = next((b for b in reversed(boundaries) if b <= i), None)
        if boundary is not None:
            distance = i - boundary
            if distance == 0:
                matrix[i, boundary] += 1.45
            elif distance <= 12:
                matrix[i, boundary] += (
                    2.55 * np.exp(-max(0, distance - 2) / 3.0)
                )

        # Special case: retain the initial comma once it is no longer local.
        # This also survives intervening quotation-ending punctuation.
        if first_comma is not None and i - first_comma >= 6:
            matrix[i, first_comma] += (
                0.90 * np.exp(-(i - first_comma - 6) / 80.0)
            )

    return "local_anchors_persistent_comma", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L1H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent comma-boundary sinks with local lexical binding.
    Articles, inflectional fragments, and opening quotes override the boundary prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "comma_sinks_with_local_binding", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    clean = [t.lstrip("▁Ġ") for t in tokens]
    special = set(tokenizer.all_special_tokens)
    apostrophes = {"'", "’"}
    quotes = {'"', "“", "”", "«", "»"}
    commas = []

    def linguistic_token(i):
        indices = alignment[i]
        if not indices:
            return None
        for k in indices:
            if not doc[k].is_space and not doc[k].is_punct:
                return doc[k]
        return doc[indices[0]]

    words = [linguistic_token(i) for i in range(n)]
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = clean[i]
        word = words[i]
        pos = word.pos_ if word is not None else ""

        # A declining BOS prior and a broad, mildly local causal background.
        bos_mass = 0.04 + 0.78 * np.exp(-0.32 * (i - 1))
        distances = i - np.arange(1, i + 1)
        local = np.exp(-distances / 4.0)
        local /= local.sum()
        background = np.zeros(n, dtype=np.float64)
        background[0] = bos_mass
        background[1:i + 1] = (1.0 - bos_mass) * (
            0.55 / i + 0.45 * local
        )
        row = background.copy()

        # Commas remain salient across clauses and even sentence boundaries.
        if commas:
            sink_weights = np.zeros(len(commas), dtype=np.float64)
            for k, j in enumerate(commas):
                sink_weights[k] = (
                    0.45 + 0.80 * np.exp(-(i - j) / 24.0)
                )
                if k == 0:
                    sink_weights[k] += 0.70
            sink_weights /= sink_weights.sum()

            sink_mass = 0.71
            if pos in {"PRON", "AUX"}:
                sink_mass = 0.59
            elif pos == "DET":
                sink_mass = 0.48
            row = (1.0 - sink_mass) * background
            for j, weight in zip(commas, sink_weights):
                row[j] += sink_mass * weight

        if text == ",":
            # A newly introduced boundary attracts its own query strongly.
            row *= 0.38
            row[i] += 0.62
            commas.append(i)
        elif text in {".", "!", "?", '."', '!"', '?"'}:
            self_mass = 0.56 if not commas else 0.29
            row *= 1.0 - self_mass
            row[i] += self_mass
        elif pos == "CCONJ":
            row *= 0.65
            row[i] += 0.35

        # Indefinite determiners bind to the immediately preceding context.
        if (
            word is not None
            and pos == "DET"
            and "Ind" in word.morph.get("Definite")
            and (not alignment[i] or i == 0
                 or not set(alignment[i]).intersection(alignment[i - 1]))
        ):
            strength = 0.75
            previous = words[i - 1]
            if previous is not None and previous.pos_ == "ADP":
                strength = 0.66
            elif i <= 3:
                strength = 0.83
            row *= 1.0 - strength
            row[i - 1] += strength

        # Apostrophes and possessive/clitic continuations bind locally.
        if text in apostrophes and tokens[i - 1] not in special:
            row *= 0.24
            row[i - 1] += 0.76
        elif (
            i >= 2
            and clean[i - 1] in apostrophes
            and text.isalnum()
            and not tokens[i].startswith(("▁", "Ġ"))
        ):
            strength = 0.88 if pos in {"PART", "AUX"} else 0.64
            row *= 1.0 - strength
            row[i - 2] += strength
        elif (
            text.isalnum()
            and not tokens[i].startswith(("▁", "Ġ", "##"))
            and clean[i - 1].isalnum()
            and tokens[i - 1] not in special
            and set(alignment[i]).intersection(alignment[i - 1])
        ):
            # Inflectional verb fragments are especially strong local binders.
            strength = 0.90 if pos in {"VERB", "AUX"} else 0.30
            row *= 1.0 - strength
            row[i - 1] += strength

        # An opening quotation mark often retrieves its reporting verb.
        if text in quotes and clean[i - 1] in {",", ":"}:
            target = None
            for j in range(i - 2, max(0, i - 10), -1):
                if clean[j] in {",", ".", "!", "?", ";"}:
                    break
                if words[j] is not None and words[j].pos_ == "VERB":
                    target = j
                    break
            if target is not None:
                while (
                    target > 1
                    and set(alignment[target]).intersection(
                        alignment[target - 1]
                    )
                ):
                    target -= 1
                row *= 0.22
                row[target] += 0.78

        attention[i] = row

    return (
        "comma_sinks_with_local_binding",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L1H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent comma sinks, with sentence-boundary resets in multi-sentence text.
    After an internal terminal, share boundary mass across surviving clause anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_comma_with_sentence_reset", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = []
    deps = []
    for indices in alignment:
        if indices:
            word = doc[indices[-1]]
            pos.append(word.pos_)
            deps.append(word.dep_)
        else:
            pos.append("")
            deps.append("")

    special = tokenizer.all_special_tokens
    clean = [t.lstrip("▁Ġ") for t in tokens]
    commas = []
    terminals = []
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = clean[i]
        is_comma = "," in text and all(
            c in ",\"'“”‘’ " for c in text
        )
        is_terminal = any(c in ".!?" for c in text) and all(
            c in ".!?\"'“”‘’ " for c in text
        )
        is_quote = bool(text) and all(c in "\"'“”‘’" for c in text)
        is_space = not text.strip() and tokens[i] not in special

        # The residual component favors the preceding one or two positions.
        local = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            distance = i - j
            if distance == 0:
                weight = 0.13
            else:
                weight = np.exp(-(distance - 1) / 2.4)
                if pos[j] == "DET":
                    weight *= 1.55
                elif pos[j] == "CCONJ":
                    weight *= 1.35
                elif pos[j] == "PUNCT":
                    weight *= 0.65
                if distance <= 3 and deps[j] in ("nsubj", "nsubjpass"):
                    weight *= 1.15
            local[j] = weight + 0.025 / (i + 1)

        if is_terminal:
            local[i] += 1.3
        if is_space:
            local[i - 1] += 1.0
        if is_quote:
            local[i - 1] += 0.5
        local /= local.sum()

        boundary = np.zeros(i + 1, dtype=np.float64)

        if not commas:
            # The first position is an especially strong BOS query.
            if i == 1:
                boundary_mass = 0.885
            else:
                boundary_mass = 0.22 + 0.32 * np.exp(-(i - 2) / 12.0)
                if pos[i] == "DET":
                    boundary_mass += 0.045
                if i == 2 and pos[i] in ("NOUN", "PROPN"):
                    if pos[i - 1] == "DET":
                        boundary_mass -= 0.075
                    else:
                        boundary_mass += 0.16
            if is_comma:
                boundary_mass *= 0.55
            if is_terminal:
                boundary_mass *= 0.65
            boundary[0] = boundary_mass
        else:
            first = commas[0]
            latest = commas[-1]
            distance = i - latest
            boundary_mass = 0.49 + 0.19 * np.exp(-distance / 17.0)

            if is_comma:
                boundary_mass = 0.24
            elif is_terminal:
                boundary_mass *= 0.72
            elif is_quote or is_space:
                boundary_mass *= 0.65

            bos_mass = 0.035
            boundary[0] = bos_mass

            if len(commas) == 1:
                boundary[first] += boundary_mass - bos_mass
            else:
                # Earlier commas remain salient across later clause boundaries.
                first_share = 0.48 + 0.12 * (
                    1.0 - np.exp(-distance / 12.0)
                )
                available = boundary_mass - bos_mass
                boundary[first] += available * first_share
                boundary[latest] += available * (1.0 - first_share) * 0.88
                middle = commas[1:-1]
                if middle:
                    for j in middle:
                        boundary[j] += available * (1.0 - first_share) * 0.12 / len(middle)
                else:
                    boundary[latest] += available * (1.0 - first_share) * 0.12

        # Only subsequent queries activate the sentence-reset exception.
        # Redistribute boundary mass without changing its total or the local
        # component, so the original diagonal attention remains unchanged.
        if terminals and commas:
            total = boundary.sum()
            previous_terminal = terminals[-1]
            terminal_share = 0.28 * np.exp(
                -(i - previous_terminal - 1) / 24.0
            )
            bos_share = 0.18

            anchor_weights = np.array([
                (0.45 ** sum(t > j for t in terminals))
                * (0.05 + 0.95 * (1.0 - np.exp(-(i - j) / 12.0)))
                for j in commas
            ], dtype=np.float64)
            anchor_weights /= anchor_weights.sum()

            boundary.fill(0.0)
            boundary[0] = total * bos_share
            boundary[previous_terminal] += total * terminal_share
            remaining = total * (1.0 - bos_share - terminal_share)
            for j, weight in zip(commas, anchor_weights):
                boundary[j] += remaining * weight

        mass = boundary.sum()
        attention[i, :i + 1] = boundary + (1.0 - mass) * local

        # Punctuation becomes an anchor only for subsequent queries.
        if is_comma:
            commas.append(i)
        if is_terminal:
            terminals.append(i)

    return "persistent_comma_with_sentence_reset", make_row_stochastic(attention)


def prog_L1H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent comma anchors dominate; without commas, attention favors self
    and earlier grammatical anchors, with a weak beginning-of-sequence sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_comma_and_grammatical_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    positions = []
    dependencies = []
    continuations = []
    commas = []
    for j, token in enumerate(tokens):
        aligned = alignment[j]
        word = doc[aligned[0]] if aligned else None
        positions.append(word.pos_ if word is not None else "")
        dependencies.append(word.dep_ if word is not None else "")
        continuations.append(
            j > 0
            and bool(aligned)
            and bool(alignment[j - 1])
            and aligned[0] == alignment[j - 1][0]
        )
        commas.append("," in token and token not in special_tokens)

    first_content = 0
    while first_content < n and tokens[first_content] in special_tokens:
        first_content += 1

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        query_pos = positions[i]
        for j in range(i + 1):
            distance = i - j
            pos = positions[j]
            decay = np.exp(-distance / 19.0)

            weight = 0.055 * np.exp(-distance / 24.0)
            if j == 0:
                weight += 0.65
            elif tokens[j] not in special_tokens:
                if j == first_content:
                    weight += 0.90 * np.exp(-distance / 13.0)
                if pos == "DET":
                    weight += 0.85 * decay
                elif pos == "CCONJ":
                    weight += 1.35 * np.exp(-distance / 16.0)
                elif pos == "SCONJ":
                    weight += 0.55 * decay
                elif pos == "AUX":
                    weight += 0.30 * decay
                elif pos == "PRON":
                    weight += 0.24 * decay

                if continuations[j]:
                    weight *= 0.40

            if commas[j]:
                # Commas remain available across sentence boundaries; newer
                # commas compete with rather than replace earlier anchors.
                weight += (
                    11.5
                    * np.exp(-j / 27.0)
                    / (1.0 + distance / 38.0)
                )
                if 1 <= distance <= 4 and query_pos in (
                    "VERB", "AUX", "ADV", "ADJ"
                ):
                    weight *= 1.16
                if query_pos == "PUNCT" and j != i:
                    weight *= 0.70

            if j == i and not commas[j]:
                diagonal = 0.55
                if query_pos == "DET":
                    diagonal = 1.50
                elif query_pos == "AUX":
                    diagonal = 1.20
                elif query_pos in ("VERB", "PROPN"):
                    diagonal = 1.05
                elif query_pos in ("PRON", "SCONJ"):
                    diagonal = 0.85
                elif query_pos == "CCONJ":
                    diagonal = 0.65
                elif query_pos == "PUNCT":
                    diagonal = 0.90
                elif query_pos in ("ADJ", "ADV"):
                    diagonal = 0.38

                if dependencies[i] in ("nsubj", "nsubjpass"):
                    diagonal += 0.15
                if continuations[i]:
                    diagonal *= 0.35
                if i == first_content:
                    diagonal = (
                        2.55 if query_pos in ("PRON", "DET") else
                        1.35 if query_pos == "ADP" else 0.90
                    )
                weight += diagonal

            matrix[i, j] = weight

    return (
        "persistent_comma_and_grammatical_anchors",
        make_row_stochastic(matrix),
    )


def prog_L1H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Comma-free clauses favor nearby phrase onsets over persistent BOS sinks.
    Otherwise retain the original comma-sink and syntactic-onset behavior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "comma_sink_with_comma_free_onsets", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                inverse[wi].append(ti)

    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
    comma_free = not any("," in t for t in clean)
    commas = []
    terminals = []

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        row = matrix[i]
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        if i == 1:
            bos_weight = 1.5
            if word is not None:
                if word.pos_ == "DET":
                    bos_weight = 1.42
                elif word.pos_ == "PROPN":
                    bos_weight = 3.8
                elif word.pos_ in ("ADP", "ADV", "SCONJ", "NUM"):
                    bos_weight = 3.2
            row[0] = bos_weight
            row[i] = 1.0
        else:
            row[0] = (1.45 if not commas else 0.75) * np.exp(-i / 160.0)
            row[i] = 0.65
            for j in range(max(1, i - 10), i):
                row[j] += 0.13 * np.exp(-(i - j - 1) / 3.0)
            row[i - 1] += 0.30

        # The earliest comma remains a sink even across subsequent quotations.
        for rank, j in enumerate(commas):
            distance = i - j
            if rank == 0:
                weight = 5.5 / ((1.0 + distance / 14.0) ** 0.24)
            else:
                weight = 4.2 / ((1.0 + distance / 5.0) ** 0.60)
            row[j] += weight

        for j in terminals:
            distance = i - j
            if distance <= 5:
                row[j] += 2.0 * np.exp(-(distance - 1) / 2.0)

        if word is not None and i > 1:
            # Function words often look back to the local predicate rather
            # than following their ordinary dependency head forward.
            if word.pos_ in ("ADP", "PART", "SCONJ", "DET", "PRON", "AUX"):
                candidates = []
                head_ids = inverse[word.head.i]
                if head_ids:
                    anchor = head_ids[0]
                    if 0 < anchor < i and i - anchor <= 9:
                        if word.head.pos_ in ("VERB", "AUX", "ADJ"):
                            candidates.append(anchor)

                if word.pos_ in ("ADP", "PART", "SCONJ"):
                    for wi in range(word.i - 1, max(-1, word.i - 6), -1):
                        previous = doc[wi]
                        if previous.is_punct:
                            break
                        if previous.pos_ in ("VERB", "AUX", "ADJ"):
                            ids = inverse[wi]
                            if ids and 0 < ids[0] < i:
                                candidates.append(ids[0])
                            break

                if candidates:
                    anchor = max(candidates)
                    strength = 5.3 if word.pos_ in ("ADP", "PART", "SCONJ") else 2.0
                    row[anchor] += strength

            # Copular predicates sometimes select the beginning of the subject.
            if word.pos_ == "AUX":
                predicate = word.head
                subjects = [
                    child for child in predicate.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                    and child.i < word.i
                ]
                for subject in subjects:
                    onset = subject
                    for child in subject.children:
                        if child.dep_ in ("det", "poss") and child.i < onset.i:
                            onset = child
                    ids = inverse[onset.i]
                    if ids and 0 < ids[0] < i:
                        row[ids[0]] += 3.2

            # Coordinators provide a weaker local clause-start anchor.
            if word.pos_ in ("VERB", "AUX", "PRON"):
                for wi in range(word.i - 1, max(-1, word.i - 5), -1):
                    previous = doc[wi]
                    if previous.is_punct:
                        break
                    if previous.pos_ == "CCONJ":
                        ids = inverse[wi]
                        if ids and 0 < ids[0] < i:
                            row[ids[0]] += 2.4
                        break

        # Special case: without comma sinks, distribute attention over the
        # preceding phrase rather than concentrating on BOS or one predicate.
        # Punctuation rows and all comma-containing inputs remain unchanged.
        if comma_free and i > 1 and word is not None and not word.is_punct:
            row[0] *= 0.25
            row[1:i] = np.minimum(row[1:i], 2.0)
            for lag, strength in enumerate((0.65, 1.55, 1.05, 0.45), start=1):
                wi = word.i - lag
                if wi < 0 or doc[wi].is_punct:
                    break
                ids = inverse[wi]
                if not ids or not (0 < ids[0] < i):
                    continue
                previous = doc[wi]
                if previous.pos_ in (
                    "DET", "ADP", "PART", "SCONJ", "CCONJ", "PRON", "AUX"
                ):
                    strength += 0.65
                row[ids[0]] += strength

        is_comma = "," in clean[i]
        is_terminal = any(mark in clean[i] for mark in (".", "!", "?"))
        if is_comma:
            row[i] += 8.0 if not commas else 6.0
            commas.append(i)
        elif is_terminal:
            row[i] += 7.5
            terminals.append(i)

    return "comma_sink_with_comma_free_onsets", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L1H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with local linguistic continuity.
    Attached suffixes bridge an intervening apostrophe to the preceding stem.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "previous_token_with_apostrophe_bridge", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        current_ids = alignment[i]
        previous_ids = alignment[i - 1]
        current = doc[current_ids[-1]] if current_ids else None
        previous = doc[previous_ids[-1]] if previous_ids else None

        previous_mass = 0.76
        self_mass = 0.08

        if current is not None and previous is not None:
            cp, pp = current.pos_, previous.pos_

            if set(current_ids).intersection(previous_ids):
                # Subword continuation within the same linguistic token.
                previous_mass = 0.79
            elif cp == "ADJ" and pp in ("DET", "ADJ", "ADV"):
                previous_mass = 0.90
            elif cp in ("NOUN", "PROPN") and pp in ("DET", "ADJ", "NUM"):
                previous_mass = 0.85
            elif cp in ("ADJ", "ADV") and pp in ("AUX", "VERB"):
                previous_mass = 0.88
            elif cp == "VERB" and pp in ("AUX", "PART"):
                previous_mass = 0.85
            elif cp == "PRON" and pp in ("VERB", "AUX", "SCONJ", "CCONJ"):
                previous_mass = 0.85
            elif cp in ("DET", "PRON", "NUM") and pp == "ADP":
                previous_mass = 0.83
            elif cp == "VERB" and pp == "CCONJ":
                previous_mass = 0.81
            elif cp in ("ADP", "CCONJ", "AUX"):
                previous_mass = 0.65
            elif (
                current.head.i == previous.i
                or previous.head.i == current.i
            ):
                previous_mass = 0.80

        surface = tokens[i].replace("▁", "").replace("Ġ", "")
        is_punctuation = (
            bool(surface)
            and all(not c.isalnum() and not c.isspace() for c in surface)
            and tokens[i] not in special_tokens
        )

        if is_punctuation:
            previous_mass = 0.28
            self_mass = 0.55
        elif not surface.strip():
            previous_mass = 0.75
        elif previous is not None and previous.is_punct:
            previous_mass = max(previous_mass, 0.76)

        # The first ordinary token has an especially strong BOS link.
        if i == 1:
            previous_mass = 0.92
            self_mass = 0.06

        remainder = 1.0 - previous_mass - self_mass
        attention[i, i - 1] += previous_mass
        attention[i, i] += self_mass
        attention[i, 0] += 0.75 * remainder

        distances = i - np.arange(i)
        background = np.exp(-distances / 2.0)
        background /= background.sum()
        attention[i, :i] += 0.25 * remainder * background

        # An attached suffix often looks past the apostrophe to the stem.
        # Transfer only predecessor mass; preserve self and background weights.
        if (
            i >= 2
            and tokens[i] not in special_tokens
            and tokens[i - 2] not in special_tokens
            and not tokens[i].startswith(("▁", "Ġ"))
            and surface.isalpha()
            and tokens[i - 1] in ("'", "’", "ʼ")
            and any(c.isalnum() for c in tokens[i - 2])
        ):
            bridge_mass = 0.65 * previous_mass
            attention[i, i - 1] -= bridge_mass
            attention[i, i - 2] += bridge_mass

    return (
        "previous_token_with_apostrophe_bridge",
        make_row_stochastic(attention),
    )


def prog_L1H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Retain BOS/early anchors; quoted or nominal-possessive discourse also
    retrieves noun-phrase onsets, objects, and clause predicates."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_early_discourse_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    words = []
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if 0 <= k < len(doc)]
        word = None
        if tokens[i] not in special and valid:
            # Prefer a lexical token when an offset overlaps punctuation too.
            word = doc[valid[0]]
            for k in valid:
                inverse[k].append(i)
                if word.is_punct and not doc[k].is_punct:
                    word = doc[k]
        words.append(word)

    first_piece = [
        word is not None
        and bool(inverse[word.i])
        and i == inverse[word.i][0]
        for i, word in enumerate(words)
    ]
    subjects = {"nsubj", "nsubjpass", "csubj", "csubjpass"}
    quotes = {'"', "'", "“", "”", "‘", "’", "«", "»"}
    boundaries = {",", ";", ":", ".", "!", "?"}

    # Restrict the extra retrieval path to quotation/nominal-possessive discourse.
    # Pronominal possessives alone do not activate it.
    discourse = any(c in {'"', "“", "”", "«", "»"} for c in sentence) or any(
        word.dep_ == "poss" and word.pos_ in {"NOUN", "PROPN"}
        for word in doc
    )
    discourse_weights = np.zeros(n, dtype=np.float64)
    if discourse:
        for j in range(1, n):
            word = words[j]
            if word is None or not first_piece[j]:
                continue
            if word.pos_ == "DET" or (
                word.pos_ == "PRON" and word.dep_ == "poss"
            ):
                discourse_weights[j] = 0.65 * np.exp(-j / 55.0)
            elif word.pos_ in {"NOUN", "PROPN"} and word.dep_ in {
                "poss", "dobj", "obj", "pobj", "iobj"
            }:
                discourse_weights[j] = 1.10 * np.exp(-j / 55.0)
            elif word.pos_ == "ADJ" and word.dep_ in {"acomp", "attr", "oprd"}:
                discourse_weights[j] = 0.95 * np.exp(-j / 18.0)
            elif word.pos_ == "VERB" and any(
                child.dep_ in {"ccomp", "parataxis"} for child in word.children
            ):
                discourse_weights[j] = 0.85 * np.exp(-j / 55.0)

    key_weights = np.zeros(n, dtype=np.float64)
    for j in range(1, n):
        word = words[j]
        early = np.exp(-j / 18.0)
        key_weights[j] = 0.10 + 0.15 * early

        if word is None:
            continue
        if first_piece[j]:
            if word.pos_ == "NOUN" and word.dep_ in subjects:
                key_weights[j] += 1.65 * early
            elif word.pos_ == "PRON" and word.dep_ in subjects:
                key_weights[j] += 0.45 * early
            elif word.pos_ == "PROPN" and word.dep_ in subjects:
                key_weights[j] += 0.22 * early
            elif word.pos_ in {"VERB", "AUX"}:
                key_weights[j] += 0.36 * early
            elif word.pos_ in {"ADJ", "ADV"}:
                key_weights[j] += 0.20 * early

        if any(c in boundaries for c in word.text):
            key_weights[j] += 2.0 * np.exp(-j / 55.0)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        row = attention[i]
        row[:i + 1] = key_weights[:i + 1]

        # A nearly fixed sink competes with an increasing number of keys.
        row[0] = 2.65

        self_weight = 0.95
        if word is not None:
            if word.pos_ == "PRON":
                self_weight = 1.65
            elif word.pos_ == "PROPN":
                self_weight = 0.55
            elif word.pos_ == "ADP":
                self_weight = 0.45
            elif word.pos_ == "NOUN" and word.dep_ in subjects:
                self_weight = 1.25
            if not first_piece[i]:
                self_weight *= 0.70

        row[i] += self_weight

        # Lexical category controls the strong first-token BOS/self split.
        if i == 1:
            row[i] = self_weight
            if word is not None and word.pos_ == "PRON":
                row[i] = 1.95
            elif word is not None and word.pos_ == "DET":
                row[i] = 0.92

        if i > 1:
            row[i - 1] += 0.24
            if word is not None and word.is_punct:
                row[i - 1] += 0.62

        if word is not None:
            # Retain a modest causal link to the syntactic governor.
            head = word.head
            if head.i != word.i and inverse[head.i]:
                j = inverse[head.i][0]
                if 0 < j <= i:
                    row[j] += 0.40

            # Subword pieces can still retrieve the word's initial piece.
            if not first_piece[i] and inverse[word.i]:
                j = inverse[word.i][0]
                if 0 < j < i:
                    row[j] += 0.32

            # Opening quotation marks often retrieve a nearby reporting verb.
            if any(c in quotes for c in word.text):
                for j in range(i - 1, max(0, i - 9), -1):
                    previous = words[j]
                    if previous is not None and previous.pos_ == "VERB":
                        row[j] += 1.60
                        break

        # Add only past-key anchors; leave the original raw self/BOS weights intact.
        if discourse:
            row[1:i] += discourse_weights[1:i]

    return (
        "bos_early_discourse_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L2H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary sinks with local attention; dialogue additionally favors quote
    boundaries and broader context rather than a persistent pre-quote comma.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_sink_quote_context", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    pos = [""] * n
    dep = [""] * n
    word = [-1] * n
    clean = [t.lstrip("▁Ġ").strip() for t in tokens]

    for i, indices in enumerate(alignment):
        for k in indices:
            if k < len(doc) and not doc[k].is_space:
                word[i] = k
                pos[i] = doc[k].pos_
                dep[i] = doc[k].dep_
                break

    has_bos = tokens[0] in special
    first = 1 if has_bos else 0
    commas = []
    endings = []
    quotes = []
    function_positions = []
    function_pos = {"DET", "ADP", "AUX", "CCONJ", "SCONJ"}
    quote_chars = "\"'“”‘’«»"

    # Include fused closing punctuation and fragmented, non-ASCII quote symbols.
    dialogue_boundaries = set()
    for j, text in enumerate(clean):
        if tokens[j] in special or not text:
            continue
        if (
            any(c in quote_chars for c in text)
            and not any(c.isalnum() for c in text)
            and dep[j] != "case"
            and pos[j] not in {"PART", "AUX"}
        ):
            dialogue_boundaries.add(j)
        elif pos[j] == "SYM" and all(ord(c) > 127 for c in text):
            start = j
            while (
                start > first
                and clean[start - 1]
                and tokens[start - 1] not in special
                and all(ord(c) > 127 for c in clean[start - 1])
            ):
                start -= 1
            dialogue_boundaries.add(start)

    first_quote = min(dialogue_boundaries) if dialogue_boundaries else n

    for i in range(n):
        text = clean[i]
        is_special = tokens[i] in special
        is_comma = not is_special and "," in text
        is_ending = (
            not is_special
            and any(c in text for c in ".!?;:")
            and (pos[i] == "PUNCT" or not any(c.isalnum() for c in text))
        )
        is_quote = (
            not is_special
            and bool(text)
            and all(c in quote_chars for c in text)
            and dep[i] != "case"
            and pos[i] not in {"PART", "AUX"}
        )
        continuation = (
            i > first and word[i] >= 0 and word[i] == word[i - 1]
        )

        if is_comma:
            commas.append(i)
        if is_ending:
            endings.append(i)
        if is_quote:
            quotes.append(i)
        if pos[i] in function_pos and not continuation:
            function_positions.append(i)

        distance = i - np.arange(i + 1)
        row = 0.018 + 0.085 * np.exp(-distance / 9.0)
        row[i] += 0.88 if not continuation else 0.64

        if i > first:
            row[i - 1] += 0.86 if not continuation else 0.38
            if pos[i - 1] in {"VERB", "AUX"} and not continuation:
                row[i - 1] += 0.30

        if has_bos:
            initial_strength = 1.85
            if first < n:
                if pos[first] == "DET":
                    initial_strength = 1.15
                elif pos[first] in {"ADP", "SCONJ"}:
                    initial_strength = 1.55
            row[0] += initial_strength / (1.0 + 0.40 * max(0, i - first))

        if first <= i and i > first:
            row[first] += 0.24 * np.exp(-(i - first - 1) / 5.0)

        for j in function_positions:
            if j >= i:
                continue
            d = i - j
            strength = 0.78 if pos[j] in {"DET", "CCONJ", "SCONJ"} else 0.48
            row[j] += strength * np.exp(-(d - 1) / 4.0)

        if continuation:
            start = i
            while start > first and word[start - 1] == word[i]:
                start -= 1
            if start > first:
                j = start - 1
                row[j] += 0.90 if pos[j] in function_pos else 0.40

        for rank, j in enumerate(commas):
            d = i - j
            strength = 2.35 if rank == 0 else 1.50
            row[j] += strength * np.exp(-d / 20.0)

        for j in endings:
            d = i - j
            row[j] += 2.25 * np.exp(-d / 2.5)
            if d == 0:
                row[j] += 0.35

        for j in quotes:
            d = i - j
            row[j] += 1.40 * np.exp(-d / 1.8)

        if is_comma and len(commas) == 1:
            row[i] += 0.15

        # Leave non-dialogue rows and every raw self-attention weight unchanged.
        if i >= first_quote:
            row[:i] += 0.10 * np.exp(-distance[:i] / 18.0)
            if has_bos:
                row[0] += 0.45

            for rank, j in enumerate(commas):
                if j < first_quote and j < i:
                    strength = 2.35 if rank == 0 else 1.50
                    row[j] -= 0.70 * strength * np.exp(-(i - j) / 20.0)

            for j in dialogue_boundaries:
                if j < i:
                    row[j] += 3.0 * np.exp(-(i - j - 1) / 2.5)

            for j in function_positions:
                if j < i and pos[j] == "CCONJ":
                    row[j] += 0.65 * np.exp(-(i - j) / 45.0)

            for j in range(max(first, i - 5), i - 1):
                if pos[j] in {"VERB", "NOUN", "PROPN", "ADJ", "ADV"}:
                    row[j] += 0.32

        matrix[i, :i + 1] = row

    return "boundary_sink_quote_context", make_row_stochastic(matrix)


def prog_L2H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-word attention with local syntactic gating.
    Commas additionally act as persistent clause-boundary anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "previous_word_with_comma_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    owners = [None] * n
    first_piece = {}
    for i, indices in enumerate(alignment):
        if tokens[i] in special:
            continue
        valid = [k for k in indices if 0 <= k < len(doc)]
        if valid:
            k = valid[-1]
            owners[i] = k
            if k not in first_piece:
                first_piece[k] = i

    last_comma = None
    attention[0, 0] = 1.0
    for i in range(1, n):
        if (
            tokens[i - 1] not in special
            and tokens[i - 1].replace("▁", "").replace("Ġ", "").strip() == ","
        ):
            last_comma = i - 1

        current_id = owners[i]
        current = doc[current_id] if current_id is not None else None
        text = tokens[i].replace("▁", "").replace("Ġ", "")
        whitespace = not text.strip() and tokens[i] not in special
        punctuation = (
            current is not None and current.is_punct
        ) or (
            bool(text.strip())
            and all(not c.isalnum() and not c.isspace() for c in text)
            and tokens[i] not in special
        )

        start = first_piece.get(current_id, i)
        continuation = start < i and not punctuation
        anchor = max(0, start - 1) if continuation else i - 1

        # Contraction fragments should look past the intervening apostrophe.
        while anchor > 0:
            previous_text = tokens[anchor].replace("▁", "").replace("Ġ", "")
            if previous_text and all(c in "'’" for c in previous_text):
                anchor -= 1
            else:
                break

        previous_id = owners[anchor]
        previous = doc[previous_id] if previous_id is not None else None
        pos = current.pos_ if current is not None else ""
        previous_pos = previous.pos_ if previous is not None else ""

        if i == 1 and tokens[0] in special:
            bos_mass = 0.71
            if pos == "DET":
                bos_mass = 0.566
            elif pos == "ADP":
                bos_mass = 0.65
            elif pos == "PROPN":
                bos_mass = 0.82
            attention[i, 0] = bos_mass
            attention[i, i] = 1.0 - bos_mass
            continue

        anchor_mass = 0.52
        self_mass = 0.18

        if pos in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
            anchor_mass, self_mass = 0.34, 0.27
        elif pos in ("NOUN", "PROPN", "ADJ", "VERB", "AUX", "ADV"):
            anchor_mass = 0.55

        if previous_pos in ("DET", "ADP", "PART"):
            if pos in ("NOUN", "PROPN", "ADJ", "VERB"):
                anchor_mass, self_mass = 0.55, 0.17

        if previous_pos == "PRON" and pos in ("VERB", "AUX"):
            anchor_mass, self_mass = 0.66, 0.14
            if anchor == 1:
                anchor_mass, self_mass = 0.81, 0.10

        if previous_pos in ("NOUN", "PROPN") and pos in ("VERB", "AUX"):
            anchor_mass, self_mass = 0.57, 0.19

        if previous_pos == "CCONJ" and not punctuation:
            anchor_mass, self_mass = 0.69, 0.14

        if previous is not None and previous.is_punct and not punctuation:
            anchor_mass, self_mass = 0.61, 0.18

        if whitespace:
            anchor_mass, self_mass = 0.45, 0.27
        elif punctuation:
            anchor_mass, self_mass = 0.23, 0.46
        elif continuation:
            anchor_mass, self_mass = 0.53, 0.15

        # The residual is a short left-context tail rather than a distant
        # dependency search. It also captures two-token phrase boundaries.
        residual = 1.0 - anchor_mass - self_mass
        background = np.zeros(i + 1, dtype=np.float64)
        for j in range(i):
            if j != anchor:
                background[j] = np.exp(-0.65 * abs(anchor - j))

        if continuation and start != anchor:
            background[start] += 0.65

        if tokens[0] in special and anchor != 0:
            background[0] += 0.12

        attention[i, anchor] += anchor_mass
        attention[i, i] += self_mass
        total = background.sum()
        if total > 0:
            attention[i, :i + 1] += residual * background / total
        else:
            attention[i, i] += residual

        # Only after a comma: reserve a persistent boundary contribution.
        # Transfer exclusively from other past positions, preserving self mass
        # and leaving already-strong comma attention unchanged.
        if last_comma is not None and tokens[i] not in special:
            target = 0.16 + 0.30 * np.exp(
                -0.45 * (i - last_comma - 1)
            )
            existing = attention[i, last_comma]
            donors = attention[i, :i].copy()
            donors[last_comma] = 0.0
            available = donors.sum()
            if existing < target and available > 0.0:
                transfer = min(target - existing, available)
                attention[i, :i] -= (transfer / available) * donors
                attention[i, last_comma] += transfer

    return (
        "previous_word_with_comma_anchor",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L2H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous completed-word attention, strengthened at syntactic boundaries.
    Punctuation and function words look backward, with diffuse self/BOS fallback.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "previous_word_syntactic_boundary", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    specials = tokenizer.all_special_tokens

    # Associate each subtoken with its most substantially overlapping word.
    word_ids = []
    for i in range(n):
        candidates = alignment[i]
        word_ids.append(
            max(candidates, key=lambda k: len(doc[k].text))
            if candidates and tokens[i] not in specials else -1
        )

    matrix[0, 0] = 1.0
    for i in range(1, n):
        distances = i - np.arange(i + 1, dtype=np.float64)
        background = np.exp(-distances / 3.5)
        background[i] += 0.9
        background[0] += 0.8
        background /= background.sum()

        current_id = word_ids[i]
        current = doc[current_id] if current_id >= 0 else None
        previous_id = word_ids[i - 1]
        previous = doc[previous_id] if previous_id >= 0 else None

        target = i - 1
        strength = 0.22

        # Find the nearest preceding non-punctuation word's final subtoken.
        lexical_target = i - 1
        lexical_word = previous
        for j in range(i - 1, 0, -1):
            sid = word_ids[j]
            if sid >= 0 and not doc[sid].is_punct and not doc[sid].is_space:
                lexical_target = j
                lexical_word = doc[sid]
                break

        continuation = (
            current_id >= 0
            and previous_id == current_id
            and current is not None
            and not current.is_punct
        )

        if i == 1:
            target = 0
            strength = 0.48
        elif continuation:
            # Within-word pieces are less sharply backward-looking.
            strength = 0.08
        elif current is not None and current.is_space:
            strength = 0.26
        elif current is not None and current.is_punct:
            target = lexical_target
            if "," in current.text:
                strength = 0.65
            elif any(c in current.text for c in ("'", "’")):
                strength = 0.43
            elif any(c in current.text for c in ('"', "“", "”")):
                strength = 0.31
            else:
                strength = 0.25
        elif current is not None and lexical_word is not None:
            cp = current.pos_
            pp = lexical_word.pos_
            target = lexical_target

            if cp == "CCONJ":
                strength = 0.62
            elif cp in ("ADP", "SCONJ"):
                strength = 0.48
            elif cp in ("VERB", "AUX") and pp in ("NOUN", "PROPN", "PRON"):
                strength = 0.57
                if cp == "AUX" and pp in ("NOUN", "PROPN"):
                    strength = 0.67
            elif cp == "PRON" and pp in ("NOUN", "PROPN", "ADJ"):
                strength = 0.49
            elif current.dep_ in ("relcl", "mark"):
                strength = 0.43
            elif cp == "PART" and current.dep_ == "case":
                strength = 0.56
            elif cp == "PART" and pp in ("NOUN", "PROPN", "PRON"):
                strength = 0.36
            elif cp in ("DET", "PRON") and previous is not None and previous.is_punct:
                strength = 0.40
            elif cp in ("NOUN", "PROPN") and pp in ("DET", "ADJ", "NUM"):
                target = i - 1
                strength = 0.10
            else:
                target = i - 1
                strength = 0.16

            # Local subject-to-predicate transitions are especially strong.
            if cp in ("VERB", "AUX"):
                for child in current.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        positions = [
                            j for j in inverse[child.i]
                            if 0 < j < i
                        ]
                        if positions:
                            candidate = max(positions)
                            if i - candidate <= 3:
                                target = candidate
                                strength = max(strength, 0.53)

        # Explicit whitespace pieces preserve the preceding punctuation anchor.
        if tokens[i].strip("▁Ġ \t\r\n") == "":
            target = i - 1
            strength = 0.28

        matrix[i, :i + 1] = (1.0 - strength) * background
        matrix[i, target] += strength

    return (
        "previous_word_syntactic_boundary",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L2H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local lexical anchoring, with skipped function-word phrase anchors
    and a persistent comma anchor beyond the short punctuation window."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_phrase_anchors", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    pos = []
    punctuation = []
    apostrophe = []
    starts = []
    clean_tokens = []

    for i, token in enumerate(tokens):
        clean = token.lstrip("▁Ġ")
        clean_tokens.append(clean)
        is_special = token in specials
        is_punct = (
            not is_special
            and bool(clean)
            and all(not c.isalnum() and not c.isspace() for c in clean)
        )
        punctuation.append(is_punct)
        apostrophe.append(clean in ("'", "’"))

        sids = aligned[i] if i < len(aligned) else []
        words = [doc[k] for k in sids if k < len(doc)]
        lexical = [w for w in words if not w.is_punct and not w.is_space]
        representative = lexical[0] if lexical else (words[0] if words else None)
        pos.append(representative.pos_ if representative is not None else "")

        boundary = token.startswith(("▁", "Ġ"))
        if i < len(spans):
            s, e = spans[i]
            if 0 <= s < len(sentence):
                boundary = boundary or sentence[s].isspace()
                boundary = boundary or (s > 0 and sentence[s - 1].isspace())

        if i == 0 or is_special:
            start = i
        elif tokens[i - 1] in specials:
            start = i
        elif is_punct:
            start = starts[i - 1] if apostrophe[i] else i
        elif boundary or (punctuation[i - 1] and not apostrophe[i - 1]):
            start = i
        else:
            start = starts[i - 1]
        starts.append(start)

    function_pos = {"DET", "ADP", "PART", "AUX", "PRON"}
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV", "NUM"}

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        distance = i - np.arange(i + 1)
        matrix[i, :i + 1] = 0.025 + 0.065 * np.exp(-distance / 28.0)

        if tokens[i] in specials:
            matrix[i, i] += 3.0
            continue

        previous = i - 1
        onset = starts[i]
        continuation = onset < i and not punctuation[i]

        if continuation:
            matrix[i, onset] += 5.0
            matrix[i, i] += 1.65
            if previous != onset:
                matrix[i, previous] += 0.35
        else:
            self_weight = 2.65 if pos[i] in content_pos else 1.45
            previous_weight = 1.65

            if pos[i] in function_pos:
                self_weight = 1.15
                previous_weight = 2.75
            elif pos[i] in {"CCONJ", "SCONJ"}:
                self_weight = 2.15
                previous_weight = 1.2

            if punctuation[i]:
                self_weight = 2.7
                previous_weight = 0.7

            matrix[i, i] += self_weight
            matrix[i, previous] += previous_weight

            if starts[previous] != previous:
                matrix[i, starts[previous]] += 0.65

        # Clause boundaries remain salient for a few following tokens.
        for j in range(max(0, i - 7), i):
            if punctuation[j] and not apostrophe[j]:
                strength = 2.5 if clean_tokens[j] in (",", ";", ":") else 1.25
                matrix[i, j] += strength * np.exp(-(i - j - 1) / 2.8)

        # A function word can anchor a phrase across intervening lexical
        # material; do not duplicate the existing immediately previous anchor.
        phrase_anchors = [
            j for j in range(max(0, onset - 4), onset - 1)
            if starts[j] == j
            and tokens[j] not in specials
            and not punctuation[j]
            and pos[j] in function_pos | {"CCONJ", "SCONJ"}
            and not any(punctuation[k] and not apostrophe[k]
                        for k in range(j + 1, onset))
        ]
        if phrase_anchors:
            for j in phrase_anchors:
                matrix[i, j] += 2.4 if j == phrase_anchors[-1] else 0.8
            if i <= 7 and tokens[0] in specials:
                matrix[i, 0] += 0.85

        # Commas remain discourse anchors after the local window expires.
        distant_commas = [
            j for j in range(max(0, i - 64), i - 7)
            if punctuation[j] and clean_tokens[j] == ","
        ]
        if distant_commas:
            j = distant_commas[-1]
            matrix[i, j] += 1.8 * np.exp(-(i - j - 8) / 40.0)

        # Early queries have little competing context; the first word is
        # predominantly self-focused rather than a strong BOS-attending query.
        if i == 1 and tokens[0] in specials:
            matrix[i, :] = 0.0
            matrix[i, 0] = 0.30
            matrix[i, i] = 0.70

    return "local_phrase_anchors", make_row_stochastic(matrix)


def prog_L2H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early clause-scaffolding tokens can share the sink's mass.
    In dialogue, these anchors also absorb excess quoted-boundary attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_and_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    punctuation = np.zeros(n, dtype=np.int8)
    whitespace = np.zeros(n, dtype=bool)
    continuation = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        if token in special_tokens:
            continue

        clean = token.lstrip("▁Ġ")
        whitespace[i] = not clean.strip()

        if alignment[i]:
            word = doc[alignment[i][0]]
            pos[i] = word.pos_
            dep[i] = word.dep_
            if i > 0 and alignment[i - 1]:
                continuation[i] = alignment[i - 1][0] == alignment[i][0]

        if any(char in clean for char in ".!?"):
            punctuation[i] = 2
        elif any(char in clean for char in ",;:"):
            punctuation[i] = 1

    sink = 0
    first = 1 if tokens[0] in special_tokens else 0
    initial_determiner = first < n and pos[first] == "DET"

    # Only activate for compact subject-predicate openings with an early
    # auxiliary or a following grammatical clause/noun-phrase anchor.
    early_predicates = [
        j for j in range(first, min(n, first + 3))
        if pos[j] in ("VERB", "AUX") and not continuation[j]
    ]
    clause_anchors = []
    if early_predicates:
        predicate = early_predicates[0]
        if pos[predicate] == "AUX":
            clause_anchors.append(predicate)
        for j in range(predicate + 1, min(n, first + 5)):
            if not continuation[j] and pos[j] in ("DET", "SCONJ", "CCONJ"):
                clause_anchors.append(j)

    quoted_boundary = np.zeros(n, dtype=bool)
    if clause_anchors:
        for j in range(n):
            if punctuation[j]:
                nearby = tokens[j:min(n, j + 2)]
                quoted_boundary[j] = any(
                    any(char in token for char in '"“”') for token in nearby
                )

    for i in range(n):
        distances = i - np.arange(i + 1, dtype=np.float64)

        # A diffuse causal background, with only a modest preference for recency.
        weights = 0.75 + 0.45 * np.exp(-distances / 5.0)
        weights[-1] *= 0.85

        # Word-internal pieces are not the main target of this head.
        for j in range(1, i + 1):
            if continuation[j]:
                weights[j] *= 0.72
            if whitespace[j]:
                weights[j] *= 0.55

        # Boundary attraction ramps up after the boundary rather than peaking
        # exclusively on its immediately following token.
        for j in range(first, i + 1):
            if not punctuation[j]:
                continue
            distance = i - j
            ramp = 0.40 + 0.60 * (1.0 - np.exp(-distance / 1.8))
            if punctuation[j] == 2:
                strength, horizon = 8.5, 32.0
            else:
                strength, horizon = 7.0, 22.0
            weights[j] += strength * ramp * np.exp(-distance / horizon)

        # An opening determiner behaves like a secondary prefix anchor.
        if initial_determiner and i >= first:
            weights[first] += 3.6 * np.exp(-(i - first) / 22.0)

        if pos[i] in ("NOUN", "PROPN"):
            sink_strength = 5.3
        elif pos[i] == "ADJ":
            sink_strength = 5.5
        elif pos[i] in ("VERB", "AUX"):
            sink_strength = 8.2
        elif pos[i] in ("DET", "PRON", "CCONJ", "SCONJ"):
            sink_strength = 9.5
        else:
            sink_strength = 7.8

        if dep[i] in ("dobj", "obj", "pobj", "attr"):
            sink_strength *= 0.88
        if continuation[i]:
            sink_strength *= 0.78
        if punctuation[i] or whitespace[i]:
            sink_strength *= 1.12

        sink_strength *= np.exp(-max(0, i - first - 3) / 23.0)

        if i == first and first != sink:
            if pos[i] == "DET":
                sink_strength = 5.33
                weights[first] = 1.0
            elif pos[i] == "PRON":
                sink_strength = 10.2
                weights[first] = 1.0
            else:
                sink_strength = 8.0
                weights[first] = 1.0

        weights[sink] = sink_strength

        # Redistribute existing mass, leaving the row total and self-attention
        # unchanged. All rows outside this specific pattern stay untouched.
        active = [
            j for j in clause_anchors
            if j < i and (
                not alignment[i] or not alignment[j]
                or alignment[i][0] != alignment[j][0]
            )
        ]
        if active:
            recipients = list(active)
            if first != sink and pos[first] == "PRON":
                recipients.append(first)

            fraction = 0.32 if all(pos[j] == "AUX" for j in active) else 0.44
            transferred = fraction * weights[sink]
            weights[sink] -= transferred

            for j in range(first, i):
                if quoted_boundary[j]:
                    released = 0.50 * weights[j]
                    weights[j] -= released
                    transferred += released

            shares = np.array([
                np.exp(-(i - j) / 22.0) for j in recipients
            ], dtype=np.float64)
            shares /= shares.sum()
            for j, share in zip(recipients, shares):
                weights[j] += transferred * share

        attention[i, :i + 1] = weights / weights.sum()

    return "bos_and_clause_anchors", attention


def prog_L2H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a causal boundary-anchor head: punctuation and phrase starters
    attract nearby tokens, with weaker self, initial-token, and BOS attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_anchors_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    strengths = np.ones(n, dtype=np.float64)
    decay = np.full(n, 0.20, dtype=np.float64)
    is_special = np.zeros(n, dtype=bool)
    positions = [None] * n
    previous_word = None

    for j, token in enumerate(tokens):
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        if token in special_tokens:
            is_special[j] = True
            strengths[j] = 1.0 if j == 0 else 0.25
            decay[j] = 0.065
            continue

        word = doc[alignment[j][0]] if alignment[j] else None
        positions[j] = word
        punctuation = bool(clean) and all(
            not char.isalnum() and not char.isspace() for char in clean
        )

        if punctuation:
            if any(char in ".!?" for char in clean):
                strengths[j] = 3.5
                decay[j] = 0.055
            elif any(char in ",;:" for char in clean):
                strengths[j] = 2.75
                decay[j] = 0.075
            elif any(char in "\"“”«»" for char in clean):
                strengths[j] = 2.0
                decay[j] = 0.11
            else:
                strengths[j] = 0.65
        elif not clean:
            strengths[j] = 0.35
        elif word is not None:
            pos = word.pos_
            if pos in ("CCONJ", "SCONJ"):
                strengths[j] = 2.0
                decay[j] = 0.12
            elif pos == "ADP":
                strengths[j] = 1.65
                decay[j] = 0.14
            elif pos in ("VERB", "AUX"):
                strengths[j] = 1.40
            elif pos == "DET":
                strengths[j] = 1.20
            elif pos in ("PRON", "ADV", "PART"):
                strengths[j] = 0.95
            else:
                strengths[j] = 0.72

            if previous_word == word.i:
                strengths[j] *= 0.58
            previous_word = word.i
        else:
            strengths[j] = 0.70

    first = 1 if is_special[0] and n > 1 else 0
    if not is_special[first]:
        word = positions[first]
        pos = word.pos_ if word is not None else ""
        strengths[first] = {
            "DET": 2.83,
            "PRON": 1.85,
            "ADP": 1.65,
            "ADV": 1.45,
            "NUM": 1.13,
            "PROPN": 1.15,
        }.get(pos, 1.40)
        decay[first] = 0.20

    for i in range(n):
        distances = i - np.arange(i + 1, dtype=np.float64)
        row = strengths[:i + 1] / (
            1.0 + decay[:i + 1] * distances
        )
        if i > first and not is_special[i]:
            word = positions[i]
            if word is not None and word.pos_ in ("NOUN", "PROPN", "ADJ"):
                row[i] *= 1.12
        attention[i, :i + 1] = row / row.sum()

    return "boundary_anchors_with_decay", attention


def prog_L2H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local skip-back attention with persistent discourse-boundary memory.
    In quoted dialogue, older clause boundaries remain useful beyond the local window.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_skipback_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    special = set(tokenizer.all_special_tokens)

    for ti, sids in enumerate(aligned):
        if tokens[ti] in special:
            aligned[ti] = []
        else:
            for si in sids:
                if si < len(doc):
                    inverse[si].append(ti)

    word_ids = [
        sids[0] if sids else None
        for sids in aligned
    ]
    phrase_start = {}
    for word in doc:
        if word.pos_ in ("NOUN", "PROPN", "PRON"):
            members = [word.i]
            for child in word.children:
                if child.dep_ in ("det", "poss", "amod", "nummod", "compound"):
                    members.append(child.i)
            candidates = [
                ti for si in members for ti in inverse[si]
                if tokens[ti] not in special
            ]
            if candidates:
                phrase_start[word.i] = min(candidates)

    # Restrict the additional memory to dialogue-like punctuation patterns.
    dialogue = (
        "," in sentence
        and any(c in sentence for c in '"“”«»!?')
    )
    boundary_tokens = []
    if dialogue:
        for word in doc:
            if word.is_punct and any(c in word.text for c in ",;:.!?"):
                if inverse[word.i]:
                    boundary_tokens.append(min(inverse[word.i]))
        boundary_tokens = sorted(set(boundary_tokens))

    attention[0, 0] = 1.0
    for i in range(1, n):
        sid = word_ids[i]
        query = doc[sid] if sid is not None else None

        distance = i - np.arange(i + 1)
        row = (
            np.exp(-0.5 * ((distance - 2.3) / 1.65) ** 2)
            + 0.045 * np.exp(-distance / 12.0)
        )
        row[i] *= 0.48

        for j in range(1, i + 1):
            key_id = word_ids[j]
            if key_id is None:
                continue
            key = doc[key_id]
            if key.pos_ in ("DET", "ADP", "AUX", "CCONJ", "SCONJ"):
                row[j] *= 1.35
            elif key.pos_ in ("NOUN", "PROPN"):
                row[j] *= 0.83
            elif key.pos_ == "VERB":
                row[j] *= 1.15

            if key_id in phrase_start and phrase_start[key_id] == j:
                row[j] *= 1.18

            if query is not None and key_id == sid and j < i:
                row[j] *= 0.65

        row[0] *= 1.45 * np.exp(-max(i - 3, 0) / 5.0)

        # Verbs often look back to the beginning of their subject phrase.
        if query is not None and query.pos_ in ("VERB", "AUX", "ADJ"):
            for child in query.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    anchor = phrase_start.get(child.i)
                    if anchor is not None and 0 < i - anchor <= 8:
                        row[anchor] *= 1.9

        # A preposition or conjunction often looks across the preceding phrase.
        if query is not None and query.pos_ in ("ADP", "CCONJ", "SCONJ"):
            for k in range(sid - 1, max(-1, sid - 6), -1):
                if doc[k].is_punct:
                    break
                if k in phrase_start:
                    anchor = phrase_start[k]
                    if 0 < i - anchor <= 8:
                        row[anchor] *= 1.65
                    break

        # Boundaries remain useful anchors for several following tokens.
        for j in range(i - 1, max(0, i - 7), -1):
            key_id = word_ids[j]
            if key_id is not None and doc[key_id].is_punct:
                if any(c in doc[key_id].text for c in ",;:.!?"):
                    row[j] *= 1.65
                    if query is not None and query.is_punct:
                        row[j] *= 1.4
                    break

        # The first positions have a distinctive BOS/self distribution.
        if i == 1:
            bos = 0.56
            if query is not None:
                if query.pos_ == "PRON":
                    bos = 0.65
                elif query.pos_ == "DET":
                    bos = 0.52
                elif query.pos_ == "ADP":
                    bos = 0.58
            row[:] = (bos, 1.0 - bos)
        elif i == 2:
            if query is not None and query.pos_ in ("NOUN", "PROPN", "ADJ"):
                row[:] = (0.23, 0.32, 0.45)
            elif query is not None and query.pos_ in ("VERB", "AUX"):
                row[:] = (0.36, 0.31, 0.33)
            else:
                row[:] = (0.35, 0.29, 0.36)

        # Dialogue boundaries can persist after their local weight has faded.
        # Add only to older boundary keys; retain every original raw weight.
        if dialogue and i > 2:
            anchors = [j for j in boundary_tokens if 0 < j <= i - 4]
            if anchors:
                gaps = i - np.asarray(anchors, dtype=np.float64)
                memory = np.exp(-(gaps - 4.0) / 28.0)
                strength = 0.30 * min(1.0, float(memory.sum()))
                row[anchors] += strength * row.sum() * memory / memory.sum()

        attention[i, :i + 1] = row

    return "local_skipback_dialogue_boundaries", make_row_stochastic(attention)


def prog_L2H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict self and boundary anchors, with stronger local transitions in dialogue.
    Quoted passages redistribute excess comma-anchor weight toward the preceding token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_and_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    key_strength = np.ones(n, dtype=np.float64)
    self_strength = np.full(n, 2.1, dtype=np.float64)
    word_ids = [None] * n
    is_special = np.zeros(n, dtype=bool)

    # Restrict the correction to explicit dialogue markers, not contractions.
    clean_tokens = [
        token.replace("▁", " ").replace("Ġ", " ").strip()
        for token in tokens
    ]
    quote_start = next(
        (
            i for i, clean in enumerate(clean_tokens)
            if tokens[i] not in special
            and any(c in '"“”«»€' for c in clean)
        ),
        None,
    )
    comma_anchors = [
        i for i, clean in enumerate(clean_tokens)
        if clean and all(c in ",;:" for c in clean)
        and tokens[i] not in special
    ]

    for i, token in enumerate(tokens):
        if token in special:
            is_special[i] = True
            key_strength[i] = 0.014
            self_strength[i] = 0.014
            continue

        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        sids = alignment[i]
        word = doc[sids[0]] if sids else None

        if word is not None:
            word_ids[i] = word.i
            pos = word.pos_
            dep = word.dep_

            if pos == "CCONJ":
                key_strength[i] = 3.2
                self_strength[i] = 4.9
            elif pos == "ADP":
                key_strength[i] = 1.35
                self_strength[i] = 3.5
            elif pos == "SCONJ":
                key_strength[i] = 1.25
                self_strength[i] = 2.5
            elif pos == "DET":
                key_strength[i] = 1.15
                self_strength[i] = 2.7
            elif pos == "PART":
                key_strength[i] = 1.15
                self_strength[i] = 2.5
            elif pos == "ADJ":
                self_strength[i] = 1.8
            elif pos == "ADV":
                self_strength[i] = 2.5
            elif pos in ("VERB", "AUX"):
                self_strength[i] = 2.2

            if dep in ("pobj", "compound"):
                self_strength[i] *= 0.85

        if clean and all(c in ",;:" for c in clean):
            key_strength[i] = 5.5
            self_strength[i] = 6.0
        elif clean and any(c in ".!?" for c in clean):
            key_strength[i] = 2.4
            self_strength[i] = 5.0
        elif clean and all(c in "\"'“”‘’`" for c in clean):
            key_strength[i] = 1.25
            self_strength[i] = 2.6
        elif not clean:
            key_strength[i] = 1.8
            self_strength[i] = 3.4

        if (
            i > 0
            and word_ids[i] is not None
            and word_ids[i] == word_ids[i - 1]
        ):
            key_strength[i] *= 0.55
            self_strength[i] *= 0.6

    first_content = next((i for i in range(n) if not is_special[i]), None)

    for i in range(n):
        if is_special[i] and i == 0:
            attention[i, i] = 1.0
            continue

        distances = i - np.arange(i + 1)
        attention[i, :i + 1] = (
            key_strength[:i + 1] / (1.0 + 0.025 * distances)
        )
        attention[i, i] = self_strength[i]

        if first_content is not None and i == first_content:
            attention[i, i] = 1.0
        elif first_content is not None and i == first_content + 1:
            if self_strength[i] < 4.0:
                attention[i, i] = 1.35

        if i > 0 and not is_special[i - 1]:
            attention[i, i - 1] *= 1.08

        # Preserve all original self weights and decay; correct only dialogue.
        if quote_start is not None and i >= quote_start and not is_special[i]:
            for j in comma_anchors:
                if j < i:
                    attention[i, j] *= 0.65

            if i > 0 and not is_special[i - 1]:
                # A preceding comma remains an anchor, not a local-transition cue.
                if i - 1 not in comma_anchors:
                    attention[i, i - 1] *= 2.6

    return "self_and_dialogue_anchors", make_row_stochastic(attention)


def prog_L2H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict persistent boundary anchors, with quote boundaries competing with
    comma sinks during dialogue, including mojibake quotation marks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "quote_competitive_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    dep = [""] * n
    word_index = [-1] * n
    first_piece = [False] * n
    seen = set()

    for i, indices in enumerate(alignment):
        if tokens[i] in tokenizer.all_special_tokens:
            continue
        if indices:
            k = indices[0]
            word_index[i] = k
            pos[i] = doc[k].pos_
            dep[i] = doc[k].dep_
            first_piece[i] = k not in seen
            seen.add(k)

    commas = []
    determiners = []
    coordinators = []
    opening_quotes = []
    closing_quotes = []
    quote_open = False

    for j, token in enumerate(tokens):
        clean = token.replace("▁", "").replace("Ġ", "").strip()

        if "," in clean:
            commas.append(j)

        if first_piece[j] and (pos[j] == "DET" or dep[j] == "det"):
            determiners.append(j)

        if first_piece[j] and (pos[j] == "CCONJ" or dep[j] == "cc"):
            coordinators.append(j)

        if '"' in clean or "“" in clean or "”" in clean:
            if "“" in clean:
                opening_quotes.append(j)
                quote_open = True
            elif "”" in clean:
                closing_quotes.append(j)
                quote_open = False
            elif quote_open:
                closing_quotes.append(j)
                quote_open = False
            else:
                opening_quotes.append(j)
                quote_open = True

    # Recognize split, misdecoded quotation punctuation without changing the
    # original quote-anchor calculations.
    boundaries = [(j, j, True) for j in opening_quotes]
    boundaries += [(j, j, False) for j in closing_quotes]
    malformed_pieces = set()
    cleaned = [t.replace("▁", "").replace("Ġ", "").strip() for t in tokens]
    for j in range(n - 1):
        # UTF-8 curly quotes misdecoded as Windows-1252: â€œ / â€[...].
        if cleaned[j] == "\u00e2" and cleaned[j + 1] == "\u20ac":
            end = j + 1
            is_open = j + 2 < n and cleaned[j + 2] == "\u0153"
            if is_open:
                end = j + 2
            elif j + 2 < n and cleaned[j + 2] == "\u009d":
                end = j + 2
            boundaries.append((j, end, is_open))
            malformed_pieces.update(range(j, end + 1))
    boundaries.sort()

    attention[0, 0] = 1.0

    for i in range(1, n):
        distances = i - np.arange(i + 1)
        row = 0.30 + 0.35 * np.exp(-distances / 4.0)

        # The initial sink loses strength as structural anchors accumulate.
        row[0] = 4.8 * np.exp(-0.10 * (i - 1))
        if pos[i] == "PUNCT":
            row[0] *= 0.78

        if pos[i] == "PROPN":
            row[i] = 0.44
        elif pos[i] == "ADP":
            row[i] = 0.45
        elif pos[i] == "PUNCT":
            row[i] = 0.85
        else:
            row[i] = 0.80

        # Determiners serve as local phrase-start anchors, including for
        # subword pieces of their following nominal.
        for j in determiners:
            if j > i:
                break
            distance = i - j
            strength = 1.93 if j == 1 else 2.8
            if distance == 0:
                row[j] = strength
                continue

            strength *= np.exp(-distance / 10.0)
            if word_index[i] >= 0 and word_index[j] >= 0:
                determiner_head = doc[word_index[j]].head
                query_word = doc[word_index[i]]
                if (
                    query_word.i == determiner_head.i
                    or query_word.head.i == determiner_head.i
                ):
                    strength *= 1.25
            row[j] += strength

        for j in coordinators:
            if j > i:
                break
            if j == i:
                row[j] += 0.7
            else:
                row[j] += 3.7 * np.exp(-(i - j) / 17.0)

        # Earlier commas remain strong even across subsequent clauses.
        for rank, j in enumerate(commas):
            if j > i:
                break
            if j < i:
                strength = 7.4 / ((rank + 1) ** 0.65)
                strength *= np.exp(-(i - j - 1) / 75.0)
                row[j] += strength
            else:
                row[j] += 0.55

        punctuation_query = pos[i] == "PUNCT"
        for j in opening_quotes:
            if j >= i:
                break
            strength = 1.25 * np.exp(-(i - j) / 65.0)
            if punctuation_query:
                strength *= 3.5
            row[j] += strength

        for j in closing_quotes:
            if j >= i:
                break
            strength = 0.65 * np.exp(-(i - j) / 60.0)
            if punctuation_query:
                strength *= 7.0
            row[j] += strength

        # Special case: quotation boundaries compete with comma anchors.
        # Leave ordinary prose and every unnormalized diagonal weight intact.
        past_boundaries = [b for b in boundaries if b[0] <= i]
        if past_boundaries:
            start, end, inside_quote = past_boundaries[-1]
            boundary_query = start <= i <= end
            malformed_context = any(j <= i for j in malformed_pieces)
            freed = 0.0

            for rank, j in enumerate(commas):
                if j >= i:
                    break
                if punctuation_query or boundary_query or malformed_context:
                    reduction = 0.65
                elif not inside_quote or j < start - 1:
                    reduction = 0.40
                else:
                    # Preserve the strong introductory comma for speech content.
                    reduction = 0.0
                strength = 7.4 / ((rank + 1) ** 0.65)
                strength *= np.exp(-(i - j - 1) / 75.0)
                removed = reduction * strength
                row[j] -= removed
                freed += removed

            row[0] += 0.20 * freed

            if punctuation_query or boundary_query:
                # Recent opening/closing boundaries jointly anchor punctuation.
                for is_open in (True, False):
                    candidates = [
                        b for b in past_boundaries
                        if b[2] == is_open and b[0] < i
                    ]
                    if candidates:
                        a, b, _ = candidates[-1]
                        keys = list(range(a, min(b, i - 1) + 1))
                        for j in keys:
                            row[j] += 0.40 * freed / len(keys)

            # Corrupted quote pieces are boundaries too, not ordinary text.
            for j in malformed_pieces:
                if j < i:
                    strength = 1.25 * np.exp(-(i - j) / 65.0)
                    if punctuation_query or i in malformed_pieces:
                        strength *= 3.5
                    row[j] += strength

        attention[i, :i + 1] = row / row.sum()

    return "quote_competitive_boundary_anchors", attention


def prog_L2H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors, with additional phrase-entry anchors at
    prepositions, infinitival markers, and subordinating clause markers.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_and_phrase_entry_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    representatives = []
    first_piece = {}
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if 0 <= k < len(doc)]
        si = max(
            valid,
            key=lambda k: (not doc[k].is_space, not doc[k].is_punct),
        ) if valid else None
        if tokens[i] in special_tokens:
            si = None
        representatives.append(si)
        if si is not None and si not in first_piece:
            first_piece[si] = i

    comma_positions = [
        i for i, token in enumerate(tokens)
        if "," in token and token not in special_tokens
    ]
    first_comma = comma_positions[0] if comma_positions else None
    comma_set = set(comma_positions)

    determiners = []
    coordinators = []
    phrase_entries = []
    for i, si in enumerate(representatives):
        if si is None or first_piece.get(si) != i:
            continue
        word = doc[si]
        if word.pos_ == "DET" and word.dep_ in ("det", "predet"):
            determiners.append((i, si))
        if word.pos_ == "CCONJ" or word.dep_ == "cc":
            coordinators.append((i, si))

        # Previously missing anchors: phrase/clause introducers, not
        # arbitrary function words or additional determiner categories.
        if (
            word.pos_ == "ADP"
            or (word.pos_ == "PART" and word.tag_ == "TO")
            or (word.pos_ == "SCONJ" and word.dep_ == "mark")
        ):
            phrase_entries.append(
                (i, 2.1 if word.pos_ == "SCONJ" else 3.5)
            )

    for i in range(n):
        distance = i - np.arange(i + 1)
        row = 0.045 + 0.11 * np.exp(-distance / 7.0)
        row[-1] += 0.52
        if i:
            row[-2] += 0.12

        # The initial sink is strongest before structural anchors appear.
        row[0] += 5.2 / (1.0 + 0.23 * i)

        query_si = representatives[i]
        query = doc[query_si] if query_si is not None else None

        for j, si in determiners:
            if j > i:
                break
            d = i - j
            strength = 2.1 / (1.0 + 0.13 * d)
            determiner = doc[si]
            if query is not None and i > j:
                noun = determiner.head
                if query.i == noun.i or query.head.i == noun.i:
                    strength *= 1.45
            # A comma reduces, but does not erase, preceding phrase anchors.
            if any(j < c <= i for c in comma_positions):
                strength *= 0.48
            row[j] += strength

        for j, si in coordinators:
            if j > i:
                break
            d = i - j
            strength = (1.5 if d == 0 else 3.5) / (1.0 + 0.11 * d)
            if any(j < c <= i for c in comma_positions):
                strength *= 0.65
            row[j] += strength

        for j in comma_positions:
            if j > i:
                break
            d = i - j
            if j == first_comma:
                strength = 5.4 if d == 0 else 6.7 / (1.0 + 0.065 * d)
            else:
                strength = 2.7 / (1.0 + 0.10 * d)
            row[j] += strength

        # Quotes and sentence punctuation are weaker queries for these anchors.
        if query is not None and query.is_punct and i not in comma_set:
            for j in comma_positions:
                if j <= i:
                    row[j] *= 0.72
            row[0] *= 1.12

        # Add only missing backward edges; leave all original raw weights,
        # including the diagonal and existing anchor decays, unchanged.
        for j, base_strength in phrase_entries:
            if j >= i:
                break
            strength = base_strength / (1.0 + 0.11 * (i - j))
            if any(j < c <= i for c in comma_positions):
                strength *= 0.48
            row[j] += strength

        attention[i, :i + 1] = row / row.sum()

    return "boundary_and_phrase_entry_anchors", attention


def prog_L2H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors also include prepositions and infinitival markers.
    Add only their missing off-diagonal attraction, preserving existing raw weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_boundary_with_prepositions", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    anchor_kind = [""] * n
    seen_words = set()
    comma_count = 0
    comma_order = np.zeros(n, dtype=np.int64)

    for j, token in enumerate(tokens):
        if token in special_tokens:
            continue

        if "," in token:
            comma_count += 1
            anchor_kind[j] = "comma"
            comma_order[j] = comma_count
            continue

        if ";" in token or ":" in token:
            anchor_kind[j] = "boundary"
            continue

        # Put a word's anchor only on its first model-token piece.
        candidates = [
            k for k in alignment[j]
            if k < len(doc) and not doc[k].is_space and not doc[k].is_punct
        ]
        if not candidates:
            continue
        k = candidates[0]
        if k in seen_words:
            continue
        seen_words.add(k)
        word = doc[k]

        if word.pos_ == "DET" and word.dep_ in ("det", "predet"):
            anchor_kind[j] = "determiner"
        elif word.pos_ == "CCONJ" or word.dep_ == "cc":
            anchor_kind[j] = "coordinator"
        elif word.pos_ == "ADP" or (
            word.pos_ == "PART" and word.dep_ in ("aux", "mark")
        ):
            anchor_kind[j] = "preposition"

    bos_strength = 2.55
    for j in range(1, n):
        candidates = [
            k for k in alignment[j]
            if k < len(doc) and not doc[k].is_space and not doc[k].is_punct
        ]
        if candidates:
            first_pos = doc[candidates[0]].pos_
            if first_pos == "PROPN":
                bos_strength = 4.0
            elif first_pos in ("ADP", "SCONJ", "ADV"):
                bos_strength = 3.3
            elif first_pos == "PRON":
                bos_strength = 2.8
            break

    for i in range(n):
        distance = i - np.arange(i + 1, dtype=np.float64)
        attention[i, :i + 1] = 0.85 / (1.0 + 0.06 * distance) ** 0.7
        attention[i, 0] = bos_strength

        for j in range(1, i + 1):
            d = i - j
            kind = anchor_kind[j]

            if kind == "comma":
                if comma_order[j] == 1:
                    strength = 7.2 / (1.0 + 0.014 * d)
                else:
                    strength = 4.8 / (1.0 + 0.12 * d)
                attention[i, j] += strength

            elif kind == "boundary":
                attention[i, j] += 2.8 / (1.0 + 0.16 * d)

            elif kind == "determiner":
                strength = 0.49 if j == 1 else 3.2
                attention[i, j] += strength / (1.0 + 0.16 * d)

            elif kind == "coordinator":
                attention[i, j] += 3.8 / (1.0 + 0.10 * d)

            elif kind == "preposition" and d > 0:
                attention[i, j] += 3.2 / (1.0 + 0.10 * d)

    return "persistent_boundary_with_prepositions", make_row_stochastic(attention)


def prog_L2H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors, with a prepositional phrase's determiner
    retained when later noun phrases would otherwise displace it.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_boundary_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    word_ids = [-1] * n
    clean = [t.lstrip("▁Ġ").strip() for t in tokens]
    first_piece = [False] * n

    seen_words = set()
    for i, indices in enumerate(alignment):
        if tokens[i] in special_tokens:
            continue
        if indices:
            # Prefer a lexical overlap to incidental punctuation overlap.
            lexical = [k for k in indices if not doc[k].is_punct]
            k = lexical[0] if lexical else indices[0]
            pos[i] = doc[k].pos_
            dep[i] = doc[k].dep_
            word_ids[i] = k
            first_piece[i] = k not in seen_words
            seen_words.add(k)

    commas = []
    determiners = []
    coordinators = []
    pp_anchor = None

    for i in range(n):
        distance = i - np.arange(i + 1)
        row = 0.12 + 0.13 * np.exp(-distance / 3.0)

        # Early tokens back off to the start-of-sequence sink.
        row[0] += 1.80 * np.exp(-max(i - 1, 0) / 3.4)
        if pos[i] == "PRON":
            row[i] += 0.38
        elif pos[i] in ("ADP", "ADV", "SCONJ"):
            row[i] += 0.16

        is_comma = "," in clean[i]
        if is_comma:
            commas.append(i)
        if first_piece[i] and pos[i] == "DET":
            determiners.append(i)

            # Only an early, pre-boundary prepositional noun phrase qualifies.
            if pp_anchor is None and not commas and not coordinators:
                nominal = doc[word_ids[i]].head
                if (
                    dep[i] == "det"
                    and nominal.pos_ in ("NOUN", "PROPN")
                    and nominal.head.pos_ == "ADP"
                ):
                    pp_anchor = i

        if first_piece[i] and (
            pos[i] == "CCONJ" or dep[i] == "cc"
        ):
            coordinators.append(i)

        # Activate only when a later determiner competes with that anchor.
        retain_pp = (
            pp_anchor is not None
            and determiners[-1] > pp_anchor
        )

        # Commas remain useful across sentence and quotation boundaries.
        # Earlier commas compete successfully with subsequent boundaries.
        for rank, j in enumerate(commas):
            d = i - j
            strength = (
                3.25
                * np.exp(-j / 38.0)
                * np.exp(-d / 65.0)
                / (1.0 + 0.35 * rank)
            )
            if d == 0:
                strength *= 0.72
            elif d <= 6:
                strength *= 1.12
            if retain_pp:
                strength *= 0.65
            row[j] += strength

        # Determiners act as local phrase-start anchors, including on self.
        for rank, j in enumerate(reversed(determiners)):
            d = i - j
            strength = 1.65 * np.exp(-d / 9.0) * (0.42 ** rank)
            if commas and j < commas[-1]:
                strength *= 0.55
            if pos[i] == "NOUN" and word_ids[i] >= 0:
                if doc[word_ids[j]].head.i == word_ids[i]:
                    strength *= 1.18

            if retain_pp:
                if j == pp_anchor:
                    # Add a persistent component without replacing local decay.
                    strength += 1.10 * np.exp(-d / 45.0)
                elif j > pp_anchor and j != i:
                    strength *= 0.35
            row[j] += strength

        # Coordinators provide a longer-lived clause-start anchor.
        for rank, j in enumerate(reversed(coordinators)):
            strength = (
                2.15
                * np.exp(-(i - j) / 13.0)
                * (0.50 ** rank)
            )
            if commas and j < commas[-1]:
                strength *= 0.65
            if retain_pp and j > pp_anchor and j != i:
                strength *= 0.35
            row[j] += strength

        # A standalone opening quote often retrieves the introducing verb,
        # rather than the intervening comma.
        if clean[i] in ('"', "“", "‘", "«"):
            candidates = [
                j for j in range(max(0, i - 12), i)
                if pos[j] == "VERB" and first_piece[j]
            ]
            if candidates:
                row *= 0.45
                row[candidates[-1]] += 3.3

        matrix[i, :i + 1] = row

    return "persistent_boundary_anchors", make_row_stochastic(matrix)


def prog_L2H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors, supplemented by overlooked grammatical anchors:
    prepositions, clause/infinitive markers, and sentence-initial pronouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_grammatical_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    word_start = [False] * n
    comma = np.zeros(n, dtype=bool)
    punctuation = np.zeros(n, dtype=bool)
    seen_words = set()

    for j, token in enumerate(tokens):
        clean = token.lstrip("▁Ġ")
        comma[j] = "," in clean
        punctuation[j] = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        ) and token not in special

        indices = alignment[j]
        if indices and token not in special:
            # Prefer lexical overlap when offsets also include whitespace.
            k = max(
                indices,
                key=lambda k: (
                    not doc[k].is_space,
                    not doc[k].is_punct,
                    len(doc[k].text),
                ),
            )
            pos[j] = doc[k].pos_
            dep[j] = doc[k].dep_
            word_start[j] = k not in seen_words
            seen_words.update(indices)

    comma_indices = np.flatnonzero(comma)
    first_comma = int(comma_indices[0]) if len(comma_indices) else -1

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        distance = i - np.arange(i + 1)
        # Small distributed background, with a weak local component.
        weights = 0.055 + 0.075 * np.exp(-distance / 4.0)
        weights[0] = 2.8 * np.exp(-i / 24.0)

        for j in range(1, i + 1):
            d = i - j
            if tokens[j] in special:
                continue

            if comma[j]:
                # Earlier boundaries remain visible across subsequent clauses.
                strength = 5.8 if j == first_comma else 3.2
                weights[j] += strength / (1.0 + d / 7.0) ** 0.48
            elif word_start[j] and (
                pos[j] == "CCONJ" or dep[j] == "cc"
            ):
                weights[j] += 2.5 * np.exp(-d / 13.0)
            elif word_start[j] and (
                pos[j] == "DET" or dep[j] == "det"
            ):
                weights[j] += 2.1 * np.exp(-d / 9.0)
            elif punctuation[j]:
                weights[j] += 0.65 * np.exp(-d / 4.0)

            # Additional anchors absent from the original feature inventory.
            # Leave existing anchor bonuses and their decay rates untouched.
            if word_start[j] and not punctuation[j]:
                if (
                    pos[j] in ("ADP", "SCONJ")
                    or (pos[j] == "PART" and dep[j] in ("aux", "mark"))
                ):
                    strength = 2.1 if pos[j] == "PART" else 1.6
                    weights[j] += strength / (1.0 + d / 12.0) ** 0.55
                elif j == 1 and j < i and pos[j] == "PRON":
                    weights[j] += 0.65 * np.exp(-d / 24.0)

        # Non-anchor self-attention is modest, stronger at the sequence onset.
        is_anchor = comma[i] or (
            word_start[i]
            and (pos[i] in ("DET", "CCONJ") or dep[i] in ("det", "cc"))
        )
        if not is_anchor:
            self_strength = 0.28
            if i == 1:
                self_strength = 0.85 if pos[i] == "PRON" else 0.42
            weights[i] += self_strength

        attention[i, :i + 1] = weights / weights.sum()

    return "persistent_grammatical_anchors", attention


def prog_L2H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent boundary anchors, with an early prepositional/subordinate
    boundary fallback when the original anchor inventory misses the first boundary.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_boundary_fallback", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    owners = []
    first_piece = {}
    clean = []
    for i, token in enumerate(tokens):
        text = token.replace("▁", " ").replace("Ġ", " ").strip()
        clean.append(text)
        candidates = aligned[i]
        owner = max(
            candidates,
            key=lambda k: len(doc[k].text.strip()),
            default=None,
        )
        owners.append(owner)
        if owner is not None and token not in special:
            first_piece.setdefault(owner, i)

    bos = 0
    start = 1 if tokens[0] in special else 0
    kinds = [None] * n
    strengths = np.zeros(n, dtype=np.float64)
    comma_indices = []
    quote_indices = []

    for j in range(start, n):
        text = clean[j]
        owner = owners[j]
        word = doc[owner] if owner is not None else None
        is_first_piece = owner is not None and first_piece[owner] == j

        if text == ",":
            kinds[j] = "comma"
            strengths[j] = (
                6.0 * np.exp(-0.055 * max(0, j - start))
                / (1.0 + 0.55 * len(comma_indices))
            )
            comma_indices.append(j)
        elif any(c in text for c in ('"', "“", "”", "«", "»")):
            quote_indices.append(j)
        elif is_first_piece and word.pos_ == "CCONJ":
            kinds[j] = "coordinator"
            strengths[j] = 3.6 * np.exp(-0.035 * max(0, j - start))
        elif is_first_piece and word.pos_ == "DET" and word.dep_ == "det":
            kinds[j] = "determiner"
            strengths[j] = 2.5 * np.exp(-0.035 * max(0, j - start))
            if comma_indices:
                strengths[j] *= 0.65
        elif is_first_piece and word.pos_ == "PART" and word.dep_ in ("aux", "mark"):
            kinds[j] = "infinitival"
            strengths[j] = 1.9 * np.exp(-0.065 * max(0, j - start))

    if start < n:
        owner = owners[start]
        pos = doc[owner].pos_ if owner is not None else ""
        initial_strength = {
            "DET": 2.30,
            "PRON": 2.12,
            "PROPN": 1.65,
            "NUM": 1.22,
            "ADP": 1.08,
            "ADV": 1.30,
        }.get(pos, 1.15)
        strengths[start] = initial_strength
        if kinds[start] is None:
            kinds[start] = "initial"

    # Activate only when an unmodeled grammatical boundary precedes every
    # original non-initial anchor. Otherwise preserve the original behavior.
    first_anchor = next(
        (
            j for j in range(start + 1, n)
            if kinds[j] in ("comma", "coordinator", "determiner", "infinitival")
        ),
        n,
    )
    missing_boundaries = [
        j for j in range(start + 1, n)
        if kinds[j] is None
        and j not in quote_indices
        and tokens[j] not in special
        and owners[j] is not None
        and first_piece.get(owners[j]) == j
        and doc[owners[j]].pos_ in ("ADP", "SCONJ")
    ]
    if missing_boundaries and missing_boundaries[0] < first_anchor:
        for j in missing_boundaries:
            kinds[j] = "fallback_boundary"
            base = 2.2 if doc[owners[j]].pos_ == "ADP" else 1.25
            strengths[j] = base * np.exp(-0.025 * max(0, j - start))

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        row = attention[i]
        row[bos] = 1.0 if i == start else 1.2

        for j in range(start, i + 1):
            distance = i - j
            row[j] += 0.018 * np.exp(-distance / 16.0)

            kind = kinds[j]
            if kind == "comma":
                decay = (1.0 + distance / 20.0) ** -0.48
            elif kind == "coordinator":
                decay = np.exp(-distance / 24.0)
            elif kind == "determiner":
                decay = np.exp(-distance / 9.0)
            elif kind == "infinitival":
                decay = np.exp(-distance / 7.0)
            elif kind == "initial":
                decay = np.exp(-distance / 1.45)
            elif kind == "fallback_boundary":
                # Add the missing anchor without removing ordinary self mass.
                row[j] += strengths[j] * np.exp(-distance / 18.0)
                continue
            else:
                continue
            row[j] += strengths[j] * decay

        if kinds[i] is None or kinds[i] == "fallback_boundary":
            row[i] += 0.72 if i <= start + 2 else 0.30
        if i > start:
            row[i - 1] += 0.10

        # Punctuation queries additionally compare earlier boundaries.
        if clean[i] == ",":
            previous = [j for j in comma_indices if j < i]
            if previous:
                row[previous[-1]] += 1.0

        # Quotes form a separate boundary chain rather than lexical anchors.
        if i in quote_indices:
            previous = [j for j in quote_indices if j < i]
            if previous:
                closing = (
                    clean[i].startswith(("?", "!", "."))
                    or clean[i] in ("”", "»")
                )
                target = previous[-1]
                row[target] += 2.5 if closing else 1.8
                if len(previous) > 1:
                    row[previous[0]] += 0.65
            else:
                row[bos] += 0.55

        # Whitespace-only model pieces preferentially link to earlier ones.
        if not clean[i] and tokens[i] not in special:
            previous = [
                j for j in range(start, i)
                if not clean[j] and tokens[j] not in special
            ]
            if previous:
                row[previous[-1]] += 4.0

        if i == start:
            row[:] = 0.0
            if start == 0:
                row[i] = 1.0
            else:
                row[bos] = 1.0
                row[i] = strengths[start]

    return (
        "persistent_boundary_fallback",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L2H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS/boundary sink with dialogue-specific closing-quote and spacing anchors.
    Fragmented, encoding-corrupted quotation marks also act as dialogue anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    weights = np.ones(n, dtype=np.float64)
    kinds = ["ordinary"] * n
    positions = [""] * n
    quote_open = False

    for j, token in enumerate(tokens):
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        sids = aligned[j]
        word = doc[sids[0]] if sids else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        positions[j] = pos

        if token in tokenizer.all_special_tokens:
            weights[j] = 0.15
            kinds[j] = "special"
            continue

        if not clean:
            weights[j] = 1.8
            kinds[j] = "space"
        elif "," in clean or ";" in clean or ":" in clean:
            weights[j] = 6.8
            kinds[j] = "boundary"
        elif any(c in clean for c in ('"', "“", "”", "«", "»")):
            opening = not quote_open
            if "“" in clean or "«" in clean:
                opening = True
            elif "”" in clean or "»" in clean:
                opening = False
            quote_open = opening
            kinds[j] = "opening_quote" if opening else "closing_quote"
            weights[j] = 7.4 if opening else 2.3
        elif pos == "PUNCT":
            weights[j] = 1.0 if clean in ("'", "’", "-") else 2.3
        elif pos == "DET":
            weights[j] = 2.4
        elif pos in ("CCONJ", "SCONJ"):
            weights[j] = 3.0 if pos == "CCONJ" else 1.8
        elif pos in ("VERB", "AUX"):
            weights[j] = 1.7
        elif pos == "ADP":
            weights[j] = 1.3
        elif pos in ("ADJ", "ADV"):
            weights[j] = 1.25
        elif pos in ("PRON", "PROPN", "NOUN"):
            weights[j] = 0.95
        elif pos == "PART":
            weights[j] = 0.8

        if dep in ("ROOT", "conj") and pos in ("VERB", "AUX"):
            weights[j] *= 1.08

    # Supplemental dialogue metadata; the original weights remain untouched.
    dialogue_roles = [
        k if k in ("opening_quote", "closing_quote") else "" for k in kinds
    ]
    cleans = [
        t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens
    ]
    fragmented = np.zeros(n, dtype=bool)
    for j in range(1, n - 1):
        # UTF-8 curly quotes misdecoded as Windows-1252 punctuation.
        if cleans[j] == "â" and cleans[j + 1] == "€":
            end = j + 2
            opening = end < n and cleans[end] == "œ"
            if end < n and cleans[end] in ("œ", "\u009d", "�"):
                end += 1
            role = "opening_quote" if opening else "closing_quote"
            for k in range(j, end):
                dialogue_roles[k] = role
                fragmented[k] = True

    dialogue = any(dialogue_roles)
    first_open = next(
        (j for j in range(n) if dialogue_roles[j] == "opening_quote"), n
    )

    for i in range(n):
        js = np.arange(i + 1)
        distances = i - js
        row = weights[:i + 1] * np.exp(-distances / 45.0)

        for j in range(1, i + 1):
            if kinds[j] == "boundary":
                row[j] = weights[j] * np.exp(-(i - j) / 65.0)
            elif kinds[j] == "opening_quote":
                row[j] = (
                    0.85 if i == j
                    else weights[j] * np.exp(-(i - j - 1) / 30.0)
                )
            elif positions[j] == "DET" and i > j:
                row[j] *= 1.45 if j == 1 else 1.12

        row[0] = 6.0 * np.exp(-i / 38.0)

        if dialogue:
            # Adjust only historical keys: retain every original diagonal weight
            # and every original decay rate.
            for j in range(1, i):
                role = dialogue_roles[j]
                if fragmented[j]:
                    row[j] *= 6.0
                elif role == "closing_quote":
                    row[j] *= 3.0
                elif role == "opening_quote":
                    if j == first_open:
                        closed = any(
                            r == "closing_quote"
                            for r in dialogue_roles[j + 1:i + 1]
                        )
                        row[j] *= 0.45 if closed else 0.65
                    else:
                        row[j] *= 1.7
                elif kinds[j] == "space" and dialogue_roles[j - 1] == "closing_quote":
                    row[j] *= 3.5
                elif kinds[j] == "boundary" and j > first_open:
                    row[j] *= 0.45

        attention[i, :i + 1] = row

    return "bos_sink_with_dialogue_anchors", make_row_stochastic(attention)


def prog_L2H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early verbal coordination remains an anchor across later comma boundaries;
    determiners beyond those boundaries are weaker competing anchors."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_coordination_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    determiner = np.zeros(n, dtype=bool)
    conjunction = np.zeros(n, dtype=bool)
    comma = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)
    terminal = np.zeros(n, dtype=bool)
    verb = np.zeros(n, dtype=bool)
    verbal_coordinator = np.zeros(n, dtype=bool)

    seen_spacy = set()
    for j, token in enumerate(tokens):
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        whitespace[j] = (
            j > 0
            and not clean
            and token not in tokenizer.all_special_tokens
        )
        comma[j] = "," in clean
        terminal[j] = any(mark in clean for mark in (".", "!", "?"))

        for sid in alignment[j]:
            word = doc[sid]
            verb[j] = verb[j] or word.pos_ in ("VERB", "AUX")
            if sid not in seen_spacy:
                determiner[j] = determiner[j] or (
                    word.pos_ == "DET" and word.dep_ != "poss"
                )
                conjunction[j] = conjunction[j] or word.pos_ == "CCONJ"
                verbal_coordinator[j] = verbal_coordinator[j] or (
                    word.pos_ == "CCONJ"
                    and word.head.pos_ in ("VERB", "AUX")
                )
                seen_spacy.add(sid)

    comma_rank = np.cumsum(comma)

    # Only activate when the first coordination links predicates before
    # the first comma; comma-following coordination keeps the default behavior.
    persistent_anchor = -1
    first_comma = -1
    comma_positions = np.flatnonzero(comma)
    conjunction_positions = np.flatnonzero(conjunction)
    if comma_positions.size and conjunction_positions.size:
        first_comma = int(comma_positions[0])
        candidate = int(conjunction_positions[0])
        if candidate < first_comma and verbal_coordinator[candidate]:
            persistent_anchor = candidate

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        positions = np.arange(i + 1)
        distance = i - positions

        # Diffuse causal background, plus modest self/previous-token attention.
        row = 0.055 + 0.10 * np.exp(-distance / 7.0)
        row[i] += 0.30
        row[i - 1] += 0.55
        row[0] += 12.0 * np.exp(-0.48 * (i - 1)) + 0.12

        for j in range(1, i + 1):
            d = i - j

            if determiner[j]:
                strength = 1.15 if j == 1 else 3.9
                if d > 0 and j == 1:
                    strength = 4.0
                if persistent_anchor >= 0 and j > first_comma:
                    strength *= 0.25
                row[j] += strength * np.exp(-max(d - 1, 0) / 4.5)

            if conjunction[j]:
                row[j] += 3.2 * np.exp(-d / 6.0)
                if j == persistent_anchor and i > first_comma:
                    row[j] += 2.2 * (1.0 - np.exp(-d / 6.0))

            if comma[j]:
                # Early commas act as persistent sinks, not merely nearest
                # clause boundaries; subsequent commas compete with them.
                rank_discount = 1.0 / (1.0 + 0.40 * (comma_rank[j] - 1))
                strength = 5.5 + 3.5 * np.exp(-j / 6.0)
                persistence = 0.34 + 0.66 * np.exp(-d / 13.0)
                row[j] += strength * rank_discount * persistence * (
                    0.66 if d == 0 else 1.0
                )

            if whitespace[j] and d > 0:
                row[j] += 5.5 * np.exp(-(d - 1) / 0.8)

        if verb[i]:
            row[i] += 0.20

        if terminal[i]:
            row[i] += 2.3

        # Very early punctuation often retains the preceding lexical anchor.
        if comma[i] and i <= 2:
            row[i] *= 0.35
            row[i - 1] += 3.0

        attention[i, :i + 1] = row / row.sum()

    return "persistent_coordination_anchor", attention


def prog_L2H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict persistent left-boundary anchors, with a targeted handoff to
    finite coordinated/complement clauses instead of stale earlier anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_linguistic_left_boundaries", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            if si < len(doc):
                inverse[si].append(ti)

    special = set(tokenizer.all_special_tokens)
    word_for_token = []
    for ti, sids in enumerate(alignment):
        valid = [si for si in sids if si < len(doc) and not doc[si].is_space]
        word_for_token.append(valid[0] if valid and tokens[ti] not in special else None)

    first = next((i for i, si in enumerate(word_for_token) if si is not None), None)
    comma_positions = [
        i for i, si in enumerate(word_for_token)
        if si is not None and doc[si].text == ","
    ]
    first_comma = comma_positions[0] if comma_positions else None

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        row = matrix[i]
        row[:i + 1] = 0.10 / (i + 1)
        row[0] += 0.32
        row[i] += 0.15
        row[i - 1] += 0.09

        if first is not None and first <= i:
            fw = doc[word_for_token[first]]
            distance = i - first
            strength = 0.40
            if fw.pos_ == "DET":
                strength = 2.9
            elif fw.pos_ in ("ADP", "SCONJ", "ADV"):
                strength = 1.25
            strength *= np.exp(-distance / 14.0)
            if first_comma is not None and first_comma <= i:
                strength *= 0.18
            row[first] += strength

        if i == first:
            w = doc[word_for_token[i]]
            self_mass = 0.46
            if w.pos_ == "DET":
                self_mass = 0.684
            elif w.pos_ in ("ADP", "SCONJ"):
                self_mass = 0.56
            elif w.pos_ == "PROPN":
                self_mass = 0.22
            elif w.pos_ == "NUM":
                self_mass = 0.29
            row[:] = 0.0
            row[0] = 1.0 - self_mass
            row[i] += self_mass
            continue

        comma_active = first_comma is not None and first_comma <= i
        if comma_active:
            row[first_comma] += 2.25 * np.exp(-(i - first_comma) / 150.0)
            for cp in comma_positions[1:]:
                if cp <= i:
                    row[cp] += 0.18 * np.exp(-(i - cp) / 18.0)

        si = word_for_token[i]
        if si is None:
            continue
        w = doc[si]

        def add_anchor(si_anchor, weight):
            if 0 <= si_anchor < len(inverse) and inverse[si_anchor]:
                target = inverse[si_anchor][0]
                if target <= i:
                    row[target] += weight

        # Determiners anchor their entire nominal span, including subwords.
        nominal = w
        if w.dep_ in ("amod", "compound", "poss", "nummod"):
            nominal = w.head
        if nominal.pos_ in ("NOUN", "PROPN", "PRON"):
            determiners = [
                c for c in nominal.children
                if c.dep_ in ("det", "poss") and c.i <= w.i
            ]
            if determiners:
                anchor = min(determiners, key=lambda c: c.i)
                add_anchor(anchor.i, 1.10 if comma_active else 3.0)
            elif nominal.dep_ in ("pobj", "obl") and nominal.head.pos_ == "ADP":
                add_anchor(nominal.head.i, 1.8 if not comma_active else 0.65)

        # Clause-opening conjunctions and interrogatives dominate local syntax.
        ancestors = [w] + list(w.ancestors)
        clause = next(
            (a for a in ancestors if a.pos_ in ("VERB", "AUX")),
            None
        )
        if clause is not None:
            children = list(clause.children)
            openers = [
                c for c in children
                if c.i <= w.i and (
                    c.dep_ in ("mark", "cc") or c.tag_.startswith("W")
                )
            ]
            if openers:
                opener = min(openers, key=lambda c: c.i)
                weight = 3.8 if opener.tag_.startswith("W") else 2.2
                add_anchor(opener.i, weight)

            subjects = [
                c for c in children
                if c.dep_ in ("nsubj", "nsubjpass", "csubj") and c.i <= w.i
            ]
            if subjects and w.pos_ in ("VERB", "AUX", "ADJ"):
                subject = min(subjects, key=lambda c: c.i)
                starts = [
                    c for c in subject.children
                    if c.dep_ in ("det", "poss") and c.i <= w.i
                ]
                anchor = min(starts, key=lambda c: c.i) if starts else subject
                add_anchor(anchor.i, 1.8 if starts else 0.55)

            auxiliaries = [
                c for c in children
                if c.dep_ in ("aux", "auxpass", "cop") and c.i <= w.i
            ]
            if auxiliaries and w.pos_ not in ("NOUN", "PROPN"):
                add_anchor(min(auxiliaries, key=lambda c: c.i).i, 1.5)

            modifiers = [
                c for c in children
                if c.dep_ in ("neg", "advmod") and c.i < w.i
            ]
            if modifiers and w.pos_ in ("VERB", "ADV", "ADJ"):
                add_anchor(max(modifiers, key=lambda c: c.i).i, 0.85)

        if w.pos_ in ("AUX", "CCONJ", "SCONJ", "DET"):
            add_anchor(w.i, 1.15 if not comma_active else 0.45)
        elif w.pos_ == "VERB" and w.dep_ == "ROOT" and not comma_active:
            add_anchor(w.i, 1.25)

        if w.pos_ == "PUNCT" and w.text != ",":
            preceding_verbs = [
                t for t in doc[:w.i] if t.pos_ == "VERB" and inverse[t.i]
            ]
            if preceding_verbs:
                add_anchor(preceding_verbs[-1].i, 0.75)

        # Special case: finite coordination/complementation introduces a new
        # persistent boundary. Ordinary nominal and adverbial spans are unchanged.
        boundary = next(
            (
                a for a in ancestors
                if a.dep_ in ("conj", "ccomp")
                and a.pos_ in ("VERB", "AUX", "ADJ")
                and (
                    a.tag_ in ("VBD", "VBP", "VBZ", "MD")
                    or any(
                        c.dep_ in ("nsubj", "nsubjpass", "csubj", "cop")
                        or (
                            c.dep_ in ("aux", "auxpass")
                            and c.tag_ in ("VBD", "VBP", "VBZ", "MD")
                        )
                        for c in a.children
                    )
                )
            ),
            None,
        )
        if boundary is not None:
            children = list(boundary.children)
            candidates = [
                c for c in children
                if c.dep_ in ("mark", "cc") or c.tag_.startswith("W")
            ]
            if boundary.dep_ == "conj":
                candidates += [
                    c for c in boundary.head.children
                    if c.dep_ == "cc" and c.i < boundary.i
                ]

            # Only earlier targets are eligible: retain the original raw
            # diagonal weight and never add a new self-attention contribution.
            additions = []
            eligible = [
                c for c in candidates
                if inverse[c.i] and inverse[c.i][0] < i
            ]
            if eligible:
                opener = max(eligible, key=lambda c: c.i)
                weight = 3.0 if opener.tag_.startswith("W") else (
                    2.0 if opener.dep_ == "cc" else 0.9
                )
                additions.append((opener.i, weight))

            subjects = [
                c for c in children
                if c.dep_ in ("nsubj", "nsubjpass", "csubj")
                and inverse[c.i] and inverse[c.i][0] < i
            ]
            if subjects:
                subject = min(subjects, key=lambda c: c.i)
                starts = [
                    c for c in subject.children
                    if c.dep_ in ("det", "poss")
                    and inverse[c.i] and inverse[c.i][0] < i
                ]
                anchor = min(starts, key=lambda c: c.i) if starts else subject
                additions.append((anchor.i, 0.8 if starts else 1.8))

            parent = boundary.head
            if (
                parent.pos_ in ("VERB", "AUX")
                and inverse[parent.i] and inverse[parent.i][0] < i
            ):
                distance = i - inverse[parent.i][0]
                additions.append((parent.i, 1.4 * np.exp(-distance / 7.0)))

            if additions:
                row[:i] *= 0.55
                for anchor_si, weight in additions:
                    add_anchor(anchor_si, weight)

    return (
        "persistent_linguistic_left_boundaries",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L2H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early structural-anchor attention: persistent determiners, verbs, and clause boundaries,
    with weaker local phrase and lexical-recurrence effects."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_structural_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    word_ids = [
        next((k for k in indices if not doc[k].is_space), -1)
        for indices in alignment
    ]
    first_piece = {}
    for j, wid in enumerate(word_ids):
        if wid >= 0 and tokens[j] not in special:
            first_piece.setdefault(wid, j)

    positions = []
    for wid in word_ids:
        positions.append(doc[wid].pos_ if wid >= 0 else "")

    first_content = next(
        (j for j, t in enumerate(tokens) if t not in special), 0
    )
    initial_pos = positions[first_content]
    initial_nominal = initial_pos == "DET"

    key_strength = np.zeros(n, dtype=np.float64)
    kinds = ["other"] * n
    seen = set()
    comma_indices = []
    conjunction_indices = []

    for j in range(n):
        wid = word_ids[j]
        if tokens[j] in special:
            continue

        pos = positions[j]
        is_first_piece = wid >= 0 and first_piece.get(wid) == j
        text = doc[wid].text if wid >= 0 else tokens[j].lstrip("▁Ġ")

        if text == "," and (is_first_piece or wid < 0):
            kinds[j] = "comma"
            strength = 7.0 if not comma_indices else 0.9
            if not comma_indices and conjunction_indices:
                strength *= 0.65
            comma_indices.append(j)
        elif is_first_piece and pos == "DET":
            kinds[j] = "determiner"
            strength = 4.1 if "determiner" not in seen else 1.25
            seen.add("determiner")
        elif is_first_piece and pos in ("VERB", "AUX"):
            kinds[j] = "verb"
            strength = 2.7 if "verb" not in seen else 0.65
            if initial_nominal:
                strength *= 0.40
            seen.add("verb")
        elif is_first_piece and pos in ("CCONJ", "SCONJ"):
            kinds[j] = "conjunction"
            strength = 3.6 if "conjunction" not in seen else 0.65
            seen.add("conjunction")
            conjunction_indices.append(j)
        elif is_first_piece and pos == "ADP":
            kinds[j] = "preposition"
            strength = 2.1 if "preposition" not in seen else 0.65
            seen.add("preposition")
        else:
            strength = 0.055

        if j == first_content:
            if pos == "DET":
                strength = 4.8
            elif pos in ("ADP", "SCONJ"):
                strength = max(strength, 3.1)
            else:
                strength = max(strength, 0.95)

        key_strength[j] = strength * np.exp(-0.055 * max(0, j - 1))

    # Associate nominal modifiers and noun pieces with a preceding determiner.
    phrase_anchor = {}
    for word in doc:
        nominal = word
        if word.dep_ in ("amod", "compound", "poss", "nummod"):
            nominal = word.head
        determiners = [
            child for child in nominal.children
            if child.pos_ == "DET" and child.i < word.i
        ]
        if determiners:
            anchor_word = min(determiners, key=lambda child: child.i)
            if anchor_word.i in first_piece:
                phrase_anchor[word.i] = first_piece[anchor_word.i]

    for i in range(n):
        if i == 0:
            attention[i, i] = 1.0
            continue

        if i == first_content and first_content > 0:
            self_mass = 0.94
            if positions[i] == "PROPN":
                self_mass = 0.85
            elif positions[i] == "PRON":
                self_mass = 0.93
            attention[i, 0] = 1.0 - self_mass
            attention[i, i] = self_mass
            continue

        row = attention[i]
        for j in range(i + 1):
            age = i - j
            kind = kinds[j]
            if kind in ("comma", "conjunction"):
                persistence = np.exp(-age / 65.0)
            elif kind == "determiner":
                persistence = np.exp(-age / 27.0)
            else:
                persistence = np.exp(-age / 38.0)

            row[j] = key_strength[j] * persistence
            row[j] += 0.025 * np.exp(-age / 18.0)

        row[0] += 0.12
        row[i] += 0.62

        # Initial nominal anchors weaken once an explicit clause boundary occurs.
        preceding_commas = [j for j in comma_indices if j < i]
        if preceding_commas:
            boundary = preceding_commas[0]
            for j in range(boundary):
                if kinds[j] == "determiner" or j == first_content:
                    row[j] *= 0.65

        wid = word_ids[i]
        if wid >= 0:
            anchor = phrase_anchor.get(wid, -1)
            if 0 <= anchor <= i:
                boost = 1.25 * np.exp(-0.045 * anchor)
                if any(anchor < c < i for c in preceding_commas):
                    boost *= 0.35
                row[anchor] += boost

            # Continuation pieces retain the structural preferences of their word.
            start = first_piece.get(wid, i)
            if start < i:
                row[start] += 0.18

            # Sparse similarity retrieval supplements, rather than replaces, anchors.
            if positions[i] in (
                "NOUN", "PROPN", "VERB", "ADJ", "ADV", "CCONJ", "SCONJ"
            ):
                candidates = [
                    j for j in range(i)
                    if word_ids[j] >= 0
                    and word_ids[j] != wid
                    and first_piece.get(word_ids[j]) == j
                    and positions[j] == positions[i]
                    and tokens[j] not in special
                ]
                candidates = sorted(set(candidates[:4] + candidates[-4:]))
                for j in candidates:
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity > 0.65:
                        row[j] += 4.5 * ((similarity - 0.65) / 0.35) ** 2

        if tokens[i].strip("▁Ġ") == "":
            row[i] += 1.0

    return "early_structural_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L2H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early boundary anchors persist, but later commas retain a strength floor.
    In comma-free clauses, subordinators are weaker persistent anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    strength = np.full(n, 0.18, dtype=np.float64)
    anchor = np.zeros(n, dtype=bool)
    comma = np.zeros(n, dtype=bool)
    boundary = np.zeros(n, dtype=bool)
    pos_tags = [""] * n
    seen_words = set()
    first_content = None

    for j, token in enumerate(tokens):
        if token in special_tokens:
            strength[j] = 1.0 if j == 0 else 0.05
            continue

        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        if "," in clean:
            comma[j] = True
            boundary[j] = True
            anchor[j] = True
            strength[j] = 75.0 * np.exp(-0.22 * max(j - 1, 0))
            continue

        mapped = alignment[j]
        if not mapped:
            strength[j] = 0.05 if not clean else 0.18
            continue

        candidates = [k for k in mapped if not doc[k].is_space]
        if not candidates:
            strength[j] = 0.05
            continue

        k = next((k for k in candidates if not doc[k].is_punct), candidates[0])
        word = doc[k]
        pos_tags[j] = word.pos_

        if word.is_punct:
            strength[j] = 0.12
            continue

        if k in seen_words:
            strength[j] = 0.12
            continue
        seen_words.add(k)

        if first_content is None:
            first_content = j
            initial_scores = {
                "DET": 13.5,
                "PRON": 6.1,
                "PROPN": 1.3,
                "ADP": 6.8,
                "SCONJ": 5.0,
                "ADV": 2.0,
                "NUM": 1.8,
            }
            strength[j] = initial_scores.get(word.pos_, 2.5)
            anchor[j] = True
            continue

        primacy = np.exp(-0.18 * max(j - 1, 0))
        if word.pos_ == "DET" and word.dep_ != "poss":
            strength[j] = 29.0 * primacy
            anchor[j] = True
        elif word.pos_ == "CCONJ":
            strength[j] = 29.0 * primacy
            anchor[j] = True
            boundary[j] = True
        elif word.pos_ == "SCONJ" or word.dep_ == "mark":
            strength[j] = 20.0 * primacy
            anchor[j] = True
            boundary[j] = True
        elif word.pos_ == "ADP":
            strength[j] = 8.0 * primacy
            anchor[j] = True
        elif word.pos_ == "PART" and word.dep_ in ("aux", "mark"):
            strength[j] = 10.0 * primacy
            anchor[j] = True
        elif word.pos_ in ("VERB", "AUX"):
            strength[j] = 4.4 * np.exp(-0.15 * max(j - 1, 0))
        else:
            strength[j] = 0.35 * np.exp(-0.06 * j)

    comma_indices = np.flatnonzero(comma)
    weak_subordinator = (
        np.array([pos == "SCONJ" for pos in pos_tags], dtype=bool)
        & anchor
        & boundary
    )
    soften_subordination = (
        len(comma_indices) == 0 and np.any(weak_subordinator)
    )

    for i in range(n):
        indices = np.arange(i + 1)
        distance = i - indices
        row = strength[:i + 1].copy()
        row *= (1.0 + 0.08 * distance) ** -0.45

        for j in range(i + 1):
            if j == 0 or comma[j]:
                continue
            if not anchor[j]:
                row[j] *= np.exp(-0.35 * (i - j))
            elif first_content is not None and j == first_content:
                later_boundaries = np.count_nonzero(boundary[j + 1:i + 1])
                row[j] *= 0.68 ** min(later_boundaries, 3)

        if pos_tags[i] in ("VERB", "AUX") and not anchor[i]:
            row[i] += 0.45

        # Repeated commas remain competitive rather than vanishing with position.
        # Only historical keys change; the original diagonal weight is retained.
        if len(comma_indices) > 1 and i > comma_indices[1]:
            floor = max(10.0, 0.4 * strength[comma_indices[0]])
            for j in comma_indices[1:]:
                if j >= i:
                    break
                row[j] = max(
                    row[j],
                    floor * (1.0 + 0.08 * (i - j)) ** -0.45,
                )

        # Unpunctuated subordination should not behave like a comma boundary.
        if soften_subordination:
            for j in np.flatnonzero(weak_subordinator[:i]):
                row[j] *= 0.25

            if first_content is not None and first_content < i:
                start = first_content + 1
                original_count = np.count_nonzero(boundary[start:i + 1])
                retained_count = np.count_nonzero(
                    boundary[start:i + 1]
                    & ~weak_subordinator[start:i + 1]
                )
                row[first_content] *= 0.68 ** (
                    min(retained_count, 3) - min(original_count, 3)
                )

        attention[i, :i + 1] = row

    return "early_boundary_anchors", make_row_stochastic(attention)


def prog_L2H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early phrase anchors persist; early definite determiners retain attention
    across later boundaries rather than being replaced by those boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_early_definite_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    spans = _char_spans(sentence, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    word_ids = []
    first_piece = {}
    for i, ids in enumerate(alignment):
        valid = [k for k in ids if 0 <= k < len(doc)]
        k = valid[0] if valid and tokens[i] not in specials else None
        word_ids.append(k)
        if k is not None and k not in first_piece:
            first_piece[k] = i

    anchors = []
    for j, token in enumerate(tokens):
        k = word_ids[j]
        if token in specials:
            continue
        if "," in token:
            anchors.append((j, "comma", 4.6 * np.exp(-0.085 * j)))
        elif k is not None and first_piece[k] == j:
            word = doc[k]
            if word.pos_ == "CCONJ":
                anchors.append((j, "coord", 3.4 * np.exp(-0.095 * j)))
            elif word.pos_ == "DET":
                anchors.append((j, "det", 2.6 * np.exp(-0.055 * j)))
            elif word.pos_ == "SCONJ":
                anchors.append((j, "clause", 2.4 * np.exp(-0.085 * j)))
            elif word.pos_ == "ADP":
                anchors.append((j, "prep", 1.25 * np.exp(-0.085 * j)))
            elif word.pos_ in ("VERB", "AUX") and j <= 3:
                anchors.append((j, "verb", 0.75))

    # Narrow exception: an early definite NP survives a subsequent boundary.
    persistent_det = None
    support = None
    for j, kind, _ in anchors:
        if kind == "det" and j <= 8:
            k = word_ids[j]
            if doc[k].dep_ == "det" and "Def" in doc[k].morph.get("Definite"):
                persistent_det = j
                if k > 0 and doc[k - 1].pos_ == "ADP":
                    support = first_piece.get(k - 1)
                else:
                    for wk, piece in first_piece.items():
                        if piece <= 3 and doc[wk].pos_ == "AUX":
                            support = piece
                            break
                break

    attention[0, 0] = 1.0
    for i in range(1, n):
        row = attention[i]
        row[:i + 1] = 0.015 / np.sqrt(i + 1.0)
        row[0] += 0.85 * np.exp(-0.25 * (i - 1))
        row[i] += 0.23
        row[i - 1] += 0.20

        active = [(j, kind, strength) for j, kind, strength in anchors if j <= i]
        boundaries = [j for j, kind, _ in active if kind in ("comma", "coord", "clause")]

        for j, kind, strength in active:
            age = i - j
            if kind == "comma":
                weight = strength / (1.0 + 0.035 * age)
            elif kind in ("coord", "clause"):
                weight = strength / (1.0 + 0.055 * age)
            elif kind == "det":
                weight = strength * np.exp(-0.085 * age)
                if any(b > j for b in boundaries):
                    weight *= 0.16
                if age == 0:
                    weight *= 0.34
            elif kind == "prep":
                weight = strength * np.exp(-0.17 * age)
                if any(b > j for b in boundaries):
                    weight *= 0.20
                if any(a > j and t == "det" for a, t, _ in active):
                    weight *= 0.45
            else:
                weight = strength * np.exp(-0.28 * age)
                if any(a > j for a, _, _ in active):
                    weight *= 0.25

            if kind in ("comma", "coord", "clause") and age == 0:
                weight *= 0.58
            row[j] += weight

        row /= row.sum()

        k = word_ids[i]
        if k is not None:
            start = first_piece[k]
            if start < i:
                word = doc[k]
                local_mass = 0.10
                if word.pos_ in ("VERB", "AUX"):
                    local_mass = 0.60
                    if i < len(spans) and start < len(spans):
                        s, e = spans[i]
                        a, b = spans[start]
                        if 0 < e - s <= 2 and b - a >= 4:
                            local_mass = 0.93
                elif word.pos_ == "ADV":
                    local_mass = 0.35
                elif word.pos_ == "PART":
                    local_mass = 0.28
                row *= 1.0 - local_mass
                row[start] += local_mass

        # Redistribute only boundary attention; preserve the original diagonal
        # and leave rows without this particular configuration unchanged.
        if persistent_det is not None and persistent_det < i:
            recovered = 0.0
            for j, kind, _ in active:
                if persistent_det < j < i and kind in ("comma", "clause"):
                    fraction = 0.43 if kind == "comma" else 0.85
                    mass = fraction * row[j]
                    row[j] -= mass
                    recovered += mass
            if support is not None and support < i:
                row[persistent_det] += 0.80 * recovered
                row[support] += 0.20 * recovered
            else:
                row[persistent_det] += recovered

        if i == 1:
            row[:] = 0.0
            k = word_ids[i]
            bos_mass = 0.78
            if k is not None:
                if doc[k].pos_ == "DET":
                    bos_mass = 0.73
                elif doc[k].pos_ == "PROPN":
                    bos_mass = 0.85
            row[0] = bos_mass
            row[i] = 1.0 - bos_mass

    return "persistent_early_definite_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L2H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict phrase-entry attention with persistent boundary sinks.
    Without punctuation, an initial subject determiner or clause marker can replace BOS as the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "phrase_entry_and_boundary_sinks", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    token_word = [None] * n

    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if wi < len(doc):
                word_tokens[wi].append(ti)
        usable = [wi for wi in word_ids
                  if wi < len(doc) and not doc[wi].is_space]
        lexical = [wi for wi in usable if not doc[wi].is_punct]
        if lexical or usable:
            token_word[ti] = (lexical or usable)[0]

    special_tokens = tokenizer.all_special_tokens
    has_bos = tokens[0] in special_tokens
    first_content = 1 if has_bos else 0
    first_comma = None
    first_coord = None

    # A punctuation-free opening may supply a lexical sink instead of BOS.
    lexical_sink = None
    if has_bos:
        opening = next(
            (w for w in doc if not w.is_space and not w.is_punct), None
        )
        if (opening is not None and opening.pos_ == "DET"
                and opening.dep_ == "det"
                and opening.head.dep_ in ("nsubj", "nsubjpass")
                and word_tokens[opening.i]):
            lexical_sink = word_tokens[opening.i][0]
        else:
            for w in doc:
                if (w.pos_ == "SCONJ" and w.dep_ == "mark"
                        and word_tokens[w.i]):
                    lexical_sink = word_tokens[w.i][0]
                    break

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        if i == first_content and has_bos:
            matrix[i, 0] = 0.80
            matrix[i, i] = 0.20
            continue

        wi = token_word[i]
        word = doc[wi] if wi is not None else None

        if first_comma is None and "," in tokens[i]:
            first_comma = i
        if (first_coord is None and word is not None
                and word.pos_ == "CCONJ"):
            first_coord = word_tokens[wi][0]

        positions = np.arange(i + 1)
        recent = np.exp(-(i - positions) / 5.0)
        matrix[i, :i + 1] = 0.22 * recent / recent.sum()
        matrix[i, i] += 0.12

        if first_comma is not None:
            distance = i - first_comma
            matrix[i, first_comma] += (
                1.10 + 1.35 * np.exp(-distance / 34.0)
            )
            matrix[i, 0] += 0.10
        else:
            matrix[i, 0] += 0.95

        if first_coord is not None and first_coord <= i:
            if first_comma is None or first_coord < first_comma:
                matrix[i, first_coord] += (
                    0.65 * np.exp(-(i - first_coord) / 55.0)
                )

        if word is None:
            matrix[i, i] += 0.45
            continue

        if word.is_space:
            matrix[i, i] += 0.80
            continue

        if word.is_punct:
            matrix[i, i] += 0.35
            continue

        previous = None
        for k in range(wi - 1, -1, -1):
            if not doc[k].is_space:
                previous = doc[k]
                break

        previous_index = None
        if previous is not None:
            indices = [j for j in word_tokens[previous.i] if j < i]
            if indices:
                previous_index = indices[-1]

        # Function words mark the left edge of a newly opened constituent.
        if previous_index is not None and not previous.is_punct:
            target = previous_index
            strength = 0.0

            if word.pos_ in ("ADP", "SCONJ"):
                strength = 4.5
                if word.pos_ == "SCONJ":
                    strength = 3.1
            elif word.pos_ == "PART" and word.dep_ in ("aux", "mark"):
                strength = 5.0
            elif word.pos_ == "DET":
                if previous.pos_ in ("VERB", "AUX"):
                    strength = 3.6
                elif previous.pos_ in ("ADP", "ADV", "PRON", "NUM"):
                    strength = 3.1
                    if previous.pos_ == "ADP":
                        head = previous.head
                        candidates = [
                            j for j in word_tokens[head.i]
                            if j < previous_index
                        ]
                        if candidates and previous.i - head.i <= 5:
                            target = candidates[-1]
                            strength = 3.7
            elif word.pos_ == "PRON":
                if previous.pos_ in ("VERB", "AUX"):
                    strength = 2.4
                elif previous.pos_ == "ADP":
                    strength = 2.0

            if strength:
                matrix[i, target] += strength

        # Determiners are entry anchors for the entire nominal phrase,
        # including every model-token fragment of its modifiers and noun.
        nominal = None
        if word.pos_ in ("NOUN", "PROPN"):
            nominal = word
        elif word.dep_ in ("amod", "compound", "nummod"):
            if word.head.pos_ in ("NOUN", "PROPN"):
                nominal = word.head

        determiner_anchor = None
        if nominal is not None:
            determiners = [
                child for child in nominal.children
                if child.dep_ == "det" and child.i < wi
            ]
            for determiner in determiners:
                indices = [j for j in word_tokens[determiner.i] if j < i]
                if indices:
                    determiner_anchor = indices[0]

            if determiner_anchor is not None:
                strength = 2.7 if first_comma is None else 1.25
                matrix[i, determiner_anchor] += strength
            elif word.dep_ in ("dobj", "obj", "pobj", "attr"):
                head = word.head
                indices = [j for j in word_tokens[head.i] if j < i]
                if indices:
                    strength = 2.0 if first_comma is None else 1.1
                    matrix[i, indices[-1]] += strength

        # Coordinators also introduce persistent clause-local anchors.
        if previous_index is not None and previous.pos_ == "CCONJ":
            matrix[i, previous_index] += 3.6
        elif word.pos_ == "CCONJ":
            matrix[i, i] += 1.2

        # Initial subject determiners can anchor the following predicate.
        if word.pos_ in ("VERB", "AUX", "ADJ") and first_comma is None:
            predicate = word.head if word.dep_ in ("acomp", "attr") else word
            subjects = [
                child for child in predicate.children
                if child.dep_ in ("nsubj", "nsubjpass")
                and child.i < wi
            ]
            for subject in subjects:
                for child in subject.children:
                    if child.dep_ != "det":
                        continue
                    indices = [j for j in word_tokens[child.i] if j < i]
                    if indices:
                        matrix[i, indices[0]] += (
                            1.0 if word.pos_ == "AUX" else 1.9
                        )

        # Early predicates retain a substantial self component rather
        # than behaving as strict previous-token attention.
        if word.pos_ in ("VERB", "AUX") and i <= first_content + 2:
            matrix[i, i] += 0.65

        # Only redirect the BOS sink when the lexical entry is otherwise
        # missing. Preserve row totals, self weights, and existing decays.
        if (first_comma is None and lexical_sink is not None
                and lexical_sink < i and i >= first_content + 3
                and matrix[i, lexical_sink] < 0.95):
            redirected = 0.80 * min(matrix[i, 0], 0.95)
            matrix[i, 0] -= redirected
            if previous_index is not None and not previous.is_punct:
                matrix[i, lexical_sink] += 0.75 * redirected
                matrix[i, previous_index] += 0.25 * redirected
            else:
                matrix[i, lexical_sink] += redirected

    return (
        "phrase_entry_and_boundary_sinks",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L2H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict local phrase links with boundary sinks; in comma-free clauses,
    an early determiner or subordinator can replace BOS as the fallback anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_phrase_links_with_early_function_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    word_ids = []

    for i, indices in enumerate(alignment):
        valid = [k for k in indices if 0 <= k < len(doc)]
        nonspace = [k for k in valid if not doc[k].is_space]
        word_ids.append(nonspace[-1] if nonspace else None)
        for k in valid:
            inverse[k].append(i)

    # Only comma-free openings use this alternate fallback. Keep the original
    # comma-anchored behavior, local links, and self-attention weights intact.
    fallback_anchor = None
    if not any(w.is_punct and "," in w.text for w in doc):
        opening = [w for w in doc if not w.is_space][:4]
        for w in opening:
            if w.pos_ in ("DET", "SCONJ"):
                candidates = [j for j in inverse[w.i] if j > 0]
                if candidates:
                    fallback_anchor = candidates[0]
                    break

    first_comma = None
    first_coordinator = None
    special_tokens = tokenizer.all_special_tokens

    for i in range(n):
        if i == 0 or tokens[i] in special_tokens:
            attention[i, 0] = 1.0
            continue

        row = attention[i]
        wi = word_ids[i]
        pi = word_ids[i - 1]
        current = doc[wi] if wi is not None else None
        previous = doc[pi] if pi is not None else None

        # A weak causal background prevents implausibly sharp predictions.
        distances = i - np.arange(i + 1)
        row[:i + 1] = 0.025 * np.exp(-distances / 12.0)
        row[i] += 0.12
        row[i - 1] += 0.45

        if first_comma is None:
            row[0] += 0.95
            if fallback_anchor is not None and fallback_anchor < i:
                row[0] -= 0.90
                row[fallback_anchor] += 0.90
        else:
            row[0] += 0.10
            row[first_comma] += 1.75 * np.exp(
                -(i - first_comma) / 110.0
            )

        if first_coordinator is not None:
            row[first_coordinator] += 0.55 * np.exp(
                -(i - first_coordinator) / 85.0
            )

        if i == 1:
            row[0] += 3.5
            if current is not None and current.pos_ == "DET":
                row[i] += 2.8

        # Pieces of the same lexical word usually follow one another.
        continuation = (
            wi is not None
            and pi == wi
            and current is not None
            and not current.is_punct
            and not any(ch in tokens[i] for ch in ("'", "’"))
            and not any(ch in tokens[i - 1] for ch in ("'", "’"))
        )
        if continuation:
            row[i - 1] += 9.0

        if current is not None and previous is not None and wi != pi:
            cp, pp = current.pos_, previous.pos_

            # Left-to-right links within nominal and modifier phrases.
            if pp in ("DET", "PRON") and cp in ("NOUN", "PROPN", "ADJ", "NUM"):
                row[i - 1] += 4.2
            if pp == "ADJ" and cp in ("NOUN", "PROPN", "ADJ"):
                row[i - 1] += 7.0
            if pp == "NUM" and cp in ("NOUN", "PROPN"):
                row[i - 1] += 4.0
            if pp == "ADV" and cp in ("ADJ", "ADV", "VERB", "ADP", "DET"):
                row[i - 1] += 4.0
            if pp == "AUX" and cp in ("VERB", "ADJ", "ADV", "PRON"):
                row[i - 1] += 3.0
            if pp == "SCONJ" and cp in ("PRON", "SCONJ"):
                row[i - 1] += 4.0
            if pp == "CCONJ" and cp in ("VERB", "AUX", "ADV"):
                row[i - 1] += 4.5
            if pp == "PRON" and cp in ("VERB", "AUX"):
                row[i - 1] += 1.5
            if pp == "VERB" and cp in ("PRON", "ADP", "PART", "NOUN"):
                row[i - 1] += 1.0
            if pp == "ADP" and cp in ("DET", "PRON", "ADV"):
                row[i - 1] += 1.2
            if pp in ("NOUN", "PROPN") and cp == "ADP":
                row[i - 1] += 0.9

            # A preceding syntactic head or modifier reinforces a local edge.
            if current.head.i == pi or previous.head.i == wi:
                row[i - 1] += 0.65

            # Subject-initial predicates sometimes retain the phrase's opening
            # determiner rather than selecting the intervening noun.
            if cp in ("VERB", "AUX") and previous.dep_ in ("nsubj", "nsubjpass"):
                for child in previous.children:
                    if child.dep_ in ("det", "poss"):
                        candidates = [j for j in inverse[child.i] if j < i]
                        if candidates:
                            row[candidates[-1]] += 1.8

            # In auxiliary-subject-verb sequences, the auxiliary remains salient.
            if cp == "VERB" and pp == "PRON":
                for child in current.children:
                    if child.dep_ in ("aux", "auxpass"):
                        candidates = [j for j in inverse[child.i] if j < i]
                        if candidates:
                            row[candidates[-1]] += 2.6

        if current is not None:
            if current.pos_ in ("DET", "ADP", "CCONJ"):
                row[i] += 0.55

            is_comma = "," in tokens[i] and current.is_punct
            if is_comma and first_comma is None:
                first_comma = i
                row[i] += 0.9 if i <= 2 else 3.0
                if i <= 2:
                    row[i - 1] += 2.2

            if current.pos_ == "CCONJ" and first_coordinator is None:
                first_coordinator = i
                row[i] += 1.0

            if current.is_punct and not is_comma:
                row[i - 1] += 0.2
                if first_comma is not None:
                    row[first_comma] += 0.65

    return (
        "local_phrase_links_with_early_function_anchor",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L2H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict persistent early anchors with targeted local modifier refresh.
    Non-degree subordinators fade; nearby nominal modifiers and auxiliaries refresh.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_anchors_local_modifier_refresh", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    first_piece = {}
    for i, sids in enumerate(alignment):
        for sid in sids:
            if sid not in first_piece and tokens[i] not in special_tokens:
                first_piece[sid] = i

    strength = np.full(n, 0.10, dtype=np.float64)
    persistence = np.full(n, 0.035, dtype=np.float64)
    word_ids = [None] * n

    for j, sids in enumerate(alignment):
        if tokens[j] in special_tokens:
            strength[j] = 0.0
            continue
        if not sids:
            strength[j] = 0.12
            continue

        sid = sids[0]
        word_ids[j] = sid
        word = doc[sid]
        if first_piece.get(sid) != j:
            strength[j] = 0.08
            continue

        pos, dep = word.pos_, word.dep_
        if word.is_punct:
            if "," in word.text:
                strength[j], persistence[j] = 24.0, 0.55
            elif ";" in word.text or ":" in word.text:
                strength[j], persistence[j] = 15.0, 0.45
            elif any(c in word.text for c in ".!?"):
                strength[j], persistence[j] = 2.5, 0.14
            else:
                strength[j] = 0.18
        elif pos == "CCONJ":
            strength[j], persistence[j] = 16.0, 0.45
        elif pos == "SCONJ" or dep == "mark":
            strength[j], persistence[j] = 14.0, 0.35
        elif pos == "DET" and dep != "poss":
            strength[j] = 8.0 if j == 1 else 14.0
            persistence[j] = 0.28
        elif dep == "poss":
            strength[j], persistence[j] = 0.85, 0.08
        elif pos == "ADP":
            strength[j], persistence[j] = 7.5, 0.22
        elif pos == "PART" and dep == "aux":
            strength[j], persistence[j] = 8.0, 0.20
        elif pos == "ADV":
            degree_modifier = (
                dep == "advmod"
                and word.head.pos_ in ("ADJ", "ADV")
                and word.head.i > sid
            )
            strength[j] = 14.0 if degree_modifier else 1.7
            persistence[j] = 0.24 if degree_modifier else 0.07
        elif pos == "AUX":
            strength[j], persistence[j] = 2.8, 0.09
        elif pos == "VERB":
            strength[j] = 3.2
            if sid > 0 and doc[sid - 1].pos_ == "PRON":
                strength[j] = 1.0
            persistence[j] = 0.08
        elif pos == "PRON":
            strength[j] = 3.55 if j == 1 else 0.45
            persistence[j] = 0.07
        elif pos == "ADJ":
            strength[j], persistence[j] = 0.65, 0.05
        elif pos == "NOUN":
            strength[j], persistence[j] = 0.25, 0.035
        elif pos == "PROPN":
            strength[j], persistence[j] = 0.21, 0.035

    # Clause markers are not persistent degree-modifier anchors.
    clause_markers = [
        j for j, sid in enumerate(word_ids)
        if sid is not None
        and first_piece.get(sid) == j
        and doc[sid].pos_ == "SCONJ"
        and doc[sid].dep_ != "advmod"
    ]

    positions = np.arange(n, dtype=np.float64)
    key_strength = strength * np.exp(-0.11 * positions)

    for i in range(n):
        distances = i - positions[:i + 1]
        retention = persistence[:i + 1]
        scores = key_strength[:i + 1] * (
            retention + (1.0 - retention) * np.exp(-distances / 4.0)
        )

        # BOS is a fallback, rather than the principal linguistic anchor.
        scores[0] += 1.20

        # Leave marker self-scores intact; suppress only their lingering tail.
        for target in clause_markers:
            if target < i:
                scores[target] *= 0.20

        sid = word_ids[i]
        if sid is not None:
            word = doc[sid]

            # All subword pieces inherit the word's phrase-initial context.
            start = first_piece.get(sid, i)
            if start < i:
                scores[start] *= 0.30

            # Predicates retain some attention to their preceding auxiliary;
            # modified adjectives instead favor their degree modifier.
            if word.pos_ in ("ADJ", "VERB", "ADV"):
                for child in word.children:
                    if child.i >= sid:
                        continue
                    target = first_piece.get(child.i)
                    if target is None or target > i:
                        continue
                    if child.dep_ == "advmod":
                        scores[target] *= 2.3
                    elif child.dep_ in ("aux", "auxpass", "cop"):
                        scores[target] *= 1.7

            # Noun phrases keep their determiner active across adjectives
            # and across tokenizer splits of the noun.
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                head = word.head if word.pos_ == "ADJ" else word
                for child in head.children:
                    if child.dep_ != "det" or child.i > sid:
                        continue
                    target = first_piece.get(child.i)
                    if target is not None and target <= i:
                        scores[target] *= 1.35

            # Refresh only a nearby, directly attached modifier or auxiliary.
            # The floor is relative to competing mass, so late dependencies
            # can survive absolute-position suppression without changing decay.
            refresh_mass = scores.sum()
            for child in word.children:
                target = first_piece.get(child.i)
                if (
                    child.i >= sid or sid - child.i > 3
                    or target is None or target >= i
                ):
                    continue
                ratio = 0.0
                if word.pos_ in ("NOUN", "PROPN"):
                    if child.dep_ == "amod":
                        ratio = 0.50
                        if any(c.dep_ == "advmod" for c in child.children):
                            ratio = 1.60
                    elif child.dep_ == "poss":
                        ratio = 0.20
                if word.pos_ in ("ADJ", "VERB", "ADV"):
                    if child.dep_ in ("aux", "auxpass", "cop"):
                        ratio = 0.80
                    elif child.dep_ == "advmod" and word.pos_ in ("ADJ", "ADV"):
                        ratio = 1.60
                if ratio:
                    scores[target] = max(
                        scores[target],
                        ratio * (refresh_mass - scores[target]),
                    )

        attention[i, :i + 1] = scores

    return "early_anchors_local_modifier_refresh", make_row_stochastic(attention)


def prog_L2H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early phrase-boundary anchors; in multi-utterance dialogue, whitespace
    boundaries compete with the persistent comma sink and expose auxiliary links."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_anchors_with_dialogue_competition", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    specials = tokenizer.all_special_tokens

    word_ids = []
    for ids in aligned:
        word_ids.append(ids[0] if ids else -1)

    first_piece = {}
    for i, sid in enumerate(word_ids):
        if sid >= 0 and tokens[i] not in specials and sid not in first_piece:
            first_piece[sid] = i

    # Commas and early phrase introducers retain attention far beyond their
    # immediate syntactic constituents. Later anchors compete more weakly.
    anchors = []
    comma_count = 0
    for j in range(n):
        sid = word_ids[j]
        if tokens[j] in specials:
            continue

        if "," in tokens[j]:
            strength = (
                11.0
                * np.exp(-0.095 * max(j - 3, 0))
                / (1.0 + 0.65 * comma_count)
            )
            anchors.append((j, strength, 0.030))
            comma_count += 1
            continue

        if sid < 0 or first_piece.get(sid) != j:
            continue

        word = doc[sid]
        position_decay = np.exp(-0.12 * max(j - 2, 0))
        if word.pos_ == "CCONJ":
            anchors.append((j, 7.0 * position_decay, 0.040))
        elif word.pos_ == "DET":
            anchors.append((j, 3.8 * position_decay, 0.065))
        elif word.pos_ == "SCONJ":
            anchors.append((j, 3.0 * position_decay, 0.065))
        elif word.pos_ == "ADP":
            anchors.append((j, 1.8 * position_decay, 0.100))

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        sid = word_ids[i]
        word = doc[sid] if sid >= 0 else None

        for j in range(i + 1):
            attention[i, j] = 0.025 * np.exp(-0.035 * (i - j))
        attention[i, 0] += 1.0 * np.exp(-0.17 * (i - 1))
        attention[i, i] += 0.55
        attention[i, i - 1] += 0.48

        if i == 1:
            attention[i, :] = 0.0
            self_weight = 0.48
            if word is not None:
                if word.pos_ == "DET":
                    self_weight = 0.595
                elif word.pos_ == "PROPN":
                    self_weight = 0.24
                elif word.pos_ in ("ADP", "ADV", "NUM"):
                    self_weight = 0.44
            attention[i, 0] = 1.0 - self_weight
            attention[i, i] = self_weight
            continue

        for j, strength, decay in anchors:
            if j <= i:
                attention[i, j] += strength * np.exp(-decay * (i - j))

        if word is None:
            continue

        # Favor the immediately preceding modifier or auxiliary rather than
        # treating all noun-phrase tokens as equivalent.
        previous_sid = -1
        for j in range(i - 1, -1, -1):
            candidate = word_ids[j]
            if candidate >= 0 and candidate != sid:
                previous_sid = candidate
                break

        if previous_sid >= 0:
            previous = doc[previous_sid]
            target = first_piece.get(previous_sid)
            if target is not None:
                distance = i - target
                if previous.pos_ == "ADJ" and word.pos_ in ("ADJ", "NOUN", "PROPN"):
                    attention[i, target] += 4.5 * np.exp(-0.04 * distance)
                elif previous.pos_ == "AUX" and word.pos_ in (
                    "VERB", "ADV", "ADJ", "PART"
                ):
                    attention[i, target] += 3.4
                elif previous.pos_ == "NOUN" and word.pos_ == "NOUN":
                    attention[i, target] += 2.6

        # A continuation piece inherits the preceding lexical context.
        start = first_piece.get(sid, i)
        if start < i:
            attention[i, start] += 1.0
            if start > 0:
                attention[i, start - 1] += 1.2

        head_sid = word.head.i
        head_target = first_piece.get(head_sid)
        if head_target is not None and head_target < i and head_sid != sid:
            if word.dep_ in ("aux", "auxpass", "neg", "advmod", "prt"):
                attention[i, head_target] += 1.3
            elif word.dep_ in ("conj", "compound", "poss", "nmod"):
                attention[i, head_target] += 1.0

        if word.pos_ in ("VERB", "AUX"):
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    target = first_piece.get(child.i)
                    if target is not None and target < i:
                        attention[i, target] += 0.8

    # Restrict the correction to quoted dialogue with an explicit whitespace
    # boundary. Ordinary narrative retains exactly the original raw weights.
    dialogue_boundaries = [
        j for j, token in enumerate(tokens)
        if j > 1
        and token not in specials
        and token
        and not token.strip("▁Ġ \t\r\n")
    ]
    if dialogue_boundaries and any(word.is_quote for word in doc):
        for i in range(2, n):
            # Reduce only the persistent comma contribution, not its baseline
            # or diagonal weight; retain the original positional decay.
            for j, strength, decay in anchors:
                if j < i and "," in tokens[j]:
                    attention[i, j] -= (
                        0.5 * strength * np.exp(-decay * (i - j))
                    )

            previous_boundaries = [j for j in dialogue_boundaries if j < i]
            if previous_boundaries:
                target = previous_boundaries[-1]
                attention[i, target] += 1.4 * np.exp(-0.08 * (i - target))

            # In questions, an intervening subject can separate an auxiliary
            # from its verb; the original adjacent-word rule misses this link.
            sid = word_ids[i]
            if sid >= 0 and doc[sid].pos_ == "VERB":
                for child in doc[sid].children:
                    target = first_piece.get(child.i)
                    if (
                        child.dep_ in ("aux", "auxpass")
                        and target is not None
                        and target < i
                        and sid - child.i > 1
                        and i - target <= 5
                    ):
                        attention[i, target] += 1.5

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "early_anchors_with_dialogue_competition", attention


def prog_L2H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Early phrase anchors persist, but possessive openings yield to later
    coordination and clause boundaries rather than remaining global sinks."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "early_phrase_anchors_with_possessive_release", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    word_ids = []
    starts = {}
    pieces = {}
    for i, ids in enumerate(alignment):
        valid = [k for k in ids if k < len(doc) and not doc[k].is_space]
        sid = valid[0] if valid and tokens[i] not in special else None
        word_ids.append(sid)
        if sid is not None:
            if sid not in starts:
                starts[sid] = i
                pieces[sid] = []
            pieces[sid].append(i)

    lexical = [
        i for i, sid in enumerate(word_ids)
        if sid is not None and not doc[sid].is_punct
    ]
    first = lexical[0] if lexical else 0
    first_sid = word_ids[first]
    first_pos = doc[first_sid].pos_ if first_sid is not None else ""

    anchor_strength = np.zeros(n, dtype=np.float64)
    anchor_strength[0] = 0.32
    if first > 0:
        anchor_strength[first] = (
            2.4 if first_pos in ("DET", "PRON") else 0.45
        )

    for sid, i in starts.items():
        w = doc[sid]
        distance = max(0, i - first)
        possessive = w.dep_ == "poss" or "Yes" in w.morph.get("Poss")
        if w.pos_ == "DET" or possessive:
            strength = 3.8 * np.exp(-0.11 * distance)
            anchor_strength[i] = max(anchor_strength[i], strength)
        elif w.pos_ == "CCONJ":
            anchor_strength[i] = max(
                anchor_strength[i], 1.05 * np.exp(-0.065 * distance)
            )
        elif w.pos_ == "PRON" and w.dep_ in ("nsubj", "nsubjpass"):
            anchor_strength[i] = max(
                anchor_strength[i], 0.55 * np.exp(-0.09 * distance)
            )
        if "," in w.text:
            anchor_strength[i] = max(
                anchor_strength[i], 5.5 * np.exp(-0.14 * distance)
            )

    matrix[0, 0] = 1.0
    for i in range(1, n):
        sid = word_ids[i]

        if i == first:
            bos_mass = 0.59 if first_pos == "DET" else 0.80
            if first_pos in ("PROPN", "ADP", "SCONJ"):
                bos_mass = 0.88
            matrix[i, 0] = bos_mass
            matrix[i, i] += 1.0 - bos_mass
            continue

        available = anchor_strength[:i + 1].copy()

        # Once an early noun phrase appears, it supersedes a pronoun opening.
        if first_pos == "PRON":
            for k in range(first + 1, i + 1):
                ks = word_ids[k]
                if ks is not None and starts[ks] == k:
                    if doc[ks].pos_ == "DET" and k <= first + 6:
                        available[first] *= 0.22
                        break

        age = i - np.arange(i + 1)
        background = 0.025 * np.exp(-age / 12.0)
        global_weights = available + background
        global_weights /= global_weights.sum()

        local = np.zeros(i + 1, dtype=np.float64)
        local[i] = 0.24
        local[i - 1] += 0.13
        local_mass = 0.22

        if sid is not None:
            w = doc[sid]
            earlier_pieces = [k for k in pieces[sid] if k < i]

            if earlier_pieces and not w.is_punct:
                local[:] = 0.0
                local[earlier_pieces[0]] = 0.76
                local[earlier_pieces[-1]] += 0.20
                local[i] = 0.04
                local_mass = 0.88
            else:
                if w.pos_ == "DET" or w.dep_ == "poss":
                    local[i] += 1.8
                    local_mass = 0.53 if i < first + 7 else 0.32
                elif w.pos_ == "CCONJ":
                    local[i] += 1.7
                    local_mass = 0.48
                elif w.is_punct and "," in w.text:
                    local[i] += 1.7
                    local_mass = 0.48

                previous_sid = word_ids[i - 1]
                if previous_sid is not None and previous_sid != sid:
                    previous = doc[previous_sid]
                    previous_start = starts[previous_sid]
                    if (
                        w.pos_ in ("NOUN", "PROPN", "ADJ", "NUM")
                        and (
                            previous.pos_ in ("DET", "ADJ", "NUM")
                            or previous.dep_ == "poss"
                        )
                    ):
                        local[previous_start] += 2.7
                        local_mass = max(local_mass, 0.66)

                if w.dep_ in ("prt", "compound:prt"):
                    head_start = starts.get(w.head.i)
                    if head_start is not None and head_start <= i:
                        local[head_start] += 3.0
                        local_mass = max(local_mass, 0.72)

                if w.pos_ in ("VERB", "AUX") and previous_sid is not None:
                    if doc[previous_sid].pos_ == "CCONJ":
                        local[starts[previous_sid]] += 2.0
                        local_mass = max(local_mass, 0.48)

        local /= local.sum()
        matrix[i, :i + 1] = (
            (1.0 - local_mass) * global_weights + local_mass * local
        )

    # Only possessive-pronominal openings receive this correction. Transfer
    # off-diagonal mass, leaving every original self-attention weight intact.
    if (
        first > 0
        and first_sid is not None
        and first_pos in ("DET", "PRON")
        and (
            doc[first_sid].dep_ == "poss"
            or "Yes" in doc[first_sid].morph.get("Poss")
        )
    ):
        boundaries = [
            (k, 1.4 if "," in doc[s].text else 1.0)
            for s, k in starts.items()
            if k > first
            and (doc[s].pos_ == "CCONJ" or "," in doc[s].text)
        ]
        for i in range(first + 1, n):
            if word_ids[i] == first_sid:
                continue
            prior = [(k, weight) for k, weight in boundaries if k < i]
            if prior:
                recipients = prior[-2:]
                release = 0.88
            else:
                recipients = [(0, 0.60)]
                if i - 1 > first:
                    recipients.append((i - 1, 0.40))
                release = 0.45 if i == first + 1 else 0.62

            mass = release * matrix[i, first]
            matrix[i, first] -= mass
            total = sum(weight for _, weight in recipients)
            for k, weight in recipients:
                matrix[i, k] += mass * weight / total

    return (
        "early_phrase_anchors_with_possessive_release",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L2H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict sticky phrase boundaries, retaining earlier anchors when later
    nominal introducers overwrite them, with a subject-pronoun fallback.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_phrase_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                inverse[wi].append(ti)

    special_tokens = tokenizer.all_special_tokens
    nominal_anchor = None
    nominal_strength = 0.0
    coordinator = None
    commas = []

    object_deps = ("obj", "dobj", "iobj", "pobj", "attr", "oprd")
    nominal_deps = ("det", "poss", "nmod:poss", "predet")
    introducer_pos = ("VERB", "AUX", "ADP", "SCONJ", "CCONJ")

    # Keep true determiner anchors distinct from possessive nouns.
    determiner_positions = [
        inverse[w.i][0] for w in doc
        if inverse[w.i] and w.pos_ == "DET" and w.dep_ != "predet"
    ]
    subject_positions = [
        inverse[w.i][0] for w in doc
        if inverse[w.i]
        and w.pos_ == "PRON"
        and w.dep_ in ("nsubj", "nsubjpass", "nsubj:pass")
    ]

    for i, token in enumerate(tokens):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        word_ids = alignment[i]
        wi = word_ids[0] if word_ids else None
        word = doc[wi] if wi is not None else None
        first_piece = word is not None and inverse[wi][0] == i

        # A small causal background keeps secondary edges visible.
        positions = np.arange(i + 1)
        background = np.exp(-(i - positions) / 5.0)
        background /= background.sum()
        attention[i, :i + 1] = 0.12 * background
        attention[i, 0] += 0.04
        attention[i, i] += 0.05

        if i == 1 and token not in special_tokens:
            bos_mass = 0.79 if word is not None and word.pos_ == "DET" else 0.86
            attention[i, :i + 1] = 0.0
            attention[i, 0] = bos_mass
            attention[i, i] = 1.0 - bos_mass
            if word is not None and (
                word.pos_ == "DET" or word.dep_ in nominal_deps
            ):
                nominal_anchor = i
                nominal_strength = 0.95
            continue

        anchors = np.zeros(i + 1, dtype=np.float64)
        if nominal_anchor is not None:
            distance = i - nominal_anchor
            anchors[nominal_anchor] += nominal_strength * np.exp(-0.018 * distance)

        if commas:
            anchors[commas[0]] += 0.90 * np.exp(-0.018 * (i - commas[0]))
            if commas[-1] != commas[0]:
                anchors[commas[-1]] += 0.33 * np.exp(-0.04 * (i - commas[-1]))

        if coordinator is not None:
            anchors[coordinator] += 0.57 * np.exp(-0.10 * (i - coordinator))

        target = None
        confidence = 0.0

        if word is not None:
            previous = doc[wi - 1] if wi > 0 else None
            is_nominal_intro = word.pos_ == "DET" or word.dep_ in nominal_deps

            if first_piece and is_nominal_intro and previous is not None:
                if inverse[wi - 1]:
                    target = inverse[wi - 1][0]
                    if previous.pos_ in introducer_pos:
                        confidence = 0.90
                    elif previous.is_punct:
                        confidence = 0.59
                    else:
                        confidence = 0.64

            elif first_piece and word.pos_ == "PRON" and word.dep_ in object_deps:
                head_indices = inverse[word.head.i]
                if head_indices and head_indices[0] < i:
                    target = head_indices[0]
                    confidence = 0.78

            elif (
                not first_piece
                and word.pos_ in ("VERB", "AUX")
                and inverse[wi][0] < i
            ):
                target = inverse[wi][0]
                confidence = 0.82

            # Noun phrases tend to point to their left-edge determiner,
            # including across adjectives and subword pieces.
            elif word.pos_ in ("NOUN", "PROPN"):
                candidates = [
                    child for child in word.children
                    if child.dep_ in nominal_deps
                    and inverse[child.i]
                    and inverse[child.i][0] < i
                ]
                if candidates:
                    determiner = candidates[0]
                    target = inverse[determiner.i][0]
                    confidence = 0.68
                    if commas and target > commas[-1]:
                        before = determiner.i - 1
                        if before >= 0 and doc[before].is_punct:
                            confidence = 0.27

            if first_piece and word.pos_ == "CCONJ":
                target = i
                confidence = 0.48

            if "," in token:
                target = i
                confidence = 0.48 if commas else 0.56

        if anchors.sum() > 0:
            anchors /= anchors.sum()
        else:
            anchors[0] = 0.55
            anchors[max(0, i - 1)] += 0.45

        attention[i, :i + 1] += 0.79 * anchors

        if target is not None and target <= i:
            attention[i, :i + 1] *= 1.0 - confidence
            attention[i, target] += confidence

        # Special case: later nominal anchors do not erase earlier boundaries.
        # Transfer only off-diagonal mass, preserving the original self weight.
        earlier_determiners = [
            p for p in determiner_positions
            if nominal_anchor is not None and p < nominal_anchor
        ]
        if earlier_determiners and nominal_anchor < i:
            destinations = np.zeros(i, dtype=np.float64)
            destinations[earlier_determiners[0]] += 0.55
            if earlier_determiners[-1] != earlier_determiners[0]:
                destinations[earlier_determiners[-1]] += 0.30
            if commas:
                destinations[commas[0]] += 0.55
                if commas[-1] != commas[0]:
                    destinations[commas[-1]] += 0.20
            destinations /= destinations.sum()

            sources = {nominal_anchor}
            if (
                word is not None
                and first_piece
                and word.pos_ in ("NOUN", "PROPN")
                and word.dep_ in ("poss", "nmod:poss")
                and target is not None
                and target < i
            ):
                sources.add(target)

            moved = 0.0
            for source in sources:
                amount = 0.72 * attention[i, source]
                attention[i, source] -= amount
                moved += amount
            attention[i, :i] += moved * destinations

        # Without an initial determiner, a sentence-initial subject pronoun
        # supplies the missing persistent anchor until a determiner appears.
        elif (
            nominal_anchor is None
            and subject_positions
            and subject_positions[0] == 1
            and subject_positions[0] < i
        ):
            prior_subjects = [p for p in subject_positions if p < i]
            destinations = np.zeros(i, dtype=np.float64)
            destinations[prior_subjects[0]] += 0.70
            destinations[prior_subjects[-1]] += 0.30
            moved = 0.65 * attention[i, :i].sum()
            attention[i, :i] *= 0.35
            attention[i, :i] += moved * destinations

        # Update memory only after computing the current row.
        if word is not None and first_piece:
            if word.pos_ == "DET" or word.dep_ in nominal_deps:
                nominal_anchor = i
                previous = doc[wi - 1] if wi > 0 else None
                if previous is not None and previous.is_punct:
                    nominal_strength = 0.30
                elif previous is not None and previous.pos_ in introducer_pos:
                    nominal_strength = 1.55
                else:
                    nominal_strength = 0.95
            if word.pos_ == "CCONJ":
                coordinator = i

        if "," in token:
            commas.append(i)

    return (
        "persistent_phrase_boundary_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L2H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Phrase-onset anchors persist beyond their noun phrase: an established
    determiner remains a background anchor for subsequent phrases."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "phrase_onset_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(aligned):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                word_tokens[wi].append(ti)

    first = [ids[0] if ids else -1 for ids in word_tokens]
    last = [ids[-1] if ids else -1 for ids in word_tokens]
    special = set(tokenizer.all_special_tokens)
    content = [i for i, t in enumerate(tokens) if t not in special]
    if not content:
        attention[:] = np.tril(np.ones((n, n)))
        return "phrase_onset_anchors", make_row_stochastic(attention)

    initial = content[0]
    initial_words = aligned[initial]
    initial_word = doc[initial_words[0]] if initial_words else None

    commas = []
    for wi, word in enumerate(doc):
        if word.is_punct and word.text == "," and first[wi] >= 0:
            commas.append(first[wi])

    # Only noninitial nominal introducers can establish this extra anchor.
    persistent_candidates = [
        word for word in doc
        if word.dep_ in ("det", "poss")
        and word.head.pos_ in ("NOUN", "PROPN")
        and initial < first[word.i] < first[word.head.i]
        and last[word.head.i] >= 0
    ]

    for i in range(n):
        if tokens[i] in special:
            attention[i, i] = 1.0
            continue

        row = attention[i]
        distance = i - np.arange(i + 1)
        row[:i + 1] = 0.025 + 0.045 * np.exp(-distance / 9.0)
        row[0] += 0.22
        row[i] += 0.12
        if i > 0:
            row[i - 1] += 0.22

        if i == initial:
            if initial_word is None:
                self_mass = 0.65
            elif initial_word.pos_ == "DET":
                self_mass = 0.93
            elif initial_word.pos_ == "PRON":
                self_mass = 0.92
            elif initial_word.pos_ == "NUM":
                self_mass = 0.83
            elif initial_word.pos_ in ("ADP", "SCONJ"):
                self_mass = 0.30
            else:
                self_mass = 0.54
            row[:] = 0.0
            if i == 0:
                row[i] = 1.0
            else:
                row[0] = 1.0 - self_mass
                row[i] = self_mass
            continue

        word_ids = aligned[i]
        wi = word_ids[0] if word_ids else -1
        word = doc[wi] if wi >= 0 else None
        previous = doc[wi - 1] if wi > 0 else None

        past_commas = [c for c in commas if c <= i]
        anchor_strength = 6.5 * np.exp(-(i - initial) / 9.0)
        if initial_word is not None and initial_word.pos_ in ("ADP", "SCONJ"):
            anchor_strength *= 0.18
        if past_commas:
            anchor_strength *= 0.32
        row[initial] += anchor_strength

        for number, c in enumerate(past_commas):
            strength = 2.5 if number == 0 else 1.0
            row[c] += strength * np.exp(-(i - c) / 35.0)
        if past_commas:
            c = past_commas[-1]
            row[c] += 5.5 * np.exp(-(i - c) / 2.8)

        if word is None:
            if i > 0 and tokens[i].isspace():
                row[i] += 1.0
            continue

        # Nominal phrases anchor on their determiner or possessive introducer.
        nominal = word
        if word.dep_ in ("amod", "compound", "nummod"):
            nominal = word.head

        determiners = [
            child for child in nominal.children
            if child.dep_ in ("det", "poss", "nummod")
            and first[child.i] >= 0 and first[child.i] <= i
        ]
        if word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM") and determiners:
            determiner = min(determiners, key=lambda child: child.i)
            anchor = first[determiner.i]
            row[anchor] += 8.0
            if anchor != initial:
                row[initial] *= 0.35

        if word.pos_ == "DET" or word.dep_ == "poss":
            row[first[wi]] += 3.8
            if not past_commas and wi <= 2:
                row[first[wi]] += 4.0

        if word.pos_ == "CCONJ":
            row[first[wi]] += 4.0

        # Predicates prefer a nearby subject, auxiliary, coordinator, or marker.
        if word.pos_ in ("VERB", "AUX", "ADJ"):
            if previous is not None and last[previous.i] < first[wi]:
                p = last[previous.i]
                if p >= 0:
                    if previous.pos_ == "AUX":
                        row[p] += 9.0
                        row[initial] *= 0.55
                    elif previous.pos_ == "PRON":
                        row[first[previous.i]] += 6.5
                    elif previous.pos_ in ("PART", "CCONJ", "SCONJ"):
                        row[p] += 6.0
                    elif previous.pos_ == "ADV":
                        row[p] += 5.0
                    elif previous.pos_ == "VERB":
                        row[p] += 5.5
                    elif previous.pos_ == "ADP" and word.pos_ == "VERB":
                        row[p] += 6.0

            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass"):
                    subject_anchor = first[child.i]
                    if 0 <= subject_anchor <= i:
                        if child.pos_ == "PRON":
                            row[subject_anchor] += 3.0
                        else:
                            for modifier in child.children:
                                if modifier.dep_ in ("det", "poss"):
                                    a = first[modifier.i]
                                    if 0 <= a <= i:
                                        row[a] += 3.5

        # Continuation pieces retain the word's external onset anchor.
        if first[wi] >= 0 and i > first[wi]:
            onset_row = attention[first[wi], :first[wi] + 1]
            total = onset_row.sum()
            if total > 0:
                row[:first[wi] + 1] += 4.0 * onset_row / total

        # Once its noun has ended, retain the earliest established nominal
        # anchor, preferring a definite/possessive introducer when available.
        # Redistribute only past-token mass: self weight and row total stay
        # exactly unchanged, and all original behavior precedes this handler.
        established = [
            candidate for candidate in persistent_candidates
            if last[candidate.head.i] < i
        ]
        if established:
            definite = [
                candidate for candidate in established
                if candidate.dep_ == "poss"
                or "Def" in candidate.morph.get("Definite")
            ]
            persistent = min(
                definite if definite else established,
                key=lambda candidate: first[candidate.i],
            )
            anchor = first[persistent.i]
            past_mass = row[:i].sum()
            row[:i] *= 0.55
            row[anchor] += 0.45 * past_mass

    return "phrase_onset_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L2H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict syntactic phrase onsets, with infinitival complements anchored
    to their governing predicate rather than their infinitival particle.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "syntactic_phrase_onsets", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    first = [min(x) if x else -1 for x in inverse]
    last = [max(x) if x else -1 for x in inverse]

    special = set(tokenizer.all_special_tokens)
    bos = 0
    for i, piece in enumerate(tokens):
        if piece in special:
            attention[i, 0] = 1.0
            continue

        # A weak causal background retains secondary and distant edges.
        attention[i, :i + 1] = 0.018 * np.exp(
            -(i - np.arange(i + 1)) / 9.0
        )
        attention[i, bos] += 0.12
        attention[i, i] += 0.11
        if i > 0:
            attention[i, i - 1] += 0.09

        sids = aligned[i]
        if not sids:
            if i > 0:
                attention[i, i - 1] += 0.40
            continue

        s = sids[-1]
        w = doc[s]
        previous = doc[s - 1] if s > 0 else None
        candidates = []

        # The first lexical token distinguishes determiner phrase openings.
        if s == 0:
            if w.pos_ == "DET":
                attention[i, :] = 0.0
                attention[i, first[s]] = 0.602
                attention[i, bos] += 0.398
            else:
                attention[i, bos] += 0.85
            continue

        # Locate the current local clause boundary.
        boundary = -1
        for k in range(s - 1, max(-1, s - 15), -1):
            if doc[k].is_punct and doc[k].text in (",", ";", ":", "!", "?"):
                boundary = k
                break
            if doc[k].is_punct and doc[k].text == ".":
                break

        if boundary >= 0:
            distance = s - boundary
            if distance <= 4:
                strength = 0.64 if w.pos_ in (
                    "PRON", "PROPN", "VERB", "AUX", "SCONJ", "CCONJ"
                ) else 0.23
                candidates.append((boundary, strength, False))

        # Nominal phrases commonly point back to their preposition or onset.
        if w.pos_ in ("NOUN", "PROPN", "PRON", "NUM"):
            prep = w.head if w.dep_ in ("pobj", "pcomp", "obl") else None
            if prep is not None and prep.i < s and prep.pos_ == "ADP":
                candidates.append((prep.i, 1.15, False))
            else:
                determiners = [
                    c for c in w.children
                    if c.i < s and c.dep_ in ("det", "poss", "nummod")
                ]
                modifiers = [
                    c for c in w.children
                    if c.i < s and c.dep_ in ("amod", "advmod", "compound")
                ]
                if determiners:
                    d = min(determiners, key=lambda c: c.i)
                    candidates.append((d.i, 0.75, False))
                if modifiers:
                    m = max(modifiers, key=lambda c: c.i)
                    candidates.append((m.i, 0.55, False))
                if w.head.i < s and w.dep_ in (
                    "dobj", "obj", "attr", "oprd", "dative"
                ):
                    candidates.append((w.head.i, 0.68, False))

        # Adjectival material often inherits the onset of its nominal phrase.
        if w.pos_ in ("ADJ", "NUM") and w.head.i >= s:
            nominal = w.head
            ds = [
                c for c in nominal.children
                if c.i < s and c.dep_ in ("det", "poss")
            ]
            if ds:
                d = min(ds, key=lambda c: c.i)
                candidates.append((d.i, 0.66, False))
                if nominal.head.i < d.i and nominal.head.pos_ == "VERB":
                    candidates.append((nominal.head.i, 0.55, False))

        if w.pos_ in ("VERB", "AUX"):
            auxiliaries = [
                c for c in w.children
                if c.i < s and c.dep_ in ("aux", "auxpass", "cop")
            ]
            adverbs = [
                c for c in w.children
                if c.i < s and c.dep_ in ("advmod", "neg")
                and s - c.i <= 4
            ]
            if auxiliaries:
                candidates.append((
                    max(auxiliaries, key=lambda c: c.i).i, 1.10, False
                ))
            elif adverbs:
                candidates.append((
                    max(adverbs, key=lambda c: c.i).i, 0.95, False
                ))
            elif w.head.i < s and w.dep_ in (
                "xcomp", "ccomp", "advcl", "pcomp"
            ):
                candidates.append((w.head.i, 0.95, False))

            if previous is not None and previous.pos_ in (
                "CCONJ", "SCONJ", "ADV"
            ):
                candidates.append((previous.i, 0.78, False))

            # Infinitival particles are not finite auxiliary phrase onsets.
            # Redirect only the existing auxiliary edge, keeping its weight
            # and all other candidates and background weights unchanged.
            if (
                w.pos_ == "VERB"
                and w.dep_ == "xcomp"
                and w.head.pos_ in ("VERB", "ADJ")
                and w.head.i < s
                and 0 <= first[w.head.i] <= i
                and auxiliaries
            ):
                marker = max(auxiliaries, key=lambda c: c.i)
                if marker.pos_ == "PART" and marker.dep_ == "aux":
                    candidates = [
                        (
                            w.head.i if sid == marker.i and not use_last else sid,
                            weight,
                            use_last,
                        )
                        for sid, weight, use_last in candidates
                    ]

        # Prepositions and particles select their left-hand governor.
        if w.pos_ == "ADP" or w.dep_ == "prt":
            if w.head.i < s:
                candidates.append((w.head.i, 1.10, True))
            elif previous is not None:
                candidates.append((previous.i, 0.60, True))

        if w.pos_ in ("ADV", "ADJ") and w.head.i < s:
            candidates.append((w.head.i, 0.72, False))
        if w.pos_ == "SCONJ" and previous is not None:
            if previous.pos_ in ("ADV", "SCONJ"):
                candidates.append((previous.i, 1.0, False))

        if w.pos_ == "DET":
            candidates.append((s, 0.35, False))
            if w.head.head.i < s and w.head.head.pos_ in ("VERB", "ADP"):
                candidates.append((w.head.head.i, 0.45, False))

        # Early subjects and predicates share the sentence-initial phrase anchor.
        if s <= 4 and doc[0].pos_ == "DET":
            if w.pos_ in ("NOUN", "ADJ", "AUX", "VERB"):
                candidates.append((0, 1.05, False))
        elif s <= 2 and w.pos_ in ("VERB", "AUX"):
            attention[i, bos] += 0.65

        if w.is_punct:
            attention[i, i] += 0.28
            if previous is not None and previous.pos_ == "VERB":
                candidates.append((previous.i, 0.35, False))

        # Continuation pieces inherit word-level anchors, not just the prior piece.
        if first[s] >= 0 and i > first[s] and not candidates:
            if previous is not None:
                candidates.append((previous.i, 0.65, False))

        for sid, weight, use_last in candidates:
            j = last[sid] if use_last else first[sid]
            if 0 <= j <= i:
                attention[i, j] += weight

    return "syntactic_phrase_onsets", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L2H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent phrase-onset anchors, with possessive and embedded-subject onsets.
    Overt noun-phrase onsets take precedence over compact-PP shortcuts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_phrase_onsets", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for sid in sids:
            if sid < len(doc):
                inverse[sid].append(ti)

    special = set(tokenizer.all_special_tokens)
    first = {}
    for sid, indices in enumerate(inverse):
        if indices:
            first[sid] = indices[0]

    # Each anchor has a strength and a persistence timescale.
    anchors = []
    comma_count = 0
    for i, token in enumerate(tokens):
        if token in special:
            if i == 0:
                anchors.append((i, 1.0, 1000.0))
            continue
        sids = alignment[i]
        word = doc[sids[0]] if sids else None

        if "," in token:
            comma_count += 1
            strength = 9.0 / (comma_count ** 0.45)
            anchors.append((i, strength, 90.0))
        elif word is not None and first.get(word.i) == i:
            if word.pos_ == "DET":
                strength = 7.0 / (1.0 + 0.055 * i)
                anchors.append((i, strength, 55.0))
            elif word.pos_ == "CCONJ":
                anchors.append((i, 6.0, 16.0))
            elif word.pos_ == "PRON" and i <= 2:
                anchors.append((i, 5.0, 13.0))
            # Possessives can be tagged PRON rather than DET.
            elif word.dep_ == "poss":
                strength = 7.0 / (1.0 + 0.055 * i)
                anchors.append((i, strength, 55.0))
            # Embedded pronominal subjects establish a local clause onset.
            elif word.pos_ == "PRON" and word.dep_ in (
                "nsubj", "nsubjpass", "csubj"
            ):
                anchors.append((i, 4.0, 13.0))

    for i, token in enumerate(tokens):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        row = matrix[i]
        row[:i + 1] = 0.015
        row[0] += 0.8 * np.exp(-i / 10.0)
        row[i] += 0.45
        row[i - 1] += 0.25

        for j, strength, lifetime in anchors:
            if j <= i:
                row[j] += strength * np.exp(-(i - j) / lifetime)

        sids = alignment[i]
        if not sids:
            if token not in special and not token.replace("▁", "").strip():
                row[i] += 4.0
            continue

        word = doc[sids[0]]
        wi = word.i
        start = first.get(wi, i)
        early = 1.0 / (1.0 + max(0, start - 8) / 18.0)

        # Split pieces retain the same phrase anchor as the whole word.
        determiner = None
        modifiers = []
        coordinators = []
        subjects = []
        for child in word.children:
            if child.i not in first:
                continue
            j = first[child.i]
            if j > i:
                continue
            if child.dep_ in ("det", "poss"):
                if determiner is None or child.i > determiner.i:
                    determiner = child
            if child.dep_ == "amod":
                modifiers.append(child)
            if child.dep_ == "cc":
                coordinators.append(child)
            if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                subjects.append(child)

        if word.pos_ in ("NOUN", "PROPN") and determiner is not None:
            j = first[determiner.i]
            row[j] += 13.0 * early
        elif word.pos_ in ("ADJ", "ADV"):
            head = word.head
            if head.pos_ in ("NOUN", "PROPN"):
                for child in head.children:
                    j = first.get(child.i)
                    if child.dep_ in ("det", "poss") and j is not None and j <= i:
                        row[j] += 12.0 * early

        # An overt NP onset or bare plural blocks the compact-PP shortcut.
        np_onset_exception = (
            word.pos_ in ("NOUN", "PROPN")
            and (
                determiner is not None
                or "Plur" in word.morph.get("Number")
            )
        )

        # Compact PP complements often point back past an intervening article.
        if word.dep_ in ("pobj", "obl") and word.head.pos_ == "ADP":
            j = first.get(word.head.i)
            if j is not None and j <= i and wi - word.head.i <= 3:
                row[j] += 45.0
                if np_onset_exception:
                    row[j] -= 45.0
        elif word.dep_ == "obl":
            for child in word.children:
                j = first.get(child.i)
                if child.dep_ == "case" and j is not None and j <= i:
                    row[j] += 35.0
                    if np_onset_exception:
                        row[j] -= 35.0

        if word.pos_ in ("VERB", "AUX"):
            for subject in subjects:
                j = first[subject.i]
                if subject.pos_ == "PRON":
                    row[j] += 18.0 * early
                else:
                    for child in subject.children:
                        k = first.get(child.i)
                        if child.dep_ in ("det", "poss") and k is not None and k <= i:
                            row[k] += 11.0 * early
            for coordinator in coordinators:
                row[first[coordinator.i]] += 14.0 * early

        # A clause's first complement can use the preceding predicate as anchor.
        head_index = first.get(word.head.i)
        if head_index is not None and head_index < start:
            distance = start - head_index
            if word.dep_ in ("mark", "ccomp", "dobj", "obj", "attr"):
                if distance <= 3 and determiner is None:
                    row[head_index] += 16.0 * early
            if word.pos_ == "PRON" and word.dep_ in ("nsubj", "nsubjpass"):
                if distance <= 2 and word.head.pos_ in ("VERB", "AUX"):
                    row[head_index] += 22.0
            if word.dep_ == "neg":
                row[head_index] += 30.0

        # A complementizer can precede its own predicate while following
        # the matrix predicate: anchor the latter, not the future head.
        if word.dep_ == "mark" and word.head.dep_ == "ccomp":
            governor = word.head.head
            j = first.get(governor.i)
            if (
                governor.pos_ in ("VERB", "AUX")
                and j is not None
                and 0 < start - j <= 3
            ):
                row[j] += 60.0 * early

        # Predicative material inherits a determiner-initial subject anchor.
        if word.dep_ in ("acomp", "attr", "advmod"):
            for subject in word.head.children:
                if subject.dep_ not in ("nsubj", "nsubjpass"):
                    continue
                for child in subject.children:
                    j = first.get(child.i)
                    if child.dep_ in ("det", "poss") and j is not None and j <= i:
                        row[j] += 10.0 * early

        if word.pos_ in ("NOUN", "PROPN") and determiner is None and modifiers:
            modifier = min(modifiers, key=lambda w: w.i)
            row[first[modifier.i]] += 7.0 * early

        if start == i and i == 1 and word.pos_ not in ("DET", "PRON"):
            row[:] = 0.0
            row[0] = 0.73
            row[i] = 0.27

    return "persistent_phrase_onsets", make_row_stochastic(apply_causal_mask(matrix))


def prog_L2H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent phrase-start anchors, with auxiliary and coordination anchors
    for coordinated predicates introduced by an auxiliary.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "persistent_phrase_start_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    word_ids = [
        next((k for k in ids if not doc[k].is_space), None)
        for ids in alignment
    ]

    starts = {}
    for i, k in enumerate(word_ids):
        if k is not None and tokens[i] not in special and k not in starts:
            starts[k] = i

    content = [
        i for i in range(n)
        if tokens[i] not in special
        and (word_ids[i] is not None or tokens[i].strip("▁Ġ \t\n"))
    ]
    first = content[0] if content else 0
    first_word = doc[word_ids[first]] if word_ids[first] is not None else None

    determiners = []
    subjects = []
    conjunctions = []
    commas = []

    for i in range(n):
        clean = tokens[i].strip("▁Ġ \t\n")
        if "," in clean:
            commas.append(i)
        k = word_ids[i]
        if k is None or starts.get(k) != i or tokens[i] in special:
            continue
        w = doc[k]
        if w.pos_ == "DET" or w.dep_ == "poss":
            determiners.append(i)
        if w.pos_ == "PRON" and w.dep_ in ("nsubj", "nsubjpass", "csubj"):
            subjects.append(i)
        if w.pos_ == "CCONJ":
            conjunctions.append(i)

    # A coordinated adjectival predicate shifts the anchor from its initial
    # possessive subject to the auxiliary, then to the coordinating conjunction.
    predicate_coordination = None
    if first_word is not None and (
        first_word.dep_ == "poss" or first_word.pos_ == "PRON"
    ):
        for cj in conjunctions:
            ck = word_ids[cj]
            c = doc[ck]
            predicate = c.head
            if predicate.pos_ not in ("ADJ", "VERB", "AUX"):
                continue
            for ak in range(ck - 1, max(-1, ck - 7), -1):
                auxiliary = doc[ak]
                aj = starts.get(ak)
                if auxiliary.is_punct:
                    break
                if auxiliary.pos_ != "AUX" or aj is None:
                    continue
                adjectives = [
                    w for w in doc[ak + 1:ck] if w.pos_ == "ADJ"
                ]
                if any(
                    w.i == predicate.i
                    or w.head.i == predicate.i
                    or predicate.head.i == w.i
                    for w in adjectives
                ):
                    predicate_coordination = (aj, cj)
                    break
            if predicate_coordination is not None:
                break

    for i in range(n):
        if tokens[i] in special:
            matrix[i, i] = 1.0
            continue

        row = matrix[i]
        distances = i - np.arange(i + 1)
        row[:i + 1] = 0.025 + 0.055 * np.exp(-distances / 8.0)
        row[0] += 0.35
        row[i] += 0.20
        if i > 0:
            row[i - 1] += 0.12

        active_dets = [j for j in determiners if first < j <= i]
        active_commas = [j for j in commas if first < j < i]
        active_conjs = [j for j in conjunctions if first < j <= i]

        if i >= first:
            first_strength = 8.5
            if first_word is not None:
                if first_word.pos_ == "PROPN":
                    first_strength = 1.6
                elif first_word.pos_ in ("ADP", "SCONJ", "ADV"):
                    first_strength = 0.9
                elif first_word.pos_ == "NUM":
                    first_strength = 4.8
            first_strength *= np.exp(-(i - first) / 32.0)
            first_strength *= 0.58 ** min(len(active_dets), 3)
            first_strength *= 0.40 ** min(len(active_commas), 2)
            first_strength *= 0.72 ** min(len(active_conjs), 2)
            row[first] += first_strength

        for rank, j in enumerate(active_dets):
            distance = i - j
            later_dets = len(active_dets) - rank - 1
            later_commas = sum(j < c < i for c in commas)
            strength = 7.8 * np.exp(-distance / 10.0)
            strength *= 0.54 ** min(later_dets, 3)
            strength *= 0.62 ** min(later_commas, 3)
            strength *= 1.0 / (1.0 + j / 32.0)
            row[j] += strength

            # Keep all subpieces of a noun phrase attached to its left edge.
            k = word_ids[i]
            dk = word_ids[j]
            if k is not None and dk is not None:
                w, d = doc[k], doc[dk]
                if (
                    w.i == d.head.i
                    or w.head.i == d.head.i
                    or w.head.head.i == d.head.i
                ):
                    row[j] += (
                        1.8 * np.exp(-distance / 14.0)
                        * 0.65 ** min(later_commas, 2)
                    )

        for rank, j in enumerate(active_commas):
            distance = i - j
            # The first discourse delimiter remains a useful long-range sink.
            strength = (6.8 if rank == 0 else 3.1)
            strength *= np.exp(-distance / (38.0 if rank == 0 else 17.0))
            strength *= 0.85 ** min(len(active_commas) - rank - 1, 4)
            row[j] += strength

        for j in conjunctions:
            if j > i:
                break
            distance = i - j
            if distance > 12:
                continue
            strength = 1.4 * np.exp(-distance / 3.5)
            k, ck = word_ids[i], word_ids[j]
            if k is not None and ck is not None:
                w, c = doc[k], doc[ck]
                if w.i == c.head.i or w.head.i == c.head.i:
                    strength += 4.0 * np.exp(-distance / 5.0)
                elif w.dep_ == "conj":
                    strength += 2.0 * np.exp(-distance / 5.0)
            row[j] += strength

        for j in subjects:
            if j <= first or j > i or i - j > 7:
                continue
            k, sk = word_ids[i], word_ids[j]
            if k is None or sk is None:
                continue
            w, subject = doc[k], doc[sk]
            if w.i == subject.head.i or i == j:
                row[j] += 3.2 * np.exp(-(i - j) / 5.0)

        clean = tokens[i].strip("▁Ġ \t\n")
        if "," in clean:
            row[i] += 0.9
            # A delimiter also looks back to the predicate closing its clause.
            for j in range(i - 1, max(first - 1, i - 9), -1):
                k = word_ids[j]
                if k is not None and doc[k].pos_ in ("VERB", "AUX"):
                    row[starts.get(k, j)] += 4.0
                    break

        # Only the detected construction changes the default anchor weights.
        if predicate_coordination is not None:
            aj, cj = predicate_coordination
            if i >= aj and first < aj:
                row[first] *= 0.35
                row[0] += 1.2 * np.exp(-(i - aj) / 12.0)
                if i <= cj:
                    row[aj] += 4.5 * np.exp(-(i - aj) / 4.0)
                if i > cj:
                    distance = i - cj
                    row[cj] += (
                        4.5
                        * (1.0 - np.exp(-distance / 2.0))
                        * np.exp(-distance / 28.0)
                    )

        if i == first:
            if first_word is not None and first_word.pos_ in ("DET", "PRON"):
                self_mass = 0.93
            elif first_word is not None and first_word.pos_ == "NUM":
                self_mass = 0.86
            elif first_word is not None and first_word.pos_ == "PROPN":
                self_mass = 0.62
            else:
                self_mass = 0.48
            if i > 0:
                row[:] = 0.0
                row[0] = 1.0 - self_mass
                row[i] = self_mass

    return (
        "persistent_phrase_start_anchors",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L2H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Persistent segment-start anchors, with a local copular reset when an
    initial possessive otherwise monopolizes attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "possessive_copular_segment_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    first_piece = {}
    word_ids = []
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if 0 <= k < len(doc)]
        wi = valid[0] if valid else None
        word_ids.append(wi)
        if wi is not None and tokens[i] not in special:
            first_piece.setdefault(wi, i)

    anchors = []
    structural_count = 0
    content_seen = 0
    for i, token in enumerate(tokens):
        if token in special:
            continue
        wi = word_ids[i]
        if wi is None or first_piece.get(wi) != i:
            continue

        word = doc[wi]
        pos = word.pos_
        dep = word.dep_
        kind = None
        strength = 0.0

        if pos == "DET" or dep == "poss":
            kind = "determiner"
            strength = 6.5 / (1.0 + 0.75 * structural_count)
        elif word.text in (",", ";", ":"):
            kind = "boundary"
            strength = 7.0 / (1.0 + 0.60 * structural_count)
        elif pos == "CCONJ":
            kind = "conjunction"
            strength = 4.8 / (1.0 + 0.30 * structural_count)
        elif word.text in (".", "!", "?"):
            kind = "terminal"
            strength = 2.0 / (1.0 + 0.45 * structural_count)
        elif pos == "PRON" and (
            content_seen == 0
            or (structural_count == 0 and dep in ("nsubj", "nsubjpass"))
        ):
            kind = "pronoun"
            strength = 3.8
        elif content_seen == 0 and pos == "NUM":
            kind = "initial"
            strength = 1.25

        if kind is not None:
            anchors.append((i, kind, strength, wi))
            if kind in ("determiner", "boundary", "conjunction", "terminal"):
                structural_count += 1
        if not word.is_punct and not word.is_space:
            content_seen += 1

    # Narrow exception: an initial possessive NP followed by a copular AUX.
    # Ordinary determiner-led, pronoun-led, and narrative inputs are unchanged.
    possessive_start = None
    reset_boundaries = []
    if first_piece:
        initial_wi = min(first_piece, key=first_piece.get)
        initial_word = doc[initial_wi]
        if initial_word.dep_ == "poss":
            auxiliary = next(
                (
                    w for w in doc
                    if w.i > initial_wi
                    and w.i in first_piece
                    and w.pos_ == "AUX"
                    and (
                        w.dep_ == "cop"
                        or (
                            w.dep_ == "ROOT"
                            and any(c.dep_ in ("acomp", "attr") for c in w.children)
                        )
                    )
                ),
                None,
            )
            if auxiliary is not None and not any(
                w.is_punct or w.pos_ in ("VERB", "CCONJ")
                for w in doc[initial_wi + 1:auxiliary.i]
            ):
                possessive_start = first_piece[initial_wi]
                reset_boundaries = [
                    j for j, kind, _, _ in anchors
                    if kind in ("boundary", "conjunction", "terminal")
                    and j > first_piece[auxiliary.i]
                ]
                anchors.append(
                    (first_piece[auxiliary.i], "auxiliary", 2.0, auxiliary.i)
                )
                anchored_words = {wi for _, _, _, wi in anchors}
                for word in doc:
                    if (
                        word.i > auxiliary.i
                        and word.i in first_piece
                        and word.i not in anchored_words
                        and word.pos_ == "PRON"
                        and word.dep_ != "poss"
                    ):
                        strength = (
                            1.2 if word.dep_ in ("nsubj", "nsubjpass") else 2.0
                        )
                        anchors.append(
                            (first_piece[word.i], "pronoun", strength, word.i)
                        )
                anchors.sort(key=lambda anchor: anchor[0])

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        positions = np.arange(i + 1)
        matrix[i, :i + 1] = 0.012 * np.exp(-(i - positions) / 18.0)
        matrix[i, 0] += 0.8 if i == 1 else 0.55
        matrix[i, i] += 0.15 + 0.4 * (1.0 - np.exp(-i / 15.0))

        wi = word_ids[i]
        query_word = doc[wi] if wi is not None else None
        for j, kind, strength, anchor_word in anchors:
            if j > i:
                break
            distance = i - j
            persistence = np.exp(-distance / 35.0) * (
                0.38 + 0.62 * np.exp(-distance / 7.0)
            )
            if kind == "pronoun":
                persistence = np.exp(-distance / 22.0) * (
                    0.65 + 0.35 * np.exp(-distance / 5.0)
                )
                if any(
                    j < k <= i and category in
                    ("determiner", "boundary", "conjunction", "terminal")
                    for k, category, _, _ in anchors
                ):
                    persistence *= 0.60
            elif kind == "initial":
                persistence *= np.exp(-distance / 3.0)

            weight = strength * persistence
            if kind == "determiner" and query_word is not None:
                anchor = doc[anchor_word]
                if (
                    query_word.i == anchor.head.i
                    or query_word.head.i == anchor.head.i
                ):
                    weight *= 1.08

            # Adjust only anchor contributions in the detected construction;
            # the original baseline, self weights, and decays remain intact.
            if possessive_start is not None:
                if j == possessive_start:
                    weight *= 0.32
                if any(j < boundary <= i for boundary in reset_boundaries):
                    weight *= 0.35

            matrix[i, j] += weight

        if wi is not None and first_piece.get(wi, i) < i:
            matrix[i, i] *= 0.5

        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        if tokens[i] not in special and not clean.strip():
            matrix[i, i] += 0.8
            previous = tokens[i - 1].replace("▁", "").replace("Ġ", "")
            if any(mark in previous for mark in (".", "!", "?")):
                matrix[i, i - 1] += 1.0

    return (
        "possessive_copular_segment_anchors",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L2H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict persistent phrase-onset anchors; nominal determiners after
    predicates or prepositions open phrases rather than strongly retrieving licensors."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "phrase_onset_and_local_introducers", matrix

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    first = {}
    last = {}
    for k, indices in enumerate(inverse):
        if indices:
            first[k] = min(indices)
            last[k] = max(indices)

    specials = set(tokenizer.all_special_tokens)
    anchor = 0
    anchor_kind = "start"
    first_comma = None
    latest_comma = None
    secondary_det = None
    seen = set()

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        sids = forward[i] if i < len(forward) else []
        sid = max(sids, key=lambda k: len(doc[k].text)) if sids else None
        word = doc[sid] if sid is not None else None
        new_word = sid is not None and sid not in seen

        # Commas and nominal determiners act as persistent key-side anchors.
        if new_word:
            seen.add(sid)
            if word.text == ",":
                if first_comma is None:
                    first_comma = i
                latest_comma = i
                anchor = i
                anchor_kind = "comma"
                secondary_det = None
            elif word.pos_ == "DET":
                if anchor_kind == "comma":
                    secondary_det = i
                else:
                    anchor = i
                    anchor_kind = "determiner"
                    secondary_det = None

        row = np.zeros(n, dtype=np.float64)
        row[anchor] += 0.72
        row[0] += 0.08
        row[i] += 0.07
        row[i - 1] += 0.06
        if first_comma is not None and first_comma <= i:
            row[first_comma] += 0.13
        if secondary_det is not None:
            row[secondary_det] += 0.16
        row[:i + 1] += 0.035 / (i + 1)
        row /= row.sum()

        target = None
        strength = 0.0

        if word is not None:
            previous = doc[sid - 1] if sid > 0 else None

            # Nouns and their modifiers share the determiner at the NP onset.
            noun = word
            if word.dep_ in ("amod", "compound", "nummod"):
                noun = word.head
            determiners = [
                c for c in noun.children
                if c.dep_ in ("det", "poss") and c.i in first
                and first[c.i] <= i
            ]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM") and determiners:
                det = min(determiners, key=lambda c: c.i)
                target = first[det.i]
                strength = 0.79 if anchor_kind != "comma" else 0.31
                if det.dep_ == "poss":
                    strength *= 0.65

            if word.pos_ == "DET":
                target = first.get(sid, i)
                strength = 0.60 if anchor_kind != "comma" else 0.16

            # Infinitival markers strongly retrieve the preceding licensor,
            # not the following infinitive to which a parser attaches them.
            if word.tag_ == "TO" or (
                word.pos_ == "PART" and word.dep_ in ("aux", "mark")
            ):
                candidates = [
                    k for k in range(max(0, sid - 9), sid)
                    if doc[k].pos_ in ("VERB", "AUX", "ADJ", "NOUN")
                    and k in last
                    and (latest_comma is None or last[k] > latest_comma)
                ]
                if candidates:
                    verbs = [k for k in candidates if doc[k].pos_ == "VERB"]
                    k = verbs[-1] if verbs else candidates[-1]
                    target = last[k]
                    strength = 0.95 if sid - k <= 2 else 0.87

            # Objects and subjects immediately following an introducer often
            # attend almost exclusively to that introducer.
            if word.pos_ in ("PRON", "DET") and previous is not None:
                if previous.pos_ in ("ADP", "SCONJ", "VERB", "AUX", "CCONJ"):
                    if previous.i in last:
                        target = last[previous.i]
                        strength = 0.82
                        if previous.pos_ == "CCONJ":
                            strength = 0.66
                elif previous.pos_ == "ADV" and word.dep_ in (
                    "nsubj", "nsubjpass", "nsubj:pass"
                ):
                    if previous.i in last:
                        target = last[previous.i]
                        strength = 0.56

            # Copulas/auxiliaries in embedded clauses share the reporting or
            # cognition predicate that licensed the preceding subject.
            if word.pos_ == "AUX":
                governing = word.head
                if governing.i >= sid and governing.head.i < sid:
                    governing = governing.head
                if governing.i < sid and governing.pos_ == "VERB":
                    if governing.i in last:
                        target = last[governing.i]
                        strength = 0.86

            if word.pos_ == "ADP":
                governing = word.head
                if governing.pos_ == "VERB" and governing.i in last:
                    if last[governing.i] < i:
                        target = last[governing.i]
                        strength = 0.76 if word.tag_ == "TO" else 0.57

            if word.pos_ == "VERB" and previous is not None:
                if previous.pos_ == "CCONJ" and previous.i in last:
                    target = last[previous.i]
                    strength = 0.66
                auxiliaries = [
                    c for c in word.children
                    if c.pos_ == "AUX" and c.i in last and last[c.i] < i
                ]
                if auxiliaries and word.tag_ == "VB":
                    auxiliary = max(auxiliaries, key=lambda c: c.i)
                    target = last[auxiliary.i]
                    strength = max(strength, 0.55)

            if word.pos_ in ("CCONJ", "SCONJ"):
                if previous is not None and previous.text == ",":
                    target = last.get(previous.i)
                    strength = 0.61

            # Exception: a nominal determiner is itself a phrase onset, not
            # a pronominal argument retrieving the preceding introducer.
            # Preserve possessives, conjunction routing, and all other rows.
            if (
                word.pos_ == "DET"
                and word.dep_ == "det"
                and previous is not None
                and previous.pos_ in ("ADP", "VERB", "AUX")
                and previous.i in last
                and last[previous.i] < i
            ):
                if anchor_kind == "comma":
                    target = first.get(sid, i)
                    strength = 0.34
                else:
                    # The default row already strongly anchors this onset.
                    target = last[previous.i]
                    strength = 0.18

            if target is not None and target <= i:
                row *= 1.0 - strength
                row[target] += strength

            # Clause/coordination introducers become anchors only after their
            # own query has been evaluated.
            if new_word and word.pos_ in ("CCONJ", "SCONJ"):
                anchor = first.get(sid, i)
                anchor_kind = "clause"
                secondary_det = None

        if tokens[i] in specials:
            row[:] = 0.0
            row[0] = 1.0

        matrix[i] = row

    return (
        "phrase_onset_and_local_introducers",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L3H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak leakage; dialogue delimiters also retrieve earlier
    matching delimiters, without changing the default self-attention weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_delimiter_retrieval", attention

    attention[0, 0] = 1.0
    special_tokens = set(tokenizer.all_special_tokens)

    clean = [t.lstrip("▁Ġ").strip() for t in tokens]
    quote_marks = '"“”'
    dialogue = any(
        t not in special_tokens
        and bool(s)
        and all(not c.isalnum() for c in s)
        and any(c in quote_marks for c in s)
        for t, s in zip(tokens, clean)
    )

    for i in range(1, n):
        text = tokens[i].lstrip("▁Ġ").strip()
        is_punctuation = (
            bool(text)
            and tokens[i] not in special_tokens
            and all(not c.isalnum() and not c.isspace() for c in text)
        )

        # Small per-key background naturally makes the sink slightly weaker
        # as the available causal context grows.
        distances = i - np.arange(1, i + 1)
        leakage = 0.0003 + 0.0007 * np.exp(-distances / 3.0)
        if is_punctuation:
            leakage *= 7.0

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = leakage

        # Transfer only BOS mass to strictly earlier dialogue delimiters.
        # Keeping the row total fixed preserves every other weight exactly.
        if dialogue and tokens[i] not in special_tokens:
            keys = []
            mass = 0.0

            if text == ",":
                keys = [j for j in range(1, i) if clean[j] == ","]
                mass = min(0.30, 0.075 * len(keys))
                if keys and i - keys[-1] <= 3:
                    mass *= 0.65
            elif text and all(c in quote_marks for c in text):
                keys = [
                    j for j in range(1, i)
                    if clean[j] and all(c in quote_marks for c in clean[j])
                ]
                mass = 0.38
            elif is_punctuation and any(c in quote_marks for c in text):
                keys = [
                    j for j in range(1, i)
                    if any(c in quote_marks for c in clean[j])
                    and any(c in ".?!" for c in clean[j])
                ]
                mass = 0.12
                if not keys:
                    keys = [
                        j for j in range(1, i)
                        if clean[j] and all(c in quote_marks for c in clean[j])
                    ]
                    mass = 0.04
            elif not text:
                keys = [
                    j for j in range(1, i)
                    if not clean[j] and tokens[j] not in special_tokens
                ]
                mass = 0.56

            if keys:
                weights = np.exp(-0.035 * (np.asarray(keys) - keys[0]))
                transfer = min(mass * attention[i].sum(), attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, keys] += transfer * weights / weights.sum()

    return "bos_sink_with_dialogue_delimiter_retrieval", make_row_stochastic(attention)


def prog_L3H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, except quotation boundaries attend to their matching
    opening quote and, more weakly, the preceding quotation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_quote_matching", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = 0.98
        attention[i, 1:i + 1] = 0.02 * residual

    opening = None
    previous_opening = None
    previous_closing = None

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        quote_count = sum(text.count(q) for q in ('"', '“', '”'))

        if quote_count == 1:
            if opening is None:
                # Later opening quotes recall the preceding quotation.
                if previous_closing is not None:
                    attention[i, 0] -= 0.085
                    attention[i, previous_closing] += 0.055
                    attention[i, previous_opening] += 0.030
                opening = i
            else:
                # Transfer sink mass without changing the diagonal or decay.
                attention[i, 0] -= 0.56
                attention[i, opening] += 0.56

                if previous_opening is not None:
                    attention[i, 0] -= 0.04
                    attention[i, previous_opening] += 0.04

                previous_opening = opening
                previous_closing = i
                opening = None

        elif previous_closing == i - 1:
            # The token immediately after a closing quote weakly recalls it.
            attention[i, 0] -= 0.04
            attention[i, previous_opening] += 0.04

    return "first_token_sink_with_quote_matching", attention


def prog_L3H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a targeted exception: coordinating conjunctions attend
    strongly to an immediately preceding adjective or noun.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.97
            attention[i, 1:i + 1] = 0.03 / i

        doc = spacy_parse(sentence)
        aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)
        for word in doc:
            if word.pos_ != "CCONJ" or word.dep_ != "cc" or word.i == 0:
                continue
            previous = doc[word.i - 1]
            if previous.pos_ not in ("ADJ", "NOUN", "PROPN"):
                continue
            if not aligned[word.i] or not aligned[previous.i]:
                continue

            i = min(aligned[word.i])
            j = max(aligned[previous.i])
            if not 0 < j < i < n:
                continue

            target = 0.475 if previous.pos_ == "ADJ" else 0.276
            delta = target - attention[i, j]
            attention[i, 0] -= delta
            attention[i, j] += delta

    return "bos_sink_with_coordination_exception", attention


def prog_L3H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant first-token attention sink with weak, diffuse causal attention.
    Sink strength decreases slightly as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.95 + 0.04 * np.exp(-i / 35.0)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 16.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L3H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal background attention.
    Fragmented non-ASCII punctuation creates a small local attention cluster.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = 0.0004
        attention[i, i] += 0.0096

    # Activate only for adjacent non-ASCII fragments containing a symbol.
    clean = [t.lstrip("▁Ġ") for t in tokens]
    fragments = [
        bool(t) and all(ord(c) > 127 for c in t)
        for t in clean
    ]
    symbols = [
        bool(t) and any(not c.isalnum() for c in t)
        for t in clean
    ]
    clustered = [False] * n
    for i in range(2, n):
        if (fragments[i - 1] and fragments[i]
                and (symbols[i - 1] or symbols[i])):
            clustered[i - 1] = True
            clustered[i] = True

    if any(clustered):
        for i in range(1, n):
            if clustered[i]:
                # Immediate fragments bind together more strongly than
                # ordinary words; earlier clusters attract repeated fragments.
                if clustered[i - 1]:
                    attention[i, i - 1] += 0.05
                    if i > 2 and clustered[i - 2]:
                        attention[i, i - 1] += 0.06
                        attention[i, i - 2] += 0.095
                        if i > 3 and clean[i - 3] and all(
                            not c.isalnum() for c in clean[i - 3]
                        ):
                            attention[i, i - 3] += 0.02
                else:
                    for j in range(1, i):
                        if clustered[j]:
                            start = not clustered[j - 1]
                            attention[i, j] += 0.08 if start else 0.04
            elif clustered[i - 1]:
                # The first text token after a fragmented delimiter still
                # attends to that delimiter, especially without a word boundary.
                weight = 0.014 if tokens[i].startswith(("▁", "Ġ")) else 0.035
                j = i - 1
                while j > 0 and clustered[j]:
                    attention[i, j] += weight
                    j -= 1

    return "bos_attention_sink", make_row_stochastic(attention)


def prog_L3H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token.
    Approximate the unobserved residual with a weak causal recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = np.exp(-0.15 * (i - positions))
        attention[i, 1:i + 1] = 0.03 * residual / residual.sum()
        attention[i, 0] = 0.97

    return "bos_attention_sink", attention


def prog_L3H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse possessive and prepositional-complement exceptions.
    Transfer mass only from BOS, preserving the original residual and diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.98
            attention[i, 1:i + 1] = 0.02 / i

    if n > 1:
        doc = spacy_parse(sentence)
        aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)

        for word in doc:
            query_ids = [i for i in aligned[word.i] if 0 < i < n]
            if not query_ids:
                continue

            # A possessive clitic redirects attention to its nominal owner.
            if word.tag_ == "POS" and word.dep_ == "case":
                owner_ids = [
                    j for j in aligned[word.head.i]
                    if 0 < j < min(query_ids)
                ]
                if not owner_ids:
                    continue

                owner = max(owner_ids)
                apostrophes = [
                    j for j in query_ids
                    if tokens[j].lstrip("▁Ġ") in ("'", "’")
                ]
                for i in query_ids:
                    additions = {}
                    if apostrophes and i > min(apostrophes):
                        apostrophe = min(apostrophes)
                        if len(owner_ids) > 1:
                            additions[apostrophe] = 0.56
                            additions[owner] = 0.18
                        else:
                            additions[owner] = 0.46
                            additions[apostrophe] = 0.03
                    else:
                        additions[owner] = (
                            0.16 if len(owner_ids) > 1 else 0.05
                        )

                    for j, mass in additions.items():
                        attention[i, 0] -= mass
                        attention[i, j] += mass

            # Determiners after nominal prepositions can retrieve the
            # preceding nominal head rather than remaining a pure BOS sink.
            elif word.pos_ == "DET" and word.i > 0:
                prep = doc[word.i - 1]
                anchor = prep.head
                if (
                    prep.pos_ != "ADP"
                    or prep.dep_ != "prep"
                    or anchor.pos_ not in ("NOUN", "PROPN", "PRON")
                ):
                    continue

                i = min(query_ids)
                anchor_ids = [
                    j for j in aligned[anchor.i] if 0 < j < i
                ]
                prep_ids = [j for j in aligned[prep.i] if 0 < j < i]
                if not anchor_ids:
                    continue

                additions = {
                    max(anchor_ids): (
                        0.66 if anchor.pos_ in ("NOUN", "PROPN") else 0.265
                    )
                }
                if prep_ids:
                    additions[max(prep_ids)] = 0.04

                for child in anchor.children:
                    if child.dep_ == "det":
                        modifier_ids = [
                            j for j in aligned[child.i] if 0 < j < i
                        ]
                        if modifier_ids:
                            j = max(modifier_ids)
                            additions[j] = additions.get(j, 0.0) + 0.06

                for j, mass in additions.items():
                    attention[i, 0] -= mass
                    attention[i, j] += mass

    return "bos_sink_with_possessive_and_nominal_exceptions", attention


def prog_L3H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a punctuation-triggered exception for earlier quotation marks.
    Transfer only BOS mass, preserving the original residual and self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.98
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 16.0)
        attention[i, 1:i + 1] = 0.02 * residual / residual.sum()

    clean = [t.lstrip("▁Ġ") for t in tokens]
    anchors = [
        j for j in range(1, n)
        if clean[j] in ('"', "“", "„", "«")
    ]

    # Recognize the first mojibake opening quotation mark as a token cluster.
    corrupted = "\u00e2\u20ac" in sentence
    encoded_punctuation = ("\u00e2", "\u20ac", "\u0153")
    if corrupted:
        for j in range(1, n):
            if clean[j] == encoded_punctuation[0]:
                anchors.extend(
                    k for k in range(j, min(j + 3, n))
                    if clean[k] in encoded_punctuation
                )
                break

    if anchors:
        for i in range(1, n):
            targets = [j for j in anchors if j < i]
            if not targets:
                continue

            text = clean[i]
            transfer = 0.0
            if corrupted and text in encoded_punctuation:
                transfer = 0.32 if text == encoded_punctuation[0] else 0.14
            elif text and all(c in ".,!?;:\"'“”‘’«»„" for c in text):
                if "." in text:
                    transfer = min(0.24, 0.18 + 0.02 * len(targets))
                elif text in ("'", "’"):
                    transfer = 0.16
                elif "," in text or '"' in text or "“" in text:
                    transfer = 0.13
                else:
                    transfer = 0.10

            if transfer:
                weights = 1.0 + np.asarray(targets, dtype=np.float64) / i
                attention[i, targets] += transfer * weights / weights.sum()
                attention[i, 0] -= transfer

    return "bos_sink_quote_exception", attention


def prog_L3H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a first-token sink with a local noun-phrase exception.
    Phrase-internal modifiers draw extra mass from the sink, not self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Locate word starts so the exception does not fire on continuation pieces.
    word_tokens = [[] for _ in doc]
    for ti, aligned_words in enumerate(alignment):
        for k in aligned_words:
            word_tokens[k].append(ti)

    for i in range(1, n):
        aligned = alignment[i]
        sink = 0.93

        if aligned:
            # Average features when a model token overlaps multiple spaCy tokens.
            estimates = []
            for k in aligned:
                word = doc[k]
                pos = word.pos_
                if pos in ("DET", "AUX", "PART", "SCONJ"):
                    value = 0.953
                elif pos in ("PRON", "ADP", "CCONJ"):
                    value = 0.944
                elif pos == "VERB":
                    value = 0.944
                elif pos == "ADV":
                    value = 0.938
                elif pos == "PUNCT":
                    value = 0.937
                elif pos == "ADJ":
                    value = 0.900
                elif pos in ("NOUN", "PROPN", "NUM"):
                    value = 0.858
                else:
                    value = 0.925
                estimates.append(value)
            sink = float(np.mean(estimates))

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.97
        elif tokens[i].isspace() or tokens[i] == "▁":
            sink = 0.935

        # The first ordinary token has an especially strong sink preference.
        if i == 1:
            sink = 0.985

        # A modest length effect allows more competing attention in long contexts.
        sink -= 0.015 * (1.0 - np.exp(-max(i - 20, 0) / 50.0))
        sink = float(np.clip(sink, 0.78, 0.995))

        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Exception: a noun phrase retrieves its preceding determiner,
        # possessor, adjectives, and governing preposition.
        if i > 1 and len(aligned) == 1:
            k = aligned[0]
            word = doc[k]
            if (
                word_tokens[k][0] == i
                and word.pos_ in ("NOUN", "ADJ")
                and (word.pos_ == "NOUN" or word.dep_ == "amod")
            ):
                nominal = word if word.pos_ == "NOUN" else word.head
                if nominal.dep_ == "compound" and nominal.head.pos_ == "NOUN":
                    nominal = nominal.head

                targets = {}
                for child in nominal.children:
                    if child.i >= word.i or word.i - child.i > 6:
                        continue
                    if child.dep_ == "det":
                        mass = 0.18 if word.pos_ == "NOUN" else 0.09
                    elif child.dep_ == "poss":
                        mass = 0.25 if word.pos_ == "NOUN" else 0.09
                    elif child.dep_ == "amod":
                        mass = 0.055 if word.pos_ == "NOUN" else 0.045
                    else:
                        continue
                    targets[child.i] = mass

                if (
                    word.pos_ == "NOUN"
                    and nominal.head.pos_ == "ADP"
                    and 0 < word.i - nominal.head.i <= 6
                ):
                    targets[nominal.head.i] = 0.15

                additions = []
                for wk, mass in targets.items():
                    previous = [j for j in word_tokens[wk] if 0 < j < i]
                    if previous:
                        additions.append((previous[-1], mass))

                total = sum(mass for _, mass in additions)
                if total > 0:
                    scale = min(1.0, max(attention[i, 0] - 0.35, 0.0) / total)
                    for j, mass in additions:
                        delta = scale * mass
                        attention[i, j] += delta
                        attention[i, 0] -= delta

    return "first_token_sink_np_exception", make_row_stochastic(attention)


def prog_L3H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position decay and punctuation/function-word boosts.
    The small remaining mass is distributed diffusely over the causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = words[0].pos_ if words else ""
        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        is_punct = (
            any(w.is_punct for w in words)
            or (bool(clean) and all(not c.isalnum() for c in clean))
        )

        sink = (
            0.84
            + 0.12 * np.exp(-i / 8.0)
            - 0.012 * np.log1p(i / 24.0)
        )
        if pos in ("NOUN", "PROPN"):
            sink -= 0.05
        elif pos in ("VERB", "ADJ"):
            sink -= 0.015
        elif pos in ("DET", "ADP", "AUX", "CCONJ", "SCONJ"):
            sink += 0.015

        if is_punct:
            sink += 0.06
        elif not clean.strip():
            sink += 0.04

        if i == 1:
            sink = 0.965
            if pos in ("PRON", "DET", "ADP", "CCONJ"):
                sink += 0.008

        sink = float(np.clip(sink, 0.72, 0.98))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = (distances + 1.0) ** -0.45
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L3H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink, with weak POS-dependent variation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_attention_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.90
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "PROPN":
                sink_mass = 0.95
            elif word.pos_ in ("NOUN", "ADJ"):
                sink_mass = 0.93
            elif word.pos_ in ("PRON", "DET", "NUM"):
                sink_mass = 0.92
            elif word.pos_ in ("VERB", "AUX", "ADP", "ADV"):
                sink_mass = 0.87
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                sink_mass = 0.86
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass = 0.84

        if i == 1:
            sink_mass = 0.98

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_attention_sink", attention


def prog_L3H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak causal background.
    Most attention goes to the first token, largely independently of syntax.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Slightly weaker sink during the initial positional warm-up.
        sink_mass = 0.90 - 0.10 * np.exp(-(i - 1) / 2.0)

        positions = np.arange(1, i + 1)
        background = (
            0.5 / i
            + 0.5 * np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_attention_sink", attention


def prog_L3H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a targeted intra-word continuation path.
    Split-word continuations move BOS mass to earlier pieces, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    word_pieces = [[] for _ in doc]
    for ti in range(1, n):
        if len(alignment[ti]) == 1:
            word_pieces[alignment[ti][0]].append(ti)

    for i in range(1, n):
        sink_mass = 0.954 - 0.0006 * min(i, 70)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("PRON", "DET"):
                sink_mass += 0.012
            elif word.pos_ in ("AUX", "VERB", "ADP"):
                sink_mass += 0.005
            elif word.pos_ in ("PUNCT", "SYM", "X"):
                sink_mass -= 0.015

        sink_mass = float(np.clip(sink_mass, 0.89, 0.978))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only continuation pieces of an alphabetic word use this path.
        # Transfer mass from BOS without altering self or unrelated edges.
        if len(alignment[i]) == 1:
            wi = alignment[i][0]
            pieces = word_pieces[wi]
            previous = [j for j in pieces if j < i]
            if doc[wi].is_alpha and previous and previous[-1] == i - 1:
                depth = len(previous)
                extra_mass = min(
                    0.42,
                    0.065 + 0.09 * (depth - 1)
                    + 0.065 * max(0, len(pieces) - 2),
                )
                weights = np.exp(
                    -0.5 * (np.arange(depth, dtype=np.float64) - 0.5) ** 2
                )
                weights /= weights.sum()
                attention[i, 0] -= extra_mass
                attention[i, previous] += extra_mass * weights

    return "bos_sink", attention


def prog_L3H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for early tokens and nominal content.
    Remaining attention is weak and broadly distributed with a recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.835 + 0.105 * np.exp(-(i - 1) / 4.0)
        sink -= 0.025 * (1.0 - np.exp(-i / 50.0))

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink += 0.095
            elif word.pos_ == "ADJ":
                sink += 0.045
            elif word.pos_ == "AUX":
                sink -= 0.035
            elif word.pos_ == "VERB":
                sink += 0.005

            if word.ent_type_:
                sink += 0.015

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink += 0.012

            if i > 1 and alignment[i - 1]:
                if alignment[i][0] == alignment[i - 1][0]:
                    sink += 0.015

        if i == 1:
            sink = 0.994

        sink = float(np.clip(sink, 0.65, 0.985 if i > 1 else 0.998))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = 0.6 + np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_lexical_modulation", attention


def prog_L3H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, strongest for nouns and punctuation.
    Linguistic query features modulate a small, diffuse causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.947,
        "PROPN": 0.963,
        "PUNCT": 0.918,
        "SYM": 0.945,
        "NUM": 0.910,
        "VERB": 0.835,
        "AUX": 0.845,
        "ADJ": 0.825,
        "ADV": 0.815,
        "CCONJ": 0.885,
        "SCONJ": 0.775,
        "DET": 0.795,
        "PRON": 0.785,
        "ADP": 0.735,
        "PART": 0.775,
        "INTJ": 0.910,
        "SPACE": 0.910,
        "X": 0.910,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            sink = 0.0
            for k in aligned:
                word = doc[k]
                value = sink_by_pos.get(word.pos_, 0.85)
                if word.ent_type_ and word.pos_ not in ("NOUN", "PROPN"):
                    value = max(value, 0.925)
                if word.dep_ == "poss":
                    value -= 0.025
                sink += value
            sink /= len(aligned)

            # Subword continuations tend to preserve strong noun/symbol sinks.
            if i > 1 and any(k in alignment[i - 1] for k in aligned):
                sink += 0.01
        else:
            surface = tokens[i].replace("▁", "").replace("Ġ", "")
            if not surface.strip():
                sink = 0.91
            elif all(not c.isalnum() for c in surface):
                sink = 0.925
            else:
                sink = 0.87

        if i == 1:
            sink = 0.98

        sink = float(np.clip(sink, 0.65, 0.985))
        attention[i, 0] = sink

        # No consistent non-BOS target is evidenced: use a broad causal tail
        # with only a modest preference for nearby positions.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.7 / i + 0.3 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * remainder

    return "bos_sink_pos_modulated", attention


def prog_L3H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with diffuse residual; opening quotation marks briefly act as
    secondary sinks, drawing mass from BOS without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_onset", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    active_quote = None

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = {word.pos_ for word in words}
        text = tokens[i].replace("▁", "").replace("Ġ", "").strip()

        sink_mass = 0.79
        if pos & {"ADP", "SCONJ"}:
            sink_mass += 0.055
        elif pos & {"AUX", "CCONJ"}:
            sink_mass += 0.025
        elif pos & {"ADJ", "VERB"}:
            sink_mass -= 0.025
        elif pos & {"PRON", "DET"}:
            sink_mass -= 0.015

        is_punctuation = (
            bool(text) and all(not c.isalnum() and not c.isspace() for c in text)
        )
        if is_punctuation or "PUNCT" in pos:
            sink_mass += 0.055
        if i == 1:
            sink_mass = 0.95

        sink_mass = float(np.clip(sink_mass, 0.68, 0.98))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-distances / 5.0)
        recent /= recent.sum()
        residual = 0.5 * recent + 0.5 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only quotation onsets override the original BOS allocation.
        if text in {'"', "“", "„", "«"}:
            if text == '"' and active_quote is not None:
                active_quote = None
            else:
                active_quote = i
        elif any(mark in text for mark in ('"', "”", "»")):
            active_quote = None
        elif active_quote is not None:
            distance = i - active_quote
            if 1 <= distance <= 4:
                transfer = (0.25, 0.14, 0.10, 0.06)[distance - 1]
                if distance == 1 and "AUX" in pos:
                    transfer += 0.10
                attention[i, 0] -= transfer
                attention[i, active_quote] += transfer

    return "bos_sink_with_quote_onset", make_row_stochastic(attention)


def prog_L3H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with clause-boundary leakage in internally punctuated discourse.
    Preserve baseline self-attention; move only BOS mass to earlier context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.98
            attention[i, 1:i + 1] = 0.02 / i

    # Exclude introductory commas: leave simple, unbroken clauses unchanged.
    internal_commas = [
        i for i, token in enumerate(tokens)
        if i > 3 and "," in token
    ]
    if internal_commas:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        boundary_positions = []

        for i in range(1, n):
            words = [doc[k] for k in alignment[i]]
            punctuation = any(w.is_punct for w in words)
            pos = words[0].pos_ if words else ""
            previous_commas = [j for j in internal_commas if j < i]
            distance = i - previous_commas[-1] if previous_commas else n
            extra = 0.0

            if i in internal_commas:
                extra = min(0.25, 0.065 + 0.003 * i)
            elif punctuation and previous_commas:
                extra = min(0.25, 0.045 + 0.003 * i)
            elif distance <= 2 and pos in (
                "ADJ", "ADV", "PRON", "SCONJ", "CCONJ", "ADP"
            ):
                extra = min(0.17, 0.045 + 0.002 * i)
            elif previous_commas and n > 30 and pos == "CCONJ":
                extra = min(0.25, 0.025 + 0.004 * i)
            elif previous_commas and pos == "ADP":
                extra = 0.025

            if extra > 0.0 and i > 1:
                # Add only to strictly earlier non-BOS positions, keeping
                # the original diagonal and all unaffected rows intact.
                weights = np.full(i - 1, 0.25, dtype=np.float64)
                weights[0] += 3.0
                weights[-1] += 0.8
                for j in boundary_positions:
                    if 1 <= j < i:
                        weights[j - 1] += 1.5

                attention[i, 0] -= extra
                attention[i, 1:i] += extra * weights / weights.sum()

            if punctuation:
                boundary_positions.append(i)

    return "bos_sink_with_clause_boundary_leakage", attention


def prog_L3H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a short-lived residual attraction to recent nominal anchors.
    Transfer only BOS mass, preserving the original diagonal and diffuse decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct or word.is_space:
                sink_mass = 0.84
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM"):
                sink_mass = 0.945
            elif word.pos_ in ("VERB", "ADV"):
                sink_mass = 0.925
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass = 0.87
            else:
                sink_mass = 0.915
        elif tokens[i].isspace():
            sink_mass = 0.84
        else:
            sink_mass = 0.92

        if i == 1:
            sink_mass = 0.975

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-distances / 8.0)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # A recent nominal (or predicative adjective) attracts the next
        # few words, especially predicates and phrase-boundary tokens.
        if aligned and i > 1:
            current = aligned[0]
            for k in range(current - 1, max(-1, current - 4), -1):
                anchor = doc[k]
                nominal = anchor.pos_ in ("NOUN", "PROPN")
                predicative = (
                    anchor.pos_ == "ADJ"
                    and anchor.dep_ in ("acomp", "attr", "ROOT")
                )
                if nominal or predicative:
                    targets = [
                        j for j in range(1, i)
                        if k in alignment[j]
                    ]
                    if targets:
                        gap = current - k
                        if word.pos_ in ("AUX", "VERB", "ADP"):
                            strength = 0.18
                            if anchor.dep_ in ("nsubj", "nsubjpass"):
                                strength += 0.045
                        elif word.is_punct or word.pos_ == "CCONJ":
                            strength = 0.13
                        elif word.pos_ in ("DET", "PRON", "SCONJ"):
                            strength = 0.10
                        else:
                            strength = 0.055

                        if predicative:
                            strength *= 0.65
                        transfer = strength * (0.55 ** (gap - 1))
                        weights = np.arange(
                            1, len(targets) + 1, dtype=np.float64
                        )
                        attention[i, 0] -= transfer
                        attention[i, targets] += (
                            transfer * weights / weights.sum()
                        )
                    break

                # Do not carry an anchor through a new lexical predicate
                # or a sentence boundary.
                if anchor.pos_ == "VERB" or (
                    anchor.is_punct and anchor.text != ","
                ):
                    break

    return "bos_sink_recent_nominal", attention


def prog_L3H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal recency leakage.
    Linguistic features mildly modulate the otherwise dominant first-token mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Nearly all observed attention goes to BOS, across lexical classes.
        sink_mass = 0.978 - 0.00045 * i
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM"):
                sink_mass += 0.006
            elif word.pos_ in ("VERB", "AUX", "PRON"):
                sink_mass -= 0.012
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass -= 0.035

        if i == 1:
            sink_mass = 0.986
        sink_mass = float(np.clip(sink_mass, 0.88, 0.992))

        # The examples do not identify residual targets reliably; use a
        # conservative mixture of diffuse causal attention and local recency.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L3H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest on phrase content and weaker on punctuation.
    Residual attention follows a small causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.95
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink = 0.79
            elif word.pos_ in ("NOUN", "ADJ", "NUM"):
                sink = 0.975
            elif word.pos_ in ("VERB", "AUX"):
                sink = 0.955
            elif word.pos_ in ("DET", "ADP", "PART"):
                sink = 0.96
            elif word.pos_ in ("PRON", "PROPN", "ADV"):
                sink = 0.935
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink = 0.91

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink -= 0.035
            elif word.dep_ in ("obj", "dobj", "pobj"):
                sink += 0.01
            elif word.dep_ == "ROOT":
                sink -= 0.045

            if word.is_sent_start:
                sink -= 0.065

        # Early tokens have less sharply separated sink attention.
        sink -= 0.055 * np.exp(-(i - 1) / 3.0)
        sink = float(np.clip(sink, 0.70, 0.99))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L3H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for content tokens and first-token queries.
    Residual attention is diffuse and mildly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_content_modulated", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "NOUN": 0.955,
        "PROPN": 0.955,
        "VERB": 0.905,
        "ADJ": 0.920,
        "ADV": 0.855,
        "ADP": 0.905,
        "AUX": 0.850,
        "PRON": 0.825,
        "DET": 0.855,
        "CCONJ": 0.780,
        "SCONJ": 0.810,
        "PART": 0.860,
        "NUM": 0.910,
        "PUNCT": 0.745,
        "SPACE": 0.800,
    }

    for i in range(1, n):
        sink = 0.900
        if aligned[i]:
            sink = np.mean([
                sink_by_pos.get(doc[k].pos_, 0.900)
                for k in aligned[i]
            ])

        if tokens[i].isspace():
            sink = 0.800
        if i == 1:
            sink = 0.986

        # Reserve the dominant mass for position zero; distribute the
        # remainder over causal non-sink positions, including self.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_content_modulated", attention


def prog_L3H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with an added clause-summary path at punctuation and coordination.
    Boundary queries shift BOS mass to prior clause features without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_summary", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "NOUN": 0.976,
        "PROPN": 0.980,
        "VERB": 0.951,
        "ADJ": 0.944,
        "ADV": 0.907,
        "AUX": 0.918,
        "PRON": 0.875,
        "DET": 0.892,
        "ADP": 0.884,
        "PART": 0.910,
        "NUM": 0.960,
        "CCONJ": 0.620,
        "SCONJ": 0.770,
        "INTJ": 0.920,
        "PUNCT": 0.560,
        "SPACE": 0.700,
        "SYM": 0.900,
        "X": 0.940,
    }

    for i in range(1, n):
        mapped = alignment[i]
        if mapped:
            word = doc[mapped[-1]]
            sink = sink_by_pos.get(word.pos_, 0.930)
            if word.ent_type_ and word.pos_ != "PUNCT":
                sink = max(sink, 0.970)
        else:
            clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
            if tokens[i] in tokenizer.all_special_tokens:
                sink = 0.970
            elif not clean:
                sink = 0.700
            elif all(not c.isalnum() for c in clean):
                sink = 0.560
            else:
                sink = 0.940

        # Early positions have especially strong sink attention.
        if i == 1:
            sink = max(sink, 0.980)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 2.5)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only boundary queries receive the additional clause-summary path.
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        previous = tokens[i - 1].replace("▁", " ").replace("Ġ", " ").strip()
        pos = doc[mapped[-1]].pos_ if mapped else ""
        punctuation_boundary = bool(clean) and all(
            not c.isalnum() for c in clean
        ) and any(c in ",;:.!?" for c in clean)
        discourse_boundary = (
            pos == "ADV"
            and any(c in ",;:" for c in previous)
        )
        if i > 2 and (
            punctuation_boundary or pos == "CCONJ" or discourse_boundary
        ):
            start = max(1, i - 24)
            for j in range(i - 2, start - 1, -1):
                boundary = tokens[j].replace("▁", " ").replace("Ġ", " ").strip()
                if any(c in ".!?" for c in boundary):
                    start = j + 1
                    break

            weights = np.zeros(i, dtype=np.float64)
            has_predicate = False
            for j in range(start, i):
                if not alignment[j]:
                    continue
                key = doc[alignment[j][-1]]
                if key.pos_ in ("VERB", "AUX"):
                    has_predicate = True
                if key.pos_ in ("PUNCT", "SPACE"):
                    continue

                salience = 1.0
                if key.pos_ in ("VERB", "AUX"):
                    salience = 3.0
                elif key.pos_ in ("ADJ", "ADV"):
                    salience = 2.5
                elif key.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    salience = 2.0
                weights[j] = salience * np.exp(-(j - start) / 14.0)

                # Avoid counting each subword as a separate linguistic feature.
                pieces = sum(
                    alignment[j][-1] in alignment[k]
                    for k in range(start, i)
                )
                weights[j] /= max(1, pieces)

            if has_predicate and weights.sum() > 0:
                transfer = (
                    0.36 if discourse_boundary
                    else 0.22 if pos == "CCONJ"
                    else 0.20 if "," in clean or ";" in clean
                    else 0.14
                )
                transfer = min(transfer, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, :i] += transfer * weights / weights.sum()

    return "bos_sink_with_clause_summary", attention


def prog_L3H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with POS modulation; clause-closing punctuation releases
    additional mass to preceding context while preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    sink_by_pos = {
        "NOUN": 0.981,
        "PROPN": 0.982,
        "ADJ": 0.974,
        "VERB": 0.963,
        "ADV": 0.953,
        "ADP": 0.960,
        "DET": 0.958,
        "NUM": 0.963,
        "PRON": 0.937,
        "AUX": 0.941,
        "PART": 0.946,
        "CCONJ": 0.909,
        "SCONJ": 0.919,
        "PUNCT": 0.862,
        "SPACE": 0.900,
    }

    attention[0, 0] = 1.0
    segment_start = 1
    for i in range(1, n):
        sink = 0.955
        if alignment[i]:
            sink = np.mean([
                sink_by_pos.get(doc[k].pos_, 0.955)
                for k in alignment[i]
            ])

        # Original leakage and self-attention remain unchanged.
        distances = i - np.arange(1, i + 1)
        leakage = 0.5 / i + 0.5 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * leakage

        # Read punctuation directly: malformed text can confuse spaCy's POS.
        surface = tokens[i].lstrip("▁Ġ").strip()
        terminal = (
            bool(surface)
            and any(c in ".!?" for c in surface)
            and all(c in ".!?\"'”’»" for c in surface)
        )
        clause_end = surface in (",", ";", ":")
        span_length = i - segment_start

        if i > 1 and (
            (terminal and span_length >= 2)
            or (clause_end and span_length >= 3)
        ):
            if terminal:
                target_sink = (
                    max(0.48, 0.66 - 0.003 * i)
                    if span_length >= 7 else 0.82
                )
                if "!" in surface or "?" in surface:
                    target_sink = min(target_sink, 0.56)
                if any(c in surface for c in "\"”’»"):
                    target_sink -= 0.05
            else:
                target_sink = 0.76 if span_length >= 6 else 0.80

            released = max(0.0, sink - target_sink)
            if released:
                # Transfer only BOS mass, never the original diagonal weight.
                context = np.full(i - 1, 0.25 / (i - 1))
                context[segment_start - 1:] += 0.75 / span_length
                attention[i, 0] -= released
                attention[i, 1:i] += released * context

        if terminal:
            segment_start = i + 1

    return "bos_sink_with_boundary_release", make_row_stochastic(attention)


def prog_L3H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, with stronger sink attraction for nominal tokens.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_nominal_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.91,
        "PROPN": 0.93,
        "VERB": 0.77,
        "AUX": 0.76,
        "ADJ": 0.79,
        "ADV": 0.76,
        "ADP": 0.80,
        "PART": 0.77,
        "PRON": 0.68,
        "DET": 0.71,
        "CCONJ": 0.80,
        "SCONJ": 0.74,
        "NUM": 0.83,
        "PUNCT": 0.78,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        sink = 0.78

        if aligned:
            values = []
            for k in aligned:
                word = doc[k]
                value = sink_by_pos.get(word.pos_, 0.78)
                if word.ent_type_:
                    value += 0.015
                values.append(value)
            sink = float(np.mean(values))

        # Offset mappings usually omit standalone whitespace pieces.
        if tokens[i].isspace() or tokens[i] == "▁":
            sink = 0.79

        sink = float(np.clip(sink, 0.60, 0.95))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 / np.sqrt(1.0 + i - positions)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

    return "bos_sink_nominal_modulation", attention


def prog_L3H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening dominance over position.
    Linguistic features modulate sink strength; residual attention is diffuse-causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_logit = 2.80 - 0.65 * np.log(float(i))

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("ADP", "SCONJ"):
                sink_logit += 0.35
            elif word.pos_ in ("DET", "PRON", "CCONJ", "PART"):
                sink_logit += 0.12
            elif word.pos_ == "VERB":
                sink_logit -= 0.35
            elif word.pos_ in ("ADJ", "ADV"):
                sink_logit -= 0.22
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_logit -= 0.10

            if word.is_punct:
                sink_logit -= 0.10
                if any(mark in word.text for mark in (".", "!", "?")):
                    sink_logit -= 0.50

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 8.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L3H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional and punctuation-boundary decay.
    Residual attention is diffuse and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    boundary_count = 0
    seen_punctuation = set()

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        is_punctuation = any(w.is_punct for w in aligned)
        is_space = bool(aligned) and all(w.is_space for w in aligned)

        sink_mass = (
            0.965
            - 0.105 * (1.0 - np.exp(-i / 24.0))
            - 0.027 * min(boundary_count, 7)
        )
        if is_punctuation:
            sink_mass -= 0.065
        if is_space:
            sink_mass -= 0.09
        if any(w.pos_ == "CCONJ" for w in aligned):
            sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.60, 0.98))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        for w in aligned:
            if w.is_punct and w.i not in seen_punctuation:
                seen_punctuation.add(w.i)
                boundary_count += 1

    return "bos_sink_with_boundary_decay", make_row_stochastic(attention)


def prog_L3H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and on nominal tokens.
    Remaining attention is weak, causal, and biased toward nearby tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    nominal = {"NOUN", "PROPN"}
    pos_mass = {
        "NOUN": 0.89,
        "PROPN": 0.91,
        "VERB": 0.74,
        "AUX": 0.69,
        "ADJ": 0.76,
        "ADV": 0.65,
        "DET": 0.77,
        "PRON": 0.73,
        "ADP": 0.80,
        "PART": 0.72,
        "CCONJ": 0.65,
        "SCONJ": 0.64,
        "NUM": 0.81,
        "PUNCT": 0.71,
        "SPACE": 0.83,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        base = 0.79
        if alignment[i]:
            word = doc[alignment[i][0]]
            base = pos_mass.get(word.pos_, base)
            if word.ent_type_ and word.pos_ in nominal:
                base += 0.015
        elif tokens[i].replace("▁", "").replace("Ġ", "").isspace():
            base = 0.83
        elif tokens[i] in tokenizer.all_special_tokens:
            base = 0.88

        # Early tokens have especially strong access to the attention sink.
        early = np.exp(-(i - 1) / 4.0)
        sink_mass = base + (0.972 - base) * early
        sink_mass = np.clip(sink_mass, 0.50, 0.99)
        attention[i, 0] = sink_mass

        distance = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distance / 5.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_lexical_modulation", attention


def prog_L3H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and POS-dependent strength.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[-1]].pos_ if aligned else ""

        # The first position remains the dominant destination throughout.
        sink = 0.965 - 0.0032 * i
        if pos in ("NOUN", "PROPN", "ADJ", "NUM"):
            sink += 0.025
        elif pos in ("VERB", "AUX"):
            sink -= 0.065
        elif pos in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
            sink -= 0.035
        elif pos in ("PUNCT", "SPACE"):
            sink -= 0.105

        if not tokens[i].strip("▁Ġ \t\r\n"):
            sink -= 0.09

        # With almost no competing context, the sink is nearly exclusive.
        if i == 1:
            sink = 0.985
        else:
            sink = float(np.clip(sink, 0.58, 0.985))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L3H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and punctuation/function-word corrections.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        # Most queries discard information into the initial attention sink.
        sink = 0.49 + 0.43 * np.exp(-(i - 1) / 5.0)

        if word is not None:
            if word.pos_ in ("CCONJ", "SCONJ", "ADP"):
                sink += 0.10
            elif word.pos_ in ("DET", "PRON", "AUX", "PART"):
                sink += 0.04
            elif word.pos_ in ("VERB", "ADJ"):
                sink -= 0.05

            # Subword continuations often have unusually strong sink attention.
            if i > 1 and aligned and alignment[i - 1]:
                if aligned[-1] in alignment[i - 1]:
                    sink += 0.12

        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        is_punctuation = (
            word is not None and word.pos_ == "PUNCT"
        ) or (
            bool(surface)
            and all(not c.isalnum() for c in surface)
            and tokens[i] not in tokenizer.all_special_tokens
        )
        if is_punctuation:
            sink = 0.74 + 0.19 * np.exp(-i / 4.0)
        elif not surface:
            sink = max(sink, 0.64)

        if i == 1:
            sink = 0.974

        sink = float(np.clip(sink, 0.20, 0.985))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.45 + np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_gating", attention


def prog_L3H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary-triggered, content-weighted attention to prior tokens.
    Boundary spillover preserves the original self-attention and local decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.960,
        "PROPN": 0.940,
        "ADJ": 0.960,
        "VERB": 0.935,
        "ADV": 0.930,
        "ADP": 0.945,
        "DET": 0.920,
        "NUM": 0.930,
        "PART": 0.905,
        "AUX": 0.885,
        "PRON": 0.875,
        "CCONJ": 0.885,
        "SCONJ": 0.905,
        "INTJ": 0.870,
        "PUNCT": 0.640,
        "SPACE": 0.700,
        "SYM": 0.720,
        "X": 0.890,
    }
    length_penalty = 0.035 * np.clip((n - 25) / 40.0, 0.0, 1.0)
    attention[0, 0] = 1.0

    history_weights = np.ones(n, dtype=np.float64)
    boundary_age = 3

    for i in range(1, n):
        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )
        aligned = [doc[k] for k in alignment[i] if k < len(doc)]
        if punctuation:
            sink = 0.640
        elif aligned:
            lexical = [w for w in aligned if not w.is_punct and not w.is_space]
            selected = lexical if lexical else aligned
            sink = sum(sink_by_pos.get(w.pos_, 0.920) for w in selected)
            sink /= len(selected)
        else:
            sink = 0.920

        sink = float(np.clip(sink - length_penalty, 0.50, 0.98))
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        local /= local.sum()
        residual = 0.65 * local + 0.35 / i

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Release only BOS mass: the original self-weight and decay stay intact.
        history_weights[i] = max(
            [
                {
                    "VERB": 2.0, "ADJ": 2.0, "ADV": 1.5,
                    "NOUN": 1.2, "PROPN": 1.2, "PUNCT": 0.15,
                    "SPACE": 0.15, "DET": 0.4, "PART": 0.4,
                }.get(w.pos_, 1.0)
                for w in aligned
            ] or [0.15 if punctuation or not clean else 1.0]
        )
        terminal = punctuation and any(c in ".!?" for c in clean)
        quote = punctuation and any(c in '"“”«»' for c in clean)
        release = 0.0
        if terminal:
            release = 0.28
            boundary_age = 0
        elif quote or not clean:
            release = 0.18 if quote else 0.35
        elif boundary_age < 3:
            release = (0.22, 0.14, 0.08)[boundary_age]
            boundary_age += 1

        if release > 0.0 and i > 1:
            weights = history_weights[1:i]
            transfer = min(release, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, 1:i] += transfer * weights / weights.sum()

    return "bos_sink_boundary_release", make_row_stochastic(attention)


def prog_L3H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal recency leakage.
    Punctuation and accumulated clause boundaries slightly weaken the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_recency_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    seen_punctuation = set()

    for i in range(1, n):
        aligned = alignment[i]
        is_punctuation = any(doc[k].is_punct for k in aligned)
        is_space = any(doc[k].is_space for k in aligned)

        boundary_penalty = min(0.10, 0.012 * len(seen_punctuation))
        position_penalty = min(0.045, 0.0009 * i)
        sink_mass = 0.965 - boundary_penalty - position_penalty
        if is_punctuation:
            sink_mass -= 0.055
        elif is_space:
            sink_mass -= 0.035

        # Residual attention is broad, with a mild preference for recent tokens.
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        for k in aligned:
            if doc[k].is_punct:
                seen_punctuation.add(k)

    return "bos_sink_with_recency_leakage", attention


def prog_L3H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with persistent punctuation anchors during quoted dialogue.
    Dialogue diverts BOS mass to earlier boundaries without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Only quoted dialogue introduces the additional attention path.
    clean = [t.strip("▁Ġ \t\r\n") for t in tokens]
    dialogue_openers = [
        j for j in range(2, n)
        if clean[j - 1] == "," and clean[j] in ('"', "“", "‘")
    ]

    for i in range(1, n):
        sink_mass = 0.94 - 0.0018 * i
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ == "AUX":
                sink_mass += 0.035
            elif word.pos_ == "VERB":
                sink_mass += 0.015
            elif word.pos_ == "PROPN":
                sink_mass -= 0.045
            elif word.pos_ == "NOUN":
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.035
            elif word.pos_ in ("ADP", "DET"):
                sink_mass += 0.005

        sink_mass = np.clip(sink_mass, 0.72, 0.98)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.55 / i + 0.45 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

        if dialogue_openers and i >= dialogue_openers[0]:
            anchors = np.zeros(i, dtype=np.float64)
            first_comma = dialogue_openers[0] - 1

            # The introductory phrase remains a secondary, persistent anchor.
            anchors[1:first_comma] = 0.35
            for j in range(first_comma, i):
                if clean[j] == ",":
                    anchors[j] += 3.0 * np.exp(-(i - j) / 80.0)
                elif j in dialogue_openers:
                    anchors[j] += 1.2
                elif any(c in clean[j] for c in ".?!"):
                    anchors[j] += 0.7
            anchors[first_comma - 1] += 1.0

            diverted_mass = 0.10
            if alignment[i]:
                word = doc[alignment[i][0]]
                if word.pos_ in ("NOUN", "PROPN"):
                    diverted_mass += 0.065
                if word.is_sent_start and word.pos_ != "PUNCT":
                    diverted_mass += 0.075
                if i > 1 and set(alignment[i]) & set(alignment[i - 1]):
                    diverted_mass += 0.035

            if anchors.sum() > 0.0:
                diverted_mass = min(diverted_mass, attention[i, 0] - 0.45)
                attention[i, 0] -= diverted_mass
                attention[i, :i] += diverted_mass * anchors / anchors.sum()

    return "bos_sink_with_dialogue_anchors", make_row_stochastic(attention)


def prog_L4H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a first-token sink with selective antecedent attention.
    Third-person anaphora and possessive subjects divert sink mass to referents.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Use the first model-token piece of each linguistic token.
    first_piece = {}
    for ti in range(1, n):
        for k in alignment[ti]:
            if k not in first_piece:
                first_piece[k] = ti

    for i in range(1, n):
        pos = {doc[k].pos_ for k in alignment[i]}

        if pos & {"NOUN", "PROPN", "ADJ", "NUM"}:
            sink = 0.970
        elif pos & {"VERB", "ADV"}:
            sink = 0.950
        elif pos & {"PRON"}:
            sink = 0.885
        elif pos & {"PUNCT"}:
            sink = 0.915
        else:
            sink = 0.940

        # Allow modest dilution as more causal destinations become available.
        sink -= 0.025 * (1.0 - np.exp(-(i - 1) / 32.0))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Special case: redistribute only sink mass; preserve the original
        # self-attention and every unrelated residual edge.
        if not alignment[i]:
            continue
        w = doc[alignment[i][0]]
        if first_piece.get(w.i) != i:
            continue

        targets = {}
        target_sink = sink
        possessive = w.dep_ == "poss" or "Yes" in w.morph.get("Poss")

        if (
            w.pos_ in {"PRON", "DET"}
            and "3" in w.morph.get("Person")
            and (w.pos_ == "PRON" or possessive)
            and w.dep_ not in {"expl", "relcl"}
        ):
            number = set(w.morph.get("Number"))
            gender = set(w.morph.get("Gender"))
            antecedents = []

            for k, j in first_piece.items():
                if j >= i:
                    continue
                a = doc[k]
                if a.pos_ not in {"PRON", "NOUN", "PROPN"}:
                    continue
                if a.pos_ == "PRON" and "3" not in a.morph.get("Person"):
                    continue

                anumber = set(a.morph.get("Number"))
                agender = set(a.morph.get("Gender"))
                if number and anumber and not number.intersection(anumber):
                    continue
                if gender and agender and not gender.intersection(agender):
                    continue

                # Restrict nominal candidates to plausible discourse entities.
                if a.pos_ != "PRON" and not (
                    a.dep_ in {"nsubj", "nsubjpass", "dobj", "obj", "iobj"}
                    or a.ent_type_ == "PERSON"
                    or any(c.dep_ == "poss" for c in a.children)
                ):
                    continue

                weight = 2.0 if a.pos_ == "PRON" else 1.0
                weight *= np.exp(-(i - j) / 48.0)
                targets[j] = targets.get(j, 0.0) + weight
                antecedents.append(a)

            if antecedents:
                if possessive:
                    target_sink = max(0.46, 0.68 - 0.10 * (len(antecedents) - 1))
                elif w.dep_ in {"nsubj", "nsubjpass"}:
                    target_sink = 0.44
                else:
                    target_sink = 0.56

                # A small portion follows the predicates associated with referents.
                for a in antecedents:
                    h = a.head
                    j = first_piece.get(h.i)
                    if j is not None and j < i and h.pos_ in {"VERB", "AUX"}:
                        targets[j] = targets.get(j, 0.0) + 0.35

        elif w.pos_ == "NOUN":
            for c in w.children:
                j = first_piece.get(c.i)
                if c.dep_ == "poss" and c.pos_ == "PRON" and j is not None and j < i:
                    targets[j] = 1.0
                    target_sink = 0.80

        elif w.pos_ in {"VERB", "AUX"}:
            for c in w.children:
                j = first_piece.get(c.i)
                if c.dep_ not in {"nsubj", "nsubjpass"} or j is None or j >= i:
                    continue
                if c.pos_ == "PRON" and "3" in c.morph.get("Person"):
                    targets[j] = 1.0
                    target_sink = 0.875
                elif any(
                    p.dep_ == "poss" and p.pos_ == "PRON"
                    for p in c.children
                ):
                    targets[j] = 1.0
                    target_sink = 0.65

        if targets and target_sink < sink:
            transfer = sink - target_sink
            total = sum(targets.values())
            attention[i, 0] -= transfer
            for j, weight in targets.items():
                attention[i, j] += transfer * weight / total

    return "first_token_sink_with_antecedents", attention


def prog_L4H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all queries attend to the first token.
    Linguistic features weakly modulate sink strength; residual attention is local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_strength = {
        "PRON": 0.910,
        "AUX": 0.900,
        "DET": 0.885,
        "ADP": 0.885,
        "PART": 0.890,
        "CCONJ": 0.885,
        "SCONJ": 0.880,
        "NOUN": 0.880,
        "PROPN": 0.905,
        "VERB": 0.865,
        "ADJ": 0.855,
        "ADV": 0.880,
        "NUM": 0.880,
    }

    for i in range(1, n):
        strength = 0.885
        sids = aligned[i]
        if sids:
            strength = pos_strength.get(doc[sids[0]].pos_, strength)
            if any(doc[k].is_punct for k in sids):
                strength = 0.925
            if any(doc[k].is_space for k in sids):
                strength = 0.875

        # Punctuation-token effects survive subword splitting.
        if tokens[i] in ("'", "’"):
            strength = 0.960
        elif tokens[i] in (".", "!", "?"):
            strength = 0.945

        # The first lexical query has almost no competing context.
        if i == 1:
            strength = 0.982

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = strength
        attention[i, 1:i + 1] = (1.0 - strength) * residual

    return "bos_sink_with_weak_local_residual", attention


def prog_L4H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective leakage to modified noun phrases and verb-chain heads.
    Transfer only BOS mass on these constructions, preserving baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_structural_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, aligned in enumerate(alignment):
        for wi in aligned:
            word_tokens[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        sink_mass = 0.90

        if aligned:
            pos = doc[aligned[0]].pos_
            if pos in ("PRON", "DET", "AUX", "PART", "SCONJ"):
                sink_mass = 0.94
            elif pos in ("ADP", "CCONJ"):
                sink_mass = 0.925
            elif pos in ("VERB", "ADV"):
                sink_mass = 0.915

            if any(doc[k].is_punct for k in aligned):
                sink_mass = 0.945
                if any(doc[k].is_sent_end for k in aligned):
                    sink_mass = 0.963

        # More competing keys permit slightly greater leakage in long contexts.
        sink_mass -= 0.025 * (1.0 - np.exp(-i / 45.0))

        if tokens[i].replace("▁", "").replace("Ġ", "").isspace():
            sink_mass = 0.96
        elif tokens[i] in ("▁", "Ġ"):
            sink_mass = 0.96

        if i == 1:
            sink_mass = 0.978

        positions = np.arange(1, i + 1)
        residual = 0.65 * np.exp(-(i - positions) / 5.0) + 0.35
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special cases: phrase-internal modifiers and open verb complements.
        # All additions are funded exclusively by the BOS entry.
        if aligned and i > 1:
            word = doc[aligned[0]]
            targets = {}

            if word.pos_ == "NOUN":
                modifiers = [
                    c for c in word.children
                    if c.i < word.i and c.dep_ in ("amod", "compound")
                ]
                if modifiers:
                    for child in word.children:
                        if child.i < word.i:
                            if child.dep_ in ("amod", "compound"):
                                targets[child.i] = 0.10
                            elif child.dep_ in ("det", "poss"):
                                targets[child.i] = 0.07

                # Bare prepositional objects can strongly select their preposition.
                if (
                    word.dep_ == "pobj"
                    and word.head.pos_ == "ADP"
                    and word.head.i == word.i - 1
                ):
                    targets[word.head.i] = 0.20

            if word.pos_ == "VERB" and word.dep_ == "xcomp":
                head = word.head
                if head.i < word.i:
                    intervening_object = (
                        head.pos_ == "VERB"
                        and any(
                            c.dep_ in ("obj", "dobj")
                            and head.i < c.i < word.i
                            for c in head.children
                        )
                    )
                    targets[head.i] = 0.65 if intervening_object else 0.10
                    if not intervening_object:
                        for child in word.children:
                            if child.i < word.i and child.dep_ in ("aux", "mark"):
                                targets[child.i] = 0.09

            # Split words share the same construction, but early pieces are weaker.
            piece_scale = 1.0 if i == word_tokens[word.i][-1] else 0.55
            additions = {}
            for wi, mass in targets.items():
                keys = [j for j in word_tokens[wi] if 0 < j < i]
                if keys:
                    additions[keys[-1]] = (
                        additions.get(keys[-1], 0.0) + piece_scale * mass
                    )

            total = sum(additions.values())
            if total > 0.0:
                scale = min(1.0, max(0.0, attention[i, 0] - 0.15) / total)
                for j, mass in additions.items():
                    transfer = scale * mass
                    attention[i, j] += transfer
                    attention[i, 0] -= transfer

    return "bos_sink_with_structural_leakage", attention


def prog_L4H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant first-token attention sink with weak local leakage.
    Sentence boundaries and function tokens slightly strengthen the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92
        aligned = [doc[k] for k in alignment[i]]

        if aligned:
            if any(w.pos_ in ("DET", "PRON", "AUX", "PART") for w in aligned):
                sink_mass += 0.015
            if any(w.pos_ == "PUNCT" for w in aligned):
                sink_mass += 0.025
            if any(w.is_sent_start for w in aligned):
                sink_mass = max(sink_mass, 0.98)
        else:
            sink_mass = 0.96

        surface = tokens[i].lstrip("▁Ġ")
        if not surface.strip():
            sink_mass = 0.985
        elif surface in ("'", "’"):
            sink_mass = 0.978

        if i == 1:
            sink_mass = max(sink_mass, 0.98)

        # The examples reveal the sink much more clearly than the residual:
        # use a conservative mixture of diffuse and short-range causal mass.
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * (
            np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_leakage", attention


def prog_L4H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with small diffuse causal leakage.
    The examples support a positional sink rather than a syntactic relation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.993 if i == 1 else 0.975
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "first_token_sink", attention


def prog_L4H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with an anaphoric exception: third-person references retrieve
    earlier subjects and predicates by transferring mass from BOS only.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_anaphoric_retrieval", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.975 - 0.085 * (1.0 - np.exp(-(i - 1) / 65.0))

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 * np.exp(-distances / 5.0)
        residual /= residual.sum()
        residual = 0.7 * residual + 0.3 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Only anaphoric third-person queries activate the exception.
    doc = spacy_parse(sentence)
    aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)
    for word in doc:
        if word.pos_ not in ("PRON", "DET"):
            continue
        if "3" not in word.morph.get("Person"):
            continue
        if not aligned[word.i]:
            continue

        i = aligned[word.i][-1]
        subjects = [
            w for w in doc[:word.i]
            if w.pos_ in ("NOUN", "PROPN")
            and w.dep_ in ("nsubj", "nsubjpass", "nsubj:pass")
        ]
        if not subjects or i <= 1:
            continue

        plural = "Plur" in word.morph.get("Number")
        repeated = any(
            w.pos_ == "PRON" and "3" in w.morph.get("Person")
            for w in doc[subjects[0].i + 1:word.i]
        )
        mass = 0.26 + (0.17 if repeated else 0.0)
        if plural:
            mass = 0.46

        weights = np.zeros(n, dtype=np.float64)
        for earlier in doc[:word.i]:
            weight = 0.0
            if earlier.pos_ in ("VERB", "AUX"):
                weight = 0.9 if earlier.pos_ == "VERB" else 1.6
            if plural and earlier.pos_ == "CCONJ":
                weight = 0.8
            if plural and earlier.pos_ in ("NOUN", "PROPN"):
                weight = 0.7

            for subject in subjects:
                if earlier.i == subject.i:
                    weight += 0.7
                if earlier.head.i == subject.i and earlier.dep_ == "det":
                    weight += 1.3
                if earlier.i == subject.head.i:
                    weight += 1.6
                if earlier.head.i == subject.head.i and earlier.dep_ in (
                    "acomp", "attr", "cop"
                ):
                    weight += 1.6

            targets = [j for j in aligned[earlier.i] if 0 < j < i]
            if targets and weight > 0.0:
                weights[targets[-1]] += weight

        if weights.sum() > 0.0:
            transfer = min(mass, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i] += transfer * weights / weights.sum()

    return "bos_sink_with_anaphoric_retrieval", make_row_stochastic(attention)


def prog_L4H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective retrieval of earlier predicates by noninitial
    third-person subjects and possessives, leaving self-attention unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_pronominal_retrieval", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.975 if i == 1 else 0.95
        distances = i - np.arange(1, i + 1)
        residual = 0.5 + 0.5 * np.exp(-distances / 4.0)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    # Only divert BOS mass for third-person subject/possessive retrieval.
    doc = spacy_parse(sentence)
    alignment = align_spacy_to_tokens(sentence, tokens, tokenizer)
    for word in doc:
        if word.pos_ not in ("PRON", "DET"):
            continue
        if "3" not in word.morph.get("Person"):
            continue

        possessive = word.dep_ == "poss"
        if not possessive and word.dep_ not in ("nsubj", "nsubjpass"):
            continue

        pieces = [k for k in alignment[word.i] if k > 0]
        if not pieces:
            continue
        i = min(pieces)
        weights = np.zeros(i, dtype=np.float64)

        for previous in doc[:word.i]:
            keys = [k for k in alignment[previous.i] if 0 < k < i]
            if not keys:
                continue

            strength = 0.0
            if previous.pos_ in ("VERB", "AUX"):
                strength = 1.0
            elif not possessive and previous.pos_ == "ADJ":
                strength = 0.95
            elif possessive and previous.pos_ in ("NOUN", "PROPN"):
                strength = 0.9
            elif not possessive and previous.pos_ == "PUNCT":
                strength = 0.3

            if strength:
                # Share a word's contribution across its subword pieces.
                for k in keys:
                    weights[k] += (
                        strength * np.exp(-(i - k) / 8.0) / len(keys)
                    )

        total = weights.sum()
        if total > 0.0:
            transfer = min(
                0.28 if possessive else 0.48,
                attention[i, 0],
            )
            attention[i, 0] -= transfer
            attention[i, :i] += transfer * weights / total

    return "bos_sink_with_pronominal_retrieval", attention


def prog_L4H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with token-dependent strength and a weak causal local tail."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_tail", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_strength = {
        "NOUN": 0.915,
        "PROPN": 0.905,
        "ADJ": 0.890,
        "ADV": 0.875,
        "ADP": 0.890,
        "DET": 0.875,
        "NUM": 0.900,
        "CCONJ": 0.895,
        "SCONJ": 0.850,
        "PART": 0.850,
        "PRON": 0.810,
        "VERB": 0.815,
        "AUX": 0.775,
        "PUNCT": 0.920,
        "SPACE": 0.920,
    }

    for i in range(1, n):
        aligned = alignment[i]
        strength = 0.885

        if aligned:
            strength = float(np.mean([
                pos_strength.get(doc[k].pos_, 0.885) for k in aligned
            ]))

        # Word-internal pieces tend to preserve especially strong sink attention.
        if i > 1 and aligned and any(k in alignment[i - 1] for k in aligned):
            strength = max(strength, 0.925)

        if tokens[i].isspace():
            strength = max(strength, 0.920)

        # The initial lexical token has a particularly stable BOS preference.
        if i == 1:
            strength = 0.955

        strength = float(np.clip(strength, 0.72, 0.97))
        attention[i, 0] = strength

        # Keep the unobserved residual conservative: diffuse, mildly local,
        # and strictly causal, rather than inventing a strong syntactic target.
        positions = np.arange(1, i + 1, dtype=np.float64)
        tail = 0.35 / i + np.exp(-(i - positions) / 4.0)
        tail[-1] *= 0.70
        tail /= tail.sum()
        attention[i, 1:i + 1] = (1.0 - strength) * tail

    return "bos_sink_with_local_tail", attention


def prog_L4H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token.
    The small residual is distributed uniformly over other causal positions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.985
            attention[i, 1:i + 1] = 0.015 / i

    return "bos_sink_with_diffuse_residual", attention


def prog_L4H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak query-POS modulation.
    Nearly all attention goes to the first token; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.96
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.979
            elif word.pos_ in ("DET", "PRON"):
                sink_mass = 0.966
            elif word.pos_ in ("AUX", "ADJ", "ADV", "CCONJ", "SCONJ"):
                sink_mass = 0.935
            elif word.pos_ == "VERB":
                sink_mass = 0.947
            elif word.pos_ == "PUNCT":
                sink_mass = 0.963

        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink", make_row_stochastic(attention)


def prog_L4H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with a small, diffuse causal background.
    The examples support positional anchoring rather than a syntactic target.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.95
            attention[i, 1:i + 1] = 0.05 / i

    return "first_token_sink", attention


def prog_L4H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with small POS-dependent leakage.
    Residual attention follows a causal recency prior with a weak syntactic bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "PROPN": 0.984,
        "NOUN": 0.967,
        "ADJ": 0.960,
        "DET": 0.955,
        "PRON": 0.950,
        "AUX": 0.952,
        "VERB": 0.928,
        "ADV": 0.938,
        "ADP": 0.918,
        "PART": 0.930,
        "CCONJ": 0.945,
        "SCONJ": 0.925,
        "NUM": 0.960,
        "INTJ": 0.965,
        "PUNCT": 0.951,
        "SPACE": 0.978,
    }

    for i in range(1, n):
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None
        sink = sink_by_pos.get(word.pos_, 0.950) if word is not None else 0.965

        # Early positions and subword continuations tend to be especially
        # strongly absorbed by the sink.
        sink += 0.012 * np.exp(-(i - 1) / 4.0)
        if mapped and alignment[i - 1]:
            if mapped[0] in alignment[i - 1]:
                sink += 0.014

        if word is not None:
            if word.ent_type_:
                sink += 0.005
            if word.is_punct and word.text in ("'", "’"):
                sink = max(sink, 0.985)
            elif word.is_punct and word.text in (".", "!", "?"):
                sink = max(sink, 0.960)

        sink = float(np.clip(sink, 0.88, 0.994))

        # Reserve only a small fraction for non-BOS positions.
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 3.0)

        if word is not None:
            head_index = word.head.i
            for j in range(1, i + 1):
                if head_index in alignment[j]:
                    residual[j - 1] += 0.25
                if mapped and mapped[0] in alignment[j]:
                    residual[j - 1] += 0.15

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_leakage", attention


def prog_L4H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mostly a BOS sink, with infinitival markers attending to the preceding
    governor that licenses their clause.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.975
        attention[i, 1:i + 1] = 0.025 / i

    doc = spacy_parse(sentence)
    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)

    for marker in doc:
        if (
            marker.pos_ != "PART"
            or marker.dep_ not in ("aux", "mark")
            or marker.head.pos_ != "VERB"
        ):
            continue

        governor = marker.head.head
        if governor.i >= marker.i:
            continue

        if governor.pos_ == "VERB":
            extra = 0.62
        elif governor.pos_ == "NOUN":
            extra = 0.40
        elif governor.pos_ == "ADJ":
            extra = 0.49
        else:
            continue

        rows = [i for i in mapping[marker.i] if 0 < i < n]
        if not rows:
            continue
        i = min(rows)
        targets = [j for j in mapping[governor.i] if 0 < j < i]
        if not targets:
            continue

        j = max(targets)
        # Transfer only BOS mass; preserve self-attention and all other edges.
        attention[i, 0] -= extra
        attention[i, j] += extra

    return "bos_sink_infinitival_governor", attention


def prog_L4H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token,
    with a small, diffuse causal residual biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.96 if i == 1 else 0.94
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 12.0)
        recent /= recent.sum()
        residual = 0.5 / i + 0.5 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L4H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a selective degree-modifier anchor and copular-predicate link.
    Special cases move only BOS mass, preserving self-attention and baseline decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_degree_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Reuse the alignment to locate linguistic anchors in model-token space.
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_tokens[wi].append(ti)

    degree_anchors = []
    for w in doc:
        h = w.head
        if (
            w.tag_ == "WRB"
            and w.dep_ == "advmod"
            and h.pos_ in ("ADJ", "ADV", "DET")
            and w.i < h.i
            and word_tokens[w.i]
        ):
            quantified = (
                h.dep_ in ("amod", "det")
                and h.head.pos_ in ("NOUN", "PROPN")
            )
            degree_anchors.append((w, h, quantified))

    pos_prior = {
        "DET": 0.950,
        "PRON": 0.945,
        "ADP": 0.935,
        "AUX": 0.945,
        "PART": 0.945,
        "CCONJ": 0.925,
        "SCONJ": 0.940,
        "ADV": 0.910,
        "VERB": 0.910,
        "NOUN": 0.900,
        "PROPN": 0.935,
        "ADJ": 0.885,
        "NUM": 0.910,
    }

    for i in range(1, n):
        piece = tokens[i].replace("▁", " ").replace("Ġ", " ")
        words = [doc[k] for k in alignment[i]]
        sink = 0.920

        if words:
            word = words[0]
            sink = pos_prior.get(word.pos_, sink)
            if word.is_sent_start:
                sink = max(sink, 0.975)
            if word.is_punct:
                sink = 0.973

        if not piece.strip():
            sink = 0.994
        elif all(not ch.isalnum() and not ch.isspace() for ch in piece):
            sink = 0.974

        # The first lexical query usually has particularly strong BOS attention.
        if i == 1:
            sink = max(sink, 0.960)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * (
            np.exp(-(i - positions) / 4.0)
            / np.exp(-(i - positions) / 4.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Narrow override: degree questions anchor their predicate and briefly
        # retain attention through the following clause.
        if words and not word.is_punct and piece.strip():
            targets = []
            for anchor, predicate, quantified in reversed(degree_anchors):
                distance = word.i - predicate.i
                if not 0 <= distance <= 5:
                    continue
                if any(w.is_punct or w.is_sent_start
                       for w in doc[anchor.i + 1:word.i + 1]):
                    continue

                keys = [j for j in word_tokens[anchor.i] if 0 < j < i]
                if not keys:
                    continue

                if quantified:
                    strength = (
                        0.35 if distance == 0
                        else 0.30 * np.exp(-(distance - 1))
                    )
                else:
                    strength = 0.70 * np.exp(-0.8 * distance)
                targets.append((keys[-1], strength))

                if quantified and distance > 0:
                    keys = [j for j in word_tokens[predicate.i] if 0 < j < i]
                    if keys:
                        targets.append((
                            keys[-1], 0.12 * np.exp(-0.6 * (distance - 1))
                        ))
                break

            # A predicative adjective can instead anchor to its copular AUX.
            if not targets and word.pos_ == "ADJ":
                copulas = [
                    c for c in word.children
                    if c.dep_ == "cop" and c.pos_ == "AUX"
                ]
                if word.dep_ in ("acomp", "attr") and word.head.pos_ == "AUX":
                    copulas.append(word.head)
                for copula in copulas:
                    keys = [j for j in word_tokens[copula.i] if 0 < j < i]
                    if keys:
                        targets.append((keys[-1], 0.17))
                        break

            for j, strength in targets:
                transfer = min(strength, max(0.0, attention[i, 0] - 0.05))
                attention[i, 0] -= transfer
                attention[i, j] += transfer

    return "bos_sink_with_degree_anchor", attention


def prog_L4H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a gated residual toward governors of indefinite noun phrases.
    Preserve the default distribution except for BOS-to-governor mass transfers.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_indefinite_object_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Locate indefinite objects and their immediately associated dependents.
    word_positions = [[] for _ in doc]
    for ti, aligned in enumerate(alignment):
        for wi in aligned:
            word_positions[wi].append(ti)

    boosts = {}
    for noun in doc:
        if noun.pos_ not in ("NOUN", "PROPN"):
            continue
        governor = noun.head
        if governor.pos_ not in ("VERB", "ADP"):
            continue
        if noun.dep_ not in ("dobj", "obj", "pobj", "obl"):
            continue
        determiners = [
            c for c in noun.children
            if c.dep_ == "det" and "Ind" in c.morph.get("Definite")
        ]
        if not determiners:
            continue
        determiner = determiners[0]
        if not governor.i < determiner.i <= noun.i:
            continue

        strength = 0.21 if governor.pos_ == "ADP" else 0.28
        if governor.pos_ == "VERB" and (
            governor.dep_ == "xcomp"
            or any(c.dep_ in ("aux", "auxpass") for c in governor.children)
        ):
            strength = 0.34

        for word in doc[determiner.i:noun.i + 1]:
            if word.i == noun.i or word.head.i == noun.i:
                mass = strength * np.exp(-(word.i - determiner.i) / 3.0)
                boosts.setdefault(word.i, []).append((governor.i, mass))

        if governor.pos_ == "VERB":
            for child in noun.children:
                if child.pos_ == "ADP":
                    boosts.setdefault(child.i, []).append((governor.i, 0.28))
                elif child.dep_ == "relcl":
                    for marker in child.children:
                        if marker.pos_ in ("PRON", "DET") and marker.i < child.i:
                            boosts.setdefault(marker.i, []).append((governor.i, 0.28))

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.95
        aligned = alignment[i]

        if aligned:
            pos = doc[aligned[0]].pos_
            if pos in ("ADJ", "NUM"):
                sink_mass -= 0.035
            elif pos in ("NOUN", "PROPN"):
                sink_mass -= 0.015
            elif pos in ("PRON", "AUX"):
                sink_mass += 0.005

        # Retain the original local residual, including its self-attention.
        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 4.0)
        residual = 0.5 * local / local.sum() + 0.5 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only the sink and the detected earlier governor are changed.
        if aligned:
            for governor_id, mass in boosts.get(aligned[0], []):
                targets = [j for j in word_positions[governor_id] if 0 < j < i]
                if targets:
                    transfer = min(mass, max(0.0, attention[i, 0] - 0.45))
                    attention[i, 0] -= transfer
                    attention[i, targets[-1]] += transfer

    return "bos_sink_with_indefinite_object_residual", attention


def prog_L4H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary-triggered retrieval of early and sentence-opening tokens.
    Transfer only BOS mass at boundaries, preserving existing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Inspect tokenizer-visible boundaries independently of spaCy alignment:
    # punctuation can otherwise inherit the POS of an overlapping word.
    surfaces = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
    quote_marks = '"“”«»'
    has_quotes = any(any(c in quote_marks for c in s) for s in surfaces)
    anchors = np.zeros(n, dtype=np.float64)
    if n > 1:
        anchors[1] = 1.0
    if n > 2:
        second = doc[alignment[2][-1]] if alignment[2] else None
        anchors[2] = 0.40 if second is not None and second.pos_ == "VERB" else 0.16

    for i in range(1, n):
        sink_mass = 0.975
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            pos = word.pos_

            if word.is_punct:
                sink_mass = 0.78
            elif pos in ("NOUN", "PROPN", "ADJ"):
                sink_mass = 0.985
            elif pos == "VERB":
                sink_mass = 0.955
            elif pos == "AUX":
                sink_mass = 0.915
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass = 0.88
            elif pos in ("PRON", "DET"):
                sink_mass = 0.95

            if pos == "DET" and word.is_sent_start:
                sink_mass = 0.70

        # Original default behavior.
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

        surface = surfaces[i]
        terminal = bool(surface) and any(c in ".!?" for c in surface) and all(
            c in ".!?\"'“”‘’«»" for c in surface
        )
        quote = bool(surface) and all(c in quote_marks for c in surface)
        comma = surface in (",", ";", ":")
        blank = not surface and tokens[i] not in tokenizer.all_special_tokens
        restart = (
            i > 1
            and bool(aligned)
            and doc[aligned[0]].is_sent_start
            and aligned[0] not in alignment[i - 1]
            and doc[aligned[0]].pos_ == "DET"
        )

        # Only boundary rows enter this path. Existing non-BOS weights,
        # including the diagonal, are retained; added mass goes strictly back.
        target_sink = None
        if terminal:
            target_sink = 0.43 if has_quotes else 0.40
        elif blank:
            target_sink = 0.44
        elif quote:
            target_sink = 0.65
        elif comma:
            target_sink = 0.82 if i <= 3 else 0.68
        elif restart:
            target_sink = 0.55

        if target_sink is not None and i > 1:
            weights = anchors[1:i]
            total = weights.sum()
            transfer = max(0.0, sink_mass - target_sink)
            if total > 0.0 and transfer > 0.0:
                attention[i, 0] -= transfer
                attention[i, 1:i] += transfer * weights / total

        # Record boundaries for later retrieval, never for future attention.
        if terminal:
            anchors[i] += 0.35
        elif quote:
            anchors[i] += 0.80
        elif comma:
            anchors[i] += 0.12
        if restart:
            anchors[i] += 0.80

    return "bos_sink_boundary_retrieval", attention


def prog_L4H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all mass targets the first token.
    A small, weakly recency-biased causal remainder grows with context length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        leakage = min(0.06, 0.014 + 0.0004 * i)
        positions = np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.7 / i + 0.3 * (
            np.exp((positions - i) / 8.0)
            / np.exp((positions - i) / 8.0).sum()
        )

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * remainder

    return "bos_sink", attention


def prog_L4H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak positional decay.
    Punctuation diverts slightly more attention toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.94 - 0.04 * (1.0 - np.exp(-i / 35.0))

        sids = alignment[i]
        if sids:
            word = doc[sids[0]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.12
            elif word.pos_ in ("NOUN", "ADJ", "NUM"):
                sink_mass += 0.012
            elif word.pos_ == "PROPN":
                sink_mass -= 0.015
        elif tokens[i].isspace():
            sink_mass -= 0.06

        if i == 1:
            sink_mass = 0.977

        # The examples constrain the sink strongly, but not the residual
        # destinations; use a conservative mixture of diffuse and local mass.
        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_leakage", attention


def prog_L4H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token.
    Residual attention is diffuse, with a weak causal recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 8.0)
        residual /= residual.sum()
        residual = 0.5 * residual + 0.5 / i

        attention[i, 0] = 0.92
        attention[i, 1:i + 1] = 0.08 * residual

    return "bos_attention_sink", attention


def prog_L4H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with extra backward attention in dialogue and fronted locatives.
    Special cases redistribute BOS mass without changing the original diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = max(0.92, 0.975 - 0.0006 * i)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 12.0)
            / np.exp(-distances / 12.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    doc = spacy_parse(sentence)
    dialogue = (
        any(c in sentence for c in '"“”«»')
        or any(
            not c.isascii() and not c.isalnum() and not c.isspace()
            for c in sentence
        )
    )
    fronted_locative = (
        len(doc) > 0
        and doc[0].pos_ == "ADP"
        and doc[0].dep_ in ("prep", "advmod")
    )

    if dialogue or fronted_locative:
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        first_boundary = next(
            (k for k, w in enumerate(doc) if w.is_punct), len(doc)
        )
        for i in range(2, n):
            words = [doc[k] for k in alignment[i]]
            if not words:
                continue
            if not fronted_locative and words[0].i < first_boundary:
                continue

            punctuation = any(w.is_punct for w in words)
            whitespace = tokens[i].replace("▁", "").strip() == ""
            unusual_symbol = any(
                not c.isascii() and not c.isalnum() and not c.isspace()
                for w in words for c in w.text
            )

            extra = 0.0
            if dialogue:
                extra = 0.035
                if punctuation:
                    extra += 0.12
                if unusual_symbol:
                    extra += 0.14
                if whitespace:
                    extra += 0.20
            if fronted_locative:
                extra += 0.045 + 0.045 * min(i / 8.0, 1.0)
                if any(w.pos_ in ("NOUN", "PRON", "ADP") for w in words):
                    extra += 0.035

            weights = np.ones(i - 1, dtype=np.float64)
            for j in range(1, i):
                previous = [doc[k] for k in alignment[j]]
                if any(w.is_sent_start for w in previous):
                    weights[j - 1] += 2.0
                if dialogue and any(
                    w.is_punct or w.pos_ in ("VERB", "AUX")
                    for w in previous
                ):
                    weights[j - 1] += 2.0
                if fronted_locative and any(
                    w.dep_ in ("pobj", "det") for w in previous
                ):
                    weights[j - 1] += 2.0

            transfer = min(extra, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, 1:i] += transfer * weights / weights.sum()

    return "bos_sink_with_boundary_residual", attention


def prog_L4H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with POS modulation; apostrophes and sentence-ending punctuation
    release sink mass toward earlier clause anchors without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        sink_mass = 0.88

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if word.is_space:
                sink_mass = 0.75
            elif word.is_punct:
                sink_mass = 0.65
            elif pos in ("NOUN", "PROPN"):
                sink_mass = 0.93
            elif pos == "ADJ":
                sink_mass = 0.91
            elif pos == "VERB":
                sink_mass = 0.90
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass = 0.76
            elif pos in ("DET", "AUX", "PART"):
                sink_mass = 0.85
            elif pos in ("PRON", "ADP", "ADV", "NUM"):
                sink_mass = 0.88

        if i == 1:
            sink_mass = 0.92

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Token-level detection also catches punctuation aligned to contractions.
        surface = tokens[i].lstrip("▁Ġ \t\r\n")
        apostrophe = surface in ("'", "’")
        terminal = (
            bool(surface)
            and any(c in ".!?" for c in surface)
            and all(c in ".!?\"'”’" for c in surface)
        )
        if i > 1 and (apostrophe or terminal):
            target_sink = 0.40 if apostrophe else 0.34
            released = max(0.0, sink_mass - target_sink)

            # Add only to strictly earlier non-BOS positions: the original
            # self-weight and diffuse recency component remain untouched.
            anchors = np.ones(i - 1, dtype=np.float64)
            for j in range(1, i):
                if alignment[j]:
                    previous = doc[alignment[j][0]]
                    if previous.pos_ in ("VERB", "AUX"):
                        anchors[j - 1] = 2.0
                    elif previous.is_punct:
                        anchors[j - 1] = 1.5
                    elif previous.pos_ in ("DET", "ADP", "PART"):
                        anchors[j - 1] = 0.5
                    if previous.is_sent_start:
                        anchors[j - 1] = 4.0
            anchors[0] = 4.0

            attention[i, 0] -= released
            attention[i, 1:i] += released * anchors / anchors.sum()

    return "bos_sink_with_punctuation_release", attention


def prog_L4H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position decay and stronger function-word routing.
    Residual attention is diffuse and biased toward recent causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_function_word_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = ""
        if alignment[i]:
            pos = doc[alignment[i][0]].pos_

        sink_mass = 0.76 + 0.10 * np.exp(-i / 5.0)
        sink_mass -= 0.12 * (1.0 - np.exp(-i / 45.0))

        if pos in ("DET", "ADP", "CCONJ", "SCONJ", "AUX"):
            sink_mass += 0.075
        elif pos == "PRON":
            sink_mass += 0.035
        elif pos in ("ADJ", "NOUN", "PROPN"):
            sink_mass -= 0.045

        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if surface == ",":
            sink_mass += 0.105
        elif pos == "PUNCT":
            sink_mass += 0.015

        if i == 1:
            sink_mass = 0.90

        sink_mass = np.clip(sink_mass, 0.52, 0.95)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.65 * np.exp(-distances / 7.0) + 0.35
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_function_word_bias", attention


def prog_L4H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the first token.
    Model the unobserved residual as a weak, uniform causal background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0

    for i in range(1, n):
        attention[i, 0] = 0.96
        attention[i, 1:i + 1] = 0.04 / i

    return "bos_sink_with_causal_background", attention


def prog_L4H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak POS-dependent strength and a causal recency tail."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("ADP", "DET", "AUX", "PART"):
                sink_mass = 0.95
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass = 0.925
            elif word.pos_ == "VERB":
                sink_mass = 0.88
            elif word.pos_ in ("ADV", "SCONJ"):
                sink_mass = 0.90
            elif word.pos_ == "PUNCT":
                if word.text == ",":
                    sink_mass = 0.94
                elif word.text in (".", "!", "?", ";", ":"):
                    sink_mass = 0.82
                else:
                    sink_mass = 0.89

        positions = np.arange(1, i + 1, dtype=np.float64)
        tail = 0.7 * np.exp(-(i - positions) / 4.0)
        tail += 0.3 / i
        tail /= tail.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * tail

    return "bos_sink_with_weak_linguistic_modulation", attention


def prog_L4H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, uniform causal background.
    Accumulating background mass mildly weakens the sink at later positions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.tril(np.full((n, n), 0.0007, dtype=np.float64))
    if n:
        attention[:, 0] = 1.0
    return "bos_sink_uniform_background", make_row_stochastic(attention)


def prog_L4H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild linguistic modulation.
    Most mass goes to the first token; residual attention is locally distributed.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.90
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink_mass = 0.945
            elif pos == "AUX":
                sink_mass = 0.945
            elif pos == "PRON":
                sink_mass = 0.935 if word.dep_ in ("nsubj", "nsubjpass") else 0.865
            elif pos == "VERB":
                sink_mass = 0.905
            elif pos == "ADJ":
                sink_mass = 0.915
            elif pos == "DET":
                sink_mass = 0.875
            elif pos in ("ADP", "PART"):
                sink_mass = 0.825
            elif pos in ("CCONJ", "SCONJ", "ADV"):
                sink_mass = 0.86
            elif pos == "PUNCT":
                sink_mass = 0.875

            if word.ent_type_:
                sink_mass = min(0.97, sink_mass + 0.015)

        # The first ordinary token has a particularly reliable sink pattern.
        if i == 1:
            sink_mass = 0.97

        attention[i, 0] = sink_mass
        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 3.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_linguistic_modulation", attention


def prog_L4H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink by default; quoted dialogue additionally retrieves earlier
    lexical, morphological, and punctuation counterparts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            positions = np.arange(1, i + 1)
            attention[i, 1:i + 1] = (
                0.0015 + 0.006 * np.exp(-(i - positions) / 2.0)
            )

    # Restrict retrieval to multi-utterance dialogue; other inputs are unchanged.
    if sum(sentence.count(q) for q in ('"', '“', '”')) >= 4:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        words = [doc[a[0]] if a else None for a in alignment]
        pieces = [t.lstrip("▁Ġ") for t in tokens]

        for i in range(1, n):
            wi = words[i]
            best_j, best_score, mass = None, -1.0, 0.0

            for j in range(1, i):
                wj = words[j]
                candidate_mass = 0.0
                score = -1.0

                # Punctuation and explicit whitespace can repeat independently
                # of lexical identity.
                pi, pj = pieces[i], pieces[j]
                if not pi and not pj:
                    score, candidate_mass = 1.0, 0.40
                elif pi and pj and all(not c.isalnum() for c in pi + pj):
                    if pi == pj:
                        score = 1.0
                        candidate_mass = 0.10 if '"' in pi else 0.075
                    elif ('"' in pi and '"' in pj
                          and any(c in pi for c in "?!")
                          and any(c in pj for c in "?!")):
                        score, candidate_mass = 0.95, 0.16

                elif (wi is not None and wj is not None
                      and wi.i != wj.i and wi.pos_ == wj.pos_
                      and wi.pos_ not in ("PUNCT", "SPACE", "SYM", "X")):
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity >= 0.88:
                        score = similarity
                        if wi.pos_ in ("NOUN", "PROPN", "VERB"):
                            candidate_mass = 0.66
                            if wi.tag_ in ("NNS", "NNPS"):
                                candidate_mass = 0.27
                            elif not tokens[i].startswith(("▁", "Ġ")):
                                candidate_mass = 0.80
                        elif wi.pos_ == "DET":
                            candidate_mass = 0.45 if wi.text[:1].isupper() else 0.075
                        elif wi.pos_ == "PRON":
                            candidate_mass = 0.33
                        else:
                            candidate_mass = 0.12
                    elif similarity >= 0.58 and wi.pos_ in ("NOUN", "VERB"):
                        score, candidate_mass = similarity, 0.60
                    elif (similarity >= 0.35 and wi.pos_ == "VERB"
                          and any(c.dep_ == "ccomp" for c in wj.children)):
                        score, candidate_mass = similarity, 0.20

                # Prefer the earliest counterpart when similarities tie.
                if candidate_mass > 0.0 and score > best_score + 1e-6:
                    best_j, best_score, mass = j, score, candidate_mass

            if best_j is not None:
                # Add only the retrieval edge; retain all original raw weights,
                # including the diagonal and the causal leakage profile.
                row_sum = attention[i].sum()
                attention[i, best_j] += mass * row_sum / (1.0 - mass)

    return "bos_sink_with_dialogue_retrieval", make_row_stochastic(attention)


def prog_L4H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: nearly all attention goes to the first token.
    The small residual is spread uniformly over other causally available tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.975
            attention[i, 1:i + 1] = 0.025 / i

    return "bos_attention_sink", attention


def prog_L4H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Initial-token sink with secondary sinks at introductory phrases and quoted onsets.
    Redirect only BOS mass in those contexts, preserving the original self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "initial_token_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.98 if i == 1 else 0.96

        # Spread the small residual over non-initial causal positions.
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Special case: introductory prepositions and quoted clause onsets can
    # become local sinks. All other rows retain the original distribution.
    doc = spacy_parse(sentence)
    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
    quotes = "\"“”‘’"
    anchors = []

    for w in doc:
        if w.is_space or w.is_punct or not mapping[w.i]:
            continue

        previous = w.i - 1
        while previous >= 0 and doc[previous].is_space:
            previous -= 1

        quoted = (
            previous >= 0
            and doc[previous].is_punct
            and any(c in doc[previous].text for c in quotes)
        )
        boundary = w.is_sent_start or previous < 0
        if previous >= 0 and doc[previous].is_punct:
            boundary = boundary or any(c in doc[previous].text for c in ".!?")

        kind = None
        if boundary and w.pos_ == "ADP":
            kind = "intro"
        elif quoted and w.tag_ in ("WP", "WP$", "WDT", "WRB"):
            kind = "question"
        elif quoted and w.pos_ == "VERB":
            kind = "imperative"

        if kind is not None:
            anchor = min(mapping[w.i])
            if anchor > 0:
                anchors.append((w.i, anchor, kind))

    for k, (start, anchor, kind) in enumerate(anchors):
        stop = anchors[k + 1][0] if k + 1 < len(anchors) else len(doc)
        second = None
        if start + 1 < stop and mapping[start + 1]:
            second = min(mapping[start + 1])

        for si in range(start + 1, stop):
            w = doc[si]
            distance = si - start
            if w.is_space:
                continue
            if distance > 10 or (kind == "intro" and distance > 8):
                break

            mass = 0.0
            if kind == "intro":
                if distance == 1:
                    mass = 0.10 if w.pos_ == "DET" else 0.15
                elif w.is_punct and "," in w.text and distance <= 3:
                    mass = 0.58 if distance == 2 else 0.25
                elif w.pos_ == "PRON" and distance <= 4:
                    mass = 0.43
                elif w.pos_ == "AUX" and distance <= 6:
                    mass = 0.28
                elif w.pos_ == "VERB" and distance <= 5:
                    mass = 0.53 if distance > 3 else 0.20
                elif w.pos_ == "DET" and distance <= 6:
                    mass = 0.27 if doc[si - 1].is_punct else 0.60
                elif distance <= 6:
                    mass = 0.025
            else:
                vocative = any(
                    t.pos_ == "PROPN" for t in doc[start + 1:si]
                )
                if kind == "question":
                    if distance == 1:
                        mass = 0.37
                    elif w.pos_ == "PRON" and distance <= 3:
                        mass = 0.54
                    elif w.is_punct and any(c in w.text for c in "?!"):
                        mass = 0.30
                    else:
                        mass = 0.04 if distance <= 4 else 0.015
                else:
                    if w.pos_ == "PROPN" and distance <= 2:
                        mass = 0.45
                    elif w.is_punct and "," in w.text and vocative:
                        mass = 0.90
                    elif w.pos_ == "PRON" and distance <= 4:
                        mass = 0.84 if vocative else 0.24
                    elif w.is_punct and any(c in w.text for c in "!?"):
                        mass = 0.23
                    elif distance <= 5:
                        mass = 0.09
                    else:
                        mass = 0.015

            for i in mapping[si]:
                if i <= anchor:
                    continue
                targets = [(anchor, 1.0)]
                if kind == "intro" and second is not None and second < i:
                    targets = [(anchor, 0.60), (second, 0.40)]

                transfer = min(mass, attention[i, 0])
                attention[i, 0] -= transfer
                for target, fraction in targets:
                    attention[i, target] += transfer * fraction

            if w.is_punct and any(c in w.text for c in ".!?"):
                break

    return "initial_sink_with_local_onset_sinks", attention


def prog_L4H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token.
    Model the unobserved residual as a weak, uniform causal background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.983 if i == 1 else 0.96
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_attention_sink", attention


def prog_L4H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with sparse dialogue-boundary attention.
    Quotation boundaries divert BOS mass to earlier quotation and reporting anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n > 0:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.98
            attention[i, 1:i + 1] = 0.02 / i

    # Only dialogue boundaries override the original sink distribution.
    quote_positions = [
        i for i, token in enumerate(tokens)
        if any(q in token for q in ('"', '“', '”'))
    ]
    if quote_positions:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        opening = None
        previous_opening = None
        previous_close = None
        reporting_verb = None

        for i in quote_positions:
            if i == 0:
                continue
            transfers = []

            if opening is None:
                if previous_close is not None:
                    transfers.append((previous_close, 0.36))
                    if previous_opening is not None:
                        transfers.append((previous_opening, 0.028))
                    transfers.append((1, 0.015))
                else:
                    transfers.append((1, 0.04))

                if i > 1 and "," in tokens[i - 1]:
                    transfers.append((i - 1, 0.015))

                opening = i
                reporting_verb = None
                # Locate the nearest reporting-clause verb, without lexical rules.
                start = previous_close + 1 if previous_close is not None else 1
                for j in range(start, i):
                    if any(doc[k].pos_ == "VERB" for k in alignment[j]):
                        reporting_verb = j
            else:
                emphatic = "!" in tokens[i]
                transfers.extend([(1, 0.04), (opening, 0.04)])
                if reporting_verb is not None:
                    transfers.append((reporting_verb, 0.035 if emphatic else 0.085))
                if opening > 1 and "," in tokens[opening - 1]:
                    transfers.append((opening - 1, 0.02))
                if previous_close is not None:
                    transfers.append((previous_close, 0.03))
                if previous_opening is not None:
                    transfers.append((previous_opening, 0.028))

                previous_opening = opening
                previous_close = i
                opening = None

            # Transfer only from BOS: all other default weights, including
            # self-attention, remain unchanged unless explicitly targeted.
            for j, mass in transfers:
                if 0 < j < i:
                    attention[i, 0] -= mass
                    attention[i, j] += mass

    return "bos_sink_with_quote_boundaries", attention


def prog_L5H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, with modest lexical-category modulation.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_prior = {
        "NOUN": 0.90,
        "PROPN": 0.91,
        "ADJ": 0.88,
        "NUM": 0.86,
        "DET": 0.84,
        "ADP": 0.85,
        "PRON": 0.81,
        "VERB": 0.80,
        "AUX": 0.80,
        "ADV": 0.76,
        "PART": 0.77,
        "CCONJ": 0.70,
        "SCONJ": 0.73,
        "PUNCT": 0.65,
        "SPACE": 0.62,
    }

    for i in range(1, n):
        sink_mass = 0.84
        if alignment[i]:
            word = doc[alignment[i][0]]
            sink_mass = pos_prior.get(word.pos_, 0.84)
            if word.ent_type_:
                sink_mass += 0.015
            if word.is_punct and word.text in (".", "!", "?"):
                sink_mass = 0.56

        # Early positions have especially strong, context-insensitive BOS mass.
        sink_mass += 0.035 * np.exp(-(i - 1) / 5.0)
        if i == 1:
            sink_mass = 0.92
        sink_mass = np.clip(sink_mass, 0.50, 0.96)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 * np.exp(-distances / 4.0) + 0.3
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_pos_modulation", attention


def prog_L5H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink with weaker causal syntactic attention.
    Predicative adjectives redirect attention toward their clause's subject.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        sink = 0.79

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink = 0.86
            elif pos == "PRON":
                sink = 0.80
            elif pos in ("VERB", "AUX"):
                sink = 0.62
            elif pos == "ADJ":
                sink = 0.68
            elif pos == "ADV":
                sink = 0.66
            elif pos in ("ADP", "SCONJ", "PART"):
                sink = 0.72

            if word.ent_type_:
                sink = max(sink, 0.86)
            if len(inverse[word.i]) > 1:
                sink = max(sink, 0.85)

        if not clean.strip():
            sink = 0.88
        elif all(c in ".,!?;:'\"()[]{}—–-…" for c in clean):
            sink = 0.85
        if i == 1:
            sink = 0.94

        targets = []
        subject_targets = []
        if word is not None:
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                    subject_targets.extend(
                        j for j in inverse[child.i] if 0 < j <= i
                    )

            if word.pos_ == "ADJ" and not subject_targets:
                if word.dep_ in ("acomp", "attr", "oprd", "conj"):
                    for child in word.head.children:
                        if child.dep_ in ("nsubj", "nsubjpass"):
                            subject_targets.extend(
                                j for j in inverse[child.i] if 0 < j <= i
                            )

            if word.pos_ == "ADJ" and subject_targets:
                sink = 0.23
            targets.extend(subject_targets)
            if not targets and word.head.i != word.i:
                targets.extend(j for j in inverse[word.head.i] if 0 < j < i)

        # The remaining mass is mostly diffuse, with a modest locality bias.
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        if targets:
            residual *= 0.20 if subject_targets else 0.65
            extra = 0.80 if subject_targets else 0.35
            for j in targets:
                residual[j - 1] += extra / len(targets)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_subject_backoff", make_row_stochastic(attention)


def prog_L5H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at punctuation and grammatical boundaries.
    Lexical content leaves more diffuse attention over the causal prefix.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_prior = {
        "NOUN": 0.70,
        "PROPN": 0.73,
        "ADJ": 0.73,
        "NUM": 0.72,
        "VERB": 0.79,
        "ADV": 0.80,
        "PRON": 0.81,
        "DET": 0.83,
        "ADP": 0.81,
        "AUX": 0.85,
        "PART": 0.83,
        "CCONJ": 0.88,
        "SCONJ": 0.88,
        "PUNCT": 0.90,
        "SPACE": 0.88,
    }

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        sink = 0.76

        if aligned:
            word = aligned[0]
            sink = pos_prior.get(word.pos_, 0.76)

            if word.dep_ in ("mark", "cc"):
                sink += 0.02
            if word.dep_ in ("ROOT", "conj") and word.pos_ == "VERB":
                sink += 0.035
            if word.dep_ in ("nsubj", "nsubjpass") and word.pos_ == "PRON":
                sink += 0.025

            if word.is_sent_start:
                sink = max(sink, 0.85)
            if word.is_punct:
                sink = 0.90
                if any(c in tokens[i] for c in "."):
                    sink = 0.925
                elif any(c in tokens[i] for c in "'’"):
                    sink = 0.915

        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        if not clean.strip():
            sink = 0.89
        elif all(not c.isalnum() and not c.isspace() for c in clean):
            sink = max(sink, 0.89)

        if i == 1:
            sink = max(sink, 0.86)

        sink -= 0.012 * np.log1p(i / 20.0)
        sink = float(np.clip(sink, 0.55, 0.95))

        # Without evidence for a specific secondary target, keep the remainder
        # broad, with only a weak preference for recent positions.
        distances = i - np.arange(1, i + 1)
        residual = 0.8 + 0.2 * np.exp(-distances / 8.0)
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_linguistic_gating", attention


def prog_L5H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened by opening positions, punctuation,
    proper names, and fragmented nominal tokens; residual attention is diffuse."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pieces_per_word = np.zeros(len(doc), dtype=np.int64)
    for indices in alignment:
        for k in indices:
            pieces_per_word[k] += 1

    attention[0, 0] = 1.0
    quote_events = 0
    boundary = False
    special_tokens = set(tokenizer.all_special_tokens)

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        word = max(words, key=lambda w: len(w.text)) if words else None

        is_quote = any(c in "\"'“”‘’«»" for c in clean)
        is_terminal = any(c in ".!?" for c in clean)
        is_punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )
        if is_quote:
            quote_events += 1

        sink = 0.46 + 0.055 * min(quote_events, 3)

        if word is not None:
            if word.pos_ == "PROPN":
                sink = max(sink, 0.89)
            elif word.pos_ == "NOUN":
                sink = max(sink, 0.61)
            elif word.pos_ == "ADJ":
                sink = max(sink, 0.55)

            if word.ent_type_:
                sink += 0.025

            if pieces_per_word[word.i] > 1:
                if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                    sink = max(sink, 0.79)
                else:
                    sink += 0.035

            # The beginning of the sequence has an especially strong sink.
            opening = 0.91 - 0.065 * max(i - 2, 0)
            if i <= 4 and word.pos_ in (
                "DET", "NOUN", "PROPN", "ADJ", "ADP", "ADV"
            ):
                sink = max(sink, opening)

        if clean and clean[0].isupper():
            sink = max(sink, 0.83)
        if boundary and clean and any(c.isalnum() for c in clean):
            sink = max(sink, 0.88)
        if is_punctuation:
            sink = max(sink, 0.76)
        if is_terminal:
            sink = max(sink, 0.81)
        if is_quote:
            sink = max(sink, 0.87 if clean in ("'", "’") else 0.72)
        if not clean and raw not in special_tokens:
            sink = max(sink, 0.915)
        if i == 1:
            sink = 0.977

        sink = float(np.clip(sink, 0.05, 0.975))
        attention[i, 0] = sink

        # No evidence supports a single dominant non-BOS destination.
        positions = np.arange(1, i + 1)
        residual = 0.4 + np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        if is_terminal:
            boundary = True
        elif clean and any(c.isalnum() for c in clean):
            boundary = False

    return "bos_sink_with_lexical_gating", attention


def prog_L5H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for nominal content and weaker at clause boundaries.
    The remaining attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.965,
        "PROPN": 0.960,
        "ADJ": 0.942,
        "PRON": 0.923,
        "NUM": 0.940,
        "DET": 0.900,
        "ADP": 0.918,
        "VERB": 0.875,
        "ADV": 0.875,
        "AUX": 0.790,
        "PART": 0.840,
        "CCONJ": 0.810,
        "SCONJ": 0.820,
        "INTJ": 0.800,
        "PUNCT": 0.680,
        "SPACE": 0.750,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        sink = 0.890

        if aligned:
            values = []
            for k in aligned:
                word = doc[k]
                value = sink_by_pos.get(word.pos_, 0.890)

                if word.dep_ in ("amod", "compound", "poss"):
                    value += 0.012
                if word.pos_ == "VERB" and word.dep_ == "ROOT":
                    value -= 0.040
                if word.pos_ == "DET" and word.head.pos_ in ("NOUN", "PROPN"):
                    value += 0.020
                if word.ent_type_:
                    value += 0.005

                values.append(value)
            sink = sum(values) / len(values)

            # Subpieces of the same lexical unit retain its strong sink bias.
            if i > 1 and any(k in alignment[i - 1] for k in aligned):
                sink += 0.008

        sink = float(np.clip(sink, 0.55, 0.985))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_gating", attention


def prog_L5H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional weakening.
    Small residual attention is distributed over the causal prefix and recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.978 - 0.0018 * min(i, 75)

        # Punctuation and standalone whitespace modestly weaken the sink.
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        if not surface:
            sink_mass -= 0.10
        elif all(not c.isalnum() for c in surface):
            sink_mass -= 0.05

        sink_mass = np.clip(sink_mass, 0.70, 0.98)

        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 4.0)
        recent /= recent.sum()
        residual = 0.60 * recent + 0.40 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L5H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local-attention exception in dialogue and after heavily
    fragmented nouns; otherwise retain the original diffuse residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Restrict the exception to the two structures most poorly modeled.
    dialogue = any(c in sentence for c in ('"', '“', '”'))
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    fragmented_ends = {
        indices[-1]
        for word, indices in zip(doc, inverse)
        if word.pos_ in ("NOUN", "PROPN") and len(indices) >= 3
    }
    local_start = min(fragmented_ends) if fragmented_ends else n

    for i in range(1, n):
        sink_mass = 0.81 + 0.085 * np.exp(-i / 9.0)
        sink_mass -= 0.0005 * i

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.045
            elif word.pos_ == "ADJ":
                sink_mass += 0.035
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.035
            elif word.pos_ == "PRON":
                sink_mass -= 0.015
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.065

        if i == 1:
            sink_mass = 0.935

        sink_mass = np.clip(sink_mass, 0.65, 0.95)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 12.0)
            / np.exp(-distances / 12.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Transfer only BOS mass; leave the original residual and decay intact.
        if i > 1 and aligned and (dialogue or i >= local_start):
            pos = doc[aligned[0]].pos_
            extra_self = {
                "NOUN": 0.060, "PROPN": 0.045,
                "VERB": 0.085, "AUX": 0.065,
                "ADP": 0.130, "CCONJ": 0.190,
                "PRON": 0.100, "DET": 0.070,
                "PUNCT": 0.130,
            }.get(pos, 0.075)
            if i in fragmented_ends:
                extra_self = 0.200

            extra_previous = 0.0
            if alignment[i - 1]:
                previous_pos = doc[alignment[i - 1][0]].pos_
                if (
                    (pos == "PRON" and previous_pos in ("VERB", "AUX"))
                    or (pos == "DET" and previous_pos == "ADP")
                ):
                    extra_previous = 0.085

            scale = min(
                1.0,
                max(0.0, attention[i, 0] - 0.45)
                / (extra_self + extra_previous),
            )
            attention[i, 0] -= scale * (extra_self + extra_previous)
            attention[i, i] += scale * extra_self
            attention[i, i - 1] += scale * extra_previous

    return "bos_sink_with_local_exception", make_row_stochastic(attention)


def prog_L5H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for nominal/content tokens.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "content_modulated_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.956,
        "PROPN": 0.957,
        "ADJ": 0.906,
        "VERB": 0.855,
        "AUX": 0.770,
        "ADV": 0.815,
        "PRON": 0.815,
        "DET": 0.835,
        "ADP": 0.860,
        "PART": 0.800,
        "CCONJ": 0.710,
        "SCONJ": 0.745,
        "NUM": 0.880,
        "PUNCT": 0.795,
        "INTJ": 0.810,
        "SPACE": 0.815,
        "SYM": 0.820,
        "X": 0.835,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        mapped = alignment[i]
        sink = 0.830
        if mapped:
            scores = []
            for si in mapped:
                word = doc[si]
                score = sink_by_pos.get(word.pos_, 0.830)
                if word.ent_type_ and word.pos_ in ("NOUN", "PROPN"):
                    score += 0.008
                if word.pos_ == "VERB" and word.dep_ in ("xcomp", "pcomp"):
                    score += 0.035
                if word.pos_ == "ADJ" and word.dep_ in ("acomp", "attr"):
                    score += 0.015
                scores.append(score)
            sink = max(scores)

        if i == 1:
            sink = max(sink, 0.895)

        sink = float(np.clip(sink, 0.65, 0.985))
        distances = i - np.arange(1, i + 1)
        residual = 0.75 / i + 0.25 * np.exp(-distances / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "content_modulated_bos_sink", attention


def prog_L5H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the initial token.
    A small residual is spread causally, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        sink_mass = 0.94

        if i == 1:
            sink_mass = 0.97
        elif not surface:
            sink_mass = 0.97
        elif all(not c.isalnum() and not c.isspace() for c in surface):
            sink_mass = 0.96

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 5.0) / np.exp(-distances / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_attention_sink", attention


def prog_L5H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position-dependent dilution.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = np.clip(0.985 - 0.0005 * (i - 1), 0.93, 0.99)

        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 6.0)
        recent /= recent.sum()
        residual = 0.75 / i + 0.25 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L5H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak, diffuse causal leakage.
    Sink dominance decreases mildly as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 1.0 / (1.0 + 0.014 + 0.007 * np.sqrt(i))

        # The examples support a strong sink, not a specific linguistic target
        # for the small remaining mass.
        distances = i - np.arange(1, i + 1)
        leakage = 0.8 / i + 0.2 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * leakage

    return "bos_sink_with_diffuse_leakage", attention


def prog_L5H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent leakage.
    Linguistic features weakly modulate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.955 - 0.00065 * i

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.015
            elif word.pos_ == "PRON":
                sink_mass += 0.008
            elif word.pos_ in ("ADJ", "ADV", "ADP", "CCONJ", "SCONJ"):
                sink_mass -= 0.008

        if i == 1:
            sink_mass = 0.980

        sink_mass = np.clip(sink_mass, 0.85, 0.99)

        # No non-BOS destination is supported strongly by the examples.
        # Spread the small residual broadly, with a weak recency preference.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_leakage", attention


def prog_L5H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token.
    A small, diffuse causal background grows slightly beyond the opening tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            sink_mass = 0.92 + 0.055 * np.exp(-(i - 1) / 3.0)
            attention[i, 0] = sink_mass
            attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_sink_with_diffuse_causal_background", attention


def prog_L5H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak background; quoted clauses add sparse syntactic links.
    Fragmented non-ASCII delimiters additionally attend to their preceding pieces.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_quote_links", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        recency = np.exp((positions - i) / 4.0)
        recency /= recency.sum()

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = 0.00055 + 0.014 * recency

    attention = make_row_stochastic(attention)

    # Detect fragmented non-ASCII delimiters without naming their characters.
    fragments = [
        bool(t.lstrip("▁"))
        and all(not c.isascii() for c in t.lstrip("▁"))
        for t in tokens
    ]
    broken_delimiter = [
        i for i in range(3, n)
        if fragments[i - 2] and fragments[i - 1] and fragments[i]
    ]
    quoted = any(c in sentence for c in ('"', "“", "”", "«", "»"))

    if quoted or broken_delimiter:
        doc = spacy_parse(sentence)
        mapping = align_tokens_to_spacy(sentence, tokens, tokenizer)
        inverse = [[] for _ in doc]
        for ti, sids in enumerate(mapping):
            for si in sids:
                inverse[si].append(ti)

        for i in range(1, n):
            additions = {}
            for si in mapping[i]:
                word = doc[si]
                head = word.head

                # Causal grammatical governors, especially auxiliaries and
                # reporting predicates, become slightly stronger in dialogue.
                if head.i != si and head.pos_ in ("VERB", "AUX"):
                    prior = [j for j in inverse[head.i] if 0 < j < i]
                    if prior:
                        j = prior[-1]
                        additions[j] = max(additions.get(j, 0.0), 0.014)

                if word.pos_ == "VERB":
                    for child in word.children:
                        if child.dep_ in ("aux", "auxpass"):
                            prior = [j for j in inverse[child.i] if 0 < j < i]
                            if prior:
                                j = prior[-1]
                                additions[j] = max(
                                    additions.get(j, 0.0), 0.020
                                )

            if i in broken_delimiter:
                additions[i - 1] = additions.get(i - 1, 0.0) + 0.165
                additions[i - 2] = additions.get(i - 2, 0.0) + 0.055

            # Transfer probability from BOS only: preserve baseline self
            # attention and every edge not explicitly selected above.
            total = sum(additions.values())
            if total > 0:
                scale = min(1.0, attention[i, 0] / total)
                for j, mass in additions.items():
                    delta = scale * mass
                    attention[i, j] += delta
                    attention[i, 0] -= delta

    return "bos_sink_with_quote_links", attention


def prog_L5H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with small diffuse causal leakage and a weak recency bias."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_causal_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        leakage = 1.0 + 2.0 * np.exp(-(i - positions) / 3.0)
        leakage[-1] += 7.0

        attention[i, 0] = 1400.0
        attention[i, 1:i + 1] = leakage
        attention[i, :i + 1] /= attention[i, :i + 1].sum()

    return "bos_sink_with_causal_leakage", attention


def prog_L5H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: almost all mass goes to the initial token.
    A small, weakly recency-biased causal remainder grows with context length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = np.clip(0.98 - 0.008 * np.log1p(i), 0.94, 0.98)
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 24.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L5H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized attention to quotation boundaries and their encoding fragments.
    Outside these boundaries, preserve the original distribution exactly.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 4.0)
        residual /= residual.sum()
        residual = 0.7 * residual + 0.3 / i

        attention[i, 0] = 0.975
        attention[i, 1:i + 1] = 0.025 * residual

    # Transfer only BOS mass to earlier boundary tokens; never change self-attention.
    clean = [t.lstrip("▁Ġ") for t in tokens]
    quotes = '"“”'
    encoded_quote = "“".encode("utf-8").decode("cp1252")
    corrupted_quotes = encoded_quote[:2] in sentence

    for i in range(1, n):
        current = clean[i]
        previous = clean[i - 1]
        additions = []

        if corrupted_quotes and current and current in encoded_quote:
            if current == encoded_quote[-1]:
                # The final fragment often attends past the intervening fragments.
                additions = [(i - 3, 0.37), (i - 2, 0.115),
                             (i - 1, 0.055), (i - 4, 0.085)]
            elif current == encoded_quote[1]:
                additions = [(i - 1, 0.14), (i - 2, 0.06)]
            else:
                additions = [(i - 1, 0.12), (i - 2, 0.035)]

        elif corrupted_quotes and previous and previous in encoded_quote:
            additions = [(i - 1, 0.25), (i - 2, 0.045),
                         (i - 3, 0.035)]

        elif current in quotes and current:
            if previous == "" and i > 2:
                additions = [(i - 1, 0.073), (i - 2, 0.145)]
            elif previous and previous[-1] in ",:;!?.":
                additions = [(i - 1, 0.205), (i - 2, 0.065),
                             (i - 3, 0.020)]

        elif current == "" and previous and any(q in previous for q in quotes):
            additions = [(i - 1, 0.115), (i - 2, 0.025)]

        elif previous == "" and i > 2 and any(q in clean[i - 2] for q in quotes):
            additions = [(i - 1, 0.18), (i - 2, 0.05)]

        elif previous and previous in quotes:
            additions = [(i - 1, 0.040), (i - 2, 0.025)]

        elif previous and any(q in previous for q in quotes):
            additions = [(i - 1, 0.035), (i - 2, 0.010)]

        for j, mass in additions:
            if 0 < j < i:
                attention[i, 0] -= mass
                attention[i, j] += mass

    return "bos_sink_with_quote_boundary_residual", attention


def prog_L5H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a short-lived comma-boundary anchor.
    After a comma, transfer a little BOS mass to that boundary, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        sink_mass = 0.985 if i == 1 else 0.96
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Only lexical queries shortly after a comma receive the correction.
        # Transfer mass directly: all other edges, including self, stay intact.
        if any(c.isalnum() for c in tokens[i]):
            for j in range(i - 1, max(0, i - 5), -1):
                if tokens[j].lstrip("▁Ġ").strip() == ",":
                    extra = 0.12 * np.exp(-(i - j - 1) / 1.6)
                    attention[i, 0] -= extra
                    attention[i, j] += extra
                    break

    return "bos_sink_comma_anchor", attention


def prog_L5H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token sink, with local anchors at quotation and whitespace boundaries.
    Boundary attention is transferred from the sink without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.91
        aligned = alignment[i]
        pos = ""

        if aligned:
            word = doc[aligned[-1]]
            pos = word.pos_

            if pos == "PUNCT":
                sink_mass = 0.95
            elif pos in ("ADP", "SCONJ", "CCONJ", "PART"):
                sink_mass = 0.945
            elif pos == "VERB":
                sink_mass = 0.935
            elif pos == "ADV":
                sink_mass = 0.93
            elif pos == "AUX":
                sink_mass = 0.905
            elif pos in ("NOUN", "PROPN", "ADJ", "NUM"):
                sink_mass = 0.885
            elif pos in ("DET", "PRON"):
                sink_mass = 0.875

        # Punctuation can occupy only part of a model token.
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if surface and all(not c.isalnum() for c in surface):
            sink_mass = 0.955

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special case: boundary tokens act as temporary, local attention sinks.
        # Change only the BOS edge and the selected preceding boundary edge.
        if i > 1:
            previous = tokens[i - 1].replace("▁", "").replace("Ġ", "").strip()
            target = None

            if not previous:
                # Explicit whitespace after a sentence boundary is a strong anchor.
                target = 0.46 if pos == "PUNCT" else 0.62
            elif previous in ('"', "“", "‘"):
                target = 0.36 if pos in ("AUX", "PRON", "DET") else 0.19
            elif (
                surface
                and pos != "PUNCT"
                and any(c in previous for c in ('"', "”", "’"))
                and any(c in previous for c in ".!?")
            ):
                target = 0.27
            elif not surface and any(c in previous for c in ".!?"):
                target = 0.12
            elif surface in ('"', "“", "‘") and previous in (",", ":", ";"):
                target = 0.065

            if target is not None:
                transfer = min(
                    attention[i, 0],
                    max(0.0, target - attention[i, i - 1]),
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "first_token_sink_with_boundary_anchors", attention


def prog_L5H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with lexical modulation and a local clause-ending exception.
    Boundary punctuation and particle-following modifiers draw extra mass from BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_boundary_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.91
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            pos = word.pos_

            if pos == "PROPN":
                sink_mass = 0.95
            elif pos == "NOUN":
                sink_mass = 0.94
            elif pos in ("DET", "PRON", "PART"):
                sink_mass = 0.925
            elif pos == "ADJ":
                sink_mass = 0.915
            elif pos in ("VERB", "AUX"):
                sink_mass = 0.895
            elif pos in ("ADP", "ADV"):
                sink_mass = 0.885
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass = 0.865
            elif pos == "PUNCT":
                sink_mass = 0.855

            if word.ent_type_:
                sink_mass += 0.005
            if word.is_punct and i == n - 1:
                sink_mass = 0.93

        # Noninitial pieces of lexical words also strongly favor the sink.
        if i > 1 and aligned and alignment[i - 1]:
            if aligned[-1] == alignment[i - 1][-1]:
                sink_mass = min(0.96, sink_mass + 0.01)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.25 + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Transfer only BOS mass: preserve self-attention and the default decay.
        if aligned:
            j = i - 1
            while j > 0 and alignment[j] and alignment[j][-1] == aligned[-1]:
                j -= 1

            if j > 0 and alignment[j]:
                previous = doc[alignment[j][-1]]
                target = j
                extra = 0.0

                if word.is_punct and word.text in (",", ";", ":", ".", "!", "?"):
                    if previous.pos_ in ("VERB", "AUX"):
                        extra = 0.23
                    elif word.text in (",", ";", ":"):
                        if previous.pos_ in ("ADV", "ADP"):
                            extra = 0.30
                        elif previous.pos_ == "PRON":
                            extra = 0.25
                        elif previous.pos_ in ("NOUN", "PROPN"):
                            extra = 0.06

                elif word.pos_ in ("ADV", "ADJ"):
                    if previous.dep_ == "prt":
                        extra = 0.24
                    elif previous.is_punct and previous.text == ",":
                        k = j - 1
                        if k > 0 and alignment[k]:
                            before_boundary = doc[alignment[k][-1]]
                            if before_boundary.pos_ in ("ADV", "ADP"):
                                target = k
                                extra = 0.20

                if extra > 0.0:
                    transfer = min(extra, attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i, target] += transfer

    return "bos_sink_with_local_boundary_exception", attention


def prog_L5H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local residual; quotation boundaries introduce a
    secondary sink, particularly for malformed encoded quotation marks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_quote_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Preserve the original default distribution exactly.
        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 4.0)
        residual /= residual.sum()

        attention[i, 0] = 0.97
        attention[i, 1:i + 1] = 0.03 * residual

    pieces = [t.replace("▁", " ").strip() for t in tokens]
    anchor = -1
    active = False
    malformed = False
    last_close = -1

    for i in range(1, n):
        text = pieces[i]

        # These sequences represent mojibake quotation punctuation, not words.
        encoded_open = "".join(pieces[max(1, i - 2):i + 1]).endswith(
            "\u00e2\u20ac\u0153"
        )
        encoded_close = (
            malformed and active and text == "\u00e2"
            and i + 1 < n and pieces[i + 1] == "\u20ac"
        )
        has_quote = any(mark in text for mark in ('"', "“", "”", "„"))

        if encoded_open:
            anchor, active, malformed = i, True, True
            continue

        closing = encoded_close
        if has_quote:
            if active:
                closing = True
            else:
                anchor, active, malformed = i, True, False
                continue

        if anchor < 1 or anchor >= i:
            continue

        if closing:
            active = False
            last_close = i

        # Move mass only from BOS to earlier tokens: the original diagonal,
        # local residual, and its decay rate remain untouched.
        extra = np.zeros(i, dtype=np.float64)
        if malformed:
            mass = 0.018
            if encoded_close:
                mass = 0.45
            elif i == last_close + 1 and text == "\u20ac":
                mass = 0.14
            elif text in ("'", "’"):
                mass = 0.08
            elif i == last_close + 2:
                mass = 0.045
            extra[anchor] += mass
        else:
            extra[anchor] += 0.10 if closing else 0.008
            if closing:
                if i - 1 > anchor:
                    extra[i - 1] += 0.025
                for j in range(i - 1, 0, -1):
                    if pieces[j] in (",", ";", ":"):
                        extra[j] += 0.04
                        break
            elif text in (".", ",", "!", "?", ";", ":"):
                extra[anchor] += 0.012
            elif i == last_close + 1:
                extra[anchor] += 0.018

        attention[i, 0] -= extra.sum()
        attention[i, :i] += extra

    return "bos_sink_with_quote_residual", attention


def prog_L5H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective local binding across subword continuations
    and tightly linked content-to-function transitions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_binding", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        sink = 0.91

        if not text or tokens[i] in tokenizer.all_special_tokens:
            sink = 0.97
        elif all(not c.isalnum() for c in text):
            sink = 0.965 if any(c in ".!?\"'“”‘’" for c in text) else 0.94
        elif words:
            if any(w.pos_ in ("VERB", "AUX") for w in words):
                sink += 0.025
            if any(w.pos_ in ("ADJ", "ADV", "PROPN") for w in words):
                sink += 0.02
            if any(w.dep_ in ("mark", "cc", "advcl", "ccomp") for w in words):
                sink += 0.02
            if any(w.is_sent_start for w in words):
                sink += 0.025

        sink = np.clip(sink, 0.86, 0.978)
        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Transfer only BOS mass: preserve self-attention and the default
        # residual exactly, except at explicitly selected earlier targets.
        if i > 1 and text and any(c.isalnum() for c in text):
            previous = [doc[k] for k in alignment[i - 1]
                        if 0 <= k < len(doc)]
            if len(words) == 1 and len(previous) == 1:
                word, prev = words[0], previous[0]
                boost = 0.0
                target = i - 1
                secondary = target

                if word.i == prev.i and word.pos_ in (
                    "NOUN", "PROPN", "ADJ", "VERB", "ADV"
                ):
                    start = i - 1
                    while start > 1 and word.i in alignment[start - 1]:
                        start -= 1
                    depth = i - start
                    boost = 0.07 if depth == 1 else 0.23
                    if depth >= 2:
                        target = start + 1
                elif word.head.i == prev.i:
                    if word.pos_ == "ADP" and prev.pos_ in ("ADJ", "ADV"):
                        boost = 0.17
                    elif (
                        word.pos_ == "ADP"
                        and prev.pos_ == "NOUN"
                        and i > 2
                        and prev.i in alignment[i - 2]
                    ):
                        boost = 0.24
                    elif (
                        word.pos_ == "PRON"
                        and word.dep_ in ("dobj", "obj")
                        and prev.pos_ == "VERB"
                    ):
                        boost = 0.10
                elif word.pos_ == "DET" and prev.pos_ == "VERB":
                    boost = 0.07

                if boost:
                    boost = min(boost, attention[i, 0])
                    attention[i, 0] -= boost
                    attention[i, target] += 0.75 * boost
                    attention[i, secondary] += 0.25 * boost

    return "bos_sink_with_local_binding", attention


def prog_L5H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant BOS sink with selective local phrase-onset attention.
    Content tokens, including subwords, draw extra mass from BOS to a preceding grammatical anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_local_phrase_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()

        sink_mass = 0.95
        if not text:
            sink_mass = 0.973
        elif all(not c.isalnum() and not c.isspace() for c in text):
            sink_mass = 0.974
        elif i == 1:
            sink_mass = 0.965

        # Preserve the original background, including its self-attention.
        distances = i - np.arange(1, i + 1)
        background = 0.8 / i + 0.2 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

        # Only matched phrase onsets receive an additional BOS-to-anchor edge.
        if text and any(c.isalnum() for c in text) and aligned[i]:
            sid = aligned[i][0]
            if sid > 0:
                current = doc[sid]
                anchor = doc[sid - 1]
                extra = 0.0

                if (
                    anchor.pos_ == "DET" or anchor.dep_ == "poss"
                ) and current.pos_ in ("NOUN", "PROPN", "ADJ"):
                    extra = 0.025
                    if anchor.is_sent_start:
                        extra += 0.025
                elif anchor.pos_ == "CCONJ" and current.pos_ == "VERB":
                    extra = 0.032
                elif anchor.pos_ == "AUX" and current.pos_ in ("ADJ", "ADV"):
                    extra = 0.035
                elif anchor.pos_ == "ADP" and current.pos_ in (
                    "NOUN", "PROPN", "ADJ", "VERB"
                ):
                    extra = 0.030

                destinations = [
                    j for j in inverse[anchor.i] if 0 < j < i
                ]
                if extra and destinations:
                    j = destinations[0]
                    attention[i, 0] -= extra
                    attention[i, j] += extra

    return "bos_sink_with_local_phrase_anchors", attention


def prog_L5H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with an additional, decaying opening-quotation sink.
    Quoted spans divert only BOS mass, preserving the original diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.92
            attention[i, 1:i + 1] = 0.08 / i

    # Quotation delimiters, including the final piece of a mojibake opener.
    clean = [t.lstrip("▁Ġ") for t in tokens]
    openers = ('"', "“", "„", "«", "œ")
    if any(t in openers for t in clean):
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        anchor = None
        closed_at = None

        for i in range(1, n):
            t = clean[i]
            if t in openers and (anchor is None or closed_at is not None):
                anchor = i
                closed_at = None
                continue

            if anchor is None:
                continue

            closing = any(c in t for c in ('"', "”", "»", "€"))
            if closing and closed_at is None:
                closed_at = i

            distance = i - anchor
            if distance <= 0:
                continue

            if closed_at is not None and i > closed_at:
                transfer = 0.075 * np.exp(-(i - closed_at - 1) / 12.0)
            else:
                transfer = 0.045 + 0.30 * np.exp(-(distance - 1) / 3.0)
                if clean[anchor] == "œ":
                    transfer *= 1.4

                positions = {doc[k].pos_ for k in aligned[i]}
                if "PRON" in positions:
                    transfer *= 1.25
                elif "VERB" in positions:
                    transfer *= 0.70
                elif "NOUN" in positions or "PROPN" in positions:
                    transfer *= 0.60

                if t and all(c in ",;:!?." for c in t):
                    transfer *= 1.5

            # Only these two off-diagonal entries change.
            transfer = min(float(transfer), attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, anchor] += transfer

    return "bos_sink_with_quotation_sink", attention


def prog_L5H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a secondary frame anchor for short, comma-delimited
    introductory noun/adpositional phrases; preserve the original residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_introductory_frame", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    # A short, verbless introductory frame can become a persistent second sink.
    frame = None
    frame_position = None
    frame_comma = None
    first_predicate = None
    for w in doc:
        if w.i > 5 or w.pos_ in ("VERB", "AUX"):
            break
        if w.text == ",":
            prefix = list(doc[:w.i])
            nouns = [p for p in prefix if p.pos_ in ("NOUN", "PROPN")]
            if (
                2 <= len(prefix) <= 5
                and prefix[0].pos_ in ("ADP", "NUM", "DET")
                and nouns
                and not any(p.is_punct for p in prefix)
            ):
                positions = [j for j in inverse[nouns[-1].i] if j > 0]
                if positions:
                    frame = nouns[-1]
                    frame_position = positions[-1]
                    frame_comma = w.i
                    first_predicate = next(
                        (p.i for p in doc[w.i + 1:]
                         if p.pos_ in ("VERB", "AUX")),
                        None,
                    )
            break

    attention[0, 0] = 1.0
    strengths = {
        "NOUN": 0.90, "PROPN": 0.94, "ADJ": 0.81,
        "VERB": 0.76, "AUX": 0.65, "PRON": 0.70,
        "DET": 0.80, "ADP": 0.81, "ADV": 0.72,
        "CCONJ": 0.84, "SCONJ": 0.70, "PART": 0.77,
        "PUNCT": 0.88, "NUM": 0.86, "SPACE": 0.93,
    }

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        sink = strengths.get(word.pos_, 0.85) if word is not None else 0.90
        if i == 1:
            sink = 0.95

        residual = np.exp(-np.arange(i - 1, -1, -1) / 5.0)
        residual[-1] *= 0.45

        if word is not None:
            # Fragments of a single lexical item usually retain sink behavior.
            if any(j < i for j in inverse[word.i]):
                sink = max(sink, 0.91)

            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if word.head.i != word.i and head_positions:
                residual[head_positions[-1] - 1] += 1.8

            # Quoted question openings can retrieve the introducing predicate.
            if word.tag_.startswith("W"):
                candidates = [
                    w for w in doc[:word.i]
                    if w.pos_ == "VERB"
                    and any(0 < j < i for j in inverse[w.i])
                ]
                if candidates:
                    predicate = candidates[-1]
                    intervening = list(doc[predicate.i + 1:word.i])
                    quoted = any(
                        w.is_punct and any(c in w.text for c in "\"“”«»")
                        for w in intervening
                    )
                    if quoted:
                        positions = [
                            j for j in inverse[predicate.i] if 0 < j < i
                        ]
                        residual[positions[-1] - 1] += 14.0
                        sink = 0.25

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Transfer only BOS mass: all original self/residual weights stay intact.
        if (
            frame is not None
            and word is not None
            and word.i >= frame_comma
            and frame_position < i
        ):
            fraction = {
                "VERB": 0.80, "AUX": 0.74, "PART": 0.80,
                "ADV": 0.55, "ADJ": 0.25, "PRON": 0.46,
                "DET": 0.25, "NOUN": 0.20, "PROPN": 0.20,
                "PUNCT": 0.25,
            }.get(word.pos_, 0.32)
            if word.pos_ == "DET" and word.i == frame_comma + 1:
                fraction = 0.60
            if first_predicate is not None:
                fraction *= np.exp(
                    -max(0, word.i - first_predicate - 1) / 7.0
                )
            moved = attention[i, 0] * fraction
            attention[i, 0] -= moved
            attention[i, frame_position] += moved

    return "bos_sink_with_introductory_frame", attention


def prog_L5H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token,
    with a small, diffuse residual over other causally available tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.965
            attention[i, 1:i + 1] = 0.035 / i

    return "bos_sink_with_diffuse_residual", attention


def prog_L5H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective residual attention to copular and subordinate-clause anchors.
    Only detected off-diagonal links borrow mass from BOS; self-attention is unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    doc = spacy_parse(sentence)
    aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)
    additions = [[] for _ in range(n)]

    for anchor in doc:
        complements = [
            c for c in anchor.children if c.dep_ in ("acomp", "attr")
        ]
        copular = (
            anchor.pos_ == "AUX" and bool(complements)
        ) or anchor.dep_ == "cop"
        subordinate = (
            anchor.pos_ == "SCONJ"
            and anchor.dep_ == "mark"
            and anchor.tag_ == "IN"
            and any(c.dep_ == "xcomp" for c in anchor.head.children)
        )
        if not (copular or subordinate):
            continue

        anchor_indices = [j for j in aligned[anchor.i] if j > 0]
        if not anchor_indices:
            continue
        j = anchor_indices[-1]

        predicate = anchor.head if anchor.dep_ == "cop" else anchor
        nominal = any(c.dep_ == "attr" for c in complements)
        if anchor.dep_ == "cop":
            nominal = predicate.pos_ in ("NOUN", "PROPN")

        subjects = [
            c for c in predicate.children
            if c.dep_ in ("nsubj", "nsubjpass") and c.pos_ == "PRON"
        ]

        for word in doc[anchor.i + 1:anchor.i + 8]:
            if word.is_punct:
                break
            if word.pos_ == "VERB" and word.dep_ not in ("xcomp", "conj"):
                break

            distance = word.i - anchor.i
            if subordinate:
                if distance > 4:
                    break
                mass = 0.27 * np.exp(-(distance - 1) / 1.5)
            elif nominal:
                mass = (
                    0.27 if word.pos_ in ("DET", "ADJ")
                    else 0.13
                ) * np.exp(-max(distance - 2, 0) / 4.0)
            else:
                intensified = any(
                    c.dep_ == "advmod"
                    for complement in complements
                    for c in complement.children
                )
                scale = 0.22 if intensified else 0.055
                mass = scale * np.exp(-(distance - 1) / 5.0)
                if word.pos_ == "CCONJ":
                    mass *= 0.6

            for i in aligned[word.i]:
                if i <= j:
                    continue
                additions[i].append((j, mass))
                if copular and nominal:
                    for subject in subjects:
                        indices = [
                            k for k in aligned[subject.i] if 0 < k < i
                        ]
                        if indices:
                            additions[i].append((indices[-1], 0.09))

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        sink_mass = 0.97 if i == 1 else 0.93
        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 6.0)
        recent /= recent.sum()

        residual = 0.5 / i + 0.5 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual
        attention[i, 0] = sink_mass

        if additions[i]:
            total = sum(mass for _, mass in additions[i])
            scale = min(1.0, 0.60 / total)
            for j, mass in additions[i]:
                transfer = scale * mass
                attention[i, j] += transfer
                attention[i, 0] -= transfer

    return "bos_sink_with_clause_anchors", attention


def prog_L5H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest initially and for nominal/subword tokens.
    Residual attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # A strong sink persists throughout the sequence; its initial advantage
        # decays without disappearing in longer contexts.
        sink = 0.79 + 0.18 * np.exp(-(i - 1) / 8.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink += 0.075
            elif pos == "ADJ":
                sink += 0.045
            elif pos in ("DET", "ADP"):
                sink += 0.025
            elif pos in ("VERB", "AUX"):
                sink -= 0.055
            elif pos in ("ADV", "CCONJ", "SCONJ", "PART"):
                sink -= 0.065

            if word.ent_type_:
                sink += 0.025

            # Multiple model pieces of one lexical item also favor the sink.
            if i > 1 and any(k in alignment[i - 1] for k in aligned):
                sink += 0.045

        if tokens[i].isspace() or tokens[i] == "▁":
            sink += 0.025

        if i == 1:
            sink = 0.985

        sink = np.clip(sink, 0.60, 0.985)
        attention[i, 0] = sink

        # The examples constrain the sink much more strongly than the remaining
        # edges, so use a smooth, low-commitment residual distribution.
        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_lexical_modulation", attention


def prog_L5H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink, with quoted-speech leakage to the reporting clause.
    Preserve the default local decay and self-attention outside that added path.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.96
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink_mass = 0.88
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "ADP", "NUM"):
                sink_mass = 0.975
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                sink_mass = 0.93
            elif word.pos_ in ("PRON", "DET", "PART"):
                sink_mass = 0.95

        attention[i, 0] = sink_mass
        positions = np.arange(1, i + 1)
        local_weights = np.exp(-(i - positions) / 3.0)
        local_weights /= local_weights.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * local_weights

    # Only dialogue activates the additional path. Apostrophes alone do not.
    clean = [t.lstrip("▁Ġ") for t in tokens]
    quote = [any(c in t for c in '"“”«»') for t in clean]
    # Also recognize fragmented, mojibake-encoded quotation punctuation.
    if "â€" in sentence:
        for i in range(1, n):
            if "€" in clean[i]:
                quote[i] = True
                if i > 1:
                    quote[i - 1] = True
                if i + 1 < n and not clean[i + 1].isalnum():
                    quote[i + 1] = True
                elif i + 1 < n and len(clean[i + 1]) == 1:
                    quote[i + 1] = True

    if any(quote):
        anchors = np.zeros(n, dtype=np.float64)
        inside = False
        following = 0

        for i in range(1, n):
            aligned = alignment[i]
            word = doc[aligned[0]] if aligned else None
            is_punct = bool(clean[i]) and (
                all(c in '.,;:!?\'"“”«»—–-()[]{}' for c in clean[i])
                or (word is not None and word.is_punct)
            )

            if quote[i]:
                if not quote[i - 1]:
                    if not inside:
                        anchors[:] = 0.0
                        # Find the nearest reporting-clause predicate.
                        verb = None
                        for j in range(i - 1, max(0, i - 15), -1):
                            if alignment[j]:
                                w = doc[alignment[j][0]]
                                if w.pos_ == "VERB":
                                    verb = w
                                    break
                        for j in range(max(1, i - 14), i):
                            if not alignment[j]:
                                continue
                            w = doc[alignment[j][0]]
                            if verb is not None and w.i == verb.i:
                                anchors[j] += 4.0
                            elif verb is not None and w.head.i == verb.i:
                                anchors[j] += (
                                    3.0 if w.dep_ == "advmod" else 1.0
                                )
                            if "," in clean[j]:
                                anchors[j] += 2.5
                        if anchors.sum() == 0.0:
                            anchors[max(1, i - 4):i] = 1.0
                    inside = not inside
                extra = 0.52
                following = 2
            elif not clean[i]:
                extra = 0.20
            elif following:
                extra = 0.25 if following == 2 else 0.07
                following -= 1
            elif is_punct:
                extra = 0.22 if any(c in clean[i] for c in ".!?") else 0.16
            else:
                continue

            # Transfer only BOS mass to strictly earlier non-BOS tokens.
            # The original diagonal and local-decay contribution stay intact.
            weights = anchors[:i].copy()
            weights[0] = 0.0
            if is_punct and not quote[i]:
                weights[1:] += 0.25
            total = weights.sum()
            if total > 0.0:
                moved = min(extra, attention[i, 0])
                attention[i, 0] -= moved
                attention[i, :i] += moved * weights / total

            # Closing quotation punctuation becomes an anchor for later rows.
            if quote[i] and not inside:
                anchors[i] += 2.0

    return "bos_sink_with_dialogue_anchors", attention


def prog_L5H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with an extra prefix-memory path for fronted prepositional phrases.
    Commas and clause restarts retrieve that prefix without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_fronted_phrase_memory", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Activate only for a short, sentence-initial prepositional frame.
    prefix_end = None
    prefix_comma = None
    if len(doc) and (
        doc[0].pos_ == "ADP"
        or (doc[0].pos_ == "ADV" and doc[0].dep_ in ("prep", "advmod"))
    ):
        for word in doc[1:5]:
            if word.pos_ in ("VERB", "AUX", "PRON") or word.is_punct:
                break
            if word.pos_ in ("NOUN", "PROPN"):
                prefix_end = word.i
                break
        if prefix_end is not None and prefix_end + 1 < len(doc):
            if doc[prefix_end + 1].text == ",":
                prefix_comma = prefix_end + 1

    for i in range(1, n):
        aligned = alignment[i]
        sink_mass = 0.955

        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink_mass = 0.890
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass = 0.972
            elif word.pos_ in ("VERB", "ADP", "ADV"):
                sink_mass = 0.960
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass = 0.925
            elif word.pos_ in ("PRON", "DET", "AUX", "PART"):
                sink_mass = 0.945

        # Mild dilution in longer contexts, without weakening the dominant sink.
        sink_mass -= 0.012 * (1.0 - np.exp(-i / 40.0))
        attention[i, 0] = sink_mass

        # The examples constrain the sink strongly, but not the residual edges.
        # Use a conservative mixture of diffuse and local causal attention.
        distances = i - np.arange(1, i + 1)
        local = np.exp(-distances / 3.0)
        local /= local.sum()
        residual = 0.65 * local + 0.35 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Transfer only BOS mass to earlier tokens; leave the original
        # diagonal and residual edges intact.
        if prefix_end is not None and aligned and i > 1:
            word = doc[aligned[0]]
            wi = word.i
            target = sink_mass
            comma_query = word.text == ","

            if wi <= prefix_end and word.pos_ == "DET":
                target = 0.78 if prefix_comma is not None else 0.81
            elif wi == prefix_end and prefix_comma is not None:
                target = 0.87
            elif comma_query:
                target = 0.28 if wi == prefix_comma else 0.40
            elif prefix_comma is not None and wi == prefix_comma + 1:
                target = 0.57
            elif prefix_comma is None and wi == prefix_end + 1:
                if word.pos_ == "PRON":
                    target = 0.51
            elif word.pos_ in ("AUX", "VERB") and wi <= prefix_end + 7:
                target = 0.76 if word.pos_ == "AUX" else 0.80

            previous_comma = None
            for k in range(wi - 1, prefix_end, -1):
                if doc[k].text == ",":
                    previous_comma = k
                    break
            if previous_comma is not None:
                gap = wi - previous_comma
                if word.pos_ == "PRON" and gap <= 2:
                    target = min(target, 0.68)
                elif word.pos_ == "VERB" and gap <= 3:
                    target = min(target, 0.86)

            if target < sink_mass:
                weights = np.zeros(i - 1, dtype=np.float64)
                for j in range(1, i):
                    if not alignment[j]:
                        continue
                    key = doc[alignment[j][0]]
                    if key.i <= prefix_end:
                        weights[j - 1] = 1.0
                        if key.i == prefix_end:
                            weights[j - 1] = 2.5 if prefix_comma is not None else 1.2
                    if key.text == ",":
                        weights[j - 1] += 0.6
                    if comma_query and wi != prefix_comma:
                        # Later commas summarize their own clause as well.
                        if previous_comma is None or key.i > previous_comma:
                            weights[j - 1] += 1.0
                            if key.pos_ == "VERB":
                                weights[j - 1] += 5.0
                    elif previous_comma is not None and wi - previous_comma <= 3:
                        if key.i == previous_comma:
                            weights[j - 1] += 3.0
                        elif key.i > previous_comma:
                            weights[j - 1] += 1.5

                total = weights.sum()
                if total > 0:
                    transfer = sink_mass - target
                    attention[i, 0] -= transfer
                    attention[i, 1:i] += transfer * weights / total

    return "bos_sink_with_fronted_phrase_memory", attention


def prog_L5H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with small POS-dependent variations and a weak
    causal recency/syntactic-head residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_indices in enumerate(alignment):
        for k in word_indices:
            inverse[k].append(i)

    sink_by_pos = {
        "PROPN": 0.95,
        "NOUN": 0.93,
        "VERB": 0.90,
        "ADJ": 0.89,
        "ADV": 0.88,
        "NUM": 0.91,
        "DET": 0.88,
        "ADP": 0.85,
        "PRON": 0.85,
        "AUX": 0.82,
        "CCONJ": 0.86,
        "SCONJ": 0.84,
        "PART": 0.86,
        "PUNCT": 0.81,
        "SPACE": 0.92,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        sink = sink_by_pos.get(word.pos_, 0.90) if word is not None else 0.90

        # A sharply preferred first position, not a content-matching head.
        residual = np.exp(-(i - np.arange(1, i + 1)) / 3.0)
        residual /= residual.sum()
        residual *= 0.75
        residual += 0.25 / i

        # Only weakly favor a syntactic governor that is already available.
        if word is not None and word.head.i != word.i:
            candidates = [j for j in inverse[word.head.i] if 0 < j <= i]
            if candidates:
                residual *= 0.85
                residual[candidates[-1] - 1] += 0.15

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_residual", make_row_stochastic(attention)


def prog_L5H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective leakage to infinitival and modal scaffolding.
    Complement spans redirect BOS mass to their introducing marker or verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_complement_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.955,
        "PROPN": 0.965,
        "PRON": 0.915,
        "DET": 0.935,
        "ADJ": 0.925,
        "VERB": 0.860,
        "AUX": 0.900,
        "ADV": 0.880,
        "ADP": 0.915,
        "PART": 0.870,
        "CCONJ": 0.900,
        "SCONJ": 0.890,
        "NUM": 0.950,
        "PUNCT": 0.935,
        "SPACE": 0.880,
        "INTJ": 0.930,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.920
        if alignment[i]:
            word = doc[alignment[i][0]]
            sink_mass = sink_by_pos.get(word.pos_, sink_mass)
            if word.ent_type_:
                sink_mass = max(sink_mass, 0.955)

        # The earliest query has an especially strong sink preference.
        if i == 1:
            sink_mass = max(sink_mass, 0.960)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.70 * np.exp(-(i - positions) / 3.0)
        residual += 0.30 / i
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Special case: nonfinite complements and modal predicates retain
    # attention on their introducer. Transfer only BOS mass; keep the
    # original diagonal, residual weights, and their decay unchanged.
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if ti > 0:
                word_tokens[wi].append(ti)

    events = []
    for word in doc:
        if word.pos_ not in ("VERB", "AUX") or not word_tokens[word.i]:
            continue
        markers = [
            child for child in word.children
            if child.dep_ in ("aux", "auxpass", "mark")
            and (child.pos_ == "PART" or child.tag_ == "MD")
            and word_tokens[child.i]
        ]
        scope = {child.i for child in word.subtree}
        for marker in markers:
            modal = marker.tag_ == "MD"
            strength = 0.30 if modal else 0.50
            if not modal:
                if word.head.pos_ in ("NOUN", "PROPN"):
                    strength = 0.40
                elif any(child.dep_ == "xcomp" for child in word.children):
                    strength = 0.64
            governor = word_tokens[word.head.i]
            events.append((
                word_tokens[marker.i][-1], scope,
                governor[-1] if governor else 0,
                strength, 0.60 if modal else 0.70,
                0.04 if modal else 0.12,
            ))

        # Bare verbal complements can introduce the same pattern without
        # an explicit marker; retain the parent's infinitival marker too.
        if not markers and word.dep_ == "xcomp" and word.head.pos_ == "VERB":
            parent_markers = [
                child for child in word.head.children
                if child.pos_ == "PART"
                and child.dep_ in ("aux", "mark")
                and word_tokens[child.i]
            ]
            if parent_markers:
                events.append((
                    word_tokens[word.head.i][-1], scope,
                    word_tokens[parent_markers[0].i][-1],
                    0.50, 0.70, 0.12,
                ))

    for i in range(1, n):
        if not alignment[i]:
            continue
        word = doc[alignment[i][0]]
        if word.pos_ == "PUNCT":
            continue
        active = [
            event for event in events
            if 0 < event[0] < i
            and i - event[0] <= 8
            and word.i in event[1]
        ]
        if not active:
            continue
        anchor, _, governor, strength, decay, support = max(
            active, key=lambda event: event[0]
        )
        distance = i - anchor - 1
        extra = strength * decay ** distance
        secondary = support * 0.80 ** distance
        if len(word_tokens[word.i]) > 1 and i == word_tokens[word.i][0]:
            extra *= 0.40
            secondary *= 0.40
        if not (0 < governor < i) or governor == anchor:
            secondary = 0.0
        scale = min(1.0, attention[i, 0] / (extra + secondary))
        attention[i, 0] -= scale * (extra + secondary)
        attention[i, anchor] += scale * extra
        if secondary:
            attention[i, governor] += scale * secondary

    return "bos_sink_with_complement_leakage", attention


def prog_L6H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with quoted speech creating temporary punctuation sinks.
    Transfer only BOS mass near quote boundaries, preserving baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = np.clip(0.965 - 0.0006 * (i - 1), 0.90, 0.965)
        positions = np.arange(1, i + 1)
        residual = 1.0 + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Recognize quotation punctuation, including common mojibake encodings.
    boundaries = []
    inside = False
    p = 0
    while p < len(sentence):
        if sentence.startswith("â€œ", p):
            boundaries.append((p + 2, True))
            inside = True
            p += 3
        elif sentence.startswith("â€", p):
            boundaries.append((p, False))
            inside = False
            p += 2
        elif sentence[p] in ('"', "“", "”"):
            opening = not inside if sentence[p] == '"' else sentence[p] == "“"
            boundaries.append((p, opening))
            inside = opening
            p += 1
        else:
            p += 1

    if not boundaries:
        return "bos_attention_sink", attention

    spans = _char_spans(sentence, tokenizer)
    events = []
    for position, opening in boundaries:
        matches = [
            j for j, (start, end) in enumerate(spans[:n])
            if j > 0 and start <= position < end
        ]
        if matches:
            events.append((matches[-1], opening))

    if not events:
        return "bos_attention_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    opening_anchor = None
    comma_anchor = None
    verb_anchor = None

    for k, (anchor, opening) in enumerate(events):
        if opening:
            opening_anchor = anchor
            comma_anchor = next(
                (j for j in range(anchor - 1, max(0, anchor - 4), -1)
                 if "," in tokens[j]),
                None,
            )
            verb_anchor = next(
                (j for j in range(anchor - 1, max(0, anchor - 10), -1)
                 if any(doc[s].pos_ == "VERB" for s in alignment[j])),
                None,
            )

        stop = events[k + 1][0] + 1 if k + 1 < len(events) else n
        for i in range(anchor + 1, stop):
            distance = i - anchor
            if opening:
                transfer = 0.09 + 0.40 * np.exp(-(distance - 1) / 5.0)
                if any(doc[s].pos_ in ("PRON", "AUX") for s in alignment[i]):
                    transfer += 0.05
                targets = [
                    (anchor, 0.60),
                    (comma_anchor, 0.18),
                    (verb_anchor, 0.15),
                    (anchor + 1, 0.07),
                ]
            else:
                transfer = 0.07 + 0.24 * np.exp(-(distance - 1) / 5.0)
                targets = [
                    (anchor, 0.67),
                    (opening_anchor, 0.18),
                    (comma_anchor, 0.08),
                    (verb_anchor, 0.07),
                ]

            # Only change BOS and strictly earlier keys; never change the diagonal.
            targets = [(j, w) for j, w in targets if j is not None and 0 < j < i]
            total = sum(w for _, w in targets)
            if total:
                transfer = min(transfer, attention[i, 0])
                attention[i, 0] -= transfer
                for j, weight in targets:
                    attention[i, j] += transfer * weight / total

    return "bos_sink_with_quote_boundaries", attention


def prog_L6H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a position-dependent strength.
    Clause boundaries and function words strengthen the sink; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i] if i < len(alignment) else []
        word = doc[aligned[0]] if aligned else None

        # Early positions have little competition for the attention sink.
        sink = 0.54 + 0.29 * np.exp(-(i - 1) / 12.0)

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("CCONJ", "SCONJ"):
                sink += 0.17
            elif pos == "PUNCT":
                sink += 0.14
            elif pos in ("DET", "ADP", "PART"):
                sink += 0.07
            elif pos == "PRON":
                sink += 0.04
            elif pos in ("NOUN", "PROPN", "VERB", "ADJ"):
                sink -= 0.05

            if dep in ("cc", "mark", "punct"):
                sink += 0.03

            if i == 1:
                sink += 0.08
        else:
            # Whitespace and special-token fragments often behave as sinks.
            if tokens[i] in tokenizer.all_special_tokens:
                sink += 0.12
            elif not tokens[i].replace("▁", "").replace("Ġ", "").strip():
                sink += 0.06

        sink = float(np.clip(sink, 0.32, 0.96))
        attention[i, 0] = sink

        # No non-BOS target is evidenced consistently, so use a broad,
        # weak recency prior rather than a strong syntactic routing rule.
        positions = np.arange(1, i + 1)
        residual = 0.45 + 0.55 * np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_gating", attention


def prog_L6H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a targeted nominal-subject link at predicates and auxiliaries.
    Preserve the diffuse baseline and self-attention outside these links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_nominal_subject_links", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.90
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = 0.10 * residual / residual.sum()

    # Transfer only BOS mass to an explicit, preceding nominal subject.
    if n > 2:
        doc = spacy_parse(sentence)
        alignment = align_spacy_to_tokens(sentence, tokens, tokenizer)

        for subject in doc:
            if subject.dep_ not in ("nsubj", "nsubjpass"):
                continue
            if subject.pos_ not in ("NOUN", "PROPN"):
                continue

            subject_tokens = [j for j in alignment[subject.i] if 0 < j < n]
            if not subject_tokens:
                continue
            j = subject_tokens[-1]
            predicate = subject.head
            if predicate.pos_ not in ("VERB", "AUX", "ADJ"):
                continue

            children = list(predicate.children)
            has_auxiliary = any(
                child.dep_ in ("aux", "auxpass", "cop")
                for child in children
            )
            targets = [predicate] + [
                child for child in children
                if child.dep_ in ("aux", "auxpass", "cop", "acomp")
            ]

            for target in targets:
                strong_link = (
                    target.pos_ == "AUX"
                    or (
                        target.i == predicate.i
                        and predicate.pos_ == "VERB"
                        and has_auxiliary
                    )
                )
                desired = 0.30 if strong_link else 0.12
                if len(subject_tokens) > 1:
                    desired = min(desired, 0.12)

                for i in alignment[target.i]:
                    if not (j < i < n):
                        continue
                    transfer = min(
                        max(0.0, desired - attention[i, j]),
                        attention[i, 0],
                    )
                    attention[i, 0] -= transfer
                    attention[i, j] += transfer

    return "bos_sink_with_nominal_subject_links", attention


def prog_L6H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token.
    Weak causal background attention gradually dilutes the sink with position.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            positions = np.arange(1, i + 1)
            attention[i, 1:i + 1] = (
                0.0025 + 0.001 * np.exp(-(i - positions) / 4.0)
            )

    return "bos_attention_sink", make_row_stochastic(attention)


def prog_L6H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly declining strength and weak lexical-role modulation.
    Residual attention is diffuse, with a modest preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.91 - 0.060 * np.log(float(i))

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ in ("VERB", "AUX", "PRON"):
                sink_mass += 0.010
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.025
            elif word.is_punct:
                sink_mass -= 0.040

        sink_mass = float(np.clip(sink_mass, 0.50, 0.95))
        if i == 1:
            sink_mass = 0.91

        # Keep the non-sink component broad rather than inventing
        # unsupported, sharply focused syntactic edges.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_recency", attention


def prog_L6H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and at discourse boundaries.
    Content-bearing tokens divert more mass into a diffuse causal background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        piece = tokens[i]
        clean = piece.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[0]]
            for k in aligned:
                if not doc[k].is_space and not doc[k].is_punct:
                    word = doc[k]
                    break

        # A position-dependent sink prior, with a slow late-context decline.
        sink = 0.70 + 0.25 * np.exp(-(i - 1) / 4.0)
        sink -= 0.002 * max(i - 12, 0)

        whitespace = not clean
        punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )

        if whitespace:
            sink = 0.96
        elif punctuation:
            sink += 0.16
        elif word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos == "NOUN":
                sink -= 0.15
            elif pos == "PROPN":
                sink += 0.13
            elif pos in ("ADJ", "ADV"):
                sink -= 0.07
            elif pos == "VERB":
                sink -= 0.08
            elif pos in ("CCONJ", "SCONJ"):
                sink += 0.14
            elif pos == "AUX":
                sink += 0.07

            if dep in ("ROOT", "conj") and pos in ("VERB", "AUX"):
                sink += 0.16
            elif dep in ("dobj", "obj", "pobj", "attr", "xcomp"):
                sink -= 0.08
            elif dep in ("nsubj", "nsubjpass", "csubj"):
                sink += 0.05

            if word.is_sent_start:
                sink += 0.12

        if i == 1:
            sink = 0.99

        sink = float(np.clip(sink, 0.25, 0.985 if i > 1 else 0.995))
        attention[i, 0] = sink

        # No non-BOS target is supported consistently by the observed edges.
        # Use a diffuse residual with only a mild recency preference.
        distances = i - np.arange(1, i + 1)
        background = 0.7 + 0.3 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink) * background / background.sum()
        )

    return "bos_sink_with_boundary_gating", attention


def prog_L6H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a diffuse causal tail.
    Linguistic and word-boundary features weakly modulate the dominant sink mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_diffuse_tail", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.75 + 0.07 * np.exp(-(i - 1) / 3.0)

        if aligned[i]:
            word_index = aligned[i][0]
            word = doc[word_index]
            if word.pos_ in ("DET", "ADJ", "PROPN"):
                sink_mass += 0.035
            elif word.pos_ in ("AUX", "SCONJ"):
                sink_mass -= 0.025

            # A continuation piece has already seen part of its own word.
            if i > 1 and word_index in aligned[i - 1]:
                sink_mass -= 0.045

        if tokens[i].isspace():
            sink_mass += 0.025
        if tokens[i] in special_tokens:
            sink_mass = 0.80
        if i == 1:
            sink_mass = 0.88

        sink_mass = float(np.clip(sink_mass, 0.60, 0.92))

        # Spread the unobserved residual conservatively, with mild recency.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        tail = 0.55 / i + 0.45 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * tail

    return "bos_sink_diffuse_tail", make_row_stochastic(attention)


def prog_L6H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for function words and clause connectors.
    A small residual is distributed over causal context with mild recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            pos = word.pos_

            if pos in ("CCONJ", "SCONJ", "ADV", "PART"):
                sink_mass = 0.955
            elif pos in ("ADP", "DET", "AUX"):
                sink_mass = 0.94
            elif pos == "VERB":
                sink_mass = 0.93
            elif pos == "ADJ":
                sink_mass = 0.91
            elif pos == "PRON":
                sink_mass = 0.89
            elif pos == "NOUN":
                sink_mass = 0.85
            elif pos == "PROPN":
                sink_mass = 0.81
            elif pos == "PUNCT":
                sink_mass = 0.925

            if word.dep_ in ("cc", "mark", "advmod"):
                sink_mass = min(0.975, sink_mass + 0.015)
        elif tokens[i].isspace():
            sink_mass = 0.89

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_linguistic_gating", attention


def prog_L6H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and sentence-onset reinforcement.
    Residual attention is diffuse and weakly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_onset_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.79 + 0.18 * np.exp(-(i - 1) / 5.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            onset_distance = word.i - word.sent.start
            if word.sent.start > 0:
                sink += 0.10 * np.exp(-onset_distance / 3.0)

            if word.pos_ == "PROPN":
                sink += 0.035
            elif word.dep_ in ("nsubj", "nsubjpass"):
                sink += 0.015

            if word.is_punct:
                sink -= 0.055
                if word.is_sent_end:
                    sink -= 0.065
            elif word.is_space:
                sink -= 0.07

        sink = float(np.clip(sink, 0.60, 0.985))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * np.exp(-distances / 5.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_onset_bias", attention


def prog_L6H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with linguistic gating; dialogue boundaries divert BOS mass
    toward earlier punctuation and clause anchors without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Restrict the additional path to quotation or multi-sentence contexts.
    surfaces = [t.lstrip("▁Ġ") for t in tokens]
    quote_marks = '"“”„‟«»'
    quoted = [any(c in quote_marks for c in t) for t in surfaces]
    terminal = [any(c in ".!?" for c in t) for t in surfaces]
    dialogue = any(quoted) or sum(terminal) > 1
    anchor_weights = np.zeros(n, dtype=np.float64)
    last_terminal = None
    last_quote = None

    for i in range(1, n):
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[0]]
            for k in aligned:
                if doc[k].pos_ not in ("PUNCT", "SPACE"):
                    word = doc[k]
                    break

        sink_mass = 0.92
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink_mass = 0.965
            elif pos == "ADJ":
                sink_mass = 0.96
            elif pos == "VERB":
                sink_mass = 0.935
            elif pos in ("DET", "ADP", "NUM"):
                sink_mass = 0.925
            elif pos in ("PRON", "AUX", "PART"):
                sink_mass = 0.90
            elif pos in ("ADV", "CCONJ", "SCONJ"):
                sink_mass = 0.875
            elif pos == "PUNCT":
                sink_mass = 0.76
            elif pos == "SPACE":
                sink_mass = 0.80

            if word.dep_ in ("dobj", "obj", "pobj", "amod", "attr", "acomp"):
                sink_mass += 0.008

        # Early tokens exhibit particularly strong sink behavior.
        if i <= 2 and word is not None and word.pos_ != "PUNCT":
            sink_mass = max(sink_mass, 0.955)

        sink_mass = float(np.clip(sink_mass, 0.65, 0.985))
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Add only BOS-to-history transfers: the original diagonal and
        # original recency component are left exactly intact.
        if dialogue and i > 1:
            target = sink_mass
            if terminal[i]:
                if quoted[i]:
                    target = 0.34 if last_terminal is None else 0.27
                elif last_terminal is not None:
                    target = float(np.clip(0.68 - 0.008 * i, 0.30, 0.55))
                else:
                    target = 0.58
            elif not surfaces[i].strip() and last_terminal is not None:
                target = 0.36
            elif quoted[i]:
                target = float(np.clip(0.88 - 0.015 * i, 0.50, 0.83))
            elif surfaces[i] in ("'", "’") and last_quote is not None:
                target = 0.69
            elif last_terminal is not None:
                distance = i - last_terminal
                if distance <= 6:
                    strength = 0.30
                    if word is not None and word.pos_ in ("VERB", "PROPN"):
                        strength = 0.40
                    # Continuation pieces recover their strong BOS preference.
                    if alignment[i] and alignment[i - 1]:
                        if alignment[i][0] == alignment[i - 1][0]:
                            strength *= 0.5
                    target -= strength * np.exp(-(distance - 1) / 4.0)

            transfer = max(0.0, sink_mass - target)
            if transfer > 0.0:
                weights = anchor_weights[1:i].copy()
                if terminal[i] and quoted[i] and last_quote is not None:
                    weights[last_quote - 1] *= 2.0
                total = weights.sum()
                if total > 0.0:
                    attention[i, 0] -= transfer
                    attention[i, 1:i] += transfer * weights / total

        # Causal anchor memory, available only to subsequent rows.
        anchor_weights[i] = 0.5
        if word is not None and word.pos_ in (
            "PRON", "AUX", "VERB", "ADV", "ADP", "CCONJ", "SCONJ"
        ):
            anchor_weights[i] = 2.0
        if surfaces[i] in (",", ";", ":"):
            anchor_weights[i] = 4.0
        if quoted[i]:
            anchor_weights[i] = 8.0
            if not terminal[i]:
                last_quote = i
        if terminal[i]:
            anchor_weights[i] = 10.0
            last_terminal = i

    return "bos_sink_with_dialogue_boundaries", attention


def prog_L6H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with positional dilution; residual attention favors the sentence
    opener and preceding punctuation boundaries without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    last_boundary = None

    for i in range(1, n):
        clean = tokens[i].lstrip("▁Ġ")
        aligned = alignment[i]
        is_punctuation = (
            bool(aligned)
            and all(doc[k].pos_ == "PUNCT" for k in aligned)
        )

        # Aggregate non-BOS strength increases as more keys become available.
        competing_mass = 0.020 + 0.008 * i

        if clean and clean.isspace():
            competing_mass = 0.040 + 0.0023 * i
        elif not clean:
            competing_mass = 0.040 + 0.0023 * i
        elif clean in ("'", "’"):
            competing_mass = 0.047 + 0.0002 * i
        elif any(c in clean for c in ".!?"):
            competing_mass = 0.022 + 0.0020 * i
        elif clean in (",", ";", ":"):
            competing_mass = 0.028 + 0.0026 * i
        elif is_punctuation:
            competing_mass *= 1.10

        sink_mass = 1.0 / (1.0 + competing_mass)

        # Preserve the original residual distribution as the default.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-(i - positions) / 16.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Concentrate only existing off-diagonal residual mass at anchors.
        # BOS and the diagonal remain exactly as in the original program.
        if i > 2 and alignment[1] and any(
            doc[k].pos_ not in ("PUNCT", "SPACE") for k in alignment[1]
        ):
            anchors = [1]
            targets = [0.035]
            if last_boundary is not None and 1 < last_boundary < i:
                anchors.append(last_boundary)
                targets.append(0.030)

            donors = np.arange(2, i)
            donors = donors[~np.isin(donors, anchors)]
            deficits = np.maximum(
                np.asarray(targets) - attention[i, anchors], 0.0
            )
            available = attention[i, donors].sum()
            needed = deficits.sum()
            if available > 0.0 and needed > 0.0:
                moved = min(0.65 * available, needed)
                attention[i, donors] *= 1.0 - moved / available
                attention[i, anchors] += moved * deficits / needed

        if is_punctuation and any(c in clean for c in ",;:.!?"):
            last_boundary = i

    return "bos_sink_with_boundary_anchors", attention


def prog_L6H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all mass targets the initial token.
    A small residual follows a diffuse causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.95 + 0.025 * np.exp(-(i - 1) / 8.0)
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-(i - positions) / 6.0)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_diffuse_residual", attention


def prog_L6H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, strongest early and on nominal/adjectival tokens.
    The remaining attention is weak, diffuse, and mildly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = None
        if aligned:
            # Prefer lexical material when a subtoken also overlaps whitespace.
            candidates = [doc[k] for k in aligned if not doc[k].is_space]
            if candidates:
                word = candidates[0]

        sink_mass = 0.89 - 0.0018 * i
        sink_mass += 0.025 * np.exp(-(i - 1) / 8.0)

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.075
            elif word.pos_ == "ADJ":
                sink_mass += 0.055
            elif word.pos_ == "VERB":
                sink_mass += 0.005
            elif word.pos_ in ("PRON", "AUX"):
                sink_mass -= 0.065
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.055
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.13

            if word.is_space:
                sink_mass -= 0.12

        # The first non-BOS position is consistently almost entirely BOS-bound.
        if i == 1:
            sink_mass = 0.968

        sink_mass = float(np.clip(sink_mass, 0.55, 0.98))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.5 + np.exp(-distances / 5.0)
        background /= background.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_linguistic_modulation", attention


def prog_L6H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant beginning-of-sequence attention sink.
    Allow mild positional weakening and a small, recency-biased causal residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.98 - 0.055 * (1.0 - np.exp(-(i - 1) / 32.0))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L6H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at punctuation and discourse boundaries.
    Ordinary tokens retain a diffuse, mildly recency-biased causal component.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i]]
        pos = words[0].pos_ if words else ""
        dep = words[0].dep_ if words else ""

        # An early-position prior accounts for the particularly strong sink
        # preference at the beginning of a sequence.
        sink = 0.55 + 0.23 * np.exp(-max(i - 2, 0) / 4.0)

        if pos in ("VERB", "AUX"):
            sink += 0.035
        elif pos in ("DET", "ADP", "PRON"):
            sink += 0.015
        elif pos in ("CCONJ", "SCONJ"):
            sink += 0.12
        if dep in ("cc", "mark"):
            sink += 0.025

        previous = tokens[i - 1].replace("▁", " ").replace("Ġ", " ").strip()
        if previous and all(c in ",;:.!?" for c in previous):
            sink += 0.10

        if not text:
            sink = 0.91
        elif all(not c.isalnum() for c in text):
            if "." in text:
                sink = 0.918
            elif "," in text or ";" in text or ":" in text:
                sink = 0.84
            elif "'" in text or "’" in text:
                sink = 0.85
            elif "!" in text or "?" in text:
                sink = 0.84
            else:
                sink = 0.79

        if i == 1:
            sink = 0.94

        sink = float(np.clip(sink, 0.45, 0.97))
        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 10.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_boundary_modulated", attention


def prog_L6H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small diffuse causal remainder.
    Sink strength weakens slightly with position and at punctuation boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos_tags = {doc[k].pos_ for k in aligned}
        dependencies = {doc[k].dep_ for k in aligned}

        sink = 0.982 - 0.00065 * min(i, 70)

        if "PUNCT" in pos_tags:
            sink -= 0.065
        elif pos_tags.intersection({"PRON", "AUX"}):
            sink -= 0.012
        elif pos_tags.intersection({"NOUN", "PROPN", "ADJ", "ADP"}):
            sink += 0.006

        if dependencies.intersection({"cc", "mark", "advcl"}):
            sink -= 0.012

        sink = float(np.clip(sink, 0.82, 0.99))
        attention[i, 0] = sink

        # The examples constrain the sink much more than the residual edges.
        # Use a broad causal background with only a weak recency preference.
        distances = i - np.arange(1, i + 1)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_diffuse_residual", make_row_stochastic(attention)


def prog_L6H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local predecessor channel at syntactic boundaries.
    Transfer only BOS mass; preserve self-attention and the diffuse baseline.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_channel", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.935
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB"):
                sink_mass = 0.955
            elif word.pos_ in ("ADV", "PRON", "DET", "NUM"):
                sink_mass = 0.940
            elif word.pos_ in ("AUX", "PART"):
                sink_mass = 0.915
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ"):
                sink_mass = 0.890
            elif word.is_punct or word.is_space:
                sink_mass = 0.880

            if alignment[i - 1] and aligned[0] in alignment[i - 1]:
                sink_mass -= 0.020

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 5.0) / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Add a sparse local channel without rescaling any other edge.
        if i > 1 and aligned and alignment[i - 1]:
            word = doc[aligned[0]]
            previous = doc[alignment[i - 1][-1]]
            target = i - 1
            local_mass = 0.0
            same_word = aligned[0] in alignment[i - 1]

            if word.tag_ == "POS":
                # A split possessive may place an apostrophe between
                # the current piece and the preceding lexical token.
                if tokens[target] in ("'", "’") and target > 1:
                    target -= 1
                local_mass = 0.32
            elif same_word:
                if word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB", "ADV"):
                    local_mass = 0.07
            elif word.is_punct and not previous.is_punct:
                if "," in tokens[i]:
                    local_mass = 0.20
                    if i <= 4 or previous.pos_ == "PROPN":
                        local_mass = 0.42
                elif any(mark in tokens[i] for mark in (".", "!", "?")):
                    local_mass = 0.11
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "AUX", "PART"):
                if previous.pos_ in ("NOUN", "PROPN", "ADJ", "VERB", "ADV", "PRON"):
                    local_mass = 0.15
                    if word.pos_ == "CCONJ":
                        local_mass = 0.24
            elif word.pos_ == "VERB" and previous.dep_ in (
                "nsubj", "nsubjpass", "csubj"
            ):
                local_mass = 0.15
                if previous.pos_ == "PROPN":
                    local_mass = 0.35

            if local_mass > attention[i, target]:
                transfer = min(
                    local_mass - attention[i, target],
                    attention[i, 0],
                )
                attention[i, 0] -= transfer
                attention[i, target] += transfer

    return "bos_sink_with_boundary_channel", make_row_stochastic(attention)


def prog_L6H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, with small POS-dependent variations in sink strength.
    The weak residual attention is modeled as a diffuse causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.950
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos == "DET":
                sink_mass = 0.980
            elif word.dep_ == "poss":
                sink_mass = 0.978
            elif pos == "ADP":
                sink_mass = 0.963
            elif pos in ("PRON", "AUX"):
                sink_mass = 0.957
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass = 0.958
            elif pos == "PUNCT":
                sink_mass = 0.970
                if word.text in ('"', "“", "”", "«", "»"):
                    sink_mass = 0.928
            elif pos in ("ADJ", "ADV"):
                sink_mass = 0.953
            elif pos in ("NOUN", "PROPN", "VERB"):
                sink_mass = 0.943

            # Later pieces of a split word have slightly weaker sink affinity.
            if i > 1 and any(k in alignment[i - 1] for k in aligned):
                sink_mass -= 0.012

        if tokens[i].isspace() or tokens[i] == "▁":
            sink_mass = 0.925

        # The first content position has particularly stable sink attention.
        if i == 1:
            sink_mass = 0.985

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-(i - positions) / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_pos_modulation", attention


def prog_L6H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant first-token/BOS attention sink, mildly modulated by query POS.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.89
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_
            if pos in ("VERB", "AUX"):
                sink_mass = 0.935
            elif pos in ("NOUN", "PROPN"):
                sink_mass = 0.80
            elif pos in ("PRON", "DET", "ADV"):
                sink_mass = 0.91
            elif pos in ("ADP", "CCONJ", "SCONJ", "PART"):
                sink_mass = 0.87
            elif pos == "ADJ":
                sink_mass = 0.86
            elif pos == "PUNCT":
                sink_mass = 0.925

        if i == 1:
            sink_mass = 0.97
            if aligned and doc[aligned[0]].pos_ == "DET":
                sink_mass = 0.945

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 + 0.3 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_pos_modulation", attention


def prog_L6H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with boundary-triggered previous-token attention.
    At lexical boundaries, concentrate older residual mass without changing BOS or self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_locality", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos_strength = {
        "NOUN": 0.78,
        "PROPN": 0.80,
        "VERB": 0.72,
        "AUX": 0.70,
        "ADJ": 0.71,
        "ADV": 0.68,
        "ADP": 0.66,
        "DET": 0.62,
        "PRON": 0.63,
        "CCONJ": 0.82,
        "SCONJ": 0.69,
        "PART": 0.67,
        "NUM": 0.74,
        "INTJ": 0.73,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        piece = tokens[i].lstrip("▁Ġ")
        words = [doc[k] for k in aligned[i]]
        sink = 0.72

        if words:
            sink = float(np.mean([
                pos_strength.get(word.pos_, 0.72) for word in words
            ]))

        if not piece.strip():
            sink = 0.75
        elif all(not c.isalnum() and not c.isspace() for c in piece):
            sink = 0.84
            if any(c in ".!?" for c in piece):
                sink = 0.88
            if any(c in "'’" for c in piece):
                sink = 0.92
        elif words:
            # Internal wordpieces often show unusually strong sink attention.
            previous_ids = aligned[i - 1]
            if any(k in previous_ids for k in aligned[i]):
                sink = max(sink, 0.82)

        if i == 1:
            sink = 0.955

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-distances / 8.0)
        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Boundary queries favor the immediately preceding token, rather than
        # diffuse older context. Leave continuation pieces and special tokens alone.
        if (
            i > 2
            and tokens[i] not in tokenizer.all_special_tokens
            and tokens[i - 1] not in tokenizer.all_special_tokens
            and not any(k in aligned[i - 1] for k in aligned[i])
            and (
                words
                or not piece.strip()
                or all(not c.isalnum() and not c.isspace() for c in piece)
            )
        ):
            moved = 0.90 * attention[i, 1:i - 1].sum()
            attention[i, 1:i - 1] *= 0.10
            attention[i, i - 1] += moved

    return "bos_sink_with_boundary_locality", attention


def prog_L6H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized lexical-boundary attention.
    Contraction apostrophes and word-final nominal/adverbial subpieces divert sink mass locally.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_lexical_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.80
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.87
            elif word.pos_ == "ADJ":
                sink_mass = 0.88
            elif word.pos_ == "VERB":
                sink_mass = 0.84
            elif word.pos_ == "ADV":
                sink_mass = 0.81
            elif word.pos_ in ("PRON", "DET", "ADP"):
                sink_mass = 0.78
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "PART"):
                sink_mass = 0.76
            elif word.is_punct:
                sink_mass = 0.77

        if i == 1:
            sink_mass = 0.86

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 * np.exp(-distances / 3.0) + 0.35 / (1.0 + distances)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Keep the default row intact except at these lexical boundaries.
        target = None
        target_mass = 0.0

        if (
            1 < i < n - 1
            and tokens[i].lstrip("▁Ġ") in ("'", "’")
            and tokens[i - 1][-1:].isalpha()
            and tokens[i + 1][:1].isalpha()
        ):
            target = i
            target_mass = 0.42
        elif aligned and i > 1:
            sid = aligned[0]
            continues_word = sid in alignment[i - 1]
            ends_word = i == n - 1 or sid not in alignment[i + 1]
            if continues_word and ends_word:
                if doc[sid].pos_ in ("NOUN", "PROPN"):
                    target = i
                    target_mass = 0.19
                elif doc[sid].pos_ == "ADV":
                    target = i - 1
                    target_mass = 0.23

        if target is not None:
            transfer = min(
                attention[i, 0],
                max(0.0, target_mass - attention[i, target]),
            )
            attention[i, 0] -= transfer
            attention[i, target] += transfer

    return "bos_sink_lexical_boundaries", attention


def prog_L6H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and on nominal tokens.
    Remaining attention is weakly distributed over recent causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""

        sink = 0.83
        if pos in ("NOUN", "PROPN"):
            sink += 0.065
        elif pos == "ADJ":
            sink += 0.025
        elif pos == "DET":
            sink += 0.015
        elif pos in ("AUX", "PRON"):
            sink -= 0.025
        elif pos in ("CCONJ", "SCONJ"):
            sink -= 0.055
        elif pos == "PUNCT":
            sink -= 0.075

        # Early positions have particularly little competition with BOS.
        sink += 0.095 * np.exp(-(i - 1) / 3.0)
        if i == 1:
            sink = 0.955
            if pos in ("PRON", "ADV", "NUM"):
                sink = 0.985

        sink = float(np.clip(sink, 0.68, 0.985))
        attention[i, 0] = sink

        # No evidence identifies a strong secondary target; use a diffuse
        # causal background with a modest recency preference.
        positions = np.arange(1, i + 1)
        background = 0.65 / i + 0.35 * np.exp(-(i - positions) / 4.0)
        background /= background.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * background

    return "bos_sink_with_lexical_modulation", attention


def prog_L6H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a selective residual toward stacked prenominal modifiers.
    Preserve the default everywhere else, including all self-attention weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.95
            attention[i, 1:i + 1] = 0.05 / i

    doc = spacy_parse(sentence)
    aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)

    for noun in doc:
        if noun.pos_ != "NOUN":
            continue

        # Restrict the exception to consecutive descriptive modifiers:
        # a lone adjective must not change the original behavior.
        modifiers = []
        k = noun.i - 1
        while k >= 0:
            word = doc[k]
            if word.pos_ == "ADJ" or word.tag_ in ("VBG", "VBN"):
                modifiers.append(k)
                k -= 1
            else:
                break
        modifiers.reverse()
        if len(modifiers) < 2:
            continue

        targets = {}

        # Later modifiers look back to the final subtoken of the preceding one.
        for previous, current in zip(modifiers, modifiers[1:]):
            previous_tokens = [j for j in aligned[previous] if j > 0]
            current_tokens = [i for i in aligned[current] if i > 0]
            if not previous_tokens:
                continue
            weight = (
                0.07 if doc[current].tag_ in ("VBG", "VBN")
                else 0.44 if len(previous_tokens) > 1
                else 0.28
            )
            for i in current_tokens:
                targets.setdefault(i, {})[previous_tokens[-1]] = weight

        # Noun subtokens retain access to both recent descriptive modifiers.
        noun_tokens = [i for i in aligned[noun.i] if i > 0]
        for position, i in enumerate(noun_tokens):
            if len(noun_tokens) == 1:
                weights = (0.20, 0.12)
            elif position == len(noun_tokens) - 1:
                weights = (0.30, 0.10)
            elif position == 0:
                weights = (0.17, 0.05)
            else:
                weights = (0.13, 0.035)
            for modifier, weight in zip(reversed(modifiers[-2:]), weights):
                indices = [j for j in aligned[modifier] if j > 0]
                if indices:
                    targets.setdefault(i, {})[indices[-1]] = weight

        # Transfer only BOS mass; leave the diagonal and other edges untouched.
        for i, edges in targets.items():
            increments = {
                j: max(0.0, weight - attention[i, j])
                for j, weight in edges.items() if 0 < j < i
            }
            total = sum(increments.values())
            if total > 0:
                scale = min(1.0, attention[i, 0] / total)
                for j, increment in increments.items():
                    delta = scale * increment
                    attention[i, j] += delta
                    attention[i, 0] -= delta

    return "bos_sink_with_stacked_modifier_residual", attention


def prog_L6H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest on punctuation and content-word onsets.
    A small residual follows a causal recency prior."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        sink_mass = 0.85

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos == "PROPN":
                sink_mass = 0.935
            elif pos == "NOUN":
                sink_mass = 0.90
            elif pos == "VERB":
                sink_mass = 0.885
            elif pos == "ADJ":
                sink_mass = 0.875
            elif pos in ("AUX", "ADV"):
                sink_mass = 0.84
            elif pos in ("DET", "ADP", "PART", "PRON", "CCONJ", "SCONJ"):
                sink_mass = 0.815

            # Interior subword pieces generally have a weaker sink preference.
            if i > 1 and aligned[0] in alignment[i - 1]:
                sink_mass -= 0.075

        visible = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if not visible:
            sink_mass = 0.925
        elif all(not c.isalnum() for c in visible):
            sink_mass = 0.925
            if any(c in ".!?" for c in visible):
                sink_mass = 0.94

        if i == 1:
            sink_mass = max(sink_mass, 0.89)
            if aligned and doc[aligned[0]].pos_ == "PRON":
                sink_mass = 0.945

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_lexical_modulation", attention


def prog_L6H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with a secondary content-recurrence pathway.
    Later content tokens can retrieve semantically similar earlier mentions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ"}
    special_tokens = tokenizer.all_special_tokens

    word_ids = []
    anchors = {}
    for i in range(n):
        sid = alignment[i][0] if alignment[i] else None
        if tokens[i] in special_tokens:
            sid = None
        word_ids.append(sid)
        if sid is not None and sid not in anchors:
            anchors[sid] = i

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The sink is nearly exclusive early, then gradually loses some mass.
        sink_mass = max(0.76, 0.984 - 0.0038 * max(0, i - 12))
        sid = word_ids[i]
        if sid is not None and doc[sid].pos_ in {"PRON", "PUNCT"}:
            sink_mass = max(0.72, sink_mass - 0.025)

        attention[i, 0] = sink_mass
        positions = np.arange(1, i + 1)
        background = 0.35 / i + 0.65 * np.exp(
            -(i - positions) / 5.0
        )
        background /= background.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

        if sid is None or doc[sid].pos_ not in content_pos:
            continue

        best_score = 0.0
        best_target = None
        for j in range(1, i):
            previous_sid = word_ids[j]
            if previous_sid is None or previous_sid == sid:
                continue
            if doc[previous_sid].pos_ not in content_pos:
                continue

            same_pos = doc[previous_sid].pos_ == doc[sid].pos_
            both_nominal = (
                doc[previous_sid].pos_ in {"NOUN", "PROPN"}
                and doc[sid].pos_ in {"NOUN", "PROPN"}
            )
            if not (same_pos or both_nominal):
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            score = max(0.0, (similarity - 0.48) / 0.52)
            score = min(1.0, score)
            if score > best_score:
                best_score = score
                best_target = anchors[previous_sid]

        if best_target is not None:
            # Strong lexical recurrence can outweigh the otherwise dominant BOS.
            attention[i, best_target] += 2.5 * best_score ** 1.4

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "bos_sink_with_content_retrieval", attention


def prog_L6H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant BOS attention sink with a small, diffuse causal residual.
    The examples show no consistent lexical or syntactic target beyond BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.99
        attention[i, 1:i + 1] = 0.01 / i

    return "bos_attention_sink", attention


def prog_L6H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak lexical-category and positional modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.78 + 0.12 * np.exp(-(i - 1) / 5.0)
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.045
            elif word.pos_ in ("VERB", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ in ("ADP", "DET", "CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.035

            if word.ent_type_:
                sink_mass += 0.015

        piece = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if piece and all(c in ".'’" for c in piece):
            sink_mass += 0.045
        elif piece and all(c in "?!\"“”" for c in piece):
            sink_mass -= 0.04

        sink_mass = float(np.clip(sink_mass, 0.64, 0.95))
        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_linguistic_modulation", attention


def prog_L6H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse referent retrieval in dialogue and possessive contexts.
    Transfer only BOS mass to related earlier tokens, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.84 + 0.10 * np.exp(-i / 28.0)
        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Restrict retrieval to the dialogue/possessive failure regime.
    doc = spacy_parse(sentence)
    has_dialogue = any(c in sentence for c in ('"', '“', '”'))
    has_possessive = any(
        w.dep_ == "poss" and any(c.dep_ == "case" for c in w.children)
        for w in doc
    )
    if not (has_dialogue or has_possessive):
        return "bos_attention_sink", attention

    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
    mapping = [
        [j for j in indices if 0 < j < n and tokens[j] not in tokenizer.all_special_tokens]
        for indices in mapping
    ]
    similarities = {}
    nominal = ("NOUN", "PROPN")
    retrievable = ("NOUN", "PROPN", "VERB", "PRON")

    for word in doc:
        current = mapping[word.i]
        if not current or word.pos_ not in retrievable:
            continue

        for offset, i in enumerate(current):
            targets = {}
            strongest = 0.0

            for earlier in doc[:word.i]:
                previous = [j for j in mapping[earlier.i] if j < current[0]]
                if not previous:
                    continue

                same_class = word.pos_ == earlier.pos_
                noun_pair = word.pos_ in nominal and earlier.pos_ in nominal
                if not (same_class or noun_pair):
                    continue

                # Corresponding pieces preserve repeated multi-piece words.
                j = previous[min(offset, len(previous) - 1)]
                key = (i, j)
                if key not in similarities:
                    similarities[key] = embedding_similarity(tokens, i, j, tokenizer)
                similarity = similarities[key]

                related_nouns = noun_pair and (
                    word.dep_ == "conj"
                    or earlier.dep_ == "poss"
                    or has_possessive
                )
                threshold = 0.42 if related_nouns else 0.70
                if similarity < threshold:
                    continue

                strength = np.clip(
                    (similarity - threshold) / (1.0 - threshold), 0.0, 1.0
                )
                mass = (0.18 + 0.20 * strength) if similarity >= 0.70 else (
                    0.12 + 0.18 * strength
                )
                targets[j] = targets.get(j, 0.0) + mass
                strongest = max(strongest, mass)

            # A first quoted predicate/object can retrieve its addressee.
            # Repeated predicates instead use the stronger lexical path above.
            if has_dialogue and not targets and word.pos_ in ("VERB", "PRON"):
                prefix = sentence[:word.idx]
                quote_count = sum(prefix.count(c) for c in ('"', '“', '”'))
                if quote_count % 2:
                    opening = max(prefix.rfind('"'), prefix.rfind('“'))
                    recipients = [
                        w for w in doc[:word.i]
                        if w.idx < opening
                        and w.pos_ in nominal
                        and w.dep_ in ("dobj", "obj", "iobj", "dative")
                        and w.head.pos_ == "VERB"
                        and mapping[w.i]
                    ]
                    if recipients:
                        recipient = recipients[-1]
                        j = mapping[recipient.i][-1]
                        if j < i:
                            mass = 0.30 if word.pos_ == "VERB" else 0.24
                            targets[j] = mass
                            strongest = mass

            if targets:
                # Modify only BOS and selected strictly earlier keys.
                total = sum(targets.values())
                budget = min(
                    total,
                    strongest + 0.18,
                    0.65,
                    attention[i, 0],
                )
                attention[i, 0] -= budget
                for j, weight in targets.items():
                    attention[i, j] += budget * weight / total

    return "bos_sink_with_sparse_referent_retrieval", attention


def prog_L6H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with a strong initial-position bias.
    Linguistic features modulate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.745 + 0.145 * np.exp(-(i - 1) / 3.5)

        if alignment[i]:
            word = doc[alignment[i][0]]
            pos = word.pos_

            if pos in ("DET", "PROPN"):
                sink += 0.045
            elif pos in ("NOUN", "ADP"):
                sink += 0.020
            elif pos in ("VERB", "ADV", "CCONJ", "SCONJ"):
                sink -= 0.025

            if i == 1 and pos == "PRON":
                sink += 0.065

            if word.is_sent_start and i > 1:
                sink += 0.035

            if word.dep_ in ("nsubj", "nsubjpass") and pos in ("NOUN", "PROPN"):
                sink += 0.020

        sink = np.clip(sink, 0.62, 0.97)
        attention[i, 0] = sink

        # The examples establish a sink, not a reliable non-BOS target.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 5.0) / np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_diffuse_residual", make_row_stochastic(attention)


def prog_L6H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing diffuse causal attention.
    Position, rather than syntax or semantic identity, drives the dominant pattern.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.98 / (1.0 + 0.006 * (i - 1) ** 1.12)

        # Spread the small non-sink component over available causal tokens,
        # with a weak preference for nearby positions.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-distances / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L6H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position and linguistic modulation.
    Non-sink attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_locality", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.865 + 0.085 * np.exp(-(i - 1) / 3.0)
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None

        if word is not None:
            pos = word.pos_
            if pos in ("DET", "ADP", "PART"):
                sink += 0.035
            elif pos in ("PRON", "PROPN"):
                sink += 0.020
            elif pos in ("ADJ", "ADV"):
                sink += 0.005
            elif pos in ("VERB", "AUX", "CCONJ", "SCONJ"):
                sink -= 0.030

            if word.is_sent_start:
                sink += 0.025

            if word.is_punct:
                if any(c in word.text for c in ('"', "“", "”", "«", "»")):
                    sink += 0.075
                elif any(c in word.text for c in (".", "!", "?")):
                    sink -= 0.060
                else:
                    sink += 0.015

        if tokens[i].strip("▁Ġ \t\r\n") == "":
            sink += 0.070

        sink = float(np.clip(sink, 0.75, 0.978))
        if i == 1:
            sink = max(sink, 0.95)

        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_weak_locality", attention


def prog_L6H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.64 + 0.34 * np.exp(-(i - 1) / 19.0)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.6 + 0.4 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L7H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with a small diffuse, recency-biased causal tail."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            positions = np.arange(1, i + 1)
            distances = i - positions
            attention[i, 1:i + 1] = (
                0.001 + 0.018 * np.exp(-distances / 2.5)
            )

    return "bos_sink_with_weak_causal_tail", make_row_stochastic(attention)


def prog_L7H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with recency; quoted dialogue additionally retrieves nominal anchors.
    Transfer only BOS mass to earlier anchors, preserving baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.80 + 0.09 * np.exp(-i / 40.0)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    # Restrict the correction to dialogue, including damaged quote encodings.
    dialogue = (
        any(c in sentence for c in ('"', "“", "”", "«", "»"))
        or ("!" in sentence and "," in sentence)
    )
    if dialogue:
        doc = spacy_parse(sentence)
        mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
        anchors = np.zeros(n, dtype=np.float64)
        word_end = {}
        for word in doc:
            indices = [
                j for j in mapping[word.i]
                if 0 < j < n and tokens[j] not in tokenizer.all_special_tokens
            ]
            if not indices:
                continue
            end = max(indices)
            word_end[end] = word
            if word.pos_ in ("NOUN", "PROPN"):
                weight = 0.6
                if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    weight += 1.2
                elif word.dep_ in ("dobj", "obj", "iobj", "pobj"):
                    weight += 0.4
                if word.pos_ == "PROPN":
                    weight += 1.5
                anchors[end] += weight

        if n > 1 and tokens[1] not in tokenizer.all_special_tokens:
            anchors[1] += 0.6

        for i in range(2, n):
            weights = anchors[:i].copy()
            if weights.sum() == 0.0:
                continue

            clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
            word = word_end.get(i)
            transfer = 0.06

            if word is not None and word.pos_ == "PROPN":
                transfer += 0.09
            if word is not None and word.pos_ == "PRON":
                transfer += 0.06
            if clean and all(c in ",;:?!.'\"“”‘’«»" for c in clean):
                transfer += 0.14
                if "'" in clean or "’" in clean:
                    transfer += 0.16
                elif "?" in clean or "!" in clean:
                    transfer += 0.08
            if not clean:
                transfer += 0.24
            if i == n - 1 and any(c in clean for c in ".?!"):
                transfer = min(0.48, 0.38 + 0.0015 * i)

            transfer = min(transfer, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, :i] += transfer * weights / weights.sum()

    return "bos_sink_with_dialogue_anchors", attention


def prog_L7H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clitic-apostrophe exception: apostrophes retrieve prior
    content words, while all baseline self-attention and decay remain unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clitic_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_prior = {
        "NOUN": 0.90,
        "PROPN": 0.91,
        "ADJ": 0.87,
        "VERB": 0.84,
        "ADV": 0.76,
        "PRON": 0.77,
        "DET": 0.77,
        "ADP": 0.79,
        "AUX": 0.74,
        "PART": 0.73,
        "CCONJ": 0.66,
        "SCONJ": 0.73,
        "NUM": 0.83,
        "INTJ": 0.83,
        "PUNCT": 0.48,
        "SPACE": 0.57,
        "SYM": 0.70,
        "X": 0.79,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            sink = pos_prior.get(word.pos_, 0.79)
            if word.ent_type_:
                sink += 0.015
            if word.is_punct and word.is_sent_end:
                sink -= 0.16
        else:
            sink = 0.78

        # The first few positions are unusually strong sink queries.
        sink += 0.035 * np.exp(-(i - 1) / 7.0)
        sink -= 0.045 * (1.0 - np.exp(-(i - 1) / 24.0))
        if i == 1:
            sink = 0.925

        sink = float(np.clip(sink, 0.20, 0.96))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual += 0.15 / np.sqrt(i - positions + 1.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Distinguish grammatical apostrophes from quotation punctuation.
        if tokens[i].lstrip("▁Ġ").strip() in ("'", "’") and aligned:
            possessive = any(doc[k].dep_ == "case" for k in aligned)
            contraction = any(doc[k].pos_ in ("AUX", "PART") for k in aligned)
            if possessive or contraction:
                retrieval = np.zeros(i, dtype=np.float64)
                for j in range(1, i):
                    if not alignment[j]:
                        continue
                    k = alignment[j][-1]
                    if doc[k].pos_ not in ("NOUN", "PROPN", "ADJ", "VERB", "ADV"):
                        continue
                    # Retrieve completed words at their final subtoken.
                    if k in alignment[j + 1]:
                        continue
                    # Contracted auxiliaries retrieve beyond their local host.
                    if not possessive and k in alignment[i - 1]:
                        continue
                    retrieval[j] = 1.0 / (1.0 + i - j) ** 0.25

                if retrieval.sum() > 0.0:
                    target_sink = 0.47 if possessive else 0.20
                    transfer = max(0.0, attention[i, 0] - target_sink)
                    attention[i, 0] -= transfer
                    attention[i, :i] += transfer * retrieval / retrieval.sum()

    return "bos_sink_with_clitic_retrieval", attention


def prog_L7H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing causal leakage.
    Content tokens retain slightly more sink attention than punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        leakage_scale = 1.0
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.is_punct:
                leakage_scale = 1.65
            elif word.is_space:
                leakage_scale = 1.8
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                leakage_scale = 0.78
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                leakage_scale = 1.2

        sink_mass = 1.0 / (1.0 + 0.009 * i ** 0.85 * leakage_scale)
        attention[i, 0] = sink_mass

        # Unobserved non-sink mass: diffuse causal attention with mild recency.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 + 0.5 * np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L7H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Nominal queries retain slightly more sink mass than verbal queries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Approximately 98% BOS attention initially, gradually falling
        # as the number of competing causal keys grows.
        competing_odds = 0.023 * (float(i) ** 0.82)
        feature_strength = min(1.0, (i - 1) / 6.0)

        if alignment[i]:
            word = doc[alignment[i][-1]]
            correction = 1.0
            if word.pos_ in ("NOUN", "PROPN"):
                correction = 0.80
            elif word.pos_ == "PRON":
                correction = 0.92
            elif word.pos_ in ("VERB", "AUX"):
                correction = 1.12
            elif word.pos_ in ("ADJ", "ADV"):
                correction = 1.08
            competing_odds *= 1.0 + feature_strength * (correction - 1.0)

        sink_mass = 1.0 / (1.0 + competing_odds)
        attention[i, 0] = sink_mass

        # The examples constrain the sink much more strongly than the
        # residual: use a diffuse causal background with mild recency.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-distances / 8.0)
        recent /= recent.sum()
        background = 0.7 / i + 0.3 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_positional_decay", make_row_stochastic(attention)


def prog_L7H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for content words and weaker for punctuation.
    Residual attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_strength = {
        "NOUN": 0.855,
        "PROPN": 0.845,
        "ADJ": 0.845,
        "ADV": 0.805,
        "VERB": 0.795,
        "NUM": 0.815,
        "PRON": 0.770,
        "DET": 0.745,
        "AUX": 0.745,
        "ADP": 0.740,
        "PART": 0.735,
        "CCONJ": 0.750,
        "SCONJ": 0.755,
        "PUNCT": 0.650,
        "SPACE": 0.645,
    }

    for i in range(1, n):
        overlapping = alignment[i]
        sink_mass = 0.785

        if overlapping:
            # Prefer the lexical token when an offset also overlaps punctuation.
            word = doc[overlapping[0]]
            for sid in overlapping:
                candidate = doc[sid]
                if not candidate.is_punct and not candidate.is_space:
                    word = candidate
                    break

            sink_mass = pos_strength.get(word.pos_, 0.785)
            if word.dep_ in ("nsubj", "nsubjpass") and word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.020
            if word.ent_type_:
                sink_mass += 0.005
        elif not tokens[i].lstrip("▁Ġ").strip():
            sink_mass = 0.645

        if i == 1:
            sink_mass = 0.5 * sink_mass + 0.5 * 0.825

        sink_mass = np.clip(sink_mass, 0.60, 0.91)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_pos_modulation", attention


def prog_L7H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong early-position boost and mild linguistic modulation.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.40 + 0.49 * np.exp(-(i - 1) / 4.0)

        if i > 1 and alignment[i]:
            word = doc[alignment[i][0]]
            if word.is_punct:
                sink += 0.075
            elif word.is_space:
                sink += 0.045
            elif word.pos_ in ("ADP", "SCONJ", "CCONJ"):
                sink += 0.035
            elif word.pos_ in ("PRON", "DET", "AUX"):
                sink += 0.015
            elif word.pos_ in ("NOUN", "VERB", "ADJ"):
                sink -= 0.035

            # Continuation pieces can retain unusually strong sink attention.
            if alignment[i - 1] and alignment[i][0] in alignment[i - 1]:
                sink += 0.045

        sink = float(np.clip(sink, 0.25, 0.94))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        residual = (
            0.70 / i
            + 0.30
            * np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L7H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, strongest on content tokens.
    Remaining attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_strength = {
        "NOUN": 0.92,
        "PROPN": 0.92,
        "ADJ": 0.91,
        "VERB": 0.87,
        "ADV": 0.83,
        "NUM": 0.86,
        "ADP": 0.82,
        "PRON": 0.78,
        "DET": 0.77,
        "AUX": 0.76,
        "PART": 0.78,
        "INTJ": 0.87,
        "CCONJ": 0.60,
        "SCONJ": 0.66,
        "PUNCT": 0.51,
        "SPACE": 0.55,
    }

    for i in range(1, n):
        strength = 0.84
        if alignment[i]:
            # Use the largest overlapping linguistic token for split words.
            word = doc[max(alignment[i], key=lambda k: len(doc[k].text))]
            strength = pos_strength.get(word.pos_, 0.84)

            if word.dep_ in ("nsubj", "nsubjpass", "dobj", "obj", "pobj", "amod"):
                strength += 0.015
            elif word.dep_ in ("cc", "mark", "punct"):
                strength -= 0.025

            if word.ent_type_:
                strength += 0.01

        if i == 1:
            strength = max(strength, 0.88)

        strength = float(np.clip(strength, 0.45, 0.96))
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = strength
        attention[i, 1:i + 1] = (1.0 - strength) * residual

    return "bos_sink_with_linguistic_gating", attention


def prog_L7H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with clause-boundary attention to preceding content.
    Preserve the default rows and self-weights; redistribute BOS mass at boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_clause_boundaries", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.90
        attention[i, 1:i + 1] = 0.10 / i

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    for i in range(2, n):
        clean = tokens[i].lstrip("▁Ġ").strip()
        terminal = bool(clean) and any(c in ".!?" for c in clean) and all(
            c in ".!?\"'”’" for c in clean
        )
        comma = clean in (",", ";", ":")
        coordinating = any(
            doc[k].pos_ == "CCONJ" and doc[k].dep_ == "cc"
            for k in alignment[i]
        )
        if not (terminal or comma or coordinating):
            continue

        # Only boundary rows change, and their diagonal entries remain intact.
        weights = np.ones(i - 1, dtype=np.float64)
        for j in range(1, i):
            pos = {doc[k].pos_ for k in alignment[j]}
            if pos & {"VERB", "ADJ"}:
                weights[j - 1] *= 3.0
            elif pos & {"ADV", "ADP", "AUX"}:
                weights[j - 1] *= 2.0
            elif pos & {"PUNCT", "DET"}:
                weights[j - 1] *= 0.6

        if terminal:
            transfer = min(0.84, 0.65 + 0.003 * i)
        else:
            # Commas and coordinators particularly expose preceding predicates.
            preceding_adjective = any(
                doc[k].pos_ == "ADJ" for k in alignment[i - 1]
            )
            transfer = min(0.58, 0.29 + 0.008 * i)
            if preceding_adjective:
                transfer = min(0.68, transfer + 0.10)
            weights *= 0.7 + 0.8 * np.arange(1, i) / i

        attention[i, 0] -= transfer
        attention[i, 1:i] += transfer * weights / weights.sum()

    return "first_token_sink_with_clause_boundaries", attention


def prog_L7H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with mild position-dependent weakening and linguistic modulation.
    Residual attention is diffuse and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92 - 0.15 * (1.0 - np.exp(-i / 30.0))
        aligned = [doc[k] for k in alignment[i] if k < len(doc)]

        if aligned:
            word = max(aligned, key=lambda w: len(w.text))
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.045
            elif word.pos_ in ("PRON", "VERB", "AUX"):
                sink_mass -= 0.025
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass -= 0.065

            if word.dep_ in ("amod", "compound"):
                sink_mass += 0.015
        elif tokens[i].isspace() or tokens[i] == "▁":
            sink_mass -= 0.12

        sink_mass = float(np.clip(sink_mass, 0.60, 0.97))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.4 / i + 0.6 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L7H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predominantly a BOS attention-sink head, with a small local residual.
    Nominal phrases favor BOS; predicates distribute more mass to recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.89,
        "PROPN": 0.88,
        "ADJ": 0.86,
        "NUM": 0.86,
        "DET": 0.84,
        "ADP": 0.85,
        "ADV": 0.83,
        "CCONJ": 0.79,
        "SCONJ": 0.82,
        "PRON": 0.75,
        "VERB": 0.75,
        "AUX": 0.73,
        "PART": 0.77,
        "PUNCT": 0.68,
        "SPACE": 0.78,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[-1]] if sids else None
        sink_mass = sink_by_pos.get(word.pos_, 0.83) if word is not None else 0.83

        # The beginning of the sequence exhibits particularly strong sink attention.
        sink_mass += 0.045 * np.exp(-(i - 1) / 5.0)

        # The main visible non-BOS edges link predicates to an adjacent subject.
        subject_positions = []
        if word is not None and word.pos_ in ("VERB", "AUX"):
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                    for j in range(1, i):
                        if child.i in alignment[j]:
                            subject_positions.append(j)
            if subject_positions:
                distance = i - max(subject_positions)
                sink_mass -= 0.10 * np.exp(-(distance - 1) / 2.0)

        sink_mass = float(np.clip(sink_mass, 0.50, 0.96))

        # A causal, recency-biased residual, including a little self-attention.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 2.0)
        residual[-1] *= 0.25
        if i > 1:
            residual[-2] *= 1.8

        for j in subject_positions:
            residual[j - 1] += 1.5 * np.exp(-(i - j - 1) / 3.0)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", attention


def prog_L7H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Punctuation and whitespace renew the sink; residual attention is broadly causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_renewal", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    attention[0, 0] = 1.0

    for i in range(1, n):
        token = tokens[i]
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        # The sink competes with a growing set of ordinary causal keys.
        logit = 3.65 - 0.038 * i - 0.30 * np.log1p(i)

        if word is not None:
            if word.pos_ == "DET":
                logit += 0.25
            elif word.pos_ in ("ADP", "AUX"):
                logit += 0.12
            elif word.pos_ in ("VERB", "ADJ", "ADV"):
                logit -= 0.18

            if word.dep_ in ("nsubj", "nsubjpass") and i <= 4:
                logit += 0.15

        sink = 1.0 / (1.0 + np.exp(-logit))

        if token in special_tokens:
            sink = max(sink, 0.96)
        elif not clean:
            sink = max(sink, 0.95)
        elif clean in ("'", "’"):
            sink = max(sink, 0.985 - 0.0045 * i)
        elif all(c in ".!?" for c in clean):
            sink = max(sink, 0.94 - 0.0006 * i)
        elif clean == ",":
            comma_logit = logit + 0.80 - 0.015 * i
            sink = 1.0 / (1.0 + np.exp(-comma_logit))
        elif all(c in "\"'“”‘’!?.,:;—–-()[]{}" for c in clean):
            sink = max(sink, 0.85 - 0.003 * i)

        # Initial queries have little competition for the sink.
        if i == 1:
            sink = 0.97
            if word is not None and word.pos_ == "DET":
                sink = 0.985

        sink = np.clip(sink, 0.15, 0.99)
        positions = np.arange(1, i + 1)
        residual = 0.55 + 0.45 * np.exp(-(i - positions) / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_boundary_renewal", attention


def prog_L7H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with position decay; quoted dialogue additionally retrieves
    earlier speakers and predicates without changing baseline self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Restrict the correction to explicitly quoted dialogue.
    quote_positions = [
        i for i, token in enumerate(tokens)
        if any(c in token for c in ('"', '“', '”', '«', '»'))
    ]
    dialogue = len(quote_positions) >= 2
    anchor_strength = np.zeros(n, dtype=np.float64)
    if dialogue:
        # Represent a split word by its final model token.
        word_ends = {
            sid: ti
            for ti, aligned in enumerate(alignment)
            for sid in aligned
            if ti > 0
        }
        anchor_strength[1] = 1.0
        for sid, ti in word_ends.items():
            word = doc[sid]
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                anchor_strength[ti] += 3.0
            elif word.pos_ in ("NOUN", "PROPN"):
                anchor_strength[ti] += 1.5
            if word.pos_ == "VERB":
                anchor_strength[ti] += 2.0
        for ti in quote_positions:
            if ti > 0:
                anchor_strength[ti] += 1.0

    for i in range(1, n):
        sink_mass = 0.48 + 0.467 * np.exp(-(i - 1) / 55.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.035
                if word.is_sent_end:
                    sink_mass -= 0.065
            elif word.pos_ == "SPACE":
                sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.40, 0.97))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.55 / i + 0.45 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

        # Transfer only BOS mass to strictly earlier dialogue anchors.
        # The original diagonal and diffuse remainder remain untouched.
        if dialogue and i >= quote_positions[0] and aligned:
            word = doc[aligned[-1]]
            previous_quotes = [q for q in quote_positions if q <= i]
            proximity = np.exp(-(i - previous_quotes[-1]) / 22.0)
            extra = 0.0
            if word.pos_ == "PRON":
                extra = 0.13
            elif word.pos_ == "VERB":
                extra = 0.05
            elif word.pos_ == "PUNCT":
                extra = 0.04

            weights = anchor_strength[1:i].copy()
            weights *= np.exp(-(i - np.arange(1, i)) / 50.0)
            for sid in aligned:
                head_index = word_ends.get(doc[sid].head.i, -1)
                if 0 < head_index < i:
                    weights[head_index - 1] += 2.0

            total = weights.sum()
            if total > 0.0:
                transfer = min(
                    (0.12 + extra) * proximity,
                    max(0.0, attention[i, 0] - 0.30),
                )
                attention[i, 0] -= transfer
                attention[i, 1:i] += transfer * weights / total

    return "bos_sink_with_dialogue_retrieval", make_row_stochastic(attention)


def prog_L7H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest on content tokens, with a weak causal
    recency background rather than a specific syntactic target."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.87,
        "PROPN": 0.90,
        "ADJ": 0.84,
        "VERB": 0.77,
        "ADV": 0.73,
        "NUM": 0.82,
        "ADP": 0.75,
        "DET": 0.69,
        "PRON": 0.65,
        "AUX": 0.62,
        "PART": 0.65,
        "CCONJ": 0.60,
        "SCONJ": 0.61,
        "PUNCT": 0.54,
        "SPACE": 0.70,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            word = max(
                (doc[k] for k in aligned),
                key=lambda w: (not w.is_space, not w.is_punct, len(w.text)),
            )
            sink = sink_by_pos.get(word.pos_, 0.77)
            if word.ent_type_:
                sink += 0.02
        else:
            sink = 0.77

        # Early queries have fewer competing keys.
        sink += 0.06 * np.exp(-(i - 1) / 2.5)
        sink = float(np.clip(sink, 0.45, 0.94))

        # The examples identify the sink but do not establish a secondary
        # target; distribute remaining mass broadly with mild recency bias.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.55 * np.exp(-distances / 4.0) + 0.45
        background /= background.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

    return "bos_sink_with_lexical_gating", make_row_stochastic(attention)


def prog_L7H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with occasional local phrase-boundary attention.
    Move only BOS mass to recent phrase endings, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos_tags = {doc[k].pos_ for k in alignment[i]}
        sink_mass = 0.94

        if pos_tags & {"ADJ"}:
            sink_mass = 0.97
        elif pos_tags & {"NOUN", "PROPN", "VERB"}:
            sink_mass = 0.955
        elif pos_tags & {"PUNCT", "CCONJ", "SCONJ"}:
            sink_mass = 0.90
        elif pos_tags & {"DET", "ADP", "AUX"}:
            sink_mass = 0.925

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only phrase-boundary queries get an additional local edge.
        if i > 1 and alignment[i] and alignment[i - 1]:
            current = doc[alignment[i][0]]
            previous = doc[alignment[i - 1][-1]]
            target = None
            extra = 0.0

            if current.i != previous.i:
                if current.pos_ == "DET":
                    if previous.text == ",":
                        target, extra = i - 1, 0.13
                    elif previous.pos_ == "VERB":
                        target, extra = i - 1, 0.035

                # Find the final subtoken of a nearby completed phrase.
                if target is None and (
                    current.pos_ == "CCONJ"
                    or current.text == ","
                    or (
                        current.pos_ in {"DET", "ADP"}
                        and previous.pos_ in {"ADP", "NOUN", "PROPN"}
                    )
                ):
                    for j in range(i - 1, max(0, i - 4), -1):
                        if not alignment[j]:
                            continue
                        anchor = doc[alignment[j][-1]]
                        if anchor.i == current.i:
                            continue
                        if anchor.pos_ in {"NOUN", "PROPN", "ADJ", "VERB"}:
                            if current.pos_ == "CCONJ":
                                target, extra = j, 0.10
                            elif current.text == "," and anchor.pos_ in {"NOUN", "PROPN"}:
                                target, extra = j, 0.08
                            elif (
                                current.pos_ == "DET"
                                and previous.pos_ == "ADP"
                                and anchor.pos_ in {"NOUN", "PROPN"}
                            ):
                                target, extra = j, 0.05
                            elif (
                                current.pos_ == "ADP"
                                and j == i - 1
                                and anchor.dep_ in {"pobj", "conj"}
                                and anchor.pos_ in {"NOUN", "PROPN"}
                            ):
                                target, extra = j, 0.05
                            break
                        if anchor.pos_ == "PUNCT" and anchor.text != ",":
                            break

            if target is not None:
                attention[i, 0] -= extra
                attention[i, target] += extra

    return "bos_sink_with_phrase_boundaries", attention


def prog_L7H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a dialogue exception: quoted queries retrieve nearby
    reporting-clause anchors while retaining the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.90 + 0.046 * np.exp(-(i - 1) / 8.0)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Leave non-dialogue inputs exactly unchanged. The euro sign also
    # recognizes quotation marks corrupted by common encoding errors.
    quote_marks = ('"', '“', '”', '„', '«', '»', '€')
    if not any(mark in sentence for mark in quote_marks):
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inside_quote = False
    quote_start = -1
    anchors = {}

    for i in range(1, n):
        text = tokens[i].replace("▁", "").replace("Ġ", "")
        boundary = any(mark in text for mark in quote_marks)
        opening = boundary and not inside_quote
        closing = boundary and inside_quote

        if opening:
            quote_start = i
            anchors = {}
            if i > 1:
                anchors[1] = 0.12

            # Use the final subtoken of each nearby linguistic anchor.
            for tags, weight in (
                (("VERB",), 0.30),
                (("NOUN", "PROPN"), 0.32),
                (("ADJ",), 0.10),
            ):
                for j in range(i - 1, max(0, i - 17), -1):
                    if any(doc[k].pos_ in tags for k in alignment[j]):
                        anchors[j] = anchors.get(j, 0.0) + weight
                        break

            if i > 1:
                anchors[i - 1] = anchors.get(i - 1, 0.0) + 0.06
            inside_quote = True

        if inside_quote:
            targets = {j: w for j, w in anchors.items() if 0 < j < i}
            if quote_start < i:
                targets[quote_start] = targets.get(quote_start, 0.0) + 0.10

            if targets:
                pos = {doc[k].pos_ for k in alignment[i]}
                if opening:
                    transfer = 0.10
                elif closing or any(c in text for c in ".!?"):
                    transfer = 0.36
                elif i - quote_start <= 3:
                    transfer = 0.48
                elif pos.intersection(("PRON", "AUX")):
                    transfer = 0.40
                else:
                    transfer = 0.20

                transfer = min(transfer, attention[i, 0])
                total = sum(targets.values())
                attention[i, 0] -= transfer
                for j, weight in targets.items():
                    attention[i, j] += transfer * weight / total

        if closing:
            inside_quote = False

    return "bos_sink_with_dialogue_anchors", attention


def prog_L7H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with punctuation-triggered release to earlier linguistic context.
    Preserve the original local residual and self-attention exactly.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.92,
        "PROPN": 0.92,
        "ADJ": 0.92,
        "NUM": 0.88,
        "VERB": 0.85,
        "AUX": 0.84,
        "DET": 0.87,
        "ADP": 0.84,
        "PRON": 0.75,
        "ADV": 0.78,
        "PART": 0.76,
        "CCONJ": 0.69,
        "SCONJ": 0.76,
        "INTJ": 0.80,
        "PUNCT": 0.48,
        "SPACE": 0.52,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            sink = sum(
                sink_by_pos.get(doc[k].pos_, 0.86) for k in aligned
            ) / len(aligned)
        elif tokens[i] in tokenizer.all_special_tokens:
            sink = 0.90
        elif not tokens[i].strip("▁Ġ \t\r\n"):
            sink = 0.52
        else:
            sink = 0.86

        # Early content positions show particularly strong sink attention.
        if i == 2 and aligned:
            if doc[aligned[0]].pos_ not in ("PUNCT", "SPACE"):
                sink += 0.035

        sink = float(np.clip(sink, 0.40, 0.97))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Long-prefix punctuation releases BOS mass into broad context.
        # Raw punctuation detection also catches contraction apostrophes,
        # which may be aligned to an AUX or PART rather than PUNCT.
        surface = tokens[i].strip("▁Ġ \t\r\n")
        if i >= 6 and surface in (".", "!", "?", ",", ";", ":", "'", "’"):
            target_sink = (
                0.14 if surface in (".", "!", "?")
                else 0.30 if surface in ("'", "’")
                else 0.24
            )
            context = np.zeros(i - 1, dtype=np.float64)
            context_by_pos = {
                "VERB": 2.5,
                "AUX": 1.7,
                "SCONJ": 2.0,
                "CCONJ": 1.3,
                "NOUN": 1.4,
                "PROPN": 1.4,
                "ADJ": 1.2,
                "DET": 0.5,
                "PUNCT": 0.1,
                "SPACE": 0.0,
            }
            for j in range(1, i):
                if tokens[j] in tokenizer.all_special_tokens:
                    continue
                previous = alignment[j]
                context[j - 1] = (
                    sum(
                        context_by_pos.get(doc[k].pos_, 1.0)
                        for k in previous
                    ) / len(previous)
                    if previous else 1.0
                )

            total = context.sum()
            if total > 0.0:
                released = max(0.0, attention[i, 0] - target_sink)
                attention[i, 0] -= released
                attention[i, 1:i] += released * context / total

    return "bos_sink_with_punctuation_release", attention


def prog_L7H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with sparse successor-induction attention.
    Repeated content and recurring dialogue boundaries divert only BOS mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_sparse_induction", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 - 0.045 * (1.0 - np.exp(-i / 24.0))
        positions = np.arange(1, i + 1)
        residual = 0.25 / i + 0.75 * np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    doc = spacy_parse(sentence)
    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
    content_matches = {}
    repeated_content = False

    # Require a strong repeated content anchor before enabling the new path.
    for wi, word in enumerate(doc):
        if word.pos_ not in ("NOUN", "PROPN", "VERB", "ADJ"):
            continue
        current = [i for i in mapping[wi] if i > 0]
        if not current:
            continue

        threshold = 0.68 if word.pos_ == "VERB" else 0.82
        best_score = threshold
        best_previous = None
        for wj in range(wi):
            if doc[wj].pos_ != word.pos_:
                continue
            previous = [j for j in mapping[wj] if j > 0]
            if not previous or current[0] - previous[-1] < 4:
                continue
            score = embedding_similarity(
                tokens, current[0], previous[0], tokenizer
            )
            if score >= best_score:
                best_score = score
                best_previous = wj

        if best_previous is not None:
            content_matches[wi] = best_previous
            if word.pos_ in ("NOUN", "PROPN", "VERB"):
                repeated_content = True

    if repeated_content:
        transfers = {}

        # Similar modifiers can serve as alternative cues in a repeated phrase.
        for wi, word in enumerate(doc):
            if word.pos_ != "ADJ" or wi in content_matches:
                continue
            current = [i for i in mapping[wi] if i > 0]
            if not current or wi == 0 or doc[wi - 1].pos_ != "DET":
                continue
            best_score = 0.52
            for wj in range(1, wi):
                previous = [j for j in mapping[wj] if j > 0]
                if (
                    doc[wj].pos_ != "ADJ"
                    or doc[wj - 1].pos_ != "DET"
                    or not previous
                    or current[0] - previous[-1] < 4
                ):
                    continue
                score = embedding_similarity(
                    tokens, current[0], previous[0], tokenizer
                )
                if score >= best_score:
                    best_score = score
                    content_matches[wi] = wj

        for wi, wj in content_matches.items():
            current = [i for i in mapping[wi] if i > 0]
            previous = [j for j in mapping[wj] if j > 0]
            pos = doc[wi].pos_
            mass = (
                0.60 if pos == "ADJ"
                else 0.45 if pos == "VERB"
                else 0.70 if len(current) > 1 and len(previous) > 1
                else 0.44
            )
            for offset, i in enumerate(current):
                # A matched cue retrieves the token AFTER its earlier occurrence.
                j = previous[min(offset, len(previous) - 1)] + 1
                if 0 < j < i:
                    transfers.setdefault(i, []).append((j, mass))

        # Repeated determiners are useful only at a new phrase boundary.
        for wi, word in enumerate(doc):
            if word.pos_ != "DET" or not mapping[wi] or wi == 0:
                continue
            boundary = doc[wi - 1].is_punct or doc[wi - 1].is_space
            after_verb = doc[wi - 1].pos_ == "VERB"
            if not (boundary or after_verb):
                continue
            i = mapping[wi][0]
            if i <= 0:
                continue
            for wj in range(wi - 1, -1, -1):
                if doc[wj].pos_ != "DET" or not mapping[wj]:
                    continue
                p = mapping[wj][0]
                if p <= 0 or i - p < 4:
                    continue
                if embedding_similarity(tokens, i, p, tokenizer) >= 0.90:
                    j = mapping[wj][-1] + 1
                    if 0 < j < i:
                        mass = 0.45 if boundary else 0.20
                        transfers.setdefault(i, []).append((j, mass))
                    break

        # Match punctuation literally, but only at recurring quotation openings.
        for i in range(1, n):
            clean = tokens[i].lstrip("▁Ġ").strip()
            is_quote = clean in ('"', "“", "”")
            before_quote = (
                clean == ","
                and i + 1 < n
                and tokens[i + 1].lstrip("▁Ġ").strip() in ('"', "“")
            )
            if not (is_quote or before_quote):
                continue
            for p in range(i - 4, 0, -1):
                if tokens[p].lstrip("▁Ġ").strip() != clean:
                    continue
                if before_quote and (
                    p + 1 >= i
                    or tokens[p + 1].lstrip("▁Ġ").strip() not in ('"', "“")
                ):
                    continue
                transfers.setdefault(i, []).append(
                    (p + 1, 0.20 if is_quote else 0.40)
                )
                break

        # Transfer only sink mass: diagonal and all unrelated edges stay intact.
        for i, edges in transfers.items():
            total = sum(mass for _, mass in edges)
            budget = min(total, 0.88, attention[i, 0])
            if total > 0:
                attention[i, 0] -= budget
                for j, mass in edges:
                    attention[i, j] += budget * mass / total

    return "bos_sink_with_sparse_induction", attention


def prog_L7H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional weakening.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_positional_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.68 + 0.23 * np.exp(-(i - 1) / 32.0)
        if i == 1:
            sink_mass = 0.97

        positions = np.arange(1, i + 1)
        residual = 0.55 / i + 0.45 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_decay", attention


def prog_L7H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened at boundaries and early positions.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].lstrip("▁Ġ")
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        # A large sink persists throughout the sequence, rather than
        # decaying away as the number of available keys increases.
        sink = 0.59 + 0.18 * np.exp(-max(i - 2, 0) / 4.0)

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.025
            elif word.pos_ in ("AUX", "ADP", "PART"):
                sink -= 0.045
            elif word.pos_ == "VERB":
                sink -= 0.015

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink += 0.035
            if word.is_sent_start:
                sink += 0.10

        # Tokenization and punctuation boundaries have especially strong
        # sink attention, including apostrophe fragments and blank pieces.
        if not text or text.isspace():
            sink = 0.85
        elif text in ("'", "’"):
            sink = 0.89
        elif all(c in ".!?…。！？\"'”’" for c in text):
            sink = 0.80
        elif all(c in ",;:，；：" for c in text):
            sink = 0.71
        elif all(not c.isalnum() and not c.isspace() for c in text):
            sink = 0.73

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.82
        if i == 1:
            sink = 0.96

        sink = float(np.clip(sink, 0.45, 0.98))
        attention[i, 0] = sink

        # No non-BOS target is supported strongly by the supplied edges:
        # use a conservative, broad causal residual instead of inventing
        # a sharp dependency or copying mechanism.
        distances = i - np.arange(1, i + 1)
        residual = 0.7 + 0.3 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_boundary_gating", attention


def prog_L7H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local syntactic-transition exception.
    Transfer sink mass to an adjacent linked token without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "NOUN": 0.045,
        "PROPN": 0.060,
        "ADJ": 0.040,
        "VERB": 0.005,
        "AUX": -0.080,
        "ADV": -0.025,
        "DET": -0.005,
        "PRON": 0.005,
        "ADP": -0.025,
        "PART": -0.045,
        "CCONJ": -0.025,
        "SCONJ": -0.015,
        "NUM": 0.010,
    }

    for i in range(1, n):
        sink_mass = 0.735
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            sink_mass += pos_adjustment.get(word.pos_, 0.0)

            if word.is_space:
                sink_mass = 0.875
            elif word.is_punct:
                if any(c in word.text for c in "'’"):
                    sink_mass = 0.835
                elif any(c in word.text for c in ".!?"):
                    sink_mass = 0.770
                elif any(c in word.text for c in "\"“”"):
                    sink_mass = 0.755
                else:
                    sink_mass = 0.650

        # Preserve the original whitespace handling.
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
        if surface and surface.isspace():
            sink_mass = 0.875

        sink_mass = float(np.clip(sink_mass, 0.60, 0.90))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-distances / 5.0)
        recent /= recent.sum()
        residual = 0.75 / i + 0.25 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # A local dependency or subword continuation can override the sink.
        # Only BOS and the immediately preceding non-BOS token are changed.
        if i > 1 and aligned and alignment[i - 1] and not surface.isspace():
            current = doc[aligned[0]]
            previous = doc[alignment[i - 1][-1]]
            continuation = current.i == previous.i
            linked = (
                current.head.i == previous.i
                or previous.head.i == current.i
            )
            functional_bridge = (
                current.head.i == previous.head.i
                and current.pos_ in ("DET", "PRON", "AUX", "PART")
                and previous.pos_ in ("ADP", "SCONJ", "AUX", "PART")
            )

            if not current.is_space and not previous.is_space and (
                continuation or linked or functional_bridge
            ):
                target = 0.17

                if continuation:
                    target = 0.16
                elif current.pos_ in ("ADP", "PART") and previous.pos_ in (
                    "VERB", "AUX", "ADV"
                ):
                    target = 0.22
                elif current.pos_ in ("NOUN", "PROPN") and previous.dep_ == "det":
                    target = 0.12
                elif (
                    i == 2
                    and current.pos_ in ("VERB", "AUX")
                    and previous.dep_ in ("nsubj", "nsubjpass")
                    and previous.head.i == current.i
                ):
                    target = 0.42

                transfer = min(
                    max(0.0, target - attention[i, i - 1]),
                    max(0.0, attention[i, 0] - 0.40),
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_local_syntax", attention


def prog_L7H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, recency-biased residual attention.
    Sink strength decreases mildly as the causal context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.97 - 0.0012 * i
        sink_mass = max(0.87, sink_mass)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        # Preserve a small diffuse component rather than assuming a
        # specific syntactic or semantic target unsupported by the examples.
        residual = 0.8 * residual + 0.2 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L7H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly decreasing strength over position.
    Residual attention is diffuse, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = np.clip(
            0.92 + 0.02 * (1.0 - np.exp(-i / 3.0)) - 0.0022 * i,
            0.72,
            0.95,
        )

        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 6.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L7H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with lexical modulation; late punctuation redirects BOS mass
    toward the sentence-opening phrase rather than the recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_prefix", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_sink = {
        "NOUN": 0.89,
        "PROPN": 0.91,
        "ADJ": 0.88,
        "NUM": 0.85,
        "VERB": 0.78,
        "ADV": 0.74,
        "PRON": 0.73,
        "DET": 0.79,
        "ADP": 0.78,
        "AUX": 0.69,
        "PART": 0.67,
        "CCONJ": 0.48,
        "SCONJ": 0.58,
        "PUNCT": 0.44,
        "SPACE": 0.55,
    }

    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            sink = sum(pos_sink.get(doc[k].pos_, 0.80)
                       for k in aligned) / len(aligned)
        else:
            clean = tokens[i].lstrip("▁Ġ")
            punctuation = bool(clean) and all(
                not c.isalnum() and not c.isspace() for c in clean
            )
            sink = 0.44 if punctuation else 0.80

        # The opening tokens consistently devote nearly all mass to BOS.
        opening = np.exp(-(i - 1) / 2.0)
        sink = sink * (1.0 - opening) + 0.94 * opening

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 / i + 0.3 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Late punctuation, including contraction apostrophes, reads back
        # the opening phrase. Transfer only BOS mass, preserving the
        # original diagonal and every non-prefix context weight exactly.
        clean = tokens[i].lstrip("▁Ġ")
        punctuation = (
            tokens[i] not in tokenizer.all_special_tokens
            and bool(clean)
            and all(not c.isalnum() and not c.isspace() for c in clean)
        )
        if i >= 6 and punctuation:
            prefix = np.arange(1, min(5, i))
            weights = np.exp(-0.5 * (prefix - 2.0) ** 2)
            for p, j in enumerate(prefix):
                if any(doc[k].dep_ in ("npadvmod", "obl:tmod")
                       for k in alignment[j]):
                    weights[p] *= 2.0
            weights /= weights.sum()

            transfer = max(0.0, attention[i, 0] - 0.12)
            attention[i, 0] -= transfer
            attention[i, prefix] += transfer * weights

    return "bos_sink_with_punctuation_prefix", attention


def prog_L7H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the initial token,
    with a small, diffuse causal residual and no clear syntactic preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.97
            attention[i, 1:i + 1] = 0.03 / i

    return "bos_sink_with_diffuse_residual", attention


def prog_L7H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild positional weakening.
    Linguistic features modulate a small, diffuse causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_remainder", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.982 - 0.085 * (1.0 - np.exp(-(i - 1) / 16.0))

        indices = alignment[i]
        if indices:
            word = doc[indices[0]]
            if word.pos_ == "PUNCT":
                sink_mass += 0.018
            elif word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ", "PART"):
                sink_mass += 0.008
            elif word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink_mass -= 0.015

        sink_mass = float(np.clip(sink_mass, 0.84, 0.995))

        # Spread the non-sink mass, retaining a weak local preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

    return "bos_sink_with_diffuse_remainder", make_row_stochastic(attention)


def prog_L7H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal recency spillover.
    Punctuation modestly reduces sink strength; no consistent syntactic target is evident.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.81 + 0.10 * np.exp(-(i - 1) / 4.0)

        aligned = alignment[i]
        if aligned and all(doc[k].pos_ == "PUNCT" for k in aligned):
            sink_mass -= 0.13

        # Spread the otherwise unobserved residual over the causal context,
        # with a mild preference for recent positions rather than a sharp edge.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_recency", attention


def prog_L7H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening dominance as context grows.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.62 + 0.32 * np.exp(-(i - 1) / 24.0)

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.55 + 0.45 * np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_recency", attention


def prog_L7H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink with weaker early-entity retrieval.
    Content and referential queries can divert mass toward earlier salient nouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_entity_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    pos = [""] * n
    dep = [""] * n
    entity = [""] * n
    representatives = []

    for i, indices in enumerate(alignment):
        if tokens[i] in special_tokens or not indices:
            continue
        word = doc[indices[-1]]
        pos[i] = word.pos_
        dep[i] = word.dep_
        entity[i] = word.ent_type_

        # Use the final subtoken as the representative of a lexical word.
        if word.pos_ in ("NOUN", "PROPN"):
            if i + 1 == n or indices[-1] not in alignment[i + 1]:
                representatives.append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        # A strong constant sink competes with a growing causal background.
        row = np.full(i + 1, 0.075, dtype=np.float64)
        row[0] = 14.0
        row[i] += 0.45
        if i > 1:
            row[i - 1] += 0.25

        for j in representatives:
            if j >= i or j == 0:
                continue

            early_prior = np.exp(-j / 24.0)
            salience = 0.35
            if dep[j] in ("nsubj", "nsubjpass", "csubj"):
                salience += 0.65
            if pos[j] == "PROPN":
                salience += 1.5
            if entity[j]:
                salience += 0.35

            row[j] += salience * early_prior

            if pos[i] == "PRON":
                row[j] += 2.0 * salience * early_prior
            elif pos[i] in ("NOUN", "PROPN"):
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                relatedness = np.clip((similarity - 0.45) / 0.50, 0.0, 1.0)
                row[j] += 22.0 * relatedness ** 2

        if pos[i] in ("PUNCT", "CCONJ", "SCONJ", "ADP", "AUX", "DET"):
            row[0] *= 1.15

        attention[i, :i + 1] = row / row.sum()

    return "bos_sink_with_entity_retrieval", attention


def prog_L7H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a nominal-anchor correction.
    Predicates, especially auxiliaries, sometimes retrieve a preceding noun subject.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if ti > 0:
                word_tokens[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        pos = word.pos_ if word is not None else ""

        # The sink is strongest near the beginning, but persists throughout.
        sink = 0.56 + 0.27 * np.exp(-(i - 1) / 9.0)
        if pos in ("NOUN", "PROPN"):
            sink += 0.10
        elif pos in ("ADJ", "ADV"):
            sink += 0.05
        elif pos in ("VERB", "AUX"):
            sink -= 0.13
        elif pos in ("PRON", "DET", "ADP"):
            sink -= 0.07

        if i == 1:
            sink = 0.84
        elif i <= 4 and pos in ("NOUN", "PROPN", "ADJ", "DET", "ADP"):
            sink += 0.06

        # Allocate the non-sink mass to local context and nominal anchors.
        prior = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            distance = i - j
            prior[j] = 0.20 * np.exp(-distance / 4.0)
            if alignment[j]:
                target = doc[alignment[j][-1]]
                if target.pos_ in ("NOUN", "PROPN"):
                    prior[j] += 0.65 * np.exp(-distance / 12.0)
                if word is not None and target.i == word.i and j < i:
                    prior[j] += 0.15

        subject_targets = []
        if word is not None and pos in ("VERB", "AUX"):
            subjects = [
                child for child in word.children
                if child.dep_ in ("nsubj", "nsubjpass", "csubj")
            ]
            if pos == "AUX" or word.dep_ in ("aux", "auxpass", "cop"):
                subjects += [
                    child for child in word.head.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                ]
            for subject in subjects:
                if subject.pos_ in ("NOUN", "PROPN"):
                    preceding = [j for j in word_tokens[subject.i] if j < i]
                    if preceding:
                        subject_targets.append(preceding[-1])

        if subject_targets:
            nearest = max(subject_targets)
            distance = i - nearest
            if pos == "AUX" and distance <= 5:
                sink = 0.17 + 0.025 * (distance - 1)
                prior[nearest] += 8.0
            else:
                sink = min(sink, 0.46 + 0.012 * min(distance, 10))
                prior[nearest] += 2.5

        sink = float(np.clip(sink, 0.15, 0.96))
        attention[i, 0] = sink
        total = prior.sum()
        if total > 0:
            attention[i, :i + 1] += (1.0 - sink) * prior / total
        else:
            attention[i, i] = 1.0 - sink

    return "bos_sink_with_nominal_anchors", make_row_stochastic(attention)


def prog_L7H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak recency; quoted dialogue adds a competing diagonal channel.
    Outside quoted dialogue, preserve the original attention exactly.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_diagonal", attention

    quoted_dialogue = (
        sentence.count('"') >= 2
        or ("“" in sentence and "”" in sentence)
    )

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.76 + 0.16 * np.exp(-i / 18.0)
        distances = i - np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        if quoted_dialogue:
            # Transfer only BOS mass: leave all other historical edges intact.
            diagonal_boost = 0.12 + 0.05 * (1.0 - np.exp(-i / 24.0))
            attention[i, 0] -= diagonal_boost
            attention[i, i] += diagonal_boost

    return "bos_sink_with_dialogue_diagonal", attention


def prog_L7H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with noun anchors; predicative-adjective contexts weaken nominal
    persistence and introduce a modest predicate anchor that respects boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_gated_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    pos = [""] * n
    dep = [""] * n
    anchor = np.zeros(n, dtype=np.float64)
    special_tokens = set(tokenizer.all_special_tokens)

    for i, indices in enumerate(alignment):
        if not indices or tokens[i] in special_tokens:
            continue
        word = doc[indices[-1]]
        pos[i] = word.pos_
        dep[i] = word.dep_

    # Restrict the exception to nominally rich, adjective-predicate contexts.
    predicate_words = [
        word for word in doc
        if word.pos_ == "ADJ"
        and word.dep_ in ("acomp", "attr", "oprd", "ROOT")
    ]
    predicate_context = (
        bool(predicate_words)
        and sum(word.pos_ == "NOUN" for word in doc) >= 2
    )
    predicate_anchor = np.zeros(n, dtype=np.float64)
    if predicate_context:
        for word in predicate_words:
            pieces = [
                i for i in inverse[word.i]
                if i > 0 and tokens[i] not in special_tokens
            ]
            if pieces:
                predicate_anchor[max(pieces)] = 4.0
    boundaries = np.cumsum([p == "PUNCT" for p in pos])

    for word in doc:
        pieces = [
            i for i in inverse[word.i]
            if i > 0 and tokens[i] not in special_tokens
        ]
        if not pieces:
            continue

        last = max(pieces)
        if word.pos_ == "NOUN":
            strength = 18.0
            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                strength = 24.0
            elif word.dep_ in ("npadvmod", "compound"):
                strength = 3.0
            anchor[last] = max(anchor[last], strength)
        elif word.pos_ == "PROPN":
            anchor[last] = max(anchor[last], 4.0)

    attention[0, 0] = 1.0
    for i in range(1, n):
        p = pos[i]
        d = dep[i]
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        is_boundary = (
            not surface
            or p == "PUNCT"
            or tokens[i] in special_tokens
        )

        bos = 12.0
        if is_boundary:
            bos *= 4.5
        elif p in ("CCONJ", "SCONJ"):
            bos *= 2.4
        elif p == "DET":
            bos *= 1.7
        elif p == "VERB":
            bos *= 1.45
        elif p in ("AUX", "ADJ"):
            bos *= 0.65

        if d in ("mark", "cc", "parataxis"):
            bos *= 1.25

        attention[i, 0] = bos
        for j in range(1, i + 1):
            distance = i - j
            background = 0.10 * np.exp(-distance / 8.0)
            noun_weight = anchor[j] * np.exp(-distance / 36.0)

            # Modify only non-self anchor contributions in the exception.
            if predicate_context and j < i:
                boundary_gate = 0.35 ** int(boundaries[i] - boundaries[j])
                noun_weight *= 0.10 * boundary_gate
                noun_weight += (
                    predicate_anchor[j]
                    * np.exp(-distance / 36.0)
                    * boundary_gate
                )

            if j == i:
                noun_weight *= 0.035
                background = 0.45
                if p in ("DET", "ADP", "CCONJ", "SCONJ", "PUNCT"):
                    background = 0.16

            attention[i, j] = background + noun_weight

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "bos_sink_with_predicate_gated_anchors", attention


def prog_L8H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position/POS modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The overwhelmingly consistent observed feature is attention to BOS.
        sink_mass = 0.955 - 0.045 * (1.0 - np.exp(-i / 24.0))
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink_mass -= 0.12
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.06
            elif word.pos_ in ("PRON", "ADV"):
                sink_mass -= 0.035
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "DET"):
                sink_mass += 0.015

        sink_mass = float(np.clip(sink_mass, 0.70, 0.985))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.5 + np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_weak_local_residual", attention


def prog_L8H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong opening-position bias.
    Linguistic and subword features modulate a small causal residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_opening_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        token = tokens[i]
        clean = token.lstrip("▁Ġ")
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink = 0.78 + 0.15 * np.exp(-(i - 1) / 5.0)

        if i == 1 and word is not None:
            sink = {
                "PRON": 0.986,
                "DET": 0.915,
                "PROPN": 0.950,
                "ADP": 0.955,
                "ADV": 0.950,
                "SCONJ": 0.945,
                "NOUN": 0.940,
            }.get(word.pos_, 0.945)
        else:
            if word is not None:
                if word.pos_ in ("NOUN", "PROPN"):
                    sink += 0.018
                elif word.pos_ in ("AUX", "PART", "SCONJ"):
                    sink -= 0.025

            # Pieces sharing a spaCy word often retain more sink attention.
            if aligned and any(k in alignment[i - 1] for k in aligned):
                sink += 0.045

            if not clean or clean.isspace():
                sink += 0.065
            elif clean in ("'", "’"):
                sink += 0.095
            elif all(c in ".!?" for c in clean):
                sink += 0.055
            elif word is not None and word.is_punct:
                sink += 0.010

        sink = float(np.clip(sink, 0.65, 0.995))

        # The unobserved residual is conservatively spread over causal
        # non-BOS keys, with a modest preference for recent positions.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.45 / i + 0.55 * (
            np.exp(-distances / 4.0) /
            np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_opening_bias", attention


def prog_L8H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak lexical-category modulation.
    Non-sink attention is approximated by a diffuse causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.76
        if alignment[i]:
            word = doc[alignment[i][0]]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink_mass = 0.80
            elif pos == "ADJ":
                sink_mass = 0.84
            elif pos == "ADV":
                sink_mass = 0.78
            elif pos == "DET":
                sink_mass = 0.79
            elif pos in ("ADP", "PART"):
                sink_mass = 0.76
            elif pos == "VERB":
                sink_mass = 0.75
            elif pos == "AUX":
                sink_mass = 0.72
            elif pos in ("PRON", "CCONJ", "SCONJ"):
                sink_mass = 0.68
            elif pos == "PUNCT":
                sink_mass = 0.61

            if word.dep_ in ("amod", "acomp"):
                sink_mass += 0.02
            if word.dep_ in ("nsubj", "nsubjpass") and pos == "PRON":
                sink_mass -= 0.03

        # Early tokens show a slightly stronger sink preference.
        sink_mass += 0.04 * np.exp(-(i - 1) / 10.0)
        sink_mass = np.clip(sink_mass, 0.50, 0.91)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 * np.exp(-distances / 4.0)
        residual += 0.35 / np.sqrt(distances + 1.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_pos_modulation", attention


def prog_L8H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a nominal-subject override for copular auxiliaries.
    Residual attention favors nearby tokens and preceding syntactic subjects.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_copular_subject", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        # The sink remains dominant across most lexical and punctuation classes.
        sink = 0.88 - 0.07 * (1.0 - np.exp(-i / 24.0))
        subject_positions = []
        copular = False

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "DET"):
                sink += 0.045
            elif word.pos_ in ("VERB", "AUX", "CCONJ", "SCONJ"):
                sink -= 0.08
            elif word.pos_ == "PRON" and i > 3:
                sink -= 0.10

            if word.pos_ in ("VERB", "AUX", "ADJ"):
                governor = word
                if word.dep_ in ("aux", "auxpass", "cop"):
                    governor = word.head

                subjects = [
                    child for child in governor.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                ]
                for subject in subjects:
                    prior = [j for j in inverse[subject.i] if 0 < j < i]
                    if prior:
                        subject_positions.append((subject, prior[-1]))

                nominal_subjects = [
                    (subject, j) for subject, j in subject_positions
                    if subject.pos_ in ("NOUN", "PROPN")
                ]
                predicate_children = any(
                    child.dep_ in ("acomp", "attr", "oprd")
                    for child in governor.children
                )
                copular = (
                    word.pos_ == "AUX"
                    and bool(nominal_subjects)
                    and (
                        word.dep_ == "cop"
                        or (
                            governor.i == word.i
                            and predicate_children
                        )
                    )
                )

                if copular:
                    subject_positions = nominal_subjects
                    sink = 0.12
                elif subject_positions:
                    sink -= 0.06

        if i == 1:
            sink = 0.93

        sink = float(np.clip(sink, 0.08, 0.97))

        # A weak local distribution accounts for non-sink residual mass.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        if subject_positions:
            subject_distribution = np.zeros(i, dtype=np.float64)
            for _, j in subject_positions:
                subject_distribution[j - 1] += 1.0
            subject_distribution /= subject_distribution.sum()
            strength = 0.96 if copular else 0.55
            residual = (
                (1.0 - strength) * residual
                + strength * subject_distribution
            )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_copular_subject", make_row_stochastic(attention)


def prog_L8H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with lexical-category gating and weak local syntactic attention.
    Sentence starts, punctuation, and fragmented words strengthen the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    sink_by_pos = {
        "NOUN": 0.78, "PROPN": 0.85, "PRON": 0.75,
        "DET": 0.79, "ADJ": 0.66, "ADV": 0.65,
        "VERB": 0.49, "AUX": 0.61, "ADP": 0.64,
        "PART": 0.61, "CCONJ": 0.68, "SCONJ": 0.70,
        "NUM": 0.76, "INTJ": 0.79, "PUNCT": 0.80,
        "SPACE": 0.92, "SYM": 0.88, "X": 0.79,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        sink = sink_by_pos.get(word.pos_, 0.72) if word is not None else 0.76

        if word is not None:
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                sink += 0.06
            if word.ent_type_:
                sink += 0.03
            if word.is_sent_start:
                sink = max(sink, 0.89)

            pieces = inverse[word.i]
            if len(pieces) > 1 and word.pos_ != "PUNCT":
                sink += 0.035
            if word.dep_ in ("ROOT", "conj") and word.pos_ == "VERB":
                sink -= 0.035

        if not clean or clean.isspace():
            sink = 0.93
        elif all(c in "'’`" for c in clean):
            sink = 0.92
        elif all(c in ".!?\"'’”" for c in clean):
            sink = 0.87
        elif all(c in ",;:" for c in clean):
            sink = 0.78 + 0.10 * np.exp(-i / 8.0)

        if raw in tokenizer.all_special_tokens:
            sink = 0.96
        if i == 1:
            sink = 0.96
        sink = float(np.clip(sink, 0.30, 0.98))

        # Residual attention combines recency with accessible syntactic anchors.
        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = np.exp(-(i - positions) / 3.0)
        residual[i] += 0.30

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_positions:
                residual[head_positions[-1]] += 1.5

            if word.pos_ in ("VERB", "AUX"):
                for child in word.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        subject_positions = [
                            j for j in inverse[child.i] if 0 < j < i
                        ]
                        if subject_positions:
                            residual[subject_positions[-1]] += 4.0

            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                residual[earlier_pieces[-1]] += 0.8

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    return "bos_sink_with_syntactic_residual", make_row_stochastic(attention)


def prog_L8H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with stronger noun-coordination boundaries and a short-lived
    attention anchor at the end of a fronted prepositional phrase."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Restrict the fronted-phrase exception to a PP followed by a pronoun.
    front_anchor = None
    front_follow = None
    if len(doc) and doc[0].pos_ == "ADP":
        for w in doc:
            if w.dep_ == "pobj" and w.head.i == 0:
                following = w.i + 1
                while following < len(doc) and doc[following].is_space:
                    following += 1
                if following < len(doc) and doc[following].pos_ == "PRON":
                    candidates = [
                        j for j in range(1, n) if w.i in alignment[j]
                    ]
                    if candidates:
                        front_anchor = candidates[-1]
                        front_follow = following
                break

    sink_by_pos = {
        "NOUN": 0.925,
        "PROPN": 0.945,
        "DET": 0.935,
        "ADJ": 0.915,
        "VERB": 0.885,
        "AUX": 0.875,
        "PRON": 0.890,
        "ADP": 0.895,
        "ADV": 0.850,
        "PART": 0.865,
        "NUM": 0.930,
        "SCONJ": 0.865,
        "CCONJ": 0.790,
        "PUNCT": 0.805,
        "SPACE": 0.865,
    }

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        sink = sink_by_pos.get(word.pos_, 0.885) if word is not None else 0.885
        target = None

        if i == 1 and word is not None:
            sink = 0.800 if word.pos_ == "DET" else 0.935

        if word is not None and word.pos_ == "CCONJ":
            previous = word.i - 1
            while previous >= 0 and doc[previous].is_space:
                previous -= 1
            if previous >= 0:
                candidates = [
                    j for j in range(1, i)
                    if previous in alignment[j]
                ]
                if candidates:
                    target = candidates[-1]
                    if doc[previous].pos_ == "ADJ":
                        sink = 0.170
                    elif doc[previous].pos_ == "VERB":
                        sink = 0.650

        attention[i, 0] = sink
        if target is not None:
            attention[i, target] += 1.0 - sink
        else:
            positions = np.arange(1, i + 1)
            local = np.exp(-(i - positions) / 2.0)
            local /= local.sum()
            attention[i, 1:i + 1] = (1.0 - sink) * local

        # Transfer only BOS mass; preserve the original self/local weights.
        if word is not None and word.pos_ == "CCONJ":
            previous = word.i - 1
            crossed_comma = False
            while previous >= 0 and (
                doc[previous].is_space or doc[previous].text == ","
            ):
                crossed_comma |= doc[previous].text == ","
                previous -= 1
            if previous >= 0 and doc[previous].pos_ in ("NOUN", "PROPN"):
                anchors = [previous]
                if crossed_comma and doc[previous].dep_ == "conj":
                    head = doc[previous].head
                    if head.i < previous and head.pos_ in ("NOUN", "PROPN"):
                        anchors.append(head.i)
                targets = []
                for anchor in anchors:
                    candidates = [
                        j for j in range(1, i) if anchor in alignment[j]
                    ]
                    if candidates:
                        targets.append(candidates[-1])
                if targets:
                    extra = min(
                        attention[i, 0], 0.60 if len(targets) > 1 else 0.36
                    )
                    attention[i, 0] -= extra
                    for j in targets:
                        attention[i, j] += extra / len(targets)

        if (
            front_anchor is not None
            and front_anchor < i
            and word is not None
            and 0 <= word.i - front_follow < 4
            and word.pos_ in ("PRON", "AUX", "VERB", "DET")
        ):
            desired = (0.73, 0.50, 0.62, 0.22)[word.i - front_follow]
            extra = min(
                attention[i, 0],
                max(0.0, desired - attention[i, front_anchor]),
            )
            attention[i, 0] -= extra
            attention[i, front_anchor] += extra

    return "bos_sink_with_boundary_anchors", make_row_stochastic(attention)


def prog_L8H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with weak linguistic modulation.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        word = words[-1] if words else None

        # The opening tokens almost exclusively select the initial sink.
        early = np.exp(-(i - 1) / 6.0)
        modulation = 1.0 - np.exp(-(i - 1) / 3.0)
        sink_mass = 0.75 + 0.225 * early
        correction = 0.0

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "VERB"):
                correction += 0.055
            elif word.pos_ == "ADJ":
                correction += 0.015
            elif word.pos_ in ("CCONJ", "SCONJ"):
                correction -= 0.13
            elif word.pos_ in ("DET", "ADP", "PART", "AUX"):
                correction -= 0.055

            if word.dep_ in ("ROOT", "nsubj", "csubj"):
                correction += 0.025
            if word.ent_type_:
                correction += 0.02

            if word.is_punct:
                if word.is_sent_end:
                    correction += 0.085
                else:
                    correction -= 0.07

        # Apostrophe pieces often retain unusually strong sink attention.
        if tokens[i].strip() in ("'", "’"):
            correction += 0.15

        sink_mass = float(np.clip(
            sink_mass + modulation * correction, 0.55, 0.992
        ))

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.6 / i + 0.4 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L8H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local clause-boundary exception: commas and opening
    quotation marks route some sink mass to the preceding predicate.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_predicate", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    strength_by_pos = {
        "NOUN": 0.950,
        "PROPN": 0.935,
        "ADJ": 0.935,
        "VERB": 0.910,
        "ADV": 0.875,
        "ADP": 0.885,
        "CCONJ": 0.900,
        "SCONJ": 0.835,
        "DET": 0.860,
        "PRON": 0.835,
        "AUX": 0.825,
        "PART": 0.865,
        "NUM": 0.905,
        "INTJ": 0.890,
        "PUNCT": 0.915,
    }

    pieces = [t.lstrip("▁Ġ").strip() for t in tokens]
    word_ends = {}
    for ti, aligned in enumerate(alignment):
        if ti > 0:
            for k in aligned:
                word_ends[k] = ti

    for i in range(1, n):
        aligned = alignment[i]
        sink = 0.890
        if aligned:
            strengths = [
                strength_by_pos.get(doc[k].pos_, 0.890)
                for k in aligned
            ]
            sink = float(np.mean(strengths))

        # Keep the unobserved residual broad, with a modest local preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 3.0)
        local /= local.sum()
        background = 0.5 / i + 0.5 * local

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

        # Boundary exception: transfer only BOS mass, preserving self-attention
        # and all background edges other than the selected boundary targets.
        is_comma = pieces[i] == ","
        is_quote = pieces[i] in ('"', "“", "‘")
        comma = i if is_comma else -1
        if is_quote:
            for j in range(i - 1, max(0, i - 3), -1):
                if pieces[j] == ",":
                    comma = j
                    break
                if pieces[j]:
                    break

        if comma > 1 and (is_comma or is_quote):
            preceding = [
                k for k, end in word_ends.items()
                if 0 < end < comma and doc[k].pos_ != "SPACE"
            ]
            predicate = None
            if preceding:
                last = max(preceding)
                for k in range(last, max(-1, last - 5), -1):
                    if doc[k].is_punct:
                        break
                    if doc[k].pos_ == "VERB" and k in word_ends:
                        if 0 < word_ends[k] < comma:
                            predicate = word_ends[k]
                        break

            targets = {}
            if is_comma:
                next_piece = i + 1
                while next_piece < n and not pieces[next_piece]:
                    next_piece += 1
                introduces_quote = (
                    next_piece < n
                    and pieces[next_piece] in ('"', "“", "‘")
                )
                strong_boundary = predicate is not None and (
                    introduces_quote or predicate == i - 1
                )
                target_sink = 0.45 if strong_boundary else 0.74
                if strong_boundary:
                    targets[predicate] = 0.80
                    targets[i - 1] = targets.get(i - 1, 0.0) + 0.20
                else:
                    targets[i - 1] = 1.0
            elif predicate is not None:
                target_sink = 0.43
                targets[predicate] = 0.65
                targets[comma] = targets.get(comma, 0.0) + 0.35
            else:
                target_sink = sink

            transfer = max(0.0, attention[i, 0] - target_sink)
            if transfer > 0.0 and targets:
                attention[i, 0] -= transfer
                for j, weight in targets.items():
                    attention[i, j] += transfer * weight

    return "bos_sink_boundary_predicate", attention


def prog_L8H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: overwhelmingly attend to the first token,
    with a small diffuse, recency-biased causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_remainder", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 8.0)
        remainder = 0.5 / i + 0.5 * recent / recent.sum()
        attention[i, 0] = 0.94
        attention[i, 1:i + 1] = 0.06 * remainder

    return "bos_sink_with_diffuse_remainder", attention


def prog_L8H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token,
    with a small diffuse residual over other causally available tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.992
            attention[i, 1:i + 1] = 0.008 / i

    return "bos_sink_with_diffuse_residual", attention


def prog_L8H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and at punctuation.
    Remaining attention is diffuse with a weak causal recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boost", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in aligned[i]]
        pos = words[0].pos_ if words else ""

        # A stable sink remains dominant even well into the sequence.
        sink = 0.53 + 0.30 * np.exp(-(i - 1) / 3.0)
        if i == 1:
            sink = 0.93

        # Small linguistic corrections, not explicit syntactic retrieval.
        if pos in ("DET", "PRON"):
            sink += 0.055
        elif pos in ("ADP", "AUX", "CCONJ"):
            sink += 0.025
        elif pos in ("VERB", "ADJ", "ADV"):
            sink -= 0.025

        punctuation = bool(text) and all(
            not c.isalnum() and not c.isspace() for c in text
        )
        if punctuation:
            if any(c in ".!?" for c in text):
                sink = max(sink, 0.79 if i == n - 1 else 0.66)
            elif "," in text or ";" in text or ":" in text:
                sink = max(sink, 0.68 + 0.14 * np.exp(-i / 6.0))
            elif "'" in text or "’" in text:
                sink = max(sink, 0.78)
            else:
                sink = max(sink, 0.60)
        elif not text:
            sink = max(sink, 0.64)

        sink = float(np.clip(sink, 0.40, 0.96))
        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 7.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_boundary_boost", attention


def prog_L8H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the initial token,
    independently of lexical content or syntactic structure.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    attention[:, 0:1] = 1.0
    return "bos_attention_sink", attention


def prog_L8H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a selective lexical-recurrence path.
    Repeated content words and pronouns divert BOS mass to earlier occurrences.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_lexical_recurrence", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.98
        attention[i, 1:i + 1] = 0.02 / i

    # Only the recurrence path modifies the default: transfer mass from BOS
    # to an earlier matching token, leaving self-attention/background intact.
    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    eligible = {"NOUN", "PROPN", "VERB", "ADJ", "PRON"}

    for i in range(1, n):
        if not alignment[i]:
            continue
        current_sid = alignment[i][0]
        current = doc[current_sid]
        if current.pos_ not in eligible:
            continue

        threshold = 0.72 if current.pos_ == "VERB" else 0.88
        if current.pos_ == "PRON":
            threshold = 0.99

        best_j, best_similarity = -1, threshold
        for j in range(1, i):
            if not alignment[j]:
                continue
            earlier_sid = alignment[j][0]
            if earlier_sid >= current_sid:
                continue
            earlier = doc[earlier_sid]
            if earlier.pos_ != current.pos_:
                continue
            similarity = embedding_similarity(tokens, i, j, tokenizer)
            if similarity >= best_similarity:
                best_j, best_similarity = j, similarity

        if best_j < 0:
            continue

        earlier = doc[alignment[best_j][0]]
        if current.pos_ == "PRON":
            mass = 0.28
            if current.dep_ in {"nsubj", "nsubjpass"}:
                mass = 0.20 if best_j == 1 else 0.025
        elif current.pos_ in {"NOUN", "PROPN"}:
            mass = 0.66
            if current.dep_ in {"nsubj", "nsubjpass"}:
                mass = (
                    0.30
                    if earlier.dep_ in {"nsubj", "nsubjpass"}
                    else 0.50
                )
            elif current.dep_ == "pobj":
                mass = 0.74
        elif current.pos_ == "VERB":
            mass = 0.375
        else:
            mass = 0.12

        mass = min(mass, attention[i, 0])
        attention[i, 0] -= mass
        attention[i, best_j] += mass

    return "bos_sink_with_lexical_recurrence", attention


def prog_L8H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant beginning-of-sequence attention sink.
    Distribute weak residual attention over causal positions with a recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = 0.96
        attention[i, 1:i + 1] = 0.04 * residual

    return "bos_sink_with_weak_recency", attention


def prog_L8H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with very weak, diffuse causal leakage.
    The first token dominates independently of syntactic or semantic features.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, :i + 1] = 0.0004
        attention[i, 0] = 1.0

    return "bos_sink_with_diffuse_leakage", make_row_stochastic(attention)


def prog_L8H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with sparse discourse links between related participants.
    Activate residual routing only for participant recurrence or multi-turn dialogue.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].lstrip("▁Ġ")
        is_punctuation = (
            bool(surface)
            and tokens[i] not in tokenizer.all_special_tokens
            and all(not c.isalnum() and not c.isspace() for c in surface)
        )
        is_whitespace = not surface or surface.isspace()

        background = 0.0009 * (1.0 + 0.01 * i)
        if is_punctuation:
            background *= 2.0
        elif is_whitespace:
            background *= 1.4

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = background

        # A small local component accounts for otherwise unobserved residual mass.
        distances = i - np.arange(1, i + 1)
        attention[i, 1:i + 1] += (
            0.0015 * np.exp(-distances / 3.0)
        )

    # Detect discourse recurrence, rather than weakening the sink globally.
    doc = spacy_parse(sentence)
    aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)
    pieces = [
        [i for i in ids if i > 0 and tokens[i] not in tokenizer.all_special_tokens]
        for ids in aligned
    ]
    nouns = [
        w for w in doc
        if w.pos_ in ("NOUN", "PROPN") and pieces[w.i]
    ]
    participant_deps = {
        "nsubj", "nsubjpass", "csubj", "dobj", "obj",
        "iobj", "attr", "appos", "poss"
    }
    noun_links = {}
    recurrence = False
    for k, word in enumerate(nouns):
        for previous in nouns[:k]:
            similarity = embedding_similarity(
                tokens, pieces[word.i][-1], pieces[previous.i][-1], tokenizer
            )
            if similarity >= 0.35:
                noun_links[word.i, previous.i] = similarity
                if (
                    word.dep_ in participant_deps
                    and previous.dep_ in participant_deps
                ):
                    recurrence = True

    dialogue = sum(sentence.count(c) for c in ('"', '“', '”')) >= 4

    if recurrence or dialogue:
        for word in doc:
            if not pieces[word.i]:
                continue

            targets = {}
            for previous in doc[:word.i]:
                if not pieces[previous.i]:
                    continue

                mass = 0.0
                if word.pos_ in ("NOUN", "PROPN"):
                    similarity = noun_links.get((word.i, previous.i), 0.0)
                    if similarity:
                        mass = 0.15 if similarity >= 0.80 else 0.17
                    elif (
                        dialogue
                        and previous.pos_ in ("NOUN", "PROPN")
                        and previous.dep_ in participant_deps
                    ):
                        mass = 0.025

                elif word.pos_ == "ADJ" and previous.pos_ == "ADJ":
                    if (word.head.i, previous.head.i) in noun_links:
                        mass = 0.085

                elif word.pos_ == "PRON" and previous.pos_ == "PRON":
                    similarity = embedding_similarity(
                        tokens, pieces[word.i][-1],
                        pieces[previous.i][-1], tokenizer
                    )
                    if dialogue and previous.dep_ == "poss":
                        mass = 0.24
                    elif similarity >= 0.55:
                        mass = 0.07

                elif dialogue and word.is_punct and previous.is_punct:
                    if (
                        any(c in word.text for c in '"“”')
                        and any(c in previous.text for c in '"“”')
                    ):
                        mass = 0.035
                    elif (
                        any(c in word.text for c in ".!?")
                        and any(c in previous.text for c in "'’")
                    ):
                        mass = 0.04

                if mass:
                    targets[pieces[previous.i][-1]] = mass

            if not targets:
                continue

            # Transfer mass from the sink: all unrelated entries, including
            # self-attention, retain their original normalized values.
            for part, i in enumerate(pieces[word.i]):
                eligible = {j: mass for j, mass in targets.items() if j < i}
                total = sum(eligible.values())
                if not total:
                    continue
                row_sum = attention[i].sum()
                budget = min(
                    total * (1.0 if part == 0 else 0.5),
                    0.48,
                    0.8 * attention[i, 0] / row_sum,
                )
                for j, mass in eligible.items():
                    attention[i, j] += row_sum * budget * mass / total
                attention[i, 0] -= row_sum * budget

    return "first_token_sink", make_row_stochastic(attention)


def prog_L8H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with small POS-dependent leakage to recent tokens.
    The dominant structure is positional rather than a syntactic relation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.94
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass = 0.89
            elif word.pos_ in ("PUNCT", "CCONJ", "SCONJ"):
                sink_mass = 0.87
            elif word.pos_ in ("ADJ", "ADV"):
                sink_mass = 0.90

        # Very early queries consistently give almost all their mass to BOS.
        if i == 1:
            sink_mass = 0.983
        elif i == 2:
            sink_mass = 0.5 * sink_mass + 0.5 * 0.97

        # No non-BOS destination is supported consistently by the examples;
        # use a weak, smooth causal recency prior for the residual mass.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_leakage", attention


def prog_L8H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the first token.
    Unobserved residual attention is modeled as diffuse over causal non-BOS tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.97
        attention[i, 1:i + 1] = 0.03 / i

    return "bos_sink_diffuse_residual", attention


def prog_L8H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak position-dependent dilution.
    Residual attention is diffuse, with a modest recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 - 0.035 * (1.0 - np.exp(-i / 24.0))
        distances = i - np.arange(1, i + 1)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 5.0) /
            np.exp(-distances / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_attention_sink", attention


def prog_L8H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak recency, plus sparse links between dialogue boundaries.
    Quotation punctuation and adjacent whitespace retrieve earlier quote anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_boundaries", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 4.0)
        recent /= recent.sum()

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = 0.0015 + 0.018 * recent

    # Only dialogue-boundary rows receive additional off-diagonal weights.
    # Keep the baseline diagonal, recency kernel, and all other rows intact.
    quote_anchors = []
    whitespace_anchors = []
    inside_quote = False

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        is_quote = any(c in text for c in ('"', '“', '”'))
        is_gap = not text and tokens[i] not in tokenizer.all_special_tokens
        is_apostrophe = text in ("'", "’")
        is_boundary = text in (",", ".", "!", "?", ";", ":")

        if quote_anchors and (
            is_quote
            or (is_gap and quote_anchors[-1][0] == i - 1)
            or (is_apostrophe and inside_quote)
            or (is_boundary and len(quote_anchors) >= 2)
        ):
            for j, opening in quote_anchors[-6:]:
                strength = 0.045 if opening else 0.028
                attention[i, j] += strength * np.exp(-(i - j) / 100.0)

            if is_quote or is_apostrophe or text == ",":
                for j in whitespace_anchors[-2:]:
                    attention[i, j] += 0.022 * np.exp(-(i - j) / 60.0)

        if is_gap and quote_anchors and quote_anchors[-1][0] == i - 1:
            whitespace_anchors.append(i)

        if is_quote:
            quote_anchors.append((i, not inside_quote))
            inside_quote = not inside_quote

    return "bos_sink_with_dialogue_boundaries", make_row_stochastic(attention)


def prog_L8H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: nearly all mass goes to the initial token.
    A small causal residual is diffuse, with a mild recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.945
        aligned = alignment[i]
        if aligned:
            if all(doc[k].is_punct or doc[k].is_space for k in aligned):
                sink_mass = 0.87

        # Preserve strong sink attention without imposing an unsupported
        # syntactic target on the small remaining mass.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L8H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal background attention.
    Sink strength decreases slightly as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_background", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 - 0.035 * (1.0 - np.exp(-i / 40.0))

        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.7 / i + 0.3 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_weak_background", attention


def prog_L8H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak lexical-class modulation.
    Residual attention is spread causally with a mild recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_pos_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.85
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink_mass = 0.88
            elif pos in ("VERB", "AUX"):
                sink_mass = 0.86
            elif pos in ("ADJ", "ADP", "PART"):
                sink_mass = 0.84
            elif pos in ("DET", "NUM"):
                sink_mass = 0.83
            elif pos in ("ADV", "SCONJ", "CCONJ"):
                sink_mass = 0.78
            elif pos == "PRON":
                sink_mass = 0.76
            elif pos == "PUNCT":
                sink_mass = 0.73

        # The initial query strongly selects BOS regardless of syntax.
        if i == 1:
            sink_mass = 0.97
        elif i <= 3:
            sink_mass += 0.05 * np.exp(-0.5 * (i - 2))

        # Do not force an artificial syntactic target for the unobserved
        # residual: use a broad, weakly local causal distribution.
        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_pos_modulation", attention


def prog_L8H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a targeted previous-piece exception for split words.
    Preserve the diffuse baseline and self-attention outside that exception.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0

    for i in range(1, n):
        attention[i, 0] = 0.94
        attention[i, 1:i + 1] = 0.06 / i

    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    for i in range(2, n):
        current = tokens[i]
        previous = tokens[i - 1]
        if current in special_tokens or previous in special_tokens:
            continue
        if current.startswith(("▁", "Ġ", "Ċ")):
            continue

        same_word = any(k in aligned[i - 1] for k in aligned[i])
        split_word = current.isalpha() and same_word

        # Adjacent non-ASCII pieces can encode a fragmented symbol or
        # malformed quotation mark rather than an ordinary word.
        previous_piece = previous.lstrip("▁Ġ")
        fragmented_symbol = (
            bool(current)
            and bool(previous_piece)
            and not current.isascii()
            and not previous_piece.isascii()
            and not current.isalpha()
            and not current.isspace()
        )

        if split_word or fragmented_symbol:
            target = 0.44 if fragmented_symbol else 0.12
            transfer = min(
                attention[i, 0],
                max(0.0, target - attention[i, i - 1]),
            )
            attention[i, 0] -= transfer
            attention[i, i - 1] += transfer

    return "bos_sink_with_split_piece_exception", attention


def prog_L8H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for content tokens, with a weak causal-local tail."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_tail", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.94
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.975
            elif word.pos_ == "ADJ":
                sink_mass = 0.96
            elif word.pos_ == "VERB":
                sink_mass = 0.95
            elif word.pos_ == "ADV":
                sink_mass = 0.945
            elif word.pos_ in ("PRON", "DET", "AUX"):
                sink_mass = 0.92
            elif word.pos_ in ("ADP", "PART", "CCONJ", "SCONJ"):
                sink_mass = 0.90
            elif word.is_punct:
                sink_mass = 0.87

        # At the beginning of the sequence the sink is especially dominant.
        if i == 1:
            sink_mass = 0.967

        positions = np.arange(1, i + 1)
        tail = np.exp(-(i - positions) / 3.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * tail / tail.sum()
        attention[i, 0] = sink_mass

    return "bos_sink_with_local_tail", attention


def prog_L8H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized leakage around names, quoted speech, and split modifiers.
    Special cases transfer only BOS mass, preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_salience", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Identify word-final pieces so a split name is not counted multiple times.
    word_ends = {}
    for j in range(1, n):
        for k in alignment[j]:
            word_ends[k] = j

    quote_chars = "\"“”«»"
    has_quotes = any(c in sentence for c in quote_chars)

    for i in range(1, n):
        sink_mass = 0.977
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink_mass = 0.955
            elif word.pos_ in ("ADP", "DET", "CCONJ", "SCONJ", "PART"):
                sink_mass = 0.985
            elif word.pos_ == "PROPN":
                sink_mass = 0.963
            elif word.pos_ in ("PRON", "AUX"):
                sink_mass = 0.979

        # Keep the default distribution, including its self-attention, unchanged.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 1.0 + 0.25 * np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )
        attention[i, 0] = sink_mass

        # Sparse additions are funded exclusively from the BOS sink.
        additions = {}
        if aligned:
            word = doc[aligned[0]]
            for k, j in word_ends.items():
                if not (1 <= j < i and i - j <= 6):
                    continue
                previous = doc[k]
                distance = i - j
                amount = 0.0

                # Names create a short-lived local anchor, especially in speech.
                if previous.pos_ == "PROPN":
                    amount = 0.040 / distance
                    if has_quotes and word.pos_ in ("PRON", "PUNCT"):
                        amount = 0.105 / distance
                    elif has_quotes and word.pos_ == "PROPN":
                        amount = 0.085 / distance

                # A name following an introductory nominal phrase.
                if (
                    word.pos_ == "PROPN"
                    and previous.pos_ == "NOUN"
                    and distance <= 2
                    and k < 4
                ):
                    amount = max(amount, 0.085 / distance)

                # Split adjectival modifiers can become strong local anchors.
                if (
                    previous.pos_ == "ADJ"
                    and word.pos_ in ("ADJ", "NOUN")
                    and distance <= 3
                    and sum(k in a for a in alignment[max(1, j - 3):j + 1]) > 1
                ):
                    amount = max(amount, 0.060 / distance)

                if amount:
                    additions[j] = amount

        # Matching quote boundaries receive a small, nonlocal connection.
        if has_quotes and any(c in tokens[i] for c in quote_chars):
            for j in range(i - 1, 0, -1):
                if any(c in tokens[j] for c in quote_chars):
                    additions[j] = additions.get(j, 0.0) + 0.035
                    break

        if additions:
            total = sum(additions.values())
            scale = min(1.0, 0.14 / total, attention[i, 0] / total)
            for j, amount in additions.items():
                attention[i, j] += scale * amount
            attention[i, 0] -= scale * total

    return "bos_sink_with_local_salience", attention


def prog_L8H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent leakage.
    Content tokens retain stronger sink attention than verbs and punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_mild_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        pos = ""
        if alignment[i]:
            pos = doc[alignment[i][0]].pos_

        if pos in ("NOUN", "PROPN", "ADJ", "NUM"):
            factor = 0.65
        elif pos == "VERB":
            factor = 1.45
        elif pos == "PUNCT":
            factor = 2.1
        elif pos in ("CCONJ", "SCONJ", "ADV"):
            factor = 1.25
        else:
            factor = 1.0

        leakage = np.clip((0.018 + 0.0017 * i) * factor, 0.012, 0.32)

        # Most residual attention is diffuse; a small component is local.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * (
            np.exp((positions - i) / 5.0)
            / np.exp((positions - i) / 5.0).sum()
        )
        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_mild_leakage", make_row_stochastic(attention)


def prog_L8H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: almost all mass targets the first token.
    The small residual is diffuse, with a weak causal recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 8.0)
        recent /= recent.sum()
        residual = 0.7 / i + 0.3 * recent

        attention[i, 0] = 0.975
        attention[i, 1:i + 1] = 0.025 * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L8H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with a transient competing sink in a fronted adjunct.
    Redirect only BOS mass to earlier adjunct tokens, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        sink_mass = 0.96 + 0.025 * np.exp(-(i - 1) / 3.0)
        positions = np.arange(1, i + 1)
        residual = 0.5 + 0.5 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    doc = spacy_parse(sentence)
    phrase = []
    prepositional = False

    if len(doc) and doc[0].pos_ == "ADP":
        objects = [w for w in doc[0].children if w.dep_ == "pobj"]
        if objects:
            phrase = sorted(
                [doc[0].i] + [w.i for w in objects[0].subtree]
            )
            prepositional = True
    elif len(doc):
        for w in doc[:4]:
            if w.pos_ == "NOUN" and w.dep_ in ("npadvmod", "obl"):
                candidate = sorted(t.i for t in w.subtree)
                if candidate and candidate[0] == 0:
                    phrase = candidate
                    break

    # Restrict the exception to a short, sentence-initial adjunct.
    if phrase and len(phrase) <= 5:
        end = phrase[-1]
        comma = end + 1 < len(doc) and doc[end + 1].text == ","
        if prepositional or comma:
            mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
            anchors = sorted({
                j for k in phrase for j in mapping[k] if j > 0
            })
            if anchors:
                last = anchors[-1]
                if not prepositional:
                    profile = (0.05, 0.86, 0.79, 0.42, 0.44, 0.025)
                    weights = np.array([
                        8.0 if j == last else 1.0 for j in anchors
                    ])
                elif comma:
                    profile = (0.40, 0.90, 0.52, 0.02, 0.74, 0.13)
                    weights = np.array([
                        5.0 if j == last else
                        3.0 if any(
                            doc[k].pos_ == "DET"
                            for k in phrase if j in mapping[k]
                        ) else 2.0
                        for j in anchors
                    ])
                else:
                    profile = (0.07, 0.70, 0.67, 0.55, 0.29,
                               0.12, 0.15, 0.21, 0.21)
                    weights = np.array([
                        5.8 if any(
                            doc[k].pos_ == "DET"
                            for k in phrase if j in mapping[k]
                        ) else 3.2 if j == anchors[0] else 1.0
                        for j in anchors
                    ])

                anchors = np.asarray(anchors, dtype=int)
                for offset, mass in enumerate(profile):
                    i = last + offset
                    if i >= n:
                        break
                    eligible = anchors < i
                    if not np.any(eligible):
                        continue
                    distribution = weights[eligible]
                    distribution = distribution / distribution.sum()
                    transfer = min(mass, attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i, anchors[eligible]] += transfer * distribution

    return "first_token_sink_with_fronted_adjunct_competition", attention


def prog_L8H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak POS-dependent strength and diffuse causal leakage."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.89
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.04
            elif word.pos_ in ("ADJ", "NUM"):
                sink_mass += 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.035
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.02

        # Early queries have fewer competing keys.
        sink_mass += 0.025 * np.exp(-(i - 1) / 4.0)
        sink_mass = np.clip(sink_mass, 0.80, 0.97)

        # The examples identify the sink much more clearly than residual targets;
        # keep the latter diffuse, with only a mild local preference.
        distances = i - np.arange(1, i + 1)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_linguistic_modulation", attention


def prog_L8H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent decay.
    Punctuation and whitespace strengthen the sink; residual attention is diffuse-causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boost", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()

        # The dominant destination is the initial token, not a syntactic head.
        sink = 0.60 + 0.375 / (1.0 + 0.22 * (i - 1))

        if not text:
            sink = max(sink, 0.82 + 0.04 * np.exp(-i / 30.0))
        elif all(c in "'’‘`" for c in text):
            sink = max(sink, 0.76 + 0.17 * np.exp(-i / 35.0))
        elif all(c in ".,!?;:\"'“”‘’`()[]{}—–-" for c in text):
            if "." in text:
                boundary_sink = 0.56 + 0.40 * np.exp(-i / 70.0)
            elif "!" in text or "?" in text:
                boundary_sink = 0.60 + 0.30 * np.exp(-i / 35.0)
            elif "," in text or ";" in text or ":" in text:
                boundary_sink = 0.57 + 0.39 * np.exp(-i / 28.0)
            else:
                boundary_sink = 0.60 + 0.30 * np.exp(-i / 30.0)
            sink = max(sink, boundary_sink)

        sink = float(np.clip(sink, 0.0, 0.99))
        attention[i, 0] = sink

        # The examples constrain the sink much more than other destinations.
        # Use a diffuse residual with only a modest preference for recent keys.
        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_boundary_boost", make_row_stochastic(attention)


def prog_L8H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink with weak local and syntactic leakage.
    Sink strength increases near the start and at discourse boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            inverse[word_id].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        sink = 0.865 + 0.075 * np.exp(-(i - 1) / 8.0)
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink += 0.025
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ"):
                sink -= 0.055
            elif word.pos_ == "PUNCT":
                sink -= 0.025

            if word.is_sent_start:
                sink += 0.025
            if word.ent_type_:
                sink += 0.015
        elif tokens[i].replace("▁", "").replace("Ġ", "").isspace() or tokens[i] in ("▁", "Ġ"):
            sink += 0.055

        sink = float(np.clip(sink, 0.72, 0.975))

        # The non-sink mass remains diffuse, with a mild recency preference.
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        # A small causal dependency correction, rather than a competing head.
        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_positions:
                residual *= 0.9
                for j in head_positions:
                    residual[j - 1] += 0.1 / len(head_positions)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_leakage", make_row_stochastic(attention)


def prog_L9H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink with a weak, diffuse causal tail.
    The tail's total mass grows slowly with the available context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            sink_mass = 1.0 / (1.0 + 0.008 + 0.0004 * i)
            attention[i, 0] = sink_mass
            attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "first_token_sink_with_diffuse_tail", attention


def prog_L9H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild positional and POS modulation.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The examples overwhelmingly favor position zero across word classes.
        sink_mass = 0.76 + 0.11 * np.exp(-(i - 1) / 22.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass -= 0.10
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                sink_mass -= 0.025

        if tokens[i] in tokenizer.all_special_tokens:
            sink_mass -= 0.05

        sink_mass = float(np.clip(sink_mass, 0.55, 0.94))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", make_row_stochastic(attention)


def prog_L9H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Punctuation and clause boundaries strengthen the sink over a diffuse causal background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_strength = 17.0
        indices = aligned[i]

        if indices:
            word = doc[indices[0]]
            if word.is_space:
                sink_strength *= 2.0
            elif word.is_punct:
                sink_strength *= 1.7
            else:
                if word.pos_ in ("DET", "PRON", "PROPN"):
                    sink_strength *= 1.15
                elif word.pos_ in ("VERB", "AUX"):
                    sink_strength *= 0.85

                if word.dep_ in ("nsubj", "nsubjpass", "cc", "mark"):
                    sink_strength *= 1.15

                if word.is_sent_start:
                    sink_strength *= 1.3
        elif tokens[i].replace("▁", "").replace("Ġ", "").strip() == "":
            sink_strength *= 2.0

        # Keep the residual broad: the examples support a sink much more
        # clearly than any particular non-BOS syntactic destination.
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.85 + 0.15 * np.exp(-(i - positions) / 8.0)
        attention[i, 0] = sink_strength
        attention[i, 1:i + 1] = background

    return "bos_sink_with_positional_dilution", make_row_stochastic(attention)


def prog_L9H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; later clause punctuation pools earlier content.
    Punctuation redistributes sink/local mass without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_pooling", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        decay = 0.12 * (1.0 - np.exp(-i / 24.0))

        if pos in ("NOUN", "PROPN"):
            sink = 0.95 - decay
        elif pos in ("ADJ", "NUM"):
            sink = 0.91 - decay
        elif pos == "VERB":
            sink = 0.85 - decay
        elif pos in ("DET", "ADP"):
            sink = 0.86 - decay
        elif pos in ("AUX", "CCONJ", "SCONJ", "PUNCT"):
            sink = 0.66 - decay
        elif pos == "PRON":
            sink = 0.77 - decay
        else:
            sink = 0.80 - decay

        if i == 1:
            sink = 0.94
        elif i <= 3:
            sink = max(sink, 0.90)

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = 0.10
        residual[i - 1] += 0.65
        if i > 2:
            residual[1:i] += 0.08 * np.exp(
                -np.arange(i - 1, 0, -1) / 3.0
            )

        if word is not None:
            head_indices = inverse[word.head.i]
            earlier_heads = [j for j in head_indices if 0 < j < i]
            if earlier_heads:
                residual[earlier_heads[-1]] += 0.30

            if pos == "PRON" and i > 3:
                candidates = [
                    w for w in doc[:word.i]
                    if w.pos_ in ("NOUN", "PROPN")
                    and inverse[w.i]
                    and inverse[w.i][-1] < i
                ]
                if candidates:
                    antecedent = candidates[-1]
                    residual[inverse[antecedent.i][-1]] += 0.45
                    sink = max(0.40, sink - 0.12)

            if pos in ("AUX", "CCONJ", "ADP", "PUNCT") and i > 2:
                previous = aligned[i - 1]
                if previous and doc[previous[-1]].pos_ in (
                    "NOUN", "PROPN", "ADJ"
                ):
                    sink = max(0.34, sink - 0.18)
                    residual[i - 1] += 0.50

        residual[0] = 0.0
        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

        # Clause-ending punctuation has a distributed content-summary channel,
        # rather than concentrating its residual on the immediately prior token.
        if (
            i >= 8
            and pos == "PUNCT"
            and any(ch in ".,!?;:" for ch in tokens[i])
        ):
            summary = np.zeros(i + 1, dtype=np.float64)
            for w in doc[:word.i]:
                if w.pos_ not in (
                    "NOUN", "PROPN", "VERB", "ADJ", "ADV", "ADP", "PRON"
                ):
                    continue
                earlier = [j for j in inverse[w.i] if 0 < j < i - 1]
                if not earlier:
                    continue
                j = earlier[-1]
                weight = 1.0 if w.pos_ in (
                    "NOUN", "PROPN", "VERB", "ADJ"
                ) else 0.55
                summary[j] += weight * np.exp(-(i - j) / 24.0)

            if summary.sum() > 0.0:
                terminal = any(ch in ".!?" for ch in tokens[i])
                target_sink = 0.15 if terminal else 0.24
                moved = max(0.0, attention[i, 0] - target_sink)
                attention[i, 0] -= moved

                previous = aligned[i - 1]
                previous_pos = doc[previous[-1]].pos_ if previous else ""
                fraction = 0.80 if previous_pos in (
                    "NOUN", "PROPN"
                ) else 0.40
                local_mass = fraction * attention[i, i - 1]
                attention[i, i - 1] -= local_mass
                attention[i, :i + 1] += (
                    (moved + local_mass) * summary / summary.sum()
                )

    return "bos_sink_with_punctuation_pooling", make_row_stochastic(attention)


def prog_L9H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and at clause boundaries.
    Residual attention is diffuse and recency-biased, with a weak syntactic prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = surface.strip()

        sink = 0.55 + 0.29 * np.exp(-(i - 1) / 6.0)

        if word is not None:
            pos, dep = word.pos_, word.dep_
            if pos in ("NOUN", "PROPN"):
                sink -= 0.10
            elif pos in ("ADJ", "ADV"):
                sink -= 0.04
            elif pos in ("AUX", "SCONJ", "CCONJ"):
                sink += 0.12
            elif pos in ("ADP", "PART"):
                sink += 0.07
            elif pos == "VERB":
                sink += 0.07

            if dep in ("nsubj", "nsubjpass", "csubj", "ROOT"):
                sink += 0.05
            if dep in ("conj", "advcl", "ccomp", "parataxis"):
                sink += 0.05
            if pos == "PUNCT":
                sink += 0.10
                if word.head.pos_ in ("VERB", "AUX"):
                    sink += 0.10

        if not stripped:
            sink = max(sink, 0.88)
        elif all(c in "\"'“”‘’!?«»" for c in stripped):
            sink = max(sink, 0.81)

        # With only one preceding position, the sink is especially stable.
        if i == 1:
            sink = max(sink, 0.87)
        sink = float(np.clip(sink, 0.30, 0.95))

        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 0.65

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_boundary_modulation", attention


def prog_L9H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and weaker clause-subject anchors.
    Punctuation and fragmentary tokens preferentially retain attention on BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    special_tokens = set(tokenizer.all_special_tokens)
    subjects = []
    boundaries = []
    for word in doc:
        indices = [
            ti for ti in inverse[word.i]
            if ti > 0 and tokens[ti] not in special_tokens
        ]
        if not indices:
            continue
        terminal = indices[-1]
        if (
            word.dep_ in ("nsubj", "nsubjpass", "nsubj:pass")
            and word.pos_ in ("NOUN", "PROPN")
        ):
            subjects.append(terminal)
        if word.is_punct and any(c in word.text for c in ".!?"):
            boundaries.append(terminal)

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        distances = i - positions
        attention[i, 1:i + 1] = 0.48 + 0.24 * np.exp(-distances / 7.0)
        attention[i, i] += 0.30

        mapped = alignment[i]
        word = doc[mapped[-1]] if mapped else None
        sink = 10.8

        if word is not None:
            if word.is_punct:
                sink *= 1.30
                if any(c in tokens[i] for c in "'’"):
                    sink *= 1.65
                elif any(c in tokens[i] for c in ".!?"):
                    sink *= 1.35
            elif word.pos_ in ("DET", "ADP", "AUX"):
                sink *= 1.12
            elif word.pos_ in ("VERB", "ADV"):
                sink *= 0.88

            pieces = inverse[word.i]
            if pieces and i != pieces[0] and not word.is_punct:
                attention[i, pieces[0]] += 0.45
        else:
            sink *= 1.30

        attention[i, 0] = sink

        eligible = [j for j in subjects if j <= i]
        if eligible:
            anchor = eligible[-1]
            strength = 8.0 * min(1.0, anchor / 22.0)
            strength *= min(1.0, i / 20.0)
            strength *= np.exp(-max(0, i - anchor - 20) / 45.0)
            attention[i, anchor] += strength

        previous_boundaries = [j for j in boundaries if j < i]
        if previous_boundaries:
            boundary = previous_boundaries[-1]
            attention[i, boundary] += 1.5 * np.exp(
                -(i - boundary) / 16.0
            )

    return "bos_sink_with_clause_anchors", make_row_stochastic(attention)


def prog_L9H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant BOS attention sink with a small, diffuse causal background.
    The examples support positional anchoring rather than syntactic targeting.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.95
        attention[i, 1:i + 1] = 0.05 / i

    return "bos_attention_sink", attention


def prog_L9H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and on descriptive tokens.
    Predicate chains and anaphoric arguments leave more residual causal attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        piece = tokens[i]
        clean = piece.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        # Early queries are almost entirely absorbed by the initial token.
        early = np.exp(-(i - 1) / 4.5)
        sink = 0.76

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("NOUN", "PROPN"):
                sink += 0.08
            elif pos in ("ADJ", "ADV"):
                sink += 0.07
            elif pos == "VERB":
                sink -= 0.09
            elif pos == "AUX":
                sink -= 0.12
            elif pos == "PRON":
                sink -= 0.16
            elif pos == "PART":
                sink -= 0.14
            elif pos in ("DET", "ADP"):
                sink -= 0.03

            if dep in ("xcomp", "ccomp", "aux", "auxpass"):
                sink -= 0.08
            elif dep in ("amod", "compound", "poss"):
                sink += 0.04

            if word.ent_type_:
                sink += 0.04

        # Whitespace and punctuation frequently retain strong sink attention.
        if not clean:
            sink = 0.96
        elif all(not c.isalnum() for c in clean):
            sink = 0.84

        sink = sink * (1.0 - early) + 0.98 * early
        sink = float(np.clip(sink, 0.38, 0.99))

        # The examples constrain the sink much more than the residual targets.
        # Use a broad causal background with only a mild recency preference.
        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_gating", attention


def prog_L9H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clause-boundary release onto preceding context.
    Boundary corrections transfer only BOS mass, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None

        sink = 0.78 + 0.17 * np.exp(-i / 28.0)
        if i == 1:
            sink -= 0.045

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "AUX"):
                sink += 0.025
            elif word.pos_ == "PRON":
                sink -= 0.035
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink -= 0.045
            elif word.pos_ == "PUNCT":
                sink -= 0.12 * (1.0 - np.exp(-i / 12.0))

        sink = np.clip(sink, 0.55, 0.975)

        # Original default behavior, including its self-attention weights.
        distances = i - np.arange(1, i + 1)
        residual = 0.75 * np.exp(-distances / 3.0)
        residual += 0.25 * np.exp(-distances / 16.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 1 <= j <= i:
                    residual[j - 1] += 0.15

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Clause-ending punctuation releases sink mass; apostrophes and
        # quotation marks deliberately retain the original behavior.
        punctuation = tokens[i].lstrip("▁Ġ").strip()
        if i > 1 and punctuation in (".", ",", ";", ":", "!", "?"):
            target_sink = (
                0.18 if punctuation == "."
                else 0.55 if punctuation in ("!", "?")
                else 0.52
            )
            released = max(0.0, attention[i, 0] - target_sink)
            if released > 0.0:
                # Broad preceding context plus a boundary-adjacent peak.
                # Exclude both BOS and the query itself from this transfer.
                weights = np.exp(-(i - np.arange(1, i)) / 16.0)
                weights /= weights.sum()
                peak = 0.15 if punctuation == "." else 0.50
                weights *= 1.0 - peak
                weights[-1] += peak

                attention[i, 0] -= released
                attention[i, 1:i] += released * weights

    return "bos_sink_boundary_release", attention


def prog_L9H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weaker sink preference on punctuation and subwords.
    Remaining attention follows a diffuse, mildly recency-weighted causal prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        sink_mass = 0.82

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.90
            elif word.pos_ == "ADJ":
                sink_mass = 0.88
            elif word.pos_ == "VERB":
                sink_mass = 0.85
            elif word.pos_ in ("DET", "PRON", "NUM"):
                sink_mass = 0.84
            elif word.pos_ in ("ADP", "ADV", "AUX", "PART"):
                sink_mass = 0.77
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass = 0.69
            elif word.is_punct:
                sink_mass = 0.58

            # Continuations of a split word generally have weaker sink attention.
            if i > 1 and aligned[0] in alignment[i - 1]:
                sink_mass -= 0.12

        if tokens[i].isspace() or not tokens[i].strip("▁Ġ"):
            sink_mass = 0.76

        if i == 1:
            sink_mass = 0.965

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_lexical_gating", attention


def prog_L9H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild context-length dilution.
    Linguistic features weakly modulate sink strength; residual attention is diffuse and causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        pos = words[0].pos_ if words else ""

        sink_mass = 0.925 - 0.045 * np.log1p(i / 8.0) - 0.0015 * i

        if pos in ("NOUN", "PROPN", "ADJ"):
            sink_mass += 0.018
        elif pos in ("PRON", "AUX", "CCONJ", "SCONJ"):
            sink_mass -= 0.018

        if words and all(w.is_punct for w in words):
            sink_mass -= 0.065
        elif tokens[i].isspace() or not tokens[i].replace("▁", "").strip():
            sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.55, 0.95))

        # No non-BOS target is supported consistently by the examples.
        # Spread the remaining mass broadly, with only a weak recency bias.
        distances = i - np.arange(1, i + 1)
        residual = 0.7 + 0.3 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()
        attention[i, 0] = sink_mass

    return "bos_sink_with_context_dilution", attention


def prog_L9H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay and small linguistic corrections.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        sink = 0.48 + 0.41 * np.exp(-(i - 1) / 22.0)

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink += 0.025
            elif pos in ("AUX", "ADP", "DET"):
                sink += 0.015
            elif pos in ("ADV", "CCONJ", "SCONJ"):
                sink -= 0.035

            if word.is_punct:
                sink -= 0.045
                if word.text in (".", "!", "?", "…"):
                    sink -= 0.16

            if i == 1:
                if pos == "PRON":
                    sink = 0.91
                elif pos == "DET":
                    sink = 0.895
                elif pos in ("ADP", "ADV", "SCONJ"):
                    sink = 0.85
                elif pos in ("NOUN", "PROPN", "NUM"):
                    sink = 0.915

        sink = float(np.clip(sink, 0.20, 0.95))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_position_decay", make_row_stochastic(attention)


def prog_L9H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional weakening.
    A secondary channel links coordinated nominals to earlier conjuncts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_coordination", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None

        sink_mass = 0.994 - 0.004 * (i - 1)
        if word is not None:
            if word.pos_ == "PROPN":
                sink_mass -= 0.025
            elif word.pos_ == "NOUN":
                sink_mass -= 0.010
            elif word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ"):
                sink_mass += 0.006
        sink_mass = float(np.clip(sink_mass, 0.66, 0.995))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual[-1] *= 0.5

        if word is not None and word.head.i != word.i:
            earlier_heads = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if earlier_heads:
                head_index = earlier_heads[-1]
                residual[head_index - 1] += 1.0
                if (
                    word.dep_ == "conj"
                    and word.pos_ in ("NOUN", "PROPN")
                    and word.head.pos_ in ("NOUN", "PROPN")
                ):
                    sink_mass = min(sink_mass, 0.28)
                    residual *= 0.08
                    residual[head_index - 1] += 8.0

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_coordination", attention


def prog_L9H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Hypothesis: a dominant BOS attention sink with positional and boundary bias.
    Remaining attention is weakly distributed over the causal, recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        token = tokens[i]
        # SentencePiece/GPT-style whitespace markers are tokenization metadata.
        surface = token.lstrip("▁Ġ")
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None

        sink_mass = 0.565 + 0.19 * np.exp(-(i - 1) / 3.5)

        if word is not None:
            if word.pos_ == "PROPN":
                sink_mass += 0.065
            elif word.pos_ in ("NOUN", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ in ("PRON", "VERB", "ADV"):
                sink_mass -= 0.025

            # Fragmented word onsets often have stronger sink attention.
            previous_mapping = alignment[i - 1]
            next_mapping = alignment[i + 1] if i + 1 < n else []
            starts_word = mapped[0] not in previous_mapping
            continues_word = mapped[0] in next_mapping
            if starts_word and continues_word and not word.is_punct:
                sink_mass += 0.085

            if word.is_sent_start and i > 1:
                sink_mass += 0.045

        if not surface or surface.isspace():
            sink_mass = max(sink_mass, 0.75)
        elif all(not c.isalnum() and not c.isspace() for c in surface):
            sink_mass = 0.66
            if any(c in ".?!" for c in surface):
                sink_mass += 0.045
            if surface in ("'", "’"):
                sink_mass += 0.075

        if i == 1:
            sink_mass = 0.84
        sink_mass = float(np.clip(sink_mass, 0.45, 0.88))

        # A broad background plus recency represents the unobserved weak edges.
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = (
            0.40 / i
            + 0.60
            * np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_boundary_bias", make_row_stochastic(attention)


def prog_L9H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with diffuse recency; clause-ending punctuation additionally
    gathers prior content and the latest subject using mass taken only from BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_boundary_summary", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Preserve the original background, sink score, and normalization.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        attention[i, 1:i + 1] = 1.0 / np.sqrt(1.0 + distances)
        attention[i, 0] = 27.5
        attention[i, :i + 1] /= attention[i, :i + 1].sum()

    # Only boundary rows change; their original self-attention is untouched.
    boundaries = [
        i for i in range(1, n)
        if any(c in tokens[i] for c in ",;:.!?")
        and all(c in "▁Ġ \t\n,;:.!?\"'’”»" for c in tokens[i])
    ]
    if boundaries:
        doc = spacy_parse(sentence)
        mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
        content_pos = {"NOUN", "PROPN", "PRON", "VERB", "AUX", "ADJ", "ADV", "NUM"}

        for i in boundaries:
            targets = [
                (w, max(mapping[w.i]))
                for w in doc
                if w.pos_ in content_pos and mapping[w.i]
                and 0 < max(mapping[w.i]) < i
            ]
            if not targets:
                continue

            bonus = np.zeros(i, dtype=np.float64)
            for w, j in targets:
                bonus[j] += 1.0 / np.sqrt(1.0 + i - j)
            bonus[targets[-1][1]] += 2.0

            subjects = [
                j for w, j in targets
                if w.dep_ in {"nsubj", "nsubjpass", "csubj", "csubjpass"}
            ]
            if subjects:
                bonus[subjects[-1]] += 2.0

            terminal = any(c in tokens[i] for c in ".!?")
            fraction = (
                min(0.70, 0.27 + 0.006 * i) if terminal
                else min(0.45, 0.18 + 0.004 * i)
            )
            mass = attention[i, 0] * fraction
            attention[i, 0] -= mass
            attention[i, :i] += mass * bonus / bonus.sum()

    return "bos_sink_with_boundary_summary", attention


def prog_L9H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker local-context channel.
    Punctuation and lexical predicates divert more attention to preceding tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        pos = word.pos_ if word is not None else ""

        # Strong sink, with a modest reduction as more context becomes available.
        sink = 0.78 + 0.08 * np.exp(-(i - 1) / 18.0)
        if pos in ("NOUN", "PROPN", "ADJ", "DET", "AUX", "NUM"):
            sink += 0.025
        elif pos == "VERB":
            sink -= 0.13
        elif pos in ("CCONJ", "SCONJ", "ADV", "ADP"):
            sink -= 0.045

        punctuation = word is not None and word.is_punct
        if punctuation:
            if word.text in (",", ";", ":"):
                sink = 0.38 + 0.40 * np.exp(-i / 4.0)
            elif word.text in (".", "!", "?"):
                sink = 0.27
            elif word.text in ('"', "'", "“", "”", "‘", "’"):
                sink = 0.64
            else:
                sink = 0.48

        # The first content position has no non-BOS history.
        if i == 1:
            sink = 0.86

        local = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        local[1:] = 0.20 * np.exp(-(i - positions) / 3.0)
        local[i] += 0.10

        if i > 1:
            local[i - 1] += 0.85 if punctuation else 0.50

        # Predicates can retain a small direct link to their causal subject.
        if word is not None and pos == "VERB":
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    candidates = [
                        j for j in range(1, i)
                        if child.i in alignment[j]
                    ]
                    if candidates:
                        local[candidates[-1]] += 0.25

        local /= local.sum()
        attention[i, :i + 1] = (1.0 - sink) * local
        attention[i, 0] = sink

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L9H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with weak recency, except for definite-NP onset anchors.
    Definite determiners and their noun phrases draw extra mass from BOS only.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_definite_np_anchors", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.89 + 0.075 * np.exp(-(i - 1) / 18.0)
        if i == 1:
            sink_mass = 0.977

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Narrow exception: definite noun phrases immediately after a
    # preposition or verb. Transfer mass without renormalizing other edges.
    doc = spacy_parse(sentence)
    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)

    for det in doc:
        if (
            det.pos_ != "DET"
            or det.dep_ != "det"
            or "Def" not in det.morph.get("Definite")
            or det.i == 0
        ):
            continue

        anchor = doc[det.i - 1]
        noun = det.head
        if (
            anchor.pos_ not in ("ADP", "VERB")
            or noun.pos_ not in ("NOUN", "PROPN")
            or noun.i <= det.i
            or noun.i - det.i > 3
        ):
            continue

        anchor_ids = [j for j in mapping[anchor.i] if 0 < j < n]
        det_ids = [j for j in mapping[det.i] if 0 < j < n]
        noun_ids = [j for j in mapping[noun.i] if 0 < j < n]
        if not anchor_ids or not det_ids or not noun_ids:
            continue

        a, d = anchor_ids[-1], det_ids[0]
        if a >= d:
            continue

        targets = [(d, a, 0.32 if anchor.pos_ == "ADP" else 0.29)]
        possessives = [
            child for child in noun.children
            if child.pos_ == "PART" and child.dep_ == "case"
        ]

        for k, i in enumerate(noun_ids):
            targets.append((i, a, 0.065 if possessives else 0.09))
            targets.append((i, d, 0.025 if possessives else
                            (0.09 if k == 0 else 0.035)))

        if anchor.pos_ == "ADP":
            for marker in possessives:
                marker_ids = [j for j in mapping[marker.i] if 0 < j < n]
                for k, i in enumerate(marker_ids):
                    targets.append((i, a, 0.17 if k == 0 else 0.42))
                    targets.append((i, d, 0.055 if k == 0 else 0.08))

        for i, j, extra in targets:
            if 0 < j < i < n:
                mass = min(extra, max(0.0, attention[i, 0] - 0.20))
                attention[i, 0] -= mass
                attention[i, j] += mass

    return "bos_sink_with_definite_np_anchors", attention


def prog_L9H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective predecessor attention inside tightly linked phrases.
    Transfer only BOS mass for possessive subjects and modified or coordinated predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "PRON": 0.950,
        "AUX": 0.940,
        "DET": 0.930,
        "PART": 0.935,
        "VERB": 0.925,
        "ADP": 0.910,
        "SCONJ": 0.925,
        "CCONJ": 0.890,
        "ADV": 0.875,
        "NOUN": 0.850,
        "PROPN": 0.870,
        "ADJ": 0.825,
        "NUM": 0.860,
        "PUNCT": 0.950,
        "SPACE": 0.900,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            sink = float(np.mean([
                sink_by_pos.get(doc[k].pos_, 0.900)
                for k in aligned
            ]))
        else:
            sink = 0.910

        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if clean and all(not c.isalnum() for c in clean):
            sink = max(sink, 0.950)

        # Keep the original residual and its self-attention unchanged.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 * np.exp(-distances / 3.0) + 0.35
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Special case: a tightly linked preceding word attracts BOS mass.
        if len(aligned) == 1 and aligned[0] > 0:
            word = doc[aligned[0]]
            prev = doc[word.i - 1]
            boost = 0.0

            if (word.pos_ == "NOUN" and prev.dep_ == "poss"
                    and prev.i == 0 and word.dep_ in ("nsubj", "nsubjpass")):
                boost = 0.65
            elif word.pos_ == "ADJ":
                if prev.pos_ == "AUX" and (
                    word.head.i == prev.i or prev.head.i == word.i
                ):
                    boost = 0.25
                elif prev.pos_ == "ADV" and prev.head.i == word.i:
                    boost = 0.27
                elif prev.pos_ == "CCONJ" and word.dep_ == "conj":
                    boost = 0.60
                elif prev.pos_ == "ADJ" and prev.head.i == word.head.i:
                    boost = 0.20
                elif prev.pos_ == "DET" and prev.head.i == word.head.i:
                    boost = 0.14
            elif word.pos_ in ("NOUN", "PROPN"):
                if prev.pos_ == "ADJ" and prev.head.i == word.i:
                    boost = 0.17
                elif prev.dep_ == "compound" and prev.head.i == word.i:
                    boost = 0.17
            elif (word.tag_ == "VBG" and prev.pos_ in ("AUX", "VERB")
                  and (word.head.i == prev.i or prev.head.i == word.i)):
                boost = 0.25

            if boost > 0.0:
                targets = [
                    j for j in range(1, i)
                    if prev.i in alignment[j]
                ]
                if targets:
                    pieces_before = sum(
                        word.i in alignment[j] for j in range(1, i)
                    )
                    transfer = min(
                        boost * (0.80 ** pieces_before),
                        attention[i, 0]
                    )
                    attention[i, 0] -= transfer
                    attention[i, targets[-1]] += transfer

    return "bos_sink_with_phrase_residual", attention


def prog_L9H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for nominal and boundary tokens.
    Predicate tokens retain more diffuse, mildly local causal attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_mass = {
        "PROPN": 0.92,
        "NOUN": 0.86,
        "DET": 0.87,
        "PRON": 0.80,
        "PUNCT": 0.85,
        "SPACE": 0.89,
        "NUM": 0.84,
        "ADJ": 0.74,
        "ADP": 0.76,
        "CCONJ": 0.73,
        "SCONJ": 0.77,
        "PART": 0.72,
        "ADV": 0.67,
        "AUX": 0.65,
        "VERB": 0.63,
        "INTJ": 0.84,
        "SYM": 0.86,
        "X": 0.80,
    }

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        mass = 0.80

        if words:
            mass = sum(pos_mass.get(w.pos_, 0.78) for w in words) / len(words)
            if any(w.ent_type_ for w in words):
                mass += 0.025
            if any(w.dep_ in ("poss", "nmod", "compound") for w in words):
                mass += 0.015
        else:
            surface = tokens[i].lstrip("▁Ġ")
            if not surface or surface.isspace():
                mass = 0.89
            elif all(not c.isalnum() for c in surface):
                mass = 0.87

        # The first content position has only the sink and itself available.
        if i == 1:
            mass = 0.94
        elif i <= 3:
            mass += 0.025

        mass = float(np.clip(mass, 0.55, 0.97))
        attention[i, 0] = mass

        # No non-BOS target is demonstrated consistently: keep the residual
        # broad rather than inventing a strong syntactic routing rule.
        distance = i - np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * np.exp(-distance / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - mass) * residual

    return "bos_sink_with_linguistic_gating", attention


def prog_L9H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, slightly strengthened for nominal tokens.
    A small residual is spread over the causal context with a recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        pos = words[0].pos_ if words else ""

        sink_mass = 0.91
        if pos in ("NOUN", "PROPN"):
            sink_mass += 0.045
        elif pos == "VERB":
            sink_mass += 0.01
        elif pos in ("PRON", "DET", "ADP", "ADV", "PUNCT"):
            sink_mass -= 0.025

        # Early tokens have fewer competing keys; later contexts mildly
        # dilute, but do not remove, the dominant initial-token sink.
        sink_mass -= 0.035 * (1.0 - np.exp(-(i - 1) / 40.0))
        if i == 1:
            sink_mass = 0.96 if pos != "DET" else 0.93

        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.5 + np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_lexical_modulation", attention


def prog_L9H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker local syntactic and recency-based attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                inverse[wi].append(ti)

    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        sink = 0.78
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink = 0.70
            elif word.pos_ in ("VERB", "AUX", "PRON"):
                sink = 0.73
            elif word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ"):
                sink = 0.80

        if not text:
            sink = 0.90
        elif all(not c.isalnum() for c in text):
            sink = 0.89
            if "'" in text or "’" in text:
                sink = 0.95
        elif word is not None and word.is_punct:
            sink = 0.89

        # Split-word fragments usually retain especially strong sink attention.
        if word is not None:
            pieces = inverse[word.i]
            if pieces and i != pieces[0]:
                sink = max(sink, 0.85)

        if i == 1:
            sink = 0.89
            if word is not None and word.pos_ in ("ADP", "ADV", "NUM"):
                sink = 0.97

        if tokens[i] in special_tokens:
            sink = 0.96

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.45

        if word is not None:
            # Only already-seen syntactic endpoints can receive attention.
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    strength = 1.4
                    if word.dep_ in ("dobj", "obj", "iobj", "attr"):
                        strength = 3.0
                        sink = min(sink, 0.65)
                    residual[candidates[-1] - 1] += strength

            for child in word.children:
                if child.dep_ not in ("poss", "nsubj", "nsubjpass", "csubj"):
                    continue
                candidates = [j for j in inverse[child.i] if 0 < j < i]
                if not candidates:
                    continue
                j = candidates[-1]
                strength = 3.0 if child.dep_ == "poss" else 2.0
                residual[j - 1] += strength
                sink = min(sink, 0.65)
                # Initial possessive subjects can override the usual sink.
                if child.dep_ == "poss" and j == 1 and i == 2:
                    sink = 0.15
                    residual[j - 1] += 12.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_syntax", attention


def prog_L9H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak POS-dependent strength.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.855
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink += 0.035
            elif word.pos_ in ("VERB", "ADJ", "DET"):
                sink += 0.015
            elif word.pos_ in ("ADP", "ADV", "CCONJ", "SCONJ", "PART"):
                sink -= 0.035
            elif word.pos_ in ("PRON", "AUX"):
                sink -= 0.015
            elif word.pos_ == "PUNCT":
                sink += 0.010
            if word.ent_type_:
                sink += 0.010

        if tokens[i].strip() in ("'", "’"):
            sink = 0.94

        if i == 1:
            sink = max(sink, 0.92)

        sink = float(np.clip(sink, 0.72, 0.96))
        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_pos_modulated", attention


def prog_L9H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with selective phrase-completion attention to preceding
    prepositions, determiners, modifiers, and object-governing verbs.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            word_tokens[si].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.84 + 0.10 * np.exp(-(i - 1) / 4.0)
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("VERB", "AUX", "ADJ"):
                sink += 0.025
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                sink += 0.025
            if word.dep_ in ("dobj", "obj", "iobj", "pobj"):
                sink -= 0.12
            if word.dep_ in ("prep", "case"):
                sink -= 0.035
            if word.pos_ in ("CCONJ", "SCONJ"):
                sink -= 0.055
            if word.pos_ == "PUNCT":
                sink -= 0.11

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.94
        if i == 1:
            sink = 0.96

        sink = float(np.clip(sink, 0.55, 0.98))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.35 + np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink) * remainder / remainder.sum()

        # Transfer only sink mass; preserve the original diagonal and remainder.
        if aligned and i > 1 and tokens[i] not in tokenizer.all_special_tokens:
            word = doc[aligned[0]]
            targets = []
            budget = 0.0

            if (word.pos_ in ("NOUN", "PROPN", "PRON")
                    and word_tokens[word.i][-1] == i):
                phrase = word.head if word.dep_ == "compound" else word
                if phrase.dep_ == "pobj" and phrase.head.pos_ == "ADP":
                    targets.append((phrase.head.i, 1.5))
                    budget = 0.30
                elif phrase.dep_ in ("obj", "dobj", "iobj"):
                    if phrase.head.pos_ == "VERB":
                        targets.append((phrase.head.i, 1.5))
                        budget = 0.22

                if budget:
                    for child in phrase.children:
                        if child.dep_ in ("det", "poss"):
                            targets.append((child.i, 1.0))
                        elif child.dep_ == "amod":
                            targets.append((child.i, 1.2))

            elif word.pos_ in ("PUNCT", "CCONJ") and word.i > 0:
                previous = doc[word.i - 1]
                if previous.pos_ in ("NOUN", "PROPN", "PRON"):
                    governor = previous.head
                    if previous.dep_ == "pobj":
                        governor = governor.head
                    if (previous.dep_ in ("obj", "dobj", "iobj", "pobj")
                            and governor.pos_ == "VERB"):
                        targets.append((governor.i, 1.0))
                        budget = 0.16

            eligible = []
            for si, weight in targets:
                preceding = [j for j in word_tokens[si] if 0 < j < i]
                if preceding:
                    eligible.append((preceding[-1], weight))

            if eligible:
                mass = min(budget, max(0.0, attention[i, 0] - 0.20))
                total = sum(weight for _, weight in eligible)
                attention[i, 0] -= mass
                for j, weight in eligible:
                    attention[i, j] += mass * weight / total

    return "first_token_sink_phrase_completion", attention


def prog_L9H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with phrase-initial governor spillover.
    Determiner-led object phrases retain attention to their governing verb or preposition.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_governor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[ids[0]] if ids else None for ids in alignment]

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        previous = words[i - 1]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.85
        if pos in ("VERB", "AUX", "PART"):
            sink = 0.90
        elif pos == "PUNCT":
            sink = 0.92
        elif pos in ("NOUN", "PROPN"):
            sink = 0.80
        elif pos in ("PRON", "ADP"):
            sink = 0.78
        elif pos == "DET":
            sink = 0.57
        elif pos in ("ADJ", "ADV"):
            sink = 0.83

        if i == 1:
            sink = 0.95

        # A continuation piece generally retains the head's sink behavior.
        continuation = (
            word is not None
            and previous is not None
            and word.i == previous.i
        )
        if continuation:
            sink = max(sink, 0.88)

        local_target = i - 1
        is_determiner = pos == "DET" or dep in ("poss", "det")
        if (
            i > 1
            and is_determiner
            and previous is not None
            and previous.pos_ == "VERB"
            and not continuation
        ):
            sink = 0.25

        # Spread residual attention locally, without leaking into future tokens.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 2.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * 0.30 * residual
        attention[i, local_target] += (1.0 - sink) * 0.70
        attention[i, 0] += sink

        # Special case: a determiner-led nominal phrase keeps its governor
        # active beyond the determiner, including modifiers and subword pieces.
        nominal = None
        if word is not None:
            if is_determiner or dep in ("amod", "compound"):
                nominal = word.head
            elif pos in ("NOUN", "PROPN"):
                nominal = word

        if nominal is not None and nominal.pos_ in ("NOUN", "PROPN"):
            while nominal.dep_ == "compound" and nominal.head.i != nominal.i:
                nominal = nominal.head

            # Extend through a nested nominal complement, e.g. partitive NPs.
            while (
                nominal.dep_ == "pobj"
                and nominal.head.pos_ == "ADP"
                and nominal.head.head.pos_ in ("NOUN", "PROPN")
                and nominal.head.head.i < nominal.i
            ):
                nominal = nominal.head.head

            determiners = [
                child for child in nominal.children
                if child.dep_ in ("det", "poss")
                and child.i <= word.i
            ]
            governor = nominal.head
            eligible = (
                governor.pos_ == "ADP"
                or (
                    governor.pos_ == "VERB"
                    and nominal.dep_ in ("dobj", "obj", "attr", "oprd")
                )
            )
            if determiners and eligible:
                anchor_positions = [
                    j for j in range(1, i)
                    if words[j] is not None
                    and words[j].i == governor.i
                ]
                if anchor_positions:
                    anchor = anchor_positions[-1]
                    if is_determiner:
                        if governor.pos_ == "ADP":
                            target = 0.68 if dep == "poss" else 0.62
                        else:
                            target = 0.74 if dep == "poss" else 0.44
                    else:
                        target = 0.28 if governor.pos_ == "ADP" else 0.17
                        if dep == "amod":
                            target = 0.30
                        target *= np.exp(-max(0, i - anchor - 2) / 4.0)

                    # Reallocate only BOS and previous-token mass; leave the
                    # original self-attention and residual decay untouched.
                    if local_target not in (0, anchor):
                        moved = 0.80 * attention[i, local_target]
                        attention[i, local_target] -= moved
                        attention[i, 0] += moved
                    delta = min(
                        target - attention[i, anchor],
                        attention[i, 0],
                    )
                    attention[i, anchor] += delta
                    attention[i, 0] -= delta

    return "bos_sink_with_phrase_governor", make_row_stochastic(attention)


def prog_L9H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker, recency-weighted syntactic attention.
    Predicate adjectives and nearby nominal heads can override the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}
    nominal_pos = {"NOUN", "PROPN", "PRON"}
    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # A persistent sink, with increasing competition as context accumulates.
        attention[i, 0] = 24.0
        attention[i, i] = 0.72

        for j in range(1, i):
            distance = i - j
            decay = np.exp(-distance / 20.0)
            word_ids = alignment[j]
            salience = 0.12
            if word_ids:
                word = doc[word_ids[-1]]
                if word.pos_ in content_pos:
                    salience = 0.95
                if word.pos_ == "PROPN":
                    salience = 0.65
                if word.pos_ == "ADJ" and word.dep_ in {
                    "ROOT", "acomp", "attr", "oprd"
                }:
                    salience = 1.7
                # Do not multiply a word's importance by its subtoken count.
                salience /= max(1, len(inverse[word.i]))
            attention[i, j] += salience * decay

        if tokens[i] in special_tokens or not alignment[i]:
            continue

        word = doc[alignment[i][-1]]

        # Backward syntactic links only; no future-token leakage.
        head = word.head
        head_tokens = [j for j in inverse[head.i] if 0 < j < i]
        if head.i != word.i and head_tokens:
            target = head_tokens[-1]
            distance = i - target
            strength = 0.0

            if word.dep_ == "cc":
                strength = 65.0 if head.pos_ == "ADJ" else 7.0
            elif word.dep_ == "conj":
                strength = 28.0 if head.pos_ == "ADJ" else 8.0
            elif word.pos_ == "ADP" and head.pos_ in nominal_pos:
                strength = 22.0
            elif word.dep_ in {"cop", "aux", "auxpass"}:
                strength = 8.0
            elif word.dep_ == "punct":
                strength = 12.0
            elif word.dep_ in {"dobj", "obj", "iobj", "advmod", "advcl"}:
                strength = 3.0

            attention[i, target] += strength * np.exp(
                -max(0, distance - 2) / 12.0
            )

        # Determiners inside postnominal prepositional phrases can retain
        # attention to the preceding nominal anchor.
        if word.pos_ == "DET":
            nominal = word.head
            preposition = nominal.head
            anchor = preposition.head
            if preposition.pos_ == "ADP" and anchor.pos_ in nominal_pos:
                candidates = [j for j in inverse[anchor.i] if 0 < j < i]
                if candidates:
                    target = candidates[-1]
                    attention[i, target] += 20.0 * np.exp(
                        -max(0, i - target - 2) / 10.0
                    )

    return (
        "bos_sink_with_local_syntax",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L9H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly position-dependent strength.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.985 - 0.105 * (1.0 - np.exp(-(i - 1) / 24.0))
        positions = np.arange(1, i + 1)
        residual_weights = 0.7 + 0.3 * np.exp(-(i - positions) / 8.0)
        residual_weights /= residual_weights.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual_weights

    return "bos_sink_with_diffuse_residual", attention


def prog_L9H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly decreasing dominance over position.
    Distribute the small residual over causal tokens with a weak recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.91 - 0.12 * (1.0 - np.exp(-i / 40.0))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L9H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at sentence starts and on salient nominal tokens.
    Remaining attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    sentence_start = 1
    previous_sentence = None

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        if word is not None:
            current_sentence = word.sent.start
            if current_sentence != previous_sentence:
                sentence_start = i
                previous_sentence = current_sentence

        # A persistent sink with an additional short sentence-initial boost.
        distance = i - sentence_start
        sink = 0.73 + 0.19 * np.exp(-distance / 3.0)
        sink += 0.025 * np.exp(-(i - 1) / 5.0)

        if word is not None:
            if word.pos_ == "PROPN":
                sink += 0.12
            elif word.pos_ == "NOUN":
                sink += 0.035
            elif word.pos_ in ("VERB", "ADJ"):
                sink += 0.025
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "PART"):
                sink -= 0.035

            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                sink += 0.035
            elif word.dep_ in ("obj", "dobj", "pobj") and word.pos_ == "PRON":
                sink -= 0.055

            if word.ent_type_:
                sink += 0.025

            # Continuation pieces often retain especially strong sink attention.
            if i > 1 and aligned and alignment[i - 1]:
                if aligned[0] in alignment[i - 1]:
                    sink += 0.045

        surface = tokens[i].lstrip("▁Ġ")
        if not surface or surface.isspace():
            sink += 0.10
        elif surface in ("'", "’"):
            sink += 0.13
        elif surface in (".", "!", "?"):
            sink += 0.025

        if tokens[i] in special_tokens:
            sink = 0.97

        sink = float(np.clip(sink, 0.50, 0.985))
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_modulation", attention


def prog_L9H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a targeted residual attraction to prenominal adjectives.
    Modifier phrases divert BOS mass without changing existing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_modifier_residual", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.88 + 0.06 * np.exp(-(i - 1) / 18.0)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Only prenominal adjectival modifiers activate the new path.
    doc = spacy_parse(sentence)
    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
    extra = np.zeros_like(attention)

    for modifier in doc:
        noun = modifier.head
        if not (
            modifier.pos_ == "ADJ"
            and modifier.dep_ == "amod"
            and noun.pos_ in ("NOUN", "PROPN")
            and modifier.i < noun.i
        ):
            continue

        keys = [j for j in mapping[modifier.i] if 0 < j < n]
        noun_tokens = [j for j in mapping[noun.i] if 0 < j < n]
        if not keys or not noun_tokens:
            continue
        key = keys[-1]

        for word_index in range(modifier.i + 1, min(len(doc), noun.i + 5)):
            word = doc[word_index]
            if word.is_punct or word.pos_ in ("CCONJ", "SCONJ"):
                break

            if word_index < noun.i:
                if word.pos_ != "ADJ" or word.head.i != noun.i:
                    continue
                strength = 0.32
            elif word_index == noun.i:
                strength = 0.22
            else:
                strength = 0.22 * np.exp(-(word_index - noun.i) / 3.0)

            for i in mapping[word_index]:
                if not (key < i < n):
                    continue
                amount = strength
                if word_index == noun.i and len(noun_tokens) > 1:
                    amount *= 1.5 if i == noun_tokens[-1] else 0.65
                extra[i, key] += amount

    # Transfer only from BOS; all other baseline edges, including the
    # diagonal, remain unchanged unless explicitly targeted above.
    for i in range(1, n):
        requested = extra[i].sum()
        if requested > 0.0:
            moved = min(requested, 0.75 * attention[i, 0])
            attention[i] += extra[i] * (moved / requested)
            attention[i, 0] -= moved

    return "bos_sink_with_modifier_residual", attention


def prog_L9H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS attention sink with a secondary first-token anchor.
    Content words favor BOS; grammatical tokens more often use the anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_initial_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    special = set(tokenizer.all_special_tokens)
    anchor = 0
    for i, token in enumerate(tokens):
        if token not in special:
            anchor = i
            break

    bos_by_pos = {
        "NOUN": 0.79,
        "PROPN": 0.89,
        "PRON": 0.68,
        "DET": 0.63,
        "ADJ": 0.62,
        "ADV": 0.54,
        "VERB": 0.55,
        "AUX": 0.43,
        "ADP": 0.54,
        "PART": 0.49,
        "CCONJ": 0.49,
        "SCONJ": 0.47,
        "NUM": 0.70,
        "PUNCT": 0.58,
        "SPACE": 0.73,
        "INTJ": 0.65,
        "X": 0.73,
    }

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        if i <= anchor:
            attention[i, 0] = 0.97
            attention[i, i] += 0.03
            continue

        indices = alignment[i]
        word = None
        for k in indices:
            if not doc[k].is_space:
                word = doc[k]
                break

        p_bos = 0.66
        if word is not None:
            p_bos = bos_by_pos.get(word.pos_, 0.64)

            if word.ent_type_:
                p_bos += 0.04

            # Rare or segmented content words remain strong sink queries.
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                if not tokens[i].startswith(("▁", "Ġ")):
                    p_bos += 0.04

            # Early copulas/auxiliaries strongly expose the initial anchor.
            if word.pos_ == "AUX" and i - anchor <= 4:
                p_bos -= 0.12

            if word.dep_ in ("poss", "det"):
                p_bos += 0.02

            # Sentence-final punctuation can recover the initial token,
            # especially before the context becomes long.
            if word.is_punct and any(c in word.text for c in ".!?"):
                p_bos -= 0.21 * np.exp(-(i - anchor) / 35.0)

        if tokens[i].isspace() or tokens[i] in ("▁", "Ġ"):
            p_bos = 0.74

        p_bos = float(np.clip(p_bos, 0.20, 0.94))
        attention[i, 0] = p_bos

        remainder = 1.0 - p_bos
        attention[i, anchor] += 0.80 * remainder

        # Spread a small residual over causal context rather than predicting
        # unsupported sharp syntactic links.
        positions = np.arange(anchor, i + 1)
        background = 0.35 + np.exp(-(i - positions) / 8.0)
        background /= background.sum()
        attention[i, anchor:i + 1] += 0.20 * remainder * background

    return "bos_sink_with_initial_anchor", make_row_stochastic(attention)


def prog_L9H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak local attention and occasional
    subject-to-auxiliary or object-to-preposition transitions."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        sink = 0.86

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink = 0.92
            elif pos in ("DET", "ADJ"):
                sink = 0.88
            elif pos == "PRON":
                sink = 0.86
            elif pos == "VERB":
                sink = 0.76
            elif pos == "AUX":
                sink = 0.67
            elif pos in ("ADV", "CCONJ", "SCONJ"):
                sink = 0.76
            elif pos == "PUNCT":
                sink = 0.84

            if word.ent_type_:
                sink = max(sink, 0.91)

            # Continuation pieces usually retain the strong null/BOS default.
            if i > 1 and set(aligned).intersection(alignment[i - 1]):
                sink = max(sink, 0.88)

        if i == 1:
            sink = 0.94
        if tokens[i] in special_tokens or tokens[i].isspace():
            sink = 0.91

        # Distribute non-sink mass locally rather than uniformly over history.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local[-1] *= 0.35

        if word is not None and i > 1 and alignment[i - 1]:
            previous = doc[alignment[i - 1][-1]]
            different_word = previous.i != word.i

            if different_word and word.pos_ == "AUX":
                if previous.dep_ in ("nsubj", "nsubjpass"):
                    sink = 0.48
                    if word.tag_ == "MD" and previous.pos_ == "PRON":
                        sink = 0.18
                    local[-2] += 8.0

            if different_word and word.pos_ == "ADP":
                if previous.pos_ in ("NOUN", "PROPN"):
                    if previous.dep_ in ("dobj", "obj", "attr"):
                        sink = 0.34
                        local[-2] += 10.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_local_syntax", attention


def prog_L9H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head, with weak position- and syntax-dependent leakage.
    Residual attention is distributed over recent causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_linguistic_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.975 - 0.075 * (1.0 - np.exp(-(i - 1) / 24.0))
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.035
            elif word.pos_ == "ADJ":
                sink_mass += 0.020
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.095

            if word.dep_ in ("cc", "mark"):
                sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.75, 0.993))
        if i == 1:
            sink_mass = 0.985

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.25 + np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_linguistic_leakage", attention


def prog_L10H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a weak recency tail; quoted dialogue additionally retrieves
    earlier predicate anchors and repeated content, without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Only enable the exception for explicitly quoted dialogue.
    dialogue = any(c in sentence for c in ('"', '“', '”', '«', '»'))
    word_ends = {}
    if dialogue:
        for ti, aligned in enumerate(alignment):
            for wi in aligned:
                if ti > 0:
                    word_ends[wi] = ti

    for i in range(1, n):
        sink_mass = 0.90 / (1.0 + 0.009 * (i - 1))

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.09
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.015
        elif tokens[i].isspace() or not tokens[i].strip("▁Ġ"):
            sink_mass += 0.025

        sink_mass = np.clip(sink_mass, 0.40, 0.95)

        # Spread non-sink mass over the causal prefix, mildly favoring recency.
        positions = np.arange(1, i + 1)
        distances = i - positions
        tail = (
            0.55 / i
            + 0.45
            * np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * tail

        # Transfer only BOS mass: existing self and background weights stay intact.
        if dialogue and aligned:
            word = doc[aligned[0]]
            anchors = {}

            # Quotation boundaries retrieve the most recent predicate.
            if any(c in tokens[i] for c in ('"', '“', '”', '«', '»')):
                for j in range(i - 1, 0, -1):
                    if alignment[j] and doc[alignment[j][0]].pos_ == "VERB":
                        anchors[j] = 0.15
                        break

            # Recover causal syntactic links inside dialogue.
            head_j = word_ends.get(word.head.i, -1)
            if (
                word.pos_ != "PUNCT"
                and word.head.pos_ == "VERB"
                and 0 < head_j < i
            ):
                anchors[head_j] = anchors.get(head_j, 0.0) + 0.08

            # Repeated content can retrieve an earlier mention across turns.
            if word.pos_ in ("NOUN", "PROPN", "VERB") and i == word_ends.get(word.i):
                best_j, best_similarity = -1, 0.82
                for wi, j in word_ends.items():
                    if (
                        0 < j < i - 2
                        and wi != word.i
                        and doc[wi].pos_ == word.pos_
                    ):
                        similarity = embedding_similarity(tokens, i, j, tokenizer)
                        if similarity > best_similarity:
                            best_j, best_similarity = j, similarity
                if best_j > 0:
                    anchors[best_j] = anchors.get(best_j, 0.0) + 0.12

            total = sum(anchors.values())
            if total > 0.0:
                scale = min(1.0, 0.35 * attention[i, 0] / total)
                for j, mass in anchors.items():
                    transfer = scale * mass
                    attention[i, 0] -= transfer
                    attention[i, j] += transfer

    return "bos_sink_with_dialogue_anchors", make_row_stochastic(attention)


def prog_L10H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and at boundaries, with weak
    recency-weighted attention to preceding content and predicates."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    features = []

    for i, token in enumerate(tokens):
        aligned = alignment[i] if i < len(alignment) else []
        word = doc[aligned[0]] if aligned else None
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        punct = (
            token not in special
            and bool(clean)
            and all(not c.isalnum() for c in clean)
        )
        whitespace = token not in special and not clean
        features.append((
            word.pos_ if word is not None else "",
            word.dep_ if word is not None else "",
            punct,
            whitespace,
        ))

    attention[0, 0] = 1.0

    for i in range(1, n):
        pos, dep, punct, whitespace = features[i]

        # Sink strength decays slowly rather than disappearing with distance.
        sink = 0.64 + 0.23 * np.exp(-(i - 1) / 12.0)
        if pos in ("DET", "PRON", "ADP", "CCONJ", "SCONJ", "AUX"):
            sink += 0.035
        elif pos in ("VERB", "ADJ", "ADV"):
            sink -= 0.045
        if dep in ("nsubj", "nsubjpass"):
            sink += 0.035
        if punct:
            sink += 0.12
        if whitespace:
            sink += 0.04

        if i == 1:
            sink = 0.95
            if pos == "DET":
                sink = 0.89
            elif pos == "PRON":
                sink = 0.955

        sink = float(np.clip(sink, 0.48, 0.98))
        attention[i, 0] = sink

        weights = np.zeros(i, dtype=np.float64)
        for j in range(1, i + 1):
            key_pos, _, key_punct, key_space = features[j]
            distance = i - j
            weight = 0.3 + np.exp(-distance / 5.0)
            if key_pos == "VERB":
                weight *= 1.65
            elif key_pos in ("NOUN", "PROPN", "ADJ"):
                weight *= 1.15
            if key_punct or key_space or tokens[j] in special:
                weight *= 0.45
            weights[j - 1] = weight

        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_boundary_bias", attention


def prog_L10H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker, causal spillover onto recent predicates.
    Predicate complements and coordinated material share a local syntactic anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_spillover", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if ti > 0:
                word_tokens[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        # A large, slowly declining attention sink is the dominant structure.
        sink = 0.59 + 0.34 * np.exp(-(i - 1) / 9.0)
        if word is not None:
            if word.pos_ in ("VERB", "PROPN"):
                sink += 0.07
            elif word.pos_ == "AUX":
                sink += 0.025
            elif word.pos_ in ("CCONJ", "SCONJ", "PUNCT"):
                sink -= 0.075
            if word.dep_ in ("nsubj", "nsubjpass") and i < 6:
                sink += 0.035
        elif tokens[i].strip("▁Ġ \t\r\n") == "":
            sink += 0.20

        # The residual is distributed causally, favoring content predicates.
        positions = np.arange(1, i + 1)
        residual = 0.045 * np.exp(-(i - positions) / 9.0)
        residual[-1] += 0.08

        for j in range(1, i + 1):
            if alignment[j]:
                candidate = doc[alignment[j][-1]]
                if candidate.pos_ in ("VERB", "ADJ"):
                    residual[j - 1] += 0.10 * np.exp(-(i - j) / 18.0)

        if word is not None:
            # A preceding syntactic governor can compete with the BOS sink.
            ancestor = word
            visited = set()
            for depth in range(6):
                if ancestor.i in visited:
                    break
                visited.add(ancestor.i)
                if ancestor.i != word.i and ancestor.pos_ in ("VERB", "ADJ"):
                    prior = [j for j in word_tokens[ancestor.i] if j < i]
                    if prior:
                        anchor = prior[0]
                        strength = 0.65 / (1.0 + 0.35 * depth)
                        nonfinite = (
                            ancestor.pos_ == "VERB"
                            and ancestor.tag_ in ("VBG", "VBN", "VB")
                            and ancestor.dep_ != "ROOT"
                        )
                        if nonfinite:
                            strength *= 2.3
                            sink -= 0.12
                        if ancestor.pos_ == "ADJ" and word.pos_ == "CCONJ":
                            strength *= 1.8
                            sink -= 0.10
                        residual[anchor - 1] += strength
                        break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

            # Keep subword pieces associated without treating them as words.
            pieces = [j for j in word_tokens[word.i] if 0 < j < i]
            if pieces:
                residual[pieces[0] - 1] += 0.18
                sink += 0.035

        sink = float(np.clip(sink, 0.30, 0.97))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_predicate_spillover", make_row_stochastic(attention)


def prog_L10H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker local-context component.
    Function words and punctuation shift more mass toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_context", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.88,
        "PROPN": 0.88,
        "ADJ": 0.87,
        "DET": 0.89,
        "PRON": 0.83,
        "VERB": 0.82,
        "ADP": 0.81,
        "ADV": 0.75,
        "AUX": 0.65,
        "PART": 0.72,
        "CCONJ": 0.53,
        "SCONJ": 0.73,
        "PUNCT": 0.61,
        "SPACE": 0.72,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[aligned[i][0]] if aligned[i] else None
        sink = sink_by_pos.get(word.pos_, 0.85) if word is not None else 0.85

        # The first lexical query has no earlier lexical context.
        if i == 1:
            attention[i, 0] = 0.90
            attention[i, i] = 0.10
            continue

        # Allocate the non-sink component primarily to immediate context.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local[-1] *= 0.25
        local[-2] += 2.0

        # A visible syntactic governor provides a small causal correction.
        if word is not None and word.head.i != word.i:
            for j in range(1, i):
                if word.head.i in aligned[j]:
                    local[j - 1] += 0.35

        local /= local.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local

    return "bos_sink_with_local_context", attention


def prog_L10H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with stronger sentence-initial and nominal attraction.
    Residual attention favors recent tokens, especially adjectival predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_adjectival_fallback", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        piece = tokens[i].replace("▁", "").replace("Ġ", "")
        distance = np.arange(i + 1, dtype=np.float64)

        sink = 0.61
        if pos in ("NOUN", "PROPN"):
            sink += 0.15
        elif pos in ("DET", "ADP"):
            sink += 0.06
        elif pos in ("VERB", "ADV", "PART"):
            sink -= 0.12
        elif pos in ("PRON", "CCONJ", "SCONJ"):
            sink -= 0.06
        elif pos == "ADJ":
            sink += 0.04

        # Initial tokens overwhelmingly use the sink, independently of syntax.
        sink += 0.28 * np.exp(-(i - 1) / 3.5)

        if not piece.strip():
            sink = max(sink, 0.93)
        elif piece in ("'", "’"):
            sink = max(sink, 0.85)

        # Later pieces of a lexical item often preserve its sink preference.
        if (
            word is not None
            and i > 1
            and words[i - 1] is not None
            and word.i == words[i - 1].i
        ):
            sink += 0.06

        residual = np.exp(-(i - distance) / 2.5)
        residual[0] = 0.0
        residual[i] *= 0.35

        strongest_predicate = 0.0
        for j in range(max(1, i - 8), i):
            previous = words[j]
            if previous is None:
                continue

            lag = i - j
            if previous.pos_ == "ADJ":
                strength = np.exp(-(lag - 1) / 2.0)
                residual[j] += 2.0 * strength
                if previous.dep_ in ("acomp", "attr", "ROOT", "oprd"):
                    residual[j] += 2.5 * strength
                    if pos in ("CCONJ", "VERB", "ADV", "ADJ"):
                        strongest_predicate = max(
                            strongest_predicate, strength
                        )

            if word is not None and previous.i == word.head.i:
                residual[j] += 0.35 * np.exp(-(lag - 1) / 5.0)

            if previous.is_punct:
                residual[j] *= 0.65

        sink -= 0.29 * strongest_predicate
        sink = float(np.clip(sink, 0.22, 0.97))
        attention[i, 0] = sink
        attention[i, :i + 1] += (
            (1.0 - sink) * residual / residual.sum()
        )

    return "bos_sink_with_local_adjectival_fallback", make_row_stochastic(attention)


def prog_L10H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution.
    Whitespace and punctuation strengthen the sink; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boost", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        # More competing context gradually dilutes the otherwise dominant sink.
        sink = 0.67 - 0.0038 * min(i, 70)

        if word is not None:
            if word.pos_ in ("ADP", "DET"):
                sink += 0.035
            elif word.pos_ in ("AUX", "PROPN"):
                sink += 0.045
            elif word.pos_ in ("PRON", "PART"):
                sink -= 0.035
            if word.dep_ in ("ROOT", "nsubj"):
                sink += 0.02

        if not text:
            sink = 0.88 - 0.0015 * i
        elif all(c in ".,!?;:…'\"‘’“”()[]{}—–-" for c in text):
            if text in ("'", "’"):
                sink = 0.89 - 0.0015 * i
            elif "." in text or "…" in text:
                sink = 0.88 - 0.003 * i
            elif "!" in text or "?" in text:
                sink = 0.76 - 0.003 * i
            else:
                sink = 0.73 - 0.004 * i

        if i == 1:
            sink = 0.95
            if word is not None and word.pos_ == "DET":
                sink = 0.925
            elif word is not None and word.pos_ == "PRON":
                sink = 0.965

        sink = float(np.clip(sink, 0.25, 0.98))

        # No non-BOS destination is evidenced consistently: use a broad,
        # mildly recency-weighted causal background rather than a hard link.
        positions = np.arange(1, i + 1)
        residual = 1.0 / np.power(1.0 + i - positions, 0.45)
        residual[-1] *= 0.8
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_boundary_boost", attention


def prog_L10H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened for early tokens and nominal constituents.
    Remaining attention is diffuse and mildly biased toward recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_bias", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in aligned[i]]
        pos = words[0].pos_ if words else ""
        dep = words[0].dep_ if words else ""

        sink = 0.75 + 0.09 * np.exp(-(i - 1) / 8.0)

        if pos in ("NOUN", "PROPN"):
            sink += 0.075
        elif pos in ("DET", "PRON"):
            sink += 0.035
        elif pos == "ADJ":
            sink += 0.015
        elif pos in ("VERB", "AUX"):
            sink -= 0.055
        elif pos == "PUNCT":
            sink -= 0.045

        if dep in ("nsubj", "nsubjpass", "poss"):
            sink += 0.045
        if words and words[0].ent_type_:
            sink += 0.035

        # Initial constituents have especially strong access to the sink.
        if i <= 3 and pos in ("NOUN", "PROPN", "ADJ", "ADP", "ADV"):
            sink += 0.055

        if i == 1:
            sink = 0.95
            if pos == "DET":
                sink = 0.88
            elif pos in ("ADV", "ADP", "NUM"):
                sink = 0.975
            elif pos == "PROPN":
                sink = 0.96

        sink = np.clip(sink, 0.58, 0.975)

        positions = np.arange(1, i + 1)
        residual = (
            0.55 / i
            + 0.45
            * np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_nominal_bias", make_row_stochastic(attention)


def prog_L10H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with positional decay and weaker causal syntactic links.
    Residual attention favors recent context and accessible dependency heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    representatives = {}
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            if word_id not in representatives:
                representatives[word_id] = i

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        # The sink is strongest near the beginning, but remains substantial
        # even after several clauses.
        sink = 0.32 + 0.62 * np.exp(-(i - 1) / 28.0)
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink += 0.045
            elif word.pos_ == "VERB":
                sink -= 0.12
            elif word.pos_ == "ADJ":
                sink -= 0.04
            elif word.pos_ == "PRON" and i > 4:
                sink -= 0.045

        if i == 1:
            sink = 0.94

        # No future positions enter either the positional or syntactic prior.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 11.0)
        residual /= residual.sum()
        residual *= 0.8
        residual[-1] += 0.12

        if word is not None:
            head_index = representatives.get(word.head.i)
            if (
                word.head.i != word.i
                and head_index is not None
                and 0 < head_index < i
            ):
                strength = 0.75
                if word.dep_ in ("advmod", "npadvmod", "acomp", "oprd"):
                    strength = 2.3
                    sink -= 0.14
                elif word.dep_ in ("dobj", "obj", "pobj", "attr"):
                    strength = 1.1
                residual[head_index - 1] += strength

            # Within a split word, allow a small amount of attention to its
            # earlier pieces without treating them as separate lexical items.
            first_piece = representatives.get(word.i)
            if first_piece is not None and 0 < first_piece < i:
                residual[first_piece - 1] += 0.25

            if word.pos_ in ("DET", "ADP"):
                for j in range(i - 1, 0, -1):
                    prior_ids = alignment[j]
                    if prior_ids and doc[prior_ids[0]].pos_ in ("NOUN", "PROPN"):
                        residual[j - 1] += 0.55
                        break

        sink = float(np.clip(sink, 0.20, 0.97))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_syntactic_residual", attention


def prog_L10H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: nearly all attention targets the first token,
    with weak grammatical modulation and a diffuse causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "DET": 0.020,
        "PRON": 0.015,
        "PROPN": 0.025,
        "AUX": 0.010,
        "NOUN": -0.010,
        "ADJ": -0.020,
        "ADV": -0.015,
        "PUNCT": -0.020,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.920
        aligned = alignment[i]
        if aligned:
            sink_mass += sum(
                pos_adjustment.get(doc[k].pos_, 0.0) for k in aligned
            ) / len(aligned)

        if i == 1:
            sink_mass = 0.965
        elif not tokens[i].replace("▁", "").replace("Ġ", "").strip():
            sink_mass = 0.945

        sink_mass = float(np.clip(sink_mass, 0.86, 0.985))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.65 / i + 0.35 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

    return "bos_sink_with_weak_linguistic_modulation", attention


def prog_L10H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with predicate residuals; argument onsets favor predicates,
    while prepositional interiors favor local attachment over distant verbs.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_argument_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        sink = 0.83 + 0.16 * np.exp(-(i - 1) / 4.5)
        target = None

        if word is not None:
            subject = word.dep_ in ("nsubj", "nsubjpass", "csubj", "expl")
            if subject or word.pos_ == "PROPN":
                sink = max(sink, 0.93)
            elif word.pos_ == "AUX":
                sink = max(sink, 0.91)
            elif word.pos_ == "PUNCT":
                sink = max(sink, 0.88)
            elif word.pos_ in ("ADJ", "ADV"):
                sink -= 0.05

            # Trace nominal modifiers through their noun to its predicate.
            branch = word
            if word.dep_ in ("det", "poss", "amod", "compound", "nummod"):
                branch = word.head

            object_branch = branch.dep_ in (
                "dobj", "obj", "iobj", "dative", "pobj", "prep", "obl"
            )
            if object_branch and not subject:
                ancestor = branch.head
                for _ in range(5):
                    if ancestor.pos_ == "VERB":
                        candidates = [j for j in inverse[ancestor.i] if 0 < j < i]
                        if candidates:
                            target = candidates[-1]
                        break
                    if ancestor.head.i == ancestor.i:
                        break
                    ancestor = ancestor.head
                if target is not None:
                    sink = 0.56
                    if word.pos_ == "ADP":
                        sink = 0.47
                    elif word.dep_ == "poss":
                        sink = 0.42

        if tokens[i] in tokenizer.all_special_tokens or not tokens[i].replace("▁", "").strip():
            sink = max(sink, 0.97)

        # Keep the first few queries strongly anchored to the initial token.
        sink = max(sink, 0.98 - 0.018 * (i - 1)) if i <= 4 else sink
        sink = float(np.clip(sink, 0.25, 0.996))
        attention[i, 0] = sink

        residual = np.exp(-(i - np.arange(1, i + 1)) / 5.0)
        residual /= residual.sum()
        if target is None:
            attention[i, 1:i + 1] = (1.0 - sink) * residual
        else:
            attention[i, 1:i + 1] = 0.15 * (1.0 - sink) * residual
            attention[i, target] += 0.85 * (1.0 - sink)

        # Local argument correction: transfer mass only between BOS and
        # explicit attachment keys, preserving self-attention and the tail.
        if (
            target is not None
            and word is not None
            and tokens[i] not in tokenizer.all_special_tokens
            and tokens[i].replace("▁", "").strip()
        ):
            prep = None
            node = branch
            for _ in range(5):
                if node.pos_ == "ADP":
                    prep = node
                    break
                if node.pos_ == "VERB" or node.head.i == node.i:
                    break
                node = node.head

            transfers = []
            desired = None
            if prep is not None:
                # Do not propagate a distant governing verb through an
                # entire prepositional phrase.
                desired = 0.08 if word.pos_ == "ADP" else 0.04
                if prep.head.pos_ in ("NOUN", "PROPN", "PRON"):
                    desired = 0.025
                local = [j for j in inverse[prep.i] if 0 < j < i]
                if local:
                    local_mass = 0.30 if word.dep_ in ("det", "poss") else 0.12
                    transfers.append((local[-1], local_mass))
                if prep.head.pos_ in ("NOUN", "PROPN"):
                    nominal = [j for j in inverse[prep.head.i] if 0 < j < i]
                    if nominal:
                        transfers.append((nominal[-1], 0.16))
            elif branch.dep_ in ("dobj", "obj", "iobj", "dative"):
                if word.dep_ in ("det", "poss"):
                    desired = 0.48
                elif word.dep_ == "amod":
                    earlier = any(
                        c.dep_ == "amod" and c.i < word.i
                        for c in branch.children
                    )
                    desired = 0.22 if earlier else 0.55
                elif word.i == branch.i and word.pos_ in ("NOUN", "PROPN"):
                    pieces = [j for j in inverse[word.i] if j > 0]
                    modified = any(
                        c.dep_ in ("det", "poss", "amod", "compound", "nummod")
                        for c in word.children
                    )
                    if pieces and i != pieces[0]:
                        desired = 0.015 if modified else 0.28
                    else:
                        desired = 0.16 if modified else 0.50
                elif word.pos_ == "PRON" and branch.head.dep_ == "conj":
                    desired = 0.76

            if desired is not None:
                attention[i, 0] += attention[i, target]
                attention[i, target] = 0.0
                transfers.insert(0, (target, desired))
                total = sum(mass for _, mass in transfers)
                scale = min(1.0, attention[i, 0] / total) if total else 1.0
                for key, mass in transfers:
                    mass *= scale
                    attention[i, 0] -= mass
                    attention[i, key] += mass

    return "bos_sink_with_local_argument_residual", make_row_stochastic(attention)


def prog_L10H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective routing to infinitival and subordinate-clause anchors.
    Transfer only BOS mass in those constructions, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        linked = [doc[k] for k in alignment[i] if k < len(doc)]
        word = max(linked, key=lambda w: len(w.text)) if linked else None

        sink = 0.78 + 0.18 * np.exp(-(i - 1) / 4.0)

        if word is not None:
            if word.pos_ == "PROPN" or word.ent_type_ == "PERSON":
                sink += 0.12
            elif word.pos_ == "AUX":
                sink += 0.045
            elif word.pos_ == "NOUN":
                sink += 0.035
            elif word.pos_ == "DET":
                sink += 0.025
            elif word.pos_ in ("ADP", "PART"):
                sink -= 0.065
            elif word.pos_ == "VERB":
                sink -= 0.015

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink += 0.025

        if not clean or clean.isspace():
            sink = max(sink, 0.94)
        elif clean in ("'", "’"):
            sink = max(sink, 0.96)
        elif clean in (".", "!", "?"):
            sink += 0.035

        # Continuation pieces tend to retain unusually strong sink attention.
        if (
            raw not in specials
            and clean
            and clean[0].isalnum()
            and not raw.startswith(("▁", "Ġ"))
        ):
            sink += 0.085

        if raw in specials:
            sink = max(sink, 0.95)
        if i == 1:
            sink = 0.98

        sink = float(np.clip(sink, 0.60, 0.98))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    # The default above remains untouched outside these syntactic scopes.
    first_piece = {}
    for ti, indices in enumerate(alignment):
        if ti > 0 and tokens[ti] not in specials:
            for k in indices:
                if 0 <= k < len(doc) and k not in first_piece:
                    first_piece[k] = ti

    scopes = []
    for marker in doc:
        infinitive = marker.tag_ == "TO" and marker.head.pos_ == "VERB"
        subordinate = marker.dep_ == "mark" and marker.pos_ == "SCONJ"
        if infinitive or subordinate:
            scopes.append((
                marker, marker.head,
                {w.i for w in marker.head.subtree},
                infinitive,
            ))

    for i in range(2, n):
        linked = [doc[k] for k in alignment[i] if 0 <= k < len(doc)]
        word = max(linked, key=lambda w: len(w.text)) if linked else None
        if word is None or tokens[i] in specials:
            continue

        active = [
            scope for scope in scopes
            if word.i in scope[2]
            and scope[0].i <= word.i
            and scope[0].i in first_piece
            and first_piece[scope[0].i] <= i
        ]
        if not active:
            continue

        marker, root, _, infinitive = max(active, key=lambda scope: scope[0].i)
        targets = []
        if infinitive:
            governor = root.head
            bare_complement = any(
                w.dep_ == "xcomp" and w.head.i == root.i
                and not any(c.tag_ == "TO" for c in w.children)
                for w in [word] + list(word.ancestors)
            )
            if bare_complement:
                targets = [(marker, 0.60), (root, 0.40)]
            else:
                targets = [(marker, 0.68), (governor, 0.32)]

            continuation = i > first_piece.get(word.i, i)
            if word.i == marker.i:
                amount = 0.26
            elif word.pos_ == "VERB" or continuation:
                amount = 0.64
            elif word.pos_ == "DET":
                amount = 0.49
            elif word.pos_ in ("NOUN", "PROPN"):
                amount = 0.29
            else:
                amount = 0.55

            if governor.pos_ == "NOUN":
                amount = min(amount, 0.43)
            amount *= np.exp(-max(0, word.i - root.i) / 24.0)
        else:
            nonfinite = next((
                w for w in [word] + list(word.ancestors)
                if w.tag_ == "VBG"
                and w.dep_ in ("advcl", "acl", "xcomp")
                and w.i >= marker.i
            ), None)
            if nonfinite is not None:
                governor = nonfinite.head
                objects = [
                    c for c in governor.children
                    if c.dep_ in ("dobj", "obj", "attr") and c.i < nonfinite.i
                ]
                if objects:
                    targets = [(objects[-1], 0.62), (governor, 0.38)]
                elif governor.pos_ == "NOUN":
                    targets = [(governor, 0.62), (governor.head, 0.38)]
                else:
                    continue
                amount = 0.63 if i > first_piece.get(word.i, i) else 0.48
                if word.i == nonfinite.i and i == first_piece.get(word.i):
                    amount = 0.12
            elif word.i <= root.i + 2:
                subjects = [
                    c for c in root.children
                    if c.dep_ in ("nsubj", "nsubjpass") and c.i < root.i
                ]
                targets = [(marker, 0.76)]
                if subjects:
                    targets.append((subjects[0], 0.24))
                amount = 0.30 if word.i == root.i else 0.38
                if word.pos_ == "ADP":
                    amount = 0.47
                elif word.i < root.i:
                    amount = 0.15
            else:
                continue

        # Strictly earlier anchors: neither the diagonal nor other residuals change.
        eligible = [
            (first_piece[w.i], weight)
            for w, weight in targets
            if w.i in first_piece and 0 < first_piece[w.i] < i
        ]
        total = sum(weight for _, weight in eligible)
        if total > 0:
            moved = min(amount, max(0.0, attention[i, 0] - 0.08))
            attention[i, 0] -= moved
            for j, weight in eligible:
                attention[i, j] += moved * weight / total

    return "bos_sink_with_clause_anchors", attention


def prog_L10H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with small linguistic variations in sink strength.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.88
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "PROPN":
                sink += 0.055
            elif word.pos_ == "NOUN":
                sink += 0.025
            elif word.pos_ in ("VERB", "ADJ", "ADV"):
                sink -= 0.035
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ"):
                sink -= 0.02

            if word.ent_type_:
                sink += 0.015

            if word.is_sent_start:
                sink += 0.025

        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        if not clean:
            sink = 0.965
        elif all(not char.isalnum() for char in clean):
            sink = 0.92
            if clean in ("'", "’"):
                sink = 0.975

        if i == 1:
            sink = 0.97
        elif i <= 3:
            sink += 0.025

        sink = float(np.clip(sink, 0.75, 0.985))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.6 / i + 0.4 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_weak_local_residual", attention


def prog_L10H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse auxiliary-chain attention.
    Transfer only BOS mass to preceding auxiliaries and infinitival governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        # The earliest queries show especially strong initial-token attention.
        sink_mass = 0.94 + 0.04 * np.exp(-(i - 1) / 2.0)

        distances = i - np.arange(1, i + 1)
        background = 0.5 + 0.5 * np.exp(-distances / 4.0)
        background /= background.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    doc = spacy_parse(sentence)
    aligned = align_spacy_to_tokens(sentence, tokens, tokenizer)
    additions = np.zeros_like(attention)

    for anchor in doc:
        is_aux = anchor.pos_ == "AUX" or anchor.dep_ in ("aux", "auxpass")
        is_infinitive = anchor.pos_ == "PART" and anchor.tag_ == "TO"
        is_governor = (
            anchor.pos_ == "VERB"
            and any(
                child.dep_ == "xcomp"
                and any(
                    part.tag_ == "TO" and part.dep_ == "aux"
                    for part in child.subtree
                )
                for child in anchor.children
            )
        )
        if not (is_aux or is_infinitive or is_governor):
            continue

        sources = [j for j in aligned[anchor.i] if j > 0]
        if not sources:
            continue
        j = sources[-1]

        for k in range(anchor.i + 1, min(len(doc), anchor.i + 7)):
            query = doc[k]
            if query.is_punct or query.is_sent_start:
                break

            distance = k - anchor.i
            mass = 0.0

            if is_governor:
                # A predicate introducing an infinitival chain can remain
                # salient throughout its short complement.
                mass = 0.10 * np.exp(-(distance - 1) / 12.0)

            if is_aux or is_infinitive:
                local_mass = 0.0
                if distance == 1:
                    local_mass = 0.045
                    if anchor.tag_ == "MD" and query.pos_ in ("PRON", "ADV", "PART"):
                        local_mass = 0.40
                    elif is_infinitive:
                        local_mass = 0.40 if query.pos_ == "AUX" else 0.14
                elif distance <= 3 and query.pos_ in ("VERB", "AUX", "ADV"):
                    local_mass = 0.055 * np.exp(-(distance - 2) / 2.0)
                    if anchor.tag_ == "MD" and query.pos_ == "VERB":
                        local_mass = 0.14 * np.exp(-(distance - 2) / 2.0)
                mass = max(mass, local_mass)

            for i in aligned[k]:
                if j < i:
                    additions[i, j] += mass

    # Keep the original diagonal and all unrelated entries exactly unchanged.
    # Multiple detected relations share a bounded transfer from the BOS sink.
    for i in range(1, n):
        total = additions[i].sum()
        if total > 0.0:
            transfer = min(total, 0.65, max(0.0, attention[i, 0] - 0.25))
            attention[i] += additions[i] * (transfer / total)
            attention[i, 0] -= transfer

    return "bos_sink_auxiliary_chain", attention


def prog_L10H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: nearly every query attends to the first token.
    A small causal background carries the remaining mass, with mild POS modulation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_causal_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = text.strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink_mass = 0.935 - 0.012 * np.log1p(i)

        if word is not None:
            if word.pos_ == "PROPN":
                sink_mass += 0.018
            elif word.pos_ in ("ADP", "DET", "PART"):
                sink_mass -= 0.012
            elif word.pos_ in ("NOUN", "ADJ"):
                sink_mass += 0.005

        if not stripped:
            sink_mass = 0.960
        elif all(not c.isalnum() for c in stripped):
            sink_mass = 0.925
        if i == 1:
            sink_mass = 0.945

        sink_mass = float(np.clip(sink_mass, 0.83, 0.97))

        # The supplied edges establish the sink, not a particular residual target.
        # Use a diffuse background with only a weak local preference.
        positions = np.arange(1, i + 1)
        background = 1.0 + 0.25 * np.exp(-(i - positions) / 4.0)
        background /= background.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_causal_background", attention


def prog_L10H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly every query attends to the first token,
    with small punctuation/POS corrections and diffuse causal residual attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()

        sink_mass = 0.91
        if words:
            if all(w.is_punct for w in words):
                sink_mass = 0.945
            elif any(w.pos_ == "PRON" for w in words):
                sink_mass = 0.875
            elif any(w.pos_ == "PROPN" for w in words):
                sink_mass = 0.94

        if not clean or tokens[i] in tokenizer.all_special_tokens:
            sink_mass = 0.97
        elif not words and all(not c.isalnum() for c in clean):
            sink_mass = 0.95

        if i == 1:
            sink_mass = 0.97

        # No non-BOS target is supported by the examples: keep the
        # remaining mass diffuse, with only a weak recency preference.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 6.0) / np.exp(-distances / 6.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", make_row_stochastic(attention)


def prog_L10H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak lexical-class modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_sink = {
        "NOUN": 0.875,
        "PROPN": 0.890,
        "VERB": 0.860,
        "PRON": 0.835,
        "DET": 0.855,
        "ADP": 0.830,
        "ADJ": 0.795,
        "ADV": 0.805,
        "AUX": 0.795,
        "CCONJ": 0.800,
        "SCONJ": 0.810,
        "PART": 0.815,
        "NUM": 0.850,
        "INTJ": 0.870,
        "PUNCT": 0.840,
        "SPACE": 0.950,
    }

    for i in range(1, n):
        piece = tokens[i]
        clean = piece.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]

        sink = 0.850
        if aligned:
            sink = np.mean([
                pos_sink.get(doc[k].pos_, 0.850) for k in aligned
            ])

        if not clean:
            sink = 0.950
        elif all(c in "'’" for c in clean):
            sink = 0.960
        elif all(c in ".!?" for c in clean):
            sink = 0.910

        # Early positions strongly favor the sink even before context develops.
        sink += 0.055 * np.exp(-(i - 2) / 2.5)
        if i == 1:
            sink = 0.965
        sink = float(np.clip(sink, 0.73, 0.98))

        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_weak_local_residual", attention


def prog_L10H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the initial token.
    Unobserved residual attention is spread uniformly over other causal tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.965
            attention[i, 1:i + 1] = 0.035 / i

    return "bos_attention_sink", attention


def prog_L10H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at discourse boundaries and function tokens.
    Content words retain a larger, weakly recency-biased causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = text.strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink = 0.85
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink = 0.69
            elif word.pos_ == "ADJ":
                sink = 0.77
            elif word.pos_ == "VERB":
                sink = 0.87
            elif word.pos_ == "ADV":
                sink = 0.87
            elif word.pos_ in ("PRON", "AUX", "SCONJ"):
                sink = 0.90
            elif word.pos_ in ("DET", "ADP", "PART", "CCONJ"):
                sink = 0.85

            if word.dep_ in ("ROOT", "conj", "advcl", "ccomp"):
                sink += 0.025
            if word.is_sent_start:
                sink = max(sink, 0.93)

        if not stripped:
            sink = 0.94
        elif all(c in ".,;:!?\"'“”‘’—–-()[]{}" for c in stripped):
            sink = 0.89
            if any(c in "\"'“”‘’" for c in stripped):
                sink = 0.94
            elif any(c in ".!?" for c in stripped):
                sink = 0.91

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.95
        if i == 1:
            sink = max(sink, 0.95)

        sink = float(np.clip(sink, 0.55, 0.98))
        positions = np.arange(1, i + 1)
        remainder = 0.5 + np.exp(-(i - positions) / 6.0)
        remainder /= remainder.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * remainder

    return "bos_sink_with_linguistic_gating", attention


def prog_L10H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal background and occasional
    backoff to an earlier predicate at coordinated clause transitions."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        if i == 0:
            continue
        for word_id in word_ids:
            word_tokens[word_id].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None

        # The overwhelming shared feature is attention to the initial token.
        sink_mass = 0.96 - 0.09 * (1.0 - np.exp(-i / 35.0))
        if word is not None and word.is_punct:
            sink_mass -= 0.08

        target = None
        transition = False
        if word is not None:
            transition = (
                word.dep_ == "conj" and word.pos_ in ("VERB", "AUX", "ADJ")
            ) or word.dep_ == "cc"

            if transition:
                # Prefer the governing predicate of a coordination.
                governor = word.head
                if word.dep_ == "cc" and governor.dep_ == "conj":
                    governor = governor.head
                if governor.pos_ in ("VERB", "AUX", "ADJ"):
                    candidates = [
                        j for j in word_tokens[governor.i] if 0 < j < i
                    ]
                    if candidates:
                        target = candidates[0]

                # Otherwise use the most recent completed predicate.
                if target is None:
                    for previous in reversed(doc[:word.i]):
                        if previous.pos_ in ("VERB", "AUX"):
                            candidates = [
                                j for j in word_tokens[previous.i] if 0 < j < i
                            ]
                            if candidates:
                                target = candidates[0]
                                break

        if target is not None:
            sink_mass -= 0.32 if word.dep_ == "conj" else 0.20

        sink_mass = float(np.clip(sink_mass, 0.45, 0.98))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 12.0)
        background /= background.sum()

        remainder = 1.0 - sink_mass
        if target is not None:
            attention[i, target] += remainder * 0.85
            attention[i, 1:i + 1] += remainder * 0.15 * background
        else:
            attention[i, 1:i + 1] = remainder * background

    return "bos_sink_with_clause_backoff", make_row_stochastic(attention)


def prog_L10H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakening gradually with position.
    Linguistic features mildly modulate sink strength; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_logit = 3.65 - 0.030 * i - 0.24 * np.log1p(i)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink_logit -= 0.55
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "DET"):
                sink_logit += 0.15
            elif word.pos_ in ("VERB", "CCONJ", "SCONJ"):
                sink_logit -= 0.15

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L10H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with phrase introducers, plus predicate-centered complement attention.
    Redistribute non-self mass only when a preceding syntactic predicate is available.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_complements", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, aligned in enumerate(alignment):
        for k in aligned:
            inverse[k].append(i)

    special = set(tokenizer.all_special_tokens)
    introducers = []
    for word in doc:
        if word.pos_ == "ADP" or word.tag_ == "TO":
            introducers.append(word.i)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.03 * np.exp(-(i - positions) / 4.0)

        sink = 0.82
        if word is not None:
            pos, dep = word.pos_, word.dep_
            if dep in ("nsubj", "nsubjpass", "csubj", "expl"):
                sink = 0.91
            elif pos == "PROPN":
                sink = 0.91
            elif pos == "PRON":
                sink = 0.84
            elif pos == "DET":
                sink = 0.77
            elif pos == "ADJ":
                sink = 0.78
            elif pos == "NOUN":
                sink = 0.79
            elif pos in ("VERB", "AUX"):
                sink = 0.75
            elif pos in ("ADV", "CCONJ", "SCONJ"):
                sink = 0.66
            elif pos == "PUNCT":
                sink = 0.64

            ancestors = {word.i}
            parent = word
            for _ in range(len(doc)):
                if parent.head.i == parent.i:
                    break
                parent = parent.head
                ancestors.add(parent.i)

            governing = []
            recent = []
            for k in introducers:
                available = [j for j in inverse[k] if 0 < j <= i]
                if not available:
                    continue
                j = available[-1]
                if k in ancestors:
                    governing.append(j)
                elif doc[k].head.i in ancestors:
                    # Infinitival markers are dependents of their verb.
                    if doc[k].tag_ == "TO":
                        governing.append(j)
                    else:
                        recent.append(j)
                else:
                    recent.append(j)

            if governing:
                key = max(governing)
                residual[key] += 1.8
                sink -= 0.30
                if word.pos_ == "ADP" or word.tag_ == "TO":
                    sink = 0.54
            elif recent:
                key = max(recent)
                distance = i - key
                strength = np.exp(-distance / 9.0)
                residual[key] += 0.65 * strength
                sink -= 0.14 * strength

            # Possessive determiners can introduce a weaker local phrase anchor.
            for k in ancestors:
                for child in doc[k].children:
                    if child.dep_ == "poss":
                        available = [j for j in inverse[child.i] if 0 < j < i]
                        if available:
                            residual[available[-1]] += 0.18

            if word.is_sent_start:
                sink = max(sink, 0.91)

        if i == 1:
            sink = 0.955
        elif i <= 3:
            sink = max(sink, 0.87 + 0.025 * (3 - i))

        if tokens[i] in special:
            sink = max(sink, 0.95)

        sink = float(np.clip(sink, 0.20, 0.98))
        attention[i, 0] = sink
        total = residual.sum()
        if total > 0:
            attention[i, :i + 1] += (1.0 - sink) * residual / total
        else:
            attention[i, 0] = 1.0

        # Targeted correction: a realized predicate anchors its complements.
        # Transfer only non-self mass; retain the original local decay exactly.
        if (
            i > 3
            and word is not None
            and tokens[i] not in special
            and not word.is_sent_start
            and word.dep_ not in ("nsubj", "nsubjpass", "csubj", "expl")
            and word.pos_ != "PROPN"
        ):
            candidates = []
            if word.pos_ in ("VERB", "ADJ"):
                candidates.extend(
                    c for c in word.children
                    if c.dep_ in ("aux", "auxpass", "cop")
                )
            candidates.extend(word.ancestors)

            predicate = None
            predicate_key = None
            for candidate in candidates:
                if candidate.pos_ not in ("VERB", "AUX"):
                    continue
                available = [j for j in inverse[candidate.i] if 0 < j < i]
                if available:
                    predicate = candidate
                    predicate_key = available[-1]
                    break

            if predicate is not None:
                targets = np.zeros(i + 1, dtype=np.float64)
                targets[predicate_key] = 1.0
                for child in predicate.children:
                    if child.dep_ in (
                        "nsubj", "nsubjpass", "csubj", "aux", "auxpass", "cop"
                    ):
                        available = [j for j in inverse[child.i] if 0 < j < i]
                        if available:
                            targets[available[-1]] += 0.30
                targets /= targets.sum()

                distance = i - predicate_key
                moved = 0.0
                for k in introducers:
                    available = [j for j in inverse[k] if 0 < j < i]
                    if not available:
                        continue
                    key = available[-1]
                    fraction = 0.50 if k in ancestors else 0.90
                    amount = fraction * attention[i, key]
                    attention[i, key] -= amount
                    moved += amount

                # Distant or descriptive material returns more stale-anchor
                # mass to BOS rather than inventing a long predicate edge.
                bos_share = (
                    0.60 if distance > 4 or word.pos_ in ("ADJ", "ADV")
                    else 0.15
                )
                attention[i, 0] += bos_share * moved
                attention[i, :i + 1] += (1.0 - bos_share) * moved * targets

                extra = 0.0
                if word.pos_ in ("PUNCT", "CCONJ", "SCONJ"):
                    extra = 0.18
                elif distance <= 3:
                    if word.pos_ in ("DET", "PRON"):
                        extra = 0.18
                    elif word.pos_ in ("VERB", "AUX"):
                        extra = 0.14
                    elif word.pos_ in ("NOUN", "ADP"):
                        extra = 0.10

                amount = min(extra, max(0.0, attention[i, 0] - 0.20))
                attention[i, 0] -= amount
                attention[i, :i + 1] += amount * targets

    return "bos_sink_with_predicate_complements", make_row_stochastic(attention)


def prog_L10H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a stronger early-position bias.
    Residual attention follows recency and weak causal syntactic links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        sink = 0.69 + 0.23 * np.exp(-(i - 1) / 5.0)
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "PRON"):
                sink -= 0.065 * (1.0 - np.exp(-(i - 1) / 4.0))
            elif word.pos_ in ("ADV", "CCONJ", "SCONJ", "PART"):
                sink += 0.045
            elif word.pos_ == "PUNCT":
                sink -= 0.025

        if not word_ids and tokens[i].strip() == "":
            sink += 0.07
        sink = float(np.clip(sink, 0.48, 0.97))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()
        residual = 0.75 * residual + 0.25 / i

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if word.head.i != word.i and head_positions:
                residual *= 0.8
                for j in head_positions:
                    residual[j - 1] += 0.2 / len(head_positions)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L10H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position and linguistic modulation.
    Non-sink attention is a weak, causally distributed recency background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The only consistently supported destination is the initial token.
        sink_mass = 0.76 + 0.15 * np.exp(-(i - 1) / 12.0)

        indices = alignment[i]
        if indices:
            word = doc[indices[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.045
            elif word.pos_ in ("VERB", "ADV", "ADP"):
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.09

            # Subword continuations still predominantly route to the sink.
            if i > 1 and any(k in alignment[i - 1] for k in indices):
                sink_mass += 0.025

        if tokens[i].strip() in ("'", "’"):
            sink_mass += 0.12

        sink_mass = float(np.clip(sink_mass, 0.55, 0.97))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        background = 0.65 / i + 0.35 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L10H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and on nominal tokens.
    Residual attention favors preceding predicates and causal syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.63 + 0.34 * np.exp(-(i - 1) / 5.0)
        if pos in ("NOUN", "PROPN"):
            sink += 0.13
        elif pos in ("DET", "ADP", "AUX"):
            sink += 0.08
        elif pos in ("ADJ", "NUM"):
            sink += 0.04
        elif pos == "VERB":
            sink -= 0.15
        elif pos == "PRON":
            sink -= 0.10

        if dep in ("xcomp", "ccomp", "advcl"):
            sink -= 0.07

        if tokens[i].strip() == "▁" or tokens[i].isspace():
            sink = max(sink, 0.88)
        if word is not None and word.is_punct:
            if word.text in ("'", "’"):
                sink = max(sink, 0.88)
            elif word.text in (".", ",", ";", ":"):
                sink += 0.12
            else:
                sink -= 0.08

        sink = float(np.clip(sink, 0.30, 0.97))
        if i == 1:
            sink = 0.98

        weights = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            distance = i - j
            score = 0.12 * np.exp(-distance / 8.0)
            if alignment[j]:
                previous = doc[alignment[j][-1]]
                if previous.pos_ in ("VERB", "ADJ"):
                    score += 0.9 / (1.0 + 0.10 * distance)
                elif previous.pos_ == "AUX":
                    score += 0.25 / (1.0 + 0.15 * distance)
                elif previous.pos_ in ("NOUN", "PROPN"):
                    score += 0.12 / (1.0 + 0.15 * distance)
            weights[j] = score

        if word is not None:
            head = word.head
            if head.i != word.i:
                targets = [j for j in inverse[head.i] if 0 < j < i]
                if targets:
                    boost = 2.5 if dep in ("conj", "xcomp", "ccomp") else 1.2
                    for j in targets:
                        weights[j] += boost / len(targets)

        # Preserve a modest self component without allowing it to dominate.
        weights[i] += 0.10
        total = weights.sum()
        if total > 0.0:
            attention[i, :i + 1] = (1.0 - sink) * weights / total
        else:
            attention[i, i] = 1.0 - sink
        attention[i, 0] = sink

    return "bos_sink_with_predicate_residual", make_row_stochastic(attention)


def prog_L10H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing causal background mass.
    Position, rather than syntactic relationships, controls the dominant pattern.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        background_odds = 0.041 + 0.0105 * max(i - 5, 0)
        sink_mass = 1.0 / (1.0 + background_odds)

        # Spread the residual broadly, with only a mild recency preference.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        weights = 0.75 + 0.25 * np.exp(-distances / 16.0)
        weights /= weights.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * weights

    return "bos_sink_with_position_decay", attention


def prog_L10H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a mild positional decay and linguistic modulation.
    Residual attention favors nearby tokens and preceding syntactic governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None

        # The sink remains dominant even well beyond the opening phrase.
        sink = 0.64 + 0.18 * np.exp(-(i - 1) / 24.0)
        sink += 0.12 * np.exp(-(i - 1) / 1.5)

        if word is not None:
            if word.pos_ in ("PRON", "AUX", "DET"):
                sink += 0.035
            elif word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.065
            elif word.pos_ == "ADP":
                sink -= 0.035

            if word.dep_ in ("pobj", "dobj", "obj", "attr"):
                sink -= 0.055

            if word.is_punct:
                if any(c in word.text for c in ".!?"):
                    sink -= 0.18
                elif any(c in word.text for c in "\"'“”‘’"):
                    sink += 0.035

        if i == 1:
            sink = 0.95

        sink = float(np.clip(sink, 0.38, 0.98))

        # A broad local background avoids inventing a second sharp pattern.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()
        residual *= 0.45
        residual[-1] += 0.10

        if i > 1:
            residual[-2] += 0.25
        else:
            residual[-1] += 0.25

        governor_tokens = []
        if word is not None and word.head.i != word.i:
            governor_tokens = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]

        if governor_tokens:
            for j in governor_tokens:
                residual[j - 1] += 0.20 / len(governor_tokens)
        elif i > 1:
            residual[-2] += 0.20
        else:
            residual[-1] += 0.20

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", attention


def prog_L10H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with contextual induction; dialogue can retrieve a broader
    earlier continuation rather than a single next-token target.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_continuations", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    pos = []
    for indices in alignment:
        pos.append(doc[indices[-1]].pos_ if indices else "")

    # Restrict the added route to quoted dialogue.
    dialogue = sum(c in ('"', "“", "”") for c in sentence) >= 2
    word_ends = {}
    for k, indices in enumerate(alignment):
        for si in indices:
            word_ends[si] = k

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The dominant structure is a nearly universal first-token sink.
        sink = 0.975 - 0.105 * (1.0 - np.exp(-(i - 1) / 32.0))
        if pos[i] in ("VERB", "AUX"):
            sink -= 0.025

        remainder = 1.0 - sink
        distances = i - np.arange(1, i + 1)
        background = 0.35 / i + 0.65 * np.exp(-distances / 5.0)
        background /= background.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = remainder * background

        # Dialogue retrieval: include the earlier word's end and a short
        # continuation. Unlike the old single-edge route, this also handles
        # the first piece of a repeated, multi-piece word.
        if dialogue and i >= 5 and alignment[i] and tokens[i] not in special_tokens:
            route = np.zeros(n, dtype=np.float64)
            strength = 0.0
            if pos[i] in ("NOUN", "PROPN", "VERB", "ADJ"):
                best = None
                for j in range(1, i - 3):
                    if pos[j] != pos[i] or not alignment[j]:
                        continue
                    end = word_ends[alignment[j][-1]]
                    if end + 2 >= i:
                        continue
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    context = embedding_similarity(tokens, i - 1, j - 1, tokenizer)
                    threshold = 0.72 if context >= 0.75 else 0.90
                    if similarity < threshold:
                        continue
                    score = similarity + 0.15 * max(context, 0.0)
                    if best is None or score > best[0]:
                        best = (score, end, context, similarity)

                if best is not None:
                    _, end, context, similarity = best
                    strength = float(np.clip(
                        0.68 + 0.18 * max(context, 0.0), 0.0, 0.88
                    ))
                    if context >= 0.75:
                        offsets = (0, 1, 2)
                        weights = (0.10, 0.80, 0.10)
                    else:
                        offsets = (-1, 0, 1, 2, 3, 4)
                        weights = (0.06, 0.18, 0.34, 0.20, 0.12, 0.10)
                    for offset, weight in zip(offsets, weights):
                        target = end + offset
                        if 0 < target < i and tokens[target] not in special_tokens:
                            route[target] += weight

            # After a completed quoted clause, anaphoric pronouns can retrieve
            # its predicate or object without requiring lexical repetition.
            if strength == 0.0 and pos[i] == "PRON":
                boundaries = [
                    k for k in range(1, i)
                    if "?" in tokens[k] or "!" in tokens[k]
                ]
                if boundaries:
                    current = doc[alignment[i][-1]]
                    subject = current.dep_ in ("nsubj", "nsubjpass", "poss")
                    candidates = [
                        k for k in range(1, i - 3)
                        if alignment[k]
                        and (
                            (subject and pos[k] == "VERB")
                            or (
                                not subject
                                and pos[k] in ("NOUN", "PROPN")
                                and doc[alignment[k][-1]].dep_
                                in ("dobj", "obj", "pobj", "attr")
                            )
                        )
                    ]
                    if candidates:
                        anchor = word_ends[alignment[candidates[-1]][-1]]
                        for offset, weight in ((-1, 0.10), (0, 0.35), (1, 0.40), (2, 0.15)):
                            target = anchor + offset
                            if 0 < target < i and tokens[target] not in special_tokens:
                                route[target] += weight
                        strength = 0.48 if subject else 0.52

            if strength > 0.0 and route.sum() > 0.0:
                # Transfer only BOS mass: preserve the original diagonal,
                # background, and positional decay exactly.
                mass = min(strength, attention[i, 0])
                attention[i, 0] -= mass
                attention[i] += mass * route / route.sum()
                continue

        # A secondary induction-like route: the current content token and
        # its predecessor resemble an earlier two-token context.
        if i < 4 or pos[i] not in ("NOUN", "PROPN", "VERB", "ADJ"):
            continue
        if tokens[i] in special_tokens or not alignment[i]:
            continue

        # Require the current piece to finish its spaCy word.
        if i + 1 < n and alignment[i + 1]:
            if alignment[i][-1] in alignment[i + 1]:
                continue

        best_strength = 0.0
        best_target = None
        for j in range(2, i - 1):
            if pos[j] != pos[i] or not alignment[j]:
                continue
            if alignment[j + 1] and alignment[j][-1] in alignment[j + 1]:
                continue
            if tokens[j + 1] in special_tokens:
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            if similarity < 0.88:
                continue
            context_similarity = embedding_similarity(
                tokens, i - 1, j - 1, tokenizer
            )
            strength = (
                0.86
                * np.clip((similarity - 0.88) / 0.12, 0.0, 1.0)
                * np.clip((context_similarity - 0.45) / 0.30, 0.0, 1.0)
            )
            if strength > best_strength:
                best_strength = float(strength)
                best_target = j + 1

        if best_target is not None:
            attention[i] *= 1.0 - best_strength
            attention[i, best_target] += best_strength

    return "bos_sink_with_dialogue_continuations", make_row_stochastic(attention)


def prog_L10H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker recency and sentence-boundary attention.
    Sink strength decreases after discourse boundaries and for referential tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_fallback", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    boundary = np.zeros(n, dtype=np.float64)
    pos = [""] * n
    continuation = np.zeros(n, dtype=bool)

    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos[i] = word.pos_
            if i > 1:
                continuation[i] = bool(
                    set(aligned).intersection(alignment[i - 1])
                )

        # Combined punctuation/quote model tokens can mark a sentence boundary.
        if any(c in tokens[i] for c in ".!?"):
            boundary[i] = 1.0

    attention[0, 0] = 1.0
    last_boundary = -1

    for i in range(1, n):
        sink = 0.77 + 0.13 * np.exp(-(i - 1) / 7.0)

        if pos[i] in ("DET", "ADP", "ADJ", "NOUN", "PROPN"):
            sink += 0.035
        elif pos[i] == "PRON":
            sink -= 0.09
        elif pos[i] in ("VERB", "ADV"):
            sink -= 0.025

        if continuation[i]:
            sink += 0.025

        if last_boundary >= 1:
            distance = i - last_boundary
            sink -= 0.29 * np.exp(-distance / 13.0)

        if boundary[i]:
            sink -= 0.10

        sink = float(np.clip(sink, 0.30, 0.95))
        if i == 1:
            sink = 0.95

        keys = np.arange(1, i + 1)
        distance = i - keys
        weights = (
            0.16
            + np.exp(-distance / 4.5)
            + 4.0 * boundary[1:i + 1] * np.exp(-distance / 22.0)
        )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        if boundary[i]:
            last_boundary = i

    return "bos_sink_with_boundary_fallback", attention


def prog_L10H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with punctuation/entity boosts and a weaker causal,
    recency-weighted syntactic background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    sink = 0
    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i]]
        word = max(words, key=lambda w: len(w.text)) if words else None

        sink_mass = 0.55
        if word is not None:
            pos = word.pos_
            if pos == "PROPN" or word.ent_type_:
                sink_mass = 0.79
            elif pos == "NOUN":
                sink_mass = 0.63
            elif pos == "ADJ":
                sink_mass = 0.59
            elif pos in ("DET", "ADP", "CCONJ", "SCONJ"):
                sink_mass = 0.59
            elif pos in ("VERB", "ADV"):
                sink_mass = 0.54
            elif pos in ("AUX", "PART"):
                sink_mass = 0.44
            elif pos == "PRON":
                sink_mass = 0.52

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink_mass += 0.05

            # Noninitial pieces retain the sink preference of their word.
            if inverse[word.i] and i != inverse[word.i][0]:
                sink_mass -= 0.06

        if not surface:
            sink_mass = 0.76
        elif all(not c.isalnum() for c in surface):
            sink_mass = 0.70
            if any(c in "'’" for c in surface):
                sink_mass = 0.90
            elif any(c in ".!?" for c in surface):
                sink_mass = 0.75

        if i == 1:
            sink_mass = 0.87
        sink_mass = float(np.clip(sink_mass, 0.35, 0.94))

        positions = np.arange(1, i + 1)
        background = 0.15 + np.exp(-(i - positions) / 3.5)
        background[-1] += 0.25

        if word is not None:
            # A preceding governor can attract the nonsink mass.
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    background[candidates[-1] - 1] += 1.6

            # Predicate context remains available even when the governor
            # lies in the future and is inaccessible to causal attention.
            for j in range(max(1, i - 10), i):
                if any(doc[k].pos_ == "VERB" for k in alignment[j]):
                    background[j - 1] += 0.35 * np.exp(-(i - j) / 6.0)

        attention[i, sink] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_syntactic_background", attention


def prog_L10H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and stronger sink
    preference at punctuation and syntactic boundaries."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boost", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_multiplier = {
        "PRON": 1.15,
        "DET": 1.10,
        "AUX": 1.50,
        "VERB": 1.45,
        "NOUN": 0.60,
        "PROPN": 0.80,
        "ADJ": 0.75,
        "ADV": 1.00,
        "ADP": 0.85,
        "CCONJ": 1.30,
        "SCONJ": 1.10,
        "PART": 0.90,
        "NUM": 0.70,
    }

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in aligned[i]]
        word = words[-1] if words else None

        sink_strength = 20.0
        if word is not None:
            sink_strength *= pos_multiplier.get(word.pos_, 1.0)
            if word.dep_ in ("cc", "mark"):
                sink_strength *= 1.15

        if not text:
            sink_strength = 85.0
        elif all(c in ".,!?;:…'\"‘’“”()[]{}—–-" for c in text):
            if any(c in "'’" for c in text):
                sink_strength = 120.0
            elif any(c in ".!?…" for c in text):
                sink_strength = 100.0
            elif any(c in "\"“”" for c in text):
                sink_strength = 65.0
            else:
                sink_strength = 48.0

        if i == 1:
            sink_probability = 0.965
        else:
            sink_probability = sink_strength / (sink_strength + i)

        # No non-BOS target is established by the examples: use a diffuse,
        # mildly recency-biased causal distribution for the residual mass.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.8 + 0.4 * np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_probability) * residual / residual.sum()
        )
        attention[i, 0] = sink_probability

    return "bos_sink_with_boundary_boost", attention


def prog_L10H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with targeted leakage to preceding nominal-phrase anchors.
    Redistribute only BOS mass; retain the original self-attention and decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Reuse the existing alignment to locate preceding syntactic anchors.
    word_tokens = [[] for _ in doc]
    for ti, linked in enumerate(alignment):
        if ti > 0:
            for wi in linked:
                word_tokens[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        linked = alignment[i]
        word = doc[linked[0]] if linked else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.965 - 0.052 * np.log1p(i - 1)

        if pos in ("PRON", "AUX", "SCONJ"):
            sink += 0.065
        elif pos == "VERB":
            sink += 0.035
        elif pos in ("NOUN", "PROPN"):
            sink -= 0.080
        elif pos == "ADJ":
            sink -= 0.050
        elif pos in ("DET", "CCONJ", "PART"):
            sink += 0.020

        if dep in ("nsubj", "nsubjpass", "csubj"):
            sink += 0.025
        elif dep in ("dobj", "obj", "pobj", "attr"):
            sink -= 0.045

        clean = tokens[i].replace("▁", " ").replace("Ġ", " ")
        if not clean.strip():
            sink += 0.050
        elif clean.strip() in ("'", "’"):
            sink += 0.100
        elif pos == "PUNCT":
            if any(c in clean for c in ".!?"):
                sink -= 0.100
            elif any(c in clean for c in "\"“”"):
                sink += 0.020

        if i == 1:
            sink = 0.965
            if pos == "PRON":
                sink = 0.980
            elif pos == "PROPN":
                sink = 0.925

        sink = float(np.clip(sink, 0.45, 0.985))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.55 / i + 0.45 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Special case: object noun phrases retrieve their preceding
        # preposition/determiner/governor instead of retaining all BOS mass.
        if word is not None and (
            pos in ("NOUN", "PROPN")
            or dep in ("amod", "det", "poss")
        ):
            nominal = word
            if dep in ("amod", "det", "poss", "compound"):
                if word.head.pos_ in ("NOUN", "PROPN"):
                    nominal = word.head

            if nominal.dep_ in ("pobj", "obj", "dobj"):
                anchors = []
                has_prep = False
                has_det = False
                has_poss = False

                candidates = [
                    (c, 1.0 if c.dep_ == "det" else 0.8)
                    for c in nominal.children
                    if c.dep_ in ("det", "poss")
                ]
                if nominal.head.pos_ == "ADP":
                    candidates.append((nominal.head, 1.5))
                elif nominal.head.pos_ == "VERB":
                    candidates.append((nominal.head, 0.7))

                for anchor, weight in candidates:
                    preceding = [
                        j for j in word_tokens[anchor.i] if 0 < j < i
                    ]
                    if not preceding:
                        continue
                    j = preceding[0]
                    if i - j > 12:
                        continue
                    anchors.append((j, weight))
                    has_prep |= anchor.pos_ == "ADP"
                    has_det |= anchor.dep_ == "det"
                    has_poss |= anchor.dep_ == "poss"

                if anchors and (has_prep or has_det or has_poss):
                    if pos in ("NOUN", "PROPN"):
                        transfer = (
                            0.40 + 0.10 * has_det
                            if has_prep
                            else 0.38 if has_det else 0.25
                        )
                    else:
                        transfer = 0.16 if has_prep else 0.08

                    transfer = min(transfer, max(0.0, sink - 0.10))
                    total_weight = sum(weight for _, weight in anchors)
                    attention[i, 0] -= transfer
                    for j, weight in anchors:
                        attention[i, j] += transfer * weight / total_weight

    return "bos_sink_with_nominal_anchors", make_row_stochastic(attention)


def prog_L10H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a secondary first-content-token anchor.
    Early phrase continuations favor the anchor; later lexical tokens favor BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_initial_phrase_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = tokenizer.all_special_tokens

    anchor = 0
    for i, token in enumerate(tokens):
        if token not in specials and token.replace("▁", "").strip():
            anchor = i
            break

    first_word = doc[alignment[anchor][0]] if alignment[anchor] else None
    initial_pos = first_word.pos_ if first_word is not None else ""
    introductory = initial_pos in ("ADP", "SCONJ", "ADV", "NUM")
    attention[0, 0] = 1.0

    for i in range(1, n):
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        clean = tokens[i].replace("▁", "").strip()

        if i == anchor:
            attention[i, 0] = 0.94
            attention[i, i] = 0.06
            continue

        # Content-bearing objects and names strongly reinforce the sink.
        bos_mass = 0.51
        if pos in ("NOUN", "PROPN"):
            bos_mass += 0.17
        elif pos == "ADJ":
            bos_mass += 0.10
        elif pos in ("ADP", "DET"):
            bos_mass += 0.03
        elif pos in ("VERB", "AUX"):
            bos_mass -= 0.09

        if word is not None:
            if word.ent_type_:
                bos_mass += 0.08
            if dep in ("dobj", "obj", "pobj", "attr"):
                bos_mass += 0.05
            # Fragmented lexical items often remain strong sink queries.
            if len(mapped) == 1 and len(clean) < len(word.text):
                bos_mass += 0.06

        if clean and not clean.isalnum():
            bos_mass += 0.05
        if not clean:
            bos_mass = 0.56

        distance = i - anchor
        anchor_mass = 0.16 * np.exp(-max(distance - 3, 0) / 15.0)
        if 0 < distance <= 4:
            if introductory:
                if pos not in ("VERB", "AUX") and dep not in ("nsubj", "nsubjpass"):
                    anchor_mass = 0.83 - 0.025 * (distance - 1)
            elif pos == "AUX":
                anchor_mass = 0.74
            elif pos == "VERB" and dep == "ROOT" and distance <= 2:
                anchor_mass = 0.62
            elif pos == "ADV" and distance <= 2:
                anchor_mass = 0.65
            elif initial_pos == "DET" and pos in ("NOUN", "PROPN"):
                anchor_mass = 0.40

        if anchor_mass > 0.35:
            bos_mass = min(bos_mass, 0.96 - anchor_mass)

        bos_mass = float(np.clip(bos_mass, 0.08, 0.91))
        anchor_mass = min(anchor_mass, 0.97 - bos_mass)
        remainder = 1.0 - bos_mass - anchor_mass

        # Low-amplitude causal background, mildly biased toward recent tokens.
        positions = np.arange(i + 1)
        background = 0.35 + np.exp(-(i - positions) / 5.0)
        attention[i, :i + 1] = remainder * background / background.sum()
        attention[i, 0] += bos_mass
        attention[i, anchor] += anchor_mass

    return (
        "bos_sink_with_initial_phrase_anchor",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L11H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a secondary prefix/boundary sink in determiner-led narration
    and quoted dialogue; corrections transfer only BOS mass, preserving diagonals.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_prefix_boundary_exception", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = np.clip(0.977 - 0.0018 * i, 0.82, 0.99)
        if i == 1:
            sink_mass = 0.99

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp((positions - i) / 12.0)
            / np.exp((positions - i) / 12.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Keep the original prediction unless a determiner-led opening or
    # paired quotation marks indicate the secondary-sink regime.
    doc = spacy_parse(sentence)
    lexical = [w for w in doc if not w.is_space and not w.is_punct]
    determiner_led = bool(lexical and lexical[0].pos_ == "DET")
    dialogue = sum(c in '"“”' for c in sentence) >= 2

    if determiner_led or dialogue:
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        clean = [t.lstrip("▁Ġ") for t in tokens]
        specials = set(tokenizer.all_special_tokens)

        for i in range(2, n):
            if tokens[i] in specials:
                continue

            words = [doc[k] for k in aligned[i]]
            pos = {w.pos_ for w in words}
            boundary = bool(clean[i]) and all(
                c in ".,;:!?\"'“”‘’" for c in clean[i]
            )
            whitespace = not clean[i]
            fragmented_start = (
                i + 1 < n
                and len(clean[i]) == 1
                and clean[i].isalpha()
                and not tokens[i + 1].startswith(("▁", "Ġ"))
                and any(w.pos_ == "VERB" for w in words)
            )

            extra = 0.0
            if determiner_led:
                if boundary:
                    extra += 0.22
                elif whitespace:
                    extra += 0.22
                elif fragmented_start:
                    extra += 0.30
                elif pos & {"PRON"}:
                    extra += 0.08
                elif pos & {"VERB", "AUX", "SCONJ", "CCONJ"}:
                    extra += 0.045
                elif pos & {"ADP", "ADV", "DET"}:
                    extra += 0.025

            if dialogue:
                extra += min(0.10, 0.0018 * i)
                if boundary or whitespace:
                    extra += 0.07
                elif pos & {"PRON", "CCONJ"}:
                    extra += 0.07

            if extra <= 0.0:
                continue

            # Strictly earlier destinations leave self-attention unchanged.
            weights = np.zeros(i, dtype=np.float64)
            if determiner_led:
                weights[1] = 4.0
                for j in range(2, min(i, 5)):
                    weights[j] = 1.0 / (j - 1)

            if dialogue:
                for j in range(1, i):
                    if tokens[j] in specials:
                        continue
                    if not clean[j]:
                        weights[j] += 2.5
                    elif any(c in ".!?" for c in clean[j]):
                        weights[j] += 2.0
                    elif any(c in "'‘’" for c in clean[j]):
                        weights[j] += 2.5
                    elif any(c in '"“”' for c in clean[j]):
                        weights[j] += 0.7

            total = weights.sum()
            if total > 0.0:
                transfer = min(extra, 0.55 * attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, :i] += transfer * weights / total

    return "bos_sink_with_prefix_boundary_exception", make_row_stochastic(attention)


def prog_L11H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild position-dependent dilution.
    Remaining attention is diffuse, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.975 / (1.0 + 0.0022 * (i - 1))
        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 8.0)
        recent /= recent.sum()
        residual = 0.75 / i + 0.25 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L11H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small causal background.
    Sink strength weakens mildly with context length and punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        is_punctuation = any(
            doc[k].pos_ == "PUNCT" for k in alignment[i]
        )

        # Short contexts retain about 96–97% on BOS; longer contexts
        # allow more competing attention without changing the main target.
        background_odds = 0.032 + 0.000025 * i * i
        if is_punctuation:
            background_odds *= 1.35
        sink_mass = 1.0 / (1.0 + background_odds)

        # The examples do not establish a specific secondary target:
        # use a mostly diffuse background with a weak recency preference.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.75 + 0.25 * np.exp(-distances / 6.0)
        background /= background.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_diffuse_background", attention


def prog_L11H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink, with a gated dialogue-repetition pathway.
    Repeated content can retrieve its earlier occurrence and following tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.tril(np.full((n, n), 0.0005, dtype=np.float64))
    if n:
        attention[:, 0] = 1.0

    # Leave the original behavior untouched outside quoted dialogue.
    if sentence.count('"') >= 2 or sentence.count("“") + sentence.count("”") >= 2:
        doc = spacy_parse(sentence)
        mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
        attention = make_row_stochastic(attention)

        for wi, word in enumerate(doc):
            if word.pos_ not in ("NOUN", "PROPN", "VERB"):
                continue
            current = [i for i in mapping[wi] if 0 < i < n]
            if not current:
                continue

            best_score, previous = 0.0, []
            threshold = 0.70 if word.pos_ == "VERB" else 0.84
            for wj in range(wi):
                if doc[wj].pos_ != word.pos_:
                    continue
                earlier = [j for j in mapping[wj] if 0 < j < current[0]]
                if not earlier or current[0] - earlier[-1] < 5:
                    continue
                score = embedding_similarity(
                    tokens, current[0], earlier[0], tokenizer
                )
                if score >= threshold and score > best_score:
                    best_score, previous = score, earlier

            if not previous:
                continue

            # Verbal repetition favors the continuation of the earlier phrase;
            # nominal repetition favors the earlier word's final subtoken.
            if word.pos_ == "VERB":
                targets = [
                    (previous[-1], 0.14),
                    (previous[-1] + 1, 0.60),
                    (previous[-1] + 2, 0.26),
                ]
                mass = 0.62 if best_score >= 0.90 else 0.82
            else:
                targets = [
                    (previous[-1], 0.72),
                    (previous[-1] + 1, 0.18),
                    (previous[-1] + 2, 0.10),
                ]
                mass = 0.15 if word.pos_ == "PROPN" else 0.19

            for i in current:
                valid = [(j, w) for j, w in targets if 0 < j < i]
                total = sum(w for _, w in valid)
                if total:
                    moved = min(mass, attention[i, 0])
                    attention[i, 0] -= moved
                    for j, weight in valid:
                        attention[i, j] += moved * weight / total

    return "bos_sink_with_dialogue_retrieval", make_row_stochastic(attention)


def prog_L11H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with clause-closing punctuation releasing sink mass to context.
    Short introductory punctuation retains the original behavior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_closure", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        early_bias = 0.09 * np.exp(-(i - 1) / 5.0)
        sink_mass = 0.70 + early_bias

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.055
            elif word.pos_ in ("ADJ", "NUM"):
                sink_mass += 0.045
            elif word.pos_ in ("PRON", "DET", "AUX"):
                sink_mass += 0.015
            elif word.pos_ == "VERB":
                sink_mass -= 0.055
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass -= 0.065
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.17

            if word.dep_ in ("ROOT", "ccomp", "advcl"):
                sink_mass -= 0.025

            if word.is_punct and word.is_sent_end:
                sink_mass -= 0.12

        # Word-internal pieces also strongly preserve the attention sink.
        if i > 1 and aligned and alignment[i - 1]:
            if aligned[0] == alignment[i - 1][0]:
                sink_mass += 0.035

        sink_mass = np.clip(sink_mass, 0.35, 0.90)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.30 / i + 0.70 * np.exp(-distances / 3.0)
        residual[-1] *= 1.15
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Only clause-closing punctuation changes: transfer BOS mass to
        # earlier context, preserving the diagonal and original residual.
        if word is not None and word.is_punct and i > 2:
            terminal = any(c in tokens[i] for c in ".!?")
            separator = any(c in tokens[i] for c in ",;:")
            clause_words = 0
            if terminal or separator:
                for previous in reversed(doc[:word.i]):
                    if previous.is_punct and any(
                        c in previous.text for c in ",;:.!?"
                    ):
                        break
                    if not previous.is_punct and not previous.is_space:
                        clause_words += 1

            if terminal or (separator and clause_words >= 4):
                target_sink = (
                    np.clip(0.22 * np.exp(-(i - 18) / 45.0), 0.10, 0.27)
                    if terminal else 0.28
                )
                released = max(0.0, attention[i, 0] - target_sink)
                context = np.ones(i - 1, dtype=np.float64)
                for j in range(1, i):
                    if alignment[j]:
                        previous = doc[alignment[j][-1]]
                        if previous.pos_ in ("VERB", "AUX", "CCONJ", "SCONJ"):
                            context[j - 1] *= 1.5
                        # Prefer completed words over their internal pieces.
                        if alignment[j + 1] and (
                            alignment[j][-1] == alignment[j + 1][0]
                        ):
                            context[j - 1] *= 0.5
                attention[i, 0] -= released
                attention[i, 1:i] += released * context / context.sum()

    return "bos_sink_with_clause_closure", make_row_stochastic(attention)


def prog_L11H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with boundary-triggered retrieval of clause anchors.
    Dialogue and pronominal narration selectively divert sink mass, not self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.97
        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = 0.03 * residual / residual.sum()

    # Keep ordinary single-clause narration on the original path.
    dialogue = any(c in sentence for c in ('"', '“', '”'))
    if not dialogue and "," not in sentence:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    words = [w for w in doc if not w.is_space and not w.is_punct]
    if not dialogue and not (words and words[0].pos_ == "PRON"):
        return "first_token_sink", attention

    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    clean = [t.lstrip("▁Ġ").strip() for t in tokens]
    quote_marks = ('"', '“', '”')
    terminal_marks = (".", "!", "?")
    quote_seen = False

    for i in range(1, n):
        text = clean[i]
        previous = clean[i - 1]
        ws = [doc[k] for k in aligned[i]]
        previous_ws = [doc[k] for k in aligned[i - 1]]
        amount = 0.0

        if not text and any(c in previous for c in terminal_marks):
            amount = 0.60
        elif any(c in text for c in terminal_marks):
            amount = 0.25 if dialogue else 0.32
        elif text == ",":
            amount = 0.26
        elif text in ("'", "’"):
            amount = 0.18 if dialogue else 0.40
        elif any(c in text for c in quote_marks):
            amount = 0.12
        elif dialogue and (
            (not previous and i > 2)
            or any(c in previous for c in terminal_marks)
        ) and any(w.pos_ in ("DET", "PRON", "PROPN") for w in ws):
            amount = 0.32
        elif dialogue and quote_seen and any(
            w.pos_ == "VERB" and any(c.dep_ == "ccomp" for c in w.children)
            for w in ws
        ):
            amount = 0.23
        elif dialogue and previous == "," and any(
            w.pos_ in ("CCONJ", "ADV") for w in ws
        ) and any(
            doc[k].pos_ in ("NOUN", "PROPN")
            for j in range(max(1, i - 3), i - 1)
            for k in aligned[j]
        ):
            amount = 0.27

        if amount > 0.0 and i > 1:
            anchors = np.zeros(i, dtype=np.float64)
            anchors[1] = 3.0
            for j in range(2, i):
                age = np.exp(-(i - j) / 24.0)
                js = [doc[k] for k in aligned[j]]
                if any(w.dep_ in ("nsubj", "nsubjpass") for w in js):
                    anchors[j] += 0.8 * age
                if any(
                    w.pos_ in ("VERB", "AUX")
                    and w.dep_ in ("ROOT", "ccomp", "conj")
                    for w in js
                ):
                    anchors[j] += 2.0 * age
                if any(c in clean[j] for c in quote_marks):
                    anchors[j] += 2.0 * age
                elif clean[j] == ",":
                    anchors[j] += 0.6 * age
                if text == "," or previous == ",":
                    if i - j <= 4 and any(
                        w.pos_ in ("NOUN", "PROPN") for w in js
                    ):
                        anchors[j] += 5.0 * age

            transfer = min(amount, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, :i] += transfer * anchors / anchors.sum()

        quote_seen = quote_seen or any(c in text for c in quote_marks)

    return "first_token_sink_with_clause_boundaries", attention


def prog_L11H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually decreasing dominance as context grows.
    Residual attention is diffuse, with a weak causal recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.994 / (1.0 + 0.0037 * (i - 1))

        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 6.0)
        recent /= recent.sum()
        residual = 0.7 / i + 0.3 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L11H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token,
    with a small diffuse causal remainder that grows with context length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.99 / (1.0 + 0.0012 * (i - 1))
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_sink_with_diffuse_leakage", attention


def prog_L11H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a very small diffuse causal tail in longer dialogue."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention_matrix = np.zeros((n, n), dtype=np.float64)
    if n:
        attention_matrix[:, 0] = 1.0

    # Keep short/plain sentences unchanged; cautiously model late-context leakage.
    if n >= 30 and any(mark in sentence for mark in ('"', '“', '”')):
        for i in range(16, n):
            leakage = min(0.004, 0.001 + 0.00005 * (i - 16))
            attention_matrix[i, 0] = 1.0 - leakage
            attention_matrix[i, 1:i + 1] = leakage / i

    return "bos_sink_with_dialogue_leakage", attention_matrix


def prog_L11H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant beginning-of-sequence sink that weakens with position,
    with residual attention to recent tokens and related earlier content."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_semantic_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ"}
    pos = [""] * n
    representatives = {}

    for i, indices in enumerate(alignment):
        if indices:
            si = indices[-1]
            pos[i] = doc[si].pos_
            if pos[i] in content_pos:
                representatives[si] = i

    content_indices = sorted(representatives.values())
    specials = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        previous = np.arange(1, i + 1)
        distance = i - previous

        # A broad residual rather than a strict previous-token head.
        residual = (
            0.65 * np.exp(-distance / 7.0)
            + 0.35 / np.sqrt(distance + 1.0)
        )
        residual[-1] *= 0.55

        sink = 0.95 / (1.0 + 0.026 * max(0, i - 4))
        sink = float(np.clip(sink, 0.28, 0.97))

        semantic = np.zeros(i, dtype=np.float64)
        best_affinity = 0.0
        if pos[i] in content_pos or pos[i] == "PRON":
            for j in content_indices:
                if j >= i:
                    break
                if tokens[j] in specials:
                    continue
                # Exclude pieces belonging to the same spaCy word.
                if set(alignment[i]).intersection(alignment[j]):
                    continue

                similarity = embedding_similarity(tokens, i, j, tokenizer)
                affinity = max(0.0, similarity - 0.28)
                affinity *= np.exp(-(i - j) / 100.0)
                if affinity > 0.0:
                    semantic[j - 1] = affinity ** 3
                    best_affinity = max(best_affinity, affinity)

        semantic_mass = semantic.sum()
        if semantic_mass > 0.0:
            strength = min(0.8, 2.0 * best_affinity)
            residual /= residual.sum()
            residual = (
                (1.0 - strength) * residual
                + strength * semantic / semantic_mass
            )
            sink *= 1.0 - 0.30 * strength

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_semantic_backoff", attention


def prog_L11H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a gradually weakening positional prior.
    Linguistic features mildly modulate sink strength; residual attention is diffuse and causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.60 + 0.32 * np.exp(-(i - 1) / 12.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("PRON", "AUX", "DET"):
                sink += 0.025
            elif word.pos_ in ("NOUN", "VERB", "ADJ"):
                sink -= 0.025
            if word.is_punct or word.is_space:
                sink += 0.025

            if i == 1:
                if word.pos_ == "PRON":
                    sink = 0.955
                elif word.pos_ == "DET":
                    sink = 0.865
                elif word.pos_ == "PROPN":
                    sink = 0.935

        sink = np.clip(sink, 0.50, 0.97)
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_position_decay", attention


def prog_L11H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse retrieval of repeated content in dialogue.
    Later mentions can retrieve earlier quoted actions, objects, and participants.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = 0.00015

    # Keep the original behavior unless there are multiple quoted turns.
    if sentence.count('"') >= 4:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        quoted = []
        inside = False
        for token in tokens:
            quoted.append(inside)
            if token.count('"') % 2:
                inside = not inside

        eligible = {"NOUN", "PROPN", "VERB", "ADP"}
        for i in range(1, n):
            if not alignment[i]:
                continue
            word = doc[alignment[i][0]]
            if word.pos_ not in eligible:
                continue

            best_j, best_similarity = None, 0.0
            for j in range(1, i - 5):
                if not alignment[j]:
                    continue
                previous = doc[alignment[j][0]]
                if previous.pos_ != word.pos_:
                    continue
                # Preposition retrieval is restricted to earlier dialogue.
                if word.pos_ == "ADP" and not (quoted[j] and not quoted[i]):
                    continue
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                threshold = 0.60 if word.pos_ == "VERB" else 0.85
                if similarity >= threshold and similarity > best_similarity:
                    best_j, best_similarity = j, similarity

            if best_j is None:
                continue

            source = doc[alignment[best_j][0]]
            weight = 0.04
            if quoted[best_j] and not quoted[i]:
                if word.pos_ == "VERB":
                    weight = 0.35
                elif word.pos_ == "ADP":
                    weight = 0.16
                elif word.pos_ == "NOUN":
                    weight = 1.05 if source.dep_ == "pobj" else 0.08

            attention[i, best_j] += weight

            # Recalled actions also weakly retrieve their following arguments.
            if word.pos_ == "VERB":
                for j in range(best_j + 1, min(best_j + 3, i)):
                    attention[i, j] += 0.35 * weight

    return "bos_sink_with_dialogue_retrieval", make_row_stochastic(attention)


def prog_L11H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Residual attention favors earlier syntactically compatible content tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    attention[0, 0] = 1.0

    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}
    predicate_pos = {"VERB", "AUX", "ADJ"}
    clause_deps = {"ROOT", "conj", "advcl", "ccomp", "parataxis"}

    for i in range(1, n):
        word = words[i]
        sink = 0.965 * np.exp(-0.014 * (i - 1))

        if word is not None:
            if word.pos_ in {"DET", "CCONJ"}:
                sink += 0.045
            elif word.pos_ == "AUX":
                sink += 0.055
            elif word.pos_ in {"NOUN", "PROPN"}:
                sink -= 0.035
            elif word.pos_ == "PRON":
                sink -= 0.015

            if word.dep_ in clause_deps and word.pos_ == "VERB":
                sink += 0.055
            if word.dep_ == "xcomp":
                sink -= 0.12
            if word.pos_ == "PUNCT":
                sink += 0.045

        if tokens[i].isspace() or tokens[i] == "▁":
            sink += 0.10

        sink = float(np.clip(sink, 0.22, 0.98))
        if i == 1:
            sink = 0.965

        indices = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - indices) / 22.0)
        residual[-1] *= 0.45

        if word is not None:
            for j in range(1, i + 1):
                earlier = words[j]
                if earlier is None:
                    continue
                if earlier.i == word.i:
                    residual[j - 1] *= 0.55
                    continue

                if earlier.pos_ in content_pos:
                    residual[j - 1] += 0.25
                if word.pos_ in content_pos and earlier.pos_ == word.pos_:
                    residual[j - 1] += 0.55
                if word.head.i == earlier.i:
                    residual[j - 1] += 0.65
                if (
                    word.pos_ in predicate_pos
                    and earlier.pos_ in predicate_pos
                    and i - j >= 3
                ):
                    residual[j - 1] += 0.65

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

    return "bos_sink_with_syntactic_residual", attention


def prog_L11H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a position-dependent escape to earlier,
    semantically similar content words."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ"}
    special_tokens = set(tokenizer.all_special_tokens)

    # Represent each model token by its most substantial overlapping word.
    words = []
    for indices in alignment:
        if indices:
            word = max(
                (doc[k] for k in indices),
                key=lambda w: (not w.is_punct, len(w.text)),
            )
            words.append(word)
        else:
            words.append(None)

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Early rows are nearly pure sink attention; later rows diversify.
        sink = 0.986 * np.exp(-0.010 * max(0, i - 12))
        sink = max(0.55, float(sink))
        word = words[i]
        if word is not None and word.is_punct:
            sink = min(0.992, sink + 0.06)

        background = np.exp(
            -0.035 * (i - np.arange(1, i + 1, dtype=np.float64))
        )
        background /= background.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

        if (
            word is None
            or word.pos_ not in content_pos
            or tokens[i] in special_tokens
        ):
            continue

        candidates = []
        for j in range(1, i):
            earlier = words[j]
            if (
                earlier is None
                or earlier.i == word.i
                or earlier.pos_ not in content_pos
                or tokens[j] in special_tokens
            ):
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            strength = np.clip((similarity - 0.55) / 0.45, 0.0, 1.0)
            if strength <= 0.0:
                continue
            if earlier.pos_ != word.pos_:
                strength *= 0.65
            candidates.append((j, float(strength)))

        if candidates:
            target, strength = max(candidates, key=lambda item: item[1])
            peak = 0.75 if word.pos_ == "PROPN" else 0.92
            if target <= 4 and word.pos_ != "PROPN":
                peak *= 0.55
            retrieval = peak * strength ** 2
            attention[i] *= 1.0 - retrieval
            attention[i, target] += retrieval

    return "bos_sink_with_lexical_retrieval", make_row_stochastic(attention)


def prog_L11H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing causal competition.
    Query POS and discourse punctuation modulate the strength of the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    quote_count = 0

    pos_competition = {
        "PRON": 0.90,
        "DET": 0.90,
        "ADP": 0.85,
        "AUX": 0.95,
        "CCONJ": 0.55,
        "SCONJ": 0.70,
        "NOUN": 1.05,
        "PROPN": 1.65,
        "VERB": 1.35,
        "ADJ": 2.00,
        "ADV": 1.35,
        "PART": 1.10,
        "PUNCT": 0.85,
        "SPACE": 0.95,
    }

    for i in range(1, n):
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
        if any(c in surface for c in ('"', "“", "”", "«", "»")):
            quote_count += 1

        overlapping = alignment[i]
        word = doc[overlapping[-1]] if overlapping else None
        competition = pos_competition.get(word.pos_, 1.0) if word is not None else 1.0

        if word is not None:
            if word.dep_ in ("cc", "mark"):
                competition *= 0.85
            elif word.dep_ in ("amod", "acomp"):
                competition *= 1.15

        # The earliest query has almost no alternative to the sink.
        if i == 1:
            competition = 1.0
            if word is not None and word.pos_ == "DET":
                competition = 1.75
            elif word is not None and word.pos_ == "PRON":
                competition = 0.80

        discourse_factor = 1.0 + 0.16 * min(quote_count, 4)
        competing_mass = (
            i * competition * discourse_factor * (1.0 + 0.006 * i)
        )
        sink_probability = 70.0 / (70.0 + competing_mass)

        # The examples constrain the sink much more than the residual edges;
        # use a diffuse, weakly recency-weighted causal residual.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_probability
        attention[i, 1:i + 1] = (1.0 - sink_probability) * residual

    return "bos_sink_with_linguistic_decay", attention


def prog_L11H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal background attention.
    Sink dominance gradually weakens as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_context_dilution", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Increasing competing attention mass captures the weaker sink
        # observed toward the ends of longer contexts.
        competing_mass = 0.004 + 0.0005 * i * np.exp(min(i / 32.0, 8.0))
        sink_mass = 1.0 / (1.0 + competing_mass)

        # The examples do not establish a reliable linguistic destination
        # for the small non-BOS residual; use a mild recency prior.
        distances = i - np.arange(1, i + 1)
        background = 0.7 + 0.3 * np.exp(-distances / 12.0)
        background /= background.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_context_dilution", attention


def prog_L11H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at discourse boundaries and weaker in dialogue.
    Residual attention is diffuse with a mild preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    in_quote = False
    boundary = True
    previous_word = -1

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        word_index = aligned[0] if aligned else -1
        continuation = word_index >= 0 and word_index == previous_word

        sink = 0.68 + 0.25 * np.exp(-(i - 1) / 5.0)
        if in_quote:
            sink -= 0.19

        if word is not None:
            if word.pos_ in ("PRON", "DET", "AUX", "PART"):
                sink -= 0.07
            if word.dep_ in ("dobj", "obj", "attr", "acomp", "xcomp"):
                sink -= 0.08
            if word.pos_ == "PROPN" or word.ent_type_:
                sink += 0.08
            if word.dep_ in ("ROOT", "conj") and word.pos_ == "VERB":
                sink += 0.06
            if continuation:
                sink += 0.04

        if boundary and text:
            sink = max(sink, 0.92 if i > 1 else 0.955)
            boundary = False

        if not text:
            sink = 0.95
        elif text in ("'", "’"):
            sink = max(sink, 0.92)
        elif text in (",", ";", ":"):
            sink += 0.08
        elif any(mark in text for mark in (".", "!", "?")):
            sink = max(sink, 0.88)
            boundary = True

        if any(mark in text for mark in ('"', "“", "”", "«", "»")):
            was_in_quote = in_quote
            in_quote = not in_quote
            if was_in_quote:
                sink = max(sink, 0.83)
                boundary = True

        sink = float(np.clip(sink, 0.30, 0.98))
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        if word_index >= 0:
            previous_word = word_index

    return "bos_sink_with_boundary_modulation", attention


def prog_L11H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and weak POS modulation.
    Residual attention is diffuse, with a mild preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.22 + 0.73 * np.exp(-i / 45.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.035
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.035
            elif word.pos_ == "PUNCT":
                sink_mass += 0.015

        if tokens[i].isspace() or tokens[i] == "▁":
            sink_mass += 0.04

        sink_mass = float(np.clip(sink_mass, 0.20, 0.98))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L11H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing competition from the prefix.
    Punctuation and whitespace retain especially strong attention to the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prefix_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        is_punctuation = bool(aligned) and all(
            doc[k].pos_ == "PUNCT" for k in aligned
        )
        is_whitespace = tokens[i].replace("▁", "").replace("Ġ", "").strip() == ""

        # A fixed sink competes with a growing number of ordinary keys.
        competition = 0.006 * i * np.exp(min(i / 65.0, 8.0))
        if is_punctuation:
            competition *= 0.30
        elif is_whitespace:
            competition *= 0.35

        sink_mass = 1.0 / (1.0 + competition)

        # No specific non-sink target is supported by the examples:
        # use a diffuse causal background with a mild recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.65 + 0.35 * np.exp(-(i - positions) / 12.0)
        background /= background.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_prefix_competition", attention


def prog_L11H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay.
    Residual attention favors recent tokens and syntactic attachment sites.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_attachment_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, aligned in enumerate(alignment):
        for sid in aligned:
            if 0 <= sid < len(doc):
                inverse[sid].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        aligned = alignment[i]
        word = None
        if aligned:
            candidates = [doc[sid] for sid in aligned if 0 <= sid < len(doc)]
            if candidates:
                word = max(candidates, key=lambda w: len(w.text))

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        punctuation = (
            bool(clean) and all(not c.isalnum() and not c.isspace() for c in clean)
        )
        apostrophe = bool(clean) and all(c in "'’`" for c in clean)
        whitespace = not clean or clean.isspace()
        continuation = (
            word is not None
            and inverse[word.i]
            and i > inverse[word.i][0]
            and not punctuation
        )

        sink = 0.965 * np.exp(-0.011 * (i - 1))
        if pos in ("NOUN", "PROPN"):
            sink += 0.045 if pos == "NOUN" else 0.13
        elif pos == "PRON":
            sink += 0.015
        elif pos == "VERB":
            sink -= 0.055
        elif pos == "AUX":
            sink -= 0.025
        elif pos == "ADJ":
            sink -= 0.085
        elif pos == "ADV":
            sink -= 0.13
        elif pos in ("CCONJ", "SCONJ"):
            sink -= 0.20
        elif pos == "ADP":
            sink -= 0.18
        elif pos == "DET":
            sink -= 0.045

        if word is not None and word.tag_ == "TO":
            sink += 0.12
        if continuation:
            sink += 0.14
        if punctuation:
            sink -= 0.24
        if apostrophe:
            sink = 0.95
        if whitespace:
            sink = max(sink, 0.86)
        if raw in special_tokens:
            sink = max(sink, 0.95)
        if i == 1:
            sink = 0.975
        sink = float(np.clip(sink, 0.15, 0.985))

        # Spread the residual causally, with a local-recency prior.
        distances = i - np.arange(1, i + 1)
        residual = 0.12 * np.exp(-distances / 5.0)
        residual[-1] += 0.07
        if i > 1:
            residual[-2] += 0.65

        if word is not None:
            head_candidates = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if head_candidates and word.head.i != word.i:
                target = head_candidates[-1]
                strength = 0.35
                if pos == "ADP":
                    strength = 1.8
                elif dep in ("cc", "mark"):
                    strength = 0.85
                elif pos == "PUNCT":
                    strength = 1.2
                residual[target - 1] += strength

        if punctuation and not apostrophe and i > 1:
            residual[-2] += 1.1

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

    return "bos_sink_with_attachment_residual", attention


def prog_L11H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weak position-dependent leakage to recent tokens.
    The examples support a positional sink rather than a syntactic relation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.92 + 0.05 * np.exp(-(i - 1) / 18.0)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.25 / i + 0.75 * (
            np.exp(-distances / 4.0)
            / np.exp(-distances / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L11H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker backward syntactic/recency channel.
    Coordination and clause continuation divert attention to earlier predicates."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_backlinks", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None

        # The initial context overwhelmingly selects the attention sink.
        early = np.exp(-(i - 1) / 4.0)
        sink = 0.79 + 0.18 * early
        weights = np.zeros(i + 1, dtype=np.float64)

        positions = np.arange(1, i + 1)
        weights[1:] = 0.15 * np.exp(-(i - positions) / 3.0)
        weights[i] += 0.08
        if i > 1:
            weights[i - 1] += 0.65

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("NOUN", "PROPN"):
                sink += 0.065
            elif pos in ("DET", "ADP", "ADJ", "NUM"):
                sink += 0.025
            elif pos in ("VERB", "AUX"):
                sink -= 0.10 * (1.0 - early)
            elif pos == "PRON":
                sink -= 0.12 * (1.0 - early)

            if dep in ("cc", "mark", "advcl", "ccomp", "xcomp"):
                sink -= 0.22 * (1.0 - early)
            if dep == "conj":
                sink -= 0.40 * (1.0 - early)

            # Earlier syntactic governors receive the residual attention.
            if word.head.i != word.i:
                targets = [j for j in inverse[word.head.i] if 0 < j < i]
                if targets:
                    strength = 3.5 if dep in ("conj", "cc") else 1.2
                    for j in targets:
                        weights[j] += strength / len(targets)

            # A coordinator points backward even when its governor is future.
            if dep == "cc" or pos == "CCONJ":
                for k in range(word.i - 1, -1, -1):
                    previous = doc[k]
                    if previous.pos_ in ("VERB", "ADJ", "NOUN"):
                        targets = [j for j in inverse[k] if 0 < j < i]
                        if targets:
                            for j in targets:
                                weights[j] += 3.0 / len(targets)
                            break

            # Word-internal pieces are usually sink-heavy rather than copying
            # their immediately preceding subword.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                sink += 0.065
                for j in earlier_pieces:
                    weights[j] *= 0.35

            if word.is_punct:
                sink -= 0.10 * (1.0 - early)

        sink = float(np.clip(sink, 0.12, 0.992))
        weights[0] = 0.0
        total = weights.sum()
        if total > 0:
            attention[i, :i + 1] = weights * ((1.0 - sink) / total)
            attention[i, 0] = sink
        else:
            attention[i, 0] = 1.0

    return "bos_sink_with_clause_backlinks", attention


def prog_L11H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and clause-sensitive leakage.
    Residual attention favors recent context and available syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    boundaries = 0
    seen_boundaries = set()

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        # Most tokens retain a strong sink even in relatively long contexts.
        sink = 0.975 - 0.14 * (1.0 - np.exp(-(i - 1) / 32.0))
        sink -= min(0.18, 0.035 * boundaries)

        if word is not None:
            if word.pos_ == "VERB":
                sink -= 0.07
            elif word.pos_ in ("AUX", "PRON", "CCONJ", "SCONJ"):
                sink -= 0.035

            if word.is_punct and word.text in (".", "!", "?", ";", ":"):
                sink -= 0.12

        sink = float(np.clip(sink, 0.52, 0.985))

        # Allocate only the small non-sink component to linguistic context.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 7.0)
        residual[-1] *= 0.45

        if word is not None and word.head.i != word.i:
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 0.6

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Count each punctuation boundary once, even if split into subwords.
        for si in aligned:
            w = doc[si]
            if w.is_punct and w.text in (",", ";", ":", ".", "!", "?"):
                if si not in seen_boundaries:
                    boundaries += 1
                    seen_boundaries.add(si)

    return "bos_sink_with_context_leakage", attention


def prog_L11H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant first-token attention sink, weakening with position.
    Residual attention favors recent content tokens and syntactic context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}
    nominal_pos = {"NOUN", "PROPN"}
    attention[0, 0] = 1.0

    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 9.0)

        for j in range(1, i + 1):
            indices = alignment[j]
            if any(doc[k].pos_ in content_pos for k in indices):
                residual[j - 1] *= 1.7
            if any(doc[k].pos_ in nominal_pos for k in indices):
                residual[j - 1] *= 1.4
            if indices and all(doc[k].is_punct for k in indices):
                residual[j - 1] *= 0.4

        # Heads and earlier conjuncts provide a small linguistic correction.
        for si in alignment[i]:
            word = doc[si]
            head_positions = [j for j in inverse[word.head.i] if 0 < j < i]
            if head_positions:
                residual[head_positions[-1] - 1] += 1.5
            if word.dep_ == "conj" and head_positions:
                residual[head_positions[-1] - 1] += 3.0

        sink_mass = 0.985 * np.exp(-0.006 * max(0, i - 5))
        sink_mass = float(np.clip(sink_mass, 0.45, 0.985))
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_content_residual", attention


def prog_L11H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with entity retrieval; copular predicates and their modifiers
    additionally retrieve the nominal subject's final subtoken.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_copular_subject_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        if tokens[i] in special_tokens:
            attention[i, 0] = 1.0
            continue

        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        residual = np.zeros(i + 1, dtype=np.float64)

        # A small causal background remains even when no entity is retrieved.
        positions = np.arange(1, i + 1)
        residual[1:] = 0.12 * np.exp(-(i - positions) / 4.0)
        sink = 0.90 - 0.025 * np.log1p(i)
        target = None
        strength = 0.0

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN", "NUM"):
                sink += 0.035
            elif pos == "VERB":
                sink -= 0.16
            elif pos == "AUX":
                sink -= 0.08
            elif pos == "ADV":
                sink -= 0.08
            elif pos == "PUNCT":
                sink -= 0.07

            # Predicates can retrieve a previously introduced subject.
            if pos in ("VERB", "AUX", "ADJ"):
                subjects = [
                    child for child in word.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                    and any(0 < j < i for j in inverse[child.i])
                ]
                if not subjects and pos == "ADJ":
                    subjects = [
                        child for child in word.head.children
                        if child.dep_ in ("nsubj", "nsubjpass")
                        and any(0 < j < i for j in inverse[child.i])
                    ]
                if subjects:
                    target = subjects[-1]
                    strength = 1.2
                    if pos == "ADJ" and word.dep_ != "amod":
                        sink = 0.47
                        strength = 2.0

            # Object pronouns particularly favor an earlier nominal referent.
            if pos == "PRON":
                best_score = -np.inf
                number = word.morph.get("Number")
                for candidate in doc[:word.i]:
                    if candidate.pos_ not in ("NOUN", "PROPN"):
                        continue
                    earlier = [j for j in inverse[candidate.i] if 0 < j < i]
                    if not earlier:
                        continue
                    score = -0.035 * (word.i - candidate.i)
                    candidate_number = candidate.morph.get("Number")
                    if number and candidate_number:
                        score += 0.5 if number == candidate_number else -1.5
                    if candidate.dep_ in ("dobj", "obj", "pobj", "attr"):
                        score += 0.25
                    if score > best_score:
                        best_score = score
                        target = candidate

                if target is not None:
                    is_object = word.dep_ in ("dobj", "obj", "pobj", "iobj")
                    sink = 0.36 if is_object else 0.66
                    strength = 2.5 if is_object else 1.2

        # Early tokens typically have exceptionally strong sink attention.
        if i <= 3:
            sink = max(sink, 0.94)

        if target is not None:
            destinations = [j for j in inverse[target.i] if 0 < j <= i]
            if destinations:
                residual[destinations] += strength / len(destinations)

        sink = float(np.clip(sink, 0.25, 0.98))
        total = residual.sum()
        if total > 0:
            attention[i, :i + 1] = residual * ((1.0 - sink) / total)
            attention[i, 0] = sink
        else:
            attention[i, 0] = 1.0

        # Narrow exception: nominal-subject copular adjective constructions.
        # Transfer only BOS/subject mass; preserve self-attention and background.
        if word is not None and (
            word.pos_ in ("AUX", "ADJ", "ADV")
            or (
                word.pos_ in ("PRON", "DET")
                and word.dep_ in ("advmod", "predet")
            )
        ):
            anchor = word
            for _ in range(3):
                if (
                    anchor.dep_ in ("advmod", "acomp", "attr", "oprd", "cop", "predet")
                    and anchor.head.i != anchor.i
                ):
                    anchor = anchor.head
                else:
                    break

            is_copular = (
                anchor.pos_ == "AUX"
                and any(
                    c.pos_ == "ADJ" and c.dep_ in ("acomp", "attr", "oprd")
                    for c in anchor.children
                )
            ) or (
                anchor.pos_ == "ADJ"
                and any(c.dep_ == "cop" for c in anchor.children)
            )

            if is_copular:
                subjects = [
                    c for c in anchor.children
                    if c.dep_ in ("nsubj", "nsubjpass")
                    and c.pos_ in ("NOUN", "PROPN")
                    and any(0 < j < i for j in inverse[c.i])
                ]
                if subjects:
                    destinations = [
                        j for j in inverse[subjects[-1].i] if 0 < j < i
                    ]
                    destination = max(destinations)
                    desired_sink = (
                        0.30 if word.pos_ == "AUX"
                        else 0.40 if word.pos_ == "ADJ"
                        else 0.38
                    )
                    transfer = max(0.0, attention[i, 0] - desired_sink)
                    attention[i, 0] -= transfer
                    attention[i, destination] += transfer

                    # Retrieved multi-piece subjects favor their final piece.
                    for j in destinations:
                        if j != destination:
                            attention[i, destination] += attention[i, j]
                            attention[i, j] = 0.0

    return "bos_sink_with_copular_subject_retrieval", make_row_stochastic(attention)


def prog_L11H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and on salient nominal tokens.
    Remaining attention is weakly recency-biased over the causal prefix.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_salience", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_adjustment = {
        "NOUN": 0.09,
        "PROPN": 0.12,
        "ADJ": 0.07,
        "NUM": 0.04,
        "DET": 0.01,
        "PRON": -0.04,
        "VERB": -0.025,
        "ADV": -0.04,
        "AUX": -0.11,
        "CCONJ": -0.12,
        "SCONJ": -0.07,
        "ADP": -0.04,
        "PUNCT": -0.08,
        "SPACE": -0.10,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.76 + 0.13 * np.exp(-(i - 1) / 10.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            sink_mass += pos_adjustment.get(word.pos_, 0.0)
            if word.ent_type_:
                sink_mass += 0.025
            if word.dep_ in ("nsubj", "nsubjpass", "amod"):
                sink_mass += 0.025
            if word.is_punct and word.text in (".", "!", "?"):
                sink_mass -= 0.12

        if i == 1:
            sink_mass = max(sink_mass, 0.91)

        sink_mass = float(np.clip(sink_mass, 0.48, 0.98))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_lexical_salience", attention


def prog_L11H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with coordination anchors that persist across nearby list material.
    Subword continuations do not independently trigger coordination anchoring.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_coordination", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_tokens[wi].append(ti)

    attention[0, 0] = 1.0
    nominal = ("NOUN", "PROPN")

    # Only adjective pairs and extended nominal lists need extra persistence.
    coordination_groups = []
    for root in doc:
        if root.dep_ == "conj" or root.pos_ not in nominal + ("ADJ",):
            continue
        members = [root]
        for child in root.subtree:
            if child.dep_ != "conj" or child.pos_ != root.pos_:
                continue
            ancestor = child
            while ancestor.dep_ == "conj" and ancestor.head.i != ancestor.i:
                ancestor = ancestor.head
            if ancestor.i == root.i:
                members.append(child)
        members.sort(key=lambda w: w.i)
        minimum = 2 if root.pos_ == "ADJ" else 3
        if len(members) >= minimum:
            coordination_groups.append((root, members))

    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        # Position is the main predictor; syntax only perturbs the sink.
        sink = 0.955 - 0.0055 * (i - 1)
        if word is not None:
            if word.pos_ == "CCONJ":
                sink -= 0.13
            elif word.pos_ == "PUNCT":
                sink -= 0.055
            elif word.pos_ in ("VERB", "ADV"):
                sink -= 0.025
        sink = float(np.clip(sink, 0.46, 0.975))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual[-1] *= 0.65

        # A weak causal dependency preference within the non-sink mass.
        if word is not None:
            head_positions = [
                j for j in word_tokens[word.head.i] if 0 < j < i
            ]
            if head_positions:
                residual[head_positions[-1] - 1] += 0.55

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Lists can redirect substantial mass to their first nominal member.
        anchor = None
        if word is not None:
            candidate = word
            if word.dep_ in ("cc", "punct"):
                candidate = word.head

            if candidate.pos_ in nominal:
                has_coordination = candidate.dep_ == "conj" or any(
                    child.dep_ == "conj" and child.pos_ in nominal
                    for child in candidate.children
                )
                if has_coordination:
                    while (
                        candidate.dep_ == "conj"
                        and candidate.head.pos_ in nominal
                        and candidate.head.i != candidate.i
                    ):
                        candidate = candidate.head
                    preceding = [
                        j for j in word_tokens[candidate.i] if 0 < j < i
                    ]
                    if preceding:
                        anchor = preceding[-1]

        if anchor is not None:
            strength = 0.45
            if word.pos_ == "PUNCT":
                strength = 0.65
            elif word.pos_ == "CCONJ":
                strength = 0.42
            attention[i] *= 1.0 - strength
            attention[i, anchor] += strength

            # Undo only the added anchor mass for within-word triggers.
            # Leave the original diagonal and residual weights untouched.
            if (
                word_tokens[word.i]
                and (
                    i > word_tokens[word.i][0]
                    or word.i == candidate.i
                )
            ):
                attention[i, anchor] -= strength
                attention[i, 0] += strength

        # Transfer only BOS mass: all existing residual/self weights survive.
        if word is not None:
            for root, members in coordination_groups:
                last = members[-1].i
                if not (root.i < word.i <= last + 6):
                    continue
                if any(
                    w.pos_ == "PUNCT"
                    and any(c in w.text for c in ".!?;")
                    for w in doc[root.i:word.i]
                ):
                    continue

                completed = [
                    w for w in members
                    if word_tokens[w.i]
                    and 0 < word_tokens[w.i][-1] < i
                ]
                if not completed:
                    continue

                if root.pos_ == "ADJ":
                    if word.pos_ == "CCONJ":
                        fraction = 0.52
                    elif word.i <= last:
                        fraction = 0.18
                    elif word.pos_ == "PUNCT":
                        fraction = 0.28
                    else:
                        fraction = 0.67 * np.exp(
                            -max(0, word.i - last - 2) / 5.0
                        )
                else:
                    # Nominal persistence requires two completed list members.
                    # Existing explicit anchors are already strong enough.
                    if len(completed) < 2 or anchor is not None:
                        continue
                    fraction = 0.88 * np.exp(
                        -max(0, word.i - last) / 4.0
                    )

                targets = [
                    (word_tokens[w.i][-1], 1.0 / (k + 1))
                    for k, w in enumerate(completed)
                ]

                # A following clause can recover the coordinated predicate's
                # auxiliary and modifiers, rather than only its adjectives.
                if (
                    root.pos_ == "ADJ"
                    and word.i > last
                    and word.pos_ in ("PRON", "VERB", "AUX", "PART")
                ):
                    context = [
                        w for w in root.children
                        if w.pos_ == "AUX" or w.dep_ == "advmod"
                    ]
                    for w in context:
                        preceding = [
                            j for j in word_tokens[w.i] if 0 < j < i
                        ]
                        if preceding:
                            targets.append((preceding[-1], 1.5))

                total = sum(weight for _, weight in targets)
                transfer = attention[i, 0] * fraction
                attention[i, 0] -= transfer
                for j, weight in targets:
                    attention[i, j] += transfer * weight / total
                break

    return "bos_sink_with_coordination", make_row_stochastic(attention)


def prog_L11H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A BOS sink with a local nominal-boundary exception.
    Completed arguments attract residual attention from nearby boundary/function tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "NOUN": 0.935,
        "PROPN": 0.945,
        "ADJ": 0.935,
        "DET": 0.905,
        "ADP": 0.875,
        "VERB": 0.875,
        "ADV": 0.865,
        "PRON": 0.855,
        "NUM": 0.900,
        "AUX": 0.805,
        "PART": 0.845,
        "CCONJ": 0.785,
        "SCONJ": 0.790,
        "INTJ": 0.875,
        "PUNCT": 0.700,
        "SPACE": 0.810,
    }

    # Index completed nominal arguments by their final model subtoken.
    word_ends = {}
    for ti, word_ids in enumerate(alignment):
        for k in word_ids:
            word_ends[k] = ti
    anchors = {
        end: doc[k]
        for k, end in word_ends.items()
        if end > 0
        and doc[k].pos_ in ("NOUN", "PROPN")
        and doc[k].dep_ in (
            "nsubj", "nsubjpass", "dobj", "obj", "iobj", "pobj", "conj"
        )
    }

    for i in range(1, n):
        sink = 0.875
        if alignment[i]:
            # Average features when a model token overlaps multiple words.
            values = [
                sink_by_pos.get(doc[k].pos_, 0.875)
                for k in alignment[i]
            ]
            sink = float(np.mean(values))
        elif tokens[i] in tokenizer.all_special_tokens:
            sink = 0.94
        elif tokens[i].isspace():
            sink = 0.81

        # The first lexical position consistently has a strong sink preference.
        if i == 1:
            sink = 0.94

        # Keep the sink independent of sequence length; distribute only its
        # small remainder over non-sink positions.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only redirect BOS mass: preserve self-attention and the original
        # residual distribution at every other position.
        if alignment[i]:
            query = doc[alignment[i][0]]
            if query.pos_ in (
                "PUNCT", "CCONJ", "SCONJ", "ADP", "PRON", "AUX", "VERB"
            ):
                for j in range(i - 1, max(0, i - 6), -1):
                    if j not in anchors:
                        continue
                    anchor = anchors[j]
                    if anchor.i >= query.i:
                        continue

                    intervening = doc[anchor.i + 1:query.i]
                    if any(
                        w.pos_ in ("NOUN", "PROPN")
                        or w.is_sent_end
                        for w in intervening
                    ):
                        break

                    subject = anchor.dep_ in ("nsubj", "nsubjpass")
                    if subject and query.pos_ not in ("VERB", "AUX"):
                        break

                    strength = 0.10 if subject else 0.18
                    if not subject and query.pos_ == "PUNCT":
                        strength = 0.25
                    if anchor.dep_ == "pobj" and query.pos_ in (
                        "PRON", "AUX", "PUNCT"
                    ):
                        strength = 0.32

                    transfer = min(
                        attention[i, 0],
                        strength * np.exp(-(i - j - 1) / 3.0),
                    )
                    attention[i, 0] -= transfer
                    attention[i, j] += transfer
                    break

    return "bos_sink_with_nominal_boundaries", attention


def prog_L11H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local-attention exception in late dialogue and
    subordinate clauses containing an open clausal complement.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Identify only the subordinate-complement construction, not all clauses.
    complement_scope = {}
    for root in doc:
        if root.dep_ == "advcl" and any(c.dep_ == "xcomp" for c in root.children):
            for member in root.subtree:
                complement_scope[member.i] = root.i

    quote_count = 0

    for i in range(1, n):
        # Sink strength declines gently rather than diluting with context size.
        sink = 0.76 - 0.09 * (1.0 - np.exp(-i / 24.0))
        aligned = [doc[k] for k in alignment[i] if k < len(doc)]

        if aligned:
            word = max(aligned, key=lambda w: len(w.text))
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink += 0.085
            elif pos == "ADJ":
                sink += 0.105
            elif pos == "ADV":
                sink += 0.025
            elif pos in ("VERB", "AUX"):
                sink += 0.015
            elif pos in ("PRON", "DET", "ADP", "NUM"):
                sink -= 0.015
            elif pos in ("CCONJ", "SCONJ", "PART"):
                sink -= 0.075
            elif pos == "PUNCT":
                sink -= 0.065

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink += 0.025
        elif tokens[i].isspace():
            sink -= 0.025

        if i == 1:
            sink = 0.85

        sink = float(np.clip(sink, 0.55, 0.92))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        quote_count += sum(tokens[i].count(q) for q in ('"', '“', '”'))
        in_complement_scope = aligned and word.i in complement_scope

        # Preserve the default row unless a targeted local regime is present.
        if in_complement_scope or (i >= 26 and quote_count >= 2):
            if in_complement_scope:
                transfer = 0.28 if word.pos_ in ("VERB", "AUX") else 0.18
                root_index = complement_scope[word.i]
                root_tokens = [
                    j for j in range(1, i + 1)
                    if root_index in alignment[j]
                ]
                target = root_tokens[-1] if root_tokens else i
                local_fraction = 0.70
            else:
                transfer = 0.18 + 0.04 * (1.0 - np.exp(-(i - 26) / 20.0))
                target = i - 1
                local_fraction = 0.85

            transfer = min(transfer, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, i] += local_fraction * transfer
            attention[i, target] += (1.0 - local_fraction) * transfer

    return "bos_sink_with_local_exception", attention


def prog_L11H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with a strong initial-position bias.
    Linguistic and subword features modulate sink strength; residual attention is diffuse-causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Early queries consistently devote almost all their mass to BOS.
        sink = 0.73 + 0.23 * np.exp(-(i - 1) / 3.5)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos == "PROPN":
                sink += 0.10
            elif pos == "NOUN":
                sink += 0.06
            elif pos == "ADJ":
                sink += 0.035
            elif pos == "VERB":
                sink -= 0.075
            elif pos == "PUNCT":
                sink -= 0.12

            if word.ent_type_:
                sink += 0.025

            # Subword fragments often retain especially strong sink attention.
            if i > 1 and pos != "PUNCT":
                if any(k in alignment[i - 1] for k in aligned):
                    sink += 0.065

        piece = tokens[i]
        if piece.isspace() or not piece.strip("▁Ġ"):
            sink += 0.06
        if piece.strip("▁Ġ ") in ("'", "’"):
            sink += 0.17

        sink = float(np.clip(sink, 0.45, 0.975))
        if i == 1:
            sink = 0.96

        # The supplied edges constrain BOS much more than other destinations.
        # Use a conservative mixture of diffuse and mildly local residual mass.
        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 8.0)
        local /= local.sum()
        residual = 0.65 / i + 0.35 * local

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_lexical_modulation", make_row_stochastic(attention)


def prog_L11H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened at sentence/clause starts and punctuation.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boost", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        word = max(
            words,
            key=lambda w: sum(c.isalnum() for c in w.text),
            default=None,
        )

        # A dominant position-zero sink, not a retrieval or copying head.
        sink = 0.64 + 0.17 * np.exp(-(i - 1) / 3.0)

        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink += 0.045
            elif word.pos_ == "PROPN":
                sink += 0.075
            elif word.pos_ in ("ADP", "PART"):
                sink -= 0.035

            if word.dep_ in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                sink += 0.10
            elif word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink -= 0.045

            if word.is_sent_start:
                sink += 0.17
            elif word.i > 0:
                previous = doc[word.i - 1]
                if previous.is_punct and previous.text in (",", ";", ":"):
                    sink += 0.10

            # Determiners and modifiers introducing a new subject inherit
            # some of the clause-onset enhancement.
            if (
                word.dep_ in ("det", "poss", "amod")
                and word.head.dep_ in ("nsubj", "nsubjpass")
            ):
                sink += 0.06

        if not text:
            sink = max(sink, 0.94)
        elif text in ("'", "’", "‘"):
            sink = max(sink, 0.94)
        elif all(c in "\"“”«»" for c in text):
            sink = max(sink, 0.82)
        elif all(c in ".!?" for c in text):
            sink = max(sink, 0.80)
        elif text in (",", ";", ":"):
            sink += 0.055

        if i == 1:
            sink = 0.89

        sink = float(np.clip(sink, 0.48, 0.98))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.35 + np.exp(-distances / 5.0)
        residual[-1] += 0.25
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_boundary_boost", attention


def prog_L11H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with a small, diffuse causal recency background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_background", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.7 / i + 0.3 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )
        attention[i, 0] = 0.93
        attention[i, 1:i + 1] = 0.07 * background

    return "bos_sink_with_diffuse_background", attention


def prog_L12H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with linguistic gating.
    In extended quoted dialogue, shift sink and diffuse mass toward self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_self_attention", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Restrict the new behavior to extended contexts containing quoted speech.
    quoted_dialogue = n >= 24 and sum(c in '"“”' for c in sentence) >= 2
    seen_quote = False

    for i in range(1, n):
        # Position zero dominates; its share gradually falls in longer contexts.
        sink_mass = 0.84 - 0.0035 * np.clip(i - 8, 0, 100)

        if alignment[i]:
            word = doc[alignment[i][0]]
            pos = word.pos_

            if pos in ("ADJ", "NOUN", "PROPN"):
                sink_mass += 0.045
            elif pos in ("DET", "AUX", "ADV"):
                sink_mass += 0.015
            elif pos == "PRON":
                sink_mass -= 0.065
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass -= 0.055
            elif pos == "PUNCT":
                sink_mass -= 0.13

            if word.dep_ in ("amod", "poss"):
                sink_mass += 0.015

        sink_mass = float(np.clip(sink_mass, 0.40, 0.94))
        attention[i, 0] = sink_mass

        # The examples constrain the sink much more than the remaining edges.
        # Use a diffuse causal background with a modest recency preference.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.35 / i + 0.65 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

        if quoted_dialogue:
            seen_quote = seen_quote or any(c in tokens[i] for c in '"“”')
            if seen_quote:
                # Dialogue weakens the sink and concentrates the residual on self.
                transfer = float(0.16 + 0.003 * np.clip(i - 8, 0, 46))
                transfer = min(transfer, attention[i, 0])
                reclaimed = 0.5 * attention[i, 1:i].sum()
                attention[i, 0] -= transfer
                attention[i, 1:i] *= 0.5
                attention[i, i] += transfer + reclaimed

    return "bos_sink_with_dialogue_self_attention", make_row_stochastic(attention)


def prog_L12H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong initial-position bias.
    Residual attention favors recent tokens and nearby syntactic context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_context", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_ids in enumerate(aligned):
        for word_id in word_ids:
            inverse[word_id].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word_ids = aligned[i]
        word = doc[word_ids[-1]] if word_ids else None

        # Early queries strongly prefer the sink; later queries retain a
        # substantial sink mass rather than becoming uniformly distributed.
        sink = 0.51 + 0.37 * np.exp(-(i - 1) / 5.0)

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN", "ADJ"):
                sink += 0.055
            elif pos in ("VERB", "AUX"):
                sink += 0.025
            elif pos == "PRON":
                sink -= 0.075
            elif pos in ("ADP", "SCONJ", "CCONJ", "PART"):
                sink -= 0.065
            elif pos == "PUNCT":
                sink -= 0.16

            if word.dep_ in ("ROOT", "amod", "advmod"):
                sink += 0.025

            # Interior pieces of a word also frequently select the sink.
            if i > 1 and any(k in aligned[i - 1] for k in word_ids):
                sink += 0.025

        if i == 1:
            sink = 0.92
            if word is not None and word.pos_ == "PRON":
                sink += 0.025

        sink = float(np.clip(sink, 0.25, 0.96))

        positions = np.arange(1, i + 1)
        distance = i - positions
        local = np.exp(-distance / 3.0)
        local[-1] *= 0.50

        if i > 1:
            local[-2] += 0.65

        if word is not None:
            # Only already-visible syntactic links can receive attention.
            for j in inverse[word.head.i]:
                if 0 < j <= i and word.head.i != word.i:
                    local[j - 1] += 0.45 * np.exp(-(i - j) / 12.0)

            if word.is_punct and i > 1:
                local[-2] += 1.2

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_local_context", attention


def prog_L12H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with length-dependent dilution and weaker local attention.
    Lexical category and punctuation modulate the sink's strength.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    representatives = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        representatives.append(candidates[0] if candidates else None)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        piece = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        sink_log_weight = 2.75

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_log_weight += 0.38
            elif word.pos_ == "ADJ":
                sink_log_weight += 0.12
            elif word.pos_ in ("VERB", "AUX", "PRON"):
                sink_log_weight -= 0.24

            if word.ent_type_:
                sink_log_weight += 0.12

            if word.is_punct:
                sink_log_weight += 0.30

        if not piece:
            sink_log_weight += 0.75
        elif piece in ("'", "’"):
            sink_log_weight += 1.65

        if tokens[i] in special_tokens:
            sink_log_weight += 0.50

        attention[i, 0] = np.exp(sink_log_weight)

        for j in range(1, i + 1):
            distance = i - j
            weight = 0.50 + 0.70 * np.exp(-distance / 3.0)

            previous_word = representatives[j]
            if previous_word is not None and previous_word.is_punct:
                weight *= 0.75

            # Weak residual preference for a previously available syntactic head.
            if word is not None and previous_word is not None:
                if word.head.i != word.i and previous_word.i == word.head.i:
                    head_pieces = sum(
                        1
                        for k in range(1, i + 1)
                        if representatives[k] is not None
                        and representatives[k].i == word.head.i
                    )
                    weight += 1.8 / max(head_pieces, 1)

            attention[i, j] = weight

        # With only one preceding token, the observed sink is particularly strong.
        if i == 1:
            attention[i, 0] = 0.95
            attention[i, 1] = 0.05

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L12H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak recency channel.
    Punctuation shifts attention toward the preceding lexical token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    pos = []
    punctuation = []
    terminal = []
    whitespace = []

    for i, token in enumerate(tokens):
        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = [doc[k] for k in alignment[i]]
        lexical = [word for word in aligned if not word.is_space and not word.is_punct]
        representative = lexical[-1] if lexical else (aligned[-1] if aligned else None)

        pos.append(representative.pos_ if representative is not None else "")
        is_punct = (
            token not in special_tokens
            and bool(clean)
            and all(not char.isalnum() for char in clean)
        )
        punctuation.append(is_punct)
        terminal.append(is_punct and any(char in ".!?" for char in clean))
        whitespace.append(token not in special_tokens and not clean)

    attention[0, 0] = 1.0
    for i in range(1, n):
        progress = 1.0 - np.exp(-(i - 1) / 24.0)
        sink = 0.94 - 0.20 * progress

        if pos[i] in ("NOUN", "PROPN", "ADJ", "NUM"):
            sink += 0.035
        elif pos[i] in ("VERB", "AUX", "PRON"):
            sink -= 0.085 * progress
        elif pos[i] in ("ADP", "DET", "CCONJ", "SCONJ", "PART"):
            sink -= 0.065 * progress

        if punctuation[i]:
            sink = (0.40 if terminal[i] else 0.84) - 0.30 * progress
        elif whitespace[i]:
            sink = 0.83 - 0.18 * progress
        elif tokens[i] in special_tokens:
            sink = 0.75

        sink = float(np.clip(sink, 0.12, 0.98))
        indices = np.arange(1, i + 1)
        weights = np.exp(-(i - indices) / 3.5)

        for k, j in enumerate(indices):
            if pos[j] in ("NOUN", "PROPN", "ADJ", "VERB"):
                weights[k] *= 1.35
            if punctuation[j] or whitespace[j]:
                weights[k] *= 0.35

        weights[-1] *= 0.55
        if punctuation[i] and i > 1:
            previous = i - 1
            while previous > 1 and (punctuation[previous] or whitespace[previous]):
                previous -= 1
            weights[previous - 1] += 4.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_punctuation_recency", attention


def prog_L12H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker sentence/quotation-start anchors.
    Lexical boundaries and punctuation modulate the sink's strength.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_segment_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            inverse[si].append(ti)

    special = set(tokenizer.all_special_tokens)
    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
    attention[0, 0] = 1.0

    segment_start = 1
    quote_start = None
    inside_quote = False

    for i in range(1, n):
        text = clean[i]
        indices = aligned[i]
        word = doc[indices[0]] if indices else None
        whitespace = not text and tokens[i] not in special
        apostrophe = text in ("'", "’")
        opening_quote = False

        if whitespace:
            segment_start = i
        elif word is not None and word.is_sent_start:
            if i == 1 or segment_start < i - 2:
                segment_start = i

        if '"' in text or "“" in text or "”" in text:
            opening_quote = (
                "“" in text
                or ('"' in text and not inside_quote
                    and not any(c in text for c in ".!?"))
            )
            if opening_quote:
                quote_start = i
                inside_quote = True
            else:
                inside_quote = False

        # Reserve explicit probability for the ubiquitous attention sink.
        sink = (
            0.46
            + 0.18 * np.exp(-i / 8.0)
            - 0.16 * (1.0 - np.exp(-i / 40.0))
        )
        if word is not None:
            if word.pos_ in ("DET", "PRON"):
                sink += 0.065
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ"):
                sink += 0.025
            if word.pos_ == "PUNCT" and not apostrophe:
                sink -= 0.065

        continuation = (
            i > 1
            and not tokens[i].startswith(("▁", "Ġ"))
            and text
            and not all(c in ".,!?;:\"'’“”()[]{}-" for c in text)
            and bool(set(indices).intersection(aligned[i - 1]))
        )
        if continuation:
            sink += 0.10
        if apostrophe:
            sink += 0.25
        if whitespace:
            sink += 0.25
        if opening_quote:
            sink -= 0.07
        if i == 1:
            sink = 0.90

        sink = float(np.clip(sink, 0.18, 0.94))

        positions = np.arange(1, i + 1)
        residual = 0.025 + 0.10 * np.exp(-(i - positions) / 5.0)

        # Residual attention favors stable contextual entry points.
        residual[0] += 0.22 * np.exp(-(i - 1) / 55.0)
        if 1 <= segment_start <= i:
            residual[segment_start - 1] += 0.48
        if inside_quote and quote_start is not None and quote_start <= i:
            residual[quote_start - 1] += 0.70

        if word is not None:
            head_indices = inverse[word.head.i]
            preceding_heads = [j for j in head_indices if 0 < j <= i]
            if preceding_heads:
                residual[preceding_heads[0] - 1] += 0.12
            if word.dep_ in ("aux", "auxpass", "cop", "advmod"):
                if 1 <= segment_start < i:
                    residual[segment_start - 1] += 0.12

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_segment_anchors", make_row_stochastic(attention)


def prog_L12H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing positional leakage.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_positional_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 1.0 / (1.0 + 0.0015 * i ** 1.35)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_leakage", attention


def prog_L12H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild positional and linguistic modulation.
    Residual attention is diffuse and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The only consistently identifiable destination is the first token.
        sink_mass = 0.90 - 0.0025 * min(i - 1, 70)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "DET"):
                sink_mass += 0.025
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.075

            if word.dep_ in ("amod", "compound", "poss"):
                sink_mass += 0.015

        if tokens[i].isspace() or tokens[i] == "▁":
            sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.62, 0.95))
        attention[i, 0] = sink_mass

        # No secondary destination is established by the supplied examples.
        # Use a conservative causal background rather than a strong syntax rule.
        positions = np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_residual", attention


def prog_L12H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: dominant first-token attention with weak causal recency.
    Sink strength decreases mildly as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.83 + 0.11 * np.exp(-(i - 1) / 18.0)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L12H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with nominal anchors; copular modifiers inherit the subject.
    Predicate adjuncts can retrieve both the subject and the completed predicate."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_inherited_subjects", attention

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    reverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    # Use the final subtoken as the address of a completed nominal.
    addresses = {}
    for word in doc:
        indices = [j for j in reverse[word.i] if j > 0]
        if indices:
            addresses[word.i] = max(indices)

    attention[0, 0] = 1.0
    for i in range(1, n):
        distance = i - np.arange(i + 1)
        background = np.exp(-distance / 5.0)
        background[0] = 0.0
        background[i] *= 0.65

        sids = forward[i]
        word = doc[sids[-1]] if sids else None
        anchor = None
        strength = 0.0
        bos = 0.76 - 0.12 * min(i / 65.0, 1.0)

        if word is not None:
            nominal = word.pos_ in ("NOUN", "PROPN")
            if nominal:
                bos = 0.88 - 0.20 * min(i / 65.0, 1.0)
            elif word.pos_ in ("DET", "ADJ", "NUM"):
                bos += 0.03
            elif word.is_punct:
                bos -= 0.09

            # A noun is an anchor only after all its subtokens have appeared.
            candidates = [
                w for w in doc
                if w.pos_ in ("NOUN", "PROPN")
                and w.i in addresses
                and addresses[w.i] < i
                and w.i < word.i
            ]

            # Predicates preferentially retrieve an explicit nominal subject.
            predicate = word
            if word.dep_ in ("aux", "auxpass", "cop", "advmod"):
                predicate = word.head
            if word.pos_ in ("VERB", "AUX", "ADJ", "ADV", "CCONJ"):
                subjects = [
                    c for c in predicate.children
                    if c.dep_ in ("nsubj", "nsubjpass", "csubj")
                    and c.pos_ in ("NOUN", "PROPN")
                    and c.i in addresses
                    and addresses[c.i] < i
                ]
                if subjects:
                    subject = min(subjects, key=lambda w: i - addresses[w.i])
                    gap = i - addresses[subject.i]
                    anchor = addresses[subject.i]
                    if word.pos_ == "AUX" or word.dep_ == "cop":
                        strength = 0.83
                    elif word.pos_ == "ADJ":
                        strength = 0.64
                    elif word.pos_ == "VERB":
                        strength = 0.56
                    else:
                        strength = 0.42
                    strength *= np.exp(-max(gap - 3, 0) / 18.0)

            # Backward nominal attachments, including prepositional phrases.
            head = word.head
            if word.pos_ == "DET" and head.head.pos_ == "ADP":
                head = head.head.head
            if (
                word.pos_ in ("ADP", "DET", "NOUN")
                and head.pos_ in ("NOUN", "PROPN")
                and head.i in addresses
                and addresses[head.i] < i
                and head.i != word.i
            ):
                anchor = addresses[head.i]
                strength = 0.67 if word.pos_ != "NOUN" else 0.45

            if word.pos_ == "ADP" and strength == 0.0 and candidates:
                previous = candidates[-1]
                gap = i - addresses[previous.i]
                if gap <= 3:
                    anchor = addresses[previous.i]
                    strength = 0.57 * np.exp(-max(gap - 1, 0) / 5.0)

            # Object pronouns retrieve compatible preceding nominal mentions.
            if (
                word.pos_ == "PRON"
                and word.dep_ in ("dobj", "obj", "pobj", "iobj", "dative")
                and candidates
            ):
                best_score = -1.0
                for candidate in candidates:
                    j = addresses[candidate.i]
                    score = np.exp(-(i - j) / 35.0)
                    number = word.morph.get("Number")
                    other_number = candidate.morph.get("Number")
                    if number and other_number and number != other_number:
                        score *= 0.25
                    gender = word.morph.get("Gender")
                    if gender and candidate.ent_type_ == "PERSON":
                        score *= 1.3
                    if not gender and candidate.pos_ == "NOUN":
                        score *= 1.15
                    if score > best_score:
                        best_score = score
                        anchor = j
                strength = 0.67

            if word.is_punct and candidates:
                j = addresses[candidates[-1].i]
                if i - j <= 2:
                    anchor = j
                    strength = 0.36

            # Small distributed nominal preference even in sink-dominated rows.
            for candidate in candidates[-4:]:
                j = addresses[candidate.i]
                background[j] += 0.6 * np.exp(-(i - j) / 16.0)

        bos = float(np.clip(bos, 0.35, 0.92))
        if anchor is not None and strength > 0.0:
            strength = float(np.clip(strength, 0.0, 0.88))
            bos = min(bos, max(0.08, 0.93 - strength))
        else:
            strength = 0.0

        background /= background.sum()
        attention[i, :i + 1] = (1.0 - bos - strength) * background
        attention[i, 0] += bos
        if strength > 0.0:
            attention[i, anchor] += strength

        # Special case: recover subjects through copular complements and
        # coordination. Move only BOS mass, preserving self and background.
        if word is not None and (
            word.pos_ in ("ADJ", "ADV", "CCONJ")
            or word.dep_ in ("acomp", "oprd")
            or (
                word.pos_ == "ADP"
                and word.head.pos_ in ("VERB", "AUX", "ADJ")
            )
        ):
            governor = (
                word if word.pos_ == "ADJ" or word.dep_ in ("acomp", "oprd")
                else word.head
            )
            for _ in range(4):
                subjects = [
                    c for c in governor.children
                    if c.dep_ in ("nsubj", "nsubjpass")
                    and c.pos_ in ("NOUN", "PROPN")
                    and c.i in addresses
                    and addresses[c.i] < i
                ]
                if subjects:
                    break
                if governor.head.i == governor.i or governor.dep_ not in (
                    "acomp", "attr", "oprd", "conj", "advmod",
                    "cc", "prep", "aux", "cop"
                ):
                    break
                governor = governor.head

            if subjects and governor.pos_ in ("VERB", "AUX", "ADJ"):
                copular = (
                    governor.pos_ in ("AUX", "ADJ")
                    or any(c.dep_ == "cop" for c in governor.children)
                )
                if copular or word.pos_ in ("ADV", "ADP"):
                    subject = min(subjects, key=lambda w: i - addresses[w.i])
                    j = addresses[subject.i]
                    if i - j <= 16:
                        targets = [(j, 0.56 if copular else 0.34)]
                        if (
                            not copular
                            and governor.i in addresses
                            and addresses[governor.i] < i
                        ):
                            targets.append((addresses[governor.i], 0.30))
                        deficits = [
                            max(0.0, target - attention[i, k])
                            for k, target in targets
                        ]
                        total = sum(deficits)
                        if total > 0.0:
                            transfer = min(
                                total, max(0.0, attention[i, 0] - 0.10)
                            )
                            for (k, _), deficit in zip(targets, deficits):
                                attention[i, k] += transfer * deficit / total
                            attention[i, 0] -= transfer

    return "bos_sink_with_inherited_subjects", make_row_stochastic(attention)


def prog_L12H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with discourse-dependent leakage to earlier semantic anchors.
    Later clauses favor related content, antecedents, and completed utterances.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_retrieval", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sentence_ids = {}
    for sid, sent in enumerate(doc.sents):
        for word in sent:
            sentence_ids[word.i] = sid

    words = [
        doc[indices[0]] if indices else None
        for indices in aligned
    ]
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}
    nominal_pos = {"NOUN", "PROPN"}
    object_deps = {"dobj", "obj", "pobj", "attr", "oprd"}
    special_tokens = tokenizer.all_special_tokens

    matrix[0, 0] = 1.0
    quote_count = 0
    last_utterance_end = None

    for i in range(1, n):
        word = words[i]
        piece = tokens[i]
        quote_marks = sum(piece.count(mark) for mark in ('"', "“", "”"))
        completed_quotes = quote_count // 2
        sid = sentence_ids.get(word.i, 0) if word is not None else 0

        # Early rows overwhelmingly use the sink. Discourse transitions
        # make a larger non-sink budget available.
        sink = 0.955 - 0.0018 * i
        sink -= 0.14 * min(sid, 3)
        sink -= 0.045 * min(completed_quotes, 3)

        weights = np.zeros(i, dtype=np.float64)
        strongest_relation = 0.0

        for j in range(1, i):
            previous = words[j]
            if tokens[j] in special_tokens:
                continue

            distance = i - j
            weights[j] = 0.12 + 0.30 * np.exp(-distance / 7.0)

            if word is None or previous is None:
                continue
            if word.i == previous.i:
                weights[j] += 0.12
                continue

            if word.pos_ in content_pos and previous.pos_ in content_pos:
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                strength = max(0.0, (similarity - 0.40) / 0.60)
                strength = min(strength, 1.0)
                weights[j] += 24.0 * strength ** 3
                strongest_relation = max(strongest_relation, strength)

            if word.pos_ == "PRON" and previous.pos_ in nominal_pos:
                antecedent = np.exp(-distance / 22.0)
                if previous.dep_ in object_deps:
                    antecedent *= 1.8
                weights[j] += 2.0 * antecedent

            if word.head.i == previous.i:
                weights[j] += 0.35
            if previous.head.i == word.i:
                weights[j] += 0.20

        sink -= 0.22 * strongest_relation

        if word is not None and word.pos_ == "PRON":
            if sid > 0 or completed_quotes > 0:
                sink -= 0.12

        if last_utterance_end is not None and last_utterance_end < i:
            distance = i - last_utterance_end
            weights[last_utterance_end] += 4.0 * np.exp(-distance / 9.0)

        sink = float(np.clip(sink, 0.25, 0.97))
        matrix[i, 0] = sink

        # A small self component keeps rows well-defined even without
        # eligible earlier lexical tokens.
        matrix[i, i] = 0.20
        matrix[i, 1:i] = weights[1:i]
        residual = matrix[i, 1:i + 1].sum()
        matrix[i, 1:i + 1] *= (1.0 - sink) / residual

        quote_count += quote_marks
        if quote_marks and quote_count % 2 == 0:
            last_utterance_end = i

    return "bos_sink_with_discourse_retrieval", make_row_stochastic(matrix)


def prog_L12H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant BOS attention sink weakens with position.
    Residual attention favors self, recent context, and nearby syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if wi < len(doc):
                inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        # The sink dominates early, but more alternatives accumulate later.
        sink = 0.20 + 0.62 * np.exp(-max(i - 7, 0) / 25.0)
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink += 0.045
            elif word.pos_ in ("VERB", "ADJ"):
                sink += 0.025
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                sink -= 0.045
            elif word.is_punct:
                sink -= 0.065
        if not tokens[i].replace("▁", "").replace("Ġ", "").strip():
            sink += 0.055
        sink = float(np.clip(sink, 0.20, 0.89))

        positions = np.arange(1, i + 1)
        residual = 0.55 * np.exp(-(i - positions) / 4.5)
        residual[-1] += 1.0

        if word is not None:
            # Same-word pieces and already available dependency heads.
            for wi in word_ids:
                for j in inverse[wi]:
                    if 0 < j < i:
                        residual[j - 1] += 0.35

            for j in inverse[word.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.65

            # A clause subject can act as a secondary discourse anchor.
            clause = word
            for _ in range(4):
                if clause.head.i == clause.i or clause.pos_ in ("VERB", "AUX"):
                    break
                clause = clause.head
            for child in clause.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    for j in inverse[child.i]:
                        if 0 < j <= i:
                            residual[j - 1] += 0.75

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L12H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective retrieval of nonpronominal subjects and dialogue participants.
    Predicate and quotation tokens sometimes replace the sink with a discourse anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_anchors", matrix

    subjects = ("nsubj", "nsubjpass", "csubj")
    objects = ("dobj", "obj", "iobj", "dative", "oprd")
    nominal = ("NOUN", "PROPN")

    def endpoint(word, before):
        indices = [j for j in inverse[word.i] if 0 < j < before]
        return max(indices) if indices else None

    def subject_of(word):
        node = word
        for _ in range(5):
            candidates = [
                child for child in node.children
                if child.dep_ in subjects and child.i < word.i
            ]
            if candidates:
                return candidates[-1]
            if node.head.i == node.i:
                break
            node = node.head
        return None

    speaker = None
    addressee = None
    reporting = None
    in_quote = False
    quote_age = 0

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
        quotation = any(c in surface for c in ('"', "“", "”"))

        if quotation and not in_quote:
            preceding = [
                w for w in doc
                if w.pos_ == "VERB" and endpoint(w, i) is not None
            ]
            reporting = preceding[-1] if preceding else None
            speaker = subject_of(reporting) if reporting is not None else None
            recipients = (
                [c for c in reporting.children
                 if c.dep_ in objects and c.pos_ in nominal]
                if reporting is not None else []
            )
            addressee = recipients[-1] if recipients else None
            in_quote = True
            quote_age = 0

        position_factor = np.exp(-i / 12.0)
        sink = 0.55 + 0.29 * position_factor
        if word is None or (word is not None and word.is_space):
            sink = 0.84
        elif word.pos_ in nominal:
            sink = 0.72 + 0.18 * position_factor
        elif word.pos_ in ("DET", "ADP", "NUM"):
            sink = 0.64 + 0.22 * position_factor
        elif word.pos_ == "ADJ" and word.dep_ == "amod":
            sink = 0.76 + 0.13 * position_factor
        if i == 1:
            sink = 0.91

        anchor = None
        strength = 0.0

        if word is not None:
            subject = subject_of(word)
            if subject is not None and subject.pos_ in nominal:
                candidate = endpoint(subject, i)
                if candidate is not None:
                    if word.pos_ in ("VERB", "ADJ", "AUX"):
                        anchor, strength = candidate, 0.53
                    elif word.pos_ in ("ADV", "CCONJ", "SCONJ", "PUNCT"):
                        anchor, strength = candidate, 0.28

            if word.dep_ == "poss":
                candidate = endpoint(word.head, i)
                if candidate is not None:
                    anchor, strength = candidate, 0.40

            if in_quote:
                person = word.morph.get("Person")
                number = word.morph.get("Number")
                target = None
                quote_strength = 0.0
                if word.tag_ in ("WDT", "WP", "WP$", "WRB") and quote_age < 4:
                    target = addressee
                    quote_strength = 0.72
                elif word.pos_ == "PRON" and "2" in person:
                    target = addressee
                    quote_strength = 0.72
                elif word.pos_ == "PRON" and "1" in person:
                    target = reporting if "Plur" in number else speaker
                    quote_strength = 0.57
                elif quotation or word.pos_ in ("VERB", "AUX"):
                    target = speaker
                    quote_strength = 0.48
                if target is not None:
                    candidate = endpoint(target, i)
                    if candidate is not None:
                        anchor, strength = candidate, quote_strength

        if anchor is not None:
            sink = min(sink, max(0.16, 0.89 - strength))
        else:
            strength = 0.0

        residual = max(0.0, 1.0 - sink - strength)
        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 7.0) + 0.12
        matrix[i, 1:i + 1] = residual * background / background.sum()
        matrix[i, 0] = sink
        if anchor is not None:
            matrix[i, anchor] += strength

        if in_quote:
            quote_age += 1
            if quotation and quote_age > 1:
                in_quote = False

    return (
        "bos_sink_with_discourse_anchors",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L12H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Lexical content mildly modulates sink strength; residual attention is diffuse-causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # A dominant initial-token sink, not a syntactic retrieval head.
        logit = 2.95 - 0.025 * i - 0.50 * np.log1p(i)
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                logit += 0.25
            elif word.pos_ == "ADJ":
                logit += 0.35
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                logit -= 0.20
            elif word.pos_ == "VERB":
                logit -= 0.10

            if word.ent_type_:
                logit += 0.15
            if word.is_punct and word.is_sent_end:
                logit -= 0.45

        sink_mass = 1.0 / (1.0 + np.exp(-logit))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = 0.65 + 0.35 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L12H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker backward syntactic links.
    Punctuation and attaching modifiers occasionally override the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        sink_mass = 0.80 - 0.0035 * min(i, 80)
        target = None
        link_mass = 0.0

        if word is not None:
            # Only use a dependency when its head is already available.
            candidates = [
                j for j in inverse[word.head.i]
                if 0 < j < i and j not in inverse[word.i]
            ]
            if candidates:
                target = candidates[0]
                link_mass = 0.10
                if word.pos_ == "ADP":
                    link_mass = 0.37
                elif word.dep_ in ("appos", "acl", "relcl"):
                    link_mass = 0.27
                elif word.pos_ == "PUNCT":
                    link_mass = 0.25

            # Clause/list punctuation often points back to the preceding noun.
            if word.pos_ == "PUNCT" and word.text in (",", ";", ":"):
                previous = doc[word.i - 1] if word.i > 0 else None
                if previous is not None and previous.pos_ in (
                    "NOUN", "PROPN", "PRON"
                ):
                    candidates = [j for j in inverse[previous.i] if 0 < j < i]
                    if candidates:
                        target = candidates[0]
                        link_mass = 0.40

        if target is not None:
            sink_mass = min(sink_mass, 0.96 - link_mass)

        # Diffuse residual attention, mildly favoring recent positions.
        positions = np.arange(1, i + 1)
        background = 0.35 + np.exp(-(i - positions) / 7.0)
        residual = 1.0 - sink_mass - link_mass
        attention[i, 1:i + 1] = residual * background / background.sum()
        attention[i, 0] = sink_mass
        if target is not None:
            attention[i, target] += link_mass

    return "bos_sink_with_syntactic_links", make_row_stochastic(attention)


def prog_L12H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker local attention and retrieval of earlier
    salient objects, especially at later predicates and clause boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_object_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = []
    for indices in alignment:
        representatives.append(doc[indices[-1]] if indices else None)

    # Use the last subtoken of a noun as its retrieval location.
    noun_locations = {}
    for i, word in enumerate(representatives):
        if i > 0 and word is not None and word.pos_ in ("NOUN", "PROPN"):
            noun_locations[word.i] = i

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = representatives[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        maturity = 1.0 - np.exp(-max(0, i - 3) / 13.0)

        # Early tokens almost exclusively select the initial attention sink.
        sink = 0.94 - 0.17 * maturity
        if pos in ("VERB", "AUX"):
            sink -= 0.17 * maturity
        elif pos == "PRON":
            sink -= 0.20 * maturity
        elif pos in ("PUNCT", "CCONJ", "SCONJ"):
            sink -= 0.23 * maturity
        elif pos in ("ADP", "PART"):
            sink -= 0.10 * maturity
        elif pos in ("NOUN", "PROPN", "ADJ", "NUM"):
            sink += 0.035 * maturity

        if tokens[i].isspace() or tokens[i] == "▁":
            sink -= 0.12 * maturity

        # Prefer earlier objects over arbitrary content words. This correction
        # is deliberately secondary to the much stronger BOS prior.
        retrieval = np.zeros(i + 1, dtype=np.float64)
        if word is not None:
            for sid, j in noun_locations.items():
                if j >= i or sid >= word.i:
                    continue
                candidate = doc[sid]
                distance = i - j
                salience = 0.15
                if candidate.dep_ in ("dobj", "obj", "pobj", "attr", "oprd"):
                    salience = 1.0
                elif candidate.dep_ in ("nsubj", "nsubjpass"):
                    salience = 0.30

                if candidate.head.i == word.i:
                    salience *= 1.7
                if word.head.i == candidate.i:
                    salience *= 1.8
                retrieval[j] = salience * np.exp(-distance / 30.0)

        retrieval_total = retrieval.sum()
        retrieval_fraction = 0.20
        if pos in ("VERB", "AUX", "ADP", "PART", "PRON", "PUNCT"):
            retrieval_fraction = 0.58
        if retrieval_total == 0.0:
            retrieval_fraction = 0.0

        sink = np.clip(sink, 0.30, 0.97)
        attention[i, 0] = sink
        residual = 1.0 - sink

        if retrieval_total > 0.0:
            attention[i, :i + 1] += (
                residual * retrieval_fraction * retrieval / retrieval_total
            )

        local = np.exp(-(i - np.arange(1, i + 1)) / 2.5)
        local[-1] *= 1.4
        local /= local.sum()
        attention[i, 1:i + 1] += (
            residual * (1.0 - retrieval_fraction) * local
        )

    return "bos_sink_with_object_retrieval", make_row_stochastic(attention)


def prog_L12H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker, clause-local subject and predicate trace.
    Early positions favor BOS most strongly; syntax distributes the residual mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_trace", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0
    subject_deps = ("nsubj", "nsubjpass", "csubj", "csubjpass")
    clause_pos = ("VERB", "AUX")

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        bos_mass = 0.51 + 0.39 * np.exp(-(i - 1) / 7.5)
        if word is not None:
            if word.pos_ in ("PRON", "DET", "ADP", "PART"):
                bos_mass -= 0.09 * (1.0 - np.exp(-(i - 1) / 5.0))
            elif word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "ADV"):
                bos_mass += 0.045
            if word.is_punct:
                bos_mass += 0.025

        if tokens[i].isspace() or tokens[i] == "▁":
            bos_mass = max(bos_mass, 0.81)

        bos_mass = float(np.clip(bos_mass, 0.32, 0.95))
        weights = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        weights[1:] = 0.12 + 0.28 * np.exp(-(i - positions) / 5.0)

        if word is not None:
            # Trace the current predicate, including a predicate above a nominal.
            predicate = word
            for _ in range(5):
                if predicate.pos_ in clause_pos or predicate.head.i == predicate.i:
                    break
                predicate = predicate.head

            if predicate.pos_ in clause_pos:
                for child in predicate.children:
                    if child.dep_ in subject_deps:
                        eligible = [j for j in inverse[child.i] if 0 < j <= i]
                        if eligible:
                            weights[eligible[-1]] += 3.8

                eligible = [j for j in inverse[predicate.i] if 0 < j < i]
                if eligible:
                    weights[eligible[-1]] += 1.1

            # A nearby subject remains a useful anchor even across clause edges.
            for si in range(word.i - 1, max(-1, word.i - 16), -1):
                candidate = doc[si]
                if candidate.dep_ in subject_deps:
                    eligible = [j for j in inverse[si] if 0 < j < i]
                    if eligible:
                        weights[eligible[-1]] += 1.8
                        break

            if word.head.i != word.i:
                eligible = [j for j in inverse[word.head.i] if 0 < j < i]
                if eligible:
                    weights[eligible[-1]] += 0.8

        attention[i, 0] = bos_mass
        attention[i, 1:i + 1] = (
            (1.0 - bos_mass) * weights[1:] / weights[1:].sum()
        )

    return "bos_sink_with_clause_trace", attention


def prog_L12H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with diffuse residual attention.
    In quoted dialogue, selectively shift sink and diffuse mass to the diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_diagonal", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "VERB": 0.055,
        "AUX": 0.020,
        "ADJ": 0.045,
        "ADV": 0.025,
        "ADP": 0.035,
        "NOUN": 0.010,
        "PROPN": -0.025,
        "DET": 0.005,
        "PRON": -0.040,
        "CCONJ": -0.055,
        "SCONJ": -0.025,
        "PART": -0.020,
        "PUNCT": -0.100,
        "SPACE": -0.035,
    }

    has_dialogue = (
        sentence.count('"') >= 2
        or ("“" in sentence and "”" in sentence)
    )

    for i in range(1, n):
        sink = 0.755 - 0.0018 * min(i, 80)
        if alignment[i]:
            word = doc[alignment[i][0]]
            sink += pos_adjustment.get(word.pos_, 0.0)
        if i == 1:
            sink -= 0.100
        sink = float(np.clip(sink, 0.52, 0.86))

        # Preserve the original default distribution.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Quoted narratives show stronger diagonal attention, increasingly
        # replacing the BOS sink at later positions.
        if has_dialogue and i > 1:
            transfer = 0.045 + 0.0015 * min(i, 60)
            redirected = 0.55 * attention[i, 1:i].sum()
            attention[i, 1:i] *= 0.45
            attention[i, 0] -= transfer
            attention[i, i] += transfer + redirected

    return "bos_sink_with_dialogue_diagonal", attention


def prog_L12H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, modulated by lexical class and token boundaries.
    Non-sink attention is weak and diffusely biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos_prior = {
        "PROPN": 0.87,
        "NOUN": 0.79,
        "ADJ": 0.80,
        "VERB": 0.74,
        "ADV": 0.71,
        "DET": 0.75,
        "ADP": 0.66,
        "AUX": 0.63,
        "PRON": 0.64,
        "PART": 0.62,
        "CCONJ": 0.71,
        "SCONJ": 0.66,
        "NUM": 0.80,
        "PUNCT": 0.84,
        "SPACE": 0.90,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None

        sink = pos_prior.get(word.pos_, 0.76) if word is not None else 0.79
        sink += 0.11 * np.exp(-(i - 1) / 4.0)

        if word is not None:
            if word.dep_ in ("nsubj", "nsubjpass", "ROOT"):
                sink += 0.025
            if word.ent_type_:
                sink += 0.025

            # Continuation pieces often retain a particularly strong sink.
            if i > 1 and mapped and alignment[i - 1]:
                if mapped[0] in alignment[i - 1]:
                    sink += 0.045

        if not clean:
            sink = 0.90
        elif clean in ("'", "’"):
            sink = 0.95
        elif clean in (".", "?", "!", '?"', '!"'):
            sink = 0.85
        elif clean == ",":
            sink = 0.84

        if raw in special_tokens:
            sink = 0.97
        if i == 1:
            sink = 0.945

        sink = float(np.clip(sink, 0.55, 0.98))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_linguistic_gating", attention


def prog_L12H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened at punctuation and clause boundaries.
    Remaining attention is weak, diffuse, and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_boost", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]

        sink_mass = 0.81 + 0.07 * np.exp(-(i - 1) / 6.0)

        if words:
            pos = words[0].pos_
            dep = words[0].dep_

            if pos in ("VERB", "AUX"):
                sink_mass += 0.045
            elif pos in ("CCONJ", "SCONJ"):
                sink_mass += 0.065
            elif pos in ("NOUN", "PRON", "DET", "ADP"):
                sink_mass -= 0.035

            if dep in ("ROOT", "conj", "advcl", "ccomp"):
                sink_mass += 0.02

        if not clean:
            sink_mass = 0.96
        elif all(not ch.isalnum() for ch in clean):
            sink_mass = 0.93
        elif tokens[i] in tokenizer.all_special_tokens:
            sink_mass = 0.95

        if i == 1:
            sink_mass = 0.95

        sink_mass = float(np.clip(sink_mass, 0.70, 0.97))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.65 * np.exp(-(i - positions) / 4.0)
        residual += 0.35
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_boundary_boost", attention


def prog_L12H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink, strongest at discourse boundaries.
    Distribute the remaining attention locally, especially for phrase-internal tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        sink = 0.76

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("NOUN", "PROPN"):
                sink = 0.66
                if dep in ("dobj", "obj", "pobj", "attr", "oprd"):
                    sink = 0.57
                elif dep in ("nsubj", "nsubjpass", "nsubj:pass"):
                    sink = 0.70
            elif pos == "PRON":
                sink = 0.84 if dep in (
                    "nsubj", "nsubjpass", "nsubj:pass", "expl"
                ) else 0.65
            elif pos == "VERB":
                sink = 0.84
                if word.tag_ in ("VB", "VBG") and dep in (
                    "xcomp", "advcl", "acl"
                ):
                    sink = 0.65
            elif pos == "AUX":
                sink = 0.78
            elif pos == "ADJ":
                sink = 0.65 if dep == "amod" else 0.82
            elif pos == "ADV":
                sink = 0.80
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.86
            elif pos == "DET":
                sink = 0.70
            elif pos == "ADP":
                sink = 0.73
            elif pos == "PART":
                sink = 0.69
            elif pos == "PUNCT":
                sink = 0.85

            if word.is_sent_start and pos != "DET":
                sink = max(sink, 0.85)

        if not text:
            sink = 0.85
        elif all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in text):
            sink = 0.84
            if any(c in ".!?" for c in text):
                sink = 0.90
            if text in ("'", "’"):
                sink = 0.95
            if i == n - 1 and any(c in ".!?" for c in text):
                sink = 0.92

        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
            continue

        # Exclude BOS from the backoff so its assigned mass is preserved.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local /= local.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * 0.20 * local
        attention[i, i - 1] += (1.0 - sink) * 0.70
        attention[i, i] += (1.0 - sink) * 0.10
        attention[i, 0] = sink

    return "bos_sink_with_local_backoff", make_row_stochastic(attention)


def prog_L12H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, recency-biased causal background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_causal_background", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        distances = i - np.arange(1, i + 1)
        background = 0.5 / i + 0.5 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = 0.90
        attention[i, 1:i + 1] = 0.10 * background

    return "bos_sink_with_causal_background", attention


def prog_L12H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with selective backward routing from nominal arguments
    to their governing prepositions or predicates, plus weak local attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_argument_routing", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        weights = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        weights[1:] = 0.12 * np.exp(-(i - positions) / 4.0)
        weights[i] += 0.15

        # Ignore zero-width special tokens when assigning linguistic roles.
        candidates = alignment[i]
        word = None
        if tokens[i] not in tokenizer.all_special_tokens and candidates:
            word = doc[candidates[-1]]

        sink = 0.82
        if word is not None:
            pos, dep = word.pos_, word.dep_
            if pos == "PRON":
                sink = 0.89
            elif pos in ("VERB", "AUX"):
                sink = 0.86
            elif pos == "DET":
                sink = 0.79
            elif pos in ("ADP", "PART"):
                sink = 0.72
            elif pos in ("ADJ", "ADV"):
                sink = 0.75
            elif pos in ("NOUN", "PROPN", "NUM"):
                sink = 0.63
                if dep in ("pobj", "obl", "nmod"):
                    sink = 0.28
                elif dep in ("dobj", "obj", "attr", "oprd"):
                    sink = 0.39
                elif dep in ("nsubj", "nsubjpass", "csubj"):
                    sink = 0.73
            elif pos == "PUNCT":
                sink = 0.86

            # Only completed, preceding governors can receive causal attention.
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if word.head.i != word.i and head_positions:
                target = head_positions[-1]
                strength = 1.2
                if pos in ("NOUN", "PROPN", "NUM"):
                    strength = 4.0
                    if word.head.pos_ == "ADP":
                        strength = 8.0
                elif dep in ("amod", "advmod", "aux", "det"):
                    strength = 0.5
                weights[target] += strength

            # Later conjuncts can inherit an earlier argument's governor.
            if dep == "conj" and pos in ("NOUN", "PROPN"):
                governor = word.head.head
                previous = [j for j in inverse[governor.i] if 0 < j < i]
                if previous:
                    weights[previous[-1]] += 2.5
                    sink = min(sink, 0.48)

            # Preserve a small within-word component for split model tokens.
            previous_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if previous_pieces:
                weights[previous_pieces[-1]] += 0.35

        # Strong initial-position preference, decaying into the linguistic gate.
        sink += (0.985 - sink) * np.exp(-(i - 1) / 2.5)
        sink = float(np.clip(sink, 0.12, 0.99))

        total = weights.sum()
        attention[i, :i + 1] = weights * ((1.0 - sink) / total)
        attention[i, 0] = sink

    return "bos_sink_with_argument_routing", make_row_stochastic(attention)


def prog_L12H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker local and backward syntactic attention.
    Determiners and modifiers favor the sink; phrase endings favor recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "DET": 0.89,
        "ADJ": 0.86,
        "ADP": 0.82,
        "AUX": 0.80,
        "VERB": 0.80,
        "PRON": 0.80,
        "ADV": 0.77,
        "PART": 0.83,
        "NOUN": 0.73,
        "PROPN": 0.81,
        "NUM": 0.80,
        "CCONJ": 0.59,
        "SCONJ": 0.72,
        "PUNCT": 0.57,
    }

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        sink = 0.79
        if word is not None:
            sink = sink_by_pos.get(word.pos_, sink)
            if word.dep_ in ("poss", "det"):
                sink = 0.91
            elif word.dep_ in ("pobj", "dobj", "obj", "attr"):
                sink -= 0.07

        # Apostrophe fragments retain unusually strong sink attention.
        if tokens[i].strip("▁Ġ ") in ("'", "’"):
            sink = 0.92
        elif not tokens[i].strip("▁Ġ \t\n"):
            sink = 0.76

        if i == 1:
            sink = 0.89
            if word is not None and word.pos_ in ("ADP", "SCONJ", "ADV"):
                sink = 0.95

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 2.5)
        residual[-1] *= 0.40

        # Keep the non-sink mass local, with a modest syntactic correction.
        if word is not None and word.head.i != word.i:
            head_indices = [
                j for j in range(1, i)
                if word.head.i in alignment[j]
            ]
            if head_indices:
                residual[head_indices[-1] - 1] += 1.5

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_syntax", attention


def prog_L12H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with modest POS-dependent strength.
    Remaining attention is weak and distributed over the causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_adjustment = {
        "NOUN": 0.035,
        "PROPN": 0.035,
        "VERB": 0.025,
        "ADJ": 0.005,
        "ADV": -0.015,
        "AUX": -0.055,
        "ADP": -0.035,
        "DET": -0.045,
        "PRON": -0.075,
        "PART": -0.050,
        "CCONJ": -0.015,
        "SCONJ": -0.035,
        "PUNCT": 0.030,
        "SPACE": -0.100,
    }

    for i in range(1, n):
        aligned = alignment[i]
        adjustment = 0.0
        if aligned:
            adjustment = sum(
                pos_adjustment.get(doc[k].pos_, 0.0) for k in aligned
            ) / len(aligned)

        early_bonus = 0.035 * np.exp(-(i - 1) / 8.0)
        sink_mass = 0.835 + adjustment + early_bonus

        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if surface in ("'", "’"):
            sink_mass = max(sink_mass, 0.935)
        elif not surface:
            sink_mass -= 0.08

        sink_mass = float(np.clip(sink_mass, 0.60, 0.96))
        attention[i, 0] = sink_mass

        # With no observed non-BOS edges, use a conservative diffuse residual.
        distance = i - np.arange(1, i + 1)
        residual = 0.6 + 0.4 * np.exp(-distance / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_pos_modulated", attention


def prog_L12H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution.
    Punctuation and sentence onsets modestly strengthen the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in aligned[i]]
        word = words[0] if words else None
        surface = tokens[i].replace("▁", "").replace("Ġ", "")
        log_odds = np.log(15.0) - 0.85 * np.log(float(i))

        if word is not None:
            if word.pos_ in ("VERB", "AUX", "ADV"):
                log_odds += 0.10
            elif word.pos_ in ("ADP", "DET", "PART"):
                log_odds -= 0.08

            if word.is_sent_start:
                log_odds += 0.40
            if word.ent_type_:
                log_odds += 0.08
            if word.dep_ in ("nsubj", "nsubjpass"):
                log_odds += 0.06

        if not surface.strip():
            log_odds += 0.55
        elif surface in ("'", "’"):
            log_odds += 0.75
        elif surface == ",":
            log_odds += 0.25
        elif surface in (".", "!", "?"):
            log_odds += 0.45
        elif word is not None and word.is_punct:
            log_odds += 0.05

        sink_mass = 1.0 / (1.0 + np.exp(-log_odds))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L12H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a diffuse tail; locative openings and long dialogue add
    persistent earlier-token anchors, drawing mass only from BOS."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_anchors", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = (
            0.82
            + 0.10 * np.exp(-(i - 1) / 4.0)
            - 0.0018 * (i - 1)
        )

        text = tokens[i].lstrip("▁Ġ")
        if text and all(not c.isalnum() and not c.isspace() for c in text):
            if tokens[i] not in tokenizer.all_special_tokens:
                sink_mass -= 0.055

        sink_mass = float(np.clip(sink_mass, 0.58, 0.94))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        tail = 0.75 / i + 0.25 * np.exp(-distances / 5.0)
        tail /= tail.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * tail

    # Restrict corrections to two structural contexts absent from the default.
    doc = spacy_parse(sentence)
    locative_opening = (
        len(doc) > 0
        and doc[0].pos_ in ("ADP", "ADV")
        and doc[0].dep_ in ("prep", "advmod")
        and any(w.dep_ in ("pobj", "obl") for w in doc[0].subtree)
    )
    long_dialogue = (
        n >= 32 and sum(c in '"“”' for c in sentence) >= 2
    )

    if locative_opening or long_dialogue:
        mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
        anchors = np.zeros(n, dtype=np.float64)

        for w, indices in zip(doc, mapping):
            indices = [j for j in indices if 0 < j < n]
            if not indices:
                continue
            # Prefer the final piece of a noun rather than its incomplete stem.
            if w.pos_ in ("NOUN", "PROPN"):
                anchors[max(indices)] = 1.0
            elif long_dialogue and w.is_punct and any(
                c in "\"'“”‘’" for c in w.text
            ):
                anchors[max(indices)] = 0.65

        if mapping:
            opening = [j for j in mapping[0] if 0 < j < n]
            if opening:
                anchors[max(opening)] = 3.0 if locative_opening else 1.0

        for i in range(2, n):
            if not locative_opening and i < 16:
                continue

            previous = np.arange(1, i)
            weights = anchors[1:i] * (
                0.45 + 0.55 * np.exp(-(i - previous) / 18.0)
            )
            total = weights.sum()
            if total <= 0.0:
                continue

            if locative_opening:
                transfer = 0.10 + 0.08 * np.exp(-(i - 2) / 0.8)
            else:
                transfer = float(np.clip(
                    0.055 + 0.0022 * (i - 16), 0.055, 0.15
                ))

            transfer = min(transfer, max(0.0, attention[i, 0] - 0.45))
            attention[i, 0] -= transfer
            attention[i, 1:i] += transfer * weights / total

    return "bos_sink_with_context_anchors", attention


def prog_L12H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing, diffuse causal leakage.
    Punctuation queries weakly increase the non-BOS component.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0
    special_tokens = set(tokenizer.all_special_tokens)

    for i in range(1, n):
        # The observed head overwhelmingly selects BOS, even far into a passage.
        leakage_odds = 0.022 + 0.0012 * i + 0.00007 * i * i

        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        if (
            text
            and tokens[i] not in special_tokens
            and all(not c.isalnum() and not c.isspace() for c in text)
        ):
            leakage_odds *= 1.45

        bos_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = bos_mass

        # No specific non-BOS target is supported by the supplied edges.
        # Use a broad causal background with a mild recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.6 + 0.4 * np.exp(-(i - positions) / 16.0)
        attention[i, 1:i + 1] = (
            (1.0 - bos_mass) * background / background.sum()
        )

    return "bos_sink_with_diffuse_leakage", attention


def prog_L12H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the beginning and at punctuation.
    Remaining attention is weakly distributed over the causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        sink_mass = 0.70 + 0.27 * np.exp(-i / 9.0) - 0.0008 * i

        if aligned:
            if all(w.is_punct for w in aligned):
                sink_mass += 0.065
                if any(any(c in ".?!" for c in w.text) for w in aligned):
                    sink_mass += 0.055
            elif any(w.pos_ == "PRON" for w in aligned):
                sink_mass -= 0.035
            elif any(w.pos_ in ("DET", "CCONJ", "SCONJ") for w in aligned):
                sink_mass -= 0.020
        elif not tokens[i].replace("▁", "").replace("Ġ", "").strip():
            sink_mass += 0.055

        if i == 1:
            sink_mass = 0.965

        sink_mass = float(np.clip(sink_mass, 0.40, 0.975))
        attention[i, 0] = sink_mass

        # The examples identify the sink much more clearly than the
        # non-sink destinations, so use a conservative, diffuse residual.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 + 0.35 * np.exp(-distances / 12.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L12H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing causal background mass.
    Linguistic features weakly modulate sink strength; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        correction = 0.0
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("ADJ", "ADV", "PRON"):
                correction = 0.12
            elif word.pos_ in ("NOUN", "PROPN"):
                correction = -0.08
            elif word.pos_ == "PUNCT":
                correction = -0.06

        background_mass = 0.032 * (i ** 0.9) * np.exp(-correction)
        sink_mass = 1.0 / (1.0 + background_mass)

        # With only one alternative, the first token strongly favors BOS.
        if i == 1:
            sink_mass = 0.973

        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 1.0 + 0.35 * np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )
        attention[i, 0] = sink_mass

    return "bos_sink_with_position_decay", attention


def prog_L12H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary resets, including narrative restarts after quoted sentences.
    Missed quote-boundary resets redirect only off-diagonal residual attention to BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quoted_boundary_resets", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    # Index zero is the causal sink, normally the tokenizer's BOS token.
    attention[0, 0] = 1.0
    sentence_start = 1
    pending_quoted_restart = False
    quoted_restart = -1

    for i in range(1, n):
        piece = tokens[i].lstrip("▁Ġ")
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        # Quoted sentence endings may not produce a spaCy sentence boundary.
        next_piece = tokens[i + 1].lstrip("▁Ġ") if i + 1 < n else ""
        if (
            any(c in ".!?" for c in piece)
            and all(c in ".,;:!?\"'’‘“”()[]{}—–-" for c in piece)
            and (
                any(c in "\"'’”" for c in piece)
                or (
                    bool(next_piece)
                    and all(c in "\"'’”" for c in next_piece)
                )
            )
        ):
            pending_quoted_restart = True
        elif (
            pending_quoted_restart
            and word is not None
            and not word.is_punct
            and not word.is_space
        ):
            quoted_restart = i
            pending_quoted_restart = False

        if word is not None and word.is_sent_start:
            covered = inverse[word.i]
            if covered and i == covered[0]:
                sentence_start = i

        sink = 0.30 + 0.65 * np.exp(-(i - 1) / 4.8)
        if sentence_start > 1:
            sink += 0.32 * np.exp(-(i - sentence_start) / 2.7)

        if word is not None:
            if word.pos_ == "PROPN":
                sink += 0.08
            elif word.pos_ in ("VERB", "AUX"):
                sink += 0.025

            covered = inverse[word.i]
            if len(covered) > 1:
                # Short pieces in fragmented words often retain sink attention.
                if len(piece) <= 2:
                    sink += 0.17
                elif covered and i == covered[0]:
                    sink += 0.08

        if not piece or piece.isspace():
            sink = max(sink, 0.76)
        elif all(c in "'’‘" for c in piece):
            sink = max(sink, 0.79)
        elif all(c in ".,;:!?\"'’‘“”()[]{}—–-" for c in piece):
            if "." in piece:
                sink = max(sink, 0.66)
            elif "," in piece:
                sink += 0.09
            else:
                sink += 0.06

        sink = float(np.clip(sink, 0.20, 0.975))

        positions = np.arange(1, i + 1)
        residual = (
            0.75 * np.exp(-(i - positions) / 3.0)
            + 0.25 / np.sqrt(i - positions + 1.0)
        )

        if word is not None:
            head_positions = inverse[word.head.i]
            for j in head_positions:
                if 0 < j <= i and word.head.i != word.i:
                    residual[j - 1] += 0.30

            # A nominal's preceding adposition is a plausible secondary target.
            if word.pos_ in ("NOUN", "PROPN", "PRON"):
                for j in range(max(1, i - 5), i):
                    if any(doc[k].pos_ == "ADP" for k in alignment[j]):
                        residual[j - 1] += 0.45 * np.exp(-(i - j - 1) / 3.0)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Repair only missed quoted-boundary resets; preserve self-attention.
        if (
            quoted_restart > 1
            and 0 <= i - quoted_restart <= 4
            and sentence_start != quoted_restart
            and word is not None
            and not word.is_punct
            and not word.is_space
            and inverse[word.i]
            and i == inverse[word.i][0]
        ):
            available = attention[i, 1:i].sum()
            if available > 0.0:
                boost = min(
                    0.36 * np.exp(-(i - quoted_restart) / 2.7),
                    0.9 * available,
                )
                attention[i, 1:i] *= 1.0 - boost / available
                attention[i, 0] += boost

    return "bos_sink_with_quoted_boundary_resets", make_row_stochastic(attention)


def prog_L12H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakening gradually with context length.
    Unobserved residual attention is modeled as diffuse causal attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_residual", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = np.clip(0.965 - 0.0045 * i, 0.55, 0.96)

        # No consistent non-BOS destination is evidenced by the examples.
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i
        attention[i, 0] = sink_mass

    return "bos_sink_with_diffuse_residual", attention


def prog_L12H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective attention to recent lexical anchors.
    Clause punctuation and tokens following nominal/predicative anchors release BOS mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_selective_lexical_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Original default behavior, unchanged.
        sink = 0.80 + 0.18 * np.exp(-(i - 1) / 5.0)
        sink -= 0.035 * (1.0 - np.exp(-(i - 1) / 40.0))

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink -= 0.18
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.035
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ", "PART"):
                sink -= 0.035

        if i == 1:
            sink = 0.98
        sink = float(np.clip(sink, 0.45, 0.98))

        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        # Transfer only BOS mass: preserve self-attention and all other
        # original weights except the explicitly selected lexical targets.
        if i > 1 and aligned:
            word = doc[aligned[0]]
            punctuation = word.is_punct and not word.is_quote
            if punctuation or word.pos_ not in ("NOUN", "PROPN", "ADJ"):
                targets = []
                additions = []
                window = 12 if punctuation else 5
                for j in range(max(1, i - window), i):
                    if not alignment[j]:
                        continue
                    sid = alignment[j][-1]
                    # Use only the last subtoken of an earlier spaCy word.
                    if sid in aligned or sid in alignment[j + 1]:
                        continue
                    anchor = doc[sid]
                    nominal = anchor.pos_ in ("NOUN", "PROPN")
                    predicate = anchor.pos_ == "ADJ" and anchor.dep_ != "amod"
                    if not (nominal or predicate or
                            (punctuation and anchor.pos_ in ("VERB", "ADV"))):
                        continue
                    strength = 0.14 if nominal else 0.12
                    if punctuation:
                        strength *= 1.5
                    distance = i - j - 1
                    targets.append(j)
                    additions.append(
                        strength * np.exp(-distance / (6.0 if punctuation else 3.0))
                    )

                if additions:
                    additions = np.asarray(additions, dtype=np.float64)
                    total = float(additions.sum())
                    transfer = min(
                        total, 0.46 if punctuation else 0.26,
                        attention[i, 0]
                    )
                    attention[i, targets] += additions * (transfer / total)
                    attention[i, 0] -= transfer

    return "bos_sink_with_selective_lexical_anchors", attention


def prog_L13H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened at punctuation and discourse boundaries.
    Residual attention follows a weak causal recency and syntactic-head prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                inverse[wi].append(ti)

    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].lstrip("▁Ġ")
        words = [doc[k] for k in alignment[i] if 0 <= k < len(doc)]
        word = max(words, key=lambda w: len(w.text)) if words else None

        sink = 0.65
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "ADJ"):
                sink = 0.57
            elif pos == "PROPN":
                sink = 0.70
            elif pos in ("VERB", "AUX"):
                sink = 0.65
            elif pos in ("PRON", "DET", "ADP", "PART"):
                sink = 0.70
            elif pos == "ADV":
                sink = 0.69
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.79

            if word.dep_ in ("cc", "mark", "discourse"):
                sink += 0.025
            if word.is_sent_start:
                sink = max(sink, 0.79)
            if word.ent_type_:
                sink += 0.015

        if i == 1:
            sink = max(sink, 0.78)

        if not surface.strip():
            sink = 0.88
        elif tokens[i] in special_tokens:
            sink = 0.90
        elif all(not c.isalnum() for c in surface):
            sink = 0.81
            if any(c in ".!?" for c in surface):
                sink = 0.92
            elif any(c in "'’" for c in surface):
                sink = 0.89
            elif any(c in "\"“”" for c in surface):
                sink = 0.80

        sink = float(np.clip(sink, 0.50, 0.95))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.30 / i + 0.70 * np.exp(-(i - positions) / 4.0)
        if word is not None:
            for head_token in inverse[word.head.i]:
                if 1 <= head_token <= i and head_token != i:
                    residual[head_token - 1] += 0.25

        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_boundary_gating", attention


def prog_L13H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with prepositional routing, backed off toward the governing
    content word when a preposition receives an overconfident routing bonus.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prepositional_backoff", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(aligned):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                inverse[wi].append(ti)

    matrix[0, 0] = 1.0

    for i in range(1, n):
        word = doc[aligned[i][0]] if aligned[i] else None
        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        sink = 0.66 + 0.30 * np.exp(-(i - 1) / 5.0)
        head_target = None
        prep_target = None

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink -= 0.15
            elif pos == "ADJ":
                sink -= 0.10
            elif pos == "ADV":
                sink -= 0.06
            elif pos == "PRON":
                sink -= 0.035
            elif pos in ("DET", "AUX", "VERB", "PART"):
                sink += 0.035
            elif pos == "PUNCT":
                sink += 0.045

            if word.head.i != word.i:
                candidates = [
                    j for j in inverse[word.head.i] if 0 < j < i
                ]
                if candidates:
                    head_target = candidates[0]

            # English pobj structures, including modifiers within the object.
            governor = word.head
            if pos in ("NOUN", "PROPN", "PRON", "ADJ"):
                if governor.pos_ != "ADP" and word.dep_ in (
                    "amod", "compound", "nummod"
                ):
                    governor = governor.head
                if governor.pos_ == "ADP":
                    candidates = [
                        j for j in inverse[governor.i] if 0 < j < i
                    ]
                    if candidates:
                        prep_target = candidates[0]

        if clean in ("'", "’"):
            sink += 0.19
        elif not clean.strip():
            sink += 0.075

        # Very short prefixes are dominated by the initial attention sink.
        if i == 1:
            sink = 0.94

        if prep_target is not None:
            distance = i - prep_target
            sink -= 0.16 + 0.05 * min(distance / 4.0, 1.0)

        sink = float(np.clip(sink, 0.22, 0.97))
        remainder = 1.0 - sink

        local = np.exp(-(i - np.arange(1, i + 1)) / 3.0)
        local /= local.sum()

        if prep_target is not None:
            matrix[i, 1:i + 1] = remainder * 0.18 * local
            matrix[i, prep_target] += remainder * 0.82
        elif head_target is not None:
            matrix[i, 1:i + 1] = remainder * 0.65 * local
            matrix[i, head_target] += remainder * 0.35
        else:
            matrix[i, 1:i + 1] = remainder * local

        matrix[i, 0] = sink

        # Back off only the explicit prepositional bonus. The local kernel,
        # self-attention, and rows without prepositional routing are unchanged.
        if prep_target is not None:
            parent = governor.head
            if parent.i != governor.i and parent.pos_ in (
                "VERB", "NOUN", "PROPN", "ADJ"
            ):
                candidates = [
                    j for j in inverse[parent.i] if 0 < j < i
                ]
                if candidates:
                    transfer = 0.75 * remainder * 0.82
                    matrix[i, prep_target] -= transfer
                    matrix[i, candidates[-1]] += 0.35 * transfer
                    matrix[i, 0] += 0.65 * transfer

    return (
        "bos_sink_with_prepositional_backoff",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L13H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak local residual attention.
    Linguistic features mildly modulate sink strength, not target selection.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.70 + 0.08 * np.exp(-(i - 1) / 8.0)
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("DET", "ADP", "ADV", "CCONJ"):
                sink += 0.025
            elif word.pos_ in ("NOUN", "PROPN", "PRON"):
                sink -= 0.025

        text = tokens[i].lstrip("▁Ġ")
        if text and all(c in "'’" for c in text):
            sink = max(sink, 0.85)
        elif text and all(not c.isalnum() and not c.isspace() for c in text):
            sink += 0.025

        if i == 1:
            sink = 0.91
        sink = float(np.clip(sink, 0.55, 0.94))

        positions = np.arange(1, i + 1)
        residual = 0.65 * np.exp(-(i - positions) / 4.0)
        residual += 0.35 / np.sqrt(i - positions + 1.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_weak_recency", attention


def prog_L13H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest on content tokens and sentence boundaries.
    Residual attention favors recent tokens, especially within split words.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        continuation = bool(
            aligned
            and alignment[i - 1]
            and set(aligned).intersection(alignment[i - 1])
        )

        sink = 0.81
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB"):
                sink = 0.88
            elif word.pos_ in ("ADV", "NUM"):
                sink = 0.84
            elif word.pos_ in ("DET", "PRON", "ADP", "AUX", "PART"):
                sink = 0.77
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink = 0.71
            elif word.pos_ == "PUNCT":
                sink = 0.88 if word.is_sent_end else 0.73

            if word.ent_type_:
                sink = min(0.92, sink + 0.02)

        if continuation:
            sink = max(0.58, sink - 0.16)
        if i == 1:
            sink = 0.90
        if tokens[i].isspace():
            sink = 0.76

        # Keep the sink mass independent of context length.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.0)
        if i > 1:
            local[-2] += 1.5
        if continuation and i > 1:
            local[-2] += 2.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_local_residual", attention


def prog_L13H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink head with secondary attention to causal clause subjects and predicates.
    Content modifiers and word fragments favor BOS; predicates favor subject anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_clause_anchors", matrix

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    subject_deps = ("nsubj", "nsubjpass", "csubj", "csubjpass")
    predicate_pos = ("VERB", "AUX")
    special_tokens = set(tokenizer.all_special_tokens)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        sids = forward[i]
        word = doc[sids[-1]] if sids else None
        weights = np.zeros(i + 1, dtype=np.float64)

        # A small causal background prevents all residual mass collapsing
        # onto a single syntactic edge.
        weights[1:] = 0.10 * np.exp(
            -(i - np.arange(1, i + 1)) / 7.0
        )
        weights[i] += 0.12
        weights[i - 1] += 0.18

        bos = 0.56
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                bos = 0.66
            elif pos == "ADJ":
                bos = 0.68
            elif pos in predicate_pos:
                bos = 0.29
            elif pos == "PRON":
                bos = 0.43
            elif pos in ("DET", "ADP"):
                bos = 0.57
            elif pos in ("CCONJ", "SCONJ", "ADV", "PART"):
                bos = 0.44
            elif pos == "PUNCT":
                bos = 0.25

            # Find the current clause's predicate without crossing sentences.
            clause = word
            visited = set()
            while clause.i not in visited:
                visited.add(clause.i)
                if clause.pos_ in predicate_pos or clause.head.i == clause.i:
                    break
                clause = clause.head

            predicates = [clause]
            if word.pos_ in predicate_pos:
                predicates = [word]
                if word.dep_ in ("conj", "xcomp", "ccomp", "advcl"):
                    predicates.append(word.head)

            for predicate in predicates:
                for child in predicate.children:
                    if child.dep_ not in subject_deps:
                        continue
                    candidates = [j for j in inverse[child.i] if 0 < j < i]
                    if candidates:
                        target = candidates[-1]
                        strength = 1.35 if pos in predicate_pos else 0.55
                        weights[target] += strength

                candidates = [
                    j for j in inverse[predicate.i] if 0 < j < i
                ]
                if candidates:
                    strength = 1.25 if pos in (
                        "PUNCT", "CCONJ", "SCONJ"
                    ) else 0.65
                    weights[candidates[-1]] += strength

            # If a syntactic governor is still in the future, the most
            # recent observed predicate provides a causal clause anchor.
            recent_predicate = None
            for prior in reversed(doc[:word.i]):
                if prior.sent.start != word.sent.start:
                    break
                if prior.pos_ in predicate_pos:
                    candidates = [
                        j for j in inverse[prior.i] if 0 < j < i
                    ]
                    if candidates:
                        recent_predicate = candidates[-1]
                        break
            if recent_predicate is not None:
                weights[recent_predicate] += (
                    0.85 if pos in ("PUNCT", "CCONJ", "SCONJ") else 0.30
                )

            # Modifier tokens tend to be sink queries rather than
            # syntactic retrieval queries.
            if word.dep_ in ("amod", "det", "poss", "compound"):
                bos += 0.06

            covered = inverse[word.i]
            if len(covered) > 1 and pos != "PUNCT":
                bos += 0.08

            # Before any predicate is available, BOS is particularly strong.
            has_prior_predicate = any(
                w.pos_ in predicate_pos and any(
                    0 < j < i for j in inverse[w.i]
                )
                for w in doc[:word.i]
            )
            if not has_prior_predicate:
                bos = max(bos, 0.82 - 0.025 * min(i, 8))

        if not clean or raw in special_tokens:
            bos = max(bos, 0.82)
        if clean and all(c in "'’`" for c in clean):
            bos = max(bos, 0.84)
        if clean and any(ord(c) > 127 for c in clean):
            bos = max(bos, 0.80)

        if i == 1:
            bos = 0.94
        else:
            bos += 0.07 * np.exp(-(i - 2) / 4.0)

        bos = float(np.clip(bos, 0.18, 0.96))
        weights[0] = 0.0
        total = weights.sum()
        if total > 0:
            matrix[i, :i + 1] = weights * ((1.0 - bos) / total)
        else:
            matrix[i, i] = 1.0 - bos
        matrix[i, 0] = bos

    return "bos_sink_clause_anchors", make_row_stochastic(matrix)


def prog_L13H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized nominal-phrase and subword continuation attention.
    Redirect only BOS mass on these rows, preserving self-attention and decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_nominal_continuation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_sink = {
        "NOUN": 0.67,
        "PROPN": 0.75,
        "ADJ": 0.67,
        "ADV": 0.70,
        "VERB": 0.78,
        "AUX": 0.74,
        "PRON": 0.75,
        "DET": 0.77,
        "ADP": 0.73,
        "PART": 0.76,
        "CCONJ": 0.69,
        "SCONJ": 0.72,
        "PUNCT": 0.83,
        "SPACE": 0.78,
    }

    for i in range(1, n):
        sink_mass = 0.73
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            sink_mass = pos_sink.get(word.pos_, 0.73)
            if word.dep_ == "ROOT":
                sink_mass += 0.02

        if tokens[i] in tokenizer.all_special_tokens:
            sink_mass = 0.90
        if i == 1:
            sink_mass = 0.91

        sink_mass = float(np.clip(sink_mass, 0.60, 0.95))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-distances / 5.0)
        recent /= recent.sum()
        residual = 0.65 / i + 0.35 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Local nominal continuations borrow from BOS, not from the baseline
        # residual: all unrelated edges, including the diagonal, stay unchanged.
        if (
            i > 1
            and aligned
            and tokens[i] not in tokenizer.all_special_tokens
            and word.pos_ in ("NOUN", "PROPN", "ADJ")
        ):
            target = None
            transfer = 0.0
            previous = doc[word.i - 1] if word.i > 0 else None

            if (
                previous is not None
                and previous.dep_ == "compound"
                and previous.head.i == word.i
            ):
                candidates = [
                    j for j in range(1, i) if previous.i in alignment[j]
                ]
                if candidates:
                    target = candidates[-1]
                    transfer = 0.36
            elif word.i in alignment[i - 1]:
                target = i - 1
                transfer = 0.18
            elif (
                previous is not None
                and previous.pos_ in ("DET", "ADJ")
                and (
                    previous.head.i == word.i
                    or previous.head.i == word.head.i
                )
            ):
                candidates = [
                    j for j in range(1, i) if previous.i in alignment[j]
                ]
                if candidates:
                    target = candidates[-1]
                    transfer = 0.14 if previous.pos_ == "DET" else 0.18

            if target is not None:
                transfer = min(transfer, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, target] += transfer

    return "bos_sink_nominal_continuation", make_row_stochastic(attention)


def prog_L13H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local bridge: clause/linking function words sometimes
    redirect part of their self-attention to the immediately preceding word."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_function_word_bridge", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "NOUN": 0.72,
        "PROPN": 0.77,
        "ADJ": 0.67,
        "NUM": 0.65,
        "ADV": 0.53,
        "VERB": 0.48,
        "AUX": 0.49,
        "PRON": 0.43,
        "DET": 0.53,
        "ADP": 0.48,
        "PART": 0.45,
        "CCONJ": 0.42,
        "SCONJ": 0.44,
        "INTJ": 0.55,
        "PUNCT": 0.44,
        "SPACE": 0.59,
        "X": 0.56,
    }

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        sink = sink_by_pos.get(word.pos_, 0.54) if word is not None else 0.56

        continuation = bool(
            sids and i > 1 and any(sid in alignment[i - 1] for sid in sids)
        )
        if continuation:
            sink -= 0.07

        if word is not None:
            if word.ent_type_:
                sink += 0.025
            if word.dep_ in ("nsubj", "nsubjpass", "appos"):
                sink += 0.025
            if word.dep_ in ("amod", "compound"):
                sink += 0.025
            if word.pos_ == "PRON" and word.dep_ in ("dobj", "obj", "pobj"):
                sink -= 0.06

        if i == 1:
            sink = 0.70
            if word is not None:
                if word.pos_ in ("PRON", "PROPN", "NUM"):
                    sink = 0.745
                elif word.pos_ == "DET":
                    sink = 0.66

        sink = float(np.clip(sink, 0.30, 0.84))
        attention[i, 0] = sink

        residual = 1.0 - sink
        if i == 1:
            attention[i, i] = residual
            continue

        attention[i, i] = 0.80 * residual
        previous = np.arange(1, i)
        local_weights = np.exp(-(i - previous - 1) / 1.8)
        local_weights /= local_weights.sum()
        attention[i, 1:i] = 0.20 * residual * local_weights

        # Only word-boundary function-word bridges alter the default row.
        if word is not None and not continuation and alignment[i - 1]:
            prev_word = doc[alignment[i - 1][-1]]
            linker = (
                word.pos_ in ("ADP", "PART", "SCONJ", "CCONJ")
                and prev_word.pos_ in (
                    "VERB", "AUX", "NOUN", "PROPN", "ADJ", "ADV"
                )
            )
            argument_intro = (
                word.pos_ in ("DET", "PRON")
                and prev_word.pos_ in ("ADP", "VERB", "CCONJ")
            )
            if linker or argument_intro:
                fraction = 0.50 if linker else 0.40
                transfer = min(0.22, fraction * attention[i, i])
                attention[i, i] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_function_word_bridge", make_row_stochastic(attention)


def prog_L13H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with local syntax and stronger phrase-boundary links.
    At selected boundaries, move only BOS mass to the preceding token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        sink = 0.77
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink = 0.83
            elif pos == "ADJ":
                sink = 0.80
            elif pos == "PRON":
                sink = 0.79
            elif pos == "VERB":
                sink = 0.73
            elif pos == "AUX":
                sink = 0.59
            elif pos == "ADV":
                sink = 0.69
            elif pos == "PUNCT":
                sink = 0.68
            elif pos in ("ADP", "SCONJ", "CCONJ"):
                sink = 0.71

            if word.ent_type_:
                sink = min(0.88, sink + 0.025)

        if i == 1:
            sink = 0.92

        # Distribute non-sink mass locally, including the current token.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.65

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_positions:
                residual[head_positions[-1] - 1] += 1.2

            # An auxiliary can read a preceding subject of its predicate.
            if word.pos_ == "AUX":
                predicate = word.head
                subjects = [
                    child for child in predicate.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                ]
                subject_positions = [
                    j for subject in subjects
                    for j in inverse[subject.i] if 0 < j < i
                ]
                if subject_positions:
                    j = max(subject_positions)
                    residual[j - 1] += 3.5
                    if i <= 4 and i - j <= 2:
                        sink = 0.30
                        residual[j - 1] += 12.0

            # Keep a small connection to earlier pieces of the same word.
            for j in inverse[word.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.45

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

        # Boundary links replace BOS mass, leaving self-attention and
        # every other non-BOS edge exactly as computed above.
        if word is not None and i > 1 and alignment[i - 1]:
            previous = doc[alignment[i - 1][-1]]
            if previous.i != word.i and i == min(inverse[word.i]):
                target = 0.0

                if word.pos_ == "PUNCT" and previous.pos_ != "PUNCT":
                    terminal = word.text in (".", "!", "?")
                    before_coordination = (
                        word.i + 1 < len(doc)
                        and doc[word.i + 1].pos_ == "CCONJ"
                    )
                    if terminal:
                        target = 0.32
                    elif word.text == "," and (
                        before_coordination or previous.pos_ == "ADV"
                    ):
                        target = 0.36

                elif word.pos_ == "CCONJ":
                    target = 0.22

                elif (
                    word.pos_ == "PRON"
                    and word.dep_ in ("nsubj", "nsubjpass", "csubj")
                ):
                    if previous.pos_ in ("NOUN", "PROPN", "ADV"):
                        target = 0.42
                    elif previous.pos_ == "CCONJ":
                        target = 0.18

                elif word.pos_ == "ADV":
                    if previous.pos_ == "CCONJ":
                        target = 0.33
                    elif previous.dep_ == "prt":
                        target = 0.50

                transfer = min(
                    max(0.0, target - attention[i, i - 1]),
                    attention[i, 0],
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_boundary_links", attention


def prog_L13H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with sentence-opening resets and punctuation boosts.
    Residual attention follows causal clause and prepositional anchors."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0
    opening = 1
    previous_si = -1

    for i in range(1, n):
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = surface.strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        if word is not None and word.i != previous_si:
            if word.is_sent_start:
                opening = i
            previous_si = word.i

        # Terminal punctuation also marks openings when sentence segmentation
        # misses a boundary inside dialogue.
        if i > 1:
            previous_surface = tokens[i - 1].replace("▁", " ").strip()
            if any(c in previous_surface for c in ".!?"):
                if word is not None and not word.is_punct:
                    opening = i

        distance = max(0, i - opening)
        sink = 0.34 + 0.62 * np.exp(-distance / 3.6)
        if opening > 1:
            sink -= 0.08 * np.exp(-distance / 3.6)

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if dep in ("nsubj", "nsubjpass", "csubj"):
                sink += 0.10
            if pos in ("VERB", "AUX") and dep in (
                "ROOT", "conj", "parataxis"
            ):
                sink += 0.22
            if pos == "PROPN":
                sink += 0.12
            if word.ent_type_ == "PERSON":
                sink += 0.07
            if pos == "CCONJ":
                sink += 0.06

        if not stripped:
            sink = max(sink, 0.83)
        elif stripped in ("'", "’", "‘"):
            sink = max(sink, 0.94)
        elif all(c in "\"“”«»" for c in stripped):
            sink = max(sink, 0.64)
        elif all(c in ".,!?;:\"'’”“()[]{}—–-" for c in stripped):
            sink = max(sink, 0.57 if "," in stripped else 0.61)

        sink = float(np.clip(sink, 0.22, 0.98))

        # The non-sink component is local, but favors accessible ancestors
        # that introduce the current phrase or clause.
        positions = np.arange(1, i + 1)
        residual = 0.12 * np.exp(-(i - positions) / 4.0)
        residual[-1] += 0.12

        if word is not None:
            ancestor = word
            for depth in range(6):
                parent = ancestor.head
                if parent.i == ancestor.i:
                    break
                candidates = [
                    ti for ti in inverse[parent.i] if 0 < ti <= i
                ]
                if candidates:
                    anchor = candidates[0]
                    if parent.pos_ in ("ADP", "SCONJ"):
                        strength = 2.4
                    elif parent.pos_ in ("VERB", "AUX"):
                        strength = 1.8
                    else:
                        strength = 0.35
                    residual[anchor - 1] += strength / (1.0 + 0.45 * depth)
                ancestor = parent

            # Preserve a modest link to the beginning of a split word.
            pieces = [ti for ti in inverse[word.i] if 0 < ti < i]
            if pieces:
                residual[pieces[0] - 1] += 0.25

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_syntactic_residual", attention


def prog_L13H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant beginning-of-sequence attention sink.
    Punctuation and clause-linking tokens weakly shift mass toward recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.90
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                sink_mass = 0.66
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass = 0.76
            elif word.pos_ in ("PRON", "AUX"):
                sink_mass = 0.84
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM"):
                sink_mass = 0.93
            elif word.pos_ == "VERB":
                sink_mass = 0.86
            elif word.pos_ == "ADV":
                sink_mass = 0.83

        # Early queries show especially strong sink behavior.
        sink_mass += 0.025 * np.exp(-(i - 1) / 8.0)
        sink_mass -= 0.035 * (1.0 - np.exp(-(i - 1) / 32.0))

        # The examples reveal little about non-sink destinations; use a
        # conservative, causal recency prior rather than a semantic target.
        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 3.0)
        local /= local.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * local

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L13H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink, with diffuse causal leakage.
    Coordinated noun lists can briefly redirect attention to their first item.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_list_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None

        # The sink remains dominant; accumulated alternatives become more
        # competitive farther into the sequence.
        leakage = min(0.32, 0.035 + 0.0025 * i)
        if word is not None:
            if word.pos_ in ("CCONJ", "SCONJ"):
                leakage += 0.075
            elif word.pos_ == "PUNCT":
                leakage += 0.055
            elif word.dep_ == "conj":
                leakage += 0.045
        if i == 1:
            leakage = 0.022

        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 7.0)

        # Weak syntactic corrections to the otherwise diffuse residual.
        if word is not None:
            for target in inverse[word.head.i]:
                if 0 < target <= i:
                    residual[target - 1] += 0.7
            for target in inverse[word.i]:
                if 0 < target < i:
                    residual[target - 1] += 0.4

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual / residual.sum()

        # Detect nominal coordination structurally rather than lexically.
        anchor = None
        strength = 0.0
        if word is not None:
            if word.dep_ == "conj" and word.pos_ in ("NOUN", "PROPN"):
                anchor = word.head
                strength = 0.43
            elif word.pos_ == "PUNCT" and word.text == "," and word.i > 0:
                previous = doc[word.i - 1]
                if previous.pos_ in ("NOUN", "PROPN"):
                    if previous.dep_ == "conj":
                        anchor = previous.head
                        strength = 0.46
                    elif any(
                        child.dep_ == "conj"
                        and child.pos_ in ("NOUN", "PROPN")
                        for child in previous.children
                    ):
                        anchor = previous
                        strength = 0.84

        if anchor is not None:
            candidates = [j for j in inverse[anchor.i] if 0 < j < i]
            if candidates:
                attention[i] *= 1.0 - strength
                attention[i, candidates[-1]] += strength

    return "bos_sink_with_list_anchors", make_row_stochastic(attention)


def prog_L13H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay and punctuation boosts.
    Residual attention is diffuse, favoring early context and nearby tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    key_salience = np.ones(n, dtype=np.float64)

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        if word is not None:
            if word.pos_ in ("AUX", "VERB"):
                key_salience[i] = 1.35
            elif word.pos_ in ("NOUN", "PROPN"):
                key_salience[i] = 1.10

    for i in range(1, n):
        piece = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = piece.strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink = 0.46 + 0.34 * np.exp(-(i - 1) / 25.0)

        if i == 1:
            sink = 0.89
            if word is not None:
                if word.pos_ == "PROPN":
                    sink += 0.04
                elif word.pos_ in ("DET", "PRON"):
                    sink -= 0.02
        else:
            if not stripped:
                sink += 0.16
            elif all(not c.isalnum() for c in stripped):
                if "'" in stripped or "’" in stripped:
                    sink += 0.22
                elif any(c in ".?!" for c in stripped):
                    sink += 0.16
                else:
                    sink += 0.06

            if word is not None:
                if word.pos_ == "PROPN":
                    sink += 0.10
                elif word.pos_ == "DET":
                    sink += 0.025
                if word.ent_type_:
                    sink += 0.025

        sink = float(np.clip(sink, 0.28, 0.96))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1, dtype=np.float64)
        early = np.exp(-(positions - 1.0) / 8.0)
        nearby = np.exp(-(i - positions) / 4.0)
        early /= early.sum()
        nearby /= nearby.sum()

        residual = (0.70 * early + 0.30 * nearby) * key_salience[1:i + 1]
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_positional_decay", attention


def prog_L13H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent dilution.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_mild_dilution", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.975 * np.exp(-0.0025 * (i - 1))
        sink_mass = np.clip(sink_mass, 0.75, 0.985)

        positions = np.arange(1, i + 1)
        residual = 0.6 + 0.4 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_mild_dilution", attention


def prog_L13H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakening with context length and clause boundaries.
    Residual attention is diffuse with a modest recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.95 - 0.0035 * i - 0.075 * np.log1p(i / 6.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("DET", "NOUN", "PROPN", "ADJ"):
                sink += 0.035
            elif word.pos_ in ("ADV", "CCONJ", "SCONJ", "PART"):
                sink -= 0.065
            elif word.pos_ == "VERB":
                sink -= 0.025

            if word.dep_ in ("ROOT", "advcl", "ccomp", "conj"):
                sink -= 0.035

            if word.is_punct:
                sink -= 0.10
                if word.text in (".", "!", "?", "..."):
                    sink -= 0.25
            elif word.is_space:
                sink -= 0.18

        if i == 1:
            sink = 0.965

        sink = float(np.clip(sink, 0.25, 0.98))
        attention[i, 0] = sink

        distance = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * np.exp(-distance / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_context_decay", attention


def prog_L13H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with decay; long-sentence terminal punctuation additionally
    pools recent nominal endpoints without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_terminal_pooling", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.40 + 0.55 * np.exp(-(i - 1) / 13.0)

        # Linguistic adjustments are deliberately weaker than the positional prior.
        correction = 0.0
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN"):
                correction = 0.025
            elif word.pos_ in ("VERB", "AUX"):
                correction = -0.035
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "PART"):
                correction = -0.020
            elif word.pos_ == "PUNCT":
                correction = 0.010

        sink_mass += correction * (1.0 - np.exp(-(i - 1) / 3.0))
        sink_mass = float(np.clip(sink_mass, 0.30, 0.97))

        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 7.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # A narrowly gated correction for the consistent long-sentence
        # ending failure: move only BOS mass, keeping the diagonal intact.
        if (
            n >= 30
            and i == n - 1
            and alignment[i]
            and doc[alignment[i][0]].pos_ == "PUNCT"
            and any(c in doc[alignment[i][0]].text for c in ".!?")
        ):
            targets = []
            for j in range(1, i):
                if not alignment[j]:
                    continue
                sid = alignment[j][-1]
                if (
                    doc[sid].pos_ in ("NOUN", "PROPN")
                    and sid not in alignment[j + 1]
                ):
                    targets.append(j)

            if targets:
                weights = np.exp(-(i - np.asarray(targets)) / 12.0)
                weights /= weights.sum()
                transfer = min(0.20, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, targets] += transfer * weights

    return "bos_sink_with_terminal_pooling", attention


def prog_L13H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing diffuse causal attention.
    Linguistic features weakly modulate the dominant positional pattern.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Non-sink mass grows with the available causal context.
        odds = 0.018 + 0.0065 * i + 0.00016 * i * i

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                odds *= 0.85
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "PUNCT"):
                odds *= 1.15

        sink_mass = 1.0 / (1.0 + odds)
        attention[i, 0] = sink_mass

        # The examples do not identify a reliable secondary target:
        # distribute residual mass broadly, with a weak recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 16.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L13H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a secondary, recency-biased focus on salient content.
    Punctuation and grammatical tokens shift more mass toward preceding content."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_content", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    salience = np.ones(n, dtype=np.float64)
    for j, word in enumerate(words):
        if word is None:
            salience[j] = 0.35
        elif word.pos_ in ("NOUN", "PROPN"):
            salience[j] = 2.8
        elif word.pos_ in ("ADJ", "VERB"):
            salience[j] = 1.7
        elif word.pos_ in ("ADV", "NUM", "PRON"):
            salience[j] = 1.0
        elif word.is_punct or word.is_space:
            salience[j] = 0.18
        else:
            salience[j] = 0.45

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        early = np.exp(-(i - 1) / 5.5)

        if word is None:
            sink = 0.56 + 0.32 * early
        elif word.pos_ in ("NOUN", "PROPN"):
            sink = 0.70 + 0.23 * early
        elif word.pos_ in ("ADJ", "VERB", "NUM"):
            sink = 0.60 + 0.30 * early
        elif word.is_punct:
            sink = 0.34 + 0.54 * early
        elif word.pos_ in ("CCONJ", "SCONJ", "DET", "ADP", "PART"):
            sink = 0.39 + 0.49 * early
        else:
            sink = 0.48 + 0.43 * early

        if (
            alignment[i]
            and alignment[i - 1]
            and alignment[i][0] == alignment[i - 1][0]
        ):
            sink = min(0.94, sink + 0.09)

        scores = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            distance = i - j
            scores[j] = salience[j] * (
                np.exp(-distance / 3.0)
                + 0.08 * np.exp(-distance / 18.0)
            )
            if j == i:
                scores[j] *= 0.24
            elif word is not None and words[j] is not None:
                if words[j].i == word.head.i and word.head.i != word.i:
                    scores[j] *= 1.35
                if word.is_punct and distance <= 2:
                    scores[j] *= 1.8

        attention[i, 0] = sink
        total = scores.sum()
        if total > 0:
            attention[i, :i + 1] += (1.0 - sink) * scores / total
        else:
            attention[i, 0] = 1.0

    return "bos_sink_with_local_content", make_row_stochastic(attention)


def prog_L13H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with persistent discourse-subject and dialogue anchors.
    Syntactic and short-range attention provide weaker, causal corrections.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, words in enumerate(alignment):
        for wi in words:
            if ti > 0:
                word_tokens[wi].append(ti)

    # Store anchors on the final subtoken of their nominal expression.
    anchors = []
    for word in doc:
        indices = word_tokens[word.i]
        if not indices or word.pos_ not in ("NOUN", "PROPN"):
            continue

        strength = 0.0
        if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
            strength = 1.0
            if word.sent.start > 0:
                strength = 2.1

        # A nominal immediately before quoted speech often remains salient
        # throughout the ensuing utterance.
        if word.dep_ in ("dobj", "obj", "iobj", "pobj", "attr", "appos"):
            for following in doc[word.i + 1:min(len(doc), word.i + 6)]:
                if following.is_punct:
                    if any(c in following.text for c in ('"', "“", "”", "«", "»")):
                        strength = max(strength, 1.6)
                        break
                elif following.pos_ in ("VERB", "AUX"):
                    break

        if strength > 0:
            anchors.append((indices[-1], strength))

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        # The sink is strongest at the beginning and remains a fallback
        # even after a discourse anchor becomes available.
        row = attention[i]
        row[:i + 1] = 0.62 / (i + 1)
        row[0] += 0.95 + 4.0 * np.exp(-max(i - 2, 0) / 11.0)
        row[i] += 0.28
        row[i - 1] += 0.18

        available = [(j, strength) for j, strength in anchors if j <= i]
        if available:
            latest = available[-1][0]
            for j, strength in available:
                distance = i - j
                if distance == 0:
                    row[j] += 0.38 * strength
                else:
                    persistence = np.exp(-distance / 65.0)
                    priority = 1.0 if j == latest else 0.24
                    maturation = 0.65 + 0.85 * (1.0 - np.exp(-distance / 5.0))
                    row[j] += strength * persistence * priority * maturation

        words = alignment[i]
        for wi in words:
            word = doc[wi]
            head_indices = word_tokens[word.head.i]
            earlier_head = [j for j in head_indices if j < i]
            if earlier_head:
                weight = 0.20
                if word.dep_ in ("amod", "acomp", "attr", "poss"):
                    weight = 0.48
                row[earlier_head[-1]] += weight / max(1, len(words))

            # Predicates can retrieve an explicitly expressed nominal subject.
            if word.pos_ in ("VERB", "AUX", "ADJ"):
                for child in word.children:
                    if child.dep_ in ("nsubj", "nsubjpass"):
                        subject_indices = [
                            j for j in word_tokens[child.i] if j < i
                        ]
                        if subject_indices:
                            row[subject_indices[-1]] += 0.55 / max(1, len(words))

        # Continuation pieces retain a small amount of within-word attention.
        if i > 1 and words and any(wi in alignment[i - 1] for wi in words):
            row[i - 1] += 0.16

    return (
        "bos_sink_with_discourse_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L13H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a decaying positional prior and punctuation boosts.
    Residual attention favors recent context, clause boundaries, and nominal anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_contextual_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    pos = [""] * n
    dep = [""] * n
    word_ids = [-1] * n
    punctuation = np.zeros(n, dtype=bool)
    boundaries = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        clean = token.replace("▁", " ").replace("Ġ", " ")
        whitespace[i] = not clean.strip() and token not in special_tokens
        punctuation[i] = (
            bool(clean.strip())
            and all(not c.isalnum() and not c.isspace() for c in clean)
            and token not in special_tokens
        )
        boundaries[i] = punctuation[i] and any(c in ".!?" for c in clean)

        if alignment[i]:
            k = alignment[i][0]
            word_ids[i] = k
            pos[i] = doc[k].pos_
            dep[i] = doc[k].dep_

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.23 + 0.69 * np.exp(-(i - 1) / 7.0)

        if pos[i] in ("NOUN", "PROPN", "ADJ"):
            sink += 0.07
        elif pos[i] == "VERB":
            sink += 0.025
        elif pos[i] in ("AUX", "ADP", "PART", "CCONJ", "SCONJ"):
            sink -= 0.035

        if punctuation[i]:
            sink += 0.15
        if boundaries[i]:
            sink += 0.06
        if whitespace[i]:
            sink = max(sink, 0.82)
        if token := (tokens[i] in special_tokens):
            sink = max(sink, 0.90)

        if i > 1 and word_ids[i] >= 0 and word_ids[i] == word_ids[i - 1]:
            sink += 0.045

        sink = float(np.clip(sink, 0.12, 0.97))

        indices = np.arange(1, i + 1)
        distance = i - indices
        residual = 0.30 + np.exp(-distance / 5.0)

        for offset, j in enumerate(indices):
            if boundaries[j]:
                residual[offset] += 2.5 * np.exp(-(i - j) / 24.0)
            elif punctuation[j]:
                residual[offset] += 0.35

            if pos[j] in ("NOUN", "PROPN"):
                residual[offset] += 0.35
                if dep[j] in ("dobj", "obj", "pobj", "attr"):
                    residual[offset] += 0.35

            if word_ids[i] >= 0 and word_ids[j] >= 0:
                if doc[word_ids[i]].head.i == word_ids[j] and j < i:
                    residual[offset] += 0.65

        if pos[i] == "PRON":
            for j in range(i - 1, 0, -1):
                if pos[j] in ("NOUN", "PROPN") and dep[j] in (
                    "dobj", "obj", "pobj", "attr"
                ):
                    residual[j - 1] += 2.5
                    break

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_contextual_residual", attention


def prog_L13H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Linguistic features weakly modulate sink strength; residual attention is local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.945 / (1.0 + 0.006 * i)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "PRON"):
                sink_mass += 0.015
            elif word.pos_ in ("DET", "CCONJ", "SCONJ", "PART"):
                sink_mass -= 0.025
            elif word.is_punct:
                sink_mass -= 0.035

        sink_mass = float(np.clip(sink_mass, 0.50, 0.97))

        # The observed edges strongly identify the sink, but do not determine
        # the remaining distribution; use a conservative causal recency prior.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.7 * np.exp(-distances / 4.0) + 0.3 / i
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L13H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a secondary self diagonal.
    Nominal complements and clause boundaries redirect some sink mass to prior syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Use the final subtoken as the anchor for each completed spaCy word.
    word_tokens = [[] for _ in doc]
    for ti, aligned_words in enumerate(alignment):
        for wi in aligned_words:
            if ti > 0:
                word_tokens[wi].append(ti)

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        punctuation = bool(surface) and all(
            not c.isalnum() and not c.isspace() for c in surface
        )

        sink = 0.28 + 0.43 * np.exp(-(i - 1) / 38.0)
        self_mass = 0.18 + 0.15 * (1.0 - np.exp(-i / 22.0))

        if pos in ("NOUN", "ADJ", "ADV", "ADP"):
            sink += 0.045
        elif pos in ("PRON", "PROPN"):
            sink -= 0.10
        elif pos in ("AUX", "CCONJ", "SCONJ"):
            sink -= 0.065
        elif pos == "VERB":
            sink -= 0.025

        if dep in ("nsubj", "nsubjpass") and i > 12:
            sink -= 0.035
            self_mass += 0.045

        if punctuation or pos == "PUNCT":
            sink -= 0.13
            self_mass += 0.12

        if not surface:
            sink += 0.04

        sink = float(np.clip(sink, 0.16, 0.82))
        self_mass = float(np.clip(self_mass, 0.12, 0.48))
        self_mass = min(self_mass, 0.96 - sink)

        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
            continue

        attention[i, 0] = sink
        attention[i, i] = self_mass

        previous = np.arange(1, i)
        background = (
            0.65 * np.exp(-(i - previous) / 7.0)
            + 0.35 / np.sqrt(i - previous)
        )
        background /= background.sum()
        attention[i, 1:i] = (1.0 - sink - self_mass) * background

        # Special case: completed nominal complements and clause-ending
        # punctuation retrieve earlier syntactic anchors, not just BOS.
        boundary = (
            word is not None
            and pos == "PUNCT"
            and any(c in surface for c in ",;:.!?")
        )
        nominal = (
            word is not None
            and pos in ("NOUN", "PROPN")
            and dep in ("pobj", "obj", "dobj", "attr", "appos", "nmod")
        )
        if boundary or nominal:
            anchors = np.zeros(i, dtype=np.float64)
            candidates = []
            if boundary:
                head = word.head
                candidates.append((head, 2.0))
                for child in head.children:
                    if child.dep_ in (
                        "nsubj", "nsubjpass", "obj", "dobj", "attr", "conj"
                    ):
                        candidates.append((child, 1.5))
            else:
                head = word.head
                candidates.append((head, 1.0))
                if head.pos_ == "ADP":
                    candidates.append((head.head, 2.0))
                for child in word.children:
                    if child.dep_ in ("det", "poss", "amod"):
                        candidates.append((child, 0.7))

            for anchor, weight in candidates:
                indices = word_tokens[anchor.i]
                if indices and 0 < indices[-1] < i:
                    anchors[indices[-1]] += weight

            if anchors.sum() > 0:
                moved = min(0.26 if boundary else 0.16, max(0.0, sink - 0.12))
                attention[i, 0] -= moved
                attention[i, :i] += moved * anchors / anchors.sum()

    return "bos_sink_with_syntactic_anchors", make_row_stochastic(attention)


def prog_L13H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakened in complements and dialogue.
    Residual attention favors recent content words and syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_contextual_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    word_ids = []
    for indices in alignment:
        word_ids.append(indices[-1] if indices else -1)

    positions = [[] for _ in doc]
    for i, wi in enumerate(word_ids):
        if wi >= 0:
            positions[wi].append(i)

    attention[0, 0] = 1.0
    inside_quote = False
    quote_anchor = -1
    last_boundary = 0

    for i in range(1, n):
        piece = tokens[i].replace("▁", " ").replace("Ġ", " ")
        clean = piece.strip()
        wi = word_ids[i]
        word = doc[wi] if wi >= 0 else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        quote_count = (
            piece.count('"') + piece.count("“") + piece.count("”")
        )
        closing_quote = inside_quote and quote_count % 2 == 1
        opening_quote = not inside_quote and quote_count % 2 == 1

        if opening_quote:
            quote_anchor = -1
            for j in range(i - 1, 0, -1):
                wj = word_ids[j]
                if wj >= 0 and doc[wj].pos_ in ("NOUN", "PROPN", "VERB"):
                    quote_anchor = j
                    break

        local_age = i - last_boundary
        logit = 0.90 + 1.10 * np.exp(-local_age / 5.0)
        logit -= 0.22 * np.log1p(i / 20.0)

        if pos in ("VERB", "AUX"):
            logit += 0.40
        if pos in ("ADJ", "ADV"):
            logit += 0.25
        if dep in ("ROOT", "nsubj", "nsubjpass"):
            logit += 0.35
        if dep in ("xcomp", "ccomp", "pcomp", "relcl", "acl"):
            logit -= 0.85
        if dep in ("dobj", "obj", "pobj", "iobj", "attr"):
            logit -= 0.40
        if pos in ("ADP", "PART"):
            logit -= 0.30
        if inside_quote and not closing_quote:
            logit -= 1.15

        if clean == ",":
            logit += 0.65
        elif clean and all(c in ".!?\"”’" for c in clean):
            logit += 0.20
        if closing_quote:
            logit += 0.80
        if not clean:
            logit += 0.85

        sink = float(np.clip(1.0 / (1.0 + np.exp(-logit)), 0.12, 0.97))
        if i == 1:
            sink = 0.94

        distances = i - np.arange(1, i + 1)
        residual = 0.25 + np.exp(-distances / 6.0)

        for j in range(1, i + 1):
            wj = word_ids[j]
            if wj < 0:
                continue
            candidate = doc[wj]
            if candidate.pos_ in ("NOUN", "PROPN", "VERB"):
                residual[j - 1] *= 1.6
            if candidate.dep_ in ("dobj", "obj", "pobj", "attr"):
                residual[j - 1] *= 1.3

        if word is not None:
            for j in positions[word.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 1.5

        if (inside_quote or opening_quote) and 0 < quote_anchor < i:
            residual[quote_anchor - 1] += 3.5

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        if quote_count % 2:
            inside_quote = not inside_quote
        if closing_quote or (
            clean and any(c in ".!?" for c in clean) and not inside_quote
        ):
            last_boundary = i

    return "bos_sink_with_contextual_residual", attention


def prog_L13H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and at punctuation boundaries.
    Standalone whitespace and apostrophes act as weaker, local secondary sinks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    whitespace = np.zeros(n, dtype=bool)
    apostrophe = np.zeros(n, dtype=bool)
    punctuation = np.zeros(n, dtype=bool)
    special = set(tokenizer.all_special_tokens)

    for i, token in enumerate(tokens):
        if token in special:
            continue
        clean = token.replace("▁", " ").replace("Ġ", " ")
        stripped = clean.strip()
        whitespace[i] = bool(clean) and not stripped
        apostrophe[i] = stripped in ("'", "’")
        punctuation[i] = bool(stripped) and all(
            c in ".,!?;:—–-…\"'“”‘’()[]{}" for c in stripped
        )

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.51 + 0.37 * np.exp(-(i - 1) / 3.4)

        sids = aligned[i]
        if sids:
            word = doc[sids[-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink += 0.055
            elif word.pos_ in ("DET", "ADP", "AUX", "CCONJ", "SCONJ", "PART"):
                sink -= 0.055
            if word.dep_ in ("nsubj", "nsubjpass") and i < 5:
                sink += 0.025

        if punctuation[i]:
            clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
            if any(c in ".!?" for c in clean):
                sink += 0.19
            else:
                sink += 0.025
        if whitespace[i]:
            sink += 0.20
        if apostrophe[i]:
            sink += 0.28

        anchors = []
        strengths = []
        for j in range(1, i):
            distance = i - j
            if whitespace[j] or apostrophe[j]:
                strength = (1.0 if whitespace[j] else 0.65)
                strength *= np.exp(-distance / 9.0)
                anchors.append(j)
                strengths.append(strength)

        anchor_strength = sum(strengths)
        sink -= 0.10 * min(1.0, anchor_strength)
        sink = float(np.clip(sink, 0.30, 0.93))
        attention[i, 0] = sink

        # Spread the unobserved residual causally, with a mild recency bias.
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        anchor_share = min(0.62, 0.65 * anchor_strength)
        attention[i, 1:i + 1] = (1.0 - sink) * (1.0 - anchor_share) * residual
        if anchor_strength > 0:
            for j, strength in zip(anchors, strengths):
                attention[i, j] += (
                    (1.0 - sink) * anchor_share * strength / anchor_strength
                )

    return "bos_sink_with_boundary_anchors", make_row_stochastic(attention)


def prog_L13H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a fading prefix bias and weaker attention to
    preceding nominal subjects and nearby context."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    positions = np.arange(n, dtype=np.float64)
    subject_strength = np.zeros(n, dtype=np.float64)

    # Divide a word's salience across its model-token pieces.
    coverage = np.zeros(len(doc), dtype=np.float64)
    for indices in alignment:
        for k in indices:
            coverage[k] += 1.0

    for j in range(1, n):
        for k in alignment[j]:
            word = doc[k]
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                if word.pos_ in ("NOUN", "PROPN"):
                    strength = 1.0
                elif word.pos_ == "PRON":
                    strength = 0.18
                else:
                    strength = 0.35
                subject_strength[j] += strength / max(coverage[k], 1.0)

    attention[0, 0] = 1.0
    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        pos = words[0].pos_ if words else ""

        sink = 0.54 + 0.40 * np.exp(-(i - 1) / 5.0)
        if pos in ("ADJ", "NOUN", "PROPN"):
            sink += 0.07
        elif pos in ("DET", "ADP", "PART"):
            sink -= 0.08
        elif pos in ("VERB", "AUX"):
            sink -= 0.03

        is_punctuation = (
            bool(words) and all(word.is_punct for word in words)
        )
        is_whitespace = (
            tokens[i].replace("▁", "").replace("Ġ", "").strip() == ""
        )
        if is_punctuation:
            sink += 0.12
        if is_whitespace:
            sink += 0.23

        sink = float(np.clip(sink, 0.32, 0.96))

        # Residual attention is broad unless a nominal subject is available.
        distance = i - positions[1:i + 1]
        residual = 0.35 + 0.65 * np.exp(-distance / 7.0)
        residual += (
            7.0
            * subject_strength[1:i + 1]
            * np.exp(-distance / 45.0)
        )
        residual[-1] *= 0.55

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_subject_residual", attention


def prog_L13H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse induction; quoted discourse additionally retrieves
    earlier nominal mentions and their continuations using only BOS mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    word_ids = []
    for i in range(n):
        if tokens[i] in special_tokens or not alignment[i]:
            word_ids.append(None)
        else:
            word_ids.append(alignment[i][0])

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The overwhelming default is the initial-token attention sink.
        sink_mass = 0.965 - 0.0012 * min(i, 80)
        if i == 1:
            sink_mass = 0.988

        wi = word_ids[i]
        if wi is not None and doc[wi].is_punct:
            sink_mass = min(0.975, sink_mass + 0.01)

        residual = 1.0 - sink_mass
        positions = np.arange(1, i + 1)
        local_weights = np.exp(-(i - positions) / 4.0)
        local_weights /= local_weights.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = residual * local_weights

        # A repeated preposition can act as an induction cue: attend to
        # the content token that followed its earlier occurrence.
        if wi is None or doc[wi].pos_ != "ADP":
            continue

        best_strength = 0.0
        best_target = None
        for j in range(1, i - 4):
            wj = word_ids[j]
            if wj is None or doc[wj].pos_ != "ADP":
                continue

            # Only compare the first model pieces of distinct spaCy words.
            if j > 1 and word_ids[j - 1] == wj:
                continue
            if i > 1 and word_ids[i - 1] == wi:
                continue

            k = j + 1
            while k < i and word_ids[k] == wj:
                k += 1
            if k >= i:
                continue

            wk = word_ids[k]
            if wk is None or doc[wk].pos_ not in ("NOUN", "PROPN"):
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            if similarity <= 0.94:
                continue

            strength = 0.82 * min(1.0, (similarity - 0.94) / 0.06)
            if strength > best_strength:
                best_strength = strength
                best_target = k

        if best_target is not None:
            attention[i] *= 1.0 - best_strength
            attention[i, best_target] += best_strength

    # The additional path is confined to discourse after a quotation begins.
    # Transfer BOS mass only: existing local and self-attention stay intact.
    pieces = [[] for _ in doc]
    for ti, wi in enumerate(word_ids):
        if wi is not None:
            pieces[wi].append(ti)

    quote_words = [
        w.i for w in doc
        if w.is_quote and any(c in w.text for c in '"“”')
    ]
    if quote_words:
        first_quote = min(quote_words)
        content_pos = ("NOUN", "PROPN", "VERB")
        for i in range(1, n):
            wi = word_ids[i]
            if wi is None or wi <= first_quote:
                continue

            word = doc[wi]
            targets = np.zeros(n, dtype=np.float64)
            anchor = None
            strength = 0.0

            # Repeated content retrieves the earlier word's final piece.
            # A determiner can retrieve an earlier nominal continuation.
            if word.pos_ in content_pos or word.pos_ == "DET":
                cue = i
                nominal_cue = word.pos_ == "DET"
                if nominal_cue and pieces[word.head.i]:
                    cue = pieces[word.head.i][0]

                best_similarity = 0.82
                for old in doc[:wi]:
                    if old.pos_ not in content_pos or not pieces[old.i]:
                        continue
                    if pieces[old.i][-1] >= i - 4:
                        continue
                    if nominal_cue and old.pos_ not in ("NOUN", "PROPN"):
                        continue
                    if not nominal_cue and (
                        (word.pos_ == "VERB") != (old.pos_ == "VERB")
                    ):
                        continue
                    similarity = embedding_similarity(
                        tokens, cue, pieces[old.i][0], tokenizer
                    )
                    if similarity > best_similarity:
                        best_similarity = similarity
                        anchor = old.i

                if anchor is not None:
                    strength = 0.58 if nominal_cue else 0.43
                    if i > 1 and word_ids[i - 1] == wi:
                        strength *= 0.55

            # Sentence-initial determiners also retrieve the earlier subject
            # frame, even when the new subject is a different participant.
            restart = (
                word.pos_ == "DET"
                and bool(word.is_sent_start)
            )
            if restart and anchor is None:
                for old in doc[:wi]:
                    if (
                        old.pos_ == "DET"
                        and old.head.pos_ in ("NOUN", "PROPN")
                        and pieces[old.head.i]
                        and pieces[old.head.i][-1] < i - 4
                    ):
                        anchor = old.head.i
                        strength = 0.65
                        break

            if anchor is not None:
                targets[pieces[anchor][-1]] += 0.55
                # Earlier continuations, including split-word endings, carry
                # the induction signal rather than a generic recency window.
                for offset, weight in ((1, 0.24), (2, 0.13), (3, 0.08)):
                    aw = anchor + offset
                    if aw < len(doc) and pieces[aw]:
                        target = pieces[aw][-1]
                        if target < i:
                            targets[target] += weight

                if word.pos_ == "VERB":
                    targets[pieces[anchor][-1]] *= 0.35

                # Nominal reintroduction can also reactivate the opening
                # discourse anchor, especially after a quoted utterance.
                if word.pos_ == "DET" or word.pos_ in ("NOUN", "PROPN"):
                    targets[1] += 0.30

                total = targets.sum()
                if total > 0:
                    mass = min(strength, attention[i, 0])
                    attention[i, 0] -= mass
                    attention[i] += mass * targets / total

    return (
        "bos_sink_with_dialogue_retrieval",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L13H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Linguistic salience mildly modulates the sink; residual attention is diffuse and local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        # The first token acts as a persistent sink, rather than a
        # syntactic target. More available context gradually dilutes it.
        sink_logit = -np.log(0.08) - 0.66 * np.log(float(i))

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_logit += 0.18
            elif word.pos_ == "VERB":
                sink_logit += 0.10
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ", "PART"):
                sink_logit -= 0.20
            if word.ent_type_:
                sink_logit += 0.06

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))

        # Allocate only the non-sink mass to ordinary causal context.
        positions = np.arange(1, i + 1)
        residual = 0.65 + 0.35 * np.exp(-(i - positions) / 12.0)

        if word is not None:
            head_index = word.head.i
            for j in range(1, i + 1):
                if head_index in alignment[j] and head_index != word.i:
                    residual[j - 1] *= 1.35

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_positional_decay", attention


def prog_L13H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly weakening positional dominance.
    Residual attention favors recent content words and causal syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if wi < len(doc):
                inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        sink = 0.95 - 0.29 * (1.0 - np.exp(-(i - 1) / 23.0))
        if word is not None:
            if word.dep_ in ("poss", "dobj", "obj", "pobj", "nsubj"):
                sink -= 0.07
            if word.pos_ in ("ADJ", "ADV", "AUX", "ADP"):
                sink += 0.025
            if word.dep_ in ("det", "cc"):
                sink -= 0.025
        sink = float(np.clip(sink, 0.48, 0.97))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 7.0)
        for j in range(1, i + 1):
            prior_words = alignment[j]
            if prior_words:
                prior = doc[prior_words[0]]
                if prior.pos_ in ("VERB", "NOUN", "PROPN"):
                    residual[j - 1] *= 1.8
                elif prior.is_punct:
                    residual[j - 1] *= 0.45

        if word is not None and word.head.i != word.i:
            head_tokens = [j for j in inverse[word.head.i] if 0 < j <= i]
            if head_tokens:
                for j in head_tokens:
                    residual[j - 1] += 2.5 / len(head_tokens)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_syntactic_residual", attention


def prog_L13H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional weakening and a secondary
    attraction to preceding sentence-ending punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    boundaries = []

    for i in range(1, n):
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        # Most queries overwhelmingly prefer the initial attention sink.
        sink = 0.57 + 0.35 * np.exp(-(i - 1) / 34.0)
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.045
            elif word.pos_ in ("PRON", "AUX", "CCONJ", "PART"):
                sink -= 0.045

        terminal = any(mark in clean for mark in (".", "?", "!"))
        if terminal:
            sink -= 0.22

        # Completed utterances can act as competing sinks, especially after
        # emphatic punctuation. Their influence fades over subsequent tokens.
        boundary_strength = 0.0
        boundary_index = None
        if boundaries:
            boundary_index, emphasis = boundaries[-1]
            distance = i - boundary_index
            boundary_strength = emphasis * np.exp(-distance / 20.0)
            sink -= 0.32 * boundary_strength

        sink = float(np.clip(sink, 0.25, 0.97))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        boundary_share = min(0.80, 0.90 * boundary_strength)
        attention[i, 1:i + 1] = (
            (1.0 - sink) * (1.0 - boundary_share) * residual
        )
        if boundary_index is not None:
            attention[i, boundary_index] += (1.0 - sink) * boundary_share

        if terminal:
            emphasis = 1.0 if "!" in clean else 0.45
            boundaries.append((i, emphasis))

    return "bos_sink_with_boundary_competition", make_row_stochastic(attention)


def prog_L13H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual contextual dilution.
    Residual attention favors recent context and earlier discourse boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    boundary_strength = np.zeros(n, dtype=np.float64)
    quote_marks = "\"“”‘’"
    special_tokens = tokenizer.all_special_tokens

    for j in range(1, n):
        surface = tokens[j].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[j]
        if surface and any(mark in surface for mark in quote_marks):
            boundary_strength[j] = 1.5
            # Narrative material immediately before quoted speech can act
            # as a retrieval anchor when the narrative resumes.
            for k in range(max(1, j - 4), j):
                for sid in alignment[k]:
                    if doc[sid].pos_ in ("NOUN", "PROPN"):
                        boundary_strength[k] = max(boundary_strength[k], 2.5)
        elif any(doc[sid].is_punct for sid in aligned):
            boundary_strength[j] = 0.6

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink_mass = 0.94 - 0.0065 * i
        if word is not None:
            if word.pos_ in ("ADJ", "NOUN", "PROPN"):
                sink_mass += 0.025
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.11
            elif word.dep_ in ("nsubj", "nsubjpass"):
                sink_mass -= 0.025

        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        if surface and any(mark in surface for mark in quote_marks):
            sink_mass -= 0.06
        if i == 1:
            sink_mass = 0.955
        sink_mass = float(np.clip(sink_mass, 0.35, 0.97))

        positions = np.arange(1, i + 1)
        residual = 0.3 + np.exp(-(i - positions) / 8.0)
        residual += boundary_strength[1:i + 1] * (
            1.0 - np.exp(-(i - positions) / 6.0)
        )
        for j in range(1, i + 1):
            if tokens[j] in special_tokens:
                residual[j - 1] *= 0.1

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_discourse_residual", attention


def prog_L13H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay.
    Residual attention favors recent nominal anchors and repeated concepts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = []
    for indices in alignment:
        words.append(doc[indices[0]] if indices else None)

    attention[0, 0] = 1.0
    nominal_positions = []

    for i in range(1, n):
        word = words[i]
        nominal = word is not None and word.pos_ in ("NOUN", "PROPN")
        scores = np.zeros(i + 1, dtype=np.float64)

        # A weak distributed background, with a mild recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        scores[1:] = 0.12 + np.exp(-(i - positions) / 7.0)
        scores[i] *= 0.55

        repeat_strength = 0.0
        for j in nominal_positions:
            distance = i - j
            anchor = words[j]
            salience = 1.0
            if anchor.dep_ in ("dobj", "obj", "pobj", "attr"):
                salience = 1.7
            scores[j] += salience * np.exp(-distance / 22.0)

            if word is not None and anchor.i != word.i:
                if word.head.i == anchor.i:
                    scores[j] += 2.5
                if nominal:
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    strength = max(0.0, (similarity - 0.55) / 0.45)
                    scores[j] += 12.0 * strength * strength
                    repeat_strength = max(repeat_strength, strength)

        sink = 0.988 * np.exp(-0.0042 * (i - 1))
        if word is not None:
            if word.pos_ in ("DET", "AUX", "PART"):
                sink += 0.012
            elif word.pos_ == "PRON" and i > 12:
                sink -= 0.035

        sink -= 0.26 * repeat_strength
        sink = float(np.clip(sink, 0.35, 0.996))
        if i == 1:
            sink = 0.993

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * scores[1:] / scores[1:].sum()
        )

        # Keep one representative model token per nominal spaCy token.
        if nominal:
            if not nominal_positions or words[nominal_positions[-1]].i != word.i:
                nominal_positions.append(i)

    return "bos_sink_with_nominal_residual", make_row_stochastic(attention)


def prog_L13H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually decreasing mass as context grows.
    Distribute the remaining attention diffusely over available non-BOS tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_context_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.975 / (1.0 + 0.014 * (i - 1))
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_sink_with_context_decay", attention


def prog_L13H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay and secondary attention
    to clause boundaries, early predicates, and plausible nominal antecedents."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    features = []
    boundaries = []

    for i, token in enumerate(tokens):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        features.append(word)

        text = token.replace("▁", " ").replace("Ġ", " ").strip()
        if token not in tokenizer.all_special_tokens:
            if any(mark in text for mark in (".", "!", "?")):
                if text and all(
                    c.isspace() or c in ".!?\"'”’»" for c in text
                ):
                    boundaries.append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = features[i]
        previous_boundaries = [j for j in boundaries if 0 < j < i]
        sink = 0.50 + 0.45 * np.exp(-(i - 1) / 18.0)

        if previous_boundaries:
            distance = i - previous_boundaries[-1]
            sink -= 0.20 * np.exp(-distance / 13.0)

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "DET"):
                sink += 0.035
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                sink -= 0.045

        sink = float(np.clip(sink, 0.28, 0.97))
        scores = np.zeros(i + 1, dtype=np.float64)

        for j in range(1, i + 1):
            distance = i - j
            key = features[j]
            scores[j] = 0.12 + 0.30 * np.exp(-distance / 6.0)

            if key is not None:
                if key.pos_ == "AUX":
                    scores[j] += 0.65 * np.exp(-j / 25.0)
                elif key.pos_ in ("NOUN", "PROPN"):
                    scores[j] += 0.20
                if key.dep_ == "ROOT":
                    scores[j] += 0.20

        for j in previous_boundaries:
            scores[j] += 6.0 * np.exp(-(i - j) / 18.0)

        if word is not None and word.pos_ == "PRON":
            candidates = [
                j for j in range(1, i)
                if features[j] is not None
                and features[j].pos_ in ("NOUN", "PROPN")
            ]
            if candidates:
                antecedent = candidates[-1]
                scores[antecedent] += 1.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * scores[1:] / scores[1:].sum()
        )

    return "bos_sink_with_boundary_competition", attention


def prog_L14H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening dominance over position.
    Residual attention is diffuse and mildly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.42 + 0.54 * np.exp(-(i - 1) / 27.0)

        # Linguistic effects are secondary to the positional sink.
        aligned = alignment[i]
        if aligned:
            pos = doc[aligned[0]].pos_
            if pos in ("NOUN", "PROPN"):
                sink_mass += 0.025
            elif pos in ("VERB", "AUX"):
                sink_mass -= 0.025
            elif pos == "PUNCT":
                sink_mass += 0.025

        sink_mass = float(np.clip(sink_mass, 0.35, 0.985))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L14H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: strong initial-token attention with gradual positional
    weakening, punctuation boosts, and a diffuse causal residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Position is the main predictor; linguistic effects are secondary.
        sink_mass = 0.58 + 0.37 * np.exp(-(i - 1) / 10.0)
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        if not surface:
            sink_mass += 0.18
        elif all(c in "'’`" for c in surface):
            sink_mass += 0.24
        elif all(not c.isalnum() for c in surface):
            if any(c in ".!" for c in surface):
                sink_mass += 0.20
            elif "," in surface:
                sink_mass += 0.04
            else:
                sink_mass += 0.06
        elif word is not None:
            if word.pos_ == "PROPN":
                sink_mass += 0.05
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.04

        sink_mass = float(np.clip(sink_mass, 0.35, 0.97))

        # The examples constrain the sink much more than the residual.
        # Spread the latter broadly, with only a weak recency preference.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L14H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a decaying prefix bias and secondary attention
    to recent content words, causal syntactic heads, and sentence boundaries."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    representatives = []

    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)
        representatives.append(
            next((doc[k] for k in indices if not doc[k].is_space), None)
        )

    content_pos = {"NOUN", "PROPN", "ADJ", "VERB"}
    linking_pos = {"PRON", "ADP", "CCONJ", "SCONJ", "DET"}
    boundaries = []
    for i, token in enumerate(tokens):
        if any(mark in token for mark in (".", "!", "?")):
            boundaries.append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = representatives[i]
        previous = representatives[i - 1]
        pos = word.pos_ if word is not None else ""
        clean = tokens[i].replace("▁", "").replace("Ġ", "")

        sink = 0.35 + 0.50 * np.exp(-(i - 1) / 4.5)

        if pos in {"NOUN", "PROPN", "ADJ"}:
            sink += 0.08
        if pos == "VERB":
            sink += 0.025
        if pos in {"DET", "ADP", "PRON", "CCONJ", "SCONJ"}:
            sink -= 0.035

        if not clean.strip():
            sink = max(sink, 0.84)
        elif clean in {"'", "’"}:
            sink = max(sink, 0.81)
        elif any(mark in clean for mark in (".", "!", "?")):
            sink = max(sink, 0.60)

        continuation = (
            word is not None
            and previous is not None
            and word.i == previous.i
        )
        if continuation:
            sink += 0.07

        local_anchor = (
            i > 1
            and previous is not None
            and previous.pos_ in {"NOUN", "PROPN", "ADJ"}
            and pos in linking_pos
            and not continuation
        )
        if local_anchor:
            sink -= 0.15

        sink = float(np.clip(sink, 0.17, 0.94))
        weights = np.zeros(i + 1, dtype=np.float64)

        for j in range(1, i + 1):
            distance = i - j
            key = representatives[j]
            weight = 0.12 * np.exp(-distance / 12.0)
            weight += 0.20 * np.exp(-distance / 2.5)
            if key is not None:
                if key.pos_ in content_pos:
                    weight += 0.65 / (1.0 + distance) ** 1.15
                if key.pos_ in {"NOUN", "PROPN", "ADJ"}:
                    weight += 0.25 * np.exp(-distance / 7.0)
                if key.is_punct:
                    weight *= 0.45
            if j == i:
                weight *= 0.45
            weights[j] = weight

        if local_anchor:
            weights[i - 1] += 2.2

        if word is not None:
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    weights[candidates[-1]] += 0.65

        earlier_boundaries = [j for j in boundaries if 0 < j < i]
        if earlier_boundaries:
            boundary = earlier_boundaries[-1]
            weights[boundary] += 1.4 * np.exp(-(i - boundary) / 18.0)

        total = weights.sum()
        if total > 0:
            attention[i, :i + 1] = (1.0 - sink) * weights / total
            attention[i, 0] = sink
        else:
            attention[i, 0] = 1.0

    return "bos_sink_with_content_anchors", make_row_stochastic(attention)


def prog_L14H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and weak local attention.
    Linguistic features modestly adjust sink strength, not its destination.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.81 - 0.004 * i
        if i == 1:
            sink = 0.87

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "ADJ":
                sink += 0.055
            elif word.pos_ in ("NOUN", "PROPN"):
                sink += 0.025
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink -= 0.055
            elif word.pos_ == "PUNCT":
                sink -= 0.045

        sink = float(np.clip(sink, 0.43, 0.92))

        # Distribute non-sink mass over self, recent tokens, and a weak
        # diffuse causal background. Keep this separate from the BOS mass.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.55 * np.exp(-(i - positions) / 3.0)
        residual[-1] += 0.65
        residual += 0.15 / i
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", attention


def prog_L14H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest early and on nominal tokens, with a
    weaker causal mixture of local context and syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = text.strip()
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""

        baseline = 0.66
        if pos in ("NOUN", "PROPN"):
            baseline = 0.79
        elif pos == "ADJ":
            baseline = 0.72
        elif pos in ("ADP", "DET"):
            baseline = 0.73
        elif pos in ("VERB", "AUX"):
            baseline = 0.58
        elif pos == "PRON":
            baseline = 0.56
        elif pos in ("ADV", "CCONJ", "SCONJ", "PART"):
            baseline = 0.62
        elif pos == "PUNCT":
            baseline = 0.65

        sink = baseline + (0.96 - baseline) * np.exp(-(i - 1) / 5.5)

        if not stripped:
            sink = max(sink, 0.81)
        elif all(c in "'’" for c in stripped):
            sink = max(sink, 0.90)
        elif all(not c.isalnum() for c in stripped):
            if any(c in "\"“”" for c in stripped):
                sink -= 0.12

        if i == 1:
            sink = 0.965
        sink = float(np.clip(sink, 0.30, 0.98))

        # Distribute the non-sink component over causally available context.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 7.0)
        residual /= residual.sum()

        if word is not None:
            anchors = [
                j for j in inverse[word.head.i]
                if 0 < j <= i
            ]
            if anchors and word.head.i != word.i:
                residual *= 0.80
                for j in anchors:
                    residual[j - 1] += 0.20 / len(anchors)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_linguistic_gating", make_row_stochastic(attention)


def prog_L14H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker causal, local content-anchor component.
    Sentence boundaries and early tokens strengthen the sink; syntax shapes the residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[ids[0]] if ids else None for ids in alignment]
    special = set(tokenizer.all_special_tokens)

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.56
        if pos in ("NOUN", "PROPN"):
            sink = 0.63
        elif pos in ("ADJ", "ADV"):
            sink = 0.60
        elif pos in ("VERB", "AUX"):
            sink = 0.53
        elif pos in ("PRON", "DET", "ADP", "PART"):
            sink = 0.51
        elif pos in ("CCONJ", "SCONJ"):
            sink = 0.65

        # The first few positions strongly prefer the initial attention sink.
        sink += 0.20 * np.exp(-(i - 1) / 2.5)

        if word is not None and word.is_sent_start:
            sink = max(sink, 0.76)
        if raw in special or not clean:
            sink = max(sink, 0.81)
        elif all(c in "'’`" for c in clean):
            sink = max(sink, 0.88)
        elif all(not c.isalnum() for c in clean):
            sink = max(sink, 0.66)
            if any(c in ".!?" for c in clean):
                sink = max(sink, 0.79)

        sink = float(np.clip(sink, 0.32, 0.93))
        residual = np.zeros(i + 1, dtype=np.float64)

        for j in range(1, i + 1):
            previous = words[j]
            distance = i - j
            weight = np.exp(-distance / 4.0)

            if previous is not None:
                if previous.pos_ in ("NOUN", "PROPN", "VERB"):
                    weight *= 1.8
                elif previous.is_punct:
                    weight *= 0.35

                if word is not None:
                    if previous.i == word.head.i and previous.i != word.i:
                        weight *= 2.0
                    if previous.i == word.i and j != i:
                        weight *= 1.3

            if j == i:
                weight *= 1.4 if pos in ("NOUN", "PROPN") else 0.75

            residual[j] = weight

        # Possessives, objects, and punctuation can retain a nearby predicate.
        if dep in ("poss", "dobj", "obj", "punct", "nsubj"):
            for j in range(i - 1, max(0, i - 7), -1):
                previous = words[j]
                if previous is not None and previous.pos_ == "VERB":
                    residual[j] *= 1.7
                    break

        total = residual.sum()
        attention[i, 0] = sink
        if total > 0:
            attention[i, :i + 1] += (1.0 - sink) * residual / total
        else:
            attention[i, i] += 1.0 - sink

    return "bos_sink_with_local_anchors", make_row_stochastic(attention)


def prog_L14H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink, gradually diluted by context.
    Residual attention is diffuse, with mild recency and syntactic-head preferences.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # The first position acts as an attention sink, not a linguistic antecedent.
    attention[0, 0] = 1.0
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}

    for i in range(1, n):
        positions = np.arange(1, i + 1)
        weights = 0.72 + 0.28 * np.exp(-(i - positions) / 12.0)

        query_heads = {
            doc[k].head.i
            for k in alignment[i]
            if k < len(doc)
        }

        for offset, j in enumerate(range(1, i + 1)):
            linguistic_tokens = [
                doc[k] for k in alignment[j] if k < len(doc)
            ]
            if any(w.pos_ in content_pos for w in linguistic_tokens):
                weights[offset] *= 1.12
            if any(w.is_punct for w in linguistic_tokens):
                weights[offset] *= 0.80
            if any(w.i in query_heads for w in linguistic_tokens):
                weights[offset] *= 1.30

        attention[i, 1:i + 1] = weights
        attention[i, 0] = 70.0 * np.exp(-i / 140.0)

    return (
        "bos_sink_with_context_dilution",
        make_row_stochastic(attention),
    )


def prog_L14H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weaker competition from completed-clause
    content anchors and sentence-ending punctuation, especially in dialogue.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    special_tokens = set(tokenizer.all_special_tokens)

    # Completed utterances can establish persistent non-BOS attention sinks.
    anchors = []
    last_boundary = 0
    for j in range(1, n):
        text = tokens[j].replace("▁", "").replace("Ġ", "").strip()
        if tokens[j] in special_tokens:
            continue
        if not any(mark in text for mark in ("?", "!", ".")):
            continue
        if words[j] is not None and not words[j].is_punct:
            continue

        candidates = []
        for k in range(max(1, last_boundary + 1), j):
            word = words[k]
            if word is not None and word.pos_ in ("NOUN", "PROPN"):
                strength = 1.0
                if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                    strength += 0.6
                strength += 0.4 * (k / max(j, 1))
                candidates.append((strength, k))
        if candidates:
            _, key = max(candidates)
            anchors.append((key, j, 1.0))

        quoted_end = any(mark in text for mark in ('"', "”", "»"))
        if quoted_end or "!" in text or "?" in text:
            anchors.append((j, j, 0.85))
        last_boundary = j

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        position = np.arange(1, i + 1, dtype=np.float64)
        background = np.exp(-(i - position) / 9.0)
        background /= background.sum()

        sink = 0.95 - 0.0025 * min(i, 70)
        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink -= 0.09
            if word.dep_ in ("ROOT", "advcl", "ccomp", "conj"):
                sink -= 0.045
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.015
        if tokens[i] in special_tokens:
            sink = 0.97
        sink = float(np.clip(sink, 0.62, 0.98))

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

        for key, boundary, strength in anchors:
            distance = i - boundary
            if distance <= 0:
                continue
            persistence = np.exp(-distance / 38.0)
            onset = 1.0 - np.exp(-distance / 2.0)
            competition = 0.55 * strength * persistence * onset
            if word is not None and word.pos_ in ("PROPN", "PUNCT"):
                competition *= 0.55
            attention[i, key] += competition

    return (
        "bos_sink_with_clause_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L14H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent leakage to recent context.
    Sentence boundaries and nearby syntactic governors receive secondary mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_leakage", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    representatives = []
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        representatives.append(doc[indices[0]] if indices else None)
        for k in indices:
            inverse[k].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    terminal_indices = []
    for i, token in enumerate(tokens):
        if token not in special_tokens and any(c in token for c in ".!?"):
            terminal_indices.append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = representatives[i]

        # An exceptionally strong sink at the beginning, persisting throughout.
        sink = 0.56 + 0.426 * np.exp(-(i - 1) / 10.0)
        if word is not None:
            if word.pos_ == "PRON" and i > 3:
                sink -= 0.065
            if word.dep_ in ("poss", "nmod:poss"):
                sink -= 0.075

        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        if not clean.strip() and tokens[i] not in special_tokens:
            sink = max(sink, 0.90)

        previous_boundaries = [j for j in terminal_indices if 0 < j < i]
        boundary = previous_boundaries[-1] if previous_boundaries else None
        if boundary is not None:
            sink -= 0.10 * np.exp(-(i - boundary) / 12.0)

        sink = float(np.clip(sink, 0.30, 0.995))

        # Spread residual attention causally, with a local-context preference.
        positions = np.arange(1, i + 1)
        residual = 0.08 + np.exp(-(i - positions) / 4.0)
        residual[-1] *= 0.65

        if boundary is not None:
            residual[boundary - 1] += 3.0 * np.exp(
                -(i - boundary) / 24.0
            )

        if word is not None and word.head.i != word.i:
            governor_tokens = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if governor_tokens:
                residual[governor_tokens[-1] - 1] += 0.65

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_context_leakage", attention


def prog_L14H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant BOS sink, with weaker local attention and competition from
    recent sentence-ending punctuation, especially across discourse boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    last_boundary = None
    last_comma = None

    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        word = max(words, key=lambda w: len(w.text)) if words else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Strong initial sink; later tokens have more non-sink alternatives.
        log_odds = 4.5 - 0.085 * min(i, 38)
        if pos in ("ADJ", "ADP", "DET", "NUM"):
            log_odds += 0.25
        if pos in ("VERB", "AUX", "PRON") and i > 5:
            log_odds -= 0.55
        if dep in ("ROOT", "conj", "ccomp", "advcl") and i > 6:
            log_odds -= 0.30
        if text and all(c in ",;:.!?\"'“”‘’" for c in text):
            log_odds -= 0.50
        if not text or tokens[i] in special:
            log_odds += 0.35

        boundary_strength = 0.0
        if last_boundary is not None:
            distance = i - last_boundary
            boundary_strength = 2.2 * np.exp(-distance / 13.0)
            log_odds -= boundary_strength
        if last_comma is not None and i - last_comma <= 5:
            log_odds -= 0.25

        sink_mass = float(np.clip(
            1.0 / (1.0 + np.exp(-log_odds)), 0.18, 0.998
        ))

        # Allocate the remaining mass causally, favoring nearby context.
        indices = np.arange(1, i + 1)
        residual = np.exp(-(i - indices) / 4.0)
        residual[-1] *= 0.65
        if last_boundary is not None:
            residual[last_boundary - 1] += (
                3.5 * boundary_strength * residual.sum()
            )
        residual /= residual.sum()
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Update only after predicting this row: punctuation is a future anchor.
        if any(c in ".!?" for c in text):
            last_boundary = i
        if any(c in ",;:" for c in text):
            last_comma = i

    return "bos_sink_with_boundary_competition", attention


def prog_L14H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with selective retrieval of repeated entities and
    weaker routing to nearby subjects or pronoun antecedents."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_entity_retrieval", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    # First and last subpieces serve different roles: lexical repetition
    # favors word starts, while reference resolution often favors word ends.
    starts = {}
    ends = {}
    for word in doc:
        pieces = [
            k for k in inverse[word.i]
            if k > 0 and tokens[k] not in special
        ]
        if pieces:
            starts[word.i] = min(pieces)
            ends[word.i] = max(pieces)

    attention[0, 0] = 1.0
    for i in range(1, n):
        row = attention[i]
        row[0] = 0.95
        row[1:i + 1] = 0.05 / i

        if tokens[i] in special or not aligned[i]:
            continue

        word = doc[aligned[i][0]]
        pos = word.pos_
        candidates = {}

        # Most ordinary tokens remain nearly entirely on the sink.
        # Predicates and anaphoric expressions have more structured tails.
        sink = 0.94
        if pos in ("VERB", "AUX"):
            sink = 0.78
        elif pos in ("PRON", "CCONJ", "SCONJ"):
            sink = 0.82
        elif pos == "PUNCT":
            sink = 0.86

        if pos in ("NOUN", "PROPN", "VERB", "ADJ"):
            best_score = 0.0
            best_target = None
            current_start = starts.get(word.i, i)

            for previous in doc[:word.i]:
                if previous.i not in starts:
                    continue
                if previous.pos_ != pos:
                    continue
                j = starts[previous.i]
                if j >= current_start:
                    continue

                similarity = embedding_similarity(
                    tokens, current_start, j, tokenizer
                )
                strength = np.clip((similarity - 0.66) / 0.34, 0.0, 1.0)
                strength *= np.exp(-(i - j) / 180.0)
                if strength > best_score:
                    best_score = strength
                    best_target = j

            if best_target is not None and best_score > 0.0:
                maximum = 0.93 if pos == "PROPN" else 0.78
                if pos == "NOUN" and word.tag_ in ("NNS", "NNPS"):
                    maximum = 0.50
                elif pos in ("VERB", "ADJ"):
                    maximum = 0.42
                candidates[best_target] = maximum * best_score

        # Subject links provide a modest correction, rather than replacing
        # the strong default attention sink.
        if pos in ("VERB", "AUX"):
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    j = ends.get(child.i)
                    if j is not None and 0 < j < i:
                        mass = 0.32 if child.pos_ == "PROPN" else 0.18
                        candidates[j] = max(candidates.get(j, 0.0), mass)

        if pos == "PRON":
            best_score = 0.0
            best_target = None
            for previous in doc[:word.i]:
                if previous.pos_ not in ("NOUN", "PROPN"):
                    continue
                j = ends.get(previous.i)
                if j is None or j >= i:
                    continue
                score = np.exp(-(i - j) / 22.0)
                if previous.dep_ in ("nsubj", "nsubjpass"):
                    score *= 1.25
                if previous.ent_type_:
                    score *= 1.10
                if score > best_score:
                    best_score, best_target = score, j

            if best_target is not None:
                candidates[best_target] = min(0.56, 0.48 * best_score)

        if candidates:
            total = sum(candidates.values())
            scale = min(1.0, 0.94 / total)
            retrieval_mass = total * scale
            row[:] = 0.0
            row[0] = max(0.04, 1.0 - retrieval_mass - 0.025)
            row[1:i + 1] = 0.025 / i
            for j, mass in candidates.items():
                row[j] += mass * scale
        else:
            row[:] = 0.0
            row[0] = sink
            row[1:i + 1] = (1.0 - sink) / i

    return (
        "bos_sink_entity_retrieval",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L14H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with a weaker
    recency- and syntax-sensitive residual over preceding tokens."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        source_ids = alignment[i]
        source = doc[source_ids[-1]] if source_ids else None

        # The dominant feature is position, not a particular lexical relation.
        sink = 0.70 + 0.28 * np.exp(-(i - 1) / 8.0)

        if source is not None:
            correction = 0.0
            if source.pos_ in ("VERB", "AUX"):
                correction -= 0.075
            elif source.pos_ in ("NOUN", "PROPN", "NUM"):
                correction += 0.045
            elif source.pos_ in ("DET", "ADP"):
                correction += 0.025
            if source.dep_ in ("ROOT", "ccomp", "xcomp"):
                correction -= 0.045
            if source.ent_type_:
                correction += 0.025
            # Early rows remain almost entirely absorbed by the sink.
            sink += (1.0 - np.exp(-(i - 1) / 5.0)) * correction

        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if surface and all(c in "\"“”«»" for c in surface):
            sink -= 0.12 * (1.0 - np.exp(-(i - 1) / 5.0))

        sink = float(np.clip(sink, 0.35, 0.99))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.20 + np.exp(-(i - positions) / 4.0)

        if source is not None:
            for j in range(1, i + 1):
                target_ids = alignment[j]
                if not target_ids:
                    continue
                target = doc[target_ids[-1]]
                if target.pos_ in ("NOUN", "PROPN", "PRON"):
                    residual[j - 1] *= 1.25
                if target.i == source.head.i and target.i != source.i:
                    residual[j - 1] *= 2.0
                if target.pos_ == "PUNCT":
                    residual[j - 1] *= 0.65

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_residual", attention


def prog_L14H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent weakening.
    Residual attention favors recent content and preceding sentence boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    features = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "NUM"}
    sink_factors = {
        "NOUN": 1.20,
        "PROPN": 1.45,
        "ADJ": 1.20,
        "VERB": 0.95,
        "ADV": 0.95,
        "AUX": 0.75,
        "PRON": 0.75,
        "DET": 0.85,
        "ADP": 0.90,
        "CCONJ": 0.70,
        "SCONJ": 0.75,
    }
    boundaries = np.zeros(n, dtype=bool)
    for j in range(1, n):
        boundaries[j] = any(c in ".!?" for c in tokens[j])

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = features[i]
        factor = sink_factors.get(word.pos_, 1.0) if word is not None else 1.0

        # Fragmented words receive a somewhat weaker sink prior.
        if (
            i > 1
            and alignment[i]
            and alignment[i - 1]
            and alignment[i][0] == alignment[i - 1][0]
        ):
            factor *= 0.85

        if tokens[i].isspace() or tokens[i] == "▁":
            factor *= 1.5

        odds = 28.0 * factor / (float(i) ** 0.98)
        sink_mass = odds / (1.0 + odds)
        attention[i, 0] = sink_mass

        weights = np.zeros(i, dtype=np.float64)
        for j in range(1, i + 1):
            previous = features[j]
            salience = 1.0
            if previous is not None:
                if previous.pos_ in content_pos:
                    salience = 2.0
                elif previous.pos_ == "PUNCT":
                    salience = 0.7
            if boundaries[j]:
                salience += 8.0
            weights[j - 1] = salience * np.exp(-0.035 * (i - j))

        # Give the latest completed sentence boundary additional prominence.
        earlier_boundaries = np.flatnonzero(boundaries[:i])
        if len(earlier_boundaries):
            boundary = int(earlier_boundaries[-1])
            weights[boundary - 1] += (
                0.35 * weights.sum() * np.exp(-0.025 * (i - boundary))
            )

        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * weights / weights.sum()
        )

    return "bos_sink_with_boundary_residual", attention


def prog_L14H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a secondary initial-determiner sink.
    Punctuation and sentence restarts selectively strengthen the secondary sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, :i + 1] = 1.0
        attention[i, 0] = 4000.0
        attention[i] /= attention[i].sum()

    doc = spacy_parse(sentence)
    if n > 1 and len(doc) and doc[0].pos_ == "DET":
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        if 0 in aligned[1]:
            for i in range(1, n):
                text = tokens[i].replace("▁", "").replace("Ġ", "").strip()
                words = [doc[k] for k in aligned[i]]
                mass = 0.002

                if i == 1:
                    mass = 0.110 - attention[i, 1]
                elif not text:
                    previous = tokens[i - 1]
                    mass = 0.190 if "?" in previous else 0.012
                elif text == ".":
                    mass = min(0.070, 0.033 + 0.001 * max(0, i - 20))
                elif text in ("'", "’"):
                    mass = 0.026
                elif any(c in text for c in ("!", "?")):
                    mass = 0.020
                elif text in (",", ";", ":"):
                    mass = 0.020
                elif any(w.pos_ == "DET" and w.is_sent_start for w in words):
                    mass = 0.050
                elif i == 2 and any(w.pos_ in ("NOUN", "PROPN") for w in words):
                    mass = 0.014
                elif any(w.pos_ == "ADJ" for w in words):
                    mass = 0.008

                # Transfer only BOS mass; all other background weights stay intact.
                mass = min(max(0.0, mass), attention[i, 0])
                attention[i, 0] -= mass
                attention[i, 1] += mass

    return "bos_sink_with_initial_determiner_sink", attention


def prog_L14H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant BOS attention sink, weakening with position.
    Residual attention favors recent tokens and nearby syntactic context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Strong early sink; progressively more competition from context.
        sink = 0.985 - 0.36 * (1.0 - np.exp(-(i - 1) / 22.0))
        indices = alignment[i]
        word = None
        if indices:
            word = doc[indices[0]]

        maturity = 1.0 - np.exp(-(i - 1) / 8.0)
        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink -= 0.075 * maturity
            elif word.pos_ in ("ADJ", "ADV", "PROPN"):
                sink += 0.035 * maturity
            elif word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ"):
                sink -= 0.025 * maturity

        # Whitespace and sentence-ending punctuation often retain the sink.
        if tokens[i].replace("▁", "").replace("Ġ", "").isspace():
            sink += 0.08
        if not tokens[i].replace("▁", "").replace("Ġ", ""):
            sink += 0.08
        if word is not None and word.is_punct:
            if any(c in word.text for c in ".!?"):
                sink = max(sink, 0.83)
            elif any(c in word.text for c in "\"“”"):
                sink -= 0.08 * maturity

        sink = float(np.clip(sink, 0.48, 0.995))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.12 + np.exp(-(i - positions) / 4.0)
        residual[-1] *= 0.45

        # Only past syntactic relations can receive the residual mass.
        for k in indices:
            current = doc[k]
            for j in inverse[current.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.8
            for child in current.children:
                for j in inverse[child.i]:
                    if 0 < j < i:
                        residual[j - 1] += 0.35
            for j in inverse[k]:
                if 0 < j < i:
                    residual[j - 1] += 0.5

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_context", attention


def prog_L14H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal context routing.
    Longer contexts permit more residual attention to syntactic and semantic echoes.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_contextual_echo", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}

    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = 0.15 + np.exp(-(i - positions) / 6.0)
        current = alignment[i]
        semantic_strength = 0.0

        # Small syntactic corrections distribute the non-sink mass.
        for k in current:
            word = doc[k]
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 1.5
            for child in word.children:
                for j in inverse[child.i]:
                    if 0 < j <= i:
                        residual[j - 1] += 0.5

        # A weak echo channel becomes relevant only in longer contexts.
        if i > 24 and any(doc[k].pos_ in content_pos for k in current):
            for j in range(1, i - 3):
                if not any(doc[k].pos_ in content_pos for k in alignment[j]):
                    continue
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                strength = max(0.0, (similarity - 0.55) / 0.45)
                if strength > 0.0:
                    residual[j - 1] += 4.0 * strength
                    semantic_strength = max(semantic_strength, strength)

        # The dominant observation is near-universal attention to position zero.
        # Length and strong semantic recurrence soften, rather than replace, it.
        excess = max(0, i - 24)
        residual_mass = (
            0.014
            + 0.12 * (1.0 - np.exp(-excess / 35.0))
            + 0.18 * semantic_strength
        )
        if i == 1:
            residual_mass = 0.003

        attention[i, 0] = 1.0 - residual_mass
        attention[i, 1:i + 1] = residual_mass * residual / residual.sum()

    return "bos_sink_with_contextual_echo", make_row_stochastic(attention)


def prog_L14H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent dilution and small linguistic corrections.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # An approximately fixed-strength sink competes with an expanding
        # causal context, so its normalized weight decreases with position.
        log_odds = 3.65 - 1.05 * np.log(float(i))

        indices = aligned[i]
        if indices:
            word = doc[indices[0]]
            if word.pos_ == "PROPN":
                log_odds += 0.22
            elif word.pos_ in ("DET", "ADP", "PART"):
                log_odds -= 0.25
            elif word.pos_ in ("CCONJ", "SCONJ"):
                log_odds -= 0.30
            elif word.pos_ in ("VERB", "AUX"):
                log_odds += 0.08

            if word.dep_ in ("nsubj", "nsubjpass") and i <= 4:
                log_odds += 0.15

        piece = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = piece.strip()
        if not stripped:
            log_odds += 0.90
        elif all(c in "'’" for c in stripped):
            log_odds += 0.85
        elif all(not c.isalnum() for c in stripped):
            log_odds += 0.12

        sink_mass = 1.0 / (1.0 + np.exp(-log_odds))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 8.0)
        recency /= recency.sum()
        residual = 0.80 / i + 0.20 * recency
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", make_row_stochastic(attention)


def prog_L14H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with weaker local and
    syntactic attention in the remaining probability mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    representatives = [None] * n
    word_to_pieces = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            if 0 <= word_id < len(doc):
                word_to_pieces[word_id].append(i)
        if word_ids:
            representatives[i] = doc[word_ids[-1]]

    baseline = {
        "NOUN": 0.61,
        "PROPN": 0.65,
        "VERB": 0.66,
        "AUX": 0.59,
        "ADJ": 0.51,
        "ADV": 0.47,
        "PRON": 0.34,
        "DET": 0.41,
        "ADP": 0.45,
        "PART": 0.43,
        "CCONJ": 0.61,
        "SCONJ": 0.47,
        "NUM": 0.53,
        "PUNCT": 0.68,
        "SPACE": 0.60,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = representatives[i]
        pos = word.pos_ if word is not None else ""
        base = baseline.get(pos, 0.57)
        surface = tokens[i].lstrip("▁Ġ")

        if surface and all(c in ".!?" for c in surface):
            base = 0.82
        elif surface and all(c in ".!?\"'“”‘’" for c in surface):
            base = 0.74

        sink = base + (0.977 - base) * np.exp(-(i - 1) / 4.5)
        sink = float(np.clip(sink, 0.28, 0.99))

        # Distribute non-sink mass over causal, mostly nearby content.
        positions = np.arange(1, i + 1)
        weights = 0.10 + np.exp(-(i - positions) / 3.0)
        weights[-1] *= 0.45

        if word is not None:
            head_pieces = word_to_pieces[word.head.i]
            preceding_heads = [j for j in head_pieces if 0 < j < i]
            if preceding_heads and word.head.i != word.i:
                weights[preceding_heads[-1] - 1] += 1.5

            # Multi-piece words share a contextual target rather than
            # attending exclusively to their own preceding subword.
            if pos in ("ADJ", "NOUN", "PROPN", "PRON"):
                for j in range(i - 1, max(0, i - 7), -1):
                    previous = representatives[j]
                    if previous is None or previous.i == word.i:
                        continue
                    if previous.pos_ == "ADP":
                        weights[j - 1] += 1.8
                        break

            if pos == "PRON":
                for j in range(i - 1, max(0, i - 6), -1):
                    previous = representatives[j]
                    if previous is not None and previous.pos_ == "VERB":
                        weights[j - 1] += 1.2
                        break

        if not surface and i > 1:
            weights[-2] += 2.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_local_syntax", attention


def prog_L14H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntactic attachment.
    Split nominal words retain attention within their preceding noun-phrase context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_split_nominal_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        anchor = None
        sink = 0.78

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("VERB", "AUX"):
                sink = 0.81
            elif pos in ("NOUN", "PROPN"):
                sink = 0.55
            elif pos == "ADJ":
                sink = 0.61
            elif pos == "DET":
                sink = 0.67
            elif pos == "ADP":
                sink = 0.72
            elif pos == "PRON":
                sink = 0.73
            elif pos == "ADV":
                sink = 0.74
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.79
            elif pos == "PUNCT":
                sink = 0.82

            if dep in ("nsubj", "nsubjpass", "csubj", "expl"):
                sink = max(sink, 0.74)

            # A modifier can inherit the attachment of its entire noun phrase.
            governor = word.head
            if dep in ("amod", "det", "poss", "compound", "nummod"):
                if governor.head.i != governor.i:
                    governor = governor.head

            candidates = [
                j for j in inverse[governor.i]
                if 0 < j < i and governor.i != word.i
            ]
            if candidates:
                anchor = candidates[-1]
                if governor.pos_ == "ADP" and pos in (
                    "NOUN", "PROPN", "ADJ", "DET", "PRON"
                ):
                    sink = min(sink, 0.44)
                elif dep in ("dobj", "obj", "pobj", "attr", "oprd"):
                    sink = min(sink, 0.49)

            # Commas can close a phrase by attending to its final content word.
            if pos == "PUNCT" and word.text in (",", ";", ":"):
                previous = doc[word.i - 1] if word.i > 0 else None
                if previous is not None and previous.pos_ in ("NOUN", "PROPN"):
                    preceding = [j for j in inverse[previous.i] if 0 < j < i]
                    if preceding:
                        anchor = preceding[-1]
                        sink = 0.34

        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        if not clean.strip() or tokens[i] in tokenizer.all_special_tokens:
            sink = 0.86

        # Early positions are especially dominated by the attention sink.
        if i == 1:
            sink = 0.89
        elif i <= 3:
            sink = max(sink, 0.80)

        attention[i, 0] = sink
        remaining = 1.0 - sink
        if anchor is not None:
            attention[i, anchor] += remaining * 0.72
            attention[i, i - 1] += remaining * 0.20
            attention[i, i] += remaining * 0.08
        else:
            attention[i, i - 1] += remaining * 0.72
            attention[i, i] += remaining * 0.18
            if i > 1:
                attention[i, 1:i] += remaining * 0.10 / (i - 1)
            else:
                attention[i, 0] += remaining * 0.10

        # Narrow exception: fragmented nouns should not repeatedly attach
        # every subtoken to an external governor. Preserve self-attention
        # and all original background/previous-token contributions.
        if (
            word is not None
            and word.pos_ in ("NOUN", "PROPN")
            and len(inverse[word.i]) > 1
            and i > 3
            and clean.strip()
            and tokens[i] not in tokenizer.all_special_tokens
        ):
            phrase_words = [word.i] + [
                child.i for child in word.children
                if child.i < word.i
                and child.dep_ in ("det", "poss", "amod", "compound", "nummod")
            ]
            prefix = sorted({
                j for k in phrase_words for j in inverse[k]
                if 0 < j < i
            })
            source = None
            moved = 0.0
            if prefix and anchor is not None and anchor not in prefix:
                source = anchor
                moved = remaining * 0.72 * 0.85
            elif prefix and anchor is None and word.dep_ in ("nsubj", "nsubjpass"):
                source = 0
                moved = min(0.28, attention[i, 0])

            if source is not None:
                weights = 1.0 / (i - np.asarray(prefix, dtype=np.float64))
                weights /= weights.sum()
                attention[i, source] -= moved
                attention[i, prefix] += moved * weights

    return "bos_sink_with_split_nominal_context", make_row_stochastic(attention)


def prog_L14H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Residual attention favors nearby tokens and preceding syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        # A fixed sink receives most attention; its share decreases slowly
        # as additional usable context accumulates.
        sink = 0.88 - 0.075 * np.log1p(i / 3.0)

        if word is not None:
            if word.pos_ in ("DET", "AUX", "CCONJ", "SCONJ", "ADP", "PART"):
                sink += 0.045
            elif word.pos_ in ("ADJ", "ADV"):
                sink += 0.025
            elif word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.075
            elif word.pos_ == "VERB":
                sink -= 0.035

            if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink -= 0.055

        if tokens[i].isspace():
            sink += 0.10

        if i == 1:
            sink = 0.94

        sink = float(np.clip(sink, 0.40, 0.96))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual[-1] *= 0.55

        # Allocate some non-sink mass to a syntactic governor when it
        # precedes the query. No future parse links become attention edges.
        if word is not None and word.head.i != word.i:
            candidates = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if candidates:
                target = candidates[-1]
                strength = 1.5
                if word.dep_ in ("pobj", "obj", "dobj"):
                    strength = 3.0
                residual[target - 1] += strength

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_syntax", attention


def prog_L14H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong prefix prior and punctuation/clause boosts.
    Residual attention spreads over earlier content words and syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[-1]] if indices else None
        for indices in alignment
    ]

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()

        prefix = np.exp(-(i - 1) / 4.0)
        correction = 0.0

        if pos in ("VERB", "AUX"):
            correction += 0.12
        elif pos == "ADJ":
            correction += 0.09
        elif pos == "ADP":
            correction -= 0.12
        elif pos == "DET":
            correction -= 0.09
        elif pos in ("NOUN", "PROPN"):
            correction -= 0.035

        if dep in ("acomp", "attr", "ROOT"):
            correction += 0.07
        if dep in ("dobj", "obj", "pobj"):
            correction -= 0.05

        if not surface:
            correction += 0.24
        elif all(not c.isalnum() for c in surface):
            correction += 0.22

        sink = 0.39 + 0.56 * prefix + (1.0 - prefix) * correction
        sink = float(np.clip(sink, 0.16, 0.97))

        indices = np.arange(1, i + 1)
        weights = np.exp(-(i - indices) / 12.0)

        for k, j in enumerate(range(1, i + 1)):
            key = words[j]
            if key is None:
                weights[k] *= 0.65
                continue

            if key.pos_ in ("NOUN", "PROPN"):
                weights[k] *= 1.7
            elif key.pos_ == "VERB":
                weights[k] *= 1.4
            elif key.pos_ in ("PUNCT", "SPACE", "DET"):
                weights[k] *= 0.55

            if word is not None:
                if word.head.i == key.i and word.i != key.i:
                    weights[k] *= 1.6
                if pos in ("DET", "PRON") and key.pos_ in ("NOUN", "PROPN"):
                    weights[k] *= 1.35

            if j == i:
                weights[k] *= 0.65

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_linguistic_residual", attention


def prog_L14H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with content gating; quoted discourse additionally favors BOS
    and preceding sentence-boundary anchors, without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    dialogue_seen = False
    boundary = None

    for i in range(1, n):
        aligned = alignment[i]
        word = None
        if aligned:
            word = max(
                (doc[k] for k in aligned),
                key=lambda w: (
                    not w.is_space,
                    not w.is_punct,
                    len(w.text),
                ),
            )

        # A persistent sink with an additional strong beginning-of-sequence bias.
        sink = 0.35 + 0.39 * np.exp(-(i - 1) / 4.5)

        if word is not None:
            pos = word.pos_
            if pos == "PROPN":
                sink += 0.25
            elif pos == "NOUN":
                sink += 0.21
            elif pos == "ADJ":
                sink += 0.13
            elif pos in ("VERB", "AUX"):
                sink += 0.035
            elif pos == "PRON":
                sink -= 0.055
            elif pos in ("CCONJ", "SCONJ", "PART"):
                sink -= 0.045
            elif pos == "PUNCT":
                sink -= 0.025

            if word.ent_type_:
                sink += 0.035
            if word.dep_ in ("nsubj", "nsubjpass") and i < 6:
                sink += 0.055

            # Subword pieces inherit salience, but later pieces weaken slightly.
            if i > 1 and aligned and alignment[i - 1]:
                if any(k in alignment[i - 1] for k in aligned):
                    sink -= 0.055

        if i == 1:
            if word is not None and word.pos_ == "PRON":
                sink = 0.93
            elif word is not None and word.pos_ == "DET":
                sink = 0.77
            else:
                sink = 0.88

        sink = float(np.clip(sink, 0.18, 0.96))
        attention[i, 0] = sink

        # The observations constrain the sink much more than the remaining mass.
        # Use a diffuse local prior rather than inventing a sharp secondary edge.
        positions = np.arange(1, i + 1)
        residual = 0.35 / np.sqrt(positions) + np.exp(
            -(i - positions) / 4.0
        )

        if word is not None:
            for j in range(1, i + 1):
                for k in alignment[j]:
                    candidate = doc[k]
                    if candidate.i == word.head.i and candidate.i != word.i:
                        residual[j - 1] += 0.35
                    if candidate.i == word.i:
                        residual[j - 1] += 0.15

        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

        # Only quoted discourse activates this correction. Keep the original
        # diagonal exactly, moving mass solely among strictly earlier tokens.
        if any(mark in tokens[i] for mark in ('"', '“', '”')):
            dialogue_seen = True

        if dialogue_seen and i > 1:
            content = word is not None and word.pos_ in ("NOUN", "PROPN", "ADJ")
            shift = -0.10 if content and boundary is not None else 0.0
            if not content:
                shift = 0.16

            available = 1.0 - attention[i, i]
            target_sink = float(np.clip(sink + shift, 0.18, available))
            prior_mass = attention[i, 1:i].sum()
            if prior_mass > 0.0:
                attention[i, 1:i] *= (available - target_sink) / prior_mass
                attention[i, 0] = target_sink

                if boundary is not None:
                    # A modest persistent anchor, not a new local decay prior.
                    bonus = min(
                        0.10 * np.exp(-(i - boundary) / 24.0),
                        0.35 * (available - target_sink),
                    )
                    pool = attention[i, 1:i].sum() - attention[i, boundary]
                    if pool > 0.0:
                        bonus = min(bonus, pool)
                        anchor_mass = attention[i, boundary]
                        attention[i, 1:i] *= 1.0 - bonus / pool
                        attention[i, boundary] = anchor_mass + bonus

        # Update after the row so a boundary never becomes a self-edge anchor.
        if dialogue_seen and any(mark in tokens[i] for mark in (".", "?", "!")):
            if word is None or word.is_punct:
                boundary = i

    return "bos_sink_with_dialogue_anchors", attention


def prog_L14H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        positions = np.arange(1, i + 1)
        recency = np.exp(-(i - positions) / 6.0)
        recency /= recency.sum()

        # Fixed sink strength competes with a growing causal background.
        attention[i, 0] = 9.0
        attention[i, 1:i + 1] = 0.07 + 0.45 * recency
        attention[i, i] += 0.15

    attention = make_row_stochastic(attention)
    return "bos_sink_with_positional_dilution", attention


def prog_L14H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-attention with a BOS sink; early lexical tokens have a stronger
    BOS preference and less diffuse recency than the default pattern.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_with_early_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        if i == 1:
            attention[i, 0] = 0.82
            attention[i, i] = 0.18
            continue

        diagonal = 0.70
        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.is_punct:
                diagonal = 0.73
            elif word.pos_ == "AUX":
                diagonal = 0.65
            elif word.pos_ in ("ADJ", "CCONJ"):
                diagonal = 0.68
            elif word.pos_ in ("PRON", "NOUN", "PROPN"):
                diagonal = 0.72

        attention[i, i] = diagonal
        attention[i, 0] = 1.0 - diagonal - 0.06

        distances = i - np.arange(1, i)
        recency = np.exp(-distances / 2.5)
        attention[i, 1:i] = 0.06 * recency / recency.sum()

        # Only override early lexical rows; retain the original path elsewhere.
        if 2 <= i <= 6 and alignment[i]:
            word = doc[alignment[i][0]]
            if not word.is_punct and (
                i == 2 or word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ")
            ):
                shift = 0.18 * np.exp(-(i - 2) / 2.5)
                recovered_recency = 0.75 * attention[i, 1:i].sum()
                attention[i, i] -= shift
                attention[i, 1:i] *= 0.25
                attention[i, 0] += shift + recovered_recency

    return "self_with_early_bos_sink", make_row_stochastic(attention)


def prog_L14H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with local backward attention at punctuation and
    coordination boundaries and weaker sink attention at phrase endings."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_locality", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        punctuation = bool(surface) and all(
            not char.isalnum() for char in surface
        )
        opening_quote = surface in ('"', "'", "“", "‘", "«") and (
            word is None or word.tag_ in ("``", "-LRB-")
        )

        sink = 0.89
        if word is not None:
            pos = word.pos_
            if pos in ("DET", "ADJ", "NUM"):
                sink = 0.945
            elif pos in ("ADP", "PART"):
                sink = 0.925
            elif pos in ("NOUN", "PROPN"):
                sink = 0.91
            elif pos in ("VERB", "AUX", "ADV"):
                sink = 0.90
            elif pos == "PRON":
                sink = 0.88
            elif pos == "SCONJ":
                sink = 0.83
            elif pos == "CCONJ":
                sink = 0.41

            last_piece = (
                i + 1 == n
                or word.i not in alignment[i + 1]
            )
            if last_piece and word.i + 1 < len(doc):
                following = doc[word.i + 1]
                if following.is_punct or following.pos_ == "CCONJ":
                    sink -= 0.12

        if punctuation:
            sink = 0.25
        if opening_quote:
            sink = 0.81
        if tokens[i] in special_tokens:
            sink = 0.96

        sink -= 0.025 * (1.0 - np.exp(-i / 35.0))
        sink = float(np.clip(sink, 0.12, 0.98))

        # Residual attention is predominantly local and backward-looking.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.0)
        local[-1] *= 0.35
        if i > 1:
            local[-2] *= 2.5 if punctuation else 1.6

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_boundary_locality", attention


def prog_L14H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; quotation boundaries act as temporary anchors.
    After a quote boundary, briefly renew BOS attention without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    quote_anchor = None

    for i in range(1, n):
        piece = tokens[i]
        clean = piece.replace("▁", " ").replace("Ġ", " ").strip()
        indices = aligned[i]
        word = None
        if indices:
            word = doc[indices[-1]]

        # The sink is strongest at sequence onset, but remains substantial later.
        sink = 0.25 + 0.69 * np.exp(-(i - 1) / 2.55)

        if word is not None:
            if word.pos_ == "PROPN":
                sink += 0.09
            if word.ent_type_:
                sink += 0.025
            if word.is_sent_start and i > 1:
                sink += 0.19

            # Short initial pieces of longer words often reactivate the sink.
            starts_word = piece.startswith(("▁", "Ġ"))
            if (
                starts_word
                and clean
                and not word.is_punct
                and len(clean) < len(word.text)
            ):
                sink += 0.29 if len(clean) <= 2 else 0.12

        if not clean:
            sink = max(sink, 0.64)
        elif clean in ("'", "’", "‘"):
            sink = max(sink, 0.81)
        elif any(c in clean for c in ('"', "“", "”", "«", "»")):
            sink = max(sink, 0.49 if "?" in clean or "!" in clean else 0.56)
        elif all(c in ".!?" for c in clean):
            sink = max(sink, 0.46)
        elif any(c in clean for c in ("€", "œ", "â")):
            sink = max(sink, 0.58)

        sink = float(np.clip(sink, 0.15, 0.96))

        # Spread the nonsink mass over a short causal context.
        positions = np.arange(1, i + 1)
        weights = np.exp(-(i - positions) / 3.2)
        weights[-1] *= 0.32

        for j in range(max(1, i - 12), i):
            if aligned[j]:
                previous = doc[aligned[j][-1]]
                if previous.pos_ in ("VERB", "AUX"):
                    weights[j - 1] *= 1.35

        if word is not None:
            # Only already-visible governors can receive causal attention.
            governors = [word.head]
            if word.head.i != word.i:
                governors.append(word.head.head)
            for depth, governor in enumerate(governors):
                candidates = [j for j in inverse[governor.i] if 0 < j < i]
                if candidates:
                    j = candidates[-1]
                    weights[j - 1] += 0.85 / (depth + 1)

            # Keep a modest connection within a split lexical unit.
            if i > 1 and any(k in aligned[i - 1] for k in indices):
                weights[i - 2] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        # Only quotation-boundary contexts use this additional path.
        # Off-diagonal mass is redistributed; the original diagonal is untouched.
        is_quote = any(c in clean for c in ('"', "“", "”", "«", "»"))
        if quote_anchor is not None and not is_quote:
            distance = i - quote_anchor
            if 1 <= distance <= 12:
                row = attention[i]
                available = 1.0 - row[i]
                renewed_sink = sink
                if distance <= 5:
                    renewed_sink = max(
                        sink, 0.32 + 0.32 * np.exp(-(distance - 1) / 5.0)
                    )
                renewed_sink = min(renewed_sink, available)
                old_mass = row[1:i].sum()
                if old_mass > 0.0:
                    remaining = available - renewed_sink
                    anchor_fraction = 0.30 * np.exp(-(distance - 1) / 18.0)
                    row[1:i] *= remaining * (1.0 - anchor_fraction) / old_mass
                    row[quote_anchor] += remaining * anchor_fraction
                    row[0] = renewed_sink

        if is_quote:
            quote_anchor = i

    return "bos_sink_with_quote_anchors", attention


def prog_L14H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually weakening positional dominance.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.50 + 0.43 * np.exp(-(i - 1) / 85.0)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 / i + 0.35 * (
            np.exp(-(i - positions) / 12.0)
            / np.exp(-(i - positions) / 12.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L14H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with gradual positional dilution.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 1.0 / (1.045 + 0.0045 * i)
        positions = np.arange(1, i + 1)
        residual = 0.75 / i + 0.25 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L14H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with weak local and
    syntactic coordination attention in the remaining probability mass."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_local_structure", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None

        sink = (
            0.71
            + 0.23 * np.exp(-(i - 1) / 2.8)
            - 0.0012 * max(i - 18, 0)
        )
        if word is not None:
            if word.pos_ in ("DET", "ADP", "AUX", "PART", "CCONJ", "SCONJ"):
                sink += 0.035
            elif word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                sink -= 0.035
            elif word.pos_ == "PUNCT":
                sink += 0.025
        else:
            # Unaligned pieces often represent whitespace or tokenizer fragments.
            sink += 0.055

        if i == 1:
            sink = 0.925 if word is not None and word.pos_ == "DET" else 0.95
        sink = float(np.clip(sink, 0.48, 0.97))

        positions = np.arange(1, i + 1)
        residual = 0.25 / i + np.exp(-(i - positions) / 5.0)
        residual[-1] *= 0.65

        if word is not None and word.dep_ == "conj":
            targets = [j for j in inverse[word.head.i] if 0 < j < i]
            if targets:
                residual[targets[-1] - 1] += 2.5 * residual.sum()

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_weak_local_structure", attention


def prog_L14H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective local readout at coordination, commas, and objects.
    Transfer sink mass to the preceding content word without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_selective_local_readout", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.86

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("VERB", "ADJ", "AUX"):
                sink_mass += 0.025
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass -= 0.045
            elif word.is_punct:
                sink_mass = 0.91 if any(
                    mark in word.text for mark in (".", "!", "?")
                ) else 0.80

        if i == 1:
            sink_mass = 0.94

        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 6.0)
        recent /= recent.sum()
        residual = 0.5 / i + 0.5 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Only completed, immediately preceding words receive the extra readout.
        if i > 1 and alignment[i] and alignment[i - 1]:
            word = doc[alignment[i][0]]
            prev = doc[alignment[i - 1][-1]]
            extra = 0.0
            if prev.i < word.i:
                if word.pos_ == "CCONJ" and prev.pos_ in (
                    "ADJ", "NOUN", "PROPN"
                ):
                    extra = 0.14
                    if prev.pos_ == "PROPN":
                        extra = 0.28
                elif word.is_punct and "," in word.text and prev.pos_ in (
                    "NOUN", "PROPN", "VERB"
                ):
                    extra = 0.12 if prev.pos_ != "PROPN" else 0.26
                elif prev.pos_ == "VERB" and (
                    (word.dep_ in ("dobj", "obj", "iobj") and word.head.i == prev.i)
                    or (word.dep_ == "det" and word.head.head.i == prev.i)
                ):
                    extra = 0.08 if word.dep_ == "det" else 0.18
                    if word.dep_ != "det" and prev.tag_ == "VBG":
                        extra = 0.30

            if extra > 0.0:
                targets = [j for j in word_tokens[prev.i] if 0 < j < i]
                if targets:
                    weights = np.arange(1, len(targets) + 1, dtype=np.float64)
                    weights /= weights.sum()
                    transfer = min(extra, attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i, targets] += transfer * weights

    return "bos_sink_with_selective_local_readout", make_row_stochastic(attention)


def prog_L14H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Copy the preceding token, except apostrophe-split suffixes preferentially
    attend past the apostrophe to their lexical host and the attention sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "previous_token_apostrophe_skip", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        current_ids = aligned[i]
        previous_ids = aligned[i - 1]
        current = doc[current_ids[-1]] if current_ids else None
        previous = doc[previous_ids[-1]] if previous_ids else None

        if i == 1 and tokens[0] in special:
            attention[i, 0] = 0.88
            attention[i, i] = 0.12
            continue

        strength = 0.77

        # Pieces of one lexical item usually form a strong adjacent chain.
        if set(current_ids).intersection(previous_ids):
            strength += 0.08

        if current is not None and previous is not None:
            if current.is_punct:
                strength += 0.06
            elif current.pos_ in ("ADP", "PART", "CCONJ"):
                strength += 0.06
            elif current.pos_ == "DET" and previous.pos_ in ("VERB", "ADP"):
                strength += 0.05
            elif current.pos_ == "VERB" and previous.pos_ in ("AUX", "ADV"):
                strength += 0.05

            if current.head.i == previous.i or previous.head.i == current.i:
                strength += 0.025

        strength = float(np.clip(strength, 0.70, 0.93))
        attention[i, i - 1] = strength
        residual = 1.0 - strength

        # Weak self-attention and an attention-sink component accompany
        # a short, geometrically decaying causal tail.
        attention[i, i] += residual * 0.22
        attention[i, 0] += residual * 0.43

        if i >= 2:
            positions = np.arange(i - 1)
            weights = np.exp(-0.65 * ((i - 2) - positions))
            attention[i, :i - 1] += residual * 0.35 * weights / weights.sum()
        else:
            attention[i, 0] += residual * 0.35

        # A bare alphabetic piece following an apostrophe is a suffix,
        # not a new whitespace-prefixed word. Redistribute only its
        # apostrophe edge; preserve self-attention and the original tail.
        if (
            i >= 3
            and tokens[i - 1] in ("'", "’")
            and tokens[i].isalpha()
            and tokens[i - 2] not in special
        ):
            possessive = current is not None and current.dep_ == "case"
            negative = current is not None and current.dep_ == "neg"
            retained = 0.36 if possessive else 0.13
            host_fraction = 0.90 if possessive else (0.60 if negative else 0.80)

            moved = max(0.0, attention[i, i - 1] - retained)
            attention[i, i - 1] -= moved
            attention[i, i - 2] += moved * host_fraction
            attention[i, 0] += moved * (1.0 - host_fraction)

    return "previous_token_apostrophe_skip", make_row_stochastic(attention)


def prog_L14H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; split content words route attention to
    pre-word context rather than their own preceding subword fragments."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_split_word_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        sink = 0.83

        if word is not None:
            if word.pos_ in ("DET", "CCONJ", "SCONJ", "PART", "AUX"):
                sink = 0.87
            elif word.pos_ in ("ADP", "PRON"):
                sink = 0.84
            elif word.pos_ in ("VERB", "ADV"):
                sink = 0.78
            elif word.pos_ == "ADJ":
                sink = 0.75
            elif word.pos_ in ("NOUN", "PROPN", "NUM"):
                sink = 0.71
            elif word.pos_ == "PUNCT":
                sink = 0.88 if word.is_sent_end else 0.81

            if word.is_sent_start:
                sink = max(sink, 0.89)

        if i == 1:
            sink = 0.90
        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.94

        # Residual attention is causal and mostly local rather than uniform.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        if i > 1:
            residual[i - 2] += 1.2

        if word is not None:
            # A causal syntactic head can absorb part of the non-sink mass.
            if word.head.i != word.i:
                head_positions = [
                    j for j in inverse[word.head.i] if 0 < j < i
                ]
                if head_positions:
                    residual[head_positions[-1] - 1] += 1.4

            # Preserve a small subword-continuation preference.
            if i > 1 and aligned and alignment[i - 1]:
                if aligned[0] in alignment[i - 1]:
                    residual[i - 2] += 0.8

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Only split alphabetic content words take this alternate path.
        # Transfers exclude the diagonal, preserving original self-attention.
        if (
            word is not None
            and word.is_alpha
            and word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ")
            and tokens[i] not in tokenizer.all_special_tokens
        ):
            pieces = [
                j for j in inverse[word.i]
                if j > 0 and alignment[j] == [word.i]
            ]
            if len(pieces) > 1 and i in pieces and pieces[0] > 1:
                start = pieces[0]
                if i == start:
                    available = attention[i, 1:i].sum()
                    moved = min(max(0.0, 0.87 - sink), available)
                    if available > 0.0:
                        attention[i, 1:i] *= 1.0 - moved / available
                        attention[i, 0] += moved
                else:
                    earlier_pieces = [j for j in pieces if j < i]
                    moved = 0.9 * attention[i, earlier_pieces].sum()
                    attention[i, earlier_pieces] *= 0.1

                    target_sink = 0.60 if word.pos_ == "ADJ" else 0.54
                    released = max(0.0, attention[i, 0] - target_sink)
                    attention[i, 0] -= released
                    moved += released

                    context = np.arange(max(1, start - 2), start)
                    weights = np.arange(1, len(context) + 1, dtype=np.float64)
                    attention[i, context] += moved * weights / weights.sum()

    return "bos_sink_with_split_word_context", attention


def prog_L15H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with syntactic residuals; prepositional objects also attend to
    the earlier content governor and its auxiliaries, not just the preposition.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pp_governors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    word_pieces = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        if tokens[i] not in special:
            for word_id in word_ids:
                word_pieces[word_id].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        if tokens[i] in special:
            attention[i, 0] = 1.0
            continue

        word_ids = alignment[i]
        if not word_ids:
            sink = 0.70
            residual = np.zeros(i + 1, dtype=np.float64)
            residual[i - 1] = 1.0
        else:
            word_id = max(
                word_ids,
                key=lambda k: (
                    not doc[k].is_space,
                    not doc[k].is_punct,
                    len(doc[k].text),
                ),
            )
            word = doc[word_id]
            pieces = word_pieces[word_id]
            unfinished = bool(pieces and i < pieces[-1])

            if unfinished:
                sink = 0.92
            elif word.pos_ == "DET" or word.dep_ == "poss":
                sink = 0.89
            elif word.pos_ == "AUX":
                sink = 0.85
            elif word.pos_ == "ADJ" and word.dep_ == "amod":
                sink = 0.90
            elif word.pos_ == "ADV":
                sink = 0.79
            elif word.pos_ == "PRON":
                sink = 0.82 if word.dep_ in ("nsubj", "nsubjpass") else 0.65
            elif word.pos_ in ("ADP", "PART"):
                sink = 0.79
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink = 0.65
            elif word.pos_ == "VERB":
                sink = 0.69
            elif word.pos_ in ("NOUN", "PROPN"):
                sink = 0.48 if word.pos_ == "NOUN" else 0.67
            elif word.is_punct:
                sink = 0.38 if word.is_sent_end else 0.61
            else:
                sink = 0.73

            residual = np.zeros(i + 1, dtype=np.float64)

            # Prefer a syntactic governor that is already available causally.
            head = word.head
            visited = {word.i}
            for depth in range(3):
                if head.i in visited:
                    break
                visited.add(head.i)
                candidates = [
                    j for j in word_pieces[head.i] if 0 < j < i
                ]
                if candidates:
                    residual[candidates[-1]] += 2.8 / (depth + 1)
                    break
                head = head.head

            # Noun-phrase prefixes provide a secondary leftward anchor.
            if word.pos_ in ("NOUN", "PROPN"):
                for child in word.children:
                    if child.dep_ in ("det", "poss", "amod", "compound"):
                        candidates = [
                            j for j in word_pieces[child.i] if 0 < j < i
                        ]
                        if candidates:
                            weight = 1.2 if child.dep_ in ("det", "poss") else 0.4
                            residual[candidates[0]] += weight

            # Punctuation tends to collect nearby completed material.
            if word.is_punct:
                for j in range(max(1, i - 6), i):
                    residual[j] += 0.7 * np.exp(-(i - j - 1) / 2.0)

            if i > 1:
                residual[i - 1] += 0.25
            residual[i] += 0.08

            # A completed PP object can retrieve the event behind its
            # preposition. Transfer existing anchor mass only: leave the
            # sink, self weight, and total residual mass unchanged.
            if (
                not unfinished
                and word.pos_ in ("NOUN", "PROPN")
                and word.head.pos_ == "ADP"
            ):
                targets = np.zeros(i + 1, dtype=np.float64)
                ancestor = word.head.head
                seen = {word.i, word.head.i}
                for depth in range(4):
                    if ancestor.i in seen:
                        break
                    seen.add(ancestor.i)
                    candidates = [
                        j for j in word_pieces[ancestor.i] if 0 < j < i
                    ]
                    if ancestor.pos_ in ("VERB", "AUX", "ADJ"):
                        if candidates:
                            targets[candidates[-1]] += 1.0
                            for child in ancestor.children:
                                if child.dep_ in ("aux", "auxpass", "cop"):
                                    available = [
                                        j for j in word_pieces[child.i]
                                        if 0 < j < i
                                    ]
                                    if available:
                                        targets[available[-1]] += 0.45
                        break
                    ancestor = ancestor.head

                if targets.sum() > 0:
                    donors = {
                        j for j in word_pieces[word.head.i] if 0 < j < i
                    }
                    for child in word.children:
                        if child.dep_ in ("det", "poss"):
                            donors.update(
                                j for j in word_pieces[child.i] if 0 < j < i
                            )
                    transferred = 0.0
                    for j in donors:
                        amount = 0.75 * residual[j]
                        residual[j] -= amount
                        transferred += amount
                    residual += transferred * targets / targets.sum()

        # The earliest positions have a particularly strong sink prior.
        if i == 1:
            sink = 0.955
        elif i <= 3:
            sink = min(0.96, sink + 0.06)

        attention[i, 0] = sink
        residual[0] = 0.0
        total = residual.sum()
        if total > 0:
            attention[i, :i + 1] += (1.0 - sink) * residual / total
        else:
            attention[i, i] += 1.0 - sink

    return "bos_sink_with_pp_governors", make_row_stochastic(attention)


def prog_L15H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with subword locality, plus a named-subject attention anchor.
    Subject-linked queries can redirect BOS mass without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_named_subject_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    first_piece = {}
    named_subjects = [
        w for w in doc
        if w.pos_ == "PROPN" and w.dep_ in ("nsubj", "nsubjpass")
    ]
    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        start = i
        if sids:
            sid = sids[0]
            start = first_piece.get(sid, i)
            first_piece.setdefault(sid, i)

        if word is None:
            sink = 0.83
        elif word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ", "PART"):
            sink = 0.88
        elif word.pos_ in ("PRON", "AUX"):
            sink = 0.81
        elif word.pos_ == "PUNCT":
            sink = 0.79
        elif word.pos_ in ("NOUN", "PROPN"):
            sink = 0.67
        elif word.pos_ in ("VERB", "ADJ", "ADV"):
            sink = 0.72
        else:
            sink = 0.76

        continuation = start < i and word is not None and not word.is_punct
        if continuation:
            sink = max(0.30, sink - 0.20 - 0.07 * (i - start - 1))

        if i == 1:
            sink = 0.80 if word is not None and word.pos_ == "DET" else 0.92

        # Preserve the original local background and continuation weights.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        if continuation:
            residual *= 0.28
            residual[start - 1] += 0.72

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only named-subject-linked word starts activate the additional path.
        if word is not None and start == i:
            candidates = [
                subject for subject in named_subjects
                if subject.i < word.i
                and subject.sent.start == word.sent.start
                and subject.i in first_piece
            ]
            if candidates:
                subject = candidates[-1]
                anchor = first_piece[subject.i]
                predicate = subject.head
                has_aux = any(
                    child.dep_ in ("aux", "auxpass")
                    for child in predicate.children
                )
                target = None

                if word.pos_ == "AUX" and word.head.i == predicate.i:
                    target = 0.80
                elif word.i == predicate.i and word.pos_ == "VERB":
                    target = 0.21 if has_aux else 0.52
                elif word.pos_ == "PRON" and word.dep_ in ("nsubj", "nsubjpass"):
                    target = 0.77 if has_aux else 0.23
                elif (
                    has_aux
                    and word.pos_ == "SCONJ"
                    and word.dep_ == "mark"
                    and any(
                        child.pos_ == "PRON"
                        and child.dep_ in ("nsubj", "nsubjpass")
                        for child in word.head.children
                    )
                ):
                    target = 0.42

                if target is not None and 0 < anchor < i:
                    transfer = min(
                        max(0.0, attention[i, 0] - 0.08),
                        max(0.0, target - attention[i, anchor]),
                    )
                    attention[i, 0] -= transfer
                    attention[i, anchor] += transfer

    return "bos_sink_with_named_subject_anchor", make_row_stochastic(attention)


def prog_L15H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with punctuation self-attention; quoted or verb-coordinated
    discourse shifts some lexical-token BOS mass onto the diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Restrict the correction to dialogue or coordinated verbal clauses.
    discourse_self = (
        any(w.dep_ == "conj" and w.pos_ == "VERB" for w in doc)
        or any(c in sentence for c in ('"', "“", "”", "«", "»"))
    )

    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        piece = tokens[i].replace("▁", "").replace("Ġ", "")
        is_space = not piece or piece.isspace()
        is_punctuation = (
            (word is not None and word.is_punct)
            or (bool(piece) and all(not c.isalnum() and not c.isspace()
                                   for c in piece))
        )

        age = 1.0 - np.exp(-(i - 1) / 18.0)
        sink = 0.79 - 0.12 * age
        self_share = 0.34

        if word is not None:
            pos = word.pos_
            dep = word.dep_
            if pos in ("NOUN", "PROPN"):
                sink += 0.035
            elif pos in ("ADJ", "ADV", "AUX"):
                sink += 0.020
            elif pos in ("ADP", "DET", "PART"):
                sink -= 0.025
            elif pos in ("CCONJ", "SCONJ"):
                sink -= 0.100

            if dep in ("nsubj", "nsubjpass") and i < 7:
                sink += 0.020
            if dep in ("amod", "advmod"):
                sink += 0.015

        if is_punctuation:
            # Early punctuation can still favor BOS; later punctuation often
            # retains about half of its attention on its own position.
            sink = 0.79 - 0.48 * (1.0 - np.exp(-(i - 1) / 5.0))
            self_share = 0.68
            if '"' in piece or "'" in piece or "“" in piece or "”" in piece:
                sink += 0.19
                self_share = 0.45
        elif is_space:
            sink = 0.43
            self_share = 0.82

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.85

        sink = float(np.clip(sink, 0.20, 0.89))
        attention[i, 0] = sink

        # Distribute the non-sink mass between self and a causal recency tail.
        residual = 1.0 - sink
        attention[i, i] = residual * self_share
        if i > 1:
            positions = np.arange(1, i)
            local = np.exp(-(i - positions) / 3.5)
            local /= local.sum()
            attention[i, 1:i] = residual * (1.0 - self_share) * local
        else:
            attention[i, i] += residual * (1.0 - self_share)

        # Keep the original tail and punctuation behavior intact. In the
        # targeted discourse context, transfer only BOS mass to lexical self.
        if (
            discourse_self
            and i > 1
            and word is not None
            and not is_punctuation
            and not is_space
            and tokens[i] not in tokenizer.all_special_tokens
        ):
            transfer = 0.12 + 0.04 * age
            if word.pos_ in ("CCONJ", "SCONJ", "ADP"):
                transfer += 0.035
            transfer = min(transfer, max(0.0, attention[i, 0] - 0.20))
            attention[i, 0] -= transfer
            attention[i, i] += transfer

    return "bos_sink_with_discourse_self", make_row_stochastic(attention)


def prog_L15H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Primarily a BOS attention sink, with weaker repeated-context continuation retrieval.
    Punctuation and later positions have a more diffuse non-BOS residual.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_continuation_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_ids = [ids[0] if ids else -1 for ids in alignment]
    special_tokens = set(tokenizer.all_special_tokens)

    attention[0, 0] = 1.0
    for i in range(1, n):
        wi = word_ids[i]
        word = doc[wi] if wi >= 0 else None
        is_special = tokens[i] in special_tokens
        is_punctuation = (
            word.is_punct if word is not None
            else bool(tokens[i].strip()) and not any(c.isalnum() for c in tokens[i])
        )

        sink = 0.965 - 0.0015 * min(i - 1, 80)
        if is_punctuation and not is_special:
            sink -= 0.17
        if word is not None and word.is_space:
            sink -= 0.12
        if wi >= 0 and i > 1 and word_ids[i - 1] == wi:
            sink -= 0.045
        sink = float(np.clip(sink, 0.60, 0.98))

        retrieval = np.zeros(i + 1, dtype=np.float64)
        if word is not None and not word.is_punct and not word.is_space:
            # Compare complete word-final pieces to avoid treating separate
            # subword fragments within the same word as repeated contexts.
            at_word_end = i == n - 1 or word_ids[i + 1] != wi
            if at_word_end and not is_special:
                for j in range(1, i - 1):
                    wj = word_ids[j]
                    if wj < 0 or wj == wi:
                        continue
                    if word_ids[j + 1] == wj:
                        continue
                    if doc[wj].pos_ != word.pos_:
                        continue
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity > 0.94:
                        strength = ((similarity - 0.94) / 0.06) ** 2
                        retrieval[j + 1] += strength

        retrieval_mass = 0.0
        if retrieval.sum() > 0:
            pos = word.pos_
            if pos in ("DET", "PRON", "AUX", "CCONJ", "SCONJ"):
                retrieval_mass = 0.06
            elif pos == "ADP":
                retrieval_mass = 0.48
            else:
                retrieval_mass = 0.32
            retrieval_mass *= min(1.0, float(retrieval.max()))
            retrieval /= retrieval.sum()

        # Most unexplained probability remains a weak causal background.
        background = np.ones(i, dtype=np.float64)
        background += 0.8 * np.exp(-(i - np.arange(1, i + 1)) / 5.0)
        background /= background.sum()

        residual = 1.0 - sink
        attention[i, 0] = sink - retrieval_mass
        attention[i, 1:i + 1] = residual * background
        attention[i, :i + 1] += retrieval_mass * retrieval

    return "bos_sink_with_continuation_retrieval", make_row_stochastic(attention)


def prog_L15H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink with weak local-context attention.
    Lexical boundaries, punctuation, and fragmented words modulate sink strength.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    coverage = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            coverage[k].append(i)

    attention[0, 0] = 1.0

    pos_strength = {
        "DET": 0.68,
        "ADP": 0.65,
        "AUX": 0.64,
        "PART": 0.63,
        "CCONJ": 0.60,
        "SCONJ": 0.61,
        "PRON": 0.57,
        "NOUN": 0.58,
        "PROPN": 0.69,
        "VERB": 0.57,
        "ADJ": 0.61,
        "ADV": 0.57,
        "NUM": 0.63,
        "PUNCT": 0.64,
        "SPACE": 0.68,
    }

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        sink = pos_strength.get(word.pos_, 0.64) if word is not None else 0.66

        if word is not None:
            if word.dep_ in ("poss", "nmod:poss"):
                sink += 0.06
            if word.ent_type_:
                sink += 0.03

            pieces = coverage[word.i]
            if len(pieces) > 1 and word.pos_ != "PUNCT":
                sink += 0.13 if i == pieces[0] else 0.09

            if word.is_punct:
                if any(c in ".!?" for c in word.text):
                    sink = 0.76
                elif any(c in "'’" for c in word.text):
                    sink = 0.84
                elif any(c in "\"“”" for c in word.text):
                    sink = 0.70

        if i == 1:
            sink = 0.89
        elif i == 2:
            sink += 0.13
        elif i == 3:
            sink += 0.05

        sink = float(np.clip(sink, 0.40, 0.94))

        # Allocate non-sink mass locally, without forcing a specific dependency.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()
        residual *= 0.65
        if i > 1:
            residual[i - 2] += 0.35
        else:
            residual[0] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L15H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with POS modulation; clause-ending punctuation redirects some
    sink mass to the preceding token and its clause head, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_boundary_redirect", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "NOUN": 0.79,
        "PROPN": 0.83,
        "ADJ": 0.80,
        "PRON": 0.76,
        "DET": 0.75,
        "NUM": 0.78,
        "ADV": 0.72,
        "VERB": 0.66,
        "AUX": 0.62,
        "ADP": 0.65,
        "PART": 0.71,
        "CCONJ": 0.62,
        "SCONJ": 0.64,
        "INTJ": 0.80,
        "PUNCT": 0.55,
        "SPACE": 0.60,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.70
        if alignment[i]:
            word_id = alignment[i][0]
            word = doc[word_id]
            sink = sink_by_pos.get(word.pos_, 0.70)

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink += 0.025
            if word.ent_type_:
                sink += 0.015

            # Later pieces of a word tend to have less consistent sink strength.
            if word_id in alignment[i - 1]:
                sink -= 0.045

            if i == 1:
                sink = 0.5 * sink + 0.5 * 0.83

        sink = float(np.clip(sink, 0.48, 0.90))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.75 / i + 0.25 * (
            np.exp(-(i - positions) / 8.0)
            / np.exp(-(i - positions) / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Only boundary-punctuation rows change; transfer mass from BOS,
        # leaving the original self weight and diffuse background intact.
        surface = tokens[i].lstrip("▁Ġ")
        if (
            i > 1
            and surface
            and all(c in ",;:.!?\"'”’)]}" for c in surface)
            and any(c in ",;:.!?" for c in surface)
            and alignment[i]
            and all(doc[k].pos_ == "PUNCT" for k in alignment[i])
        ):
            terminal = any(c in ".!?" for c in surface)
            closing_quote = terminal and any(c in "\"”’" for c in surface)
            transfer = min(
                0.34 if closing_quote else (0.24 if terminal else 0.22),
                max(0.0, attention[i, 0] - 0.18),
            )
            head_id = doc[alignment[i][0]].head.i
            head_positions = [
                j for j in range(1, i) if head_id in alignment[j]
            ]
            head_position = head_positions[-1] if head_positions else i - 1
            attention[i, 0] -= transfer
            attention[i, i - 1] += transfer * (0.70 if terminal else 1.0)
            if terminal:
                attention[i, head_position] += transfer * 0.30

    return "bos_sink_boundary_redirect", make_row_stochastic(attention)


def prog_L15H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with residual local/syntactic attention.
    Closing quotation marks preferentially retrieve their opening delimiter.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_links", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    attention[0, 0] = 1.0
    quote_stack = []

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""

        # Most queries dump their probability into the initial-token sink.
        sink = 0.87
        if pos in ("DET", "AUX", "PART"):
            sink = 0.92
        elif pos in ("PRON", "ADP", "VERB"):
            sink = 0.89
        elif pos in ("ADJ", "ADV", "NUM"):
            sink = 0.83
        elif pos in ("NOUN", "PROPN"):
            sink = 0.79
        elif pos in ("CCONJ", "SCONJ"):
            sink = 0.72
        elif pos == "PUNCT":
            sink = 0.64

        if word is not None and word.dep_ in ("dobj", "obj", "pobj", "attr"):
            sink -= 0.07

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.15 * np.exp(-(i - positions) / 3.0)
        residual[i - 1] += 0.60
        residual[i] += 0.12

        if word is not None:
            # Recover short-range links to earlier syntactic governors.
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if word.head.i != word.i and head_positions:
                j = head_positions[-1]
                residual[j] += 0.35
                if word.dep_ == "pobj" and word.head.pos_ == "ADP":
                    sink = min(sink, 0.57)
                    residual[j] += 1.80

            # Subword continuations retain a modest within-word connection.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                residual[earlier_pieces[-1]] += 0.30

        # Punctuation-only rules handle both standalone and merged delimiters.
        closing_quote = False
        for char in text:
            if char in ('"', "“", "”", "«", "»"):
                if char in ("”", "»") or (char == '"' and quote_stack):
                    if quote_stack:
                        opening = quote_stack.pop()
                        if opening < i:
                            residual[opening] += 5.0
                            closing_quote = True
                else:
                    quote_stack.append(i)

        if closing_quote:
            sink = 0.23
        elif any(char in text for char in ('"', "“", "«")):
            sink = 0.94
        elif text and all(char in ".!?;:" for char in text):
            sink = min(sink, 0.48)

        if i == 1:
            sink = 0.95

        attention[i, 0] = sink
        total = residual.sum()
        if total > 0:
            attention[i, :i + 1] += (1.0 - sink) * residual / total
        else:
            attention[i, 0] = 1.0

    return "bos_sink_with_boundary_links", make_row_stochastic(attention)


def prog_L15H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and a local syntactic residual.
    Early tokens strongly favor BOS; later tokens retain more recent-context attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[aligned[i][0]] if aligned[i] else None
        maturity = 1.0 - np.exp(-(i - 1) / 6.0)
        sink_mass = (
            0.69
            + 0.27 * np.exp(-i / 8.0)
            - 0.04 * np.log1p(i / 24.0)
        )

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass -= 0.045 * maturity
            elif word.pos_ in ("DET", "ADP", "AUX"):
                sink_mass += 0.035 * maturity

            if word.is_punct and word.text in (".", "!", "?", '."', '!"', '?"'):
                sink_mass -= 0.22 * maturity

        sink_mass = float(np.clip(sink_mass, 0.30, 0.97))

        # The residual is predominantly local, rather than a second global sink.
        positions = np.arange(1, i + 1)
        residual = 0.18 * np.exp(-(i - positions) / 3.0)
        residual[-1] += 0.20
        if i > 1:
            residual[-2] += 1.0

        if word is not None:
            # Only use already-visible pieces of the syntactic governor.
            if word.head.i != word.i:
                for j in inverse[word.head.i]:
                    if 0 < j < i:
                        residual[j - 1] += 0.65

            # A continuation piece can retain attention on its own word prefix.
            for j in inverse[word.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.35

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L15H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head: nearly all attention targets the first token.
    Spread the small, unspecified residual uniformly over other causal tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.99
            attention[i, 1:i + 1] = 0.01 / i

    return "bos_sink_uniform_residual", attention


def prog_L15H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary resets; dialogue redistributes quote-boundary
    attention toward BOS and nearby formatting/clause landmarks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_landmarks", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    pos = [""] * n
    dep = [""] * n
    primary = [None] * n
    for i, indices in enumerate(aligned):
        if indices:
            si = max(
                indices,
                key=lambda k: (not doc[k].is_punct, not doc[k].is_space)
            )
            primary[i] = si
            pos[i] = doc[si].pos_
            dep[i] = doc[si].dep_

    clean = [t.lstrip("▁Ġ") for t in tokens]
    special = set(tokenizer.all_special_tokens)
    apostrophes = {"'", "’"}
    quote_chars = {'"', "“", "”", "«", "»"}
    boundaries = []
    opening_quote = None
    last_closing_quote = None

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = clean[i]
        whitespace = tokens[i] not in special and not text
        apostrophe = text in apostrophes
        has_quote = any(c in quote_chars for c in text)
        closing_quote = False

        if has_quote:
            if opening_quote is None:
                opening_quote = i
            else:
                closing_quote = True
                last_closing_quote = i
                opening_quote = None

        sink = 0.08 + 0.88 * np.exp(-(i - 1) / 8.0)
        if pos[i] in {"DET", "ADP", "AUX"}:
            sink += 0.045
        elif pos[i] in {"NOUN", "ADJ"}:
            sink -= 0.035
        if dep[i] == "poss" and i == 1:
            sink -= 0.15

        if text == ",":
            sink += 0.10
        if has_quote:
            sink += 0.16
        if whitespace:
            sink = max(sink, 0.73 * np.exp(-i / 75.0))
        if apostrophe:
            sink = max(sink, 0.87)

        si = primary[i]
        if si is not None:
            pieces = inverse[si]
            if len(pieces) > 1 and pos[i] in {"NOUN", "PROPN", "ADJ"}:
                sink += 0.16
                if i == pieces[0]:
                    sink += 0.09

        sink = float(np.clip(sink, 0.06, 0.97))
        attention[i, 0] = sink

        indices = np.arange(1, i + 1)
        weights = 0.035 + 0.10 * np.exp(-(i - indices) / 6.0)
        weights[-1] += 0.10
        if i > 1:
            weights[-2] += 0.18

        # Phrase introducers are useful local landmarks, not semantic matches.
        for j in range(max(1, i - 10), i):
            distance = i - j
            if pos[j] in {"CCONJ", "SCONJ", "ADP"}:
                weights[j - 1] += 0.65 * np.exp(-distance / 4.5)
            if pos[j] in {"DET", "AUX"} and distance <= 3:
                weights[j - 1] += 0.22 * np.exp(-distance / 3.0)
            if dep[i] in {"dobj", "obj", "pobj", "attr", "acomp"}:
                if pos[j] in {"VERB", "AUX", "ADP"} and distance <= 4:
                    weights[j - 1] += 0.12

        # The latest punctuation boundary remains visible across its clause.
        if boundaries:
            b = boundaries[-1]
            weights[b - 1] += 0.65 * np.exp(-(i - b) / 15.0)

        if opening_quote is not None:
            q = opening_quote
            weights[q - 1] += 1.30 * np.exp(-(i - q) / 24.0)

        if last_closing_quote is not None:
            q = last_closing_quote
            weights[q - 1] += 1.45 * np.exp(-(i - q) / 23.0)

        if text == ",":
            weights[-1] += 0.45
        elif pos[i] == "PUNCT" and not apostrophe:
            weights[-1] += 0.20

        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        if (
            not apostrophe
            and (has_quote or any(c in ",;:.!?" for c in text))
        ):
            boundaries.append(i)

    # Only dialogue takes this additional path. Ordinary prose is unchanged.
    # Recognize both actual quotation marks and their mojibake encoding.
    dialogue = any(c in quote_chars for c in sentence) or "\u00e2\u20ac" in sentence
    if dialogue:
        encoded_quote = np.zeros(n, dtype=bool)
        for j in range(1, n):
            if "\u00e2\u20ac" in clean[j]:
                encoded_quote[j] = True
            elif "\u00e2" in clean[j] and j + 1 < n:
                if "\u20ac" in clean[j + 1]:
                    encoded_quote[j:j + 2] = True
                    if j + 2 < n and clean[j + 2] in {"\u0153", "\u009d"}:
                        encoded_quote[j + 2] = True

        landmarks = []
        quote_boundaries = []
        for i in range(1, n):
            text = clean[i]
            whitespace = tokens[i] not in special and not text
            quote = any(c in quote_chars for c in text) or encoded_quote[i]

            # Preserve every original diagonal entry. Only redistribute
            # off-diagonal boundary mass, using the original decay scale.
            released = 0.0
            for j in quote_boundaries:
                moved = 0.55 * attention[i, j]
                attention[i, j] -= moved
                released += moved

            anchors = landmarks[-3:]
            if anchors:
                anchor_weights = np.exp(-(i - np.asarray(anchors)) / 23.0)
                anchor_weights /= anchor_weights.sum()
                attention[i, anchors] += 0.5 * released * anchor_weights
                attention[i, 0] += 0.5 * released
            else:
                attention[i, 0] += released

            # Dialogue has a persistent BOS floor rather than continuing
            # to decay to the ordinary-prose asymptote.
            target = max(
                attention[i, 0],
                0.20 + 0.40 * np.exp(-(i - 1) / 12.0)
            )
            if whitespace:
                target = max(target, 0.85)
            if encoded_quote[i]:
                target = max(target, 0.88)
            if text in apostrophes:
                target = min(target, 0.36)

            available = attention[i, 1:i].sum()
            delta = target - attention[i, 0]
            if delta > 0.0 and available > 0.0:
                delta = min(delta, available)
                attention[i, 1:i] *= (available - delta) / available
                attention[i, 0] += delta
            elif delta < 0.0 and anchors:
                attention[i, 0] += delta
                attention[i, anchors] -= delta * anchor_weights

            if (
                whitespace
                or text == ","
                or text in apostrophes
                or (
                    i > 1
                    and quote_boundaries
                    and i - quote_boundaries[-1] <= 2
                    and pos[i] in {"PRON", "DET"}
                )
            ):
                landmarks.append(i)

            if quote or any(c in ".!?" for c in text):
                quote_boundaries.append(i)

    return "bos_sink_with_dialogue_landmarks", attention


def prog_L15H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token,
    with a small diffuse residual over the remaining causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.975
            attention[i, 1:i + 1] = 0.025 / i

    return "bos_sink_with_diffuse_residual", attention


def prog_L15H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predominantly a BOS attention sink, with residual attention to salient
    preceding entities and subjects, especially within quoted speech.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_entity_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    salience = np.zeros(n, dtype=np.float64)
    proper = np.zeros(n, dtype=bool)

    for i, indices in enumerate(alignment):
        if not indices:
            continue
        word = doc[indices[-1]]
        pos[i] = word.pos_
        proper[i] = word.pos_ == "PROPN"
        if word.pos_ in ("NOUN", "PROPN", "PRON"):
            salience[i] = 0.15
            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                salience[i] += 1.4
            if proper[i]:
                salience[i] += 2.0
            elif word.ent_type_:
                salience[i] += 0.35

        # Represent a split word at its final subtoken rather than duplicating
        # its salience across all of its pieces.
        if i + 1 < n and indices[-1] in alignment[i + 1]:
            salience[i] = 0.0
            proper[i] = False

    attention[0, 0] = 1.0
    in_quote = False

    for i in range(1, n):
        text = tokens[i]
        quote_boundary = any(c in text for c in ('"', "“", "”", "«", "»"))
        quoted = in_quote or quote_boundary

        sink = 0.77
        if pos[i] in ("NOUN", "PROPN", "ADJ", "VERB"):
            sink += 0.04
        elif pos[i] in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
            sink -= 0.07
        elif pos[i] == "PUNCT" or not text.strip("▁Ġ \t\n"):
            sink -= 0.13
        if i <= 3:
            sink += 0.04

        indices = np.arange(1, i + 1)
        distances = i - indices
        local = np.exp(-distances / 4.0)
        local /= local.sum()

        anchors = salience[1:i + 1].copy()
        anchors *= np.exp(-distances / 35.0)
        anchors[-1] = 0.0
        has_anchor = anchors.sum() > 0.0
        has_proper = bool(np.any(proper[1:i]))

        if has_proper:
            sink -= 0.12
            if quoted:
                sink -= 0.12

        sink = float(np.clip(sink, 0.38, 0.91))
        attention[i, 0] = sink

        if has_anchor:
            anchors /= anchors.sum()
            anchor_fraction = 0.70 if has_proper else 0.45
            if quoted and has_proper:
                anchor_fraction = 0.85
            residual = anchor_fraction * anchors + (1.0 - anchor_fraction) * local
        else:
            residual = local

        attention[i, 1:i + 1] = (1.0 - sink) * residual

        if quote_boundary:
            in_quote = not in_quote

    return "bos_sink_with_entity_backoff", make_row_stochastic(attention)


def prog_L15H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a secondary self-attention component.
    Punctuation and coordination shift mass from the sink toward the diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        matches = aligned[i]
        word = doc[matches[0]] if matches else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        punctuation = (
            bool(text) and all(not c.isalnum() for c in text)
        ) or pos == "PUNCT"
        whitespace = not text
        continuation = (
            i > 1
            and bool(matches)
            and bool(set(matches).intersection(aligned[i - 1]))
            and not punctuation
        )

        # Early positions strongly prefer the sink; its advantage fades slowly.
        sink = 0.70 + 0.15 * np.exp(-(i - 1) / 3.5)
        sink -= 0.0015 * min(i, 100)

        if pos in ("VERB", "ADJ", "ADV"):
            sink += 0.045
        elif pos in ("NOUN", "PROPN"):
            sink += 0.025
        elif pos == "PRON":
            sink -= 0.035

        if dep in ("ROOT", "ccomp", "xcomp"):
            sink += 0.025
        if pos in ("CCONJ", "SCONJ") or dep == "cc":
            sink -= 0.13

        if punctuation:
            sink -= 0.27 * (1.0 - np.exp(-(i - 1) / 4.0))
        if whitespace:
            sink -= 0.15
        if continuation:
            sink -= 0.07

        if i == 1:
            sink = 0.88 if not punctuation else 0.78

        sink = float(np.clip(sink, 0.30, 0.92))
        attention[i, 0] = sink

        residual = 1.0 - sink
        if i == 1:
            attention[i, i] = residual
            continue

        self_fraction = 0.72
        if punctuation or pos in ("CCONJ", "SCONJ"):
            self_fraction = 0.86
        elif continuation:
            self_fraction = 0.65

        attention[i, i] = residual * self_fraction

        # Remaining mass is weak, causal, and locally biased rather than
        # assigned to an unsupported semantic or dependency target.
        previous = np.arange(1, i)
        background = 0.15 + np.exp(-(i - previous) / 3.0)
        background /= background.sum()
        attention[i, 1:i] = residual * (1.0 - self_fraction) * background

    return "bos_sink_with_self", make_row_stochastic(attention)


def prog_L15H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at boundaries and clause starts.
    Residual attention favors recent tokens and available syntactic governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = aligned[i]
        word = None
        if indices:
            # Prefer a lexical token when an offset includes punctuation too.
            k = max(
                indices,
                key=lambda k: (
                    not doc[k].is_space,
                    not doc[k].is_punct,
                    len(doc[k].text),
                ),
            )
            word = doc[k]

        sink = 0.79
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink = 0.72
            elif pos in ("ADJ", "NUM"):
                sink = 0.73
            elif pos == "VERB":
                sink = 0.76
            elif pos in ("DET", "ADP", "PART"):
                sink = 0.78
            elif pos in ("PRON", "AUX"):
                sink = 0.85
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.87
            elif pos == "ADV":
                sink = 0.82

            if word.dep_ in ("nsubj", "nsubjpass", "expl"):
                sink += 0.025
            if word.is_sent_start:
                sink = max(sink, 0.86)

        if not text:
            sink = 0.89
        elif all(c in ".,!?;:…\"'“”‘’()[]{}—–-" for c in text):
            if any(c in ".!?…" for c in text):
                sink = 0.925
            elif "," in text or ";" in text or ":" in text:
                sink = 0.84
            else:
                sink = 0.84

        if i == 1:
            sink = max(sink, 0.86)

        # A normalized non-sink distribution, strictly over causal positions.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.45
        residual /= residual.sum()
        residual *= 0.40

        targets = []
        if word is not None:
            governor = word.head
            if governor.i != word.i:
                candidates = [j for j in inverse[governor.i] if 0 < j < i]
                if candidates:
                    targets.append(max(candidates))

            # Continuation pieces retain a local within-word connection.
            pieces = [j for j in inverse[word.i] if 0 < j < i]
            if pieces:
                targets.append(max(pieces))

        if targets:
            for j in targets:
                residual[j - 1] += 0.60 / len(targets)
        else:
            residual[-1] += 0.35
            residual[max(0, i - 2)] += 0.25

        residual /= residual.sum()
        sink = float(np.clip(sink, 0.60, 0.95))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_syntactic_residual", attention


def prog_L15H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position bias and weaker causal
    syntactic attention, especially to preceding subjects and nominal anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_to_tokens = [[] for _ in doc]
    representatives = []

    special = set(tokenizer.all_special_tokens)
    for i, word_ids in enumerate(alignment):
        valid = [
            k for k in word_ids
            if 0 <= k < len(doc) and not doc[k].is_space
        ]
        representatives.append(valid[-1] if valid else None)
        if tokens[i] not in special:
            for k in valid:
                word_to_tokens[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        wi = representatives[i]
        word = doc[wi] if wi is not None else None
        pos = word.pos_ if word is not None else ""

        sink = 0.56 + 0.40 * np.exp(-(i - 1) / 7.0)
        if pos == "ADJ":
            sink += 0.19
        elif pos == "VERB":
            sink += 0.16
        elif pos == "ADV":
            sink += 0.09
        elif pos in ("NOUN", "PROPN"):
            sink += 0.04
        elif pos == "AUX":
            sink -= 0.18
        elif pos == "ADP":
            sink -= 0.16
        elif pos == "DET":
            sink -= 0.10
        elif pos == "CCONJ":
            sink -= 0.12

        if word is not None:
            if word.dep_ in ("ROOT", "acomp", "oprd"):
                sink += 0.08
            if word.ent_type_:
                sink += 0.04

        # The initial few tokens have very little competing context.
        early_floor = 0.97 - 0.055 * (i - 1)
        if i <= 3:
            sink = max(sink, early_floor)
        sink = float(np.clip(sink, 0.30, 0.985))

        destinations = np.arange(1, i + 1)
        residual = 0.08 * np.exp(-(i - destinations) / 5.0)
        residual[-1] += 0.025

        for j in range(1, i):
            previous_wi = representatives[j]
            if previous_wi is not None:
                previous = doc[previous_wi]
                if previous.pos_ in ("NOUN", "PROPN", "PRON"):
                    residual[j - 1] += (
                        0.15 * np.exp(-(i - j) / 14.0)
                    )

        if word is not None:
            # Distribute syntactic mass over a word's available subword pieces.
            anchors = [(word.head.i, 1.2)]
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    anchors.append((child.i, 1.5))
                elif child.dep_ in ("dobj", "obj", "pobj", "attr"):
                    anchors.append((child.i, 0.5))

            for anchor, strength in anchors:
                if anchor == wi:
                    continue
                available = [j for j in word_to_tokens[anchor] if 0 < j < i]
                if available:
                    for j in available:
                        residual[j - 1] += strength / len(available)

            # Continuations retain some attention to earlier word pieces.
            pieces = [j for j in word_to_tokens[wi] if 0 < j < i]
            for j in pieces:
                residual[j - 1] += 0.15 / len(pieces)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_syntactic_residual", attention


def prog_L15H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the first token,
    with a small diffuse residual over other causally available tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.97
            attention[i, 1:i + 1] = 0.03 / i

    return "bos_sink_with_diffuse_residual", attention


def prog_L15H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: each query attends almost exclusively to the first token.
    The examples provide no reliable evidence for a linguistic correction.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n:
        attention[:, 0] = 1.0
    return "bos_attention_sink", attention


def prog_L15H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink, with slightly weaker concentration
    on punctuation and a small recency-weighted causal remainder.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        is_punctuation = any(
            doc[k].pos_ == "PUNCT" for k in alignment[i]
        )
        sink_mass = 0.94 if is_punctuation else 0.98

        distances = i - np.arange(1, i + 1)
        remainder = np.exp(-distances / 6.0)
        remainder /= remainder.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

    return "first_token_sink", attention


def prog_L15H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small, recency-weighted causal background.
    Sink dominance weakens mildly with context length and punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )
        sink_mass = 0.985 - 0.045 * (1.0 - np.exp(-i / 55.0))
        if punctuation and tokens[i] not in tokenizer.all_special_tokens:
            sink_mass -= 0.025

        positions = np.arange(1, i + 1)
        background = 0.25 / i + 0.75 * np.exp(-(i - positions) / 5.0)
        background /= background.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_weak_recency", attention


def prog_L15H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token,
    with a weak diffuse causal background that grows with context length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, :i + 1] = 0.0006
        attention[i, 0] = 1.0

    return "bos_sink_with_diffuse_background", make_row_stochastic(attention)


def prog_L15H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: each token attends almost exclusively to the first token."""
    n = len(tokenize(sentence, tokenizer))
    attention_matrix = np.zeros((n, n), dtype=np.float64)
    if n:
        attention_matrix[:, 0] = 1.0
    return "bos_attention_sink", attention_matrix


def prog_L15H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak diffuse causal leakage.
    Accumulating competing keys slightly reduces sink dominance in longer contexts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.tril(np.full((n, n), 0.0006, dtype=np.float64))

    if n:
        attention[:, 0] = 1.0

    return "bos_sink_with_causal_leakage", make_row_stochastic(attention)


def prog_L15H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak, recency-biased residual.
    Sink strength decreases mildly with position and for content/punctuation tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.978 - 0.0012 * min(i, 90)
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                sink -= 0.018
            elif word.pos_ == "PUNCT":
                sink -= 0.035

        sink = float(np.clip(sink, 0.80, 0.99))
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_residual", attention


def prog_L15H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent leakage.
    Non-BOS attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The dominant pattern is attention to the initial token, not a
        # syntactic relation. Longer contexts permit somewhat more leakage.
        leakage_odds = 0.018 * (1.0 + i / 12.0) ** 1.5
        sink_mass = 1.0 / (1.0 + leakage_odds)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_leakage", attention


def prog_L15H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay and a secondary memory
    for clause boundaries and syntactically salient content."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_memory", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    salience = np.ones(n, dtype=np.float64)
    boundary = np.zeros(n, dtype=np.float64)
    content = np.zeros(n, dtype=np.float64)

    for j in range(1, n):
        text = tokens[j].replace("▁", " ").replace("Ġ", " ").strip()
        if tokens[j] in special_tokens:
            salience[j] = 0.05
            continue

        if any(mark in text for mark in (".", "!", "?")):
            boundary[j] = 1.0
            salience[j] = 4.0
        elif any(mark in text for mark in (",", ";", ":")):
            boundary[j] = 0.25
            salience[j] = 1.1
        elif text and all(c in "\"'“”‘’" for c in text):
            salience[j] = 0.45

        for k in alignment[j]:
            word = doc[k]
            if word.pos_ in ("NOUN", "PROPN"):
                content[j] = 1.0
                salience[j] = max(salience[j], 1.5)
            if word.dep_ in ("dobj", "obj", "attr", "pobj"):
                salience[j] = max(salience[j], 2.5)
            if word.pos_ in ("DET", "ADP", "AUX", "CCONJ", "SCONJ"):
                salience[j] *= 0.65

    attention[0, 0] = 1.0
    for i in range(1, n):
        prior_boundaries = boundary[1:i].sum()
        sink = 0.985 * np.exp(-(i - 1) / 100.0)
        sink *= np.exp(-0.09 * prior_boundaries)
        sink += 0.025 * content[i]
        sink = float(np.clip(sink, 0.22, 0.985))

        positions = np.arange(1, i + 1)
        distance = i - positions
        weights = salience[1:i + 1] * np.exp(-distance / 30.0)

        # Favor completed boundaries over punctuation currently being emitted.
        weights += 3.0 * boundary[1:i + 1] * (distance > 0)
        weights[-1] *= 0.35
        if i > 1:
            weights[-2] += 0.25

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_boundary_memory", attention


def prog_L15H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position boost and POS-dependent gating.
    Residual attention favors nearby tokens, self, and causal syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        if ti > 0:
            for sid in sids:
                inverse[sid].append(ti)

    pos_adjustment = {
        "NOUN": 0.11,
        "PROPN": 0.13,
        "ADJ": 0.04,
        "VERB": -0.08,
        "AUX": -0.04,
        "PRON": -0.08,
        "ADP": -0.06,
        "PART": -0.07,
        "ADV": -0.04,
        "SCONJ": -0.09,
        "DET": -0.03,
        "CCONJ": 0.02,
        "PUNCT": 0.04,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[-1]] if sids else None

        sink = 0.62 + 0.31 * np.exp(-(i - 1) / 6.0)
        if word is not None:
            sink += pos_adjustment.get(word.pos_, 0.0)
            if word.ent_type_:
                sink += 0.03

        # The first ordinary token has almost no competing destination.
        if i == 1:
            sink = 0.95

        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if clean and all(c in "\"“”‘’" for c in clean):
            sink -= 0.23
        if clean and all(c in ".!?" for c in clean):
            sink += 0.08

        sink = float(np.clip(sink, 0.28, 0.97))

        positions = np.arange(1, i + 1)
        residual = 0.10 + np.exp(-(i - positions) / 3.0)
        residual[-1] += 0.7

        if word is not None:
            for target in inverse[word.head.i]:
                if 0 < target <= i:
                    residual[target - 1] += 1.1

            # Preserve some within-word attention for split model tokens.
            for sid in sids:
                for target in inverse[sid]:
                    if 0 < target < i:
                        residual[target - 1] += 0.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

    return "bos_sink_with_linguistic_gating", attention


def prog_L15H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with a weak position-dependent leakage to prior content.
    Earlier nominal objects act as secondary anchors rather than syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    salience = np.ones(n, dtype=np.float64)

    for j in range(1, n):
        if tokens[j] in tokenizer.all_special_tokens:
            salience[j] = 0.05
            continue

        features = [doc[k] for k in alignment[j] if k < len(doc)]
        if not features:
            salience[j] = 0.4
            continue

        score = 0.5
        for word in features:
            if word.is_punct or word.is_space:
                candidate = 0.15
            elif word.pos_ in ("NOUN", "PROPN"):
                candidate = 2.0
                if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                    candidate *= 1.7
            elif word.pos_ == "VERB":
                candidate = 1.2
            elif word.pos_ == "ADJ":
                candidate = 0.8
            else:
                candidate = 0.5
            score = max(score, candidate)
        salience[j] = score

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = float(np.clip(0.985 - 0.005 * i, 0.58, 0.98))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        weights = salience[1:i + 1] * (
            0.35 + 0.65 * np.exp(-(i - positions) / 14.0)
        )
        weights[-1] *= 0.6
        attention[i, 1:i + 1] = (1.0 - sink_mass) * weights / weights.sum()

    return "bos_sink_with_content_leakage", attention


def prog_L15H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; quotation openings briefly renew BOS dominance.
    Transfer only non-self fallback mass for quotes and their introductory prefixes.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_prefix", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    special = tokenizer.all_special_tokens

    attention[0, 0] = 1.0
    boundary = None
    in_quote = False
    quote_prefix = False

    for i in range(1, n):
        text = tokens[i]
        clean = text.replace("▁", "").replace("Ġ", "").strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.29 + 0.65 * np.exp(-(i - 1) / 4.2)
        if pos in ("VERB", "AUX"):
            sink += 0.06
        elif pos in ("ADP", "SCONJ", "PART"):
            sink += 0.03
        elif pos in ("ADJ", "ADV"):
            sink -= 0.06

        if word is not None and word.ent_type_:
            sink += 0.09

        continuation = (
            bool(clean)
            and i > 1
            and bool(set(indices).intersection(alignment[i - 1]))
        )
        if continuation:
            sink += 0.12

        apostrophe = bool(clean) and all(c in "'’`" for c in clean)
        whitespace = not clean
        punctuation = bool(clean) and all(not c.isalnum() for c in clean)

        if punctuation:
            sink += 0.10
        if whitespace:
            sink += 0.22
        if clean and all(c in ".!?" for c in clean):
            sink += 0.17
        if apostrophe:
            sink = 0.96
        if text in special:
            sink = max(sink, 0.90)

        head_targets = []
        object_link = False
        if word is not None and word.head.i != word.i:
            head_targets = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            object_link = (
                dep in ("dobj", "obj", "iobj", "dative")
                and word.head.pos_ in ("VERB", "AUX")
                and bool(head_targets)
            )
            if object_link and not continuation:
                sink *= 0.48

        sink = float(np.clip(sink, 0.08, 0.98))
        if i == 1:
            sink = float(np.clip(sink, 0.85, 0.98))

        positions = np.arange(1, i + 1)
        weights = 0.24 * np.exp(-(i - positions) / 5.0)
        weights[-1] += 0.12
        if i > 1:
            weights[-2] += 0.85

        if head_targets:
            target = head_targets[0]
            if object_link and not continuation:
                weights[target - 1] += 4.5
            elif dep in ("pobj", "obl", "nmod", "advmod", "cc"):
                weights[target - 1] += 0.65
            elif dep in ("punct", "conj"):
                weights[target - 1] += 0.35

        if boundary is not None and 0 < i - boundary <= 8:
            weights[boundary - 1] += 1.2 * np.exp(
                -(i - boundary - 1) / 6.0
            )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        # Quoted introductions favor BOS rather than a local predecessor.
        # Preserve the original self-attention and all non-triggered rows.
        quote_here = punctuation and any(c in '"“”«»' for c in clean)
        if quote_here:
            in_quote = not in_quote
            quote_prefix = in_quote

        prefix_token = (
            quote_prefix
            and not quote_here
            and not continuation
            and not apostrophe
            and pos in ("PRON", "DET", "AUX", "VERB")
        )
        if quote_here or prefix_token:
            desired_sink = 0.76 if quote_here else 0.66
            available = float(attention[i, 1:i].sum())
            transfer = min(
                max(0.0, desired_sink - attention[i, 0]), available
            )
            if available > 0.0 and transfer > 0.0:
                attention[i, 1:i] *= (available - transfer) / available
                attention[i, 0] += transfer

        if not quote_here and pos in ("VERB", "NOUN", "PROPN", "ADJ"):
            quote_prefix = False

        if clean and any(c in ".!?" for c in clean) and punctuation:
            boundary = i

    return "bos_sink_with_quote_prefix", make_row_stochastic(attention)


def prog_L15H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker recency and clause-governor attention.
    Complement clauses and opening quotations can redirect mass to their governing verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_governors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(aligned):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        word_ids = aligned[i]
        word = doc[word_ids[-1]] if word_ids else None

        # The sink is strongest near the beginning, but remains dominant later.
        sink = 0.58 + 0.35 * np.exp(-(i - 1) / 5.5)
        if word is not None:
            if word.pos_ in ("ADP", "CCONJ", "SCONJ"):
                sink += 0.05
            if word.ent_type_:
                sink += 0.05
            if word.pos_ in ("VERB", "AUX") and i > 5:
                sink -= 0.07

        is_quote = clean in ('"', "“", "”", "«", "»", "``", "''")
        if not clean:
            sink = max(sink, 0.86)
        elif clean in ("'", "’"):
            sink = max(sink, 0.92)
        elif any(c in clean for c in (".", "!", "?")):
            sink = max(sink, 0.83)

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.15 + np.exp(-(i - positions) / 4.0)
        governor = None
        governor_strength = 0.0

        if word is not None:
            node = word
            for _ in range(12):
                head = node.head
                if head.i == node.i:
                    break
                if node.dep_ in ("ccomp", "xcomp") and head.pos_ == "VERB":
                    candidates = [j for j in inverse[head.i] if 0 < j < i]
                    if candidates:
                        governor = candidates[0]
                        governor_strength = 0.70 if node.dep_ == "ccomp" else 0.38
                        break
                node = head

        # Opening quotation marks often point back to a reporting predicate.
        if is_quote and word is not None and word.is_left_punct:
            for wi in range(word.i - 1, max(-1, word.i - 7), -1):
                if doc[wi].pos_ == "VERB":
                    candidates = [j for j in inverse[wi] if 0 < j < i]
                    if candidates:
                        governor = candidates[0]
                        governor_strength = 0.58
                        break

        if governor is not None:
            distance = i - governor
            strength = governor_strength * np.exp(-max(0, distance - 3) / 9.0)
            if clean not in ("'", "’") and not any(c in clean for c in (".", "!", "?")):
                sink = min(sink, 1.0 - strength - 0.08)
            residual[governor] += 6.0 * strength * residual.sum()

        sink = float(np.clip(sink, 0.20, 0.97))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_clause_governors", attention


def prog_L15H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a strong prefix bias and weaker noun-centered,
    recency-weighted attention, especially at punctuation boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_nominal_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[ids[0]] if ids else None
        for ids in alignment
    ]
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        raw = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = raw.strip()
        is_space = not stripped
        is_punct = (
            word is not None and word.is_punct
        ) or (
            bool(stripped)
            and all(not c.isalnum() for c in stripped)
        )
        is_apostrophe = stripped in ("'", "’")

        sink = 0.58 + 0.28 * np.exp(-(i - 1) / 5.0)
        if pos == "VERB":
            sink += 0.12
        elif pos in ("NOUN", "PROPN"):
            sink -= 0.065
        elif pos in ("ADJ", "ADV"):
            sink -= 0.035
        elif pos in ("DET", "ADP"):
            sink += 0.025
        elif pos == "PRON":
            sink -= 0.02

        if is_punct:
            sink -= 0.12
        if is_apostrophe:
            sink += 0.37
        if is_space:
            sink += 0.19
        sink = float(np.clip(sink, 0.30, 0.95))

        residual = np.zeros(i, dtype=np.float64)
        for j in range(1, i + 1):
            candidate = words[j]
            distance = i - j
            score = np.exp(-distance / 7.0) + 0.025

            if candidate is not None:
                if candidate.pos_ in ("NOUN", "PROPN"):
                    score *= 3.2
                elif candidate.pos_ in ("DET", "ADP", "PUNCT"):
                    score *= 0.45

                if word is not None:
                    if candidate.i == word.head.i and candidate.i != word.i:
                        score *= 1.6
                    if is_punct and candidate.pos_ in ("NOUN", "PROPN"):
                        score *= 2.0
                    if candidate.i == word.i and j != i:
                        score *= 1.3

            if j == i:
                score *= 0.55
            residual[j - 1] = score

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_nominal_residual", attention


def prog_L15H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a gradually stronger self-attention component.
    Punctuation weakens the sink; remaining attention favors nearby tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self_and_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()

        is_punct = (
            word.is_punct if word is not None
            else bool(surface) and all(
                not char.isalnum() and not char.isspace() for char in surface
            )
        )
        is_space = not surface
        pos = word.pos_ if word is not None else ""

        sink_mass = 0.865 - 0.0038 * (i - 1)
        sink_mass = max(0.57, sink_mass)

        if pos in ("NOUN", "PROPN", "ADJ"):
            sink_mass += 0.02
        elif pos == "DET":
            sink_mass -= 0.045

        if is_punct:
            sink_mass -= 0.20
        elif is_space:
            sink_mass -= 0.14

        sink_mass = float(np.clip(sink_mass, 0.28, 0.93))
        residual = 1.0 - sink_mass
        self_fraction = 0.84 if is_punct else 0.70

        attention[i, 0] = sink_mass
        if i == 1:
            attention[i, i] = residual
            continue

        attention[i, i] = residual * self_fraction
        positions = np.arange(1, i)
        recent_weights = np.exp(-(i - positions) / 4.0)
        recent_weights /= recent_weights.sum()
        attention[i, 1:i] = residual * (1.0 - self_fraction) * recent_weights

    return (
        "bos_sink_with_self_and_recency",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L15H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with dialogue-triggered retrieval of quote boundaries and discourse entities.
    After a quotation, redirect excess sink/reporting mass without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_memory", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, sids in enumerate(aligned):
        for sid in sids:
            inverse[sid].append(i)

    attention[0, 0] = 1.0
    quote_open = False
    reporting_token = None
    closure_token = None
    closure_position = -10
    last_verb = None

    # Additional state is used only after a completed quotation.
    quote_boundaries = []
    first_quote_end = None

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        sids = aligned[i]
        word = doc[sids[0]] if sids else None
        pos = word.pos_ if word is not None else ""
        punctuation = bool(text) and all(
            c in ".,!?;:—–-()[]{}\"'“”‘’…" for c in text
        )

        closed_here = False
        for char in text:
            if char in '"“”':
                opening = char == "“" or (char == '"' and not quote_open)
                if opening:
                    quote_open = True
                    reporting_token = last_verb
                    quote_boundaries.append((i, False))
                else:
                    if quote_open:
                        quote_boundaries.append((i, True))
                        if first_quote_end is None:
                            first_quote_end = i
                    if quote_open and reporting_token is not None:
                        closure_token = reporting_token
                        closure_position = i
                        closed_here = True
                    quote_open = False

        # Original sink and ordinary-context channels.
        sink = 0.88 - 0.0025 * min(i, 100)
        if pos in ("NOUN", "PROPN", "ADJ"):
            sink += 0.055
        elif pos in ("VERB", "AUX", "PART", "SCONJ"):
            sink -= 0.12
        elif pos in ("PRON", "ADP", "CCONJ"):
            sink -= 0.045
        if punctuation:
            sink -= 0.13
        if i == 1:
            sink = 0.97
        sink = float(np.clip(sink, 0.35, 0.97))

        positions = np.arange(1, i + 1)
        weights = np.exp(-(i - positions) / 7.0)
        if word is not None:
            head_indices = inverse[word.head.i]
            for j in head_indices:
                if 0 < j <= i:
                    weights[j - 1] += 1.2
        if last_verb is not None and last_verb < i:
            weights[last_verb - 1] += 0.7

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        # Preserve the original quotation-closure channel.
        elapsed = i - closure_position
        if closure_token is not None and 0 <= elapsed <= 3:
            strength = 0.53 if closed_here else 0.53 * np.exp(-elapsed / 5.0)
            attention[i] *= 1.0 - strength
            attention[i, closure_token] += strength

        # Completed dialogue introduces persistent boundary/entity retrieval.
        # Transfer only off-diagonal mass; ordinary prose is unchanged.
        if first_quote_end is not None and text:
            memory = np.zeros(n, dtype=np.float64)
            for j, is_end in quote_boundaries:
                if 0 < j < i:
                    memory[j] += (2.5 if is_end else 0.7) * np.exp(
                        -(i - j) / 24.0
                    )

            for candidate in doc:
                indices = inverse[candidate.i]
                if not indices:
                    continue
                j = indices[-1]
                if not 0 < j < i:
                    continue
                if candidate.pos_ in ("NOUN", "PROPN"):
                    salience = (
                        1.2 if candidate.dep_ in
                        ("nsubj", "nsubjpass", "dobj", "obj", "pobj", "attr")
                        else 0.5
                    )
                elif candidate.dep_ == "prt":
                    salience = 0.8
                elif candidate.pos_ == "VERB":
                    salience = 0.3
                else:
                    continue
                memory[j] += salience * np.exp(-(i - j) / 40.0)

            if memory.sum() > 0:
                age = i - first_quote_end
                fraction = 0.22 + 0.60 * (1.0 - np.exp(-age / 20.0))
                if pos in ("ADP", "AUX", "PRON", "DET", "CCONJ", "SCONJ"):
                    fraction += 0.10
                moved = attention[i, 0] * min(fraction, 0.90)
                attention[i, 0] -= moved

                # A closing quote is not solely a reporting-verb lookup.
                if closure_token is not None and 0 <= elapsed <= 3:
                    if 0 < closure_token < i:
                        redirected = min(
                            attention[i, closure_token], 0.75 * strength
                        )
                        attention[i, closure_token] -= redirected
                        moved += redirected

                attention[i] += moved * memory / memory.sum()

        if pos == "VERB":
            last_verb = i

    return "bos_sink_with_dialogue_memory", make_row_stochastic(attention)


def prog_L16H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with governor routing; short introductory prepositional phrases
    create a persistent phrase-final/comma sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_introductory_phrase", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(aligned):
        for sid in sids:
            if sid < len(doc):
                inverse[sid].append(ti)

    # Restrict the added path to a short, verbless initial PP ending in a comma.
    intro_anchor = None
    intro_comma = None
    intro_stop = n
    if len(doc) and doc[0].pos_ == "ADP":
        for w in doc:
            if w.i > 6 or w.pos_ in ("VERB", "AUX"):
                break
            if w.text == ",":
                anchors = [
                    c for c in doc[:w.i]
                    if c.pos_ in ("NOUN", "PROPN", "PRON", "ADV")
                ]
                if anchors and inverse[anchors[-1].i] and inverse[w.i]:
                    intro_anchor = inverse[anchors[-1].i][-1]
                    intro_comma = inverse[w.i][-1]
                    for later in doc[w.i + 1:]:
                        if later.is_punct and later.text in (",", ";", ".", "!", "?"):
                            if inverse[later.i]:
                                intro_stop = inverse[later.i][0]
                            break
                break

    special_tokens = tokenizer.all_special_tokens
    last_boundary = None

    for i, token in enumerate(tokens):
        if i == 0 or token in special_tokens:
            attention[i, 0] = 1.0
            continue

        clean = token.replace("▁", " ").replace("Ġ", " ").strip()
        sids = aligned[i]
        word = doc[sids[-1]] if sids else None
        pos = word.pos_ if word is not None else ""

        sink = 0.83
        if pos in ("ADJ", "ADV", "ADP", "PART", "DET"):
            sink = 0.89
        elif pos in ("VERB", "AUX"):
            sink = 0.79
        elif pos in ("NOUN", "PROPN"):
            sink = 0.78
        elif pos == "PRON":
            sink = 0.75
        elif pos in ("CCONJ", "SCONJ"):
            sink = 0.73
        elif pos == "PUNCT":
            sink = 0.69

        if i == 1:
            sink = 0.91

        attention[i, 0] = sink
        attention[i, i] += (1.0 - sink) * 0.55
        attention[i, i - 1] += (1.0 - sink) * 0.45

        target = None
        strength = 0.0
        if word is not None:
            head = word.head
            if (
                word.dep_ in ("dobj", "obj", "iobj", "dative", "attr", "oprd")
                and head.pos_ in ("VERB", "AUX")
            ):
                target = head
                strength = 0.66 if pos in ("NOUN", "PROPN") else 0.19

            elif word.dep_ in ("det", "poss") and head.dep_ in (
                "dobj", "obj", "iobj", "dative"
            ):
                if head.head.pos_ in ("VERB", "AUX"):
                    target = head.head
                    strength = 0.40

            elif word.dep_ in ("nsubj", "nsubjpass", "nsubj:pass"):
                if (
                    head.dep_ in ("ccomp", "xcomp")
                    and head.head.pos_ in ("VERB", "AUX")
                ):
                    target = head.head
                    strength = 0.54

            if target is not None:
                candidates = [j for j in inverse[target.i] if 0 < j < i]
                if candidates:
                    j = candidates[0]
                    attention[i] *= 1.0 - strength
                    attention[i, j] += strength

        terminal = bool(clean) and any(c in ".?!" for c in clean)
        punctuation_only = bool(clean) and all(
            not c.isalnum() for c in clean
        )

        if last_boundary is not None and not terminal:
            distance = i - last_boundary
            if distance <= 6:
                strength = 0.57 * np.exp(-(distance - 1) / 2.8)
                if not clean:
                    strength = 0.80
                attention[i] *= 1.0 - strength
                attention[i, last_boundary] += strength

        if terminal and punctuation_only:
            attention[i] *= 0.42
            attention[i, i] += 0.58
            last_boundary = i

        # Transfer only BOS mass; all other baseline weights remain intact.
        if intro_anchor is not None and intro_anchor <= i < intro_stop:
            if i == intro_anchor:
                moved = min(attention[i, 0], 0.35)
                attention[i, 0] -= moved
                attention[i, intro_anchor] += moved
            elif i == intro_comma:
                moved = min(attention[i, 0], 0.50)
                attention[i, 0] -= moved
                attention[i, intro_anchor] += moved
            elif i > intro_comma and not terminal:
                distance = i - intro_comma
                if distance <= 12:
                    amount = 0.64
                    if pos in ("ADJ", "ADV"):
                        amount = 0.25
                    elif pos in ("VERB", "AUX"):
                        amount = 0.36
                    amount *= np.exp(-max(0, distance - 7) / 3.0)
                    moved = min(attention[i, 0], amount)
                    attention[i, 0] -= moved
                    attention[i, intro_anchor] += moved * 0.53
                    attention[i, intro_comma] += moved * 0.47

    return (
        "bos_sink_with_introductory_phrase",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L16H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with residual attention to recent predicates and
    clause-ending punctuation, especially across dialogue boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_landmarks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]

    # Keys representing completed propositions remain useful after a boundary.
    salience = np.full(n, 0.025, dtype=np.float64)
    for j in range(1, n):
        w = words[j]
        text = clean[j]
        if w is not None:
            if w.pos_ in ("VERB", "AUX"):
                salience[j] += 0.35
                if w.dep_ in ("ROOT", "conj", "ccomp", "advcl", "xcomp"):
                    salience[j] += 0.65
            elif w.pos_ == "ADJ":
                salience[j] += 0.45
                if w.dep_ in ("ROOT", "acomp", "attr", "xcomp", "conj"):
                    salience[j] += 1.1
            elif w.pos_ in ("NOUN", "PROPN"):
                salience[j] += 0.08
        if any(c in text for c in "?!"):
            salience[j] += 2.8
        elif "." in text and all(c in ".\"'”’" for c in text):
            salience[j] += 1.5

    attention[0, 0] = 1.0
    for i in range(1, n):
        w = words[i]
        text = clean[i]

        # Early queries overwhelmingly use the sink; later queries are mixed.
        sink = 0.67 + 0.29 * np.exp(-(i - 1) / 7.0)
        if w is not None:
            if w.pos_ in ("ADJ", "NOUN", "PROPN"):
                sink += 0.07
            elif w.pos_ in ("CCONJ", "SCONJ", "PRON", "ADV"):
                sink -= 0.07
            elif w.pos_ == "PUNCT":
                sink -= 0.18

        if text in ("'", "’"):
            sink = 0.96
        elif text and all(c in "\"“”" for c in text):
            sink -= 0.16
        elif not text:
            sink += 0.01

        if tokens[i] in special:
            sink = 0.98
        sink = float(np.clip(sink, 0.32, 0.985))

        indices = np.arange(1, i + 1)
        distances = i - indices
        residual = salience[1:i + 1] * np.exp(-distances / 22.0)
        residual += 0.025 * np.exp(-distances / 3.0)

        # A current predicate is not yet a completed preceding landmark.
        residual[-1] *= 0.12
        if i > 1:
            residual[-2] += 0.08

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_clause_landmarks", make_row_stochastic(attention)


def prog_L16H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with object-to-predicate retrieval gated by subtoken completion.
    Split objects and prepositional objects can instead retrieve nominal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_completion_gated_objects", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = None
        if indices:
            # Prefer the lexical token when an offset also overlaps punctuation.
            k = max(indices, key=lambda k: (
                not doc[k].is_punct and not doc[k].is_space,
                len(doc[k].text)
            ))
            word = doc[k]

        sink = 0.65
        target = None
        strength = 0.0

        if word is not None:
            pos = word.pos_
            dep = word.dep_
            head = word.head

            # First subtoken of a preceding syntactic governor.
            candidates = [j for j in inverse[head.i] if 0 < j < i]
            governor = min(candidates) if candidates else None

            if pos in ("NOUN", "PROPN", "PRON"):
                if dep in ("dobj", "obj", "iobj", "dative", "attr", "oprd"):
                    if head.pos_ in ("VERB", "AUX") and governor is not None:
                        sink = 0.13
                        target = governor
                        strength = 0.80
                elif dep in ("pobj", "obl"):
                    if governor is not None:
                        sink = 0.40
                        target = governor
                        strength = 0.43
                    # Objects of prepositions also weakly retrieve the predicate.
                    ancestor = head.head
                    if head.pos_ == "ADP" and ancestor.pos_ == "VERB":
                        earlier = [j for j in inverse[ancestor.i] if 0 < j < i]
                        if earlier:
                            sink = 0.34
                            target = min(earlier)
                            strength = 0.49
                elif dep == "conj":
                    ancestor = head.head
                    earlier = [j for j in inverse[ancestor.i] if 0 < j < i]
                    if head.dep_ in ("dobj", "obj", "iobj", "pobj", "obl") and earlier:
                        sink = 0.34
                        target = min(earlier)
                        strength = 0.47
                elif dep in ("nsubj", "nsubjpass", "csubj"):
                    sink = 0.61
                    if governor is not None:
                        target = governor
                        strength = 0.22
            elif pos in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
                sink = 0.73
            elif pos == "AUX":
                sink = 0.79
            elif pos == "VERB":
                sink = 0.68
            elif pos in ("ADJ", "ADV"):
                sink = 0.59

        punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )
        if raw in special_tokens or not clean or punctuation:
            sink, target, strength = 0.91, None, 0.0
        elif i == 1:
            sink, target, strength = 0.94, None, 0.0
        elif word is not None and word.is_sent_start:
            sink, target, strength = 0.88, None, 0.0

        # Small causal background prevents unsupported edges from being zero.
        positions = np.arange(i + 1)
        background = np.exp(-(i - positions) / 3.5)
        background[0] = 0.0
        background /= background.sum()
        residual = max(0.0, 1.0 - sink - strength)
        attention[i, :i + 1] = residual * background
        attention[i, 0] += sink
        if target is not None:
            attention[i, target] += strength

        # Redirect only explicit retrieval mass; self-attention and the original
        # causal background remain exactly unchanged.
        if (
            word is not None
            and word.pos_ in ("NOUN", "PROPN")
            and target is not None
            and strength > 0.0
        ):
            pieces = sorted(set(j for j in inverse[word.i] if j > 0))
            split = len(pieces) > 1
            prepositional = word.dep_ in ("pobj", "obl")
            if split or (
                prepositional and doc[
                    max(alignment[target], key=lambda k: len(doc[k].text))
                ].pos_ in ("VERB", "AUX")
            ):
                dets = [
                    j
                    for child in word.children
                    if child.dep_ in ("det", "poss")
                    for j in inverse[child.i]
                    if 0 < j < i
                ]
                det = min(dets) if dets else None
                preps = [
                    j
                    for prep in (
                        [word.head] if word.head.pos_ == "ADP"
                        else [c for c in word.children if c.dep_ == "case"]
                    )
                    for j in inverse[prep.i]
                    if 0 < j < i
                ]
                prep = min(preps) if preps else None

                if split and i != pieces[-1]:
                    fraction = 0.80 if i == pieces[0] else 0.96
                    moved = strength * fraction
                    attention[i, target] -= moved
                    attention[i, 0] += moved
                else:
                    fraction = (
                        0.90 if prepositional and split
                        else 0.75 if prepositional
                        else 0.80 if len(pieces) > 2
                        else 0.25
                    )
                    moved = strength * fraction
                    attention[i, target] -= moved
                    if prepositional and split:
                        attention[i, prep if prep is not None else 0] += moved * 0.55
                        attention[i, det if det is not None else 0] += moved * 0.45
                    elif prepositional:
                        attention[i, 0] += moved * 0.65
                        attention[i, prep if prep is not None else 0] += moved * 0.35
                    else:
                        attention[i, det if det is not None else 0] += moved * 0.70
                        attention[i, 0] += moved * 0.30

    return (
        "bos_sink_with_completion_gated_objects",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L16H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant BOS attention sink, with residual self-attention and weak local syntax.
    Clause boundaries and punctuation shift some sink mass toward the current token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self_and_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        sink = 0.75 - 0.10 * (1.0 - np.exp(-(i - 1) / 30.0))
        self_share = 0.72

        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN", "ADJ", "VERB"):
                sink += 0.045
            elif pos in ("CCONJ", "SCONJ"):
                sink -= 0.10
            elif pos == "DET":
                sink -= 0.035
                self_share = 0.86

            if word.is_punct:
                sink -= 0.18
                self_share = 0.86
                if word.text in ('"', "“", "‘", "«"):
                    sink += 0.23
                    self_share = 0.72

            if word.is_sent_start and i > 1:
                sink -= 0.14
                self_share = 0.90

            if i > 1 and any(wi in alignment[i - 1] for wi in word_ids):
                sink -= 0.035

        sink = float(np.clip(sink, 0.30, 0.91))
        attention[i, 0] = sink

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = self_share

        # Nearby context provides a small, causal background component.
        if i > 1:
            positions = np.arange(1, i)
            local = np.exp(-(i - positions) / 2.0)
            residual[1:i] += (1.0 - self_share) * local / local.sum()
        else:
            residual[i] += 1.0 - self_share

        # Only use dependency heads already visible to the query.
        if word is not None and word.head.i != word.i:
            candidates = [
                ti for ti in inverse[word.head.i] if 0 < ti < i
            ]
            if candidates:
                residual[candidates[-1]] += 0.06

        attention[i, :i + 1] += (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_self_and_local_syntax", attention


def prog_L16H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with an alternate initial-determiner sink in definite-subject narratives.
    Quoted spans can redirect that sink to their opening boundary."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_definite_subject_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    coverage = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            coverage[k].append(i)

    opening_quote = None
    last_closing_quote = None
    quote_chars = {'"', '“', '”', '«', '»'}
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        sink = 0.70
        if word is not None:
            if word.pos_ in {"DET", "ADP", "PART", "PRON"}:
                sink += 0.06
            elif word.pos_ in {"VERB", "AUX"}:
                sink -= 0.05
            elif word.pos_ == "PUNCT":
                sink -= 0.10

            if word.dep_ in {"poss", "case", "mark"}:
                sink += 0.04

            pieces = coverage[word.i]
            if len(pieces) > 1:
                sink += 0.15 if i == pieces[0] else 0.04

        if text in {"'", "’"}:
            sink = 0.92
        if not text:
            sink = 0.81
        if i == 1:
            sink = 0.86

        has_quote = any(c in quote_chars for c in text)
        closing = has_quote and opening_quote is not None
        quote_anchor = opening_quote
        quote_mass = 0.0

        if quote_anchor is not None:
            quote_mass = 0.31
            sink -= 0.17
        elif last_closing_quote is not None:
            distance = i - last_closing_quote
            quote_mass = 0.15 * np.exp(-distance / 5.0)
            quote_anchor = last_closing_quote

        if has_quote and not closing:
            sink = max(sink, 0.80)
        elif closing:
            quote_mass *= 0.65

        sink = float(np.clip(sink, 0.35, 0.95))
        quote_mass = min(quote_mass, 0.95 - sink)
        residual = 1.0 - sink - quote_mass

        positions = np.arange(1, i + 1)
        background = (
            0.55 * np.exp(-(i - positions) / 5.0)
            + 0.25 * np.exp(-(positions - 1) / 4.0)
            + 0.20 / i
        )
        background /= background.sum()
        attention[i, 1:i + 1] = residual * background
        attention[i, 0] = sink
        if quote_anchor is not None:
            attention[i, quote_anchor] += quote_mass

        if has_quote:
            if closing:
                last_closing_quote = i
                opening_quote = None
            else:
                opening_quote = i

    # Special case: an initial subject determiner becomes an alternate sink.
    # Only move BOS mass; all existing self-attention and background weights stay.
    if (
        len(doc) > 0
        and doc[0].pos_ == "DET"
        and doc[0].dep_ == "det"
        and doc[0].head.dep_ in {"nsubj", "nsubjpass"}
        and coverage[0]
    ):
        initial_anchor = coverage[0][0]
        subject_pieces = coverage[doc[0].head.i]
        subject_anchor = subject_pieces[-1] if subject_pieces else initial_anchor
        clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
        active_quote = None
        quote_prefix = None
        recent_close = None

        for i in range(initial_anchor + 1, n):
            text = clean[i]
            word = doc[alignment[i][0]] if alignment[i] else None
            ordinary_quote = any(c in quote_chars for c in text)

            # Recognize split UTF-8-mojibake quotation punctuation as well.
            encoded_open = (
                i >= 2 and text == "œ"
                and clean[i - 1] == "€" and clean[i - 2] == "â"
            )
            encoded_close = (
                i >= 1 and text == "€" and clean[i - 1] == "â"
                and (i + 1 == n or clean[i + 1] != "œ")
            )
            closes = active_quote is not None and (ordinary_quote or encoded_close)

            if active_quote is not None and not closes:
                target_sink = 0.18
                if word is not None and word.pos_ in {"DET", "ADP", "PART", "PRON", "AUX"}:
                    target_sink = 0.32
                if text in {"'", "’"}:
                    target_sink = 0.58
                moved = max(0.0, attention[i, 0] - target_sink)
                attention[i, 0] -= moved
                attention[i, active_quote] += moved * (0.8 if quote_prefix is not None else 1.0)
                if quote_prefix is not None:
                    attention[i, quote_prefix] += moved * 0.2
            elif not encoded_open and not ordinary_quote and not encoded_close or closes:
                amount = 0.22
                if word is not None:
                    if word.pos_ == "PUNCT":
                        amount = 0.36
                    elif word.pos_ == "VERB":
                        amount = 0.30
                    elif word.pos_ in {"DET", "ADP", "PART", "PRON", "AUX"}:
                        amount = 0.15
                    elif word.pos_ == "NOUN" and word.dep_ in {"nsubj", "nsubjpass"}:
                        amount = 0.27
                    elif word.pos_ == "ADJ" and i < subject_anchor:
                        amount = 0.0
                if not text:
                    amount = 0.38
                moved = min(amount, max(0.0, attention[i, 0] - 0.12))
                attention[i, 0] -= moved
                boundary_share = (
                    0.65 * np.exp(-(i - recent_close) / 8.0)
                    if recent_close is not None else 0.0
                )
                attention[i, initial_anchor] += moved * (1.0 - boundary_share)
                if recent_close is not None:
                    attention[i, recent_close] += moved * boundary_share

            if closes:
                recent_close = i
                active_quote = None
                quote_prefix = None
            elif encoded_open or ordinary_quote:
                active_quote = i
                quote_prefix = i - 2 if encoded_open else None

    return "bos_sink_with_definite_subject_anchors", make_row_stochastic(attention)


def prog_L16H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with syntactic local residuals and quoted-boundary anchors."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    boundary = None

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = aligned[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = {
            "VERB": 0.87,
            "AUX": 0.90,
            "PRON": 0.85,
            "ADV": 0.79,
            "CCONJ": 0.81,
            "SCONJ": 0.73,
            "ADJ": 0.70,
            "NOUN": 0.58,
            "PROPN": 0.62,
            "DET": 0.63,
            "ADP": 0.50,
            "PART": 0.77,
            "NUM": 0.57,
            "INTJ": 0.78,
            "PUNCT": 0.76,
        }.get(pos, 0.68)

        if dep in ("nsubj", "nsubjpass", "csubj") and pos == "PRON":
            sink = 0.89
        if dep in ("ROOT", "aux", "auxpass", "cop"):
            sink = max(sink, 0.89)
        if dep in ("poss", "nmod:poss"):
            sink = 0.29
        if dep in ("amod", "compound"):
            sink = min(sink, 0.58)
        if i == 1:
            sink = 0.86

        terminal = any(c in text for c in ".!?")
        quoted_end = terminal and any(c in text for c in "\"”’")
        if terminal:
            sink = 0.87
        if quoted_end and "?" in text:
            sink = 0.43
        if not text:
            sink = 0.66

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[1:] = 0.12 * np.exp(
            -(i - np.arange(1, i + 1)) / 3.0
        )
        residual[i] += 0.55
        if i > 1:
            residual[i - 1] += 0.65

        if word is not None:
            head_indices = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_indices:
                residual[head_indices[-1]] += 1.1

            # Possessive determiners often anchor on the preceding predicate.
            if dep in ("poss", "nmod:poss"):
                for j in range(i - 1, 0, -1):
                    if any(doc[k].pos_ in ("VERB", "AUX") for k in aligned[j]):
                        residual[j] += 4.0
                        break

        if quoted_end and "?" in text:
            residual[i] += 12.0

        # A new clause after quoted speech can use its closing punctuation
        # instead of the global sink, especially on its first determiner.
        if boundary is not None and i - boundary <= 3:
            if text and not all(c in "\"'“”‘’" for c in text):
                if pos in ("DET", "PROPN") and i - boundary <= 2:
                    sink = min(sink, 0.18)
                    residual[boundary] += 14.0
                elif pos in ("NOUN", "PROPN"):
                    sink = min(sink, 0.46)
                    residual[boundary] += 1.2

        attention[i, 0] = sink
        attention[i, :i + 1] += (1.0 - sink) * residual / residual.sum()

        if quoted_end:
            boundary = i

    return "bos_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L16H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker local syntactic/recency attention.
    Early tokens favor BOS most strongly; standalone whitespace favors its predecessor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = text.strip()
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[-1]]

        sink = 0.77 + 0.15 * np.exp(-(i - 1) / 4.0)

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink -= 0.11
            elif word.pos_ == "PRON":
                sink -= 0.08
            elif word.pos_ in ("VERB", "ADJ", "ADV"):
                sink += 0.025
            if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink -= 0.045

        if stripped and all(c in ".,;:!?\"'’“”„()-—…" for c in stripped):
            if stripped in ("'", "’"):
                sink = 0.90
            elif any(c in ".!?" for c in stripped):
                sink = 0.82
            elif "," in stripped:
                sink = 0.65
            else:
                sink = 0.76

        whitespace_only = not stripped
        if whitespace_only:
            sink = 0.28

        if i == 1:
            sink = 0.93

        sink = float(np.clip(sink, 0.20, 0.96))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 2.3)
        residual[-1] *= 0.55

        if i > 1:
            residual[-2] += 1.2
            if whitespace_only:
                residual[-2] += 12.0

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.65

            # A punctuation token may retain attention on the preceding word.
            if word.pos_ == "PUNCT" and i > 1:
                residual[-2] += 1.5

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_residual", attention


def prog_L16H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened at boundaries and sentence onset,
    with residual attention to recent tokens and preceding syntactic governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = None
        if indices:
            word = doc[max(indices, key=lambda k: len(doc[k].text))]

        sink = 0.43 + 0.52 * np.exp(-(i - 1) / 3.0)
        if word is not None:
            if word.pos_ == "PROPN":
                sink += 0.20
            elif word.pos_ in ("NOUN", "ADJ", "ADV"):
                sink += 0.07
            elif word.pos_ in ("VERB", "AUX", "ADP", "PART"):
                sink -= 0.12
            elif word.pos_ == "PRON":
                sink -= 0.06

            if word.ent_type_:
                sink += 0.04
            if word.is_sent_start and i > 1:
                sink += 0.12

        if not clean:
            sink = max(sink, 0.87)
        elif clean in ("'", "’"):
            sink = max(sink, 0.95)
        elif any(c in ".!?" for c in clean) and all(
            not c.isalnum() for c in clean
        ):
            sink = max(sink, 0.84)
        elif all(not c.isalnum() for c in clean):
            sink = max(sink, 0.50)

        if raw in tokenizer.all_special_tokens:
            sink = max(sink, 0.95)
        if i == 1:
            sink = 0.955
        sink = float(np.clip(sink, 0.20, 0.98))

        positions = np.arange(1, i + 1)
        residual = 0.12 + np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.30

        if word is not None:
            # Ancestors provide causal governors even when the immediate
            # syntactic head lies to the right.
            ancestor = word
            for depth in range(3):
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head
                candidates = [
                    j for j in inverse[ancestor.i] if 0 < j < i
                ]
                if candidates:
                    j = candidates[-1]
                    residual[j - 1] += 2.8 / (depth + 1)
                    break

            # Keep split words locally coherent without assuming lexical identity.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                residual[earlier_pieces[-1] - 1] += 0.8

            # A preceding auxiliary or modifier is another plausible local key.
            for child in word.children:
                if child.dep_ in ("aux", "auxpass", "cop", "advmod", "mark"):
                    candidates = [
                        j for j in inverse[child.i] if 0 < j < i
                    ]
                    if candidates:
                        residual[candidates[-1] - 1] += 1.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_syntax", attention


def prog_L16H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent leakage.
    Residual attention favors recent content tokens and available syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_leakage", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        # Growing competition from ordinary keys gradually weakens the sink.
        sink_logit = 3.25 - 0.90 * np.log(float(i))
        if word is not None:
            if word.pos_ in ("VERB", "ADJ", "PROPN"):
                sink_logit += 0.48
            elif word.pos_ == "NOUN":
                sink_logit += 0.20
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "PART"):
                sink_logit -= 0.52
            elif word.pos_ == "PUNCT":
                sink_logit -= 0.28
            if word.dep_ == "ROOT":
                sink_logit += 0.25

        # Preserve the particularly strong initial-position sink.
        if i == 1:
            sink_logit = 3.30

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        weights = np.zeros(i, dtype=np.float64)

        for j in range(1, i + 1):
            distance = i - j
            weight = 0.30 + np.exp(-distance / 7.0)
            previous_ids = alignment[j]
            if previous_ids:
                previous = doc[previous_ids[-1]]
                if previous.pos_ in ("NOUN", "PROPN"):
                    weight *= 2.0
                elif previous.pos_ in ("VERB", "ADJ"):
                    weight *= 1.35
                elif previous.pos_ == "PUNCT":
                    weight *= 0.60
            if j == i:
                weight *= 0.65
            weights[j - 1] = weight

        if word is not None:
            for j in inverse[word.head.i]:
                if 1 <= j <= i and word.head.i != word.i:
                    weights[j - 1] *= 1.8

        matrix[i, 0] = sink_mass
        matrix[i, 1:i + 1] = (1.0 - sink_mass) * weights / weights.sum()

    return "bos_sink_with_content_leakage", matrix


def prog_L16H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with position-dependent weakening and a secondary self/local bias.
    Linguistic features mildly modulate sink strength, especially at punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self_and_recency", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in aligned[i]]
        pos = words[0].pos_ if words else ""
        is_punct = bool(words) and all(w.is_punct for w in words)
        is_space = bool(words) and all(w.is_space for w in words)

        # A strong initial sink persists, but competes increasingly with self.
        sink = 0.32 + 0.51 * np.exp(-(i - 1) / 19.0)
        if pos in ("ADJ", "ADV"):
            sink += 0.055
        elif pos in ("NOUN", "PROPN"):
            sink += 0.035
        elif pos in ("PRON", "AUX", "CCONJ", "SCONJ"):
            sink -= 0.045
        if is_punct:
            sink -= 0.13
        if is_space or tokens[i] == "▁":
            sink += 0.08
        sink = float(np.clip(sink, 0.18, 0.92))

        attention[i, 0] = sink
        if i == 1:
            attention[i, i] = 1.0 - sink
            continue

        # Most non-sink mass stays on the query itself; the rest is local.
        self_share = 0.48 + 0.13 * (1.0 - np.exp(-i / 25.0))
        if is_punct:
            self_share += 0.12
        self_share = float(np.clip(self_share, 0.35, 0.78))

        residual = 1.0 - sink
        attention[i, i] = residual * self_share
        positions = np.arange(1, i)
        local = np.exp(-(i - positions) / 5.0)
        local += 0.12 / np.sqrt(i - positions)
        attention[i, 1:i] = residual * (1.0 - self_share) * local / local.sum()

    return "bos_sink_with_self_and_recency", make_row_stochastic(attention)


def prog_L16H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weaker semantic-recurrence and successor-copying
    attention that becomes more competitive in longer contexts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_induction", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens
    representatives = []
    for indices in alignment:
        representatives.append(doc[indices[0]] if indices else None)

    attention[0, 0] = 1.0

    for i in range(1, n):
        current = representatives[i]

        # A strong, persistent first-token sink dominates novel contexts.
        attention[i, 0] = 1.0
        background = 0.0007 + 0.000025 * i
        for j in range(1, i + 1):
            distance = i - j
            attention[i, j] = background * (
                0.65 + 0.35 * np.exp(-distance / 12.0)
            )

        if tokens[i] in special_tokens or tokens[i].isspace():
            continue

        # Linguistic distinctions affect the small non-sink component.
        if current is not None:
            if current.pos_ == "PUNCT":
                attention[i, 1:i + 1] *= 1.7
            elif current.pos_ in ("NOUN", "PROPN", "ADJ"):
                attention[i, 1:i + 1] *= 0.8

        recurrence_scale = min(1.8, (i / 45.0) ** 2)
        for j in range(1, i - 2):
            if tokens[j] in special_tokens or tokens[j].isspace():
                continue

            previous = representatives[j]
            # Do not treat pieces within the same linguistic token as repeats.
            if current is not None and previous is not None:
                if current.i == previous.i:
                    continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            strength = max(0.0, (similarity - 0.55) / 0.45) ** 3
            if strength <= 0.0:
                continue

            compatibility = 1.0
            if current is not None and previous is not None:
                if current.pos_ == previous.pos_:
                    compatibility *= 1.15
                if current.dep_ == previous.dep_:
                    compatibility *= 1.1
                if current.pos_ == "PUNCT":
                    compatibility *= 0.25

            weight = recurrence_scale * strength * compatibility
            attention[i, j] += 0.55 * weight

            # A matched earlier expression can retrieve its continuation.
            successor = j + 1
            if successor < i:
                successor_word = representatives[successor]
                continuation_weight = 0.75
                if successor_word is not None:
                    if successor_word.pos_ in ("NOUN", "PROPN", "ADJ"):
                        continuation_weight *= 1.3
                    elif successor_word.pos_ == "PUNCT":
                        continuation_weight *= 0.35
                attention[i, successor] += continuation_weight * weight

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "bos_sink_with_weak_induction", attention


def prog_L16H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and on content tokens.
    Residual attention is diffuse, with weak recency and syntactic preferences.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            if si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        pos = word.pos_ if word is not None else ""
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        punctuation = bool(clean) and all(
            not ch.isalnum() and not ch.isspace() for ch in clean
        )

        # The initial token is an exceptionally strong sink; its share
        # subsequently varies with lexical/syntactic token class.
        sink = 0.58 + 0.35 * np.exp(-(i - 1) / 4.0)
        if pos in ("NOUN", "PROPN"):
            sink += 0.13
        elif pos == "ADJ":
            sink += 0.10
        elif pos in ("PRON", "DET"):
            sink -= 0.08
        elif pos in ("ADP", "CCONJ", "SCONJ", "PART"):
            sink -= 0.04

        if word is not None and word.ent_type_:
            sink += 0.03

        if not clean.strip():
            sink = max(sink, 0.85)
        elif clean in ("'", "’"):
            sink = max(sink, 0.93)
        elif punctuation:
            sink += 0.04

        # Continuations of split words often retain the sink preference.
        if word is not None and inverse[word.i]:
            if i != inverse[word.i][0] and not punctuation:
                sink += 0.05

        if i == 1:
            sink = 0.985 if pos == "PRON" else 0.955
        sink = float(np.clip(sink, 0.30, 0.985))

        targets = np.arange(1, i + 1)
        residual = 0.45 + np.exp(-(i - targets) / 6.0)
        residual[-1] += 0.25

        if word is not None:
            # Only already available pieces of a syntactic governor count.
            if word.head.i != word.i:
                governors = [
                    j for j in inverse[word.head.i] if 0 < j <= i
                ]
                for j in governors:
                    residual[j - 1] += 0.65 / len(governors)

            # Keep modest attention within a multi-piece lexical unit.
            pieces = [j for j in inverse[word.i] if 0 < j < i]
            for j in pieces:
                residual[j - 1] += 0.45 / len(pieces)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

    return "bos_sink_with_linguistic_gating", attention


def prog_L16H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; quoted discourse weakens backward verb-to-argument links.
    Redirect only excess nominal argument-link mass to BOS, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quoted_argument_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    words = []
    for indices in alignment:
        words.append(doc[indices[-1]] if indices else None)

    quoted_discourse = any(c in sentence for c in "\"“”«»")

    attention[0, 0] = 1.0
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}
    object_deps = {"dobj", "obj", "iobj", "dative", "attr", "oprd"}
    local_deps = {
        "poss", "prep", "case", "cc", "advmod", "npadvmod", "punct"
    }

    for i in range(1, n):
        word = words[i]
        raw = tokens[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.47 + 0.23 * np.exp(-(i - 1) / 4.0)
        if pos in {"NOUN", "PROPN"}:
            sink += 0.055
        elif pos == "ADJ":
            sink += 0.14
        elif pos == "VERB":
            sink += 0.055
        elif pos in {"DET", "ADP", "PART", "CCONJ", "SCONJ"}:
            sink -= 0.10
        elif pos == "PRON":
            sink -= 0.055

        if dep in {"nsubj", "nsubjpass", "ROOT"}:
            sink += 0.055

        head_index = None
        if word is not None and word.head.i != word.i:
            candidates = [j for j in inverse[word.head.i] if 0 < j < i]
            if candidates:
                head_index = candidates[0]

        object_link = (
            head_index is not None
            and dep in object_deps
            and word.head.pos_ in {"VERB", "AUX"}
        )
        if object_link:
            sink -= 0.19

        if word is not None and inverse[word.i]:
            if i != inverse[word.i][0]:
                sink -= 0.045

        # Apostrophes and sentence/quotation boundaries are strong sink queries.
        if "'" in raw or "’" in raw:
            sink = 0.90
        elif any(c in raw for c in ".!?"):
            sink = 0.66
        elif any(c in raw for c in "\"“”"):
            sink = 0.62
        elif any(c in raw for c in ",;:"):
            sink = 0.43 + 0.20 * np.exp(-i / 6.0)
        elif raw.isspace() or raw == "▁":
            sink = 0.65

        if i == 1:
            sink = 0.80
        sink = float(np.clip(sink, 0.22, 0.93))

        # Distribute background mass causally, preferring recent content.
        local = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            target = words[j]
            importance = 1.0
            if target is not None:
                if target.pos_ in content_pos:
                    importance = 1.7
                elif target.is_punct:
                    importance = 0.35
                else:
                    importance = 0.65
            local[j] = importance * np.exp(-(i - j) / 3.0)
        local[i] *= 0.22
        local /= local.sum()

        link_mass = 0.0
        if head_index is not None:
            if object_link:
                link_mass = 0.72
            elif dep in local_deps:
                link_mass = 0.48
            elif dep not in {"nsubj", "nsubjpass"}:
                link_mass = 0.30

        attention[i, :i + 1] = (1.0 - sink) * (1.0 - link_mass) * local
        if head_index is not None:
            attention[i, head_index] += (1.0 - sink) * link_mass
        attention[i, 0] = sink

        # Back off only explicit nominal argument links in quoted discourse.
        # Possessive noun phrases retain the original behavior.
        if (
            quoted_discourse
            and object_link
            and pos in {"NOUN", "PROPN", "PRON"}
            and not any(child.dep_ == "poss" for child in word.children)
        ):
            transfer = 0.55 * (1.0 - sink) * link_mass
            attention[i, head_index] -= transfer
            attention[i, 0] += transfer

    return "bos_sink_with_quoted_argument_backoff", make_row_stochastic(attention)


def prog_L16H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink, with competing nominal sinks in temporal openings and
    narratives that repeatedly mention an early nominal subject.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.95
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    doc = spacy_parse(sentence)
    mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
    temporal = []
    subjects = []
    nominals = []
    row_pos = [""] * n

    for word in doc:
        indices = [j for j in mapping[word.i] if 0 < j < n]
        if not indices:
            continue
        for j in indices:
            row_pos[j] = word.pos_
        endpoint = indices[-1]
        if word.pos_ in ("NOUN", "PROPN"):
            weight = 2.0 if word.dep_ in ("nsubj", "nsubjpass", "dobj", "obj") else 1.0
            nominals.append((endpoint, weight))
            if word.dep_ in ("nsubj", "nsubjpass"):
                subjects.append((word.i, endpoint))
            if word.i < 4 and (
                word.dep_ in ("npadvmod", "obl:tmod")
                or word.ent_type_ in ("DATE", "TIME")
            ):
                temporal.append(endpoint)

    repeated_subject = False
    first_subject = None
    for word_index, endpoint in subjects:
        if word_index < 4:
            first_subject = endpoint
            for later_index, later_endpoint in subjects:
                if later_index > word_index + 4 and embedding_similarity(
                    tokens, endpoint, later_endpoint, tokenizer
                ) >= 0.95:
                    repeated_subject = True
                    break
        if repeated_subject:
            break

    if temporal or repeated_subject:
        start = temporal[0] if temporal else first_subject
        for i in range(start + 1, n):
            weights = np.zeros(i, dtype=np.float64)
            function_query = row_pos[i] in ("DET", "ADP", "PART", "SCONJ")

            if temporal:
                # A temporal opening supplies a persistent alternative sink.
                transfer = 0.30 + 0.06 * function_query
                weights[1:i] = 0.30 / (i - 1)
                weights[temporal[0]] += 0.70
            else:
                # Narrative noun sinks emerge gradually as the context grows.
                transfer = min(0.30, 0.04 + 0.006 * (i - start))
                transfer += 0.10 * function_query
                for endpoint, weight in nominals:
                    if endpoint < i:
                        weights[endpoint] += weight

            total = weights.sum()
            if total > 0:
                # Move only BOS mass; preserve every original self weight.
                attention[i, 0] -= transfer
                attention[i, :i] += transfer * weights / total

        return "bos_with_nominal_sinks", attention

    return "bos_sink", attention


def prog_L16H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak, causal discourse-subject fallback.
    Content tokens favor BOS; function tokens distribute more mass to context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_fallback", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    subjects = []
    seen_subjects = set()

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[0]]
            for si in aligned:
                candidate = doc[si]
                if not candidate.is_space and not candidate.is_punct:
                    word = candidate
                    break

        # The sink remains dominant even well beyond the opening tokens.
        sink = 0.77 + 0.13 * np.exp(-(i - 1) / 13.0)
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.045
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "DET", "PART"):
                sink -= 0.085
            elif word.pos_ == "PRON" and word.dep_ not in ("nsubj", "nsubjpass"):
                sink -= 0.065
            elif word.is_punct:
                sink -= 0.075

            if word.ent_type_:
                sink += 0.025

            if (word.dep_ in ("nsubj", "nsubjpass", "csubj")
                    and word.pos_ in ("NOUN", "PROPN")
                    and word.i not in seen_subjects):
                subjects.append(i)
                seen_subjects.add(word.i)

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.96
        sink = float(np.clip(sink, 0.50, 0.96))

        positions = np.arange(1, i + 1)
        residual = 0.15 / i + 0.85 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        # Earlier nominal subjects can act as secondary attention sinks.
        if subjects:
            anchor = subjects[-1]
            if anchor < i:
                anchor_share = 0.60
                residual *= 1.0 - anchor_share
                residual[anchor - 1] += anchor_share

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_subject_fallback", make_row_stochastic(attention)


def prog_L16H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with secondary attention to salient nominal anchors.
    Content tokens favor BOS; grammatical tokens more often retrieve a prior referent.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Represent a word by its final subtoken, including fragmented noun names.
    word_ends = {}
    for ti, word_ids in enumerate(aligned):
        if tokens[ti] not in tokenizer.all_special_tokens:
            for wi in word_ids:
                word_ends[wi] = ti

    subject_deps = ("nsubj", "nsubjpass", "csubj", "csubjpass")
    object_deps = ("dobj", "obj", "iobj", "pobj", "attr", "oprd")
    function_pos = ("ADP", "DET", "CCONJ", "SCONJ", "PART", "AUX")

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = aligned[i]
        word = doc[word_ids[-1]] if word_ids else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        if pos in ("ADJ", "VERB"):
            sink = 0.87
        elif pos in ("NOUN", "PROPN"):
            sink = 0.79
        elif pos == "ADV":
            sink = 0.79
        elif pos == "PRON":
            sink = 0.69
        elif pos in function_pos:
            sink = 0.53
        elif pos == "PUNCT":
            sink = 0.69
        else:
            sink = 0.78

        # Early positions strongly prefer the initial sink.
        sink += (0.94 - sink) * np.exp(-(i - 1) / 2.6)

        anchors = np.zeros(n, dtype=np.float64)
        for wi, end in word_ends.items():
            if end <= 0 or end >= i:
                continue
            candidate = doc[wi]
            if candidate.pos_ not in ("NOUN", "PROPN"):
                continue

            distance = i - end
            strength = 1.0
            if candidate.dep_ in subject_deps:
                strength = 2.5
            elif candidate.dep_ in object_deps:
                strength = 1.5
            if candidate.ent_type_:
                strength *= 1.1

            # Recency competes with the persistence of grammatical subjects.
            strength *= np.exp(-distance / 23.0)
            if word is not None:
                if word.head.i == wi:
                    strength *= 1.6
                if word.head.head.i == wi:
                    strength *= 1.15
            anchors[end] += strength

        anchor_total = anchors.sum()
        if anchor_total == 0:
            sink += 0.35 * (1.0 - sink)

        attention[i, 0] = sink
        remainder = 1.0 - sink

        # Most non-sink mass belongs to nominal anchors, with a small causal
        # background rather than an artificially exclusive two-token pattern.
        background = np.exp(-(i - np.arange(1, i + 1)) / 12.0)
        background /= background.sum()

        if anchor_total > 0:
            anchor_fraction = 0.88 if pos in function_pos else 0.73
            if dep in ("poss", "case", "relcl"):
                anchor_fraction = 0.92
            attention[i] += remainder * anchor_fraction * anchors / anchor_total
            attention[i, 1:i + 1] += (
                remainder * (1.0 - anchor_fraction) * background
            )
        else:
            attention[i, 1:i + 1] += remainder * background

    return "bos_sink_with_nominal_anchors", make_row_stochastic(attention)


def prog_L16H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with syntactic anchors; infinitival clauses also attend to
    their preceding infinitive marker rather than only their governor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_infinitival_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        sids = aligned[i]
        word = doc[sids[-1]] if sids else None
        anchor = None
        strength = 0.80
        bos = 0.46

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("VERB", "AUX"):
                bos = 0.60
            elif pos in ("CCONJ", "SCONJ"):
                bos = 0.69
            elif pos == "ADP":
                bos = 0.52
            elif pos == "ADV":
                bos = 0.49

            # Ascend through a noun phrase to a preceding external governor.
            # This also allows determiners to attend to a verb before their noun.
            node = word
            seen = set()
            for _ in range(7):
                if node.i in seen:
                    break
                seen.add(node.i)
                head = node.head
                if head.i == node.i:
                    break

                candidates = [
                    j for j in inverse[head.i] if 0 < j < i
                ]
                if candidates and head.pos_ in ("VERB", "AUX", "ADP", "ADJ"):
                    anchor = candidates[0]
                    if node.dep_ in (
                        "dobj", "obj", "iobj", "dative", "oprd", "attr"
                    ):
                        bos = 0.27
                        strength = 0.88
                    elif node.dep_ in ("pobj", "obl"):
                        bos = 0.38
                        strength = 0.82
                    else:
                        bos = 0.40
                    break
                node = head

            # A subject's predicate is usually in the future. Its left-side
            # clause marker, auxiliary, or punctuation is available instead.
            if dep in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
                anchor = None
                clause = word.head
                markers = []
                for child in clause.children:
                    if child.dep_ in ("mark", "aux", "auxpass"):
                        for j in inverse[child.i]:
                            if 0 < j < i:
                                markers.append(j)
                if markers:
                    anchor = max(markers)
                    bos = 0.20
                    strength = 0.92
                else:
                    for j in range(i - 1, max(0, i - 5), -1):
                        if not aligned[j]:
                            continue
                        previous = doc[aligned[j][-1]]
                        if previous.pos_ in ("SCONJ", "CCONJ", "ADJ"):
                            anchor = j
                            bos = 0.28
                            strength = 0.88
                            break
                        if previous.is_punct:
                            anchor = j
                            bos = 0.32
                            strength = 0.88
                            break

            # Short pieces of split words frequently default to the sink.
            pieces = inverse[word.i]
            if len(pieces) > 1 and len(clean) <= 3 and clean.isalpha():
                bos = max(bos, 0.82 if i == pieces[0] else 0.68)
                if i == pieces[-1]:
                    bos = max(0.52, bos - 0.12)

        # Boundary tokens are particularly strong sink queries.
        punctuation = (
            bool(clean)
            and not any(c.isalnum() for c in clean)
            and not clean.isspace()
        )
        if punctuation:
            if any(c in ".!?" for c in clean):
                bos = 0.89
            elif any(c in "'’" for c in clean):
                bos = 0.95
            elif any(c in "\"“”" for c in clean):
                bos = 0.77
            else:
                bos = 0.65
            anchor = None
        elif not clean or clean.isspace():
            bos = 0.82
            anchor = None

        if raw in special:
            bos = 0.98
            anchor = None
        elif i == 1:
            bos = 0.94
            anchor = None
        elif i == 2 and anchor is None:
            bos = max(bos, 0.74)

        # Allocate the remaining mass locally, with a sharper syntactic peak.
        local = np.exp((np.arange(1, i + 1) - i) / 3.5)
        local /= local.sum()
        remaining = 1.0 - bos
        if anchor is not None:
            attention[i, 1:i + 1] = remaining * (1.0 - strength) * local
            attention[i, anchor] += remaining * strength
        else:
            attention[i, 1:i + 1] = remaining * local
        attention[i, 0] = bos

        # Infinitive predicates, their direct objects, and particles share
        # attention with the infinitival onset. Move only anchor-peak mass:
        # BOS, self-attention, and the entire local-decay component stay intact.
        if word is not None and anchor is not None:
            clause = None
            if word.pos_ in ("VERB", "AUX"):
                clause = word
            elif word.dep_ in ("dobj", "obj", "iobj", "dative", "prt"):
                if word.head.pos_ in ("VERB", "AUX"):
                    clause = word.head

            for _ in range(4):
                if clause is None:
                    break
                markers = [
                    j
                    for child in clause.children
                    if child.pos_ == "PART" and child.dep_ in ("aux", "mark")
                    for j in inverse[child.i]
                    if 0 < j < i
                ]
                if markers:
                    marker = max(markers)
                    if marker != anchor:
                        moved = remaining * strength * 0.45
                        attention[i, anchor] -= moved
                        attention[i, marker] += moved
                    break
                if clause.dep_ != "xcomp" or clause.head.i == clause.i:
                    break
                clause = clause.head

    return (
        "bos_sink_with_infinitival_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L16H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a diffuse remainder; dialogue locally shifts BOS mass
    to the previous token, especially at quotation and syntactic boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_locality", attention

    # Only quoted dialogue enables the additional path.
    dialogue = '"' in sentence
    if dialogue:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    quote_count = 0

    attention[0, 0] = 1.0
    for i in range(1, n):
        if i == 1:
            sink_mass = 0.975
        else:
            sink_mass = 0.85 + 0.035 * np.exp(-(i - 2) / 5.0)

        # Original default behavior, including its self-attention weights.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        remainder = 0.7 / i + 0.3 * (
            np.exp(-distances / 4.0) / np.exp(-distances / 4.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * remainder

        if dialogue:
            current = tokens[i].lstrip("▁Ġ")
            previous = tokens[i - 1].lstrip("▁Ġ")
            opening_quote = '"' in current and quote_count % 2 == 0
            quote_count += current.count('"')

            if i > 1 and quote_count > 0:
                transfer = 0.10 if quote_count < 2 else 0.16

                # Opening quotes, quoted onsets, and standalone spacing
                # are particularly strong previous-token boundaries.
                if opening_quote:
                    transfer += 0.10
                elif '"' in previous or not current.strip():
                    transfer += 0.08

                if aligned[i] and aligned[i - 1]:
                    cur = doc[aligned[i][0]]
                    prev = doc[aligned[i - 1][-1]]
                    if cur.i == prev.i and not cur.is_punct:
                        transfer += 0.05
                    elif (
                        prev.pos_ in ("VERB", "AUX")
                        and cur.pos_ in ("ADP", "PART", "PRON", "DET")
                    ) or (
                        prev.pos_ == "ADP" and cur.pos_ == "DET"
                    ):
                        transfer += 0.07

                # Move only BOS mass: self and all other entries stay exact.
                transfer = min(transfer, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_dialogue_locality", attention


def prog_L16H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker local-context component.
    Predicate and boundary tokens favor BOS; relational tokens favor nearby context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    sink_by_pos = {
        "VERB": 0.81,
        "PROPN": 0.82,
        "PRON": 0.72,
        "NOUN": 0.65,
        "ADJ": 0.60,
        "ADV": 0.66,
        "AUX": 0.56,
        "DET": 0.65,
        "ADP": 0.54,
        "CCONJ": 0.55,
        "SCONJ": 0.70,
        "PART": 0.68,
        "INTJ": 0.84,
        "NUM": 0.69,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        pos = word.pos_ if word is not None else ""
        sink = sink_by_pos.get(pos, 0.72)

        if not surface:
            sink = 0.81
        elif all(c in ".,;:!?\"'’“”‘`()[]{}—–-" for c in surface):
            if any(c in "'’" for c in surface):
                sink = 0.93
            elif any(c in ".!?\"“”" for c in surface):
                sink = 0.85
            else:
                sink = 0.60

        if word is not None:
            if word.dep_ in ("ROOT", "ccomp", "xcomp"):
                sink += 0.035
            if word.ent_type_:
                sink += 0.025

        # Strong initial sink preference, fading rather than growing with length.
        sink += 0.07 * np.exp(-(i - 1) / 3.0)

        previous = words[i - 1]
        if (
            pos == "ADP"
            and previous is not None
            and previous.pos_ in ("NOUN", "PROPN", "ADJ", "ADV")
        ):
            sink = 0.30 if previous.pos_ in ("ADJ", "ADV") else 0.44

        sink = float(np.clip(sink, 0.25, 0.96))

        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
            continue

        # Non-sink attention is concentrated on the immediately preceding context.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.4)
        local[-1] *= 0.25
        local[-2] *= 2.5

        # A preceding syntactic governor can receive additional residual mass.
        if word is not None and word.head.i != word.i:
            governors = [
                j for j in range(1, i)
                if word.head.i in alignment[j]
            ]
            if governors:
                local[governors[-1] - 1] += 0.65

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_local_context", attention


def prog_L16H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with occasional backward attention to phrase endpoints,
    especially at punctuation and coordination boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    representatives = []
    for i in range(n):
        overlaps = alignment[i]
        if tokens[i] in special_tokens or not overlaps:
            representatives.append(None)
        else:
            representatives.append(doc[overlaps[-1]])

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        previous = representatives[i - 1]

        sink = 0.88
        if word is not None:
            if word.pos_ in ("VERB", "ADP", "PRON", "SCONJ", "PART"):
                sink = 0.82
            elif word.pos_ == "PUNCT":
                sink = 0.80

        if i <= 3:
            sink = min(0.96, sink + 0.06)

        target = None
        boundary_mass = 0.0

        if word is not None and previous is not None:
            distinct_word = word.i != previous.i
            previous_is_content = previous.pos_ in ("NOUN", "PROPN", "ADJ")

            if distinct_word and word.pos_ == "CCONJ":
                # Coordination often exposes the final subtoken of the
                # preceding conjunct, rather than its initial subtoken.
                if previous_is_content:
                    target = i - 1
                    boundary_mass = 0.68
                elif previous.pos_ == "PUNCT":
                    for j in range(i - 2, max(0, i - 6), -1):
                        candidate = representatives[j]
                        if candidate is not None and candidate.pos_ in (
                            "NOUN", "PROPN", "ADJ"
                        ):
                            target = j
                            boundary_mass = 0.58
                            break

            elif distinct_word and word.is_punct:
                # Quotes and apostrophes generally retain the sink behavior.
                if word.text in (",", ";", ":") and previous_is_content:
                    target = i - 1
                    boundary_mass = (
                        0.76 if previous.pos_ in ("NOUN", "PROPN") else 0.48
                    )
                elif word.text in (".", "!", "?") and previous_is_content:
                    target = i - 1
                    boundary_mass = 0.40

        if target is not None:
            sink = min(sink, 1.0 - boundary_mass - 0.04)

        attention[i, 0] = sink
        if target is not None:
            attention[i, target] += boundary_mass

        residual = 1.0 - sink - boundary_mass
        positions = np.arange(1, i + 1)
        local_weights = np.exp(-(i - positions) / 3.0)
        local_weights /= local_weights.sum()
        attention[i, 1:i + 1] += residual * local_weights

    return (
        "bos_sink_with_phrase_boundaries",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L16H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak, diffuse causal recency attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 12.0)
        residual /= residual.sum()

        attention[i, 0] = 0.94
        attention[i, 1:i + 1] = 0.06 * residual

    return "bos_sink_with_weak_recency", attention


def prog_L16H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a secondary preference for recent nominal endpoints.
    Modifiers and word-initial fragments favor BOS; clause boundaries retrieve nouns.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_retrieval", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(aligned):
        if ti == 0:
            continue
        for wi in word_ids:
            inverse[wi].append(ti)

    nominal_positions = []
    for wi, word in enumerate(doc):
        if word.pos_ in ("NOUN", "PROPN", "PRON") and inverse[wi]:
            nominal_positions.append((inverse[wi][-1], wi))

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = aligned[i]
        wi = word_ids[-1] if word_ids else None
        word = doc[wi] if wi is not None else None

        sink = 0.82
        if word is not None:
            pos = word.pos_
            if pos in ("DET", "ADJ", "NUM"):
                sink = 0.91
            elif pos in ("ADP", "PART", "ADV"):
                sink = 0.85
            elif pos in ("AUX", "VERB"):
                sink = 0.70
            elif pos in ("NOUN", "PROPN"):
                sink = 0.66
                if word.dep_ in ("nsubj", "nsubjpass") and i <= 5:
                    sink = 0.95
            elif pos == "PRON":
                sink = 0.77
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.73
            elif pos == "PUNCT":
                sink = 0.53

            pieces = inverse[wi]
            if len(pieces) > 1 and i < pieces[-1]:
                sink = max(sink, 0.96)

            if word.is_sent_start and pos == "DET" and i > 5:
                sink = 0.40

        if i == 1:
            sink = 0.975
        elif i <= 3:
            sink = max(sink, 0.91)

        candidates = [
            (j, k) for j, k in nominal_positions
            if j < i and k != wi
        ]

        residual = np.zeros(i + 1, dtype=np.float64)
        for j, k in candidates:
            distance = i - j
            strength = np.exp(-distance / 18.0)
            if doc[k].pos_ == "PRON":
                strength *= 0.35
            if doc[k].dep_ in ("dobj", "obj", "pobj", "attr", "dative"):
                strength *= 1.8
            residual[j] += strength

        if candidates:
            latest = max(j for j, _ in candidates)
            residual[latest] *= 1.8

        residual[i] += 0.12
        if i > 1:
            residual[i - 1] += 0.16

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] += sink

    return "bos_sink_with_nominal_retrieval", make_row_stochastic(attention)


def prog_L16H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker causal recency and syntactic-content background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = [
        doc[indices[0]] if indices else None for indices in alignment
    ]

    salience = np.ones(n, dtype=np.float64)
    for j, word in enumerate(representatives):
        if word is None:
            salience[j] = 0.5
        elif word.is_punct:
            salience[j] = 0.25
        elif word.pos_ in ("NOUN", "PROPN"):
            salience[j] = 1.8
            if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                salience[j] *= 1.4
        elif word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ"):
            salience[j] = 0.6

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = representatives[i]
        sink = 0.66
        if word is not None:
            if word.is_punct:
                sink = 0.45
                if "'" in tokens[i] or "’" in tokens[i]:
                    sink = 0.80
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink = 0.73
            elif word.pos_ in ("PRON", "AUX", "ADV"):
                sink = 0.69
            elif word.pos_ in ("DET", "ADP"):
                sink = 0.62
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink = 0.55

        sink -= 0.06 * (1.0 - np.exp(-i / 40.0))
        positions = np.arange(1, i + 1)
        distance = i - positions
        background = (
            0.55 * np.exp(-distance / 3.5)
            + 0.20 * np.exp(-distance / 24.0) * salience[1:i + 1]
        )
        background[-1] += 0.35

        if word is not None:
            for j in range(1, i + 1):
                candidate = representatives[j]
                if candidate is not None and candidate.i != word.i:
                    if candidate.i == word.head.i:
                        background[j - 1] += 0.35
                    elif candidate.head.i == word.i:
                        background[j - 1] += 0.15

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * background / background.sum()
        )

    return "bos_sink_with_content_background", attention


def prog_L16H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a punctuation-boundary residual.
    Boundary-triggered transfers leave the original diagonal and decay unchanged.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        sink = 0.85

        if word is not None:
            pos = word.pos_
            if pos in ("PRON", "DET"):
                sink = 0.90
            elif pos in ("ADP", "PART"):
                sink = 0.88
            elif pos == "PROPN":
                sink = 0.91
            elif pos == "NOUN":
                sink = 0.86
            elif pos in ("VERB", "AUX"):
                sink = 0.83
            elif pos in ("ADJ", "ADV", "CCONJ", "SCONJ"):
                sink = 0.81

            if word.ent_type_:
                sink = min(0.93, sink + 0.015)

        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        punctuation = (
            bool(clean) and all(not c.isalnum() for c in clean)
        ) or (word is not None and word.pos_ == "PUNCT")

        if punctuation:
            sink = 0.70
        elif not clean:
            sink = 0.79

        # The first ordinary token has essentially only the sink as context.
        if i == 1:
            sink = 0.93

        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local[-1] *= 0.55

        if punctuation and i > 1:
            local[-2] += 2.5

        # Weak intra-word continuity for subword pieces.
        if i > 1 and aligned and alignment[i - 1]:
            if any(k in alignment[i - 1] for k in aligned):
                local[-2] += 0.8

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Add only boundary-specific residuals, funded entirely from BOS.
        # Never change the diagonal or the baseline local distribution.
        if i > 1:
            previous = i - 1
            previous_clean = tokens[previous].replace("▁", "").replace("Ġ", "").strip()
            if not previous_clean and previous > 1:
                previous -= 1
                previous_clean = tokens[previous].replace("▁", "").replace("Ġ", "").strip()

            boundary = (
                bool(previous_clean)
                and all(not c.isalnum() for c in previous_clean)
                and any(c in ',;:!?."“”' for c in previous_clean)
            )

            if boundary and not punctuation:
                transfer = 0.22
                if not clean:
                    transfer = 0.32
                elif any(c in ".!?" for c in previous_clean):
                    transfer = 0.30
                attention[i, 0] -= transfer
                attention[i, previous] += transfer

            elif punctuation and any(c in ".!?" for c in clean):
                # Sentence endings also recover diffuse clause-level context.
                targets = [
                    j for j in range(1, i)
                    if alignment[j]
                    and doc[alignment[j][-1]].pos_ in (
                        "NOUN", "PROPN", "VERB", "ADJ", "ADV", "CCONJ", "SCONJ"
                    )
                ]
                if targets:
                    transfer = 0.28
                    attention[i, 0] -= transfer
                    attention[i, targets] += transfer / len(targets)

    return "bos_sink_with_boundary_residual", make_row_stochastic(attention)


def prog_L16H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a quoted-dialogue exception: reporting clauses retrieve
    the preceding speech boundary rather than relying solely on BOS."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_boundary", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "DET": 0.96,
        "ADJ": 0.94,
        "ADP": 0.93,
        "AUX": 0.93,
        "PART": 0.93,
        "PRON": 0.92,
        "ADV": 0.91,
        "NUM": 0.91,
        "NOUN": 0.87,
        "VERB": 0.85,
        "PROPN": 0.84,
        "SCONJ": 0.83,
        "CCONJ": 0.73,
        "PUNCT": 0.68,
        "SPACE": 0.79,
    }

    attention[0, 0] = 1.0
    boundaries = []
    sentence_starts = []

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        sink = sink_by_pos.get(word.pos_, 0.91) if word is not None else 0.91

        if i == 1:
            sink = 0.97
        elif i > 24:
            sink -= min(0.07, 0.0015 * (i - 24))

        if word is not None and word.dep_ in ("conj", "parataxis"):
            sink -= 0.06

        sink = np.clip(sink, 0.55, 0.98)

        # The residual is diffuse and causal, favoring recent positions.
        positions = np.arange(1, i + 1)
        residual = 0.08 + np.exp(-(i - positions) / 5.0)
        for j in boundaries:
            residual[j - 1] += 0.8 * np.exp(-(i - j) / 20.0)
        for j in sentence_starts:
            residual[j - 1] += 0.5 * np.exp(-(i - j) / 30.0)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        if word is not None:
            if word.is_punct:
                boundaries.append(i)
            if word.is_sent_start:
                if not sentence_starts or (
                    i > 1 and alignment[i - 1] != aligned
                ):
                    sentence_starts.append(i)

    # Special case: repeated direct speech creates a reusable boundary anchor.
    # Transfer mass only off BOS (or onto BOS at opening quotes), never self.
    openings = []
    gaps = []
    inside_quote = False
    last_close = None
    for i in range(1, n):
        if '"' not in tokens[i]:
            continue
        if inside_quote:
            last_close = i
        else:
            if openings and last_close is not None:
                gaps.append((openings[-1], last_close, i))
            openings.append(i)
        inside_quote = not inside_quote

    if len(openings) >= 2:
        for opening in openings:
            available = attention[opening, 1:opening].sum()
            moved = min(max(0.0, 0.96 - attention[opening, 0]), available)
            if available > 0.0:
                attention[opening, 1:opening] *= 1.0 - moved / available
                attention[opening, 0] += moved

        for anchor, close, next_open in gaps:
            # Require a reporting verb immediately before comma + opening quote.
            reporters = [
                i for i in range(close + 1, next_open)
                if alignment[i]
                and doc[alignment[i][-1]].pos_ == "VERB"
                and next_open - i <= 3
            ]
            if not reporters:
                continue
            reporter = reporters[-1]
            comma_anchor = anchor - 1 if "," in tokens[anchor - 1] else anchor

            for i in range(close + 1, next_open):
                word = doc[alignment[i][-1]] if alignment[i] else None
                if word is None:
                    continue
                if i == reporter:
                    floor, quote_share = 0.16, 0.72
                elif i > reporter and word.is_punct:
                    floor, quote_share = 0.34, 1.0
                elif i < reporter and word.pos_ == "ADV":
                    floor, quote_share = 0.38, 1.0
                elif word.pos_ in ("NOUN", "PROPN"):
                    floor, quote_share = attention[i, 0] - 0.15, 0.75
                else:
                    continue

                moved = max(0.0, attention[i, 0] - max(0.0, floor))
                attention[i, 0] -= moved
                attention[i, anchor] += moved * quote_share
                attention[i, comma_anchor] += moved * (1.0 - quote_share)

    return "bos_sink_with_dialogue_boundary", attention


def prog_L16H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a dialogue-boundary exception: intervening narration
    retrieves earlier opening quotes and nearby turn boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_dialogue_boundaries", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = 0.94
        attention[i, 1:i + 1] = 0.06 * residual

    # Only activate for dialogue containing a completed turn and another opening.
    openings, pairs = [], []
    active = None
    for i, token in enumerate(tokens):
        for char in token:
            if char in ('"', '“', '”'):
                if active is None:
                    active = i
                    openings.append(i)
                else:
                    pairs.append((active, i))
                    active = None

    if not pairs or len(openings) < 2:
        return "bos_sink_with_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    for i in range(1, n):
        completed = [(a, b) for a, b in pairs if b < i]
        if not completed:
            continue

        opening, closing = completed[-1]
        subsequent = [a for a in openings if a > closing]
        next_opening = subsequent[0] if subsequent else n
        in_narration = i < next_opening

        words = [doc[k] for k in aligned[i] if not doc[k].is_space]
        word = next((w for w in words if not w.is_punct), None)
        targets = []

        if in_narration:
            # The largest departures occur at reporting predicates just before
            # a new quotation; ordinary narration has a weaker version.
            mass = 0.10
            if word is not None:
                if word.pos_ == "VERB":
                    mass = 0.17
                    if next_opening < n and next_opening - i <= 3:
                        mass = 0.66
                    elif len(completed) > 1:
                        mass = 0.34
                elif word.pos_ in ("NOUN", "PROPN"):
                    mass = 0.16
                    if word.dep_ in ("nsubj", "nsubjpass"):
                        mass = 0.24
                        if i > 0 and any(
                            k in aligned[i - 1] for k in aligned[i]
                        ):
                            mass = 0.44
                elif word.pos_ == "CCONJ":
                    mass = 0.30
                elif word.pos_ == "DET":
                    mass = 0.12

            if word is None and next_opening < n:
                mass = 0.17 if next_opening - i <= 5 else 0.10

            # Later narration can retrieve both preceding turns.
            if len(completed) > 1:
                targets.append((completed[-2][0], mass * 0.45))
                targets.append((opening, mass * 0.55))
            else:
                targets.append((opening, mass))

            if opening > 1 and tokens[opening - 1].strip("▁Ġ ") == ",":
                targets.append((opening - 1, mass * 0.15))
        else:
            # Inside a subsequent turn, retain a small boundary retrieval.
            targets.append((closing, 0.055))

        boundary = closing + 1
        if boundary < i and not tokens[boundary].strip("▁Ġ \t\r\n"):
            targets.append((boundary, 0.035))

        # Transfer mass from BOS only: preserve the original diagonal,
        # recency residual, and every unrelated edge exactly.
        for target, mass in targets:
            if 0 < target < i:
                moved = min(mass, attention[i, 0])
                attention[i, 0] -= moved
                attention[i, target] += moved

    return "bos_sink_with_dialogue_boundaries", attention


def prog_L16H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all queries favor the first token.
    Sink strength gradually decreases with position; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.95 - 0.003 * min(i, 75)
        attention[i, 0] = sink_mass

        # The supplied edges support a sink, not a specific non-BOS target.
        # Distribute the remaining mass broadly over accessible tokens.
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_sink_with_position_decay", attention


def prog_L16H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakened by distance and discourse boundaries.
    Residual attention mixes local context with early syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_decay", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos = [""] * n
    dep = [""] * n
    punctuation = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)
    for i in range(1, n):
        indices = aligned[i]
        if indices:
            word = doc[indices[0]]
            pos[i] = word.pos_
            dep[i] = word.dep_
            punctuation[i] = all(doc[k].is_punct for k in indices)
            whitespace[i] = all(doc[k].is_space for k in indices)
        else:
            clean = tokens[i].replace("▁", "").replace("Ġ", "")
            whitespace[i] = not clean.strip()
            punctuation[i] = bool(clean) and all(
                not c.isalnum() and not c.isspace() for c in clean
            )

    boundaries = 0
    for i in range(1, n):
        sink = 0.975 - 0.0025 * max(i - 8, 0)
        sink -= min(0.14, 0.014 * boundaries)

        if punctuation[i]:
            sink -= 0.13
        elif whitespace[i]:
            sink -= 0.20
        elif pos[i] in ("CCONJ", "SCONJ"):
            sink -= 0.075
        elif pos[i] == "VERB":
            sink -= 0.045
        elif dep[i] in ("advcl", "ccomp", "conj"):
            sink -= 0.035

        # Continuation pieces inherit their word's linguistic features.
        if (
            i > 1
            and aligned[i]
            and aligned[i - 1]
            and aligned[i][0] == aligned[i - 1][0]
        ):
            sink -= 0.015

        sink = float(np.clip(sink, 0.40, 0.99))
        keys = np.arange(1, i + 1)
        residual = 0.55 * np.exp(-(i - keys) / 4.0)
        residual += 0.30 * np.exp(-(keys - 1) / 7.0)

        for offset, j in enumerate(keys):
            if j < i and pos[j] in ("AUX", "VERB"):
                residual[offset] += 0.30 * np.exp(-(j - 1) / 12.0)
            if punctuation[j] or whitespace[j]:
                residual[offset] *= 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        if punctuation[i]:
            boundaries += 1

    return "bos_sink_with_boundary_decay", attention


def prog_L16H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Near-exclusive attention to the initial BOS token, with diffuse causal leakage."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n:
        attention[0, 0] = 1.0
        for i in range(1, n):
            attention[i, 0] = 0.998
            attention[i, 1:i + 1] = 0.002 / i

    return "bos_attention_sink", attention


def prog_L16H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant BOS attention sink with weaker local phrase attention.
    Sink strength decreases with position and increases at function-word boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_phrases", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Locate the first model piece of each linguistic token.
    first_piece = {}
    for ti, word_indices in enumerate(alignment):
        if ti == 0:
            continue
        for wi in word_indices:
            if wi not in first_piece:
                first_piece[wi] = ti

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_indices = alignment[i]
        word = doc[word_indices[0]] if word_indices else None

        sink = 0.55 + 0.37 * np.exp(-(i - 1) / 22.0)
        anchors = {}
        if word is not None:
            pos = word.pos_
            if pos == "DET":
                sink += 0.12
            elif pos == "ADP":
                sink += 0.08
            elif pos in ("AUX", "PRON", "PART"):
                sink += 0.03
            elif pos in ("NOUN", "PROPN"):
                sink -= 0.06
            elif pos in ("VERB", "CCONJ", "PUNCT"):
                sink -= 0.04

            first = first_piece.get(word.i, i)
            if first < i:
                sink -= 0.05
                anchors[first] = 0.8

            # Objects of prepositions often retain attention on the phrase's
            # introducing preposition rather than sending everything to BOS.
            if word.head.pos_ == "ADP" and word.head.i != word.i:
                target = first_piece.get(word.head.i)
                if target is not None and 0 < target < i:
                    anchors[target] = 3.0
                    if pos in ("NOUN", "PROPN", "PRON"):
                        sink -= 0.12

            head_target = first_piece.get(word.head.i)
            if head_target is not None and 0 < head_target < i:
                anchors[head_target] = anchors.get(head_target, 0.0) + 0.5

            if pos in ("NOUN", "PROPN"):
                for child in word.children:
                    if child.dep_ in ("det", "poss", "amod", "compound"):
                        target = first_piece.get(child.i)
                        if target is not None and 0 < target < i:
                            anchors[target] = anchors.get(target, 0.0) + 0.6

        if i == 1:
            sink = 0.955

        sink = float(np.clip(sink, 0.35, 0.98))

        # Spread the residual causally, favoring recent context and phrase anchors.
        distances = i - np.arange(1, i + 1)
        residual = 0.04 + np.exp(-distances / 3.0)
        residual[-1] *= 0.45
        for target, weight in anchors.items():
            residual[target - 1] += weight

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_local_phrases", make_row_stochastic(attention)


def prog_L16H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predominantly a BOS attention-sink head, with a weak causal background.
    Later tokens and punctuation allow slightly more non-BOS attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_causal_tail", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        residual = 0.023 + 0.0012 * max(0, i - 20)
        aligned = alignment[i]

        if aligned:
            pos = doc[aligned[-1]].pos_
            if pos == "PUNCT":
                residual += 0.055
            elif pos in ("NOUN", "PROPN", "PRON"):
                residual += 0.012
        elif tokens[i].isspace():
            residual += 0.015

        residual = min(residual, 0.16)

        # A diffuse causal tail, mildly favoring nearby positions.
        distances = i - np.arange(1, i + 1)
        background = 0.5 + np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = residual * background / background.sum()
        attention[i, 0] = 1.0 - residual

    return "bos_sink_with_weak_causal_tail", attention


def prog_L16H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; sentence-final punctuation can retrieve
    the opening token instead of BOS or the immediately preceding token."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_terminal_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        previous = doc[alignment[i - 1][-1]] if alignment[i - 1] else None

        sink = 0.90
        if word is not None:
            if word.pos_ in ("DET", "ADJ", "AUX", "PRON", "NUM"):
                sink = 0.93
            elif word.pos_ in ("NOUN", "PROPN", "ADV"):
                sink = 0.89
            elif word.pos_ in ("VERB", "ADP", "SCONJ"):
                sink = 0.83
            elif word.pos_ == "CCONJ":
                sink = 0.66
            elif word.is_punct:
                sink = 0.72

        if i <= 2:
            sink = max(sink, 0.96)

        # A local nominal boundary is the clearest non-sink pattern.
        nominal_boundary = (
            word is not None
            and previous is not None
            and previous.pos_ in ("NOUN", "PROPN")
            and (
                word.pos_ == "CCONJ"
                or (word.is_punct and "," in tokens[i])
            )
        )
        if nominal_boundary:
            sink = 0.32

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[1:] = 0.03
        residual[i] += 0.15
        if i > 1:
            residual[i - 1] += 0.65

        # Only use a syntactic head when it is already causally available.
        if word is not None and word.head.i != word.i:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if head_positions:
                residual[head_positions[-1]] += 0.20

        if nominal_boundary:
            residual[i - 1] += 2.0

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

        # Terminal punctuation retrieves the opening anchor. Transfer only
        # BOS/previous-token mass, preserving self-attention and other edges.
        if (
            i > 3
            and word is not None
            and word.is_punct
            and any(mark in tokens[i] for mark in (".", "!", "?"))
            and alignment[1]
        ):
            opening = doc[alignment[1][0]]
            target = 0.50 if opening.pos_ in ("DET", "PRON") else 0.16
            needed = max(0.0, target - attention[i, 1])

            local_transfer = min(needed, attention[i, i - 1])
            attention[i, i - 1] -= local_transfer
            attention[i, 1] += local_transfer
            needed -= local_transfer

            bos_transfer = min(needed, attention[i, 0])
            attention[i, 0] -= bos_transfer
            attention[i, 1] += bos_transfer

    return "bos_sink_with_terminal_anchor", attention


def prog_L17H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent leakage.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        punctuation = bool(clean) and all(
            not char.isalnum() and not char.isspace() for char in clean
        )
        whitespace = not clean

        leakage_scale = 1.0
        if punctuation:
            leakage_scale = 1.7
        elif whitespace:
            leakage_scale = 2.0

        sink_mass = 1.0 / (1.0 + 0.0025 * i * leakage_scale)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 4.0)
        recent /= recent.sum()
        residual = 0.75 / i + 0.25 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_leakage", attention


def prog_L17H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, diffuse causal attention and a recency bias.
    Non-BOS competition gradually dilutes the sink at later positions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            distances = i - np.arange(1, i + 1)
            attention[i, 1:i + 1] = (
                0.0035 + 0.003 * np.exp(-distances / 8.0)
            )

    return "bos_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L17H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token/BOS attention sink with weak diffuse causal attention.
    Accumulating non-sink alternatives gradually reduce sink mass with position.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        distances = i - np.arange(i + 1, dtype=np.float64)
        attention[i, :i + 1] = 0.8 + 0.4 * np.exp(-distances / 8.0)
        attention[i, 0] = 320.0

    return "bos_sink_with_weak_causal_background", make_row_stochastic(attention)


def prog_L17H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant BOS attention sink with gradual positional dilution.
    The small residual attention is diffuse, with a weak recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        attention[i, 1:i + 1] = (
            0.85 + 0.35 * np.exp(-(i - positions) / 4.0)
        )
        attention[i, 0] = 400.0
        attention[i] /= attention[i].sum()

    return "bos_sink_with_positional_dilution", attention


def prog_L17H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak diffuse causal attention and a recency bias.
    Accumulating non-BOS competition gradually reduces sink dominance.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 1.0
        distances = i - np.arange(1, i + 1)
        attention[i, 1:i + 1] = (
            0.0015 + 0.0035 * np.exp(-distances / 3.0)
        )

    return "bos_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L17H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized retrieval of completed phrases at clause/list boundaries.
    Boundary retrieval moves only BOS mass, preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, positions in enumerate(alignment):
        if ti > 0:
            for k in positions:
                word_tokens[k].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        positions = alignment[i]
        pos_tags = {doc[k].pos_ for k in positions}

        sink_logit = 4.0 - 0.055 * i
        if "PUNCT" in pos_tags:
            sink_logit -= 0.65
        elif pos_tags.intersection({"CCONJ", "SCONJ"}):
            sink_logit -= 0.40
        elif pos_tags.intersection({"ADP", "PART"}):
            sink_logit -= 0.15

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        if i == 1:
            sink_mass = 0.99

        # Original diffuse recency prior.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Special case: commas and coordinators retrieve the phrase just closed.
        boundaries = [
            k for k in positions
            if doc[k].text == "," or doc[k].pos_ == "CCONJ"
        ]
        if boundaries:
            k = min(boundaries) - 1
            while k >= 0 and doc[k].pos_ in {"PUNCT", "SPACE"}:
                k -= 1
            if k >= 0 and doc[k].pos_ in {"ADJ", "VERB", "NOUN", "PROPN"}:
                previous = doc[k]
                targets = [previous]
                mass = 0.34 if previous.pos_ in {"ADJ", "VERB"} else 0.12

                # Coordinated nouns create a stronger, multi-item list anchor.
                nominal_list = previous.pos_ == "NOUN" and (
                    (previous.dep_ == "conj" and previous.head.pos_ == "NOUN")
                    or any(c.dep_ == "conj" and c.pos_ == "NOUN"
                           for c in previous.children)
                )
                if nominal_list:
                    mass = 0.44
                    if previous.dep_ == "conj" and previous.head.i < previous.i:
                        targets.append(previous.head)
                        mass = 0.72
                elif previous.pos_ == "NOUN":
                    head = previous.head
                    if head.pos_ == "ADP":
                        head = head.head
                    if head.pos_ == "VERB" and 0 < previous.i - head.i <= 6:
                        targets = [head]
                        mass = 0.28
                elif previous.pos_ == "ADJ" and "CCONJ" in pos_tags:
                    mass = 0.46

                # Strictly earlier keys only: leave self and all other keys intact.
                keys = [
                    max(j for j in word_tokens[t.i] if j < i)
                    for t in targets
                    if any(j < i for j in word_tokens[t.i])
                ]
                if keys:
                    transfer = min(mass, 0.9 * attention[i, 0])
                    attention[i, 0] -= transfer
                    for j in keys:
                        attention[i, j] += transfer / len(keys)

    return "bos_sink_with_boundary_retrieval", make_row_stochastic(attention)


def prog_L17H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, gradually weakened by position and mildly modulated
    by linguistic features; residual attention is diffuse and recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_logit = 3.4 - 0.018 * i - 0.55 * np.log1p(i / 4.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ == "VERB":
                sink_logit += 0.35
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_logit += 0.15
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "PART"):
                sink_logit -= 0.30
            elif word.pos_ == "PUNCT":
                sink_logit -= 0.40

            if word.dep_ == "ROOT":
                sink_logit += 0.15

            # Later pieces of the same linguistic token are slightly less
            # strongly tied to the sink than its first piece.
            if i > 1:
                if any(sid in alignment[i - 1] for sid in aligned):
                    sink_logit -= 0.25

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_decay", attention


def prog_L17H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal locality and syntactic-head leakage.
    Sink strength decreases mildly with position and for dependent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if wi < len(doc):
                inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.965 - min(0.105, 0.0016 * i)
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink += 0.022
            elif word.pos_ in ("CCONJ", "SCONJ", "ADP"):
                sink -= 0.045
            elif word.pos_ == "PUNCT":
                sink -= 0.035

            if word.dep_ in ("dobj", "obj", "pobj", "obl"):
                sink -= 0.065
            elif word.dep_ in ("poss", "nmod"):
                sink -= 0.085
            elif word.dep_ in ("nsubj", "csubj"):
                sink += 0.010

        if i == 1:
            sink = 0.984
        sink = float(np.clip(sink, 0.65, 0.989))

        # Distribute non-sink mass locally, retaining a weak first-token anchor.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[0] += 0.4

        if word is not None and word.head.i != word.i:
            candidates = [
                ti for ti in inverse[word.head.i]
                if 0 < ti <= i
            ]
            if candidates:
                residual[candidates[-1] - 1] += 2.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

    return "bos_sink_with_syntactic_leakage", attention


def prog_L17H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clause-subject anchor that yields to predicate context.
    Redistribute stale off-diagonal anchor mass without changing self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_subject_anchor", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    subject_deps = {
        "nsubj", "nsubjpass", "nsubj:pass",
        "csubj", "csubjpass", "csubj:pass"
    }
    special_tokens = set(tokenizer.all_special_tokens)
    active_subject = None
    active_strength = 0.0

    matrix[0, 0] = 1.0
    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        is_subject = dep in subject_deps
        subject_end = False
        if is_subject:
            pieces = inverse[word.i]
            subject_end = bool(pieces) and i == pieces[-1]
            if subject_end:
                active_subject = i
                if i <= 3:
                    if pos == "PRON":
                        active_strength = 0.18
                    elif word.tag_ in ("NNS", "NNPS"):
                        active_strength = 0.78
                    else:
                        active_strength = 0.48
                else:
                    active_strength = 0.88

        # Articles, fragments, and quotation boundaries mostly use the sink.
        bos = 0.53
        if pos == "DET":
            bos = 0.86
        elif pos == "ADJ":
            bos = 0.68
        elif pos == "PROPN":
            bos = 0.65
        elif pos == "NOUN":
            bos = 0.56
        elif pos in ("VERB", "AUX"):
            bos = 0.43
        elif pos in ("PRON", "ADV", "ADP", "SCONJ", "CCONJ", "PART"):
            bos = 0.49
        elif pos == "PUNCT":
            bos = 0.69

        if not text or tokens[i] in special_tokens:
            bos = 0.90
        elif all(c in "\"'“”‘’`" for c in text):
            bos = 0.87

        if word is not None:
            pieces = inverse[word.i]
            if pieces and i < pieces[-1]:
                bos = max(bos, 0.84)
            if is_subject and subject_end:
                if i <= 3:
                    bos = 0.87 if pos == "PRON" else 0.81
                    if word.tag_ in ("NNS", "NNPS"):
                        bos = 0.40
                else:
                    bos = 0.40

        if i == 1:
            bos = 0.92
        elif i <= 3 and active_subject is None:
            bos = max(bos, 0.82)

        # Subject-bearing clauses divert some sink mass toward their anchor.
        if active_subject is not None and active_subject < i:
            if pos in ("VERB", "AUX", "ADV", "CCONJ", "SCONJ"):
                bos -= 0.12 * active_strength

        bos = float(np.clip(bos, 0.20, 0.96))
        matrix[i, 0] = bos
        remainder = 1.0 - bos

        local = np.exp(-0.32 * (i - np.arange(1, i + 1)))
        local /= local.sum()

        anchor_share = 0.0
        if active_subject is not None:
            anchor_share = min(0.94, 0.35 + 0.65 * active_strength)
            if active_subject == i:
                anchor_share = 0.94
            matrix[i, active_subject] += remainder * anchor_share

        matrix[i, 1:i + 1] += remainder * (1.0 - anchor_share) * local

        # Once the subject's predicate has passed, its anchor is no longer
        # exclusive: release only its explicit off-diagonal anchor component.
        if (
            active_subject is not None
            and active_subject < i
            and aligned[active_subject]
        ):
            subject = doc[aligned[active_subject][-1]]
            predicate = subject.head
            predicate_pieces = inverse[predicate.i]
            if (
                predicate.pos_ in ("VERB", "AUX")
                and predicate_pieces
                and active_subject < predicate_pieces[-1] < i
            ):
                p = predicate_pieces[-1]
                targets = np.zeros(i, dtype=np.float64)
                for j in range(p, i):
                    if aligned[j]:
                        previous = doc[aligned[j][-1]]
                        if (
                            inverse[previous.i][-1] == j
                            and previous.pos_ not in ("DET", "SPACE")
                        ):
                            targets[j] = local[j - 1]
                targets[p] += 0.35
                if word is not None:
                    head_pieces = inverse[word.head.i]
                    if head_pieces and p <= head_pieces[-1] < i:
                        targets[head_pieces[-1]] += 0.25

                released = (
                    remainder * anchor_share
                    * 0.80 * (1.0 - np.exp(-0.32 * (i - p)))
                )
                matrix[i, active_subject] -= released
                sink_share = 0.25 if subject.pos_ == "PRON" else 0.0
                matrix[i, 0] += released * sink_share
                matrix[i, :i] += (
                    released * (1.0 - sink_share) * targets / targets.sum()
                )

    return "bos_sink_subject_anchor", make_row_stochastic(matrix)


def prog_L17H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional decay and weak POS modulation.
    Residual attention is diffuse and recency-biased, with a self-attention component.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.48 + 0.36 * np.exp(-i / 26.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            pos = word.pos_

            if pos == "PRON":
                sink_mass += 0.075
            elif pos == "AUX":
                sink_mass += 0.055
            elif pos == "DET":
                sink_mass += 0.025
            elif pos == "VERB":
                sink_mass -= 0.025
            elif pos == "PUNCT":
                sink_mass -= 0.065

            # Sentence-initial queries often retain a particularly strong sink.
            if word.is_sent_start:
                sink_mass += 0.035

            # Subword continuations also commonly retain substantial BOS mass.
            if i > 1 and alignment[i - 1]:
                if alignment[i][0] == alignment[i - 1][0]:
                    sink_mass += 0.025

        if i == 1:
            sink_mass = 0.90

        sink_mass = float(np.clip(sink_mass, 0.30, 0.95))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        local = np.exp(-(i - positions) / 6.0)
        local /= local.sum()

        residual = 0.50 * local + 0.25 / i
        residual[-1] += 0.25
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_recency", make_row_stochastic(attention)


def prog_L17H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for grammatical and punctuation tokens.
    Content tokens retain more diffuse, recency-biased causal attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_function_word_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "DET": 0.89,
        "ADP": 0.89,
        "CCONJ": 0.92,
        "SCONJ": 0.89,
        "PART": 0.88,
        "AUX": 0.85,
        "PUNCT": 0.87,
        "SPACE": 0.85,
        "PRON": 0.78,
        "ADV": 0.79,
        "ADJ": 0.72,
        "VERB": 0.68,
        "NOUN": 0.64,
        "PROPN": 0.68,
        "NUM": 0.71,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        if aligned:
            sink = sum(
                sink_by_pos.get(doc[k].pos_, 0.74) for k in aligned
            ) / len(aligned)
        elif tokens[i] in tokenizer.all_special_tokens:
            sink = 0.90
        else:
            sink = 0.80

        # A short initial context offers fewer competing destinations.
        if i == 1:
            sink = min(0.94, sink + 0.03)

        attention[i, 0] = sink

        # No non-BOS target is supported consistently by the observations.
        # Use a broad causal background with a modest local preference.
        distance = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.55 / i + 0.45 * (
            np.exp(-distance / 4.0)
            / np.exp(-distance / 4.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink) * background

    return "bos_sink_with_function_word_bias", make_row_stochastic(attention)


def prog_L17H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with an early-position bias and lexical-fragment boosts.
    Residual attention is diffuse and mildly favors recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    first_piece = {}
    piece_count = {}
    for i, indices in enumerate(alignment):
        for k in indices:
            if k not in first_piece:
                first_piece[k] = i
            piece_count[k] = piece_count.get(k, 0) + 1

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.47 + 0.43 * np.exp(-(i - 1) / 9.0)

        indices = alignment[i]
        if indices:
            k = max(
                indices,
                key=lambda j: (
                    not doc[j].is_space,
                    not doc[j].is_punct,
                    len(doc[j].text),
                ),
            )
            word = doc[k]
            pos = word.pos_

            if pos in ("NOUN", "PROPN"):
                sink += 0.045
            elif pos in ("ADJ", "ADV"):
                sink += 0.025
            elif pos in ("ADP", "PART", "CCONJ", "SCONJ"):
                sink -= 0.045
            elif pos == "PUNCT":
                sink -= 0.035

            if word.ent_type_:
                sink += 0.025

            if piece_count.get(k, 0) > 1 and not word.is_punct:
                if first_piece[k] == i:
                    sink += 0.18
                else:
                    offset = i - first_piece[k]
                    sink += 0.07 * np.exp(-(offset - 1) / 1.5) - 0.055

        if i == 1:
            sink = 0.93

        sink = float(np.clip(sink, 0.30, 0.96))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 5.0)
        recent /= recent.sum()
        residual = 0.55 * recent + 0.45 / i
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_lexical_modulation", make_row_stochastic(attention)


def prog_L17H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant first-token attention sink with a weak, recency-biased
    causal background that grows mildly with context length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        background_mass = 0.01 + 0.05 * (1.0 - np.exp(-(i - 1) / 32.0))
        positions = np.arange(1, i + 1)
        background = 0.5 + np.exp(-(i - positions) / 8.0)
        background /= background.sum()

        attention[i, 0] = 1.0 - background_mass
        attention[i, 1:i + 1] = background_mass * background

    return "first_token_sink", attention


def prog_L17H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest at punctuation and clause boundaries.
    Residual attention tracks recent tokens and preceding predicate/preposition anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    special_tokens = set(tokenizer.all_special_tokens)
    words = []
    for indices in aligned:
        candidates = [doc[k] for k in indices if k < len(doc)]
        nonspace = [w for w in candidates if not w.is_space]
        words.append(nonspace[-1] if nonspace else None)

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.46
        if pos in ("NOUN", "PROPN"):
            sink = 0.57
        elif pos == "VERB":
            sink = 0.51
        elif pos == "AUX":
            sink = 0.55
        elif pos == "PRON":
            sink = 0.45
        elif pos == "ADJ":
            sink = 0.40
        elif pos == "ADV":
            sink = 0.47
        elif pos == "DET":
            sink = 0.31
        elif pos in ("ADP", "PART"):
            sink = 0.28
        elif pos == "SCONJ":
            sink = 0.42
        elif pos == "CCONJ":
            sink = 0.73

        if word is not None:
            if word.ent_type_:
                sink += 0.08
            if dep in ("nsubj", "nsubjpass", "csubj"):
                sink += 0.10
            if dep in ("poss", "det"):
                sink -= 0.04
            if dep == "ROOT" and pos in ("VERB", "AUX"):
                sink += 0.07

        # Early queries have fewer competing, meaningful keys.
        sink += 0.24 * np.exp(-(i - 1) / 2.2)
        if i == 1:
            sink = 0.85

        punctuation = (
            bool(clean)
            and all(not c.isalnum() and not c.isspace() for c in clean)
        )
        if punctuation or pos == "PUNCT":
            sink = 0.75
            if any(c in ".!?" for c in clean):
                sink = 0.92
            elif any(c in "'’" for c in clean):
                sink = 0.91
            elif any(c in "\"“”" for c in clean):
                sink = 0.72
            if i <= 4:
                sink = max(sink, 0.81)
        elif not clean:
            sink = 0.58

        if raw in special_tokens:
            sink = 0.95

        sink = float(np.clip(sink, 0.15, 0.97))
        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.22 * np.exp(-(i - positions) / 3.0)
        residual[i] += 0.12
        if i > 1:
            residual[i - 1] += 0.65

        # Leftward syntactic governors are useful, but never override causality.
        if word is not None:
            head_indices = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if head_indices and word.head.i != word.i:
                residual[head_indices[-1]] += 0.55

            # Before a noun arrives, its modifiers often retain the governing
            # preposition or predicate as the active contextual anchor.
            if pos in ("DET", "ADJ", "NOUN", "PRON", "PART"):
                for j in range(i - 1, max(0, i - 9), -1):
                    previous = words[j]
                    if previous is None:
                        continue
                    if previous.pos_ == "PUNCT":
                        break
                    if previous.pos_ in ("ADP", "VERB", "AUX"):
                        residual[j] += 0.95
                        break

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_local_syntax", attention


def prog_L17H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, distance-decaying discourse-object retrieval.
    Clause transitions occasionally redirect attention to earlier content anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    representatives = []
    word_ends = {}
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if k < len(doc)]
        representative = max(
            valid,
            key=lambda k: (not doc[k].is_space, not doc[k].is_punct),
            default=None,
        )
        representatives.append(representative)
        for k in valid:
            word_ends[k] = i

    attention[0, 0] = 1.0
    object_dependencies = {"dobj", "obj", "iobj", "pobj", "attr", "oprd"}
    content_positions = {"NOUN", "PROPN", "VERB", "ADJ"}

    for i in range(1, n):
        k = representatives[i]
        word = doc[k] if k is not None else None

        sink = 0.69 + 0.20 * np.exp(-i / 30.0)
        if word is not None:
            if word.pos_ in {"PRON", "AUX", "ADV"}:
                sink += 0.045
            if word.is_punct:
                sink -= 0.13
            if word.pos_ in {"VERB", "ADP", "CCONJ", "SCONJ"}:
                sink -= 0.045
        if i == 1:
            sink = 0.965 if word is not None and word.pos_ != "DET" else 0.825
        sink = float(np.clip(sink, 0.48, 0.97))

        # The residual is broad and causal rather than a previous-token head.
        positions = np.arange(1, i + 1)
        residual = 0.15 + np.exp(-(i - positions) / 16.0)

        for offset, j in enumerate(positions):
            previous_k = representatives[j]
            if previous_k is None:
                continue
            previous = doc[previous_k]
            if previous.pos_ in content_positions:
                residual[offset] *= 1.35
            if previous.is_punct:
                residual[offset] *= 0.45

        anchors = []
        for previous in doc:
            j = word_ends.get(previous.i)
            if j is None or j == 0 or j >= i:
                continue
            if previous.dep_ in object_dependencies:
                score = np.exp(-(i - j) / 45.0)
                if previous.pos_ in {"NOUN", "PROPN"}:
                    score *= 1.6
                anchors.append((j, score))

        transition = (
            word is not None
            and (
                word.is_sent_start
                or word.is_punct
                or word.pos_ == "ADP"
            )
        )
        anchor_mass = 0.0
        if anchors:
            anchor_mass = 0.14 if transition else 0.045
            if word is not None and word.is_sent_start and i > 4:
                anchor_mass = 0.30
                sink = min(sink, 0.57)

        diffuse_mass = 1.0 - sink - anchor_mass
        attention[i, 0] = sink
        attention[i, 1:i + 1] = diffuse_mass * residual / residual.sum()

        if anchors:
            total = sum(score for _, score in anchors)
            for j, score in anchors:
                attention[i, j] += anchor_mass * score / total

    return "bos_sink_with_discourse_anchors", make_row_stochastic(attention)


def prog_L17H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with increasing diffuse leakage over longer contexts.
    Punctuation and discourse boundaries modestly weaken the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    boundaries = 0
    previous_word = -1

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        if word is not None and word.i != previous_word:
            if word.is_sent_start and word.i > 0:
                boundaries += 1
            previous_word = word.i

        leakage_odds = (0.008 + 0.00055 * i ** 1.65)
        leakage_odds *= 1.0 + 0.18 * boundaries

        if word is not None:
            if word.pos_ == "PUNCT":
                leakage_odds *= 1.8
            elif word.pos_ in ("PRON", "DET", "AUX"):
                leakage_odds *= 0.85

        sink_mass = 1.0 / (1.0 + leakage_odds)

        # The supplied edges strongly identify the sink, but do not establish
        # a reliable non-BOS target; use a broad, mildly recency-biased tail.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        tail = 0.7 + 0.3 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * tail / tail.sum()
        attention[i, 0] = sink_mass

    return "bos_sink_with_context_leakage", attention


def prog_L17H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with predicate links and clause-onset anchors.
    Subjects and nearby predicates retain boundary attention by drawing only from BOS."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        if i == 1:
            attention[i, 0] = 0.995
            attention[i, i] = 0.005
            continue

        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        piece = tokens[i].lstrip("▁Ġ")
        is_punctuation = bool(piece) and all(
            not c.isalnum() and not c.isspace() for c in piece
        )
        continuation = (
            word is not None
            and bool(inverse[word.i])
            and inverse[word.i][0] < i
        )

        sink = 0.67
        if pos in ("NOUN", "PROPN"):
            sink = 0.72
        elif pos in ("ADJ", "ADV"):
            sink = 0.73
        elif pos in ("VERB", "AUX"):
            sink = 0.64
        elif pos in ("DET", "PRON"):
            sink = 0.60
        elif pos in ("ADP", "PART", "SCONJ", "CCONJ"):
            sink = 0.68

        if dep in ("nsubj", "nsubjpass", "csubj") and i <= 4:
            sink = 0.93
        elif i <= 3:
            sink = max(sink, 0.79)
            if pos == "ADJ":
                sink = 0.92

        if (
            word is not None
            and pos in ("NOUN", "PROPN")
            and len(inverse[word.i]) > 1
            and not continuation
        ):
            sink = max(sink, 0.93)

        if piece in ("'", "’"):
            sink = 0.96
        elif is_punctuation:
            sink = 0.68
        elif not piece.strip():
            sink = 0.77

        target = None
        strength = 0.0
        if word is not None:
            head = word.head
            if head.i != word.i and head.pos_ in ("VERB", "AUX"):
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    target = candidates[0]
                    if dep in ("dobj", "obj", "iobj", "dative", "attr", "oprd"):
                        sink = 0.32 if pos == "PRON" else 0.27
                        strength = 0.87
                    elif dep in ("prep", "agent"):
                        sink = 0.49
                        strength = 0.77
                    elif dep in ("ccomp", "xcomp", "advcl"):
                        strength = 0.45
                    elif dep == "punct" and i - target <= 6:
                        sink = 0.54
                        strength = 0.76

            if target is None and dep == "pobj":
                governor = head.head
                if governor.pos_ in ("VERB", "AUX"):
                    candidates = [
                        j for j in inverse[governor.i] if 0 < j < i
                    ]
                    if candidates:
                        target = candidates[0]
                        strength = 0.48
                        sink = min(sink, 0.55)

        if continuation and piece not in ("'", "’"):
            sink = max(sink, 0.70) if strength < 0.7 else sink

        # A broad causal background accounts for the unreported weaker edges.
        positions = np.arange(1, i + 1)
        background = 0.35 + np.exp(-(i - positions) / 7.0)
        for j in range(1, i + 1):
            if alignment[j]:
                previous = doc[alignment[j][-1]]
                if previous.pos_ == "VERB":
                    background[j - 1] *= 1.7
        background /= background.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * (1.0 - strength) * background
        if target is not None:
            attention[i, target] += (1.0 - sink) * strength

        # Special case: a clause-initial subject carries its preceding boundary
        # into the nearby predicate. Move BOS mass only; preserve self/background.
        subject = None
        subject_deps = ("nsubj", "nsubjpass", "csubj")
        if word is not None:
            if dep in subject_deps:
                subject = word
            elif pos == "DET" and word.head.dep_ in subject_deps:
                subject = word.head
            elif pos in ("VERB", "AUX"):
                predicate = word.head if dep in ("aux", "auxpass") else word
                subjects = [
                    child for child in predicate.children
                    if child.dep_ in subject_deps and child.i < word.i
                ]
                if subjects:
                    subject = subjects[-1]

        if subject is not None and subject.left_edge.i > 0:
            boundary = doc[subject.left_edge.i - 1]
            is_anchor = (
                boundary.pos_ in ("PUNCT", "SCONJ", "AUX")
                or (
                    boundary.pos_ == "ADV"
                    and boundary.dep_ == "advmod"
                    and boundary.head.i == subject.head.i
                )
                or (
                    boundary.pos_ == "VERB"
                    and subject.head.dep_ == "ccomp"
                    and subject.head.head.i == boundary.i
                )
            )
            anchors = [j for j in inverse[boundary.i] if 0 < j < i]
            complete_piece = (
                word is not None
                and bool(inverse[word.i])
                and i == inverse[word.i][-1]
            )
            if is_anchor and anchors and complete_piece:
                anchor = anchors[-1]
                if i - anchor <= 4:
                    fraction = (
                        0.65 if dep in subject_deps
                        else 0.40 if pos in ("AUX", "DET")
                        else 0.25
                    )
                    moved = fraction * attention[i, 0]
                    attention[i, 0] -= moved
                    attention[i, anchor] += moved

    return "bos_sink_with_clause_anchors", make_row_stochastic(attention)


def prog_L17H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional decay and linguistic modulation.
    Residual attention is diffuse, with weak recency and syntactic-head biases.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = representatives[i]
        sink = 0.985 - 0.16 * (1.0 - np.exp(-(i - 1) / 24.0))

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.025
            elif word.pos_ in ("PRON", "CCONJ", "SCONJ"):
                sink -= 0.035
            elif word.pos_ == "PUNCT":
                sink -= 0.055

        sink = float(np.clip(sink, 0.65, 0.99))
        weights = np.ones(i, dtype=np.float64)
        positions = np.arange(1, i + 1)
        weights += 0.7 * np.exp(-(i - positions) / 8.0)

        for j in range(1, i + 1):
            previous = representatives[j]
            if previous is not None:
                if previous.pos_ in ("NOUN", "PROPN"):
                    weights[j - 1] *= 1.25
                if (
                    word is not None
                    and word.head.i != word.i
                    and previous.i == word.head.i
                ):
                    weights[j - 1] *= 1.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_weak_residual", attention


def prog_L17H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with short-lived coordination anchors that persist into the
    following phrase; redistribute only BOS mass, preserving self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_coordination_carryover", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        # The null/BOS destination dominates, including on punctuation.
        sink = 0.96 - 0.34 * (1.0 - np.exp(-(i - 1) / 35.0))
        if word is not None:
            if word.pos_ in ("NOUN", "ADJ", "ADP", "DET"):
                sink -= 0.045
            elif word.pos_ == "PUNCT":
                sink += 0.035
            if word.pos_ == "VERB":
                sink += 0.025
        if i <= 3:
            sink = max(sink, 0.94 - 0.025 * (i - 1))

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.12 + np.exp(-(i - positions) / 7.0)
        residual[i] *= 0.45

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if head_positions:
                residual[head_positions[-1]] += 1.5

            # Predicate coordination is the clearest non-sink motif.
            if word.pos_ == "CCONJ" and word.i > 0:
                previous = doc[word.i - 1]
                if previous.pos_ == "ADJ":
                    targets = [
                        j for j in inverse[previous.i] if 0 < j < i
                    ]
                    if targets:
                        sink = 0.10
                        residual *= 0.03
                        residual[targets[-1]] += 12.0

        sink = float(np.clip(sink, 0.08, 0.985))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

        # Extend only local coordination events; leave the original
        # adjective-to-conjunction row and every self-weight unchanged.
        if word is not None:
            for c in range(word.i, max(0, word.i - 6), -1):
                if doc[c].pos_ != "CCONJ":
                    continue
                anchor = doc[c - 1]
                if anchor.pos_ not in ("ADJ", "NOUN"):
                    break
                if c == word.i and anchor.pos_ == "ADJ":
                    break
                if any(doc[k].text in (".", "!", "?")
                       for k in range(c + 1, word.i)):
                    break

                targets = np.zeros(i, dtype=np.float64)
                for j in inverse[anchor.i]:
                    if 0 < j < i:
                        targets[j] = 1.0
                budget = 0.24 * np.exp(-max(0, word.i - c - 1) / 3.0)

                if c == word.i:
                    budget = 0.64
                elif anchor.pos_ == "ADJ":
                    for k in range(c + 1, word.i):
                        if doc[k].pos_ == "ADJ" and doc[k].dep_ == "conj":
                            for j in inverse[k]:
                                if 0 < j < i:
                                    targets[j] += 0.8
                            if word.pos_ in ("PUNCT", "ADV", "SCONJ"):
                                budget = 0.64
                elif c + 1 < word.i and doc[c + 1].pos_ == "ADV":
                    for j in inverse[c + 1]:
                        if 0 < j < i:
                            targets[j] += 2.5
                    budget = 0.55 if word.pos_ in ("PRON", "PART", "AUX") else 0.40

                if targets.sum() > 0:
                    mass = min(budget, max(0.0, attention[i, 0] - 0.08))
                    attention[i, 0] -= mass
                    attention[i, :i] += mass * targets / targets.sum()
                break

    return "bos_sink_with_coordination_carryover", make_row_stochastic(attention)


def prog_L17H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant first-token attention sink with mild linguistic modulation.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # Early positions have fewer competing keys; the sink remains dominant
        # throughout the sequence.
        sink_mass = 0.87 + 0.065 * np.exp(-(i - 1) / 12.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB", "PRON"):
                sink_mass += 0.025
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass -= 0.045
            elif word.pos_ in ("ADP", "CCONJ", "SCONJ", "AUX"):
                sink_mass -= 0.02

        sink_mass = np.clip(sink_mass, 0.78, 0.97)
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )
        attention[i, 0] = sink_mass

    return "first_token_sink", attention


def prog_L17H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant BOS attention sink, gradually diluted by context length.
    Residual attention combines a broad causal background with weak syntactic locality.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_context_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0
    initial_pos = ""
    for word in doc:
        if not word.is_space and not word.is_punct:
            initial_pos = word.pos_
            break

    initial_sink = 0.994
    if initial_pos == "DET":
        initial_sink = 0.963
    elif initial_pos in ("ADP", "ADV"):
        initial_sink = 0.986

    for i in range(1, n):
        sink = initial_sink / (1.0 + 0.00020 * i * i)
        sink = np.clip(sink, 0.40, 0.997)

        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 9.0)

        for wi in alignment[i]:
            word = doc[wi]
            if word.head.i != wi:
                for j in inverse[word.head.i]:
                    if 1 <= j <= i:
                        residual[j - 1] += 0.65
            for child in word.children:
                for j in inverse[child.i]:
                    if 1 <= j <= i:
                        residual[j - 1] += 0.25

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_context_dilution", attention


def prog_L17H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with modest position-dependent leakage.
    Residual attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = np.clip(0.965 - 0.0012 * i, 0.86, 0.965)

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-distances / 6.0)
        recent /= recent.sum()
        residual = 0.7 / i + 0.3 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_leakage", attention


def prog_L17H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal leakage that grows with context length.
    No consistent syntactic or semantic target is supported by the examples.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        # The first token remains dominant even in longer contexts.
        leakage_odds = 0.008 + 0.0022 * i
        sink_mass = 1.0 / (1.0 + leakage_odds)

        # Distribute the unobserved residual conservatively, with mild recency.
        distances = i - np.arange(1, i + 1)
        residual = 0.75 + 0.25 * np.exp(-distances / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_leakage", attention


def prog_L17H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Linguistic features weakly modulate sink strength; residual attention is local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.965 / (1.0 + 0.006 * (i - 1))

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink += 0.035
            elif pos in ("VERB", "ADJ"):
                sink += 0.015
            elif pos in ("AUX", "ADV"):
                sink -= 0.035
            elif pos in ("CCONJ", "SCONJ"):
                sink -= 0.075
            elif pos == "PUNCT":
                sink -= 0.080
            elif pos == "DET":
                sink -= 0.020

            if word.ent_type_:
                sink += 0.015

        sink = float(np.clip(sink, 0.45, 0.985))

        # Keep the non-sink component diffuse, with a modest recency bias.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.65 * np.exp(-distances / 5.0) + 0.35
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L17H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective object-to-verb attention, including pronominal objects.
    Adjectivally or nominally modified objects do not trigger the verb override.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_selective_object_to_verb", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    matrix[0, 0] = 1.0
    function_pos = {
        "DET", "PRON", "ADP", "AUX", "CCONJ", "SCONJ", "PART", "INTJ"
    }
    object_deps = {"dobj", "obj", "dative", "iobj"}
    special_tokens = set(tokenizer.all_special_tokens)

    for i in range(1, n):
        candidates = alignment[i]
        word = None
        if candidates and tokens[i] not in special_tokens:
            word = max(
                (doc[k] for k in candidates),
                key=lambda w: (not w.is_space, not w.is_punct, len(w.text)),
            )

        sink = 0.90
        if word is None:
            sink = 0.97
        elif word.is_punct or word.is_space:
            sink = 0.96
        elif word.pos_ in function_pos:
            sink = 0.93
        elif word.pos_ in {"NOUN", "PROPN"}:
            sink = 0.80
        elif word.pos_ == "VERB":
            sink = 0.89
        elif word.pos_ in {"ADJ", "ADV"}:
            sink = 0.85

        if i == 1:
            sink = max(sink, 0.95)

        # The non-sink background is local and strictly causal.
        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 3.0)
        background /= background.sum()
        matrix[i, 0] = sink
        matrix[i, 1:i + 1] = (1.0 - sink) * background

        # Modified lexical objects retain the default sink/background rather
        # than receiving the otherwise strong object-to-verb override.
        modified_object = (
            word is not None
            and word.pos_ in {"NOUN", "PROPN"}
            and any(
                child.dep_ in {"amod", "compound", "nummod"}
                for child in word.children
            )
        )

        if (
            word is not None
            and word.pos_ in {"NOUN", "PROPN"}
            and word.dep_ in object_deps
            and word.head.pos_ == "VERB"
            and not modified_object
        ):
            head_tokens = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if head_tokens:
                target = head_tokens[0]
                distance = max(1, word.i - word.head.i)
                modifiers = sum(
                    child.dep_ in {"amod", "compound", "nummod"}
                    for child in word.children
                )
                strength = 0.89 * np.exp(-0.065 * max(0, distance - 1))
                strength *= 0.76 ** modifiers

                # Apply the relation at the lexical onset, less on suffix pieces.
                lexical_tokens = inverse[word.i]
                if lexical_tokens and i != lexical_tokens[0]:
                    strength *= 0.70

                strength = float(np.clip(strength, 0.35, 0.92))
                matrix[i] *= 1.0 - strength
                matrix[i, target] += strength

        # Pronominal objects also retrieve their governing verb. Transfer only
        # BOS mass, preserving the original self-attention and local background.
        if (
            word is not None
            and word.pos_ == "PRON"
            and word.dep_ in object_deps
            and word.head.pos_ == "VERB"
        ):
            head_tokens = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if head_tokens:
                distance = max(1, word.i - word.head.i)
                strength = 0.84 * np.exp(-0.065 * max(0, distance - 1))
                lexical_tokens = inverse[word.i]
                if lexical_tokens and i != lexical_tokens[0]:
                    strength *= 0.70
                transfer = min(matrix[i, 0], float(strength))
                matrix[i, 0] -= transfer
                matrix[i, head_tokens[0]] += transfer

    return "bos_sink_with_selective_object_to_verb", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L17H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak POS-dependent strength.
    Remaining attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.78
        if aligned[i]:
            word = doc[aligned[i][0]]
            pos = word.pos_
            if pos == "DET":
                sink += 0.06
            elif pos == "ADP":
                sink += 0.04
            elif pos == "VERB":
                sink += 0.02
            elif pos == "AUX":
                sink -= 0.07
            elif pos in ("ADJ", "ADV", "CCONJ", "SCONJ"):
                sink -= 0.04

        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if surface and all(c in ".!?\"'”’" for c in surface):
            sink += 0.06
        elif surface and all(c in ",;:" for c in surface):
            sink -= 0.03

        if i == 1:
            sink = 0.90

        sink = float(np.clip(sink, 0.62, 0.94))
        distances = i - np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-distances / 6.0) / np.exp(-distances / 6.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_pos_modulated", make_row_stochastic(attention)


def prog_L17H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with POS-dependent strength and weak local syntactic attention.
    Content tokens retain more attention on nearby governors than boundary tokens do.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    special_tokens = tokenizer.all_special_tokens
    sink_strength = {
        "PROPN": 0.955,
        "PRON": 0.900,
        "DET": 0.910,
        "PART": 0.910,
        "SCONJ": 0.875,
        "CCONJ": 0.855,
        "ADP": 0.865,
        "AUX": 0.815,
        "VERB": 0.775,
        "NOUN": 0.755,
        "ADJ": 0.690,
        "ADV": 0.750,
        "NUM": 0.825,
        "PUNCT": 0.925,
        "SPACE": 0.975,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        word = doc[aligned[i][0]] if aligned[i] else None
        mass = sink_strength.get(word.pos_, 0.860) if word is not None else 0.930

        if tokens[i] in special_tokens or not clean.strip():
            mass = 0.975
        elif all(not c.isalnum() for c in clean):
            mass = 0.935

        if word is not None:
            pieces = inverse[word.i]
            if len(pieces) > 1 and word.pos_ != "PUNCT":
                mass = max(mass, 0.915 if i == pieces[0] else 0.890)
            if word.dep_ in ("pobj", "obl", "obj", "dobj") and len(pieces) == 1:
                mass -= 0.055

        if i == 1:
            mass = max(mass, 0.975)

        # Residual attention is causal and local, with a modest syntax preference.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual[-1] *= 0.65

        if word is not None:
            head = word.head
            if head.i != word.i:
                for j in inverse[head.i]:
                    if 0 < j <= i:
                        residual[j - 1] += 2.5
            for child in word.children:
                for j in inverse[child.i]:
                    if 0 < j < i:
                        residual[j - 1] += 0.35

        attention[i, 0] = mass
        attention[i, 1:i + 1] = (1.0 - mass) * residual / residual.sum()

    return "bos_sink_with_syntactic_residual", attention


def prog_L17H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A BOS sink with a stronger diagonal alternative for noninitial pronouns.
    Subject-adjacent modal auxiliaries also divert sink mass to self and subject."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pronominal_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = alignment[i]
        word = doc[words[0]] if words else None

        sink = 0.68 + 0.09 * np.exp(-(i - 1) / 5.0)
        previous_share = 0.28

        if word is not None:
            if word.pos_ in ("ADP", "DET", "AUX", "PART"):
                sink += 0.055
            elif word.pos_ in ("NOUN", "PRON"):
                sink -= 0.045
            elif word.pos_ == "CCONJ":
                sink -= 0.12
                previous_share = 0.65

            # Within-word fragments have a stronger self/local alternative.
            if i > 1 and any(k in alignment[i - 1] for k in words):
                sink -= 0.10
                previous_share = 0.20

        if i == 1:
            sink = 0.79

        sink = float(np.clip(sink, 0.45, 0.86))
        attention[i, 0] = sink

        # Preserve the original residual allocation.
        residual = np.zeros(i + 1, dtype=np.float64)
        residual[1:] = 0.10 * np.exp(
            -(i - np.arange(1, i + 1)) / 4.0
        )
        residual[i] += 1.0 - previous_share
        if i > 1:
            residual[i - 1] += previous_share

        residual /= residual.sum()
        attention[i, :i + 1] += (1.0 - sink) * residual

        # Only these special cases move mass; all other edges stay unchanged.
        if i > 1 and word is not None:
            previous_words = alignment[i - 1]
            continuation = any(k in previous_words for k in words)
            if word.pos_ == "PRON" and not continuation:
                transfer = min(0.22, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, i] += transfer
            elif word.pos_ == "AUX" and word.tag_ == "MD" and previous_words:
                previous = doc[previous_words[0]]
                if (
                    previous.pos_ == "PRON"
                    and previous.dep_ in ("nsubj", "nsubjpass")
                    and previous.head.i == word.head.i
                    and not continuation
                ):
                    transfer = min(0.30, attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i, i] += 0.75 * transfer
                    attention[i, i - 1] += 0.25 * transfer

    return "bos_sink_with_pronominal_residual", attention


def prog_L17H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with selective backward links to object-governing
    verbs and prepositions, including the beginnings of their argument phrases.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_argument_links", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, aligned in enumerate(alignment):
        for sid in aligned:
            inverse[sid].append(i)

    matrix[0, 0] = 1.0
    specials = set(tokenizer.all_special_tokens)

    for i in range(1, n):
        # A small diffuse causal component accompanies the dominant sink.
        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 5.0)
        background /= background.sum()

        sink_mass = 0.93
        target = None
        link_mass = 0.0
        raw = tokens[i]

        if raw in specials or not alignment[i]:
            sink_mass = 0.97
        else:
            word = doc[alignment[i][-1]]
            pos = word.pos_
            dep = word.dep_

            if word.is_punct or word.is_space:
                sink_mass = 0.965
            elif pos in ("ADP", "PART", "CCONJ", "SCONJ"):
                sink_mass = 0.94
            elif pos in ("VERB", "AUX", "ADV"):
                sink_mass = 0.92
            elif pos in ("DET", "ADJ", "NUM"):
                sink_mass = 0.86
            elif pos in ("NOUN", "PROPN", "PRON"):
                sink_mass = 0.82

            if not word.is_punct and not word.is_space:
                argument = word
                phrase_factor = 1.0

                # Argument-initial determiners can already identify the governor.
                if dep in ("det", "poss", "amod", "nummod"):
                    argument = word.head
                    phrase_factor = {
                        "det": 0.76,
                        "poss": 0.48,
                        "amod": 0.25,
                        "nummod": 0.35,
                    }[dep]

                governor = argument.head
                relation = argument.dep_
                strength = 0.0

                if relation in ("dobj", "obj", "iobj", "dative"):
                    strength = 0.80
                    if argument.pos_ == "PRON":
                        strength = 0.86
                elif relation in ("pobj", "obl"):
                    strength = 0.57
                elif relation in ("attr", "oprd"):
                    strength = 0.32
                elif relation in ("nsubj", "nsubjpass"):
                    # A subordinate subject may point back to the verb that
                    # introduced its clause, rather than its future predicate.
                    if governor.dep_ in ("ccomp", "xcomp"):
                        governor = governor.head
                        strength = 0.57

                candidates = [
                    j for j in inverse[governor.i] if 0 < j < i
                ]
                if strength and candidates and governor.i != argument.i:
                    target = candidates[-1]
                    distance = i - target
                    locality = np.exp(-max(distance - 3, 0) / 22.0)
                    link_mass = strength * phrase_factor * locality

                    # Incomplete lexical pieces mostly retain the sink;
                    # argument selection is stronger at word completion.
                    pieces = inverse[word.i]
                    if pieces and i != pieces[-1]:
                        link_mass *= 0.12
                        sink_mass = max(sink_mass, 0.95)

        if i == 1:
            sink_mass = max(sink_mass, 0.94)
            link_mass = 0.0

        if target is not None and link_mass > 0.0:
            remainder = 1.0 - link_mass
            matrix[i] = 0.045 * remainder * background
            matrix[i, 0] += 0.955 * remainder
            matrix[i, target] += link_mass
        else:
            matrix[i] = (1.0 - sink_mass) * background
            matrix[i, 0] += sink_mass

    return "bos_sink_with_argument_links", make_row_stochastic(matrix)


def prog_L17H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with syntactic residuals; prepositional noun phrases retain
    attention to their introducing preposition rather than a distant verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prepositional_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].lstrip("▁Ġ")
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = {
            "PRON": 0.935,
            "AUX": 0.935,
            "CCONJ": 0.875,
            "SCONJ": 0.885,
            "ADV": 0.895,
            "PART": 0.885,
            "INTJ": 0.935,
            "PUNCT": 0.940,
            "VERB": 0.785,
            "NOUN": 0.755,
            "PROPN": 0.835,
            "ADJ": 0.805,
            "ADP": 0.675,
            "DET": 0.625,
            "NUM": 0.755,
        }.get(pos, 0.84)

        if dep in ("nsubj", "nsubjpass", "csubj", "expl"):
            sink = max(sink, 0.945)
        elif dep in ("poss", "nmod:poss"):
            sink = 0.48
        elif dep in ("dobj", "obj", "pobj"):
            sink = max(sink, 0.79)

        punctuation = bool(text) and all(
            not c.isalnum() and not c.isspace() for c in text
        )
        if punctuation or not text.strip():
            sink = 0.95

        # Resolve a governing verb only when it is already causally available.
        governor = None
        if word is not None:
            ancestor = word.head
            visited = set()
            while ancestor.i not in visited:
                visited.add(ancestor.i)
                candidates = [
                    ti for ti in inverse[ancestor.i] if 0 < ti < i
                ]
                if ancestor.pos_ == "VERB" and candidates:
                    governor = candidates[-1]
                    break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

        introducer = pos == "DET" or dep in ("poss", "nmod:poss")
        if introducer and governor is not None:
            sink = 0.30 if governor == i - 1 else 0.49

        # Nonfinite predicates can retain substantial attention to themselves.
        self_weight = 0.30
        if pos == "VERB" and word is not None:
            if "Ger" in word.morph.get("VerbForm"):
                sink = min(sink, 0.43)
                self_weight = 2.5

        # Later pieces of a split word tend to revert toward the sink.
        if indices and i > 1 and set(indices).intersection(alignment[i - 1]):
            sink = max(sink, 0.855)

        if i == 1:
            sink = 0.89 if pos == "DET" else 0.982

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = self_weight
        if i > 1:
            residual[1:i] = 0.12 * np.exp(
                -0.45 * (i - np.arange(1, i))
            )
            residual[i - 1] += 0.35
        if governor is not None:
            residual[governor] += 3.0 if introducer else 0.60

        # Special case: stay inside a nominal dependency chain and find its
        # introducing ADP. Never climb through a verb into an unrelated PP.
        if word is not None and (
            pos in ("DET", "ADJ", "NOUN", "PROPN", "NUM") or introducer
        ) and not punctuation and text.strip():
            nominal = word
            visited = set()
            while (
                nominal.i not in visited
                and nominal.dep_ in (
                    "det", "poss", "nmod:poss", "amod",
                    "compound", "nummod"
                )
                and nominal.head.pos_ in ("NOUN", "PROPN", "PRON")
            ):
                visited.add(nominal.i)
                nominal = nominal.head

            prep = nominal.head
            anchors = [
                ti for ti in inverse[prep.i] if 0 < ti < i
            ] if (
                nominal.dep_ in ("pobj", "obj")
                and prep.pos_ == "ADP"
            ) else []

            if anchors:
                anchor = anchors[-1]
                # Replace only the inappropriate distant-verb increment.
                if governor is not None:
                    residual[governor] -= 3.0 if introducer else 0.60
                residual[:i] *= 0.20
                residual[anchor] += 1.10 if introducer else 0.80

                if introducer:
                    sink = 0.28 if governor is not None else 0.40
                elif pos in ("ADJ", "NUM"):
                    sink = 0.28
                else:
                    sink = 0.35 if dep == "compound" else 0.56
                    for child in nominal.children:
                        if child.dep_ in ("det", "poss", "nmod:poss"):
                            preceding = [
                                ti for ti in inverse[child.i]
                                if 0 < ti < i
                            ]
                            if preceding:
                                residual[preceding[-1]] += 0.45

                if i > 1 and set(indices).intersection(alignment[i - 1]):
                    sink = max(sink, 0.65)

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    return "bos_sink_with_prepositional_residual", make_row_stochastic(attention)


def prog_L17H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with object routing gated by subword completion.
    Completed nominal objects share verb attention with modifiers; object pronouns select their verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_gated_object_route", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_indices in enumerate(alignment):
        for k in word_indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = None
        for k in alignment[i]:
            if 0 <= k < len(doc):
                candidate = doc[k]
                if word is None or (word.is_space and not candidate.is_space):
                    word = candidate

        sink = 0.86
        governor = None
        governor_mass = 0.0

        if tokens[i] in special_tokens:
            sink = 0.97
        elif word is not None:
            pos = word.pos_
            dep = word.dep_

            if word.is_space:
                sink = 0.92
            elif word.is_punct:
                sink = 0.87
            elif pos in ("DET", "AUX", "PART", "PRON"):
                sink = 0.90
            elif pos in ("CCONJ", "SCONJ", "ADP"):
                sink = 0.85
            elif pos in ("VERB", "ADV", "ADJ"):
                sink = 0.81
            elif pos in ("NOUN", "PROPN", "NUM"):
                sink = 0.77

            if word.head.i != word.i:
                earlier = [
                    j for j in inverse[word.head.i]
                    if 0 < j < i
                ]
                if earlier:
                    governor = earlier[0]
                    if (
                        pos in ("NOUN", "PROPN")
                        and dep in ("dobj", "obj", "iobj", "dative", "attr", "oprd")
                        and word.head.pos_ in ("VERB", "AUX")
                    ):
                        sink = 0.28
                        governor_mass = 0.64
                    elif pos in ("NOUN", "PROPN") and dep in ("pobj", "obl"):
                        sink = 0.64
                        governor_mass = 0.20
                    elif dep in ("advmod", "acomp", "xcomp", "ccomp"):
                        governor_mass = min(0.12, 1.0 - sink)

        # The first few positions exhibit especially strong sink behavior.
        if i == 1:
            sink = 0.97
            governor_mass = 0.0
        elif i <= 3 and governor_mass < 0.30:
            sink = max(sink, 0.91)
            governor_mass = min(governor_mass, 0.03)

        residual = max(0.0, 1.0 - sink - governor_mass)
        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 4.0)
        background /= background.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = residual * background
        if governor is not None:
            attention[i, governor] += governor_mass
        else:
            attention[i, 0] += governor_mass

        # Transfer only off-diagonal mass; keep the original self weight
        # and residual decay exactly unchanged.
        if (
            word is not None
            and tokens[i] not in special_tokens
            and governor is not None
            and word.head.pos_ in ("VERB", "AUX")
            and word.dep_ in ("dobj", "obj", "iobj", "dative", "attr", "oprd")
        ):
            pieces = [j for j in inverse[word.i] if j > 0]
            modifiers = [
                child for child in word.children
                if child.dep_ in ("det", "poss", "amod", "nummod", "compound")
                and child.i < word.i
            ]
            modifier_positions = sorted({
                j for child in modifiers for j in inverse[child.i]
                if 0 < j < i and j != governor
            })

            if word.pos_ in ("NOUN", "PROPN") and governor_mass > 0:
                incomplete = bool(pieces) and i < max(pieces)
                if incomplete or len(pieces) > 1 or modifier_positions:
                    retained = 0.03 if incomplete else 0.20
                    moved = max(0.0, governor_mass - retained)
                    attention[i, governor] -= moved

                    share = 0.0
                    if not incomplete and modifier_positions:
                        share = (
                            0.80 if any(c.dep_ == "amod" for c in modifiers)
                            else 0.35
                        )
                        targets = np.asarray(modifier_positions, dtype=np.int64)
                        weights = np.exp(-(i - targets) / 3.0)
                        weights /= weights.sum()
                        attention[i, targets] += moved * share * weights
                    attention[i, 0] += moved * (1.0 - share)

            elif (
                word.pos_ == "PRON"
                and word.dep_ in ("dobj", "obj", "iobj", "dative")
                and pieces
                and i == max(pieces)
                and i > 3
            ):
                verb_end = max(j for j in inverse[word.head.i] if 0 < j < i)
                moved = min(attention[i, 0], 0.44 if i - verb_end <= 2 else 0.30)
                attention[i, 0] -= moved
                attention[i, governor] += moved

    return "bos_sink_with_gated_object_route", make_row_stochastic(attention)


def prog_L17H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a special-case noun-phrase anchor pathway.
    Modified and possessive noun phrases redirect sink mass to their introducers.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_np_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    sink_by_pos = {
        "PRON": 0.945,
        "DET": 0.905,
        "AUX": 0.925,
        "PART": 0.940,
        "SCONJ": 0.920,
        "CCONJ": 0.875,
        "ADP": 0.875,
        "PUNCT": 0.950,
        "SPACE": 0.960,
        "VERB": 0.805,
        "ADV": 0.805,
        "NOUN": 0.610,
        "PROPN": 0.755,
        "ADJ": 0.645,
        "NUM": 0.735,
        "INTJ": 0.890,
    }

    # Inverse alignment is used only by the noun-phrase exception.
    word_pieces = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for wi in indices:
            word_pieces[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        piece = tokens[i]
        # Remove tokenizer boundary markers, not lexical material.
        clean = piece.lstrip("▁Ġ")
        words = [doc[k] for k in aligned[i]]
        word = max(words, key=lambda w: len(w.text)) if words else None

        if piece in special_tokens:
            sink = 0.970
        elif not clean or clean.isspace():
            sink = 0.960
        elif all(not c.isalnum() and not c.isspace() for c in clean):
            sink = 0.950
        elif word is not None:
            sink = sink_by_pos.get(word.pos_, 0.780)
            if word.dep_ in ("mark", "aux", "auxpass", "expl"):
                sink = max(sink, 0.935)
            elif word.dep_ in ("nsubj", "nsubjpass") and word.pos_ == "PRON":
                sink = max(sink, 0.955)
        else:
            sink = 0.790

        if i == 1:
            sink = max(sink, 0.940)

        # Residual attention favors recent tokens, with a small self component.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local[-1] *= 0.35

        if i > 1:
            local[-2] *= 2.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Exception: an introduced, modified or possessive noun phrase.
        # The default decay and self-attention remain exactly unchanged.
        if word is not None and word.pos_ in ("ADJ", "NOUN", "PROPN"):
            head = word
            while head.dep_ in ("amod", "compound") and head.head.i != head.i:
                head = head.head

            if head.pos_ not in ("NOUN", "PROPN"):
                continue

            children = list(head.children)
            modifiers = [
                c for c in children if c.dep_ in ("amod", "compound")
            ]
            introducers = [
                c for c in children if c.dep_ in ("det", "poss")
            ]
            if not introducers or not (
                modifiers or any(c.dep_ == "poss" for c in introducers)
            ):
                continue

            anchors = []
            for intro in introducers:
                candidates = list(word_pieces[intro.i])
                if intro.dep_ == "poss":
                    for child in intro.children:
                        if child.dep_ == "case":
                            candidates.extend(word_pieces[child.i])
                candidates = [j for j in candidates if 0 < j < i]
                if candidates:
                    anchors.append(max(candidates))
            if not anchors:
                continue

            targets = np.zeros(i + 1, dtype=np.float64)
            for j in anchors:
                targets[j] += 1.0 / len(anchors)

            previous_modifiers = []
            for modifier in modifiers:
                if modifier.i != word.i:
                    candidates = [
                        j for j in word_pieces[modifier.i] if 0 < j < i
                    ]
                    if candidates:
                        previous_modifiers.append(max(candidates))
            if previous_modifiers:
                targets *= 0.70
                for j in previous_modifiers:
                    targets[j] += 0.30 / len(previous_modifiers)

            target_sink = 0.43 if not previous_modifiers else 0.36
            moved = max(0.0, attention[i, 0] - target_sink)
            attention[i, 0] -= moved

            # A continuation piece should retain the phrase anchor rather
            # than treating the preceding piece as a new lexical neighbor.
            for j in word_pieces[word.i]:
                if 0 < j < i:
                    redirected = 0.75 * attention[i, j]
                    attention[i, j] -= redirected
                    moved += redirected

            attention[i, :i + 1] += moved * targets

    return "bos_sink_with_np_anchors", attention


def prog_L18H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional weakening and a local syntactic backup.
    Coordinating conjunctions preferentially read the preceding conjunct."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        pos = word.pos_ if word is not None else ""

        sink = 0.975 - 0.55 * (1.0 - np.exp(-(i - 1) / 40.0))
        if pos in ("NOUN", "PROPN"):
            sink += 0.035
        elif pos == "PUNCT":
            sink -= 0.085
        elif pos == "CCONJ":
            sink -= 0.38
            if alignment[i - 1]:
                previous = doc[alignment[i - 1][-1]]
                if previous.pos_ in ("ADJ", "VERB"):
                    sink -= 0.16
        elif pos == "SCONJ":
            sink -= 0.12

        # Later pieces of a word have a somewhat stronger local alternative.
        if i > 1 and alignment[i] and alignment[i - 1]:
            if alignment[i][0] in alignment[i - 1]:
                sink -= 0.065

        sink = float(np.clip(sink, 0.20, 0.985))

        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        local[-1] *= 0.45
        if i > 1:
            local[-2] += 1.5

        if word is not None:
            # Only already-visible syntactic targets can receive attention.
            head_positions = inverse[word.head.i]
            for j in head_positions:
                if 0 < j < i:
                    local[j - 1] += 1.0

            if pos == "CCONJ" and i > 1:
                local[i - 2] += 8.0

            for child in word.children:
                if child.dep_ in ("amod", "advmod", "compound", "nsubj", "obj"):
                    for j in inverse[child.i]:
                        if 0 < j < i:
                            local[j - 1] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_local_syntax", attention


def prog_L18H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with mildly increasing residual attention over longer prefixes."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.995 - 0.10 * (1.0 - np.exp(-(i - 1) / 24.0))

        # The observations strongly constrain the sink, but not the residual:
        # use a diffuse causal distribution with only a weak recency bias.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-distances / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L18H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink with weak causal recency.
    Punctuation slightly increases the residual attention outside the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        is_punctuation = bool(aligned) and all(
            doc[k].is_punct for k in aligned
        )

        sink_mass = 0.97 - 0.035 * (1.0 - np.exp(-i / 32.0))
        if is_punctuation:
            sink_mass -= 0.10

        # The examples constrain the sink far more strongly than the residual;
        # use a smooth, nonspecific causal prior for the remaining mass.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L18H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with sparse modifier exceptions restricted to local syntactic scope.
    Prevent negation and adverb anchors from leaking into unrelated clauses.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_modifier_scope", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        # Preserve the original causal background and sink initialization.
        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 4.0)
        background /= background.sum()

        sink = 0.81
        if i == 1:
            sink = 0.987
        elif i <= 3:
            sink = 0.93

        if word is not None:
            pos = word.pos_
            if i > 3:
                if pos in ("DET", "PROPN"):
                    sink = 0.90
                elif pos == "PRON":
                    sink = 0.63
                elif pos in ("NOUN", "VERB", "ADJ", "ADV"):
                    sink = 0.72
                elif pos in ("AUX", "ADP", "PART"):
                    sink = 0.77
                elif pos == "PUNCT":
                    sink = 0.84

            if inverse[word.i] and inverse[word.i][-1] > i:
                sink = max(sink, 0.965)
        elif tokens[i].isspace() or tokens[i] in tokenizer.all_special_tokens:
            sink = 0.92

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

        candidates = {}
        if word is not None:
            for k in range(max(0, word.i - 8), word.i + 1):
                modifier = doc[k]
                available = [j for j in inverse[k] if 0 < j <= i]
                if not available:
                    continue

                strength = 0.0
                distance = word.i - k
                related = (
                    modifier.head.i == word.i
                    or modifier.head.i == word.head.i
                    or modifier.head.i == word.head.head.i
                )
                if modifier.dep_ == "neg" and distance <= 6:
                    strength = 0.91 if related else 0.55
                elif modifier.pos_ == "ADV" and modifier.dep_ == "advmod":
                    if related and distance <= 5:
                        strength = 0.60
                elif (
                    modifier.pos_ == "ADP"
                    and word.dep_ == "pobj"
                    and word.head.i == k
                    and modifier.head.pos_ in ("NOUN", "PROPN")
                ):
                    strength = 0.72

                # New: constrain only the exceptional modifier-routing path.
                if strength:
                    if modifier.dep_ == "neg":
                        # A negation fragment is not its own scope; shared
                        # grandparents do not license later-clause attention.
                        in_scope = (
                            modifier.i < word.i
                            and modifier.head.i == word.i
                            and inverse[k][-1] < i
                        )
                        strength = min(strength, 0.48) if in_scope else 0.0
                    elif modifier.pos_ == "ADV":
                        local_scope = (
                            modifier.head.i == word.i
                            or (
                                modifier.head.i == word.head.i
                                and word.dep_ not in ("xcomp", "ccomp", "advcl")
                            )
                        )
                        crosses_boundary = any(
                            doc[j].is_punct
                            for j in range(k + 1, word.i)
                        )
                        if not local_scope or crosses_boundary or word.is_punct:
                            strength = 0.0
                        elif modifier.i == word.i:
                            strength = min(strength, 0.20)
                        elif modifier.head.pos_ not in ("ADJ", "ADV"):
                            strength = min(strength, 0.25)
                    elif modifier.pos_ == "ADP":
                        # Nominal attachment alone is weak evidence of an anchor.
                        strength = min(strength, 0.18)

                if strength:
                    candidates[available[-1]] = strength

            # Preserve the original coordination-boundary exception.
            if word.dep_ == "conj" and word.pos_ in ("NOUN", "PROPN"):
                previous = word.i - 1
                if previous >= 0 and doc[previous].text == ",":
                    available = [j for j in inverse[previous] if 0 < j < i]
                    if available:
                        candidates[available[-1]] = 0.92

        if candidates:
            target = max(candidates, key=candidates.get)
            strength = candidates[target]
            attention[i] *= 1.0 - strength
            attention[i, target] += strength

    return "bos_sink_with_local_modifier_scope", make_row_stochastic(attention)


def prog_L18H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak linguistic modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.965 - 0.001 * min(i, 70)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ in ("DET", "PRON"):
                sink_mass += 0.015
            elif word.pos_ in ("PUNCT", "SPACE"):
                sink_mass -= 0.065
            elif word.pos_ in ("ADV", "CCONJ", "SCONJ"):
                sink_mass -= 0.020

        if i == 1:
            sink_mass = 0.982

        sink_mass = np.clip(sink_mass, 0.80, 0.99)
        positions = np.arange(1, i + 1)
        residual = 0.5 + 0.5 * np.exp(-(i - positions) / 8.0)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_weak_recency", attention


def prog_L18H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, length-dependent causal leakage.
    Punctuation modestly increases leakage into recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_causal_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The first token overwhelmingly dominates, even far into the text.
        leakage_odds = 0.005 + 0.0006 * i + 0.000025 * i * i

        aligned = alignment[i] if i < len(alignment) else []
        if any(doc[k].pos_ == "PUNCT" for k in aligned):
            leakage_odds *= 1.5

        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        # Residual attention is diffuse, with a small recency preference.
        distances = i - np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_causal_leakage", make_row_stochastic(attention)


def prog_L18H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker discourse-boundary and syntactic routing.
    Content tokens favor BOS; quotation boundaries can retrieve earlier participants.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_discourse_routing", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    quotes = {'"', "'", "“", "”", "‘", "’", "«", "»"}
    matrix[0, 0] = 1.0
    discourse_anchor = None
    in_quote = False
    boundary_pending = False

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        is_punct = bool(clean) and all(not c.isalnum() for c in clean)
        is_quote = any(c in quotes for c in clean)
        # Apostrophes inside words are not dialogue delimiters.
        if word is not None and not word.is_punct:
            is_quote = False

        sink = 0.965 - 0.16 * (1.0 - np.exp(-i / 32.0))
        if pos in ("NOUN", "PROPN", "ADJ", "NUM"):
            sink += 0.025
        elif pos in ("ADP", "CCONJ", "SCONJ", "PART"):
            sink -= 0.045
        if is_punct:
            sink -= 0.18
        if not clean:
            sink -= 0.16
        sink = float(np.clip(sink, 0.50, 0.985))

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[1:] = 0.08 * np.exp(
            -(i - np.arange(1, i + 1)) / 12.0
        )
        residual[i] += 0.12

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    residual[j] += 0.45
            for earlier in reversed(doc[:word.i]):
                if earlier.pos_ in ("NOUN", "PROPN"):
                    candidates = [j for j in inverse[earlier.i] if 0 < j < i]
                    if candidates:
                        residual[candidates[0]] += 0.30
                        break

        if is_quote:
            if not in_quote:
                if word is not None:
                    for earlier in reversed(doc[:word.i]):
                        if earlier.pos_ in ("NOUN", "PROPN"):
                            candidates = [
                                j for j in inverse[earlier.i] if 0 < j < i
                            ]
                            if candidates:
                                discourse_anchor = candidates[0]
                                break
                in_quote = True
            else:
                in_quote = False
                boundary_pending = True
                if discourse_anchor is not None:
                    sink = min(sink, 0.40)
                    residual[discourse_anchor] += 4.0
        elif boundary_pending and clean and not is_punct:
            if discourse_anchor is not None:
                sink = min(sink, 0.48)
                residual[discourse_anchor] += 4.0
            boundary_pending = False

        if tokens[i] in special_tokens:
            sink = 0.98

        matrix[i, 0] = sink
        total = residual.sum()
        if total > 0:
            matrix[i, :i + 1] += (1.0 - sink) * residual / total
        else:
            matrix[i, 0] = 1.0

    return (
        "bos_sink_with_discourse_routing",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L18H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, recency-biased causal leakage.
    Non-BOS attention grows modestly with position and at punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_causal_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        punctuation = any(doc[k].pos_ == "PUNCT" for k in alignment[i])
        leakage = min(0.10, 0.004 + 0.0015 * (i - 1))
        if punctuation:
            leakage = min(0.15, leakage + 0.025)

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp((positions - i) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * residual

    return "bos_sink_with_causal_leakage", attention


def prog_L18H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary fallback; prepositional objects additionally
    retrieve their governing phrase rather than the preceding determiner."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pp_retrieval", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Updated causally so phrase anchors use their latest completed subtoken.
    last_seen = {}

    for i in range(1, n):
        sids = aligned[i]
        word = doc[sids[-1]] if sids else None
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        sink = 0.94

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.97
        elif not surface:
            sink = 0.85
        elif word is not None:
            pos = word.pos_
            dep = word.dep_
            first_piece = i == 0 or word.i not in aligned[i - 1]
            last_piece = i + 1 == n or word.i not in aligned[i + 1]

            if pos in ("DET", "ADP", "AUX", "PART"):
                sink = 0.96
            elif pos == "VERB":
                sink = 0.95
            elif pos == "PRON":
                sink = 0.94 if dep not in ("obj", "dobj", "pobj") else 0.84
            elif pos in ("NOUN", "PROPN"):
                sink = 0.88
                if first_piece and not last_piece:
                    sink = 0.97
                elif not first_piece:
                    sink = 0.87
            elif pos == "ADJ":
                sink = 0.94 if dep == "amod" else 0.85
            elif pos == "ADV":
                sink = 0.86
            elif pos == "SCONJ":
                sink = 0.90
            elif pos == "CCONJ":
                sink = 0.43
            elif pos == "PUNCT":
                if "," in surface or ";" in surface or ":" in surface:
                    sink = 0.28
                elif any(c in surface for c in ".!?"):
                    sink = 0.68
                else:
                    sink = 0.82

            # Phrase-final content is less strongly absorbed by the sink.
            if last_piece and pos in ("NOUN", "PROPN", "ADJ", "ADV"):
                if word.i + 1 < len(doc):
                    following = doc[word.i + 1]
                    if following.pos_ in ("PUNCT", "CCONJ"):
                        sink = min(sink, 0.70)

        attention[i, 0] = sink
        residual = 1.0 - sink

        # Most non-sink mass is local, with a small causal recency tail.
        attention[i, i - 1] += residual * 0.80
        attention[i, i] += residual * 0.12
        positions = np.arange(i + 1)
        tail = np.exp((positions - i) / 3.0)
        attention[i, :i + 1] += residual * 0.08 * tail / tail.sum()

        # Only completed nominal PP objects trigger phrase retrieval.
        # Move existing mass without changing the diagonal or recency tail.
        if (
            word is not None
            and tokens[i] not in tokenizer.all_special_tokens
            and surface
            and word.pos_ in ("NOUN", "PROPN")
            and word.dep_ == "pobj"
            and word.head.pos_ == "ADP"
            and (i + 1 == n or word.i not in aligned[i + 1])
        ):
            prep = word.head
            governor = prep.head
            targets = []
            for anchor, weight in ((governor, 0.65), (prep, 0.30)):
                j = last_seen.get(anchor.i)
                if j is not None and 0 < j < i:
                    targets.append((j, weight))
            for child in word.children:
                if child.dep_ in ("compound", "amod"):
                    j = last_seen.get(child.i)
                    if j is not None and 0 < j < i:
                        targets.append((j, 0.25))

            if targets and governor.i in last_seen:
                moved = min(0.40, attention[i, 0])
                attention[i, 0] -= moved
                if i > 1:
                    local = residual * 0.80 * 0.75
                    attention[i, i - 1] -= local
                    moved += local
                total = sum(weight for _, weight in targets)
                for j, weight in targets:
                    attention[i, j] += moved * weight / total

        for sid in sids:
            last_seen[sid] = i

    return "bos_sink_with_pp_retrieval", make_row_stochastic(attention)


def prog_L18H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink head with sparse attention to fronted predicates/objects
    when an embedded subject follows a wh-modified phrase.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_fronted_phrase", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        # Most queries park almost all their probability at the first token.
        sink = 0.965 - 0.0014 * min(i, 65)
        if word is not None:
            if word.pos_ == "PUNCT":
                sink -= 0.045
            elif word.pos_ == "PRON":
                sink -= 0.025

        residual = np.exp(
            -(i - np.arange(1, i + 1, dtype=np.float64)) / 5.0
        )

        # A small dependency component accounts for ordinary non-sink mass.
        if word is not None:
            for target in inverse[word.head.i]:
                if 0 < target <= i:
                    residual[target - 1] += 0.8

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # In fronted wh-phrases, the following subject can retrieve the
        # immediately preceding predicate or object rather than the sink.
        if (
            word is None
            or word.pos_ != "PRON"
            or word.dep_ not in ("nsubj", "nsubjpass")
            or word.i == 0
        ):
            continue

        previous = doc[word.i - 1]
        if previous.pos_ not in ("ADJ", "NOUN"):
            continue

        phrase_start = max(0, previous.i - 3)
        has_wh_modifier = any(
            doc[k].tag_ in ("WRB", "WDT", "WP", "WP$")
            for k in range(phrase_start, previous.i)
        )
        if not has_wh_modifier:
            continue

        candidates = [
            ti for ti in inverse[previous.i] if 0 < ti < i
        ]
        if not candidates:
            continue

        target = candidates[-1]
        strength = 0.985 if previous.pos_ == "ADJ" else 0.970
        attention[i] *= 1.0 - strength
        attention[i, target] += strength

    return "bos_sink_with_fronted_phrase", make_row_stochastic(attention)


def prog_L18H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective subject–predicate bursts at auxiliaries.
    Preserve the default leakage except around nominal-subject and raising constructions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_bursts", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[0]].pos_ if aligned else None
        sink_mass = 0.93

        if pos == "PUNCT":
            sink_mass = 0.95
        elif pos in ("DET", "ADP"):
            sink_mass = 0.95

        if i == 1:
            sink_mass = 0.92 if pos == "DET" else 0.97

        # Original default distribution, unchanged.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * np.exp(-distances / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Only these constructions receive additional mass, taken directly from BOS.
    word_tokens = [[] for _ in doc]
    for ti, aligned in enumerate(alignment):
        if ti > 0:
            for wi in aligned:
                word_tokens[wi].append(ti)

    for predicate in doc:
        modal = predicate.pos_ == "AUX" and predicate.tag_ == "MD"
        auxiliary = predicate.pos_ == "AUX"
        raising = (
            predicate.pos_ == "VERB"
            and any(c.dep_ == "xcomp" and c.pos_ in ("AUX", "ADJ")
                    for c in predicate.children)
        )
        if not (auxiliary or raising) or not word_tokens[predicate.i]:
            continue

        governor = (
            predicate.head
            if predicate.dep_ in ("aux", "auxpass", "cop")
            else predicate
        )
        subjects = [
            c for c in governor.children
            if c.dep_ in ("nsubj", "nsubjpass")
            and c.i < predicate.i
            and word_tokens[c.i]
        ]
        if not subjects:
            continue
        subject = subjects[-1]
        if auxiliary and subject.pos_ not in ("NOUN", "PROPN"):
            continue
        if raising and subject.pos_ != "PRON":
            continue

        pi = word_tokens[predicate.i][0]
        si = word_tokens[subject.i][-1]
        if si >= pi:
            continue

        if modal:
            mass, subject_share = 0.52, 0.75
        elif raising:
            mass, subject_share = 0.68, 0.72
        elif subject.pos_ == "PROPN":
            mass, subject_share = 0.50, 0.32
        elif subject.tag_ in ("NNS", "NNPS"):
            mass, subject_share = 0.83, 0.68
        else:
            mass, subject_share = 0.69, 0.60

        mass = min(mass, attention[pi, 0])
        attention[pi, 0] -= mass
        attention[pi, si] += mass * subject_share
        attention[pi, pi] += mass * (1.0 - subject_share)

        # Brief spillover, not a sentence-wide reduction of the sink.
        for offset in (1, 2):
            wi = predicate.i + offset
            if wi >= len(doc) or not word_tokens[wi]:
                break
            following = doc[wi]
            qi = word_tokens[wi][0]
            if modal and offset == 1 and following.i == governor.i:
                extra = 0.43
                targets = ((si, 0.34), (pi, 0.43), (qi, 0.23))
            elif not modal and not raising and following.pos_ in ("ADV", "DET"):
                extra = 0.72 if offset == 1 else 0.58
                previous = word_tokens[wi - 1][-1]
                targets = (
                    ((si, 0.34), (pi, 0.28), (qi, 0.38))
                    if offset == 1
                    else ((si, 0.23), (pi, 0.34), (previous, 0.43))
                )
            else:
                break

            extra = min(extra, attention[qi, 0])
            attention[qi, 0] -= extra
            for key, share in targets:
                attention[qi, key] += extra * share

    return "bos_sink_with_subject_bursts", attention


def prog_L18H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective backward syntactic attention.
    Prepositional objects and their determiners can inherit the outer PP governor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pp_inheritance", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        piece = tokens[i]
        clean = piece.replace("▁", "").replace("Ġ", "").strip()
        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None
        target = None
        sink = 0.83

        if word is not None:
            pos = word.pos_
            dep = word.dep_
            if pos in ("DET", "ADJ", "AUX"):
                sink = 0.88
            elif pos in ("PRON", "CCONJ", "SCONJ", "PART"):
                sink = 0.83
            elif pos == "ADV":
                sink = 0.82
            elif pos == "PROPN":
                sink = 0.87
            elif pos == "VERB":
                sink = 0.75
            elif pos == "NOUN":
                sink = 0.65
            elif pos == "ADP":
                sink = 0.55
            elif pos == "PUNCT":
                sink = 0.71

            governors = [
                j for j in inverse[word.head.i]
                if 0 < j < i and word.head.i != word.i
            ]
            if governors:
                if dep in ("dobj", "obj", "iobj", "attr", "oprd"):
                    target = governors[-1]
                    sink = 0.36 if word.head.pos_ == "VERB" else 0.55
                elif pos == "ADP" and dep in ("prep", "agent"):
                    target = governors[-1]
                    sink = 0.48
                elif dep in ("pobj", "obl"):
                    target = governors[-1]
                    sink = 0.51

            # Incomplete lexical items largely leave the sink undisturbed.
            pieces = inverse[word.i]
            if pieces and i < pieces[-1]:
                sink = max(sink, 0.96)
                target = None
            elif len(pieces) > 1 and pos != "PUNCT":
                sink = max(sink, 0.74)

            if word.ent_type_:
                sink = max(sink, 0.84)

        if not clean or piece in tokenizer.all_special_tokens:
            sink = 0.91
            target = None
        elif all(c in ".,!?;:\"'“”‘’—–-()[]{}…" for c in clean):
            if "." in clean:
                sink = 0.93
            elif "'" in clean or "’" in clean:
                sink = 0.94
            elif '"' in clean or "“" in clean or "”" in clean:
                sink = 0.88
            else:
                sink = 0.72
            target = None

        if i == 1:
            sink = 0.96
            target = None

        # Spread the nonsink residue locally, emphasizing a licensed governor.
        weights = np.exp((np.arange(1, i + 1) - i) / 3.0)
        weights /= weights.sum()
        if target is not None:
            weights *= 0.18
            weights[target - 1] += 0.82

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights

        # Narrow exception: inherit a nearby outer PP's nonnominal governor.
        # Transfer only BOS / licensed-preposition mass; preserve self and decay.
        if (
            i > 1
            and word is not None
            and clean
            and piece not in tokenizer.all_special_tokens
            and inverse[word.i]
            and i == inverse[word.i][-1]
            and not word.ent_type_
            and (
                word.pos_ == "NOUN"
                or (word.pos_ == "DET" and word.dep_ == "det")
            )
        ):
            nominal = word.head if word.pos_ == "DET" else word
            if nominal.dep_ == "pobj" and nominal.head.pos_ == "ADP":
                inner_prep = nominal.head
                outer_prep = inner_prep
                visited = {outer_prep.i}
                while (
                    outer_prep.head.pos_ == "NOUN"
                    and outer_prep.head.dep_ == "pobj"
                    and outer_prep.head.head.pos_ == "ADP"
                    and outer_prep.head.head.i not in visited
                ):
                    outer_prep = outer_prep.head.head
                    visited.add(outer_prep.i)

                governor = outer_prep.head
                gs = [j for j in inverse[governor.i] if 0 < j < i]
                ps = [j for j in inverse[outer_prep.i] if 0 < j < i]
                if (
                    governor.pos_ in ("VERB", "ADJ", "ADV")
                    and gs
                    and ps
                    and gs[-1] < ps[-1]
                    and i - gs[-1] <= 8
                ):
                    g, p = gs[-1], ps[-1]
                    nested = outer_prep.i != inner_prep.i
                    governor_share = 0.45 if nested else 0.70
                    if word.pos_ == "DET":
                        amount = min(
                            max(0.0, attention[i, 0] - 0.24),
                            0.52 if governor.pos_ in ("ADJ", "ADV") else 0.45,
                        )
                    else:
                        amount = max(0.0, attention[i, 0] - 0.15)

                    attention[i, 0] -= amount
                    attention[i, g] += governor_share * amount
                    attention[i, p] += (1.0 - governor_share) * amount

                    if word.pos_ == "NOUN":
                        sources = [
                            j for j in inverse[inner_prep.i] if 0 < j < i
                        ]
                        if sources:
                            source = sources[-1]
                            moved = attention[i, source] * (0.90 if nested else 0.55)
                            attention[i, source] -= moved
                            attention[i, g] += governor_share * moved
                            attention[i, p] += (1.0 - governor_share) * moved

    return "bos_sink_with_pp_inheritance", make_row_stochastic(attention)


def prog_L18H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal recency attention.
    Punctuation and clause boundaries divert more mass away from the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        surface = tokens[i].lstrip("▁Ġ")
        is_punctuation = (
            word.is_punct if word is not None
            else bool(surface) and all(
                not c.isalnum() and not c.isspace() for c in surface
            )
        )

        sink_mass = 0.945 - 0.0015 * min(i, 70)
        if is_punctuation:
            sink_mass -= 0.19
        elif not surface:
            sink_mass -= 0.16
        elif word is not None:
            if word.pos_ in ("CCONJ", "SCONJ"):
                sink_mass -= 0.10
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.015
            if word.dep_ in ("cc", "mark"):
                sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.55, 0.975))

        # The small non-sink component favors nearby preceding tokens,
        # with a diffuse causal tail rather than a strong syntactic target.
        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = (
            0.75 * np.exp(-distances / 2.5)
            + 0.25 * np.exp(-distances / 16.0)
        )
        residual[-1] *= 0.45
        if is_punctuation and i > 1:
            residual[-2] *= 1.8

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L18H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective local phrase retrieval.
    Wh-complements and modified nouns divert sink mass to preceding phrase tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_phrase", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_strength = {
        "NOUN": 0.69,
        "PROPN": 0.80,
        "PRON": 0.77,
        "DET": 0.78,
        "ADJ": 0.73,
        "ADV": 0.81,
        "VERB": 0.82,
        "AUX": 0.82,
        "ADP": 0.69,
        "PART": 0.75,
        "CCONJ": 0.90,
        "SCONJ": 0.78,
        "NUM": 0.74,
        "INTJ": 0.85,
        "PUNCT": 0.93,
        "SPACE": 0.96,
    }

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ")
        stripped = text.strip()
        mapped = alignment[i]

        sink = 0.79
        if mapped:
            word = doc[mapped[0]]
            sink = pos_strength.get(word.pos_, 0.79)

            if word.dep_ == "poss":
                sink -= 0.13
            elif word.dep_ in ("dobj", "obj", "pobj"):
                sink -= 0.04

            if word.is_sent_start:
                sink = max(sink, 0.87)

            if word.is_punct:
                sink = 0.91
                if any(c in ".!?" for c in word.text):
                    sink = 0.96
                elif any(c in "\"“”«»" for c in word.text):
                    sink = 0.96

            # Short leading fragments often act as particularly strong sink queries.
            if (
                word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB")
                and len(stripped) <= 2
                and len(word.text) > len(stripped) + 1
                and i == min(
                    j for j in range(1, i + 1)
                    if mapped[0] in alignment[j]
                )
            ):
                sink = max(sink, 0.92)

        if not stripped:
            sink = 0.96
        elif all(not c.isalnum() for c in stripped):
            sink = max(sink, 0.91)
            if any(c in ".!?\"“”" for c in stripped):
                sink = max(sink, 0.96)

        if i == 1:
            sink = max(sink, 0.88)

        sink = float(np.clip(sink, 0.50, 0.98))
        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        # Transfer only BOS mass: self-attention and the original decay stay intact.
        if mapped and stripped and not word.is_punct:
            targets = {}
            transfer = 0.0
            start = max(0, word.i - 5)
            wh = [
                w for w in doc[start:word.i + 1]
                if w.tag_ in ("WDT", "WP", "WRB")
                and w.pos_ in ("DET", "PRON", "ADV")
            ]
            if wh and not any(w.is_punct for w in doc[wh[-1].i:word.i]):
                marker = wh[-1]
                prefix = list(doc[marker.i:word.i])
                anchors = [w for w in prefix if w.pos_ in ("NOUN", "ADJ")]

                if word.i == marker.i and word.i > 0:
                    targets[word.i - 1] = 1.0
                    transfer = 0.14
                elif anchors and word.pos_ in ("PRON", "AUX"):
                    targets[anchors[-1].i] = 4.0
                    targets[word.i - 1] = targets.get(word.i - 1, 0.0) + 1.0
                    transfer = 0.46 if word.pos_ == "PRON" else 0.55
                elif word.pos_ in ("NOUN", "ADJ", "ADV", "PRON", "VERB"):
                    for w in prefix:
                        targets[w.i] = 1.0
                    transfer = 0.24 if word.pos_ != "ADV" else 0.16

            if not targets and word.pos_ == "NOUN":
                modifiers = [
                    c for c in word.children
                    if c.dep_ == "amod" and c.i < word.i
                ]
                if modifiers:
                    for c in word.children:
                        if c.i < word.i and c.dep_ in ("amod", "det"):
                            targets[c.i] = 2.0 if c.dep_ == "amod" else 1.0
                    transfer = 0.20

            if targets:
                local = np.zeros(i, dtype=np.float64)
                for j in range(1, i):
                    if alignment[j]:
                        local[j] = sum(
                            targets.get(k, 0.0) for k in alignment[j]
                        )
                if local.sum() > 0.0:
                    transfer = min(transfer, attention[i, 0] - 0.12)
                    if transfer > 0.0:
                        attention[i, 0] -= transfer
                        attention[i, :i] += transfer * local / local.sum()

    return "bos_sink_with_local_phrase", attention


def prog_L18H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with mild grammatical modulation.
    Residual attention is diffuse and recency-biased rather than syntactically targeted.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_grammatical_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.70 + 0.27 * np.exp(-(i - 1) / 8.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_
            dep = word.dep_

            if pos == "DET" or dep == "poss":
                sink += 0.10
            elif pos in ("NOUN", "PROPN"):
                sink += 0.025
            elif pos in ("VERB", "AUX"):
                sink -= 0.055
            elif pos in ("CCONJ", "SCONJ"):
                sink -= 0.09
            elif pos == "PUNCT":
                sink -= 0.11

            if dep in ("amod", "advmod"):
                sink += 0.025

        sink = float(np.clip(sink, 0.40, 0.985))

        # Keep the remaining mass causal, broad, and modestly local.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-distances / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "bos_sink_with_grammatical_modulation", attention


def prog_L18H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for nominal onsets and grammatical anchors.
    Residual attention is weak, causal, and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_linguistic_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_strength = {
        "DET": 0.95,
        "PRON": 0.90,
        "PROPN": 0.91,
        "NOUN": 0.77,
        "ADJ": 0.85,
        "NUM": 0.86,
        "AUX": 0.73,
        "VERB": 0.59,
        "ADV": 0.72,
        "ADP": 0.71,
        "PART": 0.69,
        "CCONJ": 0.60,
        "SCONJ": 0.67,
        "INTJ": 0.86,
        "PUNCT": 0.69,
        "SPACE": 0.73,
        "X": 0.80,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        strength = 0.74
        sids = alignment[i]
        if sids:
            word = doc[sids[0]]
            strength = pos_strength.get(word.pos_, 0.74)

            if word.dep_ in ("nsubj", "nsubjpass", "poss"):
                strength += 0.04
            elif word.dep_ in ("ROOT", "conj", "xcomp", "ccomp"):
                strength -= 0.03

            # Fragmented lexical items often retain especially strong BOS mass.
            previous_overlap = (
                i > 1 and sids[0] in alignment[i - 1]
            )
            next_overlap = (
                i + 1 < n and sids[0] in alignment[i + 1]
            )
            if word.pos_ not in ("VERB", "AUX", "PUNCT"):
                if next_overlap:
                    strength += 0.12
                elif previous_overlap:
                    strength += 0.07

            if word.is_punct:
                if word.text in ("'", "’", '"', "“", "”", "‘"):
                    strength = 0.92
                elif word.text in (",", ";", ":"):
                    strength = 0.81
                elif word.text in (".", "!", "?"):
                    strength = 0.54

        if i == 1:
            strength = 0.974
        strength = float(np.clip(strength, 0.40, 0.985))

        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = strength
        attention[i, 1:i + 1] = (1.0 - strength) * residual

    return "bos_sink_linguistic_gating", attention


def prog_L18H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, enhanced by early positions and fragmented lexical tokens.
    Residual attention favors nearby tokens and recent local syntactic anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    words = [doc[indices[0]] if indices else None for indices in alignment]
    clean = [t.lstrip("▁Ġ") for t in tokens]
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        piece = clean[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Most rows retain a sink component even well into the sequence.
        logit = -1.30 + 3.0 * np.exp(-(i - 1) / 3.5)
        if pos in ("NOUN", "PROPN"):
            logit += 0.65
            if word.tag_ in ("NN", "NNP"):
                logit += 0.30
        elif pos == "ADJ":
            logit += 0.42
        elif pos in ("VERB", "AUX"):
            logit += 0.10
        elif pos in ("DET", "ADP", "ADV"):
            logit += 0.08

        if word is not None:
            pieces = [j for j in inverse[word.i] if j > 0]
            if len(pieces) > 1 and pos not in ("PUNCT", "SPACE"):
                if i == pieces[0]:
                    logit += 2.25 if len(piece) <= 4 else 1.25
                elif i != pieces[-1] and len(piece) <= 3:
                    logit += 2.65
                else:
                    logit += 0.12

            if word.ent_type_ and pos == "PROPN":
                logit += 0.35

        if piece in ("'", "’"):
            logit = 0.15 if dep == "case" else 2.65
        elif not piece.strip():
            logit = 1.40
        elif piece and all(not c.isalnum() for c in piece):
            logit += 0.65
        elif piece and any(ord(c) > 127 for c in piece):
            logit += 1.60

        sink = float(1.0 / (1.0 + np.exp(-logit)))
        if i == 1:
            sink = 0.95

        # Spread non-sink mass locally rather than assigning it to one edge.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 1.65

        for j in range(max(1, i - 14), i + 1):
            key = words[j]
            if key is not None:
                if key.pos_ in ("AUX", "ADJ"):
                    residual[j - 1] *= 1.45
                if word is not None and key.i == word.head.i:
                    residual[j - 1] *= 1.35

            if clean[j] in ('"', "“", "‘"):
                residual[j - 1] += 1.8 * np.exp(-(i - j) / 9.0)

            # A completed split word can briefly serve as a local anchor.
            if key is not None:
                pieces = inverse[key.i]
                if len(pieces) > 1 and j == pieces[-1]:
                    residual[j - 1] *= 1.45

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_residual", attention


def prog_L18H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild POS-dependent strength.
    Residual attention is diffuse and biased toward recent causal positions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        linked = alignment[i]
        word = doc[linked[0]] if linked else None
        strength = 0.86

        if word is not None:
            if word.pos_ == "PRON":
                strength = 0.94
            elif word.pos_ in ("NOUN", "PROPN"):
                strength = 0.91
            elif word.pos_ == "ADJ":
                strength = 0.89
            elif word.pos_ == "VERB":
                strength = 0.87
            elif word.pos_ in ("DET", "ADP", "AUX", "PART"):
                strength = 0.79
            elif word.pos_ in ("CCONJ", "SCONJ", "ADV"):
                strength = 0.82
            elif word.is_punct or word.is_space:
                strength = 0.73

        strength -= 0.035 * np.log1p(i / 16.0)
        if i == 1:
            strength = 0.89 if word is not None and word.pos_ == "DET" else 0.97

        strength = np.clip(strength, 0.55, 0.98)
        positions = np.arange(1, i + 1)
        residual = 0.5 + np.exp(-(i - positions) / 6.0)
        attention[i, 1:i + 1] = (1.0 - strength) * residual / residual.sum()
        attention[i, 0] = strength

    return "bos_sink_pos_modulated", attention


def prog_L18H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak causal background and punctuation competition.
    Longer contexts accumulate more non-sink attention, especially at boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    key_weights = np.full(n, 0.10, dtype=np.float64)
    sink_strength = np.full(n, 55.0, dtype=np.float64)

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        surface = tokens[i].lstrip("▁Ġ")

        is_punctuation = (
            bool(surface) and all(not c.isalnum() for c in surface)
        ) or any(w.pos_ == "PUNCT" for w in aligned)
        is_quote = any(c in "\"'“”‘’«»" for c in surface)

        if is_punctuation:
            key_weights[i] = 0.95
            sink_strength[i] *= 0.72
        if is_quote:
            key_weights[i] = 2.0

        if any(w.dep_ in ("ROOT", "conj", "advcl", "ccomp") for w in aligned):
            sink_strength[i] *= 0.90

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        attention[i, 1:i + 1] = (
            key_weights[1:i + 1]
            + 0.25 * np.exp(-(i - positions) / 5.0)
        )
        attention[i, 0] = sink_strength[i]

    return (
        "bos_sink_with_boundary_competition",
        make_row_stochastic(attention),
    )


def prog_L18H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink, with secondary boundary sinks in quoted dialogue.
    Malformed quotation marks can become unusually strong local sinks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        background = np.exp(-(i - positions) / 8.0)
        background /= background.sum()

        attention[i, 0] = 0.96
        attention[i, 1:i + 1] = 0.04 * background

    # Only dialogue activates the exception; ordinary prose is unchanged.
    quotes = [
        i for i, t in enumerate(tokens)
        if any(c in t for c in ('"', '“', '”'))
    ]
    # The euro sign is a characteristic fragment of mojibake curly quotes.
    damaged_quotes = [i for i, t in enumerate(tokens) if "€" in t]

    if quotes or damaged_quotes:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        first_pos = (
            doc[alignment[1][0]].pos_
            if n > 1 and alignment[1] else ""
        )

        for i in range(2, n):
            text = tokens[i].lstrip("▁Ġ")
            pos = doc[alignment[i][0]].pos_ if alignment[i] else ""
            boundary = (
                pos == "PUNCT"
                or not text.strip()
                or any(c in text for c in (".", ",", "!", "?", ";", ":"))
            )
            salient = pos in ("NOUN", "PROPN", "ADJ", "VERB")
            mass = 0.14 if boundary else (0.055 if salient else 0.015)

            weights = np.zeros(i, dtype=np.float64)
            weights[1] = 2.5 if first_pos == "DET" else 0.6

            for j in quotes:
                if 0 < j < i:
                    weights[j] += 1.0
            for j in range(1, i):
                if not tokens[j].lstrip("▁Ġ").strip():
                    weights[j] += 1.2

            if damaged_quotes:
                anchor = damaged_quotes[0]
                if anchor <= i:
                    # Inside the malformed quotation, its fragments compete
                    # strongly with BOS; after closure the effect is weaker.
                    inside = (
                        len(damaged_quotes) == 1
                        or i <= damaged_quotes[1]
                    )
                    mass = (
                        0.72 if boundary or pos in ("AUX", "PART")
                        else 0.50 if pos == "ADJ"
                        else 0.22
                    ) if inside else (0.40 if boundary else 0.16)
                    weights *= 0.2
                    if anchor < i:
                        weights[anchor] += 3.0
                    if anchor > 1:
                        weights[anchor - 1] += 1.2

            if weights.sum() > 0:
                # Transfer only BOS mass to strictly earlier positions:
                # self-attention and the original recency background survive.
                transfer = min(mass, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, :i] += transfer * weights / weights.sum()

    return "bos_with_dialogue_boundary_sinks", attention


def prog_L18H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start, with weak linguistic modulation.
    Residual attention is diffuse and mildly favors recent tokens and punctuation anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    anchors = []

    for i in range(1, n):
        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        sink = 0.61 + 0.34 * np.exp(-(i - 1) / 8.0)
        if word is not None:
            if word.pos_ in ("DET", "AUX", "CCONJ", "SCONJ"):
                sink += 0.045
            elif word.pos_ == "PRON":
                sink += 0.025
            elif word.pos_ == "VERB":
                sink -= 0.055
            elif word.pos_ in ("NOUN", "ADJ", "ADV"):
                sink -= 0.025
            if word.dep_ == "poss":
                sink += 0.045

        if clean in ("'", "’"):
            sink += 0.20
        elif not clean:
            sink += 0.12

        if i == 1:
            sink = 0.965
        sink = np.clip(sink, 0.40, 0.985)

        positions = np.arange(1, i + 1)
        residual = np.ones(i, dtype=np.float64)
        residual += 0.8 * np.exp(-(i - positions) / 4.0)

        # Apostrophes and unusual punctuation can become secondary sinks.
        for j in anchors:
            residual[j - 1] += 0.65 * i / (1.0 + 0.015 * (i - j))

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        if clean in ("'", "’", "€"):
            anchors.append(i)

    return "bos_sink_with_weak_anchors", attention


def prog_L18H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, diffuse causal attention and a recency bias.
    Competing non-BOS keys gradually reduce sink dominance as context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        distances = i - positions

        attention[i, 0] = 1.0
        attention[i, 1:i + 1] = (
            0.0015 + 0.003 * np.exp(-distances / 4.0)
        )

    return "bos_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L18H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with mild positional decay and linguistic modulation.
    Residual attention is diffuse and recency-biased rather than strongly syntactic.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[0]].pos_ if aligned else ""

        sink_mass = 0.975 - 0.105 * (1.0 - np.exp(-i / 35.0))
        if pos in ("PRON", "DET"):
            sink_mass += 0.018
        elif pos in ("AUX", "ADJ", "PROPN"):
            sink_mass += 0.008
        elif pos in ("VERB", "ADP", "CCONJ", "SCONJ"):
            sink_mass -= 0.020
        elif pos == "PUNCT":
            sink_mass -= 0.085
        elif not aligned:
            sink_mass -= 0.020

        sink_mass = np.clip(sink_mass, 0.72, 0.99)
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L18H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing non-BOS leakage.
    Linguistic features modestly modulate a predominantly positional pattern.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        feature_scale = 1.0
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("DET", "AUX"):
                feature_scale = 0.65
            elif word.pos_ in ("ADP", "PRON"):
                feature_scale = 0.85
            elif word.pos_ in ("NOUN", "PROPN"):
                feature_scale = 1.25
            elif word.pos_ in ("VERB", "ADJ"):
                feature_scale = 0.95
            elif word.pos_ == "PUNCT":
                feature_scale = 1.15
                if word.is_sent_end:
                    feature_scale = 2.5

        if tokens[i].isspace() or tokens[i] == "▁":
            feature_scale *= 1.7

        leakage_odds = 0.0015 * (i ** 1.35) * feature_scale
        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        # The observed edges constrain the sink much more strongly than
        # the residual distribution; use a diffuse causal recency prior.
        residual = 0.5 + np.exp(-(i - positions) / 12.0)
        residual[-1] += 0.25
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L18H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with sparse retrieval of objects after related predicates.
    Most tokens default to BOS; repeated verbal contexts can reactivate earlier objects.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_object_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        if ti == 0:
            continue
        for wi in word_ids:
            word_tokens[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None
        pos = word.pos_ if word is not None else ""

        sink = 0.88
        if pos in ("VERB", "AUX", "ADP"):
            sink = 0.92
        elif pos in ("NOUN", "PROPN"):
            sink = 0.86
        elif pos in ("PUNCT", "DET", "ADJ"):
            sink = 0.79

        if i == 1:
            sink = 0.97 if pos in ("PRON", "PROPN", "ADV") else sink
            if pos == "DET":
                sink = 0.62

        sink -= min(0.12, max(0, i - 16) * 0.0025)
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.25 + np.exp(-(i - positions) / 7.0)
        attention[i, 1:i + 1] = (1.0 - sink) * background / background.sum()
        attention[i, 0] = sink

        if word is None or pos != "VERB":
            continue

        best_score = 0.0
        best_target = None
        for earlier in doc[:word.i]:
            if earlier.pos_ != "VERB" or not word_tokens[earlier.i]:
                continue
            source = word_tokens[earlier.i][0]
            if source >= i:
                continue

            objects = [
                child for child in earlier.children
                if child.dep_ in ("dobj", "obj", "attr", "oprd")
                and child.pos_ in ("NOUN", "PROPN", "PRON")
            ]
            for obj in objects:
                candidates = [j for j in word_tokens[obj.i] if source < j < i]
                if not candidates:
                    continue
                similarity = embedding_similarity(tokens, i, source, tokenizer)
                score = (similarity - 0.58) / 0.32
                if score > best_score:
                    best_score = score
                    best_target = candidates[0]

        if best_target is not None:
            strength = min(0.90, 0.90 * best_score)
            attention[i] *= 1.0 - strength
            attention[i, best_target] += strength

    return (
        "bos_sink_with_predicate_object_retrieval",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L18H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with selective object-to-governing-verb attention.
    Completed object words and coordinated objects strengthen the syntactic route.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_object_to_verb", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Most queries use BOS as a sink, with a small local residual.
        residual = np.exp(-0.65 * (i - np.arange(1, i + 1)))
        residual /= residual.sum()
        attention[i, 1:i + 1] = 0.16 * residual
        attention[i, 0] = 0.84

        if not alignment[i]:
            continue

        word = doc[alignment[i][-1]]
        pieces = [p for p in inverse[word.i] if p > 0]
        completed = bool(pieces) and i == pieces[-1]

        if word.pos_ in ("PRON", "PROPN"):
            sink = 0.90
        elif word.pos_ in ("ADJ", "AUX", "PUNCT"):
            sink = 0.86
        else:
            sink = 0.82

        if i <= 2:
            sink = max(sink, 0.94)
        if pieces and len(pieces) > 1 and not completed:
            sink = max(sink, 0.93)

        attention[i, :] = 0.0
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        if word.pos_ not in ("NOUN", "PROPN", "PRON") or not completed:
            continue

        # Follow conjunctions to the original object's governing relation.
        anchor = word
        steps = 0
        while anchor.dep_ == "conj" and anchor.head.i != anchor.i and steps < 6:
            anchor = anchor.head
            steps += 1

        governor = None
        strength = 0.0
        if anchor.dep_ in ("dobj", "obj", "iobj", "dative"):
            if anchor.head.pos_ == "VERB":
                governor = anchor.head
                strength = 0.64
        elif anchor.dep_ == "pobj":
            prep = anchor.head
            if prep.head.pos_ == "VERB":
                governor = prep.head
                strength = 0.30

        if governor is None:
            continue

        targets = [p for p in inverse[governor.i] if 0 < p <= i]
        if not targets:
            continue

        target = targets[0]
        distance = i - targets[-1]
        strength *= np.exp(-0.012 * max(0, distance - 4))
        if word.pos_ == "PRON":
            strength *= 0.92
        if word.dep_ == "conj":
            strength *= 0.92

        attention[i] *= 1.0 - strength
        attention[i, target] += strength

    return "bos_sink_with_object_to_verb", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L18H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker, predominantly local contextual attention.
    Punctuation and clause boundaries strengthen the sink; phrase interiors weaken it.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        text = raw.replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        previous_indices = alignment[i - 1]
        previous_word = doc[previous_indices[-1]] if previous_indices else None

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = {
            "VERB": 0.72,
            "AUX": 0.72,
            "NOUN": 0.51,
            "PROPN": 0.66,
            "PRON": 0.56,
            "DET": 0.47,
            "ADJ": 0.60,
            "ADV": 0.65,
            "ADP": 0.57,
            "PART": 0.57,
            "CCONJ": 0.62,
            "SCONJ": 0.73,
            "NUM": 0.49,
            "INTJ": 0.82,
            "PUNCT": 0.83,
            "SPACE": 0.90,
        }.get(pos, 0.65)

        if word is not None:
            if dep in ("ROOT", "conj", "advcl", "ccomp"):
                sink += 0.05
            if dep in ("pobj", "dobj", "obj", "amod", "compound"):
                sink -= 0.04

        # The earliest lexical token has almost no competing context.
        if i == 1:
            sink = 0.83 if pos == "DET" else 0.96

        if not text:
            sink = 0.91
        elif all(not c.isalnum() for c in text):
            sink = 0.81 if "," in text else 0.90
            if "'" in text or "’" in text:
                sink = 0.95

        if raw in special_tokens:
            sink = 0.97

        local_gate = False
        if i > 2 and word is not None and previous_word is not None:
            # Some phrase-internal queries strongly select their immediate context.
            local_gate = (
                pos == "PRON"
                and previous_word.pos_ in ("ADP", "ADV", "NOUN", "AUX")
            ) or (
                pos == "DET" and previous_word.pos_ == "ADP"
            )
            if local_gate:
                sink = 0.29

        sink = float(np.clip(sink, 0.18, 0.98))
        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
            continue

        weights = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        weights[1:] = 0.22 * np.exp(-(i - positions) / 2.2)
        weights[i - 1] += 0.56
        weights[i] += 0.16

        if local_gate:
            weights[i - 1] += 1.8

        # Add a small backward syntactic correction without overriding the sink.
        if word is not None and word.head.i != word.i:
            for j in range(max(1, i - 8), i):
                if word.head.i in alignment[j]:
                    weights[j] += 0.16
                    break

        # Later subword pieces retain some attention to the preceding piece.
        if indices and previous_indices and indices[0] == previous_indices[-1]:
            weights[i - 1] += 0.20

        attention[i, 0] = sink
        attention[i, 1:] = (1.0 - sink) * weights[1:] / weights[1:].sum()

    return "bos_sink_with_local_context", attention


def prog_L18H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild positional weakening and a small
    recency- and content-sensitive causal background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_content_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    salience = np.ones(n, dtype=np.float64)
    punctuation = np.zeros(n, dtype=bool)
    content = np.zeros(n, dtype=bool)

    for i, indices in enumerate(alignment):
        if not indices:
            continue
        words = [doc[k] for k in indices]
        punctuation[i] = all(w.is_punct for w in words)
        content[i] = any(
            w.pos_ in ("NOUN", "PROPN", "VERB", "ADJ") for w in words
        )
        if any(w.pos_ in ("NOUN", "PROPN") for w in words):
            salience[i] = 2.0
        elif content[i]:
            salience[i] = 1.35
        if punctuation[i]:
            salience[i] = 0.45

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.965 - 0.16 * i / (i + 18.0)
        if content[i]:
            sink += 0.025
        if punctuation[i]:
            sink -= 0.08
        if not alignment[i]:
            sink += 0.015
        sink = float(np.clip(sink, 0.70, 0.99))

        positions = np.arange(1, i + 1)
        distance = i - positions
        background = salience[1:i + 1] * (
            0.35 / i + 0.65 * np.exp(-distance / 5.0)
        )
        background /= background.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * background

    return "bos_sink_with_content_background", attention


def prog_L18H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink, with weaker local and
    syntactic attention when the sink is less dominant."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_context", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            if 0 <= si < len(doc):
                inverse[si].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[0]] if indices else None
        piece = tokens[i].lstrip("▁Ġ")
        punctuation = bool(piece) and all(
            not c.isalnum() and not c.isspace() for c in piece
        )

        # Strong positional sink; grammatical features only modulate its strength.
        sink = 0.87 - 0.07 * (1.0 - np.exp(-i / 24.0))
        if word is not None:
            if word.pos_ in ("VERB", "ADJ", "PROPN"):
                sink += 0.045
            elif word.pos_ in ("NOUN", "PRON", "AUX"):
                sink -= 0.065
            elif word.pos_ in ("DET", "ADP"):
                sink += 0.015

        if not piece:
            sink = max(sink, 0.93)
        elif punctuation:
            sink = max(sink, 0.85)
            if "'" in piece or "’" in piece:
                sink = max(sink, 0.95)

        if i == 1:
            sink = 0.98
        sink = float(np.clip(sink, 0.60, 0.98))

        # A small causal residual rather than a second dominant linguistic rule.
        positions = np.arange(1, i + 1)
        residual = 0.15 + np.exp(-(i - positions) / 5.0)
        residual[-1] += 0.5

        if word is not None:
            head_indices = inverse[word.head.i]
            eligible = [j for j in head_indices if 0 < j <= i]
            if eligible:
                residual[eligible[-1] - 1] += 0.75

            # Preserve subword cohesion without lexical identity tests.
            previous_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if previous_pieces:
                residual[previous_pieces[-1] - 1] += 0.6

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_weak_context", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L18H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clause-linking exception: coordinators and discourse
    adverbs retrieve the preceding predicate and its local complements.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Inverse alignment, used only by the clause-linking exception.
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        if ti > 0:
            for wi in word_ids:
                word_tokens[wi].append(ti)

    pos_adjustment = {
        "NOUN": 0.045,
        "PROPN": 0.065,
        "VERB": 0.045,
        "AUX": 0.025,
        "ADJ": 0.055,
        "PRON": 0.015,
        "DET": -0.045,
        "ADP": -0.015,
        "ADV": -0.045,
        "CCONJ": -0.105,
        "SCONJ": -0.065,
        "PART": -0.045,
        "PUNCT": -0.085,
    }

    for i in range(1, n):
        sink_mass = 0.47 + 0.41 * np.exp(-(i - 1) / 24.0)
        word = doc[alignment[i][0]] if alignment[i] else None

        if word is not None:
            sink_mass += pos_adjustment.get(word.pos_, 0.0)
            if word.is_sent_start and i > 1:
                sink_mass += 0.035
            if i == 1 and word.pos_ == "DET":
                sink_mass -= 0.12
            elif i == 1 and word.pos_ == "PRON":
                sink_mass += 0.045

        if tokens[i].isspace() or tokens[i] == "▁":
            sink_mass += 0.035

        sink_mass = float(np.clip(sink_mass, 0.32, 0.97))
        attention[i, 0] = sink_mass

        residual = np.zeros(i, dtype=np.float64)
        residual[-1] = 0.62

        if i > 1:
            distances = i - np.arange(1, i)
            local = np.exp(-distances / 2.5)
            local /= local.sum()
            residual[:-1] += 0.28 * local
            residual += 0.10 / i
        else:
            residual[0] = 1.0

        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

        # Transfer only BOS mass; preserve the original self/local weights.
        if word is not None:
            coordinator = (
                word.pos_ == "CCONJ"
                and word.head.pos_ in ("VERB", "ADJ")
            )
            discourse_link = (
                word.pos_ in ("ADV", "SCONJ")
                and word.i > 0
                and doc[word.i - 1].text in (",", ";", ":")
            )
            if coordinator or discourse_link:
                predicates = []
                for wi in range(word.i - 1, max(-1, word.i - 8), -1):
                    candidate = doc[wi]
                    if candidate.text in (".", "!", "?"):
                        break
                    if candidate.pos_ in ("VERB", "ADJ"):
                        predicates.append(candidate)
                        break

                if predicates:
                    predicate = predicates[0]
                    targets = {predicate.i: 1.0}
                    if predicate.dep_ == "conj":
                        head = predicate.head
                        if (
                            head.pos_ in ("VERB", "ADJ")
                            and 0 < predicate.i - head.i <= 7
                        ):
                            targets[head.i] = 0.6

                    for child in predicate.children:
                        if predicate.i < child.i < word.i and (
                            child.pos_ == "ADP"
                            or child.dep_ in ("obj", "dobj", "attr", "oprd", "prt")
                        ):
                            targets[child.i] = 0.8

                    retrieval = np.zeros(i, dtype=np.float64)
                    for wi, weight in targets.items():
                        causal = [ti for ti in word_tokens[wi] if ti < i]
                        if causal:
                            retrieval[causal[-1]] += weight

                    total = retrieval.sum()
                    if total > 0:
                        transfer = min(
                            0.36 if discourse_link else 0.23,
                            max(0.0, attention[i, 0] - 0.20),
                        )
                        attention[i, 0] -= transfer
                        attention[i, :i] += transfer * retrieval / total

    return "bos_sink_with_clause_links", attention


def prog_L18H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a small causal background that grows with position.
    Most attention remains on the initial token, with weaker recency-biased leakage.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_causal_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        leakage = min(0.18, 0.008 + 0.00065 * i + 0.000015 * i * i)

        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        if not surface:
            leakage = min(0.28, leakage + 0.06)
        elif all(not char.isalnum() for char in surface):
            leakage = min(0.25, leakage + 0.025)

        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.5 + np.exp(-(i - positions) / 12.0)
        background /= background.sum()

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * background

    return "bos_sink_with_causal_leakage", attention


def prog_L18H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak lexical-category modulation.
    Residual attention is diffuse and mildly favors recent clause boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_weak_context", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    boundary = np.zeros(n, dtype=np.float64)

    for i, indices in enumerate(aligned):
        if any(doc[k].is_punct for k in indices):
            boundary[i] = 1.0

    attention[0, 0] = 1.0
    for i in range(1, n):
        words = [doc[k] for k in aligned[i]]
        word = max(words, key=lambda w: len(w.text)) if words else None

        sink = 0.83
        if word is not None:
            if word.pos_ in ("ADJ", "PROPN"):
                sink += 0.045
            elif word.pos_ in ("PRON", "AUX"):
                sink -= 0.045
            elif word.pos_ in ("VERB", "ADV"):
                sink -= 0.02
            elif word.pos_ == "PUNCT":
                sink += 0.035

        # Early queries are particularly strongly absorbed by the first token.
        sink += 0.08 * np.exp(-(i - 1) / 3.0)

        if tokens[i].strip() in ("'", "’"):
            sink = 0.973
        if tokens[i] in tokenizer.all_special_tokens:
            sink = max(sink, 0.95)
        if i == 1:
            sink = 0.97

        sink = float(np.clip(sink, 0.65, 0.985))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = (
            0.45
            + np.exp(-(i - positions) / 7.0)
            + 0.45 * boundary[1:i + 1]
        )
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_weak_context", attention


def prog_L19H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local residual attention; predicate complements additionally
    retrieve their preceding predicate frame using mass transferred only from BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_frame", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        sink_mass = 0.90

        if word is not None:
            if word.pos_ in ("AUX", "DET", "CCONJ", "PART"):
                sink_mass = 0.94
            elif word.pos_ in ("ADJ", "ADV", "PROPN"):
                sink_mass = 0.92
            elif word.pos_ in ("NOUN", "VERB", "PRON"):
                sink_mass = 0.86

            if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink_mass -= 0.06

            # Early pieces of split words retain the original sink behavior.
            if i + 1 < n and any(k in alignment[i + 1] for k in indices):
                sink_mass = max(sink_mass, 0.96)

        if i == 1:
            sink_mass = 0.98
        if tokens[i] in tokenizer.all_special_tokens:
            sink_mass = 0.98

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = np.exp(-(i - positions) / 4.0)
        residual[i] += 0.5

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_positions:
                residual[head_positions[-1]] += 1.5

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink_mass) * residual
        attention[i, 0] = sink_mass

        # Complement completion can release the sink into an earlier predicate
        # frame. Preserve every original non-BOS weight, including the diagonal.
        if (
            word is not None
            and i > 1
            and tokens[i] not in tokenizer.all_special_tokens
            and not (
                i + 1 < n
                and any(k in alignment[i + 1] for k in indices)
            )
        ):
            complement = word
            if complement.dep_ == "conj" and complement.pos_ == "ADJ":
                complement = complement.head

            eligible = (
                complement.dep_ in ("dobj", "obj", "pobj", "attr", "acomp", "oprd")
                or (
                    complement.dep_ == "xcomp"
                    and complement.pos_ in ("ADJ", "VERB")
                )
                or (
                    complement.dep_ in ("prt", "advmod")
                    and complement.pos_ in ("ADV", "PART")
                )
            )
            if eligible:
                frame = np.zeros(i + 1, dtype=np.float64)
                node = complement
                predicate = None
                for depth in range(4):
                    parent = node.head
                    if parent.i == node.i or parent.i >= word.i:
                        break
                    for j in inverse[parent.i]:
                        if 0 < j < i:
                            frame[j] += 1.0 if parent.pos_ == "ADP" else 2.5
                    if parent.pos_ in ("VERB", "AUX"):
                        predicate = parent
                        break
                    if parent.pos_ not in ("ADP", "NOUN", "PROPN", "ADJ"):
                        break
                    node = parent

                if predicate is not None:
                    for child in predicate.children:
                        if child.i < word.i and child.dep_ in (
                            "aux", "auxpass", "cop", "neg", "advmod",
                            "dobj", "obj", "acomp", "attr",
                        ):
                            for j in inverse[child.i]:
                                if 0 < j < i:
                                    frame[j] += 1.5

                    if frame.sum() > 0.0:
                        target_sink = 0.45
                        if word.pos_ == "ADJ":
                            target_sink = 0.30
                        elif word.pos_ == "PRON" or word.dep_ == "prt":
                            target_sink = 0.20
                        elif complement.dep_ == "pobj":
                            target_sink = 0.35
                        transfer = max(0.0, attention[i, 0] - target_sink)
                        attention[i, 0] -= transfer
                        attention[i, :i + 1] += transfer * frame / frame.sum()

    return "bos_sink_with_predicate_frame", make_row_stochastic(attention)


def prog_L19H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local residuals; completed verbal PP objects additionally
    retrieve their preposition and governing verb without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pp_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        punctuation = bool(surface) and all(
            not c.isalnum() and not c.isspace() for c in surface
        )

        sink = 0.91
        if word is not None:
            if word.pos_ in ("ADP", "DET", "PART"):
                sink = 0.94
            elif word.pos_ in ("VERB", "PROPN"):
                sink = 0.93
            elif word.pos_ in ("NOUN", "ADJ"):
                sink = 0.85
            elif word.pos_ in ("AUX", "ADV", "PRON", "CCONJ", "SCONJ"):
                sink = 0.87

            # Completed phrases are more likely to use local context.
            continues_word = (
                i + 1 < n
                and bool(set(aligned).intersection(alignment[i + 1]))
            )
            if not continues_word and word.dep_ in (
                "dobj", "obj", "pobj", "attr", "oprd"
            ):
                sink -= 0.10

        if punctuation:
            sink = 0.48
        elif not surface:
            sink = 0.58

        # The first few queries have particularly strong sink behavior.
        if not punctuation and surface:
            sink += 0.04 * np.exp(-(i - 1) / 5.0)
        sink = float(np.clip(sink, 0.25, 0.98))

        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
            continue

        # Allocate residual mass primarily to the immediate predecessor,
        # with a small, smoothly decaying causal neighborhood.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.0)
        local[-1] *= 0.25
        local[i - 2] += 3.0
        local /= local.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local

        # Only completed objects of verbal PPs trigger structural retrieval.
        # Transfer BOS mass, leaving the original self/local weights intact.
        if (
            word is not None
            and not punctuation
            and surface
            and not continues_word
            and word.dep_ == "pobj"
            and word.head.pos_ == "ADP"
            and word.head.head.pos_ in ("VERB", "AUX")
        ):
            prep_positions = [
                j for j in range(1, i) if word.head.i in alignment[j]
            ]
            verb_positions = [
                j for j in range(1, i) if word.head.head.i in alignment[j]
            ]
            if prep_positions and verb_positions:
                prep_j = prep_positions[-1]
                verb_j = verb_positions[-1]
                if verb_j < prep_j < i:
                    mass = min(0.36, max(0.0, sink - 0.25))
                    attention[i, 0] -= mass
                    attention[i, prep_j] += 0.65 * mass
                    attention[i, verb_j] += 0.35 * mass

    return "bos_sink_with_pp_retrieval", attention


def prog_L19H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a clause-spine exception for completed objects and complements.
    Redistribute only BOS mass toward preceding governors and clause scaffolding.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_spine", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    word_tokens = [[] for _ in doc]
    for ti, aligned_words in enumerate(alignment):
        for wi in aligned_words:
            word_tokens[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        sink = 0.82

        if word is not None:
            pos = word.pos_
            if pos in ("CCONJ", "SCONJ"):
                sink = 0.96
            elif pos in ("DET", "PRON", "AUX"):
                sink = 0.91
            elif pos in ("ADP", "PART"):
                sink = 0.85
            elif pos == "ADV":
                sink = 0.86
            elif pos in ("NOUN", "PROPN"):
                sink = 0.72
            elif pos == "VERB":
                sink = 0.77
            elif pos == "ADJ":
                sink = 0.69

            if word.dep_ in ("nsubj", "nsubjpass", "expl"):
                sink = max(sink, 0.89)

        if not text or tokens[i] in tokenizer.all_special_tokens:
            sink = 0.93
        elif all(c in ".!?" for c in text):
            sink = 0.93
        elif all(c in ".,;:!?\"'’“”()-" for c in text):
            sink = 0.82
            if text == ",":
                sink = 0.73
            elif text in ("'", "’"):
                sink = 0.95

        indices = np.arange(1, i + 1)
        distance = i - indices
        residual = np.exp(-distance / 2.5)
        residual[-1] *= 0.45

        for j in range(max(1, i - 6), i):
            prior = tokens[j].replace("▁", " ").replace("Ġ", " ").strip()
            if prior and all(c in ",;:!?." for c in prior):
                residual[j - 1] *= 2.5
                if j == i - 1 and word is not None:
                    if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                        sink = max(0.45, sink - 0.12)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Exception: completed complements retrieve the preceding clause spine.
        # Leave the original self-attention and all existing residual mass intact.
        if word is not None and word_tokens[word.i][-1] == i:
            nominal = (
                word.pos_ in ("NOUN", "PROPN")
                and word.dep_ in ("dobj", "obj", "pobj", "attr", "oprd")
            )
            complement = (
                word.pos_ in ("VERB", "ADJ", "ADV")
                and word.dep_ in ("xcomp", "acomp", "oprd", "prt", "advmod")
            )
            if nominal or complement:
                spine = []
                seen = {word.i}
                node = word.head
                while node.i not in seen:
                    seen.add(node.i)
                    if node.i >= word.i:
                        break
                    spine.append(node)
                    node = node.head

                if any(node.pos_ == "VERB" for node in spine):
                    targets = {}
                    for depth, node in enumerate(spine):
                        strength = 1.0 / (1.0 + 0.25 * depth)
                        if node.pos_ in ("VERB", "AUX", "NOUN", "PROPN", "ADP"):
                            targets[node.i] = strength

                        if node.pos_ in ("VERB", "AUX", "ADJ"):
                            for child in node.children:
                                if child.i >= word.i:
                                    continue
                                relative_subject = (
                                    node.dep_ == "relcl"
                                    and child.dep_ in ("nsubj", "nsubjpass")
                                    and child.pos_ == "PRON"
                                )
                                if child.dep_ in (
                                    "mark", "cc", "aux", "auxpass", "advmod"
                                ) or relative_subject:
                                    weight = strength * (
                                        1.4 if child.dep_ in ("mark", "cc") else 0.8
                                    )
                                    targets[child.i] = max(
                                        targets.get(child.i, 0.0), weight
                                    )

                    extra = np.zeros(i, dtype=np.float64)
                    for wi, weight in targets.items():
                        if word_tokens[wi]:
                            j = word_tokens[wi][-1]
                            if 0 < j < i:
                                extra[j] += weight

                    total = extra.sum()
                    if total > 0:
                        target_sink = 0.22 if nominal else 0.32
                        transfer = max(0.0, attention[i, 0] - target_sink)
                        attention[i, 0] -= transfer
                        attention[i, :i] += transfer * extra / total

    return "bos_sink_with_clause_spine", attention


def prog_L19H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local residual attention and clause-boundary predicate routing.
    Pronouns do not automatically route strongly to an adjacent verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_routing", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    sink_prior = {
        "PROPN": 0.85,
        "NOUN": 0.73,
        "ADJ": 0.69,
        "ADV": 0.64,
        "VERB": 0.60,
        "AUX": 0.52,
        "PRON": 0.49,
        "DET": 0.40,
        "ADP": 0.41,
        "PART": 0.47,
        "CCONJ": 0.40,
        "SCONJ": 0.43,
        "NUM": 0.69,
        "PUNCT": 0.52,
        "SPACE": 0.75,
        "INTJ": 0.73,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        previous_indices = alignment[i - 1]
        previous = doc[previous_indices[0]] if previous_indices else None

        sink = sink_prior.get(word.pos_, 0.62) if word is not None else 0.65
        sink += 0.15 * np.exp(-(i - 1) / 7.0)
        sink -= 0.08 * (1.0 - np.exp(-i / 35.0))

        if word is not None:
            if word.ent_type_:
                sink += 0.04
            if len(inverse[word.i]) > 1:
                sink += 0.07
            if word.dep_ in ("nsubj", "nsubjpass") and i < 6:
                sink += 0.05

        clean = tokens[i].replace("▁", "").replace("Ġ", "")
        if not clean.strip():
            sink = max(sink, 0.78)
        elif "'" in clean or "’" in clean:
            sink = max(sink, 0.81)
        elif "?" in clean or "!" in clean:
            sink = max(sink, 0.73)

        if i == 1 and word is not None:
            sink = {
                "PRON": 0.97,
                "PROPN": 0.96,
                "DET": 0.70,
                "NUM": 0.86,
            }.get(word.pos_, 0.86)

        local = np.zeros(i + 1, dtype=np.float64)
        local[1:] = 0.12 * np.exp(
            -(i - np.arange(1, i + 1)) / 3.0
        )
        local[i] += 0.43
        if i > 1:
            local[i - 1] += 0.38
        if i > 2:
            local[i - 2] += 0.10

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_positions:
                local[head_positions[-1]] += 0.12

            if previous is not None and previous.i != word.i:
                if (
                    word.pos_ == "PRON"
                    and previous.pos_ in ("VERB", "AUX")
                ):
                    sink -= 0.19
                    local[i - 1] += 0.95
                elif (
                    word.pos_ == "CCONJ"
                    and previous.pos_ in ("VERB", "AUX", "ADJ")
                ):
                    sink -= 0.10
                    local[i - 1] += 0.65

            # Adjacent pronouns retain the baseline local kernel rather than
            # receiving the extra verb-to-pronoun shortcut above.
            if (
                previous is not None
                and previous.i != word.i
                and word.pos_ == "PRON"
                and previous.pos_ in ("VERB", "AUX")
            ):
                sink += 0.19
                local[i - 1] -= 0.95
                if word.dep_ in ("dobj", "obj", "iobj"):
                    sink += 0.10

            # Predicate coordination and embedded subjects can retrieve an
            # earlier predicate instead of the immediately preceding noun.
            coordination = (
                word.pos_ == "CCONJ"
                and word.head.pos_ in ("VERB", "AUX", "ADJ")
            )
            embedded_subject = (
                word.pos_ == "PRON"
                and word.dep_ in ("nsubj", "nsubjpass")
                and word.head.dep_ in ("ccomp", "advcl", "relcl", "conj")
            )
            if coordination or embedded_subject:
                candidates = [
                    j for j in range(1, i)
                    if alignment[j]
                    and doc[alignment[j][0]].pos_ in ("VERB", "AUX")
                    and (
                        coordination
                        or alignment[j][0] != word.head.i
                    )
                    and doc[alignment[j][0]].sent.start == word.sent.start
                ]
                if candidates:
                    target = candidates[-1]
                    sink -= 0.15 if coordination else 0.22
                    local[target] += 1.20
                    if (
                        coordination
                        and previous is not None
                        and previous.i != word.i
                        and previous.pos_ in ("VERB", "AUX", "ADJ")
                    ):
                        local[i - 1] -= 0.65
                    for j in range(target + 1, i):
                        if (
                            alignment[j]
                            and doc[alignment[j][0]].pos_ == "ADP"
                        ):
                            local[j] += 0.30

        sink = float(np.clip(sink, 0.22, 0.98))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * local[1:] / local[1:].sum()
        )

    return "bos_sink_with_clause_routing", attention


def prog_L19H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with clause-completion retrieval: completed predicates and
    arguments redirect sink mass to their predicate frame."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_completion_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for sid in sids:
            inverse[sid].append(ti)

    previous_focus = None
    attention[0, 0] = 1.0
    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        sink = 0.95

        if word is not None:
            pos = word.pos_
            if pos in ("DET", "AUX", "ADP", "PART"):
                sink = 0.975
            elif pos == "PRON":
                sink = 0.955
            elif pos == "PROPN":
                sink = 0.945
            elif pos in ("NOUN", "VERB", "ADJ", "ADV"):
                sink = 0.90
            elif pos == "CCONJ":
                sink = 0.65
            elif pos == "SCONJ":
                sink = 0.92
            elif pos == "PUNCT":
                sink = 0.72

            if word.dep_ in ("poss", "det"):
                sink = max(sink, 0.975)

            # Internal subword pieces often retain a strong sink preference.
            if inverse[word.i] and inverse[word.i][0] < i and pos != "PUNCT":
                sink = max(sink, 0.94)

        if i == 1:
            sink = 0.995

        # The non-sink component is causal and mostly local.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.35

        if word is not None:
            head_indices = inverse[word.head.i]
            eligible = [j for j in head_indices if 0 < j < i]
            if eligible and word.head.i != word.i:
                residual[eligible[-1] - 1] += 1.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Only completed frames get additional retrieval; preserve the entire
        # default row, including its self-weight, except for transferred BOS mass.
        focus = None
        target_sink = 0.32
        if word is not None and inverse[word.i] and i == inverse[word.i][-1]:
            anchor = None
            following = doc[word.i + 1] if word.i + 1 < len(doc) else None
            boundary = following is None or following.pos_ in (
                "PUNCT", "CCONJ", "SCONJ"
            )
            if word.pos_ == "ADJ":
                predicate = word
                while predicate.dep_ == "conj" and predicate.head.i != predicate.i:
                    predicate = predicate.head
                if predicate.dep_ in ("acomp", "attr") or any(
                    c.dep_ == "cop" for c in predicate.children
                ):
                    anchor = predicate
                    target_sink = 0.25
            elif word.pos_ in ("NOUN", "PROPN") and boundary and word.dep_ in (
                "dobj", "obj", "pobj", "attr"
            ):
                anchor = word.head
                if anchor.pos_ == "ADP":
                    anchor = anchor.head
            elif word.dep_ == "prt" or (
                word.pos_ == "PRON"
                and word.dep_ in ("dobj", "obj")
                and word.head.dep_ == "xcomp"
            ):
                anchor = word.head
                target_sink = 0.16
            elif word.pos_ == "CCONJ" and word.head.pos_ in ("VERB", "AUX"):
                if word.i > 0 and doc[word.i - 1].dep_ in ("dobj", "obj", "pobj"):
                    anchor = word.head
                    target_sink = 0.20

            if anchor is not None and anchor.pos_ in ("VERB", "AUX", "ADJ"):
                focus = np.zeros(n, dtype=np.float64)
                frames = [anchor]
                while frames[-1].dep_ in ("xcomp", "acomp", "attr"):
                    parent = frames[-1].head
                    if parent.i == frames[-1].i or parent.pos_ not in ("VERB", "AUX"):
                        break
                    frames.append(parent)
                for frame in frames:
                    members = [(frame, 3.0)]
                    members += [
                        (c, 3.0 if c.dep_ == "advmod" else 1.5)
                        for c in frame.children
                        if c.dep_ in (
                            "nsubj", "nsubjpass", "aux", "auxpass",
                            "cop", "neg", "mark", "advmod", "prep"
                        )
                    ]
                    for member, weight in members:
                        eligible = [j for j in inverse[member.i] if 0 < j < i]
                        if eligible:
                            focus[eligible[-1]] += weight
            elif word.pos_ == "PUNCT" and previous_focus is not None:
                focus = previous_focus.copy()
                target_sink = 0.25

        if focus is not None and focus.sum() > 0:
            transfer = max(0.0, attention[i, 0] - target_sink)
            attention[i, 0] -= transfer
            attention[i] += transfer * focus / focus.sum()
        previous_focus = focus

    return "bos_sink_with_completion_retrieval", attention


def prog_L19H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink, with selective off-diagonal escape to discourse anchors
    in quoted speech and sentences introduced by a prepositional frame.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        distances = i - np.arange(i + 1)
        residual = np.exp(-distances / 4.0)
        residual /= residual.sum()
        attention[i, :i + 1] = 0.03 * residual
        attention[i, 0] += 0.97

    doc = spacy_parse(sentence)
    quoted = any(c in sentence for c in ('"', '“', '”', '«', '»'))
    framed = bool(doc) and doc[0].pos_ == "ADP"

    # Leave ordinary, unquoted sentences entirely unchanged.
    if quoted or framed:
        mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
        frame_end = -1
        if framed:
            for word in doc:
                if word.pos_ in ("NOUN", "PROPN", "PRON", "VERB", "AUX"):
                    break
                frame_end = word.i

        for word in doc:
            pieces = mapping[word.i]
            if not pieces:
                continue
            i = pieces[-1]
            if i <= 1:
                continue

            following = doc[word.i + 1] if word.i + 1 < len(doc) else None
            subject = word.dep_ in ("nsubj", "nsubjpass", "csubj")
            clause_end = following is None or following.is_punct
            coordinated = (
                word.i > 0
                and doc[word.i - 1].pos_ == "CCONJ"
            )

            mass = 0.0
            if word.pos_ in ("NOUN", "PROPN"):
                mass = 0.45 if clause_end else 0.12
                if subject:
                    mass = 0.60 if quoted else 0.38
            elif word.pos_ == "PRON" and subject and coordinated:
                mass = 0.65
            elif word.pos_ == "CCONJ":
                mass = 0.32
            elif word.is_punct:
                mass = 0.26 if any(c in word.text for c in ".!?") else 0.12
            elif word.pos_ == "ADV" and coordinated:
                mass = 0.28

            if mass == 0.0:
                continue

            anchors = np.zeros(i, dtype=np.float64)
            for previous in doc[:word.i]:
                prior_pieces = [j for j in mapping[previous.i] if 0 < j < i]
                if not prior_pieces:
                    continue
                j = prior_pieces[-1]
                weight = 0.0

                if previous.i <= frame_end:
                    weight += 1.0 if previous.i == frame_end else 0.4
                if previous.is_punct:
                    if any(c in previous.text for c in ('"', '“', '”', '«', '»')):
                        weight += 3.0
                    elif any(c in previous.text for c in ".!?"):
                        weight += 2.0
                    else:
                        weight += 1.0
                if previous.pos_ in ("VERB", "AUX") and (
                    previous.dep_ in ("ROOT", "conj")
                    or any(c.dep_ == "ccomp" for c in previous.children)
                ):
                    weight += 1.5
                if previous.pos_ == "CCONJ":
                    weight += 0.8
                if previous.dep_ in ("nsubj", "nsubjpass"):
                    weight += 0.4
                if previous.head.i == word.i and previous.pos_ == "DET":
                    weight += 0.8

                anchors[j] += weight

            total = anchors.sum()
            if total > 0:
                # Transfer only BOS mass: retain every original diagonal
                # entry and the original recency-decay contribution.
                moved = min(mass, attention[i, 0])
                attention[i, 0] -= moved
                attention[i, :i] += moved * anchors / total

    return "bos_sink_with_discourse_escape", attention


def prog_L19H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent leakage.
    Residual attention is diffuse, with a small recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.99 / (1.0 + 0.0012 * (i - 1))
        positions = np.arange(1, i + 1)
        residual = 0.8 / i + 0.2 * np.exp(-(i - positions) / 4.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_diffuse_leakage", attention


def prog_L19H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with secondary attention to the initial token and opening quotes.
    Content words favor these anchors; function words and word starts favor BOS.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_start_anchors", matrix

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)

    first = next(
        (i for i, t in enumerate(tokens) if t not in specials),
        0,
    )
    opening_quote = None
    in_quote = False

    for i, raw in enumerate(tokens):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        text = raw.replace("▁", " ").replace("Ġ", " ").strip()
        sids = aligned[i]
        word = doc[sids[0]] if sids else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        is_quote = any(c in text for c in ('"', "“", "”", "«", "»"))
        closing_quote = is_quote and in_quote
        if is_quote and not in_quote:
            opening_quote = i
            in_quote = True

        anchor = first if first < i else 0
        if opening_quote is not None and opening_quote < i and in_quote:
            anchor = opening_quote

        bos = 0.70
        if pos in ("DET", "PRON", "ADP", "CCONJ", "SCONJ", "PART", "AUX"):
            bos = 0.88
        elif pos == "ADV":
            bos = 0.78
        elif pos == "VERB":
            bos = 0.46
        elif pos in ("NOUN", "PROPN"):
            bos = 0.48
            if dep in ("nsubj", "nsubjpass", "csubj") and i < first + 5:
                bos = 0.80
        elif pos == "ADJ":
            bos = 0.88 if dep == "amod" else 0.24
        elif pos == "PUNCT":
            bos = 0.55 if text in (",", ".", "!", "?", '?"', '!"') else 0.88

        # Split lexical words often route their early pieces almost entirely
        # to the sink, while their final pieces expose the anchor preference.
        if word is not None:
            pieces = inverse[word.i]
            if len(pieces) > 1:
                if i < pieces[-1]:
                    bos = max(bos, 0.94)
                elif pos in ("NOUN", "PROPN", "VERB", "ADJ"):
                    bos = min(bos, 0.42)

        if text in ("'", "’") or not text:
            bos = max(bos, 0.92)
        if is_quote and not closing_quote:
            bos = max(bos, 0.84)
        if i == first:
            bos = 0.95

        # Keep a small causal local tail rather than making the head purely
        # a two-position lookup.
        tail = 0.035
        matrix[i, 0] += bos
        matrix[i, anchor] += 1.0 - bos - tail
        start = max(1, i - 3)
        distances = np.arange(i - start, -1, -1, dtype=np.float64)
        weights = np.exp(-0.9 * distances)
        matrix[i, start:i + 1] += tail * weights / weights.sum()

        if closing_quote:
            in_quote = False
            opening_quote = None

    return "bos_sink_with_start_anchors", make_row_stochastic(
        apply_causal_mask(matrix)
    )


def prog_L19H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A dominant beginning-of-sequence attention sink, with weak causal recency.
    Sink strength gradually decreases as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_weak_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.99 - 0.14 * (1.0 - np.exp(-(i - 1) / 65.0))

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 5.0)
        residual /= residual.sum()
        residual = 0.75 * residual + 0.25 / i

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_weak_recency", attention


def prog_L19H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a dominant beginning-of-sequence attention sink.
    Sink strength slowly decreases with position, with weak causal background attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.988 / (1.0 + 0.0025 * (i - 1))

        # Punctuation and whitespace tend to have a slightly weaker sink.
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if not surface:
            sink_mass -= 0.035
        elif all(not ch.isalnum() for ch in surface):
            sink_mass -= 0.025

        sink_mass = np.clip(sink_mass, 0.65, 0.995)
        attention[i, 0] = sink_mass

        # The examples do not identify specific non-BOS targets, so keep
        # the residual diffuse, with only a modest preference for recency.
        distances = i - np.arange(1, i + 1) + 1.0
        background = 0.8 / i + 0.2 * (
            distances ** -0.7 / np.sum(distances ** -0.7)
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_position_decay", attention


def prog_L19H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS attention sink with local syntactic spillover.
    Completed modifiers and nearby predicates attract the strongest non-BOS mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_tokens[wi].append(ti)

    special_tokens = tokenizer.all_special_tokens
    word_index = []
    for ti, word_ids in enumerate(alignment):
        if tokens[ti] in special_tokens or not word_ids:
            word_index.append(None)
        else:
            word_index.append(word_ids[-1])

    attention[0, 0] = 1.0

    for i in range(1, n):
        wi = word_index[i]
        word = doc[wi] if wi is not None else None
        previous_wi = word_index[i - 1]
        previous = doc[previous_wi] if previous_wi is not None else None

        sink = 0.59 + 0.40 * np.exp(-(i - 1) / 5.0)
        if word is not None:
            if word.pos_ in ("ADJ", "PROPN"):
                sink += 0.07
            elif word.pos_ in ("VERB", "AUX"):
                sink += 0.03
            elif word.pos_ in ("CCONJ", "SCONJ"):
                sink -= 0.10

            pieces = word_tokens[wi]
            if len(pieces) > 1 and i != pieces[-1]:
                sink = max(sink, 0.94 if i == pieces[0] else 0.88)

            if word.pos_ in ("NOUN", "PROPN"):
                if any(child.dep_ == "amod" for child in word.children):
                    sink -= 0.20

            if word.is_punct:
                sink += 0.03

        local_target = None
        if word is not None and previous is not None and wi != previous_wi:
            if word.pos_ == "CCONJ" and previous.pos_ == "ADJ":
                sink = 0.30
                local_target = i - 1
            elif (
                word.dep_ in ("dobj", "obj", "attr")
                and word.head.i == previous_wi
                and previous.pos_ == "VERB"
                and previous.tag_ == "VBG"
            ):
                sink = 0.36
                local_target = i - 1

        if i == 1:
            sink = 0.985
        sink = float(np.clip(sink, 0.12, 0.995))

        positions = np.arange(1, i + 1)
        weights = 0.10 * np.exp(-(i - positions) / 3.0)
        if i > 1:
            weights[i - 2] += 1.0
        weights[-1] += 0.12

        if word is not None:
            head_pieces = word_tokens[word.head.i]
            causal_head = [j for j in head_pieces if 0 < j < i]
            if word.head.i != wi and causal_head:
                distance = i - causal_head[-1]
                weights[causal_head[-1] - 1] += 0.65 * np.exp(-distance / 8.0)

            for child in get_modifying_adjectives(word):
                candidates = [j for j in word_tokens[child.i] if 0 < j < i]
                if candidates:
                    weights[candidates[-1] - 1] += 1.2

        if local_target is not None:
            weights *= 0.12
            weights[local_target - 1] += 3.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "bos_sink_with_local_syntax", attention


def prog_L19H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink, weakening with distance.
    Punctuation slightly increases the small, diffuse causal residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[0]].pos_ if aligned else ""
        is_punctuation = (
            pos == "PUNCT"
            or (
                bool(tokens[i].strip("▁Ġ "))
                and all(
                    not c.isalnum() and not c.isspace()
                    for c in tokens[i].strip("▁Ġ ")
                )
            )
        )

        # Increasing competition from the growing causal context.
        residual_odds = 0.006 + 0.0015 * i + 0.000025 * i * i
        if is_punctuation:
            residual_odds += 0.065
        elif pos in ("VERB", "ADJ", "ADV"):
            residual_odds += 0.012
        elif pos in ("PRON", "DET"):
            residual_odds *= 0.85

        if i == 1:
            residual_odds *= 0.5

        sink_mass = 1.0 / (1.0 + residual_odds)
        attention[i, 0] = sink_mass

        # The examples constrain the sink much more than residual targets;
        # use a broad causal background with only a mild recency preference.
        positions = np.arange(1, i + 1, dtype=np.float64)
        background = 0.75 / i + 0.25 * np.exp((positions - i) / 8.0)
        background /= background.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "bos_sink_with_position_decay", attention


def prog_L19H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention targets the first token.
    A weak, diffuse causal background gradually grows with prefix length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_background", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 1.0 / (1.0 + 0.008 + 0.004 * i)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) / i

    return "bos_sink_with_diffuse_background", attention


def prog_L19H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with mildly increasing leakage over position.
    Punctuation and clause boundaries weaken the sink; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        leakage_odds = 0.009 + 0.0012 * i
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.is_punct:
                leakage_odds *= 2.5
            elif word.is_space:
                leakage_odds *= 5.0
            elif word.pos_ in ("VERB", "ADV"):
                leakage_odds *= 1.25
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                leakage_odds *= 0.85

            if word.dep_ in ("advcl", "ccomp", "conj", "parataxis"):
                leakage_odds *= 1.15
        else:
            surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
            if not surface.strip():
                leakage_odds *= 5.0
            elif all(not c.isalnum() and not c.isspace() for c in surface):
                leakage_odds *= 2.5

        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.7 + 0.3 * np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_boundary_leakage", attention


def prog_L19H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution and weak linguistic modulation.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.975 - 0.0036 * min(i - 1, 65)

        if alignment[i]:
            word_index = alignment[i][0]
            word = doc[word_index]

            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.015
            elif word.pos_ in ("PUNCT", "CCONJ", "SCONJ"):
                sink_mass -= 0.035

            # Fragmented lexical items often retain unusually strong BOS attention.
            pieces = inverse[word_index]
            if len(pieces) > 1 and i == pieces[0]:
                sink_mass += 0.065
            elif len(pieces) > 1 and i == pieces[1]:
                sink_mass += 0.025

        sink_mass = float(np.clip(sink_mass, 0.65, 0.99))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_positional_dilution", attention


def prog_L19H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the initial token,
    with weak causal background attention that grows with context length.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_attention_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 / (1.0 + 0.0025 * (i - 1))
        attention[i, 0] = sink_mass

        # The examples constrain the sink much more than the residual edges.
        # Use a broad background with only a mild recency preference.
        distances = i - np.arange(1, i + 1)
        background = 1.0 + np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_attention_sink", attention


def prog_L19H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild position-dependent leakage.
    Residual attention favors recent context and accessible syntactic relations.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        # The overwhelmingly dominant destination is the initial token.
        sink_mass = 0.993 * np.exp(-0.0028 * (i - 1))
        word_ids = alignment[i]
        if word_ids:
            word = doc[word_ids[0]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.055
            elif word.pos_ in ("NOUN", "PROPN", "DET", "PRON"):
                sink_mass += 0.008
        sink_mass = np.clip(sink_mass, 0.72, 0.995)

        destinations = np.arange(1, i + 1)
        residual = 0.15 + np.exp(-(i - destinations) / 7.0)

        for wi in word_ids:
            word = doc[wi]
            # Only use syntactic links whose destinations are already visible.
            if word.head.i != wi:
                for j in inverse[word.head.i]:
                    if 0 < j <= i:
                        residual[j - 1] += 1.5

            for child in word.children:
                if child.dep_ in ("dobj", "obj", "pobj", "nsubj", "attr"):
                    for j in inverse[child.i]:
                        if 0 < j < i:
                            residual[j - 1] += 0.8

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_syntactic_leakage", attention


def prog_L19H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, recency-weighted causal leakage.
    Sink strength decreases mildly with position rather than tracking syntax.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_recency_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.98 - 0.10 * (1.0 - np.exp(-(i - 1) / 35.0))

        # Spread the small non-sink component over accessible content tokens.
        distances = i - np.arange(1, i + 1)
        residual = 0.7 * np.exp(-distances / 6.0) + 0.3
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_recency_leakage", attention


def prog_L19H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker local/self attention, especially at phrase endings."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[ids[0]] if ids else None for ids in alignment]
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Strong default sink, gradually less dominant as context accumulates.
        sink = 0.60 + 0.25 * np.exp(-(i - 1) / 11.0)
        if pos in ("ADJ", "ADV"):
            sink += 0.11
        elif pos in ("DET", "AUX"):
            sink += 0.06
        elif pos in ("PRON", "PROPN"):
            sink += 0.08
        elif pos in ("ADP", "CCONJ", "SCONJ", "PART"):
            sink -= 0.06
        elif pos == "PUNCT":
            sink -= 0.17

        if dep in ("nsubj", "nsubjpass", "csubj"):
            sink += 0.07
        if word is not None and word.ent_type_:
            sink += 0.04

        # Subword pieces often retain the sink preference of their word.
        if i > 1 and alignment[i] and alignment[i - 1]:
            if alignment[i][0] == alignment[i - 1][0]:
                sink += 0.06

        if i == 1:
            sink = 0.97 if pos != "DET" else 0.92
        sink = float(np.clip(sink, 0.30, 0.985))

        # Residual attention is local, with content-bearing tokens acting
        # as small secondary anchors rather than a global syntactic target.
        indices = np.arange(1, i + 1)
        residual = np.exp(-(i - indices) / 2.5)
        for j in range(1, i + 1):
            key = words[j]
            if key is not None:
                if key.pos_ in ("NOUN", "PROPN", "ADJ"):
                    residual[j - 1] *= 1.6
                elif key.pos_ == "PUNCT":
                    residual[j - 1] *= 0.35

        if pos in ("NOUN", "PROPN", "ADJ"):
            residual[-1] *= 1.8
        if pos == "PUNCT" and i > 1:
            residual[-2] *= 2.5
            residual[-1] *= 0.4

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_local_residual", attention


def prog_L19H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink head with position-dependent leakage to subjects, self, and local context.
    Subject introductions and fragmented content words reinforce the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_leakage", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    subjects = {"nsubj", "nsubjpass", "csubj", "csubjpass"}
    objects = {"dobj", "obj", "iobj", "pobj", "attr", "oprd"}
    opening_quotes = {'"', "“", "‘", "«", "``"}
    latest_subject = None
    latest_quote = None
    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = [k for k in aligned[i] if 0 <= k < len(doc)]
        word = doc[indices[0]] if indices else None

        if word is not None and word.dep_ in subjects:
            latest_subject = inverse[word.i][0]

        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        if clean in opening_quotes:
            latest_quote = i

        # Early positions strongly favor the sink; later tokens have more
        # opportunities to retrieve a subject or another contextual anchor.
        logit = 3.25 - 0.047 * i
        if i == 1:
            logit += 1.1

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if dep in subjects:
                logit += 0.85
            if pos == "PROPN":
                logit += 0.85
            elif pos == "AUX":
                logit += 0.25
            elif pos == "ADP":
                logit -= 1.25
            elif pos == "VERB":
                logit -= 0.85
            elif pos == "PRON" and dep not in subjects:
                logit -= 0.85
            elif pos == "ADV":
                logit -= 0.45

            if dep in objects:
                logit -= 0.45
            if dep in {"poss", "det"}:
                logit -= 0.15
            if dep in {"xcomp", "advcl", "relcl"}:
                logit -= 0.4

            pieces = inverse[word.i]
            if len(pieces) > 1 and pos in {"NOUN", "PROPN", "ADJ"}:
                logit += 0.75 if i < pieces[-1] else 0.15

            if word.is_punct:
                if clean == ",":
                    logit += 0.15
                elif clean in {"'", "’"}:
                    logit += 0.9
                else:
                    logit -= 0.65

        sink_mass = float(np.clip(
            1.0 / (1.0 + np.exp(-logit)), 0.08, 0.997
        ))

        remainder = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        remainder[1:] = 0.15 * np.exp(-(i - positions) / 3.0)
        remainder[i] += 0.45

        if latest_subject is not None and 0 < latest_subject <= i:
            remainder[latest_subject] += 1.1

        if word is not None:
            head_indices = inverse[word.head.i]
            causal_heads = [j for j in head_indices if 0 < j <= i]
            if causal_heads:
                remainder[causal_heads[0]] += 0.25

            if (
                latest_quote is not None
                and latest_quote <= i
                and word.pos_ in {"AUX", "VERB"}
                and i - latest_quote < 10
            ):
                remainder[latest_quote] += 0.5

        remainder /= remainder.sum()
        attention[i, :i + 1] = (1.0 - sink_mass) * remainder
        attention[i, 0] = sink_mass

    return "bos_sink_with_subject_leakage", attention


def prog_L19H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weak causal background attention and a small
    preference for preceding syntactically salient nominal anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_background", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = tokenizer.all_special_tokens

    # Share each word's background salience across its model-token pieces.
    piece_counts = np.zeros(len(doc), dtype=np.float64)
    for indices in alignment:
        for k in indices:
            piece_counts[k] += 1.0

    salience = np.full(n, 0.30, dtype=np.float64)
    query_scale = np.ones(n, dtype=np.float64)

    for i, indices in enumerate(alignment):
        if tokens[i] in special_tokens:
            continue
        if not indices:
            if tokens[i].strip("▁Ġ").isspace() or not tokens[i].strip("▁Ġ"):
                query_scale[i] = 0.65
            continue

        word = doc[indices[0]]
        if word.pos_ in ("NOUN", "PROPN"):
            salience[i] += 0.45 / max(piece_counts[word.i], 1.0)
            if word.dep_ in ("dobj", "obj", "iobj", "pobj", "attr"):
                salience[i] += 1.10 / max(piece_counts[word.i], 1.0)
            query_scale[i] = 0.95
        elif word.pos_ == "PRON":
            query_scale[i] = 1.20
        elif word.pos_ in ("VERB", "AUX"):
            query_scale[i] = 1.10
        elif word.pos_ in ("DET", "ADP", "PART"):
            query_scale[i] = 0.85
        elif word.pos_ == "PUNCT":
            query_scale[i] = 0.62

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        distance = i - positions

        # Mostly diffuse residual mass; no strong previous-token mechanism.
        attention[i, 1:i + 1] = (
            salience[1:i + 1]
            + 0.35 * np.exp(-distance / 5.0)
        )
        attention[i, i] += 0.35
        attention[i, 0] = 85.0 * query_scale[i]

    return "bos_sink_with_nominal_background", make_row_stochastic(attention)


def prog_L19H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weaker causal attention to subjects and local content.
    Sink strength increases at sequence onset, named entities, and subword fragments.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_entity_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    pos_prior = {
        "PROPN": 0.88,
        "PRON": 0.68,
        "DET": 0.72,
        "NOUN": 0.57,
        "ADJ": 0.66,
        "ADV": 0.52,
        "VERB": 0.49,
        "AUX": 0.51,
        "ADP": 0.46,
        "PART": 0.57,
        "CCONJ": 0.43,
        "SCONJ": 0.47,
        "PUNCT": 0.55,
        "SPACE": 0.86,
        "NUM": 0.65,
        "INTJ": 0.66,
        "X": 0.80,
    }
    subject_deps = ("nsubj", "nsubjpass", "csubj", "csubjpass")
    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        sink = pos_prior.get(word.pos_, 0.62) if word is not None else 0.76

        if word is not None:
            pieces = [k for k in inverse[word.i] if k > 0]
            if len(pieces) > 1:
                sink += 0.16 if i != pieces[-1] else 0.07
            if word.ent_type_:
                sink += 0.05
            if word.dep_ in subject_deps:
                sink += 0.07

        sink = min(0.95, sink)
        sink += (0.98 - sink) * np.exp(-(i - 1) / 2.8)
        sink = min(0.99, max(0.32, sink))

        residual = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            distance = i - j
            score = 0.025 * np.exp(-distance / 14.0)
            if alignment[j]:
                candidate = doc[alignment[j][0]]
                if candidate.pos_ in ("NOUN", "PROPN", "PRON"):
                    score += 0.12 * np.exp(-distance / 15.0)
                if candidate.dep_ in subject_deps:
                    score += 0.32 * np.exp(-distance / 22.0)
            residual[j] = score

        residual[i] += 0.24
        if i > 1:
            residual[i - 1] += 0.08

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_entity_residual", make_row_stochastic(attention)


def prog_L19H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker late-position syntactic attention.
    Closing dialogue punctuation can retrieve the preceding addressee/object.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        if tokens[i] not in tokenizer.all_special_tokens:
            for k in indices:
                inverse[k].append(i)

    attention[0, 0] = 1.0
    quote_open = False
    dialogue_target = None
    pending_target = None

    for i in range(1, n):
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        first_piece = (
            word is not None
            and bool(inverse[word.i])
            and inverse[word.i][0] == i
        )

        # Initial queries overwhelmingly use the sink; later queries have
        # more opportunities for non-sink competition.
        sink = 0.97 - 0.31 * (1.0 - np.exp(-(i - 1) / 17.0))
        if pos in ("NOUN", "PROPN") and first_piece:
            sink += 0.13
        elif pos in ("PRON", "DET"):
            sink += 0.05
        elif pos in ("VERB", "ADJ", "ADP", "SCONJ"):
            sink -= 0.08
        if word is not None and not first_piece and pos != "PUNCT":
            sink -= 0.09
        if i == 1:
            sink = 0.995
        sink = float(np.clip(sink, 0.38, 0.995))

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = 0.12 + np.exp(-(i - positions) / 8.0)

        if word is not None:
            for k in inverse[word.head.i]:
                if 0 < k <= i:
                    residual[k] += 2.0
            for child in word.children:
                for k in inverse[child.i]:
                    if 0 < k < i:
                        residual[k] += 0.5

        has_quote = any(c in clean for c in ('"', '“', '”'))
        terminal = any(c in clean for c in ("?", "!"))
        if not terminal and i > 1 and has_quote:
            terminal = any(c in tokens[i - 1] for c in ("?", "!"))

        if terminal and dialogue_target is not None:
            sink = 0.22
            residual *= 0.12
            residual[dialogue_target] += 12.0

        if has_quote:
            if quote_open:
                quote_open = False
            else:
                quote_open = True
                dialogue_target = pending_target

        if (
            not quote_open
            and word is not None
            and pos in ("NOUN", "PROPN", "PRON")
            and dep in ("dobj", "obj", "iobj", "dative", "pobj", "vocative")
        ):
            pending_target = i

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_dialogue_retrieval", make_row_stochastic(attention)


def prog_L19H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Dominant beginning-of-sequence attention sink with weak local attention.
    Punctuation modestly shifts attention from the sink toward recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        is_punctuation = (
            any(doc[k].pos_ == "PUNCT" for k in aligned)
            if aligned
            else (
                bool(tokens[i].strip("▁Ġ "))
                and all(
                    not c.isalnum()
                    for c in tokens[i].strip("▁Ġ ")
                )
            )
        )

        # Early queries are especially sink-dominated; the effect persists
        # throughout the sequence rather than moving to a sentence boundary.
        sink_mass = 0.89 + 0.105 * np.exp(-(i - 1) / 5.0)
        if is_punctuation:
            sink_mass -= 0.10

        # The remaining mass is deliberately diffuse: the examples provide
        # little evidence for a consistent non-BOS target.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-(i - positions) / 5.0)
        residual += 0.15
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_local_residual", attention


def prog_L19H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak self-attention and recency-weighted residuals.
    Linguistic features modestly adjust the strength of the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self_and_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.83
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ == "VERB":
                sink += 0.045
            elif word.pos_ in ("ADJ", "ADV"):
                sink += 0.015
            elif word.pos_ == "PROPN":
                sink -= 0.065
            elif word.pos_ == "NOUN":
                sink -= 0.035
            elif word.pos_ == "AUX":
                sink -= 0.025

            if word.dep_ in ("nsubj", "nsubjpass"):
                sink -= 0.015

        attention[i, 0] = sink
        residual = 1.0 - sink

        if i == 1:
            attention[i, i] = residual
        else:
            # Most non-sink mass stays on the query token; the remainder
            # follows a short causal recency distribution excluding BOS.
            attention[i, i] = 0.70 * residual
            distances = i - np.arange(1, i)
            weights = np.exp(-distances / 3.0)
            attention[i, 1:i] = 0.30 * residual * weights / weights.sum()

    return "bos_sink_with_self_and_recency", make_row_stochastic(attention)


def prog_L19H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention-sink head with weak, diffuse causal background attention.
    Background mass grows mildly with the number of available tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, 0] = 1.0
        if i > 0:
            positions = np.arange(1, i + 1)
            # A small distributed remainder, with only a weak recency bias.
            attention[i, 1:i + 1] = (
                0.0015 + 0.003 * np.exp(-(i - positions) / 4.0)
            )

    return "bos_sink_with_diffuse_background", make_row_stochastic(attention)


def prog_L19H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local syntax; definite prepositional noun phrases additionally
    route a small portion of sink attention to their introducing preposition.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_definite_pp_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "VERB": 0.935,
        "AUX": 0.84,
        "NOUN": 0.84,
        "PROPN": 0.94,
        "ADJ": 0.91,
        "ADV": 0.81,
        "ADP": 0.81,
        "DET": 0.64,
        "PRON": 0.67,
        "PART": 0.78,
        "CCONJ": 0.87,
        "SCONJ": 0.83,
        "NUM": 0.83,
        "PUNCT": 0.96,
        "SPACE": 0.91,
    }

    for i in range(1, n):
        word = None
        if alignment[i]:
            word = doc[alignment[i][0]]

        sink = sink_by_pos.get(word.pos_, 0.88) if word is not None else 0.90
        head_positions = []

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j < i
            ]
            if word.pos_ == "PRON":
                if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    sink = 0.79
                elif (
                    word.dep_ in ("dobj", "obj", "iobj", "attr")
                    and word.head.pos_ in ("VERB", "AUX")
                    and head_positions
                ):
                    gap = i - max(head_positions)
                    sink = 0.34 if gap <= 2 else 0.52

        if tokens[i] in tokenizer.all_special_tokens:
            sink = 0.98

        # Keep the non-sink component causal and predominantly local.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.0)
        local[-1] *= 0.30
        if i > 1:
            local[-2] += 1.5

        if head_positions:
            local[max(head_positions) - 1] += 2.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Narrow exception: a definite NP governed by a nearby preposition.
        # Transfer only BOS mass; preserve self-attention and all other edges.
        if word is not None and tokens[i] not in tokenizer.all_special_tokens:
            nominal = None
            if word.pos_ in ("NOUN", "PROPN"):
                nominal = word
            elif (
                word.dep_ in ("det", "amod")
                and word.head.pos_ in ("NOUN", "PROPN")
            ):
                nominal = word.head

            if (
                nominal is not None
                and nominal.dep_ in ("pobj", "obj", "obl")
                and nominal.head.pos_ == "ADP"
                and any(
                    child.dep_ == "det"
                    and "Def" in child.morph.get("Definite")
                    for child in nominal.children
                )
            ):
                anchors = [
                    j for j in inverse[nominal.head.i]
                    if 0 < j < i and i - j <= 5
                ]
                if anchors:
                    transfer = (
                        0.28 if word.dep_ == "det"
                        else 0.30 if word.dep_ == "amod"
                        else 0.08
                    )
                    transfer = min(transfer, attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i, max(anchors)] += transfer

    return "bos_sink_with_definite_pp_anchor", attention


def prog_L19H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local residual; quoted dialogue adds backward attention
    at punctuation boundaries and fragmented names or nouns."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_local_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        attention[i, 0] = 0.91
        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 3.0)
        attention[i, 1:i + 1] = 0.09 * residual / residual.sum()

    # Leave ordinary prose untouched. Transfer only BOS mass, preserving
    # every original self-weight and the original residual distribution.
    if any(q in sentence for q in ('"', '“', '”')):
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        word_pieces = [[] for _ in doc]
        for ti, sids in enumerate(aligned):
            for sid in sids:
                word_pieces[sid].append(ti)

        for i in range(2, n):
            if not aligned[i]:
                continue
            sid = aligned[i][-1]
            word = doc[sid]
            pieces = word_pieces[sid]
            start = pieces[0]
            target = None
            extra = 0.0

            # Commas often point sharply to the final piece of the word
            # they close, especially a nominal immediately before speech.
            if word.text == "," and i == start and sid > 0:
                previous = doc[sid - 1]
                previous_pieces = word_pieces[sid - 1]
                if previous_pieces:
                    target = previous_pieces[-1]
                    if previous.pos_ in ("NOUN", "PROPN"):
                        extra = 0.43 if len(previous_pieces) == 1 else 0.50
                        if previous.pos_ == "PROPN" and len(previous_pieces) > 1:
                            extra = 0.07
                    else:
                        extra = 0.16

            # Fragmented nominal tokens retain a strong connection to the
            # token before the word; later pieces also attend its first piece.
            elif word.pos_ in ("NOUN", "PROPN") and len(pieces) > 1 and start > 1:
                strength = 0.58 if word.pos_ == "PROPN" else 0.18
                if i == start:
                    target = start - 1
                    extra = strength
                else:
                    extra = strength * 0.60 ** (pieces.index(i))
                    attention[i, start] += extra * 0.60
                    attention[i, start - 1] += extra * 0.40
                    attention[i, 0] -= extra
                    continue

            # The first lexical token following an opening quotation mark.
            elif i == start and '"' in tokens[i - 1]:
                target = i - 1
                extra = 0.23

            if target is not None and 0 < target < i and extra > 0.0:
                attention[i, target] += extra
                attention[i, 0] -= extra

    return "bos_sink_with_dialogue_boundary_residual", attention


def prog_L19H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local residuals; intra-word continuations suppress their
    preceding fragment, with split nominal objects favoring causal subject anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_continuation_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = None
        if aligned:
            word = doc[aligned[-1]]

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # A strong initial sink settles into a moderate default BOS preference.
        sink = 0.46 + 0.43 * np.exp(-(i - 1) / 3.0)
        if pos in ("NOUN", "PROPN", "ADJ"):
            sink += 0.07
        elif pos in ("VERB", "AUX"):
            sink -= 0.12
        elif pos in ("PRON", "PART", "SCONJ"):
            sink -= 0.06

        if dep in ("amod", "pobj", "attr"):
            sink += 0.035

        if i == 1:
            sink = 0.94
        elif i == 2:
            sink = 0.80 if pos != "AUX" else 0.69

        # Tokenization artifacts and punctuation often act as sink-only queries.
        if not clean:
            sink = 0.86
        elif clean in ("'", "’"):
            sink = 0.94
        elif any(c in ".?!" for c in clean) and all(
            not c.isalnum() for c in clean
        ):
            sink = 0.85
        elif clean == ",":
            sink = 0.55 + 0.30 * np.exp(-(i - 1) / 6.0)
        elif all(c in "\"“”«»" for c in clean):
            sink = 0.47
        elif raw in special_tokens:
            sink = 0.90

        if (
            pos == "PROPN"
            and len(clean) == 1
            and clean.isupper()
        ):
            sink = max(sink, 0.90)

        sink = float(np.clip(sink, 0.22, 0.97))
        attention[i, 0] = sink

        # The non-sink component is mainly local, not a long-range relation head.
        positions = np.arange(1, i + 1)
        residual = 0.12 * np.exp(-(i - positions) / 4.0)
        residual[-1] += 0.70
        if i > 1:
            residual[-2] += 0.75

        # Verbal queries often select their immediate left context.
        if pos in ("VERB", "AUX") and i > 1:
            residual[-2] += 1.70
            residual[-1] *= 0.65
        elif pos == "PUNCT":
            residual[-1] += 0.60

        # A small causal syntactic correction, subordinate to the local prior.
        if word is not None and word.head.i != word.i:
            for j in range(max(1, i - 8), i):
                if word.head.i in alignment[j]:
                    residual[j - 1] += 0.15

        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual / residual.sum()
        )

        # Exception: fragments within one lexical word are not ordinary
        # previous-token targets. Preserve self-attention and all other edges.
        if (
            i > 1
            and word is not None
            and pos in ("NOUN", "PROPN", "ADJ", "VERB", "ADV")
            and word.i in alignment[i - 1]
            and raw not in special_tokens
            and clean
            and not raw.startswith(("▁", "Ġ"))
        ):
            moved = 0.85 * attention[i, i - 1]
            attention[i, i - 1] -= moved
            attention[i, 0] += moved

            # A split object can instead retrieve a split subject's completed
            # representation and the intervening predicate.
            if pos in ("NOUN", "PROPN") and dep in ("obj", "dobj", "pobj"):
                governor = word.head
                if governor.pos_ == "ADP" and governor.head.i != governor.i:
                    governor = governor.head

                if governor.pos_ in ("VERB", "AUX"):
                    predicate_keys = [
                        j for j in range(1, i - 1)
                        if governor.i in alignment[j]
                    ]
                    subject_keys = []
                    for child in governor.children:
                        if child.dep_ in ("nsubj", "nsubjpass", "nsubj:pass"):
                            keys = [
                                j for j in range(1, i - 1)
                                if child.i in alignment[j]
                            ]
                            if len(keys) > 1:
                                subject_keys.append(keys[-1])

                    if predicate_keys and subject_keys:
                        moved = 0.85 * attention[i, 0]
                        attention[i, 0] -= moved
                        attention[i, subject_keys[-1]] += 0.65 * moved
                        attention[i, predicate_keys[-1]] += 0.35 * moved

    return "bos_sink_with_continuation_exception", attention


def prog_L19H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local modifier/complement exception.
    Transfer only BOS mass to strong adjacent linguistic links, preserving self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_local_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_sink = {
        "DET": 0.935,
        "PRON": 0.885,
        "AUX": 0.850,
        "PART": 0.885,
        "ADP": 0.845,
        "CCONJ": 0.835,
        "SCONJ": 0.865,
        "PROPN": 0.860,
        "VERB": 0.815,
        "ADV": 0.820,
        "ADJ": 0.815,
        "NOUN": 0.760,
        "NUM": 0.825,
        "INTJ": 0.830,
        "PUNCT": 0.900,
        "SPACE": 0.945,
    }

    for i in range(1, n):
        surface = tokens[i].lstrip("▁Ġ")
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        sink = pos_sink.get(word.pos_, 0.835) if word is not None else 0.835

        if word is not None:
            if word.dep_ == "poss":
                sink = max(sink, 0.935)
            if word.ent_type_:
                sink = max(sink, 0.865)
            if i == 1:
                if word.pos_ == "DET":
                    sink = 0.972
                elif word.pos_ == "PROPN":
                    sink = 0.925
                elif word.pos_ == "PRON":
                    sink = 0.890

        if not surface or surface.isspace():
            sink = 0.945
        elif all(c in "\"'“”‘’«»" for c in surface):
            sink = 0.965 if any(c in "\"“”«»" for c in surface) else 0.920
        elif all(not c.isalnum() and not c.isspace() for c in surface):
            if any(c in ".!?" for c in surface):
                sink = 0.925
            elif "," in surface or ";" in surface or ":" in surface:
                sink = 0.875
            else:
                sink = 0.900

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 5.0)
        recency /= recency.sum()
        residual = 0.55 / i + 0.45 * recency

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Local exceptions modify only BOS and the immediately preceding token.
        if i > 1 and word is not None and alignment[i - 1]:
            previous = doc[alignment[i - 1][-1]]
            target = 0.0

            if previous.i == word.i:
                # Within a fragmented nominal, the previous piece is informative.
                if word.pos_ in ("NOUN", "PROPN"):
                    target = 0.22
                    if len(tokens[i - 1].lstrip("▁Ġ")) == 1:
                        target = 0.32

            elif word.pos_ in ("NOUN", "PROPN"):
                if previous.dep_ == "poss":
                    target = 0.32
                elif previous.pos_ == "DET":
                    target = 0.24
                elif previous.pos_ == "ADJ" and previous.head.i == word.i:
                    target = 0.32
                elif previous.pos_ in ("NOUN", "PROPN"):
                    target = 0.30
                elif previous.pos_ == "ADP" and word.head.i == previous.i:
                    target = 0.17

                # A very short opening piece strengthens the nominal link.
                if (
                    target > 0.0
                    and len(surface) == 1
                    and i + 1 < n
                    and word.i in alignment[i + 1]
                ):
                    target = max(target, 0.48)

            elif (
                word.pos_ == "ADP"
                and previous.pos_ in ("VERB", "ADJ", "ADV")
                and (
                    word.head.i == previous.i
                    or previous.head.i == word.i
                )
            ):
                target = 0.36

            elif (
                word.pos_ in ("ADV", "PART")
                and word.dep_ in ("advmod", "prt")
                and previous.pos_ == "VERB"
                and word.head.i == previous.i
            ):
                target = 0.30

            if target > attention[i, i - 1]:
                transfer = min(
                    target - attention[i, i - 1],
                    attention[i, 0],
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_local_links", make_row_stochastic(attention)


def prog_L19H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with quote-boundary exceptions and extra self-retention at
    standalone sentence-final punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_terminal_retention", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    quotes = {'"', "“", "”", "«", "»", "„", "‟"}
    terminal = {"?", "!"}

    strengths = {
        "PRON": 0.91,
        "AUX": 0.93,
        "PART": 0.89,
        "ADP": 0.85,
        "PROPN": 0.86,
        "NOUN": 0.81,
        "VERB": 0.80,
        "ADJ": 0.73,
        "ADV": 0.76,
        "DET": 0.69,
        "CCONJ": 0.77,
        "SCONJ": 0.85,
        "NUM": 0.79,
        "PUNCT": 0.62,
    }

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        mapped = alignment[i]
        word = doc[mapped[0]] if mapped else None
        pos = word.pos_ if word is not None else ""
        is_quote = any(c in quotes for c in clean)
        is_terminal_quote = is_quote and any(c in terminal for c in clean)

        if raw in special_tokens:
            attention[i, 0] = 1.0
            continue

        if not clean:
            previous = tokens[i - 1]
            previous_is_quote = any(c in quotes for c in previous)
            previous_is_terminal = any(c in terminal for c in previous)
            local_mass = 0.87 if previous_is_quote and previous_is_terminal else 0.45
            attention[i, 0] = 1.0 - local_mass
            attention[i, i - 1] += local_mass
            continue

        if is_quote:
            self_mass = 0.81 if is_terminal_quote else 0.64
            attention[i, i] = self_mass
            attention[i, 0] = 1.0 - self_mass
            continue

        sink_mass = strengths.get(pos, 0.80)
        if i == 1:
            sink_mass = 0.74 if pos == "DET" else max(sink_mass, 0.90)

        attention[i, 0] = sink_mass
        residual = 1.0 - sink_mass

        # A weak causal local component accounts for non-sink attention.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local /= local.sum()
        attention[i, 1:i + 1] += residual * local

        # Determiners can retain a stronger link to the preceding predicate.
        if pos == "DET" and i > 1:
            previous_ids = alignment[i - 1]
            if previous_ids and doc[previous_ids[0]].pos_ == "VERB":
                attention[i] *= 0.73
                attention[i, i - 1] += 0.27

        # Standalone sentence boundaries retain mass that otherwise goes to BOS.
        # Leave quote handling, local decay, and all other edges unchanged.
        if (
            clean in {".", "?", "!"}
            and word is not None
            and word.pos_ == "PUNCT"
            and word.is_sent_end
        ):
            transfer = min(0.32, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, i] += transfer

    return "bos_sink_with_terminal_retention", make_row_stochastic(attention)


def prog_L19H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective local routing at nominal and adjectival phrase onsets.
    Transfer sink mass to the preceding phrase cue, preserving the original residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_phrase_onsets", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "PRON": 0.94,
        "AUX": 0.95,
        "PART": 0.95,
        "SCONJ": 0.94,
        "CCONJ": 0.93,
        "ADP": 0.92,
        "DET": 0.89,
        "ADV": 0.90,
        "PUNCT": 0.94,
        "VERB": 0.86,
        "PROPN": 0.82,
        "NOUN": 0.77,
        "ADJ": 0.79,
        "NUM": 0.82,
    }
    special_tokens = set(tokenizer.all_special_tokens)

    for i in range(1, n):
        sids = alignment[i]
        sink = 0.88

        if sids:
            word = doc[sids[0]]
            sink = sink_by_pos.get(word.pos_, sink)
            if word.dep_ in ("aux", "auxpass", "mark", "cc", "expl"):
                sink = max(sink, 0.94)
            if word.is_punct or word.is_space:
                sink = max(sink, 0.94)

            # Later pieces of a lexical word have less reliable sink routing.
            if (
                i > 1
                and alignment[i - 1]
                and sids[0] in alignment[i - 1]
                and word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB")
            ):
                sink -= 0.08

        if tokens[i] in special_tokens:
            sink = 0.97
        if i == 1:
            sink = max(sink, 0.95)

        # Preserve the original residual, including its self-attention weight.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 4.0)
        residual[-1] *= 0.65
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        # Special case: a new lexical word follows a local phrase cue.
        # Only BOS and the preceding token change; continuation pieces retain
        # the default behavior.
        if (
            i > 1
            and sids
            and alignment[i - 1]
            and sids[0] not in alignment[i - 1]
            and tokens[i] not in special_tokens
        ):
            word = doc[sids[0]]
            previous = doc[alignment[i - 1][-1]]
            transfer = 0.0

            if previous.i + 1 == word.i:
                if word.pos_ in ("NOUN", "ADJ"):
                    if previous.dep_ in ("det", "poss") and previous.head == word:
                        transfer = 0.24
                    elif previous.pos_ == "DET" and word.dep_ == "amod":
                        transfer = 0.24
                    elif (
                        previous.pos_ == "ADJ"
                        and previous.dep_ == "amod"
                        and (
                            word.pos_ == "ADJ"
                            or (
                                previous.i > 0
                                and doc[previous.i - 1].pos_ in ("DET", "ADJ")
                            )
                        )
                    ):
                        transfer = 0.30
                    elif (
                        word.pos_ == "NOUN"
                        and previous.pos_ == "ADP"
                        and word.head == previous
                    ):
                        transfer = 0.24

                if (
                    word.pos_ == "ADJ"
                    and previous.pos_ == "AUX"
                    and (
                        previous.head == word
                        or word.dep_ in ("acomp", "attr")
                    )
                ):
                    transfer = 0.34

                if (
                    word.pos_ == "VERB"
                    and word.dep_ in ("amod", "acl")
                    and previous.pos_ == "ADJ"
                    and previous.head == word.head
                ):
                    transfer = 0.28

            transfer = min(transfer, attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, i - 1] += transfer

    return "bos_sink_with_phrase_onsets", attention


def prog_L20H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest on grammatical tokens and punctuation.
    Residual attention follows recency, with weak syntactic and quote anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_linguistic_gating", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    sink_by_pos = {
        "CCONJ": 0.93,
        "SCONJ": 0.85,
        "DET": 0.88,
        "AUX": 0.90,
        "PRON": 0.87,
        "ADP": 0.80,
        "PART": 0.84,
        "PUNCT": 0.86,
        "SPACE": 0.85,
        "ADV": 0.74,
        "ADJ": 0.70,
        "VERB": 0.66,
        "NOUN": 0.65,
        "PROPN": 0.74,
        "NUM": 0.70,
        "INTJ": 0.72,
    }

    attention[0, 0] = 1.0
    quote_anchor = None
    for i in range(1, n):
        clean = tokens[i].lstrip("▁Ġ")
        indices = aligned[i]
        word = doc[indices[0]] if indices else None
        sink = sink_by_pos.get(word.pos_, 0.76) if word is not None else 0.82

        if not clean.strip():
            sink = 0.85
        if clean in ("'", "’"):
            sink = 0.90
        if i == 1:
            sink = max(sink, 0.92)

        is_quote = '"' in clean or "“" in clean or "”" in clean
        opening_quote = is_quote and quote_anchor is None
        if opening_quote:
            sink = 0.52

        weights = np.exp(-(i - np.arange(1, i + 1)) / 5.0)
        weights[-1] *= 0.65

        if word is not None:
            head_indices = inverse[word.head.i]
            eligible = [j for j in head_indices if 0 < j <= i]
            if eligible:
                weights[eligible[-1] - 1] += 0.65

        if quote_anchor is not None and quote_anchor < i:
            weights[quote_anchor - 1] += 2.0
            if word is not None and word.pos_ in ("NOUN", "VERB", "ADJ"):
                sink = max(0.40, sink - 0.12)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        if is_quote:
            quote_anchor = i if opening_quote else None

    return "bos_sink_with_linguistic_gating", make_row_stochastic(attention)


def prog_L20H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local exceptions and a prepositional-complement retrieval path.
    Completed PP nominals can retrieve their preposition and governing predicate.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_pp_retrieval", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        previous_indices = alignment[i - 1]
        previous = doc[previous_indices[-1]] if previous_indices else None

        sink = 0.88
        if word is not None:
            if word.pos_ == "DET":
                sink = 0.95
            elif word.pos_ == "ADP":
                sink = 0.94
            elif word.pos_ == "CCONJ":
                sink = 0.91
            elif word.pos_ == "AUX":
                sink = 0.91
            elif word.pos_ in ("NOUN", "PROPN"):
                sink = 0.87
            elif word.pos_ == "VERB":
                sink = 0.83
            elif word.pos_ in ("ADJ", "ADV"):
                sink = 0.81
            elif word.pos_ == "PRON":
                sink = 0.82
            elif word.pos_ == "PUNCT":
                sink = 0.88

            # Word-internal pieces usually retain the dominant sink behavior.
            if previous_indices and any(k in previous_indices for k in indices):
                sink = max(sink, 0.93)

        if i == 1:
            sink = 0.985

        local = np.zeros(i + 1, dtype=np.float64)
        local[i] = 0.20
        local[i - 1] += 0.60
        for j in range(max(1, i - 5), i):
            local[j] += 0.08 * np.exp(-(i - j) / 2.0)

        if word is not None:
            earlier_heads = [j for j in inverse[word.head.i] if 0 < j < i]
            if earlier_heads:
                local[earlier_heads[-1]] += 0.30

            # A verbal infinitival marker can strongly select the preceding verb.
            if (
                word.pos_ == "PART"
                and word.dep_ in ("aux", "mark")
                and previous is not None
                and previous.pos_ in ("VERB", "AUX")
            ):
                sink = 0.20
                local[:] = 0.0
                local[i - 1] = 1.0

        piece = tokens[i].lstrip("▁Ġ")
        if (
            piece in ("'", "’")
            and previous is not None
            and previous.pos_ == "PRON"
        ):
            sink = 0.07
            local[:] = 0.0
            local[i - 1] = 1.0

        # Only completed PP nominals enter the additional retrieval path.
        # A compound modifier can inherit its nominal head's PP attachment.
        if (
            i > 1
            and word is not None
            and word.pos_ in ("NOUN", "PROPN", "PRON")
            and inverse[word.i]
            and i == inverse[word.i][-1]
        ):
            nominal = word
            if word.dep_ == "compound" and word.head.pos_ in ("NOUN", "PROPN"):
                nominal = word.head

            prep = nominal.head
            if nominal.dep_ == "pobj" and prep.pos_ == "ADP":
                retrieval = np.zeros(i + 1, dtype=np.float64)
                anchor = prep
                for depth in range(5):
                    candidates = [j for j in inverse[anchor.i] if 0 < j < i]
                    if candidates:
                        weight = 0.60 if depth == 0 else 0.40
                        if depth == 1:
                            weight = 1.40
                        retrieval[candidates[-1]] += weight

                    if anchor.pos_ in ("VERB", "AUX"):
                        for child in anchor.children:
                            if child.dep_ in ("dobj", "obj") and child.pos_ == "PRON":
                                candidates = [
                                    j for j in inverse[child.i] if 0 < j < i
                                ]
                                if candidates:
                                    retrieval[candidates[-1]] += 0.75
                        break
                    if anchor.head.i == anchor.i:
                        break
                    anchor = anchor.head

                if retrieval.sum() > 0:
                    governor = prep.head
                    strong_context = (
                        governor.dep_ in ("xcomp", "ccomp")
                        or any(
                            child.dep_ in ("dobj", "obj")
                            and child.pos_ == "PRON"
                            and any(0 < j < i for j in inverse[child.i])
                            for child in governor.children
                        )
                    )
                    sink = min(sink, 0.32 if strong_context else 0.50)
                    local[i - 1] *= 0.15
                    local += retrieval

        matrix[i, :i + 1] = (1.0 - sink) * local / local.sum()
        matrix[i, 0] += sink

    return "bos_sink_with_pp_retrieval", make_row_stochastic(matrix)


def prog_L20H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink, with a clause-onset exception for coordination.
    Coordinators and explicit coordinated subjects retain attention locally.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_clause_onsets", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        sink = 0.91

        if word is not None:
            if word.pos_ in ("DET", "AUX", "ADP"):
                sink = 0.955
            elif word.pos_ == "PUNCT":
                sink = 0.92
            elif word.pos_ in ("VERB", "ADJ", "ADV"):
                sink = 0.89
            elif word.pos_ in ("NOUN", "PROPN"):
                sink = 0.83
            elif word.pos_ == "PRON":
                sink = 0.73
                if word.dep_ in ("poss", "det"):
                    sink = 0.94

        local = np.zeros(i + 1, dtype=np.float64)
        local[i] = 0.45
        if i > 1:
            local[i - 1] += 0.55
        else:
            local[i] += 0.55

        if word is not None:
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j <= i]
                if candidates:
                    local[candidates[-1]] += 0.8

            if word.pos_ == "PRON" and word.dep_ in ("nsubj", "nsubjpass"):
                previous = alignment[i - 1]
                if previous and doc[previous[-1]].pos_ == "VERB":
                    sink = 0.28
                    local[i - 1] += 3.0

        attention[i, 0] = sink
        attention[i, :i + 1] += (1.0 - sink) * local / local.sum()

        # Only move BOS mass for a syntactically identified clause onset.
        # All other rows, and their original local weights, remain unchanged.
        if word is not None:
            anchor = None
            target_sink = None
            self_share = 0.35

            if word.pos_ == "CCONJ" and word.dep_ == "cc":
                if word.head.pos_ in ("VERB", "AUX"):
                    anchor = i
                    target_sink = 0.30
            else:
                subject = word
                if word.dep_ in ("det", "amod", "poss"):
                    subject = word.head

                predicate = subject.head
                if (
                    subject.dep_ in ("nsubj", "nsubjpass")
                    and predicate.dep_ == "conj"
                    and subject.i < predicate.i
                ):
                    coordinators = [
                        c for c in predicate.children
                        if c.pos_ == "CCONJ"
                        and c.dep_ == "cc"
                        and c.i < subject.i
                    ]
                    anchors = [
                        j for c in coordinators
                        for j in inverse[c.i]
                        if 0 < j < i
                    ]
                    if anchors:
                        anchor = max(anchors)
                        if word.i == subject.i:
                            target_sink = 0.10
                        elif word.pos_ == "ADJ":
                            target_sink = 0.55
                        elif word.pos_ == "DET":
                            target_sink = 0.80

            if anchor is not None and target_sink is not None:
                moved = max(0.0, attention[i, 0] - target_sink)
                attention[i, 0] -= moved
                if anchor == i:
                    attention[i, i] += moved * 0.72
                    attention[i, i - 1] += moved * 0.28
                else:
                    attention[i, i] += moved * self_share
                    attention[i, anchor] += moved * (1.0 - self_share)

    return "bos_sink_with_clause_onsets", make_row_stochastic(attention)


def prog_L20H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict BOS-versus-self gating, with local attachment edges for
    infinitival markers and prepositions immediately following content words.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "linguistic_bos_self_local_attachment", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pieces = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            pieces[k].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        indices = alignment[i]
        self_mass = 0.36
        residual = 0.13

        if raw in special_tokens:
            self_mass, residual = 0.05, 0.03
        elif indices:
            # Prefer the largest overlapping word when a model token spans
            # punctuation as well as ordinary text.
            k = max(indices, key=lambda k: len(doc[k].text))
            word = doc[k]
            pos = word.pos_
            dep = word.dep_

            if pos == "DET":
                self_mass = 0.67
            elif pos == "ADP":
                self_mass = 0.57
            elif pos == "PART":
                self_mass = 0.58
            elif pos == "VERB":
                self_mass = 0.53
                if dep in ("xcomp", "ccomp"):
                    self_mass += 0.07
            elif pos == "AUX":
                self_mass = 0.40
            elif pos == "ADJ":
                self_mass = 0.39
                if dep == "acomp":
                    self_mass -= 0.13
            elif pos == "ADV":
                self_mass = 0.29
            elif pos == "PRON":
                self_mass = 0.29
                if dep == "poss" or word.tag_ == "PRP$":
                    self_mass = 0.70
            elif pos == "PROPN":
                self_mass = 0.10
            elif pos == "NOUN":
                self_mass = 0.23
            elif pos in ("CCONJ", "SCONJ"):
                self_mass = 0.31
            elif pos == "NUM":
                self_mass = 0.34
            elif pos == "PUNCT":
                self_mass = 0.43

            if word.ent_type_ and pos in ("NOUN", "PROPN"):
                self_mass *= 0.70

            word_pieces = pieces[k]
            if len(word_pieces) > 1:
                if pos in ("NOUN", "PROPN", "ADJ"):
                    if i == word_pieces[0]:
                        self_mass *= 0.36
                        residual = 0.08
                    else:
                        self_mass *= 0.68
                elif pos == "VERB" and i != word_pieces[0]:
                    self_mass *= 0.83

            if i == 1 and pos in ("PRON", "PROPN", "NOUN", "ADV"):
                self_mass *= 0.30
                residual = 0.04

        # Apostrophes commonly retain strong diagonal attention, whereas
        # standalone quotation marks and whitespace favor the sink.
        stripped = raw.replace("▁", "").replace("Ġ", "").strip()
        if stripped in ("'", "’"):
            self_mass, residual = 0.79, 0.06
        elif stripped in ('"', "“", "”", "«", "»"):
            self_mass, residual = 0.19, 0.08
        elif not stripped:
            self_mass, residual = 0.16, 0.10

        self_mass = float(np.clip(self_mass, 0.04, 0.84))
        attention[i, 0] = 1.0 - self_mass - residual
        attention[i, i] = self_mass

        # A small causal recency component models the non-dominant edges.
        previous = np.arange(i)
        recency = np.exp((previous - (i - 1)) / 2.0)
        attention[i, :i] += residual * recency / recency.sum()

        # Narrow override: these grammatical links need a distinct local edge,
        # rather than a change to the default recency distribution.
        if i > 1 and raw not in special_tokens and stripped and indices:
            k = max(indices, key=lambda k: len(doc[k].text))
            word = doc[k]
            if k > 0 and pieces[k] == [i] and i - 1 in pieces[k - 1]:
                preceding = doc[k - 1]
                if (
                    word.pos_ == "PART"
                    and word.tag_ == "TO"
                    and word.dep_ in ("aux", "mark")
                    and preceding.pos_ == "VERB"
                ):
                    moved = min(0.30, attention[i, i])
                    attention[i, i] -= moved
                    attention[i, i - 1] += 0.60 * moved
                    attention[i, 0] += 0.40 * moved
                elif (
                    word.pos_ == "ADP"
                    and word.dep_ == "prep"
                    and preceding.pos_ in ("VERB", "NOUN", "PROPN", "ADJ")
                ):
                    moved = min(0.24, attention[i, 0])
                    attention[i, 0] -= moved
                    attention[i, i - 1] += moved

    return "linguistic_bos_self_local_attachment", make_row_stochastic(attention)


def prog_L20H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with token-form and syntactic modulation.
    Residual attention favors self, recent tokens, and local word boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pieces = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            pieces[k].append(i)

    attention[0, 0] = 1.0
    quote_count = 0

    for i in range(1, n):
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ")
        clean = surface.strip()
        indices = aligned[i]
        word = doc[indices[0]] if indices else None

        sink = 0.66
        if word is not None:
            sink = {
                "VERB": 0.79,
                "AUX": 0.51,
                "NOUN": 0.62,
                "PROPN": 0.77,
                "PRON": 0.68,
                "DET": 0.68,
                "ADP": 0.74,
                "PART": 0.61,
                "ADJ": 0.64,
                "ADV": 0.72,
                "CCONJ": 0.69,
                "SCONJ": 0.76,
                "PUNCT": 0.52,
            }.get(word.pos_, 0.66)

            if word.dep_ in ("ROOT", "ccomp", "xcomp", "advcl"):
                sink += 0.03

            word_pieces = pieces[word.i]
            if len(word_pieces) > 1 and word.pos_ not in ("PUNCT", "PART"):
                if i == word_pieces[0]:
                    sink = max(sink, 0.93)
                else:
                    sink = 0.70 * sink + 0.30 * 0.68

        if i == 1:
            sink = 0.93
            if word is not None:
                if word.pos_ == "DET":
                    sink = 0.73
                elif word.pos_ in ("PRON", "PROPN"):
                    sink = 0.96
                elif word.pos_ == "ADP":
                    sink = 0.88

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = 0.36
        if i > 1:
            distances = np.arange(i - 1, 0, -1, dtype=np.float64)
            residual[1:i] = 0.64 * np.exp(-distances / 2.8)

        if word is not None:
            preceding_pieces = [j for j in pieces[word.i] if 0 < j < i]
            if preceding_pieces:
                residual[preceding_pieces[-1]] += 0.35

            head_pieces = [
                j for j in pieces[word.head.i] if 0 < j < i
            ]
            if head_pieces and word.head.i != word.i:
                residual[head_pieces[-1]] += 0.12

        if clean in ('"', "“", "”", "«", "»"):
            quote_count += 1
            if quote_count == 1:
                sink = 0.30
                residual[:] = 0.0
                residual[i] = 1.0
            else:
                sink = 0.55
                residual[i] += 0.45
        elif not clean:
            sink = 0.32
            residual[:] = 0.0
            residual[max(1, i - 1)] = 1.0
        elif clean in ("'", "’") and i > 1:
            sink = min(sink, 0.48)
            residual[i - 1] += 1.0

        sink = float(np.clip(sink, 0.18, 0.98))
        residual[0] = 0.0
        total = residual.sum()
        if total <= 0:
            residual[i] = 1.0
            total = 1.0

        attention[i, :i + 1] = (1.0 - sink) * residual / total
        attention[i, 0] = sink

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L20H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker local syntactic attention.
    Copular auxiliaries favor self; objects sometimes favor preceding governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        if tokens[i] not in tokenizer.all_special_tokens:
            for k in indices:
                inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.88
        if pos in ("ADP", "DET", "PUNCT", "SCONJ"):
            sink = 0.94
        elif pos == "CCONJ":
            sink = 0.90
        elif pos == "VERB":
            sink = 0.88
        elif pos in ("NOUN", "PROPN"):
            sink = 0.79
        elif pos in ("ADJ", "ADV", "NUM"):
            sink = 0.81
        elif pos == "PRON":
            sink = 0.76
        elif pos == "PART":
            sink = 0.73
        elif pos == "AUX":
            sink = 0.60

        if dep in ("poss", "nmod:poss"):
            sink = 0.77
        if word is not None and word.is_space:
            sink = 0.90

        copular = (
            word is not None
            and pos == "AUX"
            and (
                dep in ("cop", "ROOT")
                or any(c.dep_ in ("acomp", "attr") for c in word.children)
            )
        )
        if copular:
            sink = 0.32

        # The first ordinary token has an especially strong sink preference.
        if i == 1:
            sink = 0.975 if pos == "PRON" else 0.945

        local = np.zeros(i + 1, dtype=np.float64)
        distances = i - np.arange(1, i + 1)
        local[1:] = 0.12 * np.exp(-distances / 3.0)
        local[i] += 0.35
        local[i - 1] += 0.20 if i > 1 else 0.0

        if copular:
            local[i] += 4.0

        if word is not None:
            head_positions = [
                j for j in inverse[word.head.i] if 0 < j <= i
            ]
            if word.head.i != word.i and head_positions:
                governor = head_positions[-1]
                strength = 0.45
                if dep in ("dobj", "obj", "attr", "acomp", "oprd"):
                    strength = 1.25
                    if governor == i - 1:
                        sink = min(sink, 0.60)
                        strength = 2.5
                local[governor] += strength

            # Retain a small within-word component for split model tokens.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                local[earlier_pieces[-1]] += 0.30

        local[0] = 0.0
        local /= local.sum()
        attention[i, :i + 1] = (1.0 - sink) * local
        attention[i, 0] = sink

    return "bos_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L20H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink/object-predicate head, with local routing inside prepositional phrases.
    Possessive determiners do not inherit their noun's object-to-predicate route.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_prepositional_routing", matrix

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    special = set(tokenizer.all_special_tokens)

    word_pieces = []
    for indices in inverse:
        word_pieces.append([
            k for k in indices
            if 0 <= k < n and tokens[k] not in special
        ])

    for i, piece in enumerate(tokens):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        matrix[i, 0] = 0.90
        matrix[i, i] = 0.07
        matrix[i, i - 1] += 0.03

        if piece in special:
            matrix[i] = 0.0
            matrix[i, 0] = 1.0
            continue

        clean = piece.lstrip("▁Ġ")
        if not clean.strip():
            matrix[i] = 0.0
            matrix[i, 0] = 0.32
            matrix[i, i - 1] += 0.58
            matrix[i, i] += 0.10
            continue

        candidates = forward[i]
        if not candidates:
            continue

        # Prefer a lexical overlap if offsets also include adjacent punctuation.
        si = candidates[-1]
        for candidate in candidates:
            if doc[candidate].pos_ != "PUNCT":
                si = candidate
                break
        word = doc[si]
        pieces = word_pieces[si]
        final_piece = bool(pieces) and i == pieces[-1]

        if word.pos_ == "PUNCT":
            if clean and all(c in "'’" for c in clean):
                sink, own = 0.87, 0.10
            else:
                sink, own = 0.34, 0.59
            matrix[i] = 0.0
            matrix[i, 0] = sink
            matrix[i, i] += own
            matrix[i, i - 1] += 1.0 - sink - own
            continue

        # Early subword pieces generally behave as attention-sink queries.
        if not final_piece:
            matrix[i] = 0.0
            matrix[i, 0] = 0.96
            matrix[i, i] = 0.025
            matrix[i, i - 1] += 0.015
            continue

        if word.pos_ in ("DET", "AUX", "PART"):
            sink, own = 0.94, 0.04
        elif word.pos_ in ("ADP", "CCONJ", "SCONJ"):
            sink, own = 0.85, 0.10
        elif word.pos_ == "VERB":
            sink, own = 0.62, 0.33
        elif word.pos_ in ("ADJ", "ADV"):
            sink, own = 0.84, 0.12
        elif word.pos_ == "PRON":
            sink, own = 0.91, 0.06
        else:
            sink, own = 0.83, 0.12

        matrix[i] = 0.0
        matrix[i, 0] = sink
        matrix[i, i] += own
        matrix[i, i - 1] += 1.0 - sink - own

        if word.pos_ not in ("NOUN", "PROPN", "PRON", "NUM"):
            continue

        # Possessives are modifiers, not independent predicate arguments.
        if word.dep_ in ("poss", "det"):
            continue

        # Trace nominal, possessive, and prepositional chains to a predicate.
        current = word
        predicate = None
        role = ""
        prepositional = False
        for _ in range(8):
            parent = current.head
            if parent.i == current.i:
                break
            if parent.pos_ == "VERB":
                predicate = parent
                role = current.dep_
                break
            if parent.pos_ == "ADP":
                prepositional = True
            if parent.pos_ not in ("NOUN", "PROPN", "PRON", "ADP", "NUM"):
                break
            current = parent

        if predicate is None:
            continue

        object_role = role in (
            "dobj", "obj", "iobj", "dative", "attr", "oprd", "obl", "prep"
        )
        inverted_subject = (
            role in ("nsubj", "nsubjpass", "csubj")
            and predicate.i < word.i
        )
        if not object_role and not inverted_subject:
            continue

        anchors = [k for k in word_pieces[predicate.i] if 0 < k < i]
        if not anchors:
            continue
        target = anchors[-1]

        strength = 0.84
        if prepositional or role in ("prep", "obl"):
            strength = 0.71
        if inverted_subject:
            strength = 0.79
        if word.pos_ == "PRON":
            strength *= 0.79
        if word.pos_ == "PROPN" or word.ent_type_:
            strength = min(0.91, strength + 0.04)
        if i - target > 20:
            strength *= 0.85

        matrix[i] = 0.0
        matrix[i, target] = strength
        matrix[i, 0] += 0.85 * (1.0 - strength)
        matrix[i, i] += 0.10 * (1.0 - strength)
        matrix[i, i - 1] += 0.05 * (1.0 - strength)

    # Local PP exception: redirect only sink/predicate mass. Existing self
    # and previous-piece contributions remain intact, including on subwords.
    for word in doc:
        if word.pos_ not in ("NOUN", "PROPN", "NUM"):
            continue

        current = word
        for _ in range(8):
            if current.dep_ != "conj" or current.head.i == current.i:
                break
            current = current.head

        prep = current.head
        if prep.pos_ != "ADP" or current.dep_ not in ("pobj", "obj", "obl"):
            continue

        governor = prep.head
        for i in word_pieces[word.i]:
            if i == 0:
                continue
            prep_anchors = [k for k in word_pieces[prep.i] if 0 < k < i]
            if not prep_anchors:
                continue

            # Collect only existing nonlocal predicate contributions.
            sources = {0}
            ancestor = prep
            for _ in range(8):
                parent = ancestor.head
                if parent.i == ancestor.i:
                    break
                if parent.pos_ == "VERB":
                    anchors = [
                        k for k in word_pieces[parent.i]
                        if 0 < k < i - 1
                    ]
                    if anchors:
                        sources.add(anchors[-1])
                    break
                if parent.pos_ not in ("NOUN", "PROPN", "PRON", "ADP", "NUM"):
                    break
                ancestor = parent

            mass = sum(matrix[i, k] for k in sources)
            for k in sources:
                matrix[i, k] = 0.0

            governor_anchors = [
                k for k in word_pieces[governor.i] if 0 < k < i
            ]
            if (
                governor.pos_ in ("NOUN", "PROPN", "ADJ")
                and governor_anchors
            ):
                matrix[i, 0] += 0.10 * mass
                matrix[i, prep_anchors[-1]] += 0.55 * mass
                matrix[i, governor_anchors[-1]] += 0.35 * mass
            else:
                # Retain a smaller predicate component for verb-attached PPs.
                predicate_sources = [k for k in sources if k != 0]
                matrix[i, prep_anchors[-1]] += 0.55 * mass
                if predicate_sources:
                    matrix[i, predicate_sources[-1]] += 0.20 * mass
                    matrix[i, 0] += 0.25 * mass
                else:
                    matrix[i, 0] += 0.45 * mass

    return (
        "bos_sink_with_local_prepositional_routing",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L20H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mild POS-dependent strength.
    Non-BOS attention is weak and diffuse, with a modest recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_pos_modulated", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.93
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("DET", "AUX", "CCONJ", "SCONJ"):
                sink_mass = 0.965
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass = 0.89
            elif word.pos_ in ("ADJ", "ADP", "PRON"):
                sink_mass = 0.91
            elif word.pos_ == "PUNCT":
                sink_mass = 0.85

            if word.dep_ in ("ROOT", "conj") and word.pos_ == "VERB":
                sink_mass = 0.95

            if word.is_punct and word.is_sent_end:
                sink_mass = 0.95

        if i == 1:
            sink_mass = 0.974

        positions = np.arange(1, i + 1)
        residual = 0.6 / i + 0.4 * (
            np.exp(-(i - positions) / 6.0)
            / np.exp(-(i - positions) / 6.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_pos_modulated", make_row_stochastic(attention)


def prog_L20H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink: nearly all attention goes to the first token.
    Sink strength gradually decreases with position, leaving diffuse causal attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.995 - 0.17 * (1.0 - np.exp(-(i - 1) / 40.0))

        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 5.0)
        recent /= recent.sum()
        residual = 0.85 / i + 0.15 * recent

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L20H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with targeted exceptions for fragmented nominal onsets and
    short-lived attention to the first noun in an enumerated list.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_nominal_exceptions", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = float(np.clip(0.935 - 0.0012 * i, 0.80, 0.935))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        distances = i - positions
        residual = 0.75 / i + 0.25 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    doc = spacy_parse(sentence)
    word_tokens = align_spacy_to_tokens(sentence, tokens, tokenizer)

    # A one-character nominal onset is an unusually strong local key.
    # Transfer only BOS mass; all unrelated entries retain their baseline values.
    for word in doc:
        if word.pos_ not in ("NOUN", "PROPN"):
            continue
        pieces = [i for i in word_tokens[word.i] if 0 < i < n]
        if len(pieces) < 2:
            continue
        onset = tokens[pieces[0]].lstrip("▁Ġ")
        if len(onset) != 1 or not onset.isalpha():
            continue

        for k, i in enumerate(pieces):
            extra = (0.52 if word.pos_ == "PROPN" else 0.64) if k == 0 else 0.09
            extra = min(extra, max(0.0, attention[i, 0] - 0.15))
            attention[i, 0] -= extra
            attention[i, i] += extra

    # In a multi-item nominal enumeration, retain its first noun as an anchor.
    for word in doc:
        if word.pos_ != "NOUN" or word.dep_ == "conj":
            continue
        conjuncts = [w for w in word.conjuncts if w.pos_ in ("NOUN", "PROPN")]
        if len(conjuncts) < 2:
            continue
        pieces = [i for i in word_tokens[word.i] if 0 < i < n]
        if not pieces:
            continue

        anchor = pieces[-1]
        last = max(w.i for w in conjuncts)
        for i in range(anchor, min(n, anchor + 8)):
            distance = i - anchor
            if distance == 0:
                extra = 0.15
            else:
                aligned = [
                    w for w in doc[word.i:last + 1]
                    if i in word_tokens[w.i]
                ]
                if not aligned:
                    continue
                nominal = any(w.pos_ in ("NOUN", "PROPN") for w in aligned)
                extra = (0.06 if nominal else 0.39) * np.exp(
                    -max(0, distance - 1) / 8.0
                )
            extra = min(extra, max(0.0, attention[i, 0] - 0.20))
            attention[i, 0] -= extra
            attention[i, anchor] += extra

    return "bos_sink_with_nominal_exceptions", attention


def prog_L20H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradually increasing causal background mass.
    Residual attention is diffuse, with a weak preference for recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        leakage_odds = 0.012 + 0.0015 * i + 0.00005 * i * i
        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        background = 0.7 + 0.3 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L20H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with token-dependent gating.
    Residual attention favors self, nearby context, and available clause subjects.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_subject_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(aligned):
        for wi in word_ids:
            inverse[wi].append(ti)

    sink_by_pos = {
        "PROPN": 0.79,
        "NOUN": 0.67,
        "DET": 0.74,
        "ADJ": 0.69,
        "ADP": 0.68,
        "VERB": 0.57,
        "AUX": 0.39,
        "PRON": 0.38,
        "ADV": 0.47,
        "CCONJ": 0.47,
        "SCONJ": 0.54,
        "PART": 0.56,
        "PUNCT": 0.71,
        "SPACE": 0.65,
        "NUM": 0.68,
        "INTJ": 0.72,
        "X": 0.73,
    }
    subject_deps = ("nsubj", "nsubjpass", "csubj", "csubjpass")

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[aligned[i][0]] if aligned[i] else None
        sink = sink_by_pos.get(word.pos_, 0.67) if word is not None else 0.69

        # The opening few positions have an especially strong sink prior.
        sink += 0.23 * np.exp(-(i - 1) / 4.0)
        if i == 1:
            sink = 0.96

        if word is not None:
            pieces = inverse[word.i]
            if len(pieces) > 1:
                # Fragmented lexical items often retain strong BOS attention.
                sink += 0.12 if i == pieces[0] else 0.06
            if word.ent_type_:
                sink += 0.04

        if tokens[i].strip() in ("'", "’"):
            sink = max(sink, 0.90)
        sink = float(np.clip(sink, 0.25, 0.985))

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] += 0.45
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        residual[1:] += 0.25 * local / local.sum()

        subject_positions = []
        if word is not None:
            # Search outward through the syntactic ancestry for a causal subject.
            node = word
            for _ in range(8):
                for child in node.children:
                    if child.dep_ in subject_deps:
                        candidates = [j for j in inverse[child.i] if 0 < j <= i]
                        if candidates:
                            subject_positions.append(candidates[-1])
                if subject_positions or node.head.i == node.i:
                    break
                node = node.head

        if subject_positions:
            for j in subject_positions:
                residual[j] += 0.30 / len(subject_positions)
        else:
            residual[i] += 0.30

        attention[i, 0] = sink
        attention[i, :i + 1] += (1.0 - sink) * residual / residual.sum()

    return "bos_sink_with_subject_residual", make_row_stochastic(attention)


def prog_L20H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakening with distance from the beginning.
    Residual attention follows recency and weak syntactic/nominal anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        sink_mass = 0.56 + 0.42 * np.exp(-(i - 1) / 24.0)
        if word is not None:
            if word.pos_ in ("DET", "ADP", "PART"):
                sink_mass += 0.025
            elif word.pos_ in ("NOUN", "PROPN"):
                sink_mass -= 0.025
            elif word.is_punct:
                sink_mass -= 0.015
        sink_mass = float(np.clip(sink_mass, 0.50, 0.985))

        positions = np.arange(1, i + 1)
        residual = 0.20 + np.exp(-(i - positions) / 5.0)

        if word is not None:
            for target in inverse[word.head.i]:
                if 0 < target <= i and target != i:
                    residual[target - 1] += 1.2

            # Early nominal subjects can remain useful discourse anchors.
            for wi in range(word.i):
                earlier = doc[wi]
                if (
                    earlier.pos_ in ("NOUN", "PROPN")
                    and earlier.dep_ in ("nsubj", "nsubjpass", "csubj")
                ):
                    for target in inverse[wi]:
                        if 0 < target < i:
                            residual[target - 1] += (
                                0.45 / (1.0 + wi / 12.0)
                            )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_syntactic_residual", attention


def prog_L20H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly weakening positional dominance.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_mild_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.99 - 0.12 * (1.0 - np.exp(-(i - 1) / 32.0))
        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 6.0)
        residual = 0.5 / i + 0.5 * recent / recent.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_mild_decay", attention


def prog_L20H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a possessive-phrase exception: possessive markers retain
    local attention, and possessed nouns attend back to their possessive edge."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_possessive_edges", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "PRON": 0.89,
        "AUX": 0.90,
        "VERB": 0.80,
        "CCONJ": 0.86,
        "SCONJ": 0.69,
        "ADV": 0.78,
        "PROPN": 0.83,
        "NOUN": 0.74,
        "ADJ": 0.65,
        "PART": 0.73,
        "DET": 0.53,
        "ADP": 0.49,
        "NUM": 0.64,
        "PUNCT": 0.70,
        "SPACE": 0.53,
        "INTJ": 0.76,
        "X": 0.72,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        mapped = alignment[i]
        word = doc[mapped[-1]] if mapped else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        sink = sink_by_pos.get(pos, 0.73)

        if dep in ("nsubj", "nsubjpass", "csubj"):
            sink += 0.045
        elif dep in ("poss", "amod", "det", "pobj"):
            sink -= 0.035

        if word is not None and word.ent_type_:
            sink += 0.025

        # Continuation pieces retain their word's linguistic role.
        if mapped and alignment[i - 1]:
            if mapped[-1] in alignment[i - 1]:
                sink += 0.025

        if tokens[i].isspace():
            sink = 0.53

        # The earliest position has an especially reliable sink preference.
        if i == 1:
            sink = 0.94 if pos in ("PRON", "PROPN") else 0.90

        sink = float(np.clip(sink, 0.30, 0.97))
        attention[i, 0] = sink
        remaining = 1.0 - sink

        local = np.zeros(i + 1, dtype=np.float64)
        local[i] = 0.66
        if i > 1:
            local[i - 1] += 0.24
            distances = i - np.arange(1, i + 1)
            decay = np.exp(-distances / 2.5)
            local[1:] += 0.10 * decay / decay.sum()

            # Articles and modifiers sometimes retain the preceding phrase edge.
            previous = alignment[i - 1]
            previous_pos = doc[previous[-1]].pos_ if previous else ""
            if pos == "DET" and previous_pos == "ADP":
                local[i] *= 0.45
                local[i - 1] += 0.45
        else:
            local[i] = 1.0

        local /= local.sum()
        attention[i, :i + 1] += remaining * local

        # Narrow exception: redistribute BOS mass only at possessive edges.
        if i > 1 and word is not None and alignment[i - 1]:
            previous_word = doc[alignment[i - 1][-1]]
            if pos in ("PRON", "DET") and dep == "poss":
                moved = 0.72 * attention[i, 0]
                attention[i, 0] -= moved
                attention[i, i] += 0.50 * moved
                attention[i, i - 1] += 0.50 * moved
            elif pos in ("NOUN", "PROPN") and previous_word.i != word.i:
                direct_possessor = (
                    previous_word.dep_ == "poss"
                    and previous_word.head.i == word.i
                )
                possessive_clitic = (
                    previous_word.dep_ == "case"
                    and previous_word.head.dep_ == "poss"
                    and previous_word.head.head.i == word.i
                )
                if direct_possessor or possessive_clitic:
                    fraction = 0.65 if possessive_clitic else 0.25
                    moved = fraction * attention[i, 0]
                    attention[i, 0] -= moved
                    attention[i, i - 1] += moved

    return "bos_sink_with_possessive_edges", make_row_stochastic(attention)


def prog_L20H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest near the start and on fragmented content words.
    Residual attention is mostly local, with a weak causal syntactic component.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_pieces = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            if i > 0:
                word_pieces[word_id].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        word_ids = alignment[i]
        word = None
        if word_ids:
            word = doc[word_ids[0]]

        # The sink remains dominant even well beyond the opening phrase.
        sink = 0.52 + 0.34 * np.exp(-(i - 1) / 5.0)
        if word is not None:
            pos = word.pos_
            if pos in ("NOUN", "PROPN"):
                sink += 0.13
            elif pos == "ADJ":
                sink += 0.08
            elif pos in ("VERB", "AUX"):
                sink += 0.015
            elif pos in ("PRON", "DET"):
                sink += 0.055 * np.exp(-(i - 1) / 8.0)

            pieces = word_pieces[word.i]
            if len(pieces) > 1 and pos in ("NOUN", "PROPN", "ADJ", "VERB"):
                if i == pieces[0]:
                    sink += 0.25
                elif i < pieces[-1]:
                    sink += 0.22
                else:
                    sink += 0.06

        if clean and all(c in "'’" for c in clean):
            sink += 0.30
        if not clean.strip():
            sink += 0.06
        if i == 1:
            sink = max(sink, 0.97)

        sink = float(np.clip(sink, 0.35, 0.99))
        attention[i, 0] = sink

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = 0.55
        for j in range(max(1, i - 6), i):
            residual[j] += 0.25 * np.exp(-(i - j - 1) / 1.8)

        # Coordination and punctuation can preserve a preceding content anchor.
        if word is not None:
            head_indices = word_pieces[word.head.i]
            causal_heads = [j for j in head_indices if 0 < j <= i]
            if causal_heads and word.head.i != word.i:
                strength = 0.15
                if word.dep_ in ("conj", "cc", "punct"):
                    strength = 0.45
                residual[causal_heads[0]] += strength

        residual /= residual.sum()
        attention[i, :i + 1] += (1.0 - sink) * residual

    return "bos_sink_with_local_residual", attention


def prog_L20H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with small, position-growing leakage across the causal prefix."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_prefix_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_weight = 1.0 / (1.0 + 0.008 + 0.0025 * (i - 1))
        attention[i, 0] = sink_weight
        attention[i, 1:i + 1] = (1.0 - sink_weight) / i

    return "bos_sink_with_prefix_leakage", attention


def prog_L20H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with stronger predecessor attention for indefinite
    determiners and prepositions immediately following participial predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV"}
    function_pos = {"DET", "ADP", "AUX", "PART", "SCONJ"}

    for i in range(1, n):
        current = [doc[k] for k in alignment[i] if k < len(doc)]
        pos = current[0].pos_ if current else ""
        clean = tokens[i].lstrip("▁Ġ")

        if pos in content_pos:
            sink_mass = 0.960
        elif pos in function_pos:
            sink_mass = 0.885
        elif pos == "PRON":
            sink_mass = 0.925
        elif pos == "CCONJ":
            sink_mass = 0.950
        elif pos == "PUNCT":
            sink_mass = 0.890 if clean == "," else 0.800
        else:
            sink_mass = 0.940

        # The clearest non-sink example is an apostrophe following a pronoun.
        previous = [doc[k] for k in alignment[i - 1] if k < len(doc)]
        contraction_mark = (
            clean in ("'", "’")
            and previous
            and previous[-1].pos_ == "PRON"
        )
        if contraction_mark:
            attention[i, 0] = 0.025
            attention[i, i - 1] += 0.970
            attention[i, i] += 0.005
            continue

        # Keep the small non-sink component causal and biased toward recency.
        positions = np.arange(1, i + 1)
        local_weights = np.exp(-0.45 * (i - positions))
        local_weights[-1] *= 0.65
        local_weights /= local_weights.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * local_weights

        # Redirect only BOS mass; preserve self-attention and the decay tail.
        if i > 1 and current and previous and current[0].i != previous[-1].i:
            target_previous = 0.0
            if pos == "DET" and "Ind" in current[0].morph.get("Definite"):
                if previous[-1].pos_ == "ADP":
                    target_previous = 0.58
                elif previous[-1].pos_ == "VERB":
                    target_previous = 0.20
            elif (
                pos == "ADP"
                and previous[-1].pos_ in {"VERB", "ADJ"}
                and (
                    "Part" in previous[-1].morph.get("VerbForm")
                    or previous[-1].tag_ == "VBN"
                )
            ):
                target_previous = 0.38

            transfer = min(
                attention[i, 0],
                max(0.0, target_previous - attention[i, i - 1]),
            )
            attention[i, 0] -= transfer
            attention[i, i - 1] += transfer

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L20H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for subjects and grammatical scaffolding.
    Residual attention favors self and nearby, already-seen syntactic governors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if k < len(doc):
                inverse[k].append(i)

    special_tokens = tokenizer.all_special_tokens
    attention[0, 0] = 1.0

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ")
        indices = alignment[i]
        word = None
        if indices:
            # Prefer a lexical token when a model piece overlaps punctuation too.
            k = max(indices, key=lambda k: (
                not doc[k].is_punct, not doc[k].is_space, len(doc[k].text)
            ))
            word = doc[k]

        sink = 0.62
        self_weight = 0.75
        head_weight = 0.15
        previous_weight = 0.10
        governor = None

        if tokens[i] in special_tokens:
            sink = 0.95
        elif not text.strip():
            sink = 0.30
            self_weight, head_weight, previous_weight = 0.10, 0.0, 0.90
        elif word is not None:
            pos, dep = word.pos_, word.dep_
            subject = dep in ("nsubj", "nsubjpass", "csubj", "csubjpass")
            if subject:
                sink = 0.93 if pos == "PRON" else 0.87
            elif pos == "DET":
                sink = 0.87
            elif pos == "AUX":
                sink = 0.85
            elif pos == "PART":
                sink = 0.84
            elif pos == "PRON":
                sink = 0.77
            elif pos == "ADP":
                sink = 0.72
            elif pos == "PROPN":
                sink = 0.78
            elif pos == "NOUN":
                sink = 0.61
            elif pos == "ADJ":
                sink = 0.65
            elif pos == "VERB":
                sink = 0.53
            elif pos in ("ADV", "CCONJ", "SCONJ"):
                sink = 0.63
            elif pos == "PUNCT":
                sink = 0.59
                if text.strip() in ('"', "'", "“", "‘"):
                    sink = 0.47

            if dep in ("dobj", "obj", "iobj", "dative"):
                sink = min(sink, 0.49)
                self_weight, head_weight, previous_weight = 0.30, 0.62, 0.08

            candidates = [
                j for j in inverse[word.head.i]
                if 0 < j < i and j not in inverse[word.i]
            ]
            if candidates:
                governor = max(candidates)

            # Continuation pieces usually retain the sink preference rather
            # than obligatorily attending to the beginning of their word.
            if inverse[word.i] and i > min(inverse[word.i]):
                sink = max(sink, 0.78)

        if i == 1:
            sink = 0.96

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] += self_weight
        residual[i - 1] += previous_weight
        if governor is not None:
            residual[governor] += head_weight
        else:
            residual[i] += head_weight

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] += sink

    return "bos_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L20H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with localized attention at infinitival and coordination boundaries.
    Sentence-final periods additionally shift sink mass to themselves.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_boundary_exceptions", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "DET": 0.95,
        "ADP": 0.93,
        "ADJ": 0.91,
        "ADV": 0.88,
        "AUX": 0.91,
        "VERB": 0.88,
        "NOUN": 0.86,
        "PROPN": 0.88,
        "NUM": 0.89,
        "PRON": 0.58,
        "CCONJ": 0.68,
        "SCONJ": 0.77,
        "PART": 0.79,
        "PUNCT": 0.65,
        "SPACE": 0.62,
    }

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        sink = sink_by_pos.get(word.pos_, 0.87) if word is not None else 0.86

        if word is not None:
            if word.dep_ in ("poss", "det"):
                sink = 0.95
            elif word.pos_ == "PRON":
                sink = 0.38 if word.dep_ in ("nsubj", "nsubjpass") else 0.61
            elif word.dep_ in ("aux", "auxpass", "cop"):
                sink = 0.92

        if not clean:
            sink = 0.62
        elif all(c in ".,;:" for c in clean):
            sink = 0.78
        elif all(not c.isalnum() and not c.isspace() for c in clean):
            sink = 0.35

        # Standalone contraction apostrophes often point to their lexical stem.
        apostrophe = clean in ("'", "’")
        possessive = word is not None and word.dep_ in ("case", "poss")
        if apostrophe and not possessive:
            attention[i, 0] = 0.13
            attention[i, i - 1] += 0.80
            attention[i, i] += 0.07
            continue
        elif apostrophe:
            sink = 0.85

        # The first content position consistently uses the beginning-of-sequence sink.
        if i == 1:
            sink = 0.95

        # Keep a small causal background rather than predicting completely sparse rows.
        background = 0.015
        previous = 0.015 if i > 1 else 0.0
        attention[i, :i + 1] = background / (i + 1)
        attention[i, 0] += sink
        attention[i, i] += 1.0 - sink - background - previous
        if i > 1:
            attention[i, i - 1] += previous

        # Exceptions only redistribute BOS mass; all other rows remain unchanged.
        if i > 1:
            prev_indices = alignment[i - 1]
            prev_word = doc[prev_indices[0]] if prev_indices else None
            first_piece = (
                word is not None
                and (prev_word is None or prev_word.i != word.i)
            )
            self_shift = 0.0
            previous_shift = 0.0

            if clean == "." and i == n - 1:
                self_shift = 0.40
            elif first_piece:
                if (
                    word.tag_ == "TO"
                    and word.pos_ == "PART"
                    and word.head.pos_ == "VERB"
                ):
                    self_shift, previous_shift = 0.37, 0.30
                elif (
                    word.pos_ == "VERB"
                    and prev_word is not None
                    and prev_word.tag_ == "TO"
                    and prev_word.head.i == word.i
                ):
                    self_shift, previous_shift = 0.20, 0.30
                elif word.pos_ == "CCONJ" and word.dep_ == "cc":
                    self_shift = 0.36
                elif (
                    word.pos_ in ("VERB", "ADV")
                    and prev_word is not None
                    and prev_word.pos_ == "CCONJ"
                    and prev_word.dep_ == "cc"
                ):
                    self_shift, previous_shift = 0.17, 0.52

            transfer = self_shift + previous_shift
            if transfer > 0.0:
                scale = min(1.0, attention[i, 0] / transfer)
                attention[i, 0] -= scale * transfer
                attention[i, i] += scale * self_shift
                attention[i, i - 1] += scale * previous_shift

    return "bos_sink_with_boundary_exceptions", make_row_stochastic(attention)


def prog_L20H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local exception for elaborated non-subject noun phrases.
    Possessors and nominal modifiers redirect sink mass to nearby phrase tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_nominal_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    pos_sink = {
        "PRON": 0.94,
        "AUX": 0.93,
        "PART": 0.90,
        "VERB": 0.85,
        "ADV": 0.85,
        "CCONJ": 0.86,
        "SCONJ": 0.85,
        "PROPN": 0.86,
        "PUNCT": 0.82,
        "ADP": 0.69,
        "DET": 0.64,
        "NOUN": 0.68,
        "ADJ": 0.70,
        "NUM": 0.69,
        "SPACE": 0.72,
    }

    # Restrict the exception to internally modified, non-subject nominals.
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if ti > 0:
                word_tokens[wi].append(ti)

    nominal_gate = {}
    for head in doc:
        if head.pos_ not in ("NOUN", "PROPN"):
            continue
        if head.dep_ in ("nsubj", "nsubjpass", "csubj", "csubjpass"):
            continue
        modifiers = [
            c for c in head.children
            if c.i < head.i and c.dep_ in ("det", "poss", "amod", "compound")
        ]
        determiners = [c for c in modifiers if c.dep_ == "det"]
        quantifier = any(
            c.morph.get("PronType") and "Art" not in c.morph.get("PronType")
            for c in determiners
        )
        elaborate = (
            any(c.dep_ in ("poss", "compound") for c in modifiers)
            or (determiners and any(c.dep_ == "amod" for c in modifiers))
            or (head.dep_ == "pobj" and determiners)
            or quantifier
        )
        if not elaborate:
            continue
        anchors = [
            ti for c in modifiers for ti in word_tokens[c.i]
            if c.dep_ != "det" or not any(
                m.dep_ in ("poss", "amod", "compound") for m in modifiers
            )
        ]
        if not anchors:
            continue
        anchor = min(anchors)
        for word in [head] + modifiers:
            target = 0.48
            if word.dep_ == "poss":
                target = 0.30
            elif word.dep_ == "amod":
                target = 0.32
            elif word.dep_ == "det":
                target = 0.38 if quantifier else 0.44
            nominal_gate[word.i] = (target, anchor)

    for i in range(1, n):
        sink = 0.78
        if alignment[i]:
            word = doc[alignment[i][-1]]
            sink = pos_sink.get(word.pos_, 0.78)

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                sink += 0.025
            elif word.dep_ in ("aux", "auxpass", "neg", "mark"):
                sink += 0.025
            elif word.dep_ in ("amod", "compound", "poss"):
                sink -= 0.04

            if word.ent_type_ == "PERSON":
                sink = max(sink, 0.89)

            if i == 1:
                if word.pos_ == "PRON":
                    sink = 0.984
                elif word.pos_ == "PROPN":
                    sink = 0.984
                elif word.pos_ == "DET":
                    sink = 0.862
                else:
                    sink = max(sink, 0.88)
        elif tokens[i].isspace():
            sink = 0.72

        sink = float(np.clip(sink, 0.50, 0.985))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-distances / 5.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Preserve the original row except for a localized transfer from BOS.
        if i > 1 and alignment[i]:
            wi = alignment[i][-1]
            if wi in nominal_gate:
                target, anchor = nominal_gate[wi]
                if anchor <= i:
                    moved = max(0.0, sink - target)
                    attention[i, 0] -= moved
                    if doc[wi].dep_ == "amod" and anchor == i:
                        attention[i, i] += 0.80 * moved
                        attention[i, i - 1] += 0.20 * moved
                    else:
                        attention[i, i] += 0.35 * moved
                        attention[i, i - 1] += 0.35 * moved
                        attention[i, anchor] += 0.30 * moved

    return "bos_sink_with_local_nominal_gating", attention


def prog_L20H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with mildly declining strength and diffuse causal leakage.
    No consistent syntactic or semantic target is evident beyond the first token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.96 - 0.07 * (1.0 - np.exp(-(i - 1) / 35.0))
        if i == 1:
            sink_mass = 0.98

        positions = np.arange(1, i + 1)
        recency = np.exp(-(i - positions) / 5.0)
        recency /= recency.sum()
        leakage = 0.8 / i + 0.2 * recency

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * leakage

    return "bos_sink_with_diffuse_leakage", attention


def prog_L20H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local predecessor gate for split content-word onsets
    and copular adjectives; gated mass comes only from BOS, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_onset_gate", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "DET": 0.961,
        "PRON": 0.918,
        "CCONJ": 0.921,
        "SCONJ": 0.845,
        "PART": 0.855,
        "ADP": 0.805,
        "AUX": 0.710,
        "VERB": 0.755,
        "NOUN": 0.805,
        "PROPN": 0.918,
        "ADJ": 0.795,
        "ADV": 0.825,
        "NUM": 0.865,
        "INTJ": 0.910,
        "PUNCT": 0.965,
        "SPACE": 0.980,
        "SYM": 0.940,
    }

    for i in range(1, n):
        raw = tokens[i]
        surface = raw.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = None

        if aligned:
            word = doc[aligned[0]]
            sink = sink_by_pos.get(word.pos_, 0.835)
        else:
            sink = 0.855

        if not surface:
            sink = 0.980
        elif all(not char.isalnum() for char in surface):
            sink = 0.965
            if any(char in ".!?" for char in surface):
                sink = 0.978

        if word is not None:
            if word.dep_ == "poss":
                sink = max(sink, 0.946)
            if word.ent_type_ and word.pos_ == "PROPN":
                sink = max(sink, 0.925)

        if i == 1:
            sink = max(sink, 0.955)

        # Preserve the original residual distribution and self-attention.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # A split content-word onset can strongly retrieve its preceding word.
        # Copular adjectives exhibit the same gate without requiring a split.
        if word is not None and i > 1 and alignment[i - 1]:
            previous = doc[alignment[i - 1][-1]]
            starts_word = (
                word.i not in alignment[i - 1]
                and previous.i == word.i - 1
            )
            split_onset = (
                starts_word
                and i + 1 < n
                and word.i in alignment[i + 1]
                and word.pos_ in ("NOUN", "ADJ", "VERB")
                and previous.pos_ in (
                    "DET", "ADJ", "NOUN", "PROPN", "AUX", "VERB"
                )
            )
            copular_adjective = (
                starts_word
                and word.pos_ == "ADJ"
                and previous.pos_ == "AUX"
                and (previous.head.i == word.i or word.head.i == previous.i)
            )
            if split_onset or copular_adjective:
                target = 0.70 if split_onset else 0.54
                transfer = min(
                    max(0.0, target - attention[i, i - 1]),
                    max(0.0, attention[i, 0] - 0.12),
                )
                attention[i, 0] -= transfer
                attention[i, i - 1] += transfer

    return "bos_sink_with_onset_gate", make_row_stochastic(attention)


def prog_L20H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a local previous-token exception for definite determiners.
    Linguistic category and subword position modulate the residual local attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_definite_determiner_locality", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        word = doc[alignment[i][0]] if alignment[i] else None
        sink = 0.85

        if word is not None:
            if word.pos_ in ("AUX", "ADP", "SCONJ"):
                sink = 0.90
            elif word.pos_ in ("VERB", "CCONJ", "ADV"):
                sink = 0.87
            elif word.pos_ in ("NOUN", "PROPN"):
                sink = 0.80
            elif word.pos_ in ("PRON", "ADJ"):
                sink = 0.79
            elif word.pos_ == "DET":
                sink = 0.86
            elif word.is_punct:
                sink = 0.83

            # A word's initial model piece often retains stronger sink attention.
            if i > 1 and alignment[i - 1]:
                if alignment[i][0] == alignment[i - 1][0]:
                    sink -= 0.035

        definite = (
            word is not None
            and word.pos_ == "DET"
            and "Def" in word.morph.get("Definite")
        )

        if definite:
            # Determine whether this is the first model piece of the determiner.
            first_piece = (
                i == 1
                or not alignment[i - 1]
                or alignment[i - 1][0] != alignment[i][0]
            )
            if first_piece:
                sink = 0.21
                attention[i, 0] = sink
                if i == 1:
                    attention[i, i] = 1.0 - sink
                else:
                    attention[i, i - 1] = 0.93 * (1.0 - sink)
                    attention[i, i] = 0.07 * (1.0 - sink)
                continue

        attention[i, 0] = sink
        # Keep the non-sink component causal, primarily local, and mildly diffuse.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.5)
        local[-1] *= 0.65
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "bos_sink_with_definite_determiner_locality", make_row_stochastic(attention)


def prog_L20H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with determiner-predecessor exceptions; quoted questions and
    replies additionally route predicate/object attention to the quote opener."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "PROPN": 0.93,
        "NOUN": 0.87,
        "PRON": 0.88,
        "VERB": 0.86,
        "AUX": 0.89,
        "ADJ": 0.82,
        "ADV": 0.81,
        "ADP": 0.77,
        "CCONJ": 0.88,
        "SCONJ": 0.82,
        "PART": 0.85,
        "PUNCT": 0.90,
        "NUM": 0.87,
    }

    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        candidates = alignment[i]
        word = doc[candidates[0]] if candidates else None
        pos = word.pos_ if word is not None else ""
        sink = sink_by_pos.get(pos, 0.88)

        if not text or tokens[i] in special_tokens:
            sink = 0.90
        elif all(not c.isalnum() for c in text):
            sink = 0.91
        elif pos == "DET":
            sink = 0.92

        if i == 1 and pos != "DET":
            sink = 0.97

        # Preserve the original local residual and decay exactly.
        distances = i - np.arange(1, i + 1)
        local = np.exp(-distances / 2.5)
        local /= local.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local

        if word is None:
            continue

        definite = "Def" in word.morph.get("Definite")
        possessive = (
            "Yes" in word.morph.get("Poss")
            or word.dep_ == "poss"
        )
        first_piece = not any(
            word.i in alignment[j] for j in range(1, i)
        )

        if not first_piece:
            continue

        previous = doc[word.i - 1] if word.i > 0 else None
        determiner_exception = (
            (pos == "DET" and definite)
            or (
                possessive
                and previous is not None
                and previous.pos_ in ("VERB", "AUX", "ADP")
            )
        )

        if determiner_exception:
            if i == 1:
                target, strength = i, 0.72
            else:
                target = i - 1
                strength = 0.78 if definite else 0.70
                if previous is not None:
                    if previous.pos_ in ("VERB", "ADP"):
                        strength += 0.08
                    elif previous.is_punct:
                        strength -= 0.15

            attention[i] *= 1.0 - strength
            attention[i, target] += strength

    # Narrow exception for auxiliary-led questions and interjection-led replies.
    # Transfer only BOS mass: original self-attention and local decay survive.
    quote_start = None
    quote_first = None
    quote_kind = None
    for i in range(1, n):
        if tokens[i] in special_tokens:
            continue
        if any(c in tokens[i] for c in ('"', '“', '”', '«', '»')):
            quote_start = i if quote_start is None else None
            quote_first = None
            quote_kind = None
            continue

        if quote_start is None or not alignment[i]:
            continue
        word = doc[alignment[i][0]]
        if word.is_punct or word.is_space:
            continue
        if quote_first is None:
            quote_first, quote_kind = i, word.pos_
        if quote_kind not in ("AUX", "INTJ"):
            continue

        targets = []
        if i == quote_first and quote_kind == "INTJ":
            targets = [(quote_start, 0.30)]
        elif word.pos_ == "PRON" and word.dep_ in ("dobj", "obj", "pobj"):
            if quote_kind == "AUX":
                targets = [(quote_start, 0.50)]
            else:
                targets = [(quote_start, 0.14), (quote_first, 0.14)]
        elif word.pos_ == "VERB":
            for j in range(i - 1, quote_start, -1):
                if alignment[j]:
                    previous = doc[alignment[j][0]]
                    if previous.pos_ == "AUX" or previous.dep_ in ("nsubj", "nsubjpass"):
                        targets = [(quote_start, 0.12), (j, 0.18)]
                        break

        if targets:
            total = sum(weight for _, weight in targets)
            scale = min(1.0, attention[i, 0] / total)
            attention[i, 0] -= total * scale
            for target, weight in targets:
                attention[i, target] += weight * scale

    return (
        "bos_sink_with_quote_exception",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L20H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weak local residual.
    Short, word-initial noun fragments can instead become self-attention sinks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_fragment_self_attention", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    special_tokens = tokenizer.all_special_tokens

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        # Most queries strongly prefer the initial token; this preference
        # gradually weakens as the causal context grows.
        bos_mass = 0.94 - 0.105 * (1.0 - np.exp(-i / 28.0))

        if word is not None:
            if word.pos_ == "DET":
                bos_mass -= 0.045
            elif word.pos_ == "PUNCT":
                bos_mass -= 0.035
            elif word.pos_ == "ADP":
                bos_mass -= 0.020
            elif word.pos_ in ("ADJ", "ADV", "PRON"):
                bos_mass += 0.012

        if tokens[i] in special_tokens:
            bos_mass = 0.94

        fragment_self = 0.0
        if word is not None and word.pos_ in ("NOUN", "PROPN"):
            pieces = inverse[word.i]
            if len(pieces) > 1 and pieces[0] == i:
                surface = tokens[i].lstrip("▁Ġ")
                if surface.isalpha() and len(surface) <= 3:
                    fragment_self = 0.90 - 0.11 * (len(surface) - 1)

        if fragment_self > 0.0:
            bos_mass = 1.0 - fragment_self - 0.035

        bos_mass = float(np.clip(bos_mass, 0.05, 0.97))
        attention[i, 0] = bos_mass

        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = 0.55

        start = max(1, i - 12)
        positions = np.arange(start, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        residual[start:i + 1] += 0.30 * local / local.sum()

        if word is not None:
            heads = [j for j in inverse[word.head.i] if 0 < j <= i]
            if heads:
                residual[heads[-1]] += 0.15
            else:
                residual[i] += 0.15
        else:
            residual[i] += 0.15

        if fragment_self > 0.0:
            residual[:] = 0.0
            residual[i] = fragment_self
            if i > 1:
                residual[i - 1] += 0.035
            else:
                residual[i] += 0.035

        attention[i, :i + 1] += (
            (1.0 - bos_mass) * residual / residual.sum()
        )

    return "bos_sink_with_fragment_self_attention", make_row_stochastic(attention)


def prog_L20H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak, recency-biased causal leakage.
    Sink dominance gradually weakens as the available context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_causal_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.965 - 0.0015 * min(i - 1, 60)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.25 + np.exp(-distances / 4.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_causal_leakage", attention


def prog_L20H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with clause anchors; local clause-entry cues can replace distant
    predicate anchors without changing the original self-attention or decay.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_clause_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pieces = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if 0 <= k < len(doc):
                pieces[k].append(i)

    special_tokens = set(tokenizer.all_special_tokens)
    quote_chars = {'"', '“', '”', '«', '»'}
    opening_quotes = {'"', '“', '«'}
    closing_quotes = {'"', '”', '»'}
    representatives = []
    for indices in alignment:
        valid = [k for k in indices if 0 <= k < len(doc)]
        content = [k for k in valid if not doc[k].is_space]
        representatives.append(content[-1] if content else (valid[-1] if valid else None))

    last_predicate = None
    last_boundary = None
    quote_open = False
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        text = raw.replace("▁", " ").replace("Ġ", " ").strip()
        k = representatives[i]
        word = doc[k] if k is not None else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        mapped = pieces[k] if k is not None else []
        first_piece = bool(mapped) and i == mapped[0]
        final_piece = bool(mapped) and i == mapped[-1]

        anchor = last_predicate
        if word is not None:
            ancestor = word.head
            visited = set()
            while ancestor.i not in visited and ancestor.i != word.i:
                visited.add(ancestor.i)
                if ancestor.pos_ in ("VERB", "AUX", "ADJ"):
                    candidates = [j for j in pieces[ancestor.i] if 0 < j <= i]
                    if candidates:
                        anchor = candidates[-1]
                        break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

        sink, self_mass, anchor_mass, previous_mass = 0.58, 0.15, 0.21, 0.0
        is_predicate = pos == "VERB" or (
            pos == "ADJ" and dep in ("ROOT", "acomp", "attr", "oprd")
        )

        if pos == "DET" or dep == "poss":
            sink, self_mass, anchor_mass = 0.90, 0.02, 0.02
        elif pos in ("ADJ", "NUM") and not is_predicate:
            sink, self_mass, anchor_mass = 0.83, 0.04, 0.07
        elif pos in ("NOUN", "PROPN"):
            sink, self_mass, anchor_mass = 0.70, 0.08, 0.16
            if len(mapped) > 1 and not final_piece:
                sink, self_mass, anchor_mass = 0.88, 0.02, 0.04
            elif dep in ("dobj", "obj", "iobj", "dative", "pobj", "attr", "appos"):
                sink, self_mass, anchor_mass = 0.38, 0.08, 0.48
            if dep in ("nsubj", "nsubjpass", "csubj"):
                sink, self_mass, anchor_mass = 0.77, 0.07, 0.10
                if last_boundary is not None and i - last_boundary <= 5:
                    anchor = last_boundary
                    sink, self_mass, anchor_mass = 0.35, 0.07, 0.52
        elif is_predicate:
            sink, self_mass, anchor_mass = 0.40, 0.43, 0.11
        elif pos == "AUX":
            sink, self_mass, anchor_mass = 0.47, 0.15, 0.32
        elif pos == "PRON":
            sink, self_mass, anchor_mass = 0.40, 0.10, 0.44
        elif pos in ("ADP", "PART"):
            sink, self_mass, anchor_mass = 0.61, 0.05, 0.28
        elif pos in ("CCONJ", "SCONJ"):
            sink, self_mass, anchor_mass = 0.72, 0.08, 0.14
        elif pos == "ADV":
            sink, self_mass, anchor_mass = 0.65, 0.12, 0.17
            if dep == "advmod" and last_boundary is not None and i - last_boundary <= 2:
                sink, self_mass, anchor_mass = 0.24, 0.60, 0.10

        contains_quote = any(c in quote_chars for c in text)
        opens_quote = contains_quote and (
            any(c in {'“', '«'} for c in text)
            or ('"' in text and not quote_open)
        )
        if text and all(c in opening_quotes for c in text) and opens_quote:
            sink, self_mass, anchor_mass = 0.15, 0.78, 0.01
        elif pos == "PUNCT" or (text and all(not c.isalnum() for c in text)):
            sink, self_mass, anchor_mass = 0.59, 0.15, 0.20
            if contains_quote and any(c in "?!." for c in text):
                sink, self_mass, anchor_mass = 0.51, 0.37, 0.06
        elif not text:
            sink, self_mass, anchor_mass, previous_mass = 0.51, 0.02, 0.01, 0.40

        # A directly adjacent clause cue is more reliable than an older predicate.
        # Redistribute only anchor/sink mass; leave self and recency unchanged.
        if word is not None and k > 0 and first_piece and text:
            previous_word = doc[k - 1]
            previous_pieces = [j for j in pieces[k - 1] if 0 < j < i]
            if previous_pieces and previous_pieces[-1] == i - 1:
                subject_cue = (
                    previous_word.pos_ == "PRON"
                    and previous_word.dep_ in ("nsubj", "nsubjpass", "csubj")
                    and previous_word.head.i == k
                )
                modifier_cue = (
                    previous_word.head.i == k
                    and previous_word.dep_ in ("aux", "auxpass", "cop", "advmod", "mark")
                    and previous_word.pos_ in ("AUX", "ADV", "PART")
                )
                if (is_predicate or pos == "AUX") and (subject_cue or modifier_cue):
                    anchor = previous_pieces[-1]
                    transfer = min(sink, 0.18 if is_predicate else 0.08)
                    sink -= transfer
                    anchor_mass += transfer
                elif (
                    pos == "PRON"
                    and dep in ("nsubj", "nsubjpass", "csubj")
                    and previous_word.pos_ in ("CCONJ", "SCONJ")
                ):
                    anchor = previous_pieces[-1]

        if i == 1:
            sink, self_mass, anchor_mass, previous_mass = 0.91, 0.03, 0.0, 0.0
        if raw in special_tokens:
            sink, self_mass, anchor_mass, previous_mass = 0.94, 0.0, 0.0, 0.0

        recency = np.exp(-0.30 * np.arange(i, -1, -1, dtype=np.float64))
        attention[i, :i + 1] = 0.06 * recency / recency.sum()
        attention[i, 0] += sink
        attention[i, i] += self_mass
        attention[i, i - 1] += previous_mass
        if anchor is not None and 0 < anchor <= i:
            attention[i, anchor] += anchor_mass
        else:
            attention[i, 0] += anchor_mass

        if is_predicate and final_piece:
            last_predicate = i
        if pos == "ADV" and self_mass >= 0.60:
            last_predicate = i
        if contains_quote:
            if opens_quote:
                quote_open = True
            elif any(c in closing_quotes for c in text):
                quote_open = False
                last_boundary = i
                last_predicate = None
        elif text and any(c in ".?!" for c in text) and pos == "PUNCT":
            last_boundary = i
            last_predicate = None

    return "bos_sink_with_local_clause_links", make_row_stochastic(attention)


def prog_L20H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary gates; prepositional objects favor the preceding
    lexical verb over the intervening preposition."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_prepositional_routing", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    terminal_chars = ".!?"
    quote_chars = "\"'“”‘’"
    last_boundary = None

    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None

        whitespace = not clean and raw not in tokenizer.all_special_tokens
        terminal = (
            bool(clean)
            and any(c in terminal_chars for c in clean)
            and all(c in terminal_chars + quote_chars for c in clean)
        )
        quote_only = bool(clean) and all(c in quote_chars for c in clean)

        # Default sink and all original modulation remain unchanged.
        sink = 0.50 + 0.37 * np.exp(-(i - 1) / 13.0)

        if word is not None:
            pos = word.pos_
            if pos in ("PRON", "AUX", "DET"):
                sink += 0.07
            elif pos == "VERB":
                sink += 0.06
            elif pos in ("ADP", "PART"):
                sink += 0.01
            elif pos in ("NOUN", "PROPN"):
                sink -= 0.04
            elif pos in ("ADJ", "ADV", "CCONJ", "SCONJ"):
                sink -= 0.08

            pieces = inverse[word.i]
            if len(pieces) > 1:
                if i < pieces[-1]:
                    sink += 0.19
                else:
                    sink -= 0.04

            if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink -= 0.10
            if word.ent_type_:
                sink += 0.03

        if i == 1:
            sink = 0.96

        weights = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        weights[1:] = 0.12 * np.exp(-(i - positions) / 7.0)
        weights[i] += 0.55

        if word is not None:
            head_pieces = inverse[word.head.i]
            eligible = [j for j in head_pieces if 0 < j <= i]
            if word.head.i != word.i and eligible:
                strength = 1.25
                if word.dep_ in ("dobj", "obj", "pobj", "attr"):
                    strength = 2.8
                weights[eligible[-1]] += strength

                # Only reroute the dependency bonus for a verb-attached
                # prepositional object. Preserve total weight, sink, self,
                # and recency weights; leave nominal attachments untouched.
                if (
                    word.dep_ in ("pobj", "obj")
                    and word.head.pos_ == "ADP"
                    and word.head.head.pos_ == "VERB"
                    and eligible[-1] < i
                ):
                    governor_pieces = [
                        j for j in inverse[word.head.head.i]
                        if 0 < j < i
                    ]
                    if governor_pieces:
                        moved = 0.80 * strength
                        weights[eligible[-1]] -= moved
                        weights[governor_pieces[-1]] += moved

            if word.is_punct and i > 1:
                weights[i - 1] += 0.55

        if quote_only:
            sink -= 0.20
            weights[i] += 1.7

        if last_boundary is not None and i - last_boundary <= 5:
            weights[last_boundary] += 0.8 * np.exp(
                -(i - last_boundary) / 3.0
            )

        sink = float(np.clip(sink, 0.24, 0.98))
        weights /= weights.sum()
        attention[i, :i + 1] = (1.0 - sink) * weights
        attention[i, 0] = sink

        if terminal:
            quoted = any(c in quote_chars for c in clean)
            self_mass = 0.86 if quoted and "?" in clean else 0.60
            attention[i, :i + 1] *= 1.0 - self_mass
            attention[i, i] += self_mass
            last_boundary = i

        if whitespace and i > 1:
            previous = tokens[i - 1]
            if any(c in terminal_chars for c in previous):
                attention[i, :i + 1] *= 0.10
                attention[i, i - 1] += 0.90

    return (
        "bos_sink_with_prepositional_routing",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L20H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink, with secondary anchors for numeral-led openings and
    adjectival descriptions when a nominal referent recurs."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.tril(np.ones((n, n), dtype=np.float64))

    if n:
        attention[:, 0] = 400.0

    if n > 1:
        doc = spacy_parse(sentence)
        mapping = align_spacy_to_tokens(sentence, tokens, tokenizer)
        reverse = align_tokens_to_spacy(sentence, tokens, tokenizer)

        # A numeral-led nominal opening can become a persistent secondary sink.
        if (
            len(doc) > 1
            and doc[0].pos_ == "NUM"
            and doc[0].dep_ == "nummod"
            and doc[0].head.pos_ == "NOUN"
            and mapping[0]
        ):
            anchor = mapping[0][0]
            if anchor > 0:
                for i in range(anchor + 1, n):
                    query = doc[reverse[i][0]] if reverse[i] else None
                    weight = 55.0
                    if query is not None:
                        if query.is_punct:
                            weight = 118.0
                        elif query.pos_ == "PROPN":
                            weight = 90.0
                        elif query.pos_ == "AUX":
                            weight = 25.0
                        elif query.pos_ == "PRON":
                            weight = 45.0
                    attention[i, anchor] += weight

        # Gate descriptive anchors on a recurring nominal, avoiding a broad
        # adjective bias in otherwise well-modelled, single-reference sentences.
        nominals = [
            w for w in doc
            if w.pos_ in ("NOUN", "PROPN") and mapping[w.i]
        ]
        recurring = False
        for a, left in enumerate(nominals):
            for right in nominals[a + 1:]:
                if embedding_similarity(
                    tokens, mapping[left.i][0], mapping[right.i][0], tokenizer
                ) > 0.90:
                    recurring = True
                    break
            if recurring:
                break

        if recurring:
            anchors = [
                mapping[w.i][0]
                for w in doc
                if w.pos_ == "ADJ"
                and w.dep_ == "amod"
                and w.head.dep_ in ("nsubj", "dobj", "obj")
                and mapping[w.i]
                and mapping[w.i][0] > 0
            ]
            for i in range(1, n):
                active = [j for j in anchors if j < i]
                query = doc[reverse[i][0]] if reverse[i] else None
                for rank, j in enumerate(active):
                    weight = 40.0 if i - j > 3 else 18.0
                    if query is not None:
                        if query.pos_ == "DET" and query.dep_ == "det":
                            weight = (
                                650.0 * (1.0 + 0.38 * (len(active) - 1))
                                * (0.54 ** rank)
                            )
                        elif query.is_punct:
                            weight = 85.0
                        elif query.pos_ == "ADJ" and query.dep_ != "amod":
                            weight = 65.0 if rank == 0 else 130.0
                    attention[i, j] += weight

    return "bos_sink_with_gated_secondary_anchors", make_row_stochastic(attention)


def prog_L20H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local backoff; complement-opening tokens can release
    additional BOS mass to an immediately preceding lexical host.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_complement_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        piece = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()

        sink = 0.89
        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos == "DET":
                sink = 0.40
            elif pos == "ADP":
                sink = 0.64
            elif pos == "PART":
                sink = 0.77
            elif pos == "VERB":
                sink = 0.76
            elif pos == "AUX":
                sink = 0.87
            elif pos == "PRON":
                sink = 0.87
            elif pos in ("NOUN", "PROPN", "ADJ", "ADV"):
                sink = 0.90
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.88

            if dep == "poss":
                sink = 0.57
            elif dep == "punct":
                sink = 0.82

        if not piece:
            sink = 0.63
        elif all(c in ".,!?;:—–-\"'“”‘’()[]" for c in piece):
            if any(c in ".!?" for c in piece):
                sink = 0.93
            elif any(c in "\"“”" for c in piece):
                sink = 0.89
            else:
                sink = 0.80

        # Preserve the original self weight and exponentially decaying tail.
        attention[i, 0] = sink
        remainder = 1.0 - sink
        attention[i, i] += 0.08 * remainder

        previous = np.arange(1, i)
        if previous.size:
            weights = np.exp(-1.25 * (i - 1 - previous))
            weights /= weights.sum()
            attention[i, previous] += 0.92 * remainder * weights
        else:
            attention[i, 0] += 0.92 * remainder

        # Only complement onsets directly following a suitable host receive
        # extra previous-token mass. All other rows remain unchanged.
        if i > 1 and word is not None and alignment[i - 1]:
            prev_word = doc[alignment[i - 1][-1]]
            if prev_word.i != word.i:
                prepositional_onset = (
                    word.pos_ == "ADP"
                    and word.dep_ in ("prep", "agent")
                    and prev_word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB")
                )
                indefinite_object_onset = (
                    word.pos_ == "DET"
                    and word.dep_ == "det"
                    and "Ind" in word.morph.get("Definite")
                    and prev_word.pos_ in ("VERB", "AUX")
                    and word.head.dep_ in ("dobj", "obj", "attr", "oprd")
                    and word.head.head.i == prev_word.i
                )
                if prepositional_onset or indefinite_object_onset:
                    transfer = min(
                        attention[i, 0],
                        0.24 if prepositional_onset else 0.26,
                    )
                    attention[i, 0] -= transfer
                    attention[i, i - 1] += transfer

    return "bos_sink_with_complement_backoff", make_row_stochastic(attention)


def prog_L20H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strengthened by boundaries and fragmented word pieces.
    Linguistic and positional features modulate the sink's strength."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "boundary_modulated_bos_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_pieces = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_pieces[wi].append(ti)

    special_tokens = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        surface = raw.lstrip("▁Ġ")
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None

        sink = 0.47
        if word is not None:
            pos = word.pos_
            if pos == "DET":
                sink = 0.80 if len(word.text) > 1 else 0.42
            elif pos == "PROPN":
                sink = 0.73
            elif pos == "ADJ":
                sink = 0.56
            elif pos == "ADV":
                sink = 0.51
            elif pos == "ADP":
                sink = 0.48
            elif pos in ("PRON", "AUX", "PART"):
                sink = 0.41
            elif pos in ("VERB", "NOUN"):
                sink = 0.48
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.52

            if word.dep_ == "ROOT":
                sink += 0.04

            # Early context has relatively little competition with BOS.
            sink += 0.15 * np.exp(-(i - 1) / 6.0)

            pieces = word_pieces[word_ids[0]]
            if len(pieces) > 1 and not word.is_punct:
                if i == pieces[0]:
                    fragment_strength = 0.95 if len(surface) <= 4 else 0.82
                elif i != pieces[-1]:
                    fragment_strength = 0.91
                else:
                    fragment_strength = 0.58
                sink = max(sink, fragment_strength)

        if raw in special_tokens:
            sink = 0.94
        elif not surface or surface.isspace():
            sink = 0.85
        elif all(not c.isalnum() and not c.isspace() for c in surface):
            if any(c in "'’" for c in surface):
                sink = 0.92
            elif any(c in "\"“”?!" for c in surface):
                sink = 0.87
            elif "." in surface:
                sink = 0.82
            else:
                sink = 0.61 + 0.20 * np.exp(-i / 18.0)

        if i == 1:
            sink = max(sink, 0.88)

        sink = float(np.clip(sink, 0.30, 0.98))
        positions = np.arange(1, i + 1)
        residual = 0.65 / i + 0.35 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    return "boundary_modulated_bos_sink", make_row_stochastic(attention)


def prog_L21H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with selective self-routing for negation and marked predicates.
    Definite determiners after prepositions or conjunctions split their local route.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_selective_self_routing", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.88 - 0.0018 * min(i, 65)

        if pos in ("VERB", "ADJ"):
            sink += 0.025
        elif pos in ("DET", "PRON", "PART"):
            sink -= 0.065
        elif pos in ("ADP", "AUX"):
            sink -= 0.025

        if pos == "PROPN" and i <= 3:
            sink += 0.07
        if pos == "CCONJ":
            sink += 0.02

        clean = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        if not clean or tokens[i] in tokenizer.all_special_tokens:
            sink += 0.045
        elif pos == "PUNCT":
            sink += 0.03

        sink = float(np.clip(sink, 0.68, 0.97))

        # Keep the residual causal, mostly local, and mildly self-directed.
        positions = np.arange(1, i + 1)
        tail = np.exp(-(i - positions) / 3.0)
        tail[-1] *= 0.65
        tail /= tail.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * tail

        definite = (
            word is not None
            and pos == "DET"
            and dep == "det"
            and "Def" in word.morph.get("Definite")
        )
        first_piece = (
            not aligned
            or i == 1
            or aligned[0] not in alignment[i - 1]
        )

        if definite and first_piece:
            if i == 1:
                attention[i, :] = 0.0
                attention[i, 0] = 0.27
                attention[i, i] = 0.73
            else:
                attention[i, :] *= 0.22
                attention[i, i - 1] += 0.78

        # Only these marked constructions divert the default BOS allocation.
        if word is not None and first_piece:
            self_target = 0.0
            gerund_complement = (
                pos == "VERB"
                and dep == "xcomp"
                and "Ger" in word.morph.get("VerbForm")
            )
            if pos in ("AUX", "VERB") and any(
                child.dep_ == "neg" for child in word.children
            ):
                self_target = 0.65
            elif gerund_complement:
                self_target = 0.56
            elif (
                pos == "PRON"
                and dep in ("dobj", "obj")
                and word.head.dep_ == "xcomp"
                and "Ger" in word.head.morph.get("VerbForm")
            ):
                self_target = 0.50
            elif (
                pos == "PRON"
                and dep == "nsubj"
                and word.head.pos_ == "ADJ"
                and word.head.i < word.i
                and any(
                    child.pos_ == "AUX" and child.i > word.i
                    for child in word.head.children
                )
            ):
                self_target = 0.78

            if self_target:
                transfer = min(
                    attention[i, 0],
                    max(0.0, self_target - attention[i, i]),
                )
                attention[i, 0] -= transfer
                attention[i, i] += transfer

            if definite and i > 1 and alignment[i - 1]:
                previous = doc[alignment[i - 1][-1]]
                if previous.pos_ in ("ADP", "CCONJ"):
                    transfer = min(0.35, attention[i, i - 1])
                    attention[i, i - 1] -= transfer
                    attention[i, i] += transfer * 0.77
                    attention[i, 0] += transfer * 0.23

    return "bos_sink_with_selective_self_routing", make_row_stochastic(attention)


def prog_L21H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with gradual positional dilution.
    Weak residual attention follows recency and available syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_positional_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    first_piece = {}
    for i, aligned in enumerate(alignment):
        if i > 0:
            for sid in aligned:
                if sid not in first_piece:
                    first_piece[sid] = i

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Position zero dominates; competing keys accumulate with context.
        odds = 0.015 + 0.0009 * i + 0.00004 * i * i
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("PRON", "AUX"):
                odds *= 0.85
            elif word.pos_ in ("ADP", "PART"):
                odds *= 1.15

        sink_mass = 1.0 / (1.0 + odds)
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + np.exp(-(i - positions) / 7.0)

        if aligned:
            head_sid = doc[aligned[0]].head.i
            head_piece = first_piece.get(head_sid)
            if head_piece is not None and head_piece < i:
                residual[head_piece - 1] += 0.5

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "bos_sink_with_positional_dilution", attention


def prog_L21H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink head with a secondary self/local channel.
    Apostrophes bind backward, while standalone whitespace follows punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_punctuation", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]

    sink_by_pos = {
        "PRON": 0.72,
        "DET": 0.79,
        "ADP": 0.85,
        "AUX": 0.81,
        "VERB": 0.80,
        "NOUN": 0.61,
        "PROPN": 0.70,
        "ADJ": 0.67,
        "ADV": 0.66,
        "PART": 0.76,
        "CCONJ": 0.66,
        "SCONJ": 0.72,
        "NUM": 0.67,
        "PUNCT": 0.55,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = clean[i]
        matches = aligned[i]
        word = doc[matches[-1]] if matches else None
        pos = word.pos_ if word is not None else ""
        sink = sink_by_pos.get(pos, 0.72)

        # Early positions have a particularly strong attention sink.
        if i == 1:
            sink = 0.99 if pos == "PRON" else 0.94
        elif i <= 3:
            sink = min(0.94, sink + 0.07)

        # Short initial pieces of split words strongly favor BOS.
        same_word_before = bool(
            matches and set(matches).intersection(aligned[i - 1])
        )
        same_word_after = bool(
            i + 1 < n and matches
            and set(matches).intersection(aligned[i + 1])
        )
        if same_word_after and not same_word_before and text.isalnum():
            sink = max(sink, 0.95)
        elif same_word_before:
            sink = max(sink, 0.70)

        # Later mentions retain a larger non-sink component.
        if i > 12 and not (same_word_after and not same_word_before):
            sink -= min(0.10, 0.002 * (i - 12))

        # Opening/closing quote tokens commonly emphasize their own position.
        if text and any(c in "\"“”«»" for c in text):
            sink = 0.43
        elif text and all(c in ".!?…" for c in text):
            sink = 0.46

        # Isolated contraction/possessive apostrophes point to the stem.
        if text in ("'", "’") and clean[i - 1] and clean[i - 1][-1].isalnum():
            previous_matches = aligned[i - 1]
            previous_pos = (
                doc[previous_matches[-1]].pos_ if previous_matches else ""
            )
            backward = 0.74 if previous_pos in ("NOUN", "PROPN") else 0.96
            attention[i, i - 1] = backward
            attention[i, 0] += 1.0 - backward
            continue

        # Explicit whitespace after punctuation preserves the boundary.
        if not text and clean[i - 1] and not clean[i - 1][-1].isalnum():
            attention[i, i - 1] = 0.72
            attention[i, 0] += 0.24
            attention[i, i] = 0.04
            continue

        sink = float(np.clip(sink, 0.35, 0.99))
        attention[i, 0] = sink
        residual = 1.0 - sink
        attention[i, i] += 0.76 * residual

        # The remaining mass is a small causal recency distribution.
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 2.0)
        local /= local.sum()
        attention[i, 1:i + 1] += 0.24 * residual * local

    return "bos_sink_with_local_punctuation", make_row_stochastic(attention)


def prog_L21H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a BOS sink with punctuation attachment and an infinitival-marker exception.
    Infinitival markers favor themselves and an immediately preceding verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_infinitival_attachment", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)

    content_pos = {"NOUN", "PROPN", "ADJ", "NUM"}
    function_pos = {"ADP", "CCONJ", "SCONJ", "PART"}
    apostrophes = {"'", "’", "ʼ"}
    quotes = {'"', "“", "”", "«", "»", "``", "''"}

    cleaned = []
    for token in tokens:
        cleaned.append(token.replace("▁", " ").replace("Ġ", " ").strip())

    attention[0, 0] = 1.0

    for i in range(1, n):
        text = cleaned[i]
        previous = cleaned[i - 1]
        matches = alignment[i]
        word = doc[matches[0]] if matches else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Reserve a small, causal local distribution for non-sink attention.
        local = np.zeros(i + 1, dtype=np.float64)
        local[i] = 0.40
        for distance in range(1, min(i, 8) + 1):
            j = i - distance
            if j > 0:
                local[j] += 0.60 * np.exp(-(distance - 1) / 1.8)

        sink = 0.80
        if pos in content_pos:
            sink = 0.89
        elif pos == "DET":
            sink = 0.86
        elif pos == "VERB":
            sink = 0.78
        elif pos == "AUX":
            sink = 0.80
        elif pos == "PRON":
            sink = 0.78
        elif pos == "ADV":
            sink = 0.77
        elif pos in function_pos:
            sink = 0.65

        if dep == "poss":
            sink = 0.66
        if word is not None and word.ent_type_:
            sink = max(sink, 0.88)

        if i == 1:
            sink = 0.94

        # A standalone apostrophe is the clearest non-BOS behavior.
        if text in apostrophes and i > 1:
            attention[i, 0] = 0.015
            attention[i, i - 1] = 0.98
            attention[i, i] = 0.005
            continue

        # Standalone whitespace after dialogue punctuation attaches leftward.
        if not text and tokens[i] not in special_tokens:
            attention[i, 0] = 0.12
            attention[i, i - 1] += 0.84
            attention[i, i] = 0.04
            continue

        if text in quotes:
            attention[i, 0] = 0.28
            attention[i, i] = 0.58
            attention[i, i - 1] += 0.14
            continue

        if text and all(c in ".,;:!?\"'“”‘’«»—–-()[]{}" for c in text):
            if "," in text or ";" in text or ":" in text:
                attention[i, 0] = 0.30
                attention[i, i - 1] += 0.55
                attention[i, i] = 0.15
                continue
            sink = 0.71

        # The suffix following an apostrophe often retains substantial self mass.
        if previous in apostrophes:
            attention[i, 0] = 0.35
            attention[i, i] = 0.55
            attention[i, i - 1] += 0.10
            continue

        # Subword continuation preserves the lexical sink preference.
        if i > 1 and matches and alignment[i - 1]:
            if any(k in alignment[i - 1] for k in matches):
                sink = max(sink, 0.84)

        # Infinitival markers, unlike prepositions, strongly suppress the sink.
        if i > 1 and pos == "PART" and word.tag_ == "TO":
            previous_matches = alignment[i - 1]
            previous_word = doc[previous_matches[-1]] if previous_matches else None
            sink = 0.14
            local[:] = 0.0
            local[i] = 0.88
            local[i - 1] = 0.12
            if previous_word is not None and previous_word.pos_ in {"VERB", "AUX"}:
                local[i] = 0.47
                local[i - 1] = 0.53

        local[0] = 0.0
        local /= local.sum()
        attention[i, :i + 1] = (1.0 - sink) * local
        attention[i, 0] = sink

    return "bos_sink_with_infinitival_attachment", make_row_stochastic(attention)


def prog_L21H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local argument attention only for genuine, unsplit objects.
    Subjects, possessives, and partial words do not trigger the argument override.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_verified_local_arguments", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            if 0 <= k < len(doc):
                inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[0]] if indices else None
        sink = 0.82 - 0.0015 * min(i, 60)
        target = None
        local_argument = False

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos in ("DET", "AUX"):
                sink += 0.10
            elif pos in ("PRON", "ADJ", "PROPN"):
                sink += 0.06
            elif pos in ("ADP", "CCONJ", "SCONJ", "PART"):
                sink += 0.025
            elif pos == "VERB":
                sink -= 0.13
            elif pos == "PUNCT":
                sink -= 0.06

            pieces = inverse[word.i]
            first_piece = bool(pieces) and i == pieces[0]
            if pos in ("NOUN", "PROPN") and first_piece and len(pieces) > 1:
                sink += 0.08

            head_indices = [
                j for j in inverse[word.head.i]
                if 0 < j < i and word.head.i != word.i
            ]
            if head_indices:
                target = head_indices[-1]

            if first_piece and word.i > 0 and pos in ("NOUN", "PRON"):
                previous = doc[word.i - 1]
                previous_indices = [
                    j for j in inverse[previous.i] if 0 < j < i
                ]
                if previous.pos_ == "VERB" and previous_indices:
                    # Adjacency alone also catches subjects, possessives,
                    # and the first piece of a split noun.
                    if (
                        dep in ("dobj", "obj", "iobj", "dative", "attr", "oprd")
                        and word.head.i == previous.i
                        and len(pieces) == 1
                    ):
                        target = previous_indices[-1]
                        local_argument = True
                        sink = 0.22 if pos == "PRON" else 0.18

            if not local_argument and dep in ("dobj", "obj", "attr", "oprd"):
                sink -= 0.10

        if i == 1:
            sink = 0.97
        sink = float(np.clip(sink, 0.12, 0.97))
        attention[i, 0] = sink
        remaining = 1.0 - sink

        weights = np.exp(
            -0.35 * (i - np.arange(1, i + 1, dtype=np.float64))
        )
        weights[-1] *= 0.65

        if target is not None:
            if local_argument:
                directed = 0.94
            else:
                directed = 0.35
            attention[i, target] += remaining * directed
            remaining *= 1.0 - directed

        attention[i, 1:i + 1] += remaining * weights / weights.sum()

    return "bos_sink_with_verified_local_arguments", make_row_stochastic(attention)


def prog_L21H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS-sink/self gate with a backward predicate-link exception:
    complement linkers can redirect BOS mass to the preceding predicate."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_link", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        clean = raw.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None

        sink, self_mass, previous = 0.60, 0.28, 0.04

        if not clean:
            sink, self_mass, previous = 0.07, 0.87, 0.02

        elif all(not c.isalnum() for c in clean):
            if any(c in ".!?" for c in clean):
                sink, self_mass, previous = 0.25, 0.66, 0.03
                if any(c in "\"“”" for c in clean):
                    sink, self_mass, previous = 0.45, 0.43, 0.04
            elif any(c in "'’" for c in clean):
                sink, self_mass, previous = 0.78, 0.13, 0.03
            elif any(c in "\"“”" for c in clean):
                sink, self_mass, previous = 0.69, 0.20, 0.03
            else:
                sink, self_mass, previous = 0.47, 0.42, 0.03

        elif word is not None:
            pos, dep = word.pos_, word.dep_
            next_word = doc[word.i + 1] if word.i + 1 < len(doc) else None
            boundary = next_word is None or next_word.is_punct
            split_after = (
                i + 1 < n
                and bool(set(aligned).intersection(alignment[i + 1]))
            )
            split_before = bool(set(aligned).intersection(alignment[i - 1]))

            if pos == "DET":
                if "Ind" in word.morph.get("Definite"):
                    sink, self_mass, previous = 0.36, 0.13, 0.43
                else:
                    sink, self_mass, previous = 0.81, 0.12, 0.02
            elif pos in ("PRON", "PROPN"):
                if dep in ("nsubj", "nsubjpass", "poss", "expl"):
                    sink, self_mass, previous = 0.70, 0.21, 0.03
                else:
                    sink, self_mass, previous = 0.39, 0.51, 0.04
            elif pos == "NOUN":
                if dep in ("nsubj", "nsubjpass", "compound"):
                    sink, self_mass, previous = 0.62, 0.27, 0.04
                else:
                    sink, self_mass, previous = 0.39, 0.50, 0.04
            elif pos in ("AUX", "VERB"):
                sink, self_mass, previous = 0.64, 0.25, 0.04
            elif pos in ("ADP", "PART", "SCONJ", "CCONJ"):
                sink, self_mass, previous = 0.61, 0.25, 0.06
            elif pos in ("ADJ", "ADV", "NUM"):
                sink, self_mass, previous = 0.53, 0.35, 0.05

            if boundary and pos in ("NOUN", "PROPN", "PRON", "ADJ", "ADV", "VERB", "AUX"):
                transfer = min(0.17, sink - 0.20)
                sink -= transfer
                self_mass += transfer

            if split_after:
                transfer = min(0.19, self_mass - 0.05)
                sink += transfer
                self_mass -= transfer
            elif split_before and pos in ("NOUN", "PROPN", "ADJ", "ADV", "VERB"):
                transfer = min(0.12, sink - 0.20)
                sink -= transfer
                self_mass += transfer

            if i == 1:
                transfer = min(0.09, self_mass - 0.04)
                sink += transfer
                self_mass -= transfer

            # Preserve self and background mass; only strengthen a narrowly
            # gated backward link from a complement marker to its predicate.
            if i > 1 and not split_before and not split_after and alignment[i - 1]:
                prev_word = doc[alignment[i - 1][-1]]
                adjacent = prev_word.i + 1 == word.i
                predicate_prep = (
                    pos == "ADP"
                    and (
                        prev_word.pos_ in ("ADJ", "ADV")
                        or (
                            prev_word.pos_ == "VERB"
                            and "Part" in prev_word.morph.get("VerbForm")
                            and word.head.i == prev_word.i
                        )
                    )
                )
                infinitive_link = (
                    pos == "PART"
                    and dep in ("aux", "mark")
                    and prev_word.pos_ == "VERB"
                    and "Inf" in word.head.morph.get("VerbForm")
                    and word.head.head.i == prev_word.i
                )
                if adjacent and (predicate_prep or infinitive_link):
                    transfer = min(0.15, max(0.0, sink - 0.20))
                    sink -= transfer
                    previous += transfer

        attention[i, 0] += sink
        attention[i, i] += self_mass
        attention[i, i - 1] += previous

        residual = max(0.0, 1.0 - sink - self_mass - previous)
        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 3.0)
        background /= background.sum()
        attention[i, :i + 1] += residual * background

    return "bos_sink_with_predicate_link", make_row_stochastic(attention)


def prog_L21H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with slowly increasing causal background mass.
    Residual attention is weakly biased toward recent tokens, not syntax.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_position_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 1.0 / (1.0 + 0.008 + 0.0025 * i)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        background = 0.65 + 0.35 * np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "bos_sink_with_position_decay", attention


def prog_L21H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local gates; nominal prepositional complements additionally
    retrieve their governing noun, including through a relative clause."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_attachment", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = aligned[i]
        word = doc[indices[0]] if indices else None

        # The sink remains dominant, but becomes less exclusive in long contexts.
        sink = float(np.clip(0.82 - 0.0035 * i, 0.48, 0.86))
        if i == 1:
            sink = 0.92
        elif word is not None:
            if word.pos_ in ("AUX", "CCONJ", "SCONJ", "PRON"):
                sink += 0.045
            elif word.pos_ in ("ADJ", "ADV", "ADP"):
                sink -= 0.035
        sink = float(np.clip(sink, 0.45, 0.95))

        # Allocate non-sink mass mainly to nearby positions, with a small tail.
        positions = np.arange(1, i + 1)
        residual = (
            0.8 * np.exp(-(i - positions) / 2.5)
            + 0.2 * np.exp(-(i - positions) / 14.0)
        )
        if word is not None and word.head.i != word.i:
            head_tokens = [j for j in inverse[word.head.i] if 0 < j <= i]
            if head_tokens:
                residual[head_tokens[-1] - 1] += 0.8

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        target = None
        strength = 0.0

        # Apostrophe pieces consistently point to the preceding contraction stem.
        if text in ("'", "’") and i > 1:
            target, strength = i - 1, 0.86

        # Indefinite articles strongly select the immediately preceding context.
        elif (
            word is not None
            and word.pos_ == "DET"
            and "Ind" in word.morph.get("Definite")
            and inverse[word.i]
            and i == inverse[word.i][0]
            and i > 1
        ):
            target, strength = i - 1, 0.76

        # Direct objects sometimes select a nearby governing predicate.
        elif word is not None and word.dep_ in ("dobj", "obj", "iobj"):
            head_tokens = [j for j in inverse[word.head.i] if 0 < j < i]
            if head_tokens and i - head_tokens[-1] <= 3:
                target = head_tokens[-1]
                strength = 0.58 if i - target == 1 else 0.38

        # Terminal punctuation often switches from the sink to itself.
        if text and all(c in ".!?”\"’" for c in text) and any(
            c in ".!?" for c in text
        ):
            target, strength = i, 0.62

        if target is not None:
            attention[i] *= 1.0 - strength
            attention[i, target] += strength

        # A nominal prepositional complement can retrieve the enclosing noun.
        # Transfer only BOS mass: self-attention and all other edges are intact.
        if (
            word is not None
            and word.pos_ in ("NOUN", "PROPN")
            and word.dep_ in ("pobj", "obl", "nmod")
            and word.head.pos_ == "ADP"
        ):
            governor = word.head.head
            amount = 0.32
            if (
                governor.pos_ in ("VERB", "AUX")
                and governor.dep_ in ("relcl", "acl")
            ):
                governor = governor.head
                amount = 0.26
            if governor.pos_ in ("NOUN", "PROPN"):
                candidates = [j for j in inverse[governor.i] if 0 < j < i]
                if candidates and 2 <= i - candidates[-1] <= 10:
                    transfer = min(amount, max(0.0, attention[i, 0] - 0.20))
                    attention[i, 0] -= transfer
                    attention[i, candidates[-1]] += transfer

    return "bos_sink_with_nominal_attachment", make_row_stochastic(attention)


def prog_L21H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predominantly a BOS attention sink, with weaker self and local attention.
    Linguistic features modestly modulate the strength of the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "PRON": 0.80,
        "AUX": 0.75,
        "DET": 0.69,
        "NOUN": 0.71,
        "PROPN": 0.70,
        "VERB": 0.65,
        "ADJ": 0.68,
        "ADV": 0.71,
        "ADP": 0.68,
        "CCONJ": 0.70,
        "SCONJ": 0.67,
        "PART": 0.71,
        "PUNCT": 0.77,
        "SPACE": 0.65,
    }

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        sink = sink_by_pos.get(word.pos_, 0.72) if word is not None else 0.72

        if word is not None:
            # Split lexical items often exhibit especially strong sink attention.
            pieces = [
                k for k in range(1, n)
                if sids[0] in alignment[k]
            ]
            if len(pieces) > 1 and word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.09 if i == pieces[0] else 0.03

            # Sentence-initial determiners show a stronger self alternative.
            if word.is_sent_start and word.pos_ == "DET":
                sink -= 0.15

        sink = float(np.clip(sink, 0.45, 0.88))
        remainder = 1.0 - sink

        # Allocate the non-sink mass to self, nearby context, and a diffuse tail.
        attention[i, 0] = sink
        attention[i, i] += 0.55 * remainder
        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        local /= local.sum()
        attention[i, 1:i + 1] += remainder * (
            0.30 * local + 0.15 / i
        )

    return "bos_sink_with_self_backoff", make_row_stochastic(attention)


def prog_L21H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with lexical self-attention and a strong
    apostrophe-to-preceding-fragment exception."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_lexical_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    specials = set(tokenizer.all_special_tokens)
    attention[0, 0] = 1.0

    for i in range(1, n):
        raw = tokens[i]
        text = raw.replace("▁", " ").replace("Ġ", " ").strip()
        aligned = alignment[i]
        word = None
        for k in aligned:
            if not doc[k].is_space:
                word = doc[k]
                break

        # Split apostrophes strongly retrieve the preceding lexical fragment.
        if text in ("'", "’", "‘") and i > 1:
            previous = tokens[i - 1].replace("▁", "").replace("Ġ", "")
            if any(c.isalpha() for c in previous):
                attention[i, 0] = 0.055
                attention[i, i - 1] = 0.93
                attention[i, i] = 0.015
                continue

        sink = 0.73
        if word is not None:
            pos = word.pos_
            if pos in ("PRON", "AUX", "PART"):
                sink = 0.87
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.83
            elif pos == "DET":
                sink = 0.77
            elif pos == "ADP":
                sink = 0.75
            elif pos == "VERB":
                sink = 0.76
            elif pos == "ADV":
                sink = 0.74
            elif pos == "ADJ":
                sink = 0.65
            elif pos in ("NOUN", "PROPN", "NUM"):
                sink = 0.57
            elif pos == "PUNCT":
                sink = 0.72

            if word.dep_ in ("nsubj", "nsubjpass") and pos == "PRON":
                sink = min(0.92, sink + 0.025)

        if not text or raw in specials:
            sink = 0.75

        # The first ordinary token has little competing lexical context.
        if i == 1:
            sink = 0.78

        remaining = 1.0 - sink
        attention[i, 0] = sink
        attention[i, i] += 0.80 * remaining
        attention[i, i - 1] += 0.12 * remaining

        # A small causal background avoids assigning all residual mass locally.
        distances = np.arange(i, 0, -1, dtype=np.float64)
        background = np.exp(-distances / 6.0)
        background /= background.sum()
        attention[i, :i] += 0.08 * remaining * background

    return "bos_sink_lexical_self", make_row_stochastic(attention)


def prog_L21H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker self/local attention and occasional
    quotation-boundary or morphologically related verb retrieval."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_contextual_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]

    attention[0, 0] = 1.0
    quote_start = None
    quote_marks = {'"', '“', '”', '«', '»'}

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        clean = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        is_quote = any(mark in clean for mark in quote_marks)
        continuation = (
            word is not None
            and i > 1
            and alignment[i]
            and alignment[i - 1]
            and alignment[i][0] == alignment[i - 1][0]
        )

        sink = 0.79
        if pos == "PROPN":
            sink = 0.88
        elif pos in ("NOUN", "DET", "ADP"):
            sink = 0.82
        elif pos in ("PRON", "AUX"):
            sink = 0.83
        elif pos == "VERB":
            sink = 0.68
        elif pos in ("ADJ", "ADV"):
            sink = 0.72
        elif pos == "PUNCT":
            sink = 0.58

        if dep in ("nsubj", "nsubjpass"):
            sink += 0.05
        elif dep in ("dobj", "obj", "attr", "acomp", "xcomp"):
            sink -= 0.08

        sink += 0.10 * np.exp(-(i - 1) / 7.0)
        sink -= 0.09 * (1.0 - np.exp(-i / 25.0))
        if continuation:
            sink += 0.05
        if not clean:
            sink = 0.62
        if i == 1:
            sink = 0.94

        residual = np.zeros(i + 1, dtype=np.float64)
        distances = i - np.arange(1, i + 1)
        residual[1:] = 0.12 + 0.18 * np.exp(-distances / 5.0)
        residual[i] += 0.55

        if word is not None:
            head_index = word.head.i
            for j in range(1, i):
                if head_index in alignment[j] and word.head.i != word.i:
                    residual[j] += 0.30

        if pos == "VERB":
            best_j = None
            best_similarity = 0.45
            for j in range(1, i):
                previous = words[j]
                if previous is None or previous.pos_ != "VERB":
                    continue
                if alignment[j] == alignment[i]:
                    continue
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                if similarity > best_similarity:
                    best_similarity = similarity
                    best_j = j
            if best_j is not None:
                strength = min(1.0, (best_similarity - 0.45) / 0.40)
                sink -= 0.24 * strength
                residual[best_j] += 5.0 * strength

        if quote_start is not None and pos == "VERB":
            if 1 <= i - quote_start <= 6:
                sink -= 0.22
                residual[quote_start] += 4.0

        if is_quote:
            sink -= 0.12
            if quote_start is None:
                quote_start = i
            else:
                quote_start = None

        sink = float(np.clip(sink, 0.28, 0.97))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * residual[1:] / residual[1:].sum()
        )

    return "bos_sink_with_contextual_retrieval", attention


def prog_L21H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with lexical-completion gating.
    Secondary attention favors self, nearby tokens, and contraction prefixes.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_lexical_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pieces = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            pieces[word_id].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        raw = tokens[i]
        clean = raw.lstrip("▁Ġ")
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # Early positions have a particularly strong sink prior.
        sink = 0.46 + 0.34 * np.exp(-(i - 1) / 6.0)
        if pos in ("DET", "ADP", "PART"):
            sink += 0.15
        elif pos in ("PRON", "PROPN"):
            sink += 0.09
        elif pos == "AUX":
            sink += 0.07
        elif pos in ("NOUN", "ADJ"):
            sink -= 0.10
        elif pos == "ADV":
            sink -= 0.04

        if dep in ("poss", "case", "mark"):
            sink += 0.05
        if i == 1:
            sink = 0.91 if pos in ("PRON", "PROPN") else 0.84

        # Incomplete lexical prefixes strongly prefer the sink; completed
        # content words are more likely to retain attention on themselves.
        if word is not None:
            word_pieces = pieces[word.i]
            lexical_pieces = [
                j for j in word_pieces
                if tokens[j].lstrip("▁Ġ")
                and any(c.isalnum() for c in tokens[j])
            ]
            if len(lexical_pieces) > 1 and any(c.isalnum() for c in clean):
                if i == lexical_pieces[0]:
                    sink = max(sink, 0.93)
                elif i != lexical_pieces[-1]:
                    sink = max(sink, 0.72)
                else:
                    sink = max(sink, 0.49)

        if clean and all(c in "\"“”«»" for c in clean):
            sink = 0.43
        elif pos == "PUNCT":
            sink = 0.43 + 0.24 * np.exp(-i / 10.0)

        sink = float(np.clip(sink, 0.25, 0.97))

        # A standalone space after punctuation usually reads the boundary.
        if not clean.strip():
            attention[i, 0] = 0.30
            attention[i, i - 1] += 0.65
            attention[i, i] += 0.05
            continue

        # Apostrophes often retrieve the preceding contraction prefix.
        if clean in ("'", "’"):
            negative = False
            for k in range(max(1, i - 1), min(n, i + 3)):
                for word_id in alignment[k]:
                    if doc[word_id].dep_ == "neg":
                        negative = True
            previous = 0.98 if negative else 0.60
            attention[i, i - 1] = previous
            attention[i, 0] += (1.0 - previous) * 0.88
            attention[i, i] += (1.0 - previous) * 0.12
            continue

        attention[i, 0] = sink
        residual = np.zeros(i + 1, dtype=np.float64)
        residual[i] = 1.35 if pos in ("NOUN", "ADJ", "PUNCT") else 0.85

        if i > 1:
            residual[1:i] += 0.18 * np.exp(
                -(i - np.arange(1, i)) / 3.0
            )
            residual[i - 1] += 0.30

        if word is not None and word.head.i != word.i:
            candidates = [j for j in pieces[word.head.i] if 0 < j <= i]
            if candidates:
                residual[candidates[-1]] += 0.24

        if word is not None:
            earlier_pieces = [j for j in pieces[word.i] if 0 < j < i]
            if earlier_pieces:
                residual[earlier_pieces[-1]] += 0.15

        residual /= residual.sum()
        attention[i, :i + 1] += (1.0 - sink) * residual

    return "bos_sink_with_lexical_gating", make_row_stochastic(attention)


def prog_L21H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a secondary self-attention component.
    Linguistic features modulate sink strength; residual attention is local and causal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "PRON": 0.74,
        "DET": 0.72,
        "NOUN": 0.70,
        "PROPN": 0.70,
        "AUX": 0.69,
        "ADP": 0.67,
        "ADJ": 0.64,
        "ADV": 0.63,
        "NUM": 0.65,
        "PART": 0.65,
        "VERB": 0.57,
        "SCONJ": 0.56,
        "CCONJ": 0.49,
        "PUNCT": 0.48,
        "INTJ": 0.53,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        sink = sink_by_pos.get(word.pos_, 0.66) if word is not None else 0.66

        # Sentence-initial tokens have especially little competing context.
        sink += 0.035 * np.exp(-(i - 1) / 5.0)

        # Split-word pieces generally retain the same sink-dominated behavior.
        if i > 1 and aligned and alignment[i - 1]:
            if aligned[0] == alignment[i - 1][0]:
                sink += 0.025

        sink = float(np.clip(sink, 0.40, 0.86))
        attention[i, 0] = sink
        remaining = 1.0 - sink

        if i == 1:
            attention[i, i] = remaining
            continue

        # Most non-sink mass stays on the query token itself.
        self_fraction = 0.68
        if word is not None and word.pos_ in ("PUNCT", "CCONJ", "VERB"):
            self_fraction = 0.76

        attention[i, i] = remaining * self_fraction

        # A small, broad recency tail avoids inventing strong syntactic edges.
        positions = np.arange(1, i)
        weights = 0.35 + np.exp(-(i - positions) / 5.0)
        attention[i, 1:i] = (
            remaining * (1.0 - self_fraction) * weights / weights.sum()
        )

    return "bos_sink_with_self", make_row_stochastic(attention)


def prog_L21H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weaker self, recency, and punctuation-boundary attention.
    Linguistic features modulate how strongly each query defaults to the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0
    last_boundary = None

    for i in range(1, n):
        words = [doc[k] for k in aligned[i] if k < len(doc)]
        word = None
        for candidate in words:
            if not candidate.is_space:
                word = candidate
                break

        sink = 0.70
        boundary = False

        if word is not None:
            pos = word.pos_
            if pos == "PRON":
                sink = 0.81
            elif pos == "AUX":
                sink = 0.77
            elif pos in ("DET", "PART"):
                sink = 0.73
            elif pos in ("ADP", "SCONJ", "CCONJ"):
                sink = 0.67
            elif pos == "VERB":
                sink = 0.66
            elif pos in ("NOUN", "PROPN", "ADJ", "ADV"):
                sink = 0.65

            if word.dep_ in ("nsubj", "nsubjpass") and pos == "PRON":
                sink += 0.02

            if word.is_punct:
                boundary = any(c in word.text for c in ".!?;:")
                sink = 0.77 if boundary else 0.62

        residual = 1.0 - sink
        attention[i, 0] = sink

        # Most non-sink mass remains on the query or its immediate context.
        attention[i, i] += residual * 0.55
        attention[i, i - 1] += residual * 0.20

        if last_boundary is not None:
            attention[i, last_boundary] += residual * 0.15
        else:
            attention[i, i] += residual * 0.15

        positions = np.arange(1, i + 1)
        recency = np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] += residual * 0.10 * recency / recency.sum()

        if boundary:
            last_boundary = i

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L21H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a self-attention gate; commas and quoted clause endings
    selectively redirect sink mass toward self and nearby context."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_gate", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        sink = 0.64

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos == "PRON":
                sink = 0.75
            elif pos == "PROPN":
                sink = 0.73
            elif pos == "NOUN":
                sink = 0.66
            elif pos == "DET":
                sink = 0.68
            elif pos == "AUX":
                sink = 0.65
            elif pos == "VERB":
                sink = 0.54
            elif pos == "ADJ":
                sink = 0.53
            elif pos == "CCONJ":
                sink = 0.55
            elif pos in ("ADP", "PART"):
                sink = 0.64

            if dep in ("nsubj", "nsubjpass", "poss"):
                sink += 0.035
            elif dep in ("ROOT", "conj", "acomp"):
                sink -= 0.035

            # Sentence openings often route more strongly to the sink.
            if i == 1:
                if pos in ("PRON", "PROPN"):
                    sink = 0.86
                elif pos == "DET":
                    sink = 0.58
                else:
                    sink = 0.76

            # Continuation pieces retain a slightly stronger sink prior.
            if i > 1 and aligned and alignment[i - 1]:
                if aligned[0] in alignment[i - 1]:
                    sink += 0.035

        if any(mark in tokens[i] for mark in (".", "!", "?")):
            sink = 0.74

        sink = float(np.clip(sink, 0.40, 0.90))
        if i == 1:
            attention[i, 0] = sink
            attention[i, i] = 1.0 - sink
        else:
            # A small causal background captures the weaker non-sink edges.
            attention[i, 1:i] = 0.035 / (i - 1)
            attention[i, i - 1] += 0.025
            attention[i, 0] = sink
            attention[i, i] = 0.94 - sink

        # Only punctuation-boundary rows depart from the original behavior.
        surface = tokens[i].lstrip("▁Ġ").strip()
        quoted_end = (
            any(mark in surface for mark in (".", "!", "?"))
            and any(quote in surface for quote in ('"', "”", "»"))
        )
        if i > 1 and (surface == "," or quoted_end):
            if quoted_end:
                attention[i, 0] -= 0.36
                attention[i, i] += 0.24
                attention[i, i - 1] += 0.04
                attention[i, 1:i] += 0.08 / (i - 1)
            else:
                attention[i, 0] -= 0.22
                attention[i, i] += 0.12
                attention[i, i - 1] += 0.10

    return "bos_sink_with_punctuation_gate", make_row_stochastic(attention)


def prog_L21H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A self-versus-BOS gating head: punctuation favors self, while pronouns
    and fragmented lexical tokens favor the initial attention sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_bos_linguistic_gate", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    specials = tokenizer.all_special_tokens

    for i in range(1, n):
        token = tokens[i]
        text = token.replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = None
        if indices:
            word = doc[max(
                indices,
                key=lambda k: (not doc[k].is_punct, len(doc[k].text))
            )]

        self_mass = 0.51
        residual = 0.07

        if token in specials:
            self_mass, residual = 0.30, 0.02
        elif not text:
            self_mass, residual = 0.51, 0.06
        elif all(not c.isalnum() for c in text):
            if any(c in ".?!" for c in text):
                self_mass, residual = 0.79, 0.04
            elif any(c in ",;:" for c in text):
                self_mass, residual = 0.68, 0.06
            else:
                self_mass, residual = 0.60, 0.07
        elif word is not None:
            pos, dep = word.pos_, word.dep_

            if pos == "PRON":
                self_mass = 0.31
                if dep in ("poss", "det"):
                    self_mass = 0.57
            elif pos == "DET":
                self_mass = 0.44
                if dep == "poss":
                    self_mass = 0.57
            elif pos in ("NOUN", "PROPN"):
                self_mass = 0.45
            elif pos in ("VERB", "AUX"):
                self_mass = 0.47
            elif pos in ("ADJ", "ADV"):
                self_mass = 0.53
            elif pos in ("ADP", "PART"):
                self_mass = 0.49
            elif pos in ("CCONJ", "SCONJ"):
                self_mass = 0.60
            elif pos == "NUM":
                self_mass = 0.38

            pieces = inverse[word.i]
            if len(pieces) > 1:
                if i == pieces[0]:
                    self_mass = 0.19
                    residual = 0.04
                elif i != pieces[-1]:
                    self_mass = 0.26
                    residual = 0.06
                else:
                    self_mass = 0.49

            if i == 1:
                if pos == "PRON":
                    self_mass = 0.205
                elif pos == "DET":
                    self_mass = 0.613
                else:
                    self_mass = 0.25
                residual = 0.0

        bos_mass = 1.0 - self_mass - residual
        attention[i, 0] = bos_mass
        attention[i, i] = self_mass

        if i > 1:
            positions = np.arange(1, i)
            weights = np.exp(-(i - positions) / 4.0)
            attention[i, 1:i] = residual * weights / weights.sum()
        else:
            attention[i, 0] += residual

    return "self_bos_linguistic_gate", make_row_stochastic(attention)


def prog_L21H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local residual attention; morphological apostrophes redirect
    sink mass to their lexical host and, for possessives, its adjective."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_apostrophe_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_pieces = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if 0 <= k < len(doc):
                word_pieces[k].append(i)

    sink_by_pos = {
        "PRON": 0.87,
        "AUX": 0.92,
        "PROPN": 0.83,
        "NOUN": 0.62,
        "VERB": 0.61,
        "ADJ": 0.45,
        "ADV": 0.68,
        "DET": 0.43,
        "ADP": 0.49,
        "PART": 0.67,
        "CCONJ": 0.85,
        "SCONJ": 0.65,
        "NUM": 0.58,
        "INTJ": 0.57,
        "PUNCT": 0.45,
        "SPACE": 0.47,
        "SYM": 0.77,
        "X": 0.72,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = [k for k in alignment[i] if 0 <= k < len(doc)]
        word = doc[indices[0]] if indices else None
        sink = sink_by_pos.get(word.pos_, 0.66) if word is not None else 0.64
        previous_share = 0.18
        local_share = 0.06

        if word is not None:
            if word.dep_ in ("nsubj", "nsubjpass", "csubj", "expl"):
                sink += 0.045
            if word.dep_ in ("aux", "auxpass", "cop"):
                sink = max(sink, 0.91)

            pieces = word_pieces[word.i]
            earlier = [j for j in pieces if 0 < j < i]
            later = [j for j in pieces if j > i]

            if later and not earlier and word.pos_ != "PUNCT":
                sink = max(sink, 0.92)
            elif earlier:
                sink = 0.60
                previous_share = 0.70
                local_share = 0.04

            if word.is_punct:
                if word.text in (",", ";", ":"):
                    sink = 0.73
                elif any(c in word.text for c in ".!?"):
                    sink = 0.30
                    previous_share = 0.12
                elif word.text in ("'", "’"):
                    sink = 0.36
                    previous_share = 0.78
                else:
                    sink = 0.65
                    previous_share = 0.24

        if tokens[i].strip("▁Ġ \t\r\n") == "":
            sink = 0.44
            previous_share = 0.80
            local_share = 0.03

        if i == 1:
            sink = max(sink, 0.79)
            if word is not None and word.pos_ in ("PRON", "PROPN"):
                sink = max(sink, 0.97)

        sink = float(np.clip(sink, 0.08, 0.98))
        residual = 1.0 - sink
        attention[i, 0] = sink
        attention[i, i] += residual * (1.0 - previous_share - local_share)

        previous = max(1, i - 1)
        attention[i, previous] += residual * previous_share

        start = max(1, i - 5)
        positions = np.arange(start, i + 1)
        weights = np.exp(-(i - positions) / 2.0)
        weights /= weights.sum()
        attention[i, positions] += residual * local_share * weights

        # Only morphological apostrophes: leave quotation marks and all other
        # rows unchanged, including their self-attention and local decay.
        if (
            i > 1
            and tokens[i].strip("▁Ġ \t\r\n") in ("'", "’")
            and word is not None
            and (
                word.dep_ in ("case", "neg", "aux", "auxpass")
                or any(k in alignment[i - 1] for k in indices)
            )
        ):
            host_indices = [
                k for k in alignment[i - 1] if 0 <= k < len(doc)
            ]
            if host_indices:
                host = doc[host_indices[-1]]
                if host.pos_ not in ("PUNCT", "SPACE", "SYM"):
                    fraction = 0.90 if word.dep_ == "neg" else 0.72
                    moved = attention[i, 0] * fraction
                    attention[i, 0] -= moved

                    modifier_positions = []
                    if host.pos_ in ("NOUN", "PROPN"):
                        for child in host.children:
                            if child.dep_ == "amod":
                                modifier_positions.extend(
                                    j for j in word_pieces[child.i]
                                    if 0 < j < i - 1
                                )

                    if modifier_positions:
                        attention[i, max(modifier_positions)] += moved * 0.45
                        attention[i, i - 1] += moved * 0.55
                    else:
                        attention[i, i - 1] += moved

    return "bos_sink_with_apostrophe_links", make_row_stochastic(attention)


def prog_L21H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a weaker local/self channel.
    Lexical onsets favor BOS; list punctuation and word endings favor self."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None
        sink = 0.85

        if word is not None:
            pos = word.pos_
            dep = word.dep_
            onset = i == 1 or not any(
                sid in alignment[i - 1] for sid in sids
            )

            if pos == "DET":
                sink = 0.93
                if dep == "det" and word.head.pos_ == "NOUN":
                    sink = 0.95
            elif pos == "PROPN":
                sink = 0.96 if onset else 0.82
            elif pos == "NOUN":
                sink = 0.89 if onset else 0.80
            elif pos == "ADJ":
                sink = 0.93 if dep == "amod" else 0.84
            elif pos == "PRON":
                sink = 0.88
                if dep == "poss":
                    sink = 0.91
            elif pos == "PART":
                sink = 0.93 if dep == "aux" else 0.84
            elif pos == "AUX":
                sink = 0.88
            elif pos == "VERB":
                sink = 0.81
            elif pos in ("ADP", "ADV", "SCONJ", "CCONJ"):
                sink = 0.78
            elif pos == "PUNCT":
                if any(c in tokens[i] for c in ".!?"):
                    sink = 0.88
                elif any(c in tokens[i] for c in "\"'“”‘’"):
                    sink = 0.87
                else:
                    sink = 0.71

                # Punctuation attached to a coordinated list often keeps
                # substantial probability on its own position.
                if word.text in (",", ";", ":"):
                    head = word.head
                    if head.dep_ == "conj" or (
                        head.pos_ in ("NOUN", "PROPN")
                        and any(c.dep_ == "conj" for c in head.children)
                    ):
                        sink = 0.30

            # Initial subpieces of split content words are strong sink queries.
            if onset and pos in ("NOUN", "PROPN", "ADJ"):
                if i + 1 < n and any(
                    sid in alignment[i + 1] for sid in sids
                ):
                    sink = min(0.98, sink + 0.07)

        if i == 1:
            sink = max(sink, 0.93)

        attention[i, 0] = sink
        residual = 1.0 - sink
        if i == 1:
            attention[i, i] = residual
        else:
            attention[i, i] = residual * 0.85
            attention[i, 1:i] = residual * 0.15 / (i - 1)

    return "bos_sink_with_local_self", make_row_stochastic(attention)


def prog_L21H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with a local-attention exception for copular and auxiliary-supported
    intransitive predicate chains; all other rows retain the original behavior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_predicate_exception", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        bos_mass = 0.86
        self_share = 0.65
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            pos = word.pos_

            if pos == "PRON":
                bos_mass = 0.92
            elif pos == "PROPN":
                bos_mass = 0.89
            elif pos == "NOUN":
                bos_mass = 0.85
            elif pos == "AUX":
                bos_mass = 0.87
            elif pos == "VERB":
                bos_mass = 0.72
                self_share = 0.82
            elif pos in ("DET", "ADP"):
                bos_mass = 0.73
            elif pos == "CCONJ":
                bos_mass = 0.87
            elif pos in ("ADJ", "ADV"):
                bos_mass = 0.84

            if word.dep_ in ("ROOT", "ccomp", "xcomp") and pos == "VERB":
                bos_mass -= 0.05

            if word.is_punct:
                bos_mass = 0.89 if word.is_sent_end else 0.81

            if word.is_space:
                bos_mass = 0.93

        if i == 1:
            bos_mass = 0.94

        residual = 1.0 - bos_mass
        attention[i, 0] = bos_mass
        attention[i, i] += residual * self_share

        previous = np.arange(1, i)
        if len(previous):
            weights = np.exp(-(i - previous) / 2.0)
            weights /= weights.sum()
            attention[i, previous] += residual * (1.0 - self_share) * weights
        else:
            attention[i, i] += residual * (1.0 - self_share)

    # Exception: move only BOS mass into a tightly gated predicate-local path.
    # The original self/local contributions and their decay remain intact.
    inverse = [[] for _ in doc]
    for ti, aligned in enumerate(alignment):
        for wi in aligned:
            inverse[wi].append(ti)

    copular = set()
    chains = set()
    for word in doc:
        children = list(word.children)
        if (
            word.pos_ == "AUX"
            and any(c.dep_ in ("acomp", "attr") and c.pos_ == "ADJ"
                    for c in children)
        ) or (
            word.pos_ == "ADJ"
            and any(c.dep_ == "cop" for c in children)
        ):
            copular.add(word.i)

        if word.pos_ == "VERB" and not any(
            c.dep_ in ("obj", "dobj", "iobj", "neg") for c in children
        ):
            if any(c.dep_ == "aux" and c.tag_ == "MD" for c in children):
                chains.add(word.i)
            elif any(
                c.dep_ == "xcomp"
                and any(a.pos_ == "AUX" for a in c.children)
                for c in children
            ):
                chains.add(word.i)
                for c in children:
                    if c.dep_ == "xcomp":
                        chains.add(c.i)

    for i in range(1, n):
        if not alignment[i]:
            continue
        word = doc[alignment[i][0]]
        head = word.head
        target = None
        share = 0.65
        anchors = []

        if word.i in copular and word.pos_ == "AUX":
            target, share = 0.22, 0.62
            anchors = [c.i for c in word.children
                       if c.dep_ in ("nsubj", "nsubjpass")]
        elif head.i in copular and word.dep_ in ("nsubj", "nsubjpass"):
            # Possessive subjects provide a particularly strong local anchor.
            if any(c.dep_ == "poss" for c in word.children):
                target, share = 0.18, 0.40
        elif word.pos_ == "ADV" and (
            head.i in copular
            or (head.pos_ == "ADJ" and head.head.i in copular)
        ):
            target, share = 0.10, 0.66
            if head.i in copular:
                share = 0.35
                anchors = [head.i] + [
                    c.i for c in head.children
                    if c.dep_ in ("nsubj", "nsubjpass")
                ]
        elif (
            word.dep_ == "cc"
            and head.pos_ == "ADJ"
            and (head.head.i in copular or head.head.head.i in copular)
        ):
            target, share = 0.12, 0.72
            anchors = [
                c.i for c in head.head.children if c.dep_ == "advmod"
            ]
        elif (
            copular
            and word.pos_ == "ADV"
            and word.dep_ == "advmod"
            and i > 1
            and alignment[i - 1]
            and doc[alignment[i - 1][0]].is_punct
            and any(k < word.i for k in copular)
        ):
            target, share = 0.14, 0.76
        elif word.i in chains:
            target = 0.34
            share = 0.64
            if any(c.dep_ == "xcomp" for c in word.children):
                target, share = 0.18, 0.80
            anchors = [
                c.i for c in word.children
                if c.dep_ in ("aux", "auxpass", "mark")
            ]
        elif head.i in chains and (
            word.dep_ in ("prt", "advmod")
            or word.pos_ == "AUX"
        ):
            target, share = 0.30, 0.56
            anchors = [head.i]

        if target is None:
            continue

        keys = []
        for wi in anchors:
            causal = [ti for ti in inverse[wi] if 0 < ti < i]
            if causal:
                keys.append(causal[-1])
        if not keys and i > 1:
            keys = [i - 1]

        moved = max(0.0, attention[i, 0] - target)
        attention[i, 0] -= moved
        if keys:
            attention[i, i] += moved * share
            for key in keys:
                attention[i, key] += moved * (1.0 - share) / len(keys)
        else:
            attention[i, i] += moved

    return "bos_sink_with_predicate_exception", make_row_stochastic(attention)


def prog_L21H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with self fallback; closing punctuation favors self-attention.
    Adverbial particles are exempt from the prepositional self-attention boost.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_punctuation_exceptions", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        bos_mass = 0.81 - 0.05 * i / (i + 32.0)
        local_mass = 0.04
        sids = alignment[i]

        if sids:
            word = doc[sids[0]]
            if word.pos_ == "ADP":
                bos_mass -= 0.27
            elif word.pos_ == "PUNCT":
                bos_mass -= 0.07
            elif word.pos_ in ("NOUN", "PROPN", "ADJ", "VERB"):
                bos_mass += 0.02

            # Continuation pieces have a slightly stronger self fallback.
            if i > 1 and sids[0] in alignment[i - 1]:
                bos_mass -= 0.06

            # Particles can be tagged ADP but do not behave like prepositions.
            if word.pos_ == "ADP" and word.dep_ == "prt":
                bos_mass += 0.27

        # Target punctuation exceptions without changing ordinary lexical rows.
        piece = tokens[i].lstrip("▁")
        if (
            piece
            and all(c in ".!?\"'’”" for c in piece)
            and any(c in ".!?" for c in piece)
        ):
            # Fused sentence-ending punctuation and quotes have stronger loops.
            bos_mass -= 0.38 if any(c in "\"'’”" for c in piece) else 0.20
        elif (
            piece in ("'", "’")
            and i + 1 < n
            and not tokens[i + 1].startswith("▁")
            and tokens[i + 1] not in tokenizer.all_special_tokens
        ):
            # An internal contraction apostrophe, rather than an opening quote.
            bos_mass -= 0.30

        attention[i, 0] = bos_mass
        attention[i, i] = 1.0 - bos_mass - local_mass

        positions = np.arange(1, i + 1)
        recency = np.exp((positions - i) / 2.0)
        attention[i, 1:i + 1] += local_mass * recency / recency.sum()

    return "bos_sink_with_punctuation_exceptions", make_row_stochastic(attention)


def prog_L21H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, strongest for function words and word-initial fragments.
    Residual attention favors self, recent tokens, and preceding syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        surface = tokens[i].replace("▁", " ").replace("Ġ", " ").strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # A persistent sink with a modest reduction beyond the opening context.
        sink = 0.68 + 0.20 * np.exp(-(i - 1) / 11.0)
        if pos in ("DET", "ADP", "PART"):
            sink += 0.10
        elif pos in ("PRON", "SCONJ"):
            sink += 0.04
        elif pos in ("VERB", "ADJ", "ADV"):
            sink -= 0.09
        elif pos in ("NOUN", "PROPN"):
            sink -= 0.03

        if dep == "poss":
            sink += 0.08

        first_fragment = False
        continuation = False
        if word is not None:
            pieces = inverse[word.i]
            if pieces:
                first_fragment = len(pieces) > 1 and pieces[0] == i
                continuation = pieces[0] < i
        if first_fragment:
            sink += 0.22
        elif continuation:
            sink -= 0.06

        punctuation = (
            word is not None and word.is_punct
        ) or (bool(surface) and all(not c.isalnum() for c in surface))
        quotation = any(c in "\"“”«»" for c in surface)
        if punctuation:
            sink -= 0.14
        if quotation:
            sink -= 0.20
        if not surface:
            sink -= 0.16

        sink = float(np.clip(sink, 0.27, 0.98))
        if i == 1:
            sink = 0.95

        residual = np.zeros(i + 1, dtype=np.float64)
        distances = i - np.arange(1, i + 1)
        residual[1:] = 0.18 * np.exp(-distances / 3.0)
        residual[i] += 0.48
        if i > 1:
            residual[i - 1] += 0.24

        if quotation or punctuation:
            residual[i] += 0.65
        if not surface and i > 1:
            residual[i - 1] += 0.75
        if continuation and word is not None:
            preceding = [j for j in inverse[word.i] if 0 < j < i]
            if preceding:
                residual[preceding[-1]] += 0.30

        if word is not None and word.head.i != word.i:
            preceding_heads = [j for j in inverse[word.head.i] if 0 < j < i]
            if preceding_heads:
                residual[preceding_heads[-1]] += 0.20

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    return "bos_sink_with_local_residual", make_row_stochastic(attention)


def prog_L21H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak local attention and persistent dialogue-boundary anchors."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special_tokens = set(tokenizer.all_special_tokens)
    cleaned = [t.lstrip("▁Ġ") for t in tokens]

    pos_tags = []
    dep_tags = []
    for indices in alignment:
        words = [doc[k] for k in indices if k < len(doc)]
        lexical = [w for w in words if w.pos_ not in ("SPACE", "PUNCT")]
        word = lexical[0] if lexical else (words[0] if words else None)
        pos_tags.append(word.pos_ if word is not None else "")
        dep_tags.append(word.dep_ if word is not None else "")

    question_anchor = None
    contraction_anchor = None
    in_quote = False

    attention[0, 0] = 1.0
    for i in range(1, n):
        text = cleaned[i]
        pos = pos_tags[i]
        punctuation = bool(text) and all(
            not c.isalnum() and not c.isspace() for c in text
        )

        sink = 0.78
        if pos in ("DET", "ADJ", "NUM"):
            sink = 0.87
        elif pos in ("NOUN", "PROPN"):
            sink = 0.84
        elif pos in ("ADP", "CCONJ", "SCONJ"):
            sink = 0.80
        elif pos in ("VERB", "AUX"):
            sink = 0.72
        elif pos == "PRON":
            sink = 0.76
        if punctuation:
            sink = 0.60
        if not text:
            sink = 0.50
        if i == 1:
            sink = 0.90

        targets = {}
        if question_anchor is not None:
            distance = i - question_anchor
            if distance <= 6:
                strength = 0.18
                if pos in ("VERB", "AUX"):
                    strength = 0.53
                elif not text:
                    strength = 0.48
                targets[question_anchor] = strength

        if contraction_anchor is not None:
            strength = 0.16
            if pos in ("VERB", "AUX", "ADP", "PART"):
                strength = 0.43
            if punctuation and any(c in text for c in ".!?"):
                strength = 0.54
            if not text:
                strength = 0.40
            targets[contraction_anchor] = strength

        anchor_mass = sum(targets.values())
        if anchor_mass > 0.64:
            scale = 0.64 / anchor_mass
            targets = {j: weight * scale for j, weight in targets.items()}
            anchor_mass = 0.64

        sink *= 1.0 - anchor_mass
        attention[i, 0] = sink
        for j, weight in targets.items():
            attention[i, j] += weight

        remainder = 1.0 - sink - anchor_mass
        positions = np.arange(1, i + 1)
        local = np.exp((positions - i) / 2.5)
        local[-1] *= 1.8
        attention[i, 1:i + 1] += remainder * local / local.sum()

        # Closing question punctuation can remain a salient dialogue boundary.
        if "?" in text:
            question_anchor = i

        apostrophe = text in ("'", "’")
        if apostrophe and in_quote and dep_tags[i] != "case":
            nearby = pos_tags[max(1, i - 1):min(n, i + 3)]
            if any(p in ("VERB", "AUX") for p in nearby):
                contraction_anchor = i

        if text not in special_tokens:
            if '"' in text:
                if text.count('"') % 2:
                    in_quote = not in_quote
            elif "“" in text:
                in_quote = True
            elif "”" in text:
                in_quote = False

    return "bos_sink_with_dialogue_anchors", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L21H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with self-copy; split nominal words favor BOS until their final
    subtoken, which transfers sink mass to the diagonal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_nominal_completion", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sink_by_pos = {
        "DET": 0.80,
        "ADJ": 0.75,
        "ADV": 0.69,
        "ADP": 0.65,
        "AUX": 0.62,
        "VERB": 0.60,
        "NOUN": 0.63,
        "PROPN": 0.76,
        "PRON": 0.62,
        "CCONJ": 0.57,
        "SCONJ": 0.65,
        "PART": 0.58,
        "NUM": 0.70,
        "PUNCT": 0.49,
        "SPACE": 0.66,
    }

    attention[0, 0] = 1.0

    for i in range(1, n):
        surface = tokens[i].replace("▁", "").replace("Ġ", "").strip()
        sids = aligned[i]
        word = doc[sids[-1]] if sids else None
        pos = word.pos_ if word is not None else ""
        sink = sink_by_pos.get(pos, 0.66)

        if word is not None:
            if word.dep_ == "poss":
                sink = 0.81
            elif word.dep_ in ("amod", "advmod", "predet"):
                sink += 0.04
            elif word.dep_ in ("nsubj", "nsubjpass") and i > 3:
                sink -= 0.10
            if word.ent_type_ and pos == "PROPN":
                sink += 0.04

        continuation = (
            i > 1
            and bool(sids)
            and bool(aligned[i - 1])
            and sids[0] in aligned[i - 1]
        )
        if continuation:
            sink -= 0.09

        if not surface:
            sink = 0.67
        if i == 1:
            sink = 0.91

        sink = float(np.clip(sink, 0.30, 0.94))

        # Preserve the original apostrophe exception.
        if surface in ("'", "’", "‘") and i > 1:
            attention[i, 0] = 0.16
            attention[i, i - 1] = 0.76
            attention[i, i] = 0.08
            continue

        attention[i, 0] = sink
        remaining = 1.0 - sink
        attention[i, i] += 0.80 * remaining
        attention[i, i - 1] += 0.12 * remaining

        # Weak causal contextual channel, subordinate to sink and diagonal.
        candidates = []
        if word is not None and word.head.i != word.i:
            for j in range(1, i):
                if word.head.i in aligned[j]:
                    candidates.append(j)

        if candidates:
            attention[i, candidates[-1]] += 0.08 * remaining
        else:
            attention[i, i] += 0.08 * remaining

        # Local exception: incomplete nominal subtokens sink to BOS;
        # completed nominal subtokens copy themselves. Transfer only between
        # BOS and self, leaving every contextual edge unchanged.
        if word is not None and pos in ("NOUN", "PROPN") and surface:
            continues_after = (
                i + 1 < n and word.i in aligned[i + 1]
            )
            continues_before = (
                i > 1 and word.i in aligned[i - 1]
            )
            if continues_after or continues_before:
                target_sink = 0.92 if continues_after else 0.20
                transfer = float(np.clip(
                    target_sink - attention[i, 0],
                    -attention[i, 0],
                    attention[i, i],
                ))
                attention[i, 0] += transfer
                attention[i, i] -= transfer

    return "bos_sink_with_nominal_completion", make_row_stochastic(attention)


def prog_L21H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with local leakage; apostrophes and single-letter nominal
    word starts can instead link strongly to their preceding token."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_split_links", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        sink_mass = 0.97

        if any(w.pos_ in ("PRON", "DET", "AUX", "PART") for w in words):
            sink_mass = 0.98
        elif any(w.pos_ in ("NOUN", "PROPN", "VERB") for w in words):
            sink_mass = 0.955
        elif words and all(w.is_punct for w in words):
            sink_mass = 0.945

        # Preserve the original local distribution exactly by default.
        positions = np.arange(1, i + 1)
        local = np.exp((positions - i) / 3.0)
        local /= local.sum()
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * local

        surface = tokens[i].lstrip("▁Ġ")
        if (
            i > 1
            and surface in ("'", "’")
            and any(w.dep_ == "neg" for w in words)
        ):
            attention[i, :] = 0.0
            attention[i, i - 1] = 0.976
            attention[i, 0] = 0.024

        elif (
            i > 1
            and surface in ("'", "’")
            and any(
                w.pos_ in ("AUX", "PART")
                or w.dep_ in ("aux", "auxpass", "case")
                or w.tag_ == "POS"
                for w in words
            )
        ):
            # Extend the contraction exception to auxiliary and possessive
            # clitics, without treating ordinary quotation marks as clitics.
            possessive = any(
                w.tag_ == "POS" or w.dep_ == "case" for w in words
            )
            if possessive:
                attention[i, 0] -= 0.43
                attention[i, i - 1] += 0.34
                attention[i, i - 2] += 0.09
            else:
                attention[i, 0] -= 0.83
                attention[i, i - 1] += 0.83

        elif (
            i > 1
            and i + 1 < n
            and tokens[i].startswith(("▁", "Ġ"))
            and len(surface) == 1
            and surface.isalpha()
            and any(
                w.pos_ in ("NOUN", "PROPN")
                and w.i in alignment[i + 1]
                for w in words
            )
        ):
            # A one-letter first piece of a split nominal word is a distinct
            # exception: move sink mass to the preceding piece and itself.
            possessive_predecessor = any(
                doc[k].tag_ == "POS" or doc[k].dep_ == "case"
                for k in alignment[i - 1]
            )
            previous_mass = 0.43 if possessive_predecessor else 0.36
            attention[i, 0] -= previous_mass + 0.21
            attention[i, i - 1] += previous_mass
            attention[i, i] += 0.21

    return "bos_sink_with_split_links", attention


def prog_L21H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with a secondary self-attention gate.
    Function words favor BOS; punctuation and discourse boundaries favor self."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_self_gate", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    sink_by_pos = {
        "DET": 0.94,
        "PRON": 0.88,
        "AUX": 0.83,
        "ADP": 0.76,
        "PART": 0.81,
        "PROPN": 0.78,
        "NOUN": 0.66,
        "ADJ": 0.73,
        "VERB": 0.66,
        "ADV": 0.62,
        "CCONJ": 0.57,
        "SCONJ": 0.65,
        "NUM": 0.76,
        "PUNCT": 0.48,
        "SPACE": 0.40,
    }

    for i in range(1, n):
        piece = tokens[i].lstrip("▁Ġ")
        word = doc[aligned[i][0]] if aligned[i] else None
        sink = sink_by_pos.get(word.pos_, 0.72) if word is not None else 0.72

        if word is not None:
            if word.dep_ in ("poss", "det"):
                sink = max(sink, 0.93)
            elif word.dep_ in ("nsubj", "nsubjpass") and word.pos_ == "PRON":
                sink = max(sink, 0.89)

            # Clause-level connectives can activate the diagonal alternative.
            if (
                word.pos_ in ("ADV", "CCONJ", "SCONJ")
                and word.dep_ in ("advmod", "discourse", "cc", "mark")
                and word.i > 0
                and doc[word.i - 1].is_punct
            ):
                sink = 0.34

            # Short initial fragments sometimes behave as strong self anchors.
            starts_word = tokens[i].startswith(("▁", "Ġ"))
            if (
                starts_word
                and len(piece) == 1
                and piece.isalpha()
                and len(word.text) > 1
                and word.pos_ in ("PROPN", "NOUN")
            ):
                sink = 0.18

            # Most continuation pieces still use the sink rather than linking
            # systematically to the preceding subword.
            elif (
                not starts_word
                and piece.isalpha()
                and len(piece) < len(word.text)
                and word.pos_ != "PUNCT"
            ):
                sink = max(sink, 0.78)

        if piece and all(c in "\"“”«»" for c in piece):
            sink = 0.32
        elif piece and all(c in "'’" for c in piece):
            sink = 0.81
        elif not piece:
            sink = 0.40

        if i == 1:
            sink = 0.97

        # A small causal-local component leaves BOS and self as the main modes.
        local_mass = 0.04 if i > 1 else 0.0
        attention[i, 0] = sink
        attention[i, i] = 1.0 - sink - local_mass

        if local_mass:
            positions = np.arange(1, i)
            weights = np.exp(-(i - positions) / 2.5)
            attention[i, 1:i] = local_mass * weights / weights.sum()

    return "bos_sink_with_self_gate", make_row_stochastic(attention)


def prog_L21H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with weak diffuse causal attention and recency bias.
    The sink remains dominant while background attention accumulates with context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "bos_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        positions = np.arange(1, i + 1)
        background = 0.35 + 0.65 * np.exp(-(i - positions) / 6.0)

        attention[i, 0] = 64.0
        attention[i, 1:i + 1] = background
        attention[i] /= attention[i].sum()

    return "bos_sink_with_diffuse_leakage", attention


def prog_L21H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS sink with boundary-gated quotation attention.
    Quote attraction weakens at speech onset and survives fragmented quote encoding.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_quote_sink_with_boundary_gating", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    quote_anchor = None

    # Recognize mojibake quotation marks without interpreting their fragments
    # as ordinary words. Opening marks can provide several attention targets.
    clean_tokens = [
        t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens
    ]
    encoded_boundaries = {}
    encoded_openers = {}
    for j in range(1, n - 1):
        if clean_tokens[j] == "â" and clean_tokens[j + 1] == "€":
            opening = j + 2 < n and clean_tokens[j + 2] == "œ"
            parts = tuple(range(j, j + (3 if opening else 2)))
            for k in parts:
                encoded_boundaries[k] = j if opening else None
            if opening:
                encoded_openers[j] = parts

    for i, token in enumerate(tokens):
        if i == 0:
            attention[i, i] = 1.0
            continue

        text = token.replace("▁", " ").replace("Ġ", " ").strip()
        mapped = alignment[i]
        word = None
        if mapped:
            word = doc[mapped[-1]]
            for k in mapped:
                if not doc[k].is_punct and not doc[k].is_space:
                    word = doc[k]
                    break

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        tag = word.tag_ if word is not None else ""
        punctuation = (
            word.is_punct if word is not None
            else bool(text) and all(not c.isalnum() for c in text)
        )

        # Determine the region before predicting this row. Closing quotes are
        # boundary tokens, not members of the quoted-content sink.
        active_anchor = quote_anchor
        next_anchor = quote_anchor
        has_quote = False
        closes_quote = False
        for char in text:
            if char in ('"', "“", "”", "«", "»"):
                has_quote = True
                if char in ("”", "»"):
                    next_anchor = None
                    closes_quote = True
                elif char in ("“", "«"):
                    next_anchor = i
                elif next_anchor is None:
                    next_anchor = i
                else:
                    next_anchor = None
                    closes_quote = True

        if i in encoded_boundaries:
            has_quote = True
            active_anchor = None
            next_anchor = encoded_boundaries[i]
            closes_quote = next_anchor is None

        if closes_quote:
            active_anchor = None

        bos_mass = 0.55
        self_mass = 0.13
        quote_mass = 0.0

        if pos in ("NOUN", "PROPN"):
            bos_mass = 0.66
            self_mass = 0.10
        elif pos == "DET":
            bos_mass = 0.66
            self_mass = 0.15
        elif pos == "PRON":
            bos_mass = 0.67
            self_mass = 0.12
        elif pos in ("VERB", "AUX"):
            bos_mass = 0.46
            self_mass = 0.18
        elif pos in ("ADJ", "ADV"):
            bos_mass = 0.53
            self_mass = 0.13

        if i <= 4:
            bos_mass = min(0.94, bos_mass + 0.15)
            self_mass = 0.07
        if i == 1:
            bos_mass, self_mass = 0.91, 0.09

        possessive = dep == "poss" or tag == "PRP$"
        indefinite = (
            word is not None
            and pos == "DET"
            and "Ind" in word.morph.get("Definite")
        )
        if possessive:
            bos_mass, self_mass = 0.18, 0.73
        elif indefinite:
            bos_mass, self_mass = 0.23, 0.65

        if punctuation:
            bos_mass, self_mass = 0.62, 0.10
            if text in ("'", "’"):
                bos_mass, self_mass = 0.84, 0.07
                if dep == "case":
                    bos_mass, self_mass = 0.35, 0.54

        if active_anchor is not None and not punctuation and not has_quote:
            if pos in ("NOUN", "PROPN", "VERB", "PRON", "ADJ", "ADV", "AUX"):
                quote_mass = 0.72
                bos_mass, self_mass = 0.12, 0.07
                if dep in ("dobj", "obj", "attr", "acomp", "ROOT"):
                    quote_mass = 0.84
                    bos_mass, self_mass = 0.07, 0.04

                # Initial pieces of split proper names often retain the BOS sink.
                if pos == "PROPN" and mapped:
                    starts_word = i == 1 or not any(
                        k in alignment[i - 1] for k in mapped
                    )
                    if starts_word and i + 1 < n and any(
                        k in alignment[i + 1] for k in mapped
                    ):
                        bos_mass, self_mass, quote_mass = 0.74, 0.06, 0.12

                if possessive:
                    bos_mass, self_mass, quote_mass = 0.12, 0.65, 0.14

        if has_quote:
            bos_mass, self_mass, quote_mass = 0.60, 0.13, 0.0

        # Special-case quotation boundaries and speech onset only. Ordinary
        # unquoted rows retain every original weight and decay parameter.
        if active_anchor is not None and not has_quote:
            parts = encoded_openers.get(active_anchor, (active_anchor,))
            first_content = i == parts[-1] + 1
            if text in ("'", "’") and dep != "case":
                bos_mass, self_mass, quote_mass = 0.84, 0.07, 0.0
            elif punctuation:
                bos_mass, self_mass, quote_mass = (
                    (0.04, 0.06, 0.82)
                    if active_anchor in encoded_openers
                    else (0.14, 0.10, 0.55)
                )
            elif pos == "INTJ":
                bos_mass, self_mass, quote_mass = 0.06, 0.13, 0.70
            elif first_content and not possessive and not indefinite:
                bos_mass, self_mass, quote_mass = 0.32, 0.26, 0.24
            elif active_anchor not in encoded_openers:
                if pos == "PRON" and not possessive:
                    bos_mass, self_mass, quote_mass = 0.40, 0.10, 0.34
                elif pos == "AUX":
                    bos_mass, self_mass, quote_mass = 0.35, 0.10, 0.30

        if i in encoded_boundaries:
            bos_mass, self_mass, quote_mass = 0.90, 0.04, 0.0

        residual = max(0.0, 1.0 - bos_mass - self_mass - quote_mass)
        distances = i - np.arange(i + 1)
        background = 0.35 / (i + 1) + 0.65 * np.exp(-distances / 3.0)
        background /= background.sum()
        attention[i, :i + 1] = residual * background
        attention[i, 0] += bos_mass
        attention[i, i] += self_mass
        if active_anchor is not None:
            if active_anchor in encoded_openers:
                parts = encoded_openers[active_anchor]
                for k, weight in zip(parts, (0.40, 0.35, 0.25)):
                    attention[i, k] += quote_mass * weight
            else:
                attention[i, active_anchor] += quote_mass

        quote_anchor = next_anchor

    return (
        "bos_quote_sink_with_boundary_gating",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L21H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict BOS sinks, with persistent dialogue-delimiter sinks.
    Malformed Unicode quotation marks can become especially strong sinks.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_with_dialogue_sinks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    special = tokenizer.all_special_tokens

    cleaned = [
        t.replace("▁", " ").replace("Ġ", " ").strip()
        for t in tokens
    ]
    pos = [
        doc[indices[0]].pos_ if indices else ""
        for indices in alignment
    ]

    first_content = 1 if tokens[0] in special and n > 1 else 0
    initial_determiner = pos[first_content] == "DET"

    apostrophes = []
    boundaries = []
    for j, text in enumerate(cleaned):
        if tokens[j] in special:
            continue
        if text and all(c in "'’" for c in text):
            apostrophes.append(j)
        elif not text:
            boundaries.append((j, 4.0))
        elif any(c in "?!" for c in text):
            boundaries.append((j, 2.8))

    # Extra sinks are enabled only for explicit quotation boundaries.
    # The escaped sequences are mojibake quotation punctuation, not words.
    malformed_quotes = "\u00e2\u20ac" in sentence
    dialogue_sinks = []
    quote_marks = '"“”„«»'
    for j, text in enumerate(cleaned):
        if tokens[j] in special:
            continue
        if malformed_quotes and "\u00e2" in text:
            dialogue_sinks.append((j, "encoded_quote", 6.0))
        elif malformed_quotes and "\u20ac" in text:
            dialogue_sinks.append((j, "encoded_inner", 18.0))
        elif any(c in quote_marks for c in text):
            closing = any(c in ".?!" for c in text)
            dialogue_sinks.append(
                (j, "closing" if closing else "quote",
                 4.5 if closing else 1.4)
            )
            # A speech-introducing comma is a separate, persistent key.
            if j > 0 and cleaned[j - 1] == ",":
                dialogue_sinks.append((j - 1, "comma", 4.0))
        elif (
            not text and j > 0
            and any(c in quote_marks for c in cleaned[j - 1])
            and any(c in ".?!" for c in cleaned[j - 1])
        ):
            dialogue_sinks.append((j, "space", 2.8))

    attention[0, 0] = 1.0
    for i in range(1, n):
        # A small, diffuse causal remainder prevents treating all unlisted
        # edges as zero; recent positions receive slightly more of it.
        distances = i - np.arange(i + 1)
        background = 0.35 + np.exp(-distances / 5.0)
        attention[i, :i + 1] = 0.55 * background / background.sum()

        bos = 3.6 + 4.0 * np.exp(-i / 8.0)
        if pos[i] in ("NOUN", "PROPN"):
            starts_word = (
                tokens[i].startswith(("▁", "Ġ"))
                or i == first_content
            )
            bos *= 1.65 if starts_word else 1.10
        elif pos[i] in ("ADJ", "ADV"):
            bos *= 1.12
        elif pos[i] in ("DET", "ADP", "CCONJ", "SCONJ", "PART"):
            bos *= 0.88

        if cleaned[i] and all(c in "'’" for c in cleaned[i]):
            bos *= 2.2
        if tokens[i] not in special and not cleaned[i]:
            bos *= 1.4

        earlier_apostrophes = [j for j in apostrophes if j < i]
        if initial_determiner and i > first_content:
            strength = 3.5 * (1.0 - np.exp(-(i - first_content) / 2.5))
            if earlier_apostrophes:
                strength *= 0.22
            attention[i, first_content] += strength

        # Apostrophe keys can remain salient across a long continuation.
        for j in earlier_apostrophes:
            age = i - j
            strength = 3.1 * (0.75 + 0.25 * np.exp(-age / 35.0))
            strength /= 1.0 + 0.5 * (len(earlier_apostrophes) - 1)
            attention[i, j] += strength

        # Dialogue boundaries act as shorter-lived local attention sinks.
        for j, strength in boundaries:
            if j < i:
                attention[i, j] += strength * np.exp(-(i - j - 1) / 8.0)

        attention[i, 0] += bos

        if i == first_content:
            if pos[i] == "DET":
                p_bos = 0.74
            elif pos[i] in ("PRON", "PROPN"):
                p_bos = 0.985
            else:
                p_bos = 0.93
            attention[i, :] = 0.0
            attention[i, 0] = p_bos
            attention[i, i] = 1.0 - p_bos

        # Transfer existing sink mass rather than adding row mass:
        # the original self-attention and diffuse remainder are preserved.
        active = [(j, kind, weight) for j, kind, weight in dialogue_sinks
                  if 0 < j < i]
        if active and i > first_content:
            weights = []
            latest_encoded = max(
                (j for j, kind, _ in active if kind == "encoded_quote"),
                default=-1
            )
            for j, kind, weight in active:
                if malformed_quotes:
                    if kind == "encoded_inner":
                        weight *= 1.0 if j > latest_encoded else 0.06
                    elif kind == "encoded_quote":
                        weight *= 1.0 if j == latest_encoded else 0.60
                    else:
                        weight *= 0.15
                else:
                    weight *= 0.65 + 0.35 * np.exp(-(i - j) / 30.0)
                weights.append(weight)

            total = sum(weights)
            fraction = total / (total + bos)
            # Rare encoded delimiters nearly replace the default BOS sink.
            if malformed_quotes:
                fraction = min(0.98, fraction + 0.18)

            moved = fraction * attention[i, 0]
            attention[i, 0] -= moved
            if initial_determiner:
                transfer = 0.75 * attention[i, first_content]
                attention[i, first_content] -= transfer
                moved += transfer

            for (j, _, _), weight in zip(active, weights):
                attention[i, j] += moved * weight / total

    return "bos_with_dialogue_sinks", make_row_stochastic(attention)


def prog_L21H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with quotation-boundary memory and local syntactic corrections.
    Apostrophes preferentially retrieve the preceding word fragment.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_quote_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if k < len(doc):
                inverse[k].append(i)

    clean = [t.replace("▁", " ").replace("Ġ", " ").strip() for t in tokens]
    special = set(tokenizer.all_special_tokens)
    active_quote = None
    last_close = None
    quote_pending = False

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        text = clean[i]
        word = None
        for k in alignment[i]:
            if k < len(doc) and not doc[k].is_space:
                word = doc[k]
                break

        distance = np.arange(i, -1, -1, dtype=np.float64)
        row = 0.36 + 0.20 * np.exp(-distance / 6.0)
        row[0] = 4.8
        row[i] += 0.22

        # Fragmented lexical items often preserve unusually strong sink attention.
        continuation = (
            i + 1 < n
            and tokens[i + 1] not in special
            and not tokens[i + 1].startswith(("▁", "Ġ"))
            and clean[i + 1].isalnum()
        )
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ") and continuation:
                row[0] *= 1.65 if len(text) <= 3 else 1.25
            if word.pos_ == "CCONJ":
                row[0] *= 0.85

        # Tokens inside direct speech retrieve its opening delimiter.
        if active_quote is not None:
            quote_strength = 0.58 * row.sum()
            if word is not None and word.pos_ in ("VERB", "NOUN", "PRON"):
                quote_strength *= 1.15
            row[active_quote] += quote_strength

        # Completed quotation boundaries remain weak discourse landmarks.
        if last_close is not None:
            row[last_close] += (
                0.28 * row.sum() * np.exp(-(i - last_close) / 48.0)
            )

        # Objects locally retrieve an earlier verbal governor.
        if word is not None and word.dep_ in ("dobj", "obj", "iobj", "pobj"):
            head = word.head
            if head.i < len(inverse):
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates and head.pos_ in ("VERB", "AUX"):
                    target = candidates[-1]
                    row[target] += 3.8 * np.exp(-max(0, i - target - 1) / 5.0)

        is_apostrophe = text in ("'", "’")
        contraction = (
            is_apostrophe
            and i > 0
            and bool(clean[i - 1])
            and clean[i - 1][-1].isalnum()
            and not tokens[i].startswith(("▁", "Ġ"))
        )

        # Recognize combined closing punctuation such as ?".
        has_double_quote = any(c in text for c in ('"', "“", "”"))
        closes_sentence = any(c in text for c in (".", "!", "?"))
        if has_double_quote:
            if active_quote is None or ("“" in text and "”" not in text):
                active_quote = i
                quote_pending = True
                row[0] *= 1.4
            else:
                row[i] += 0.48 * row.sum()
                last_close = i
                active_quote = None
                quote_pending = False
        elif text == "" and last_close is not None and i == last_close + 1:
            row[last_close] += 1.3 * row.sum()
        elif closes_sentence and active_quote is not None:
            row[i] += 0.25 * row.sum()
        elif quote_pending:
            row[0] *= 1.15
            quote_pending = False

        row /= row.sum()
        if contraction:
            previous_mass = 0.82
            if word is not None and word.dep_ == "case":
                previous_mass = 0.65
            row *= 1.0 - previous_mass
            row[i - 1] += previous_mass

        attention[i, :i + 1] = row

    return "bos_sink_quote_boundaries", attention


def prog_L21H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, weakening with context length.
    Linguistic and subword features modestly adjust the sink strength.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_position_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sids = alignment[i]
        word = doc[sids[0]] if sids else None

        # A dominant, approximately content-independent attention sink.
        sink_logit = 2.9 - 0.035 * i

        if word is not None:
            if word.pos_ in ("PRON", "DET"):
                sink_logit += 0.25
            elif word.pos_ == "PROPN":
                sink_logit += 0.20
            elif word.pos_ in ("VERB", "AUX", "ADJ", "ADV"):
                sink_logit -= 0.20
            elif word.pos_ == "PUNCT":
                sink_logit -= 0.60

            # Unfinished lexical tokens often retain especially strong BOS mass.
            continues = (
                i + 1 < n
                and any(sid in alignment[i + 1] for sid in sids)
            )
            if continues and word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_logit += 1.15

        if i == 1:
            sink_logit += 1.0

        sink_mass = float(1.0 / (1.0 + np.exp(-sink_logit)))

        # The examples identify the sink much more clearly than the residual
        # destinations: use a conservative, weakly recency-biased causal prior.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = np.exp(-distances / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "bos_sink_with_position_decay", attention


def prog_L21H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink with definite-article self-attention.
    Residual attention favors local context, subjects, possessors, and quote boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_article_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[ids[0]] if ids else None for ids in alignment]

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        bos_mass = 0.66
        self_mass = 0.10

        if pos == "PRON":
            bos_mass, self_mass = 0.90, 0.025
        elif pos == "PROPN":
            bos_mass, self_mass = 0.87, 0.035
        elif pos == "DET":
            if "Def" in word.morph.get("Definite"):
                bos_mass, self_mass = 0.13, 0.76
            elif dep == "poss":
                bos_mass, self_mass = 0.92, 0.025
            else:
                bos_mass, self_mass = 0.88, 0.035
        elif pos == "NOUN":
            bos_mass = 0.77 if dep in ("nsubj", "nsubjpass") else 0.58
        elif pos == "ADJ":
            bos_mass, self_mass = 0.77, 0.055
        elif pos == "ADV":
            bos_mass, self_mass = 0.76, 0.045
        elif pos == "AUX":
            bos_mass, self_mass = 0.77, 0.055
        elif pos == "VERB":
            bos_mass, self_mass = 0.53, 0.09
        elif pos in ("ADP", "SCONJ", "CCONJ", "PART"):
            bos_mass, self_mass = 0.57, 0.08
        elif pos == "PUNCT":
            bos_mass, self_mass = 0.35, 0.065
            if word.is_quote:
                bos_mass, self_mass = 0.72, 0.045

        # Internal wordpieces often retain exceptionally strong sink attention.
        if word is not None and i + 1 < n:
            if alignment[i] and alignment[i + 1]:
                if alignment[i][0] == alignment[i + 1][0]:
                    bos_mass = max(bos_mass, 0.94)
                    self_mass = min(self_mass, 0.02)

        if i == 1 and not (
            pos == "DET" and "Def" in word.morph.get("Definite")
        ):
            bos_mass = max(bos_mass, 0.95)
            self_mass = min(self_mass, 0.025)

        residual = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i):
            prior_word = words[j]
            score = 0.12 * np.exp(-(i - j) / 9.0)

            if prior_word is not None:
                if prior_word.dep_ in ("nsubj", "nsubjpass", "poss"):
                    score += 0.85 * np.exp(-(i - j) / 22.0)
                if prior_word.is_quote:
                    score += 0.65 * np.exp(-(i - j) / 16.0)
                if word is not None and word.head.i == prior_word.i:
                    score += 0.30

            residual[j] = score

        residual[i] = 0.18
        residual /= residual.sum()

        attention[i, :i + 1] = (
            (1.0 - bos_mass - self_mass) * residual
        )
        attention[i, 0] += bos_mass
        attention[i, i] += self_mass

    return "bos_sink_with_article_self", make_row_stochastic(attention)


def prog_L21H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """BOS attention sink, with weaker clause-subject and quoted-span anchors.
    Function words favor BOS; quoted content also attends to its opening quote.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "bos_sink_with_quote_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            word_tokens[k].append(i)

    special = set(tokenizer.all_special_tokens)
    quote_anchor = None
    previous_closed_quote = None
    quote_marks = {'"', '“', '”', '«', '»'}
    opening_marks = {'“', '«'}
    closing_marks = {'”', '»'}

    for i, token in enumerate(tokens):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        text = token.replace("▁", " ").replace("Ġ", " ")
        stripped = text.strip()
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.62
        if pos == "DET" or dep == "poss":
            sink = 0.96
        elif pos == "PROPN":
            sink = 0.90
        elif pos == "PRON":
            sink = 0.91 if dep in ("nsubj", "nsubjpass", "expl") else 0.69
        elif pos == "NOUN":
            sink = 0.87 if dep in ("nsubj", "nsubjpass") else 0.57
        elif pos == "ADJ":
            sink = 0.89 if dep == "amod" else 0.47
        elif pos == "ADV":
            sink = 0.88 if dep in ("advmod", "neg") else 0.65
        elif pos == "AUX":
            sink = 0.78
        elif pos == "VERB":
            sink = 0.49
        elif pos == "PART":
            sink = 0.87
        elif pos in ("ADP", "SCONJ", "CCONJ"):
            sink = 0.49
        elif pos == "PUNCT":
            sink = 0.42

        if i == 1 or token in special:
            sink = 0.99

        quote_target = quote_anchor
        is_opening = False
        is_closing = False
        for char in text:
            if char not in quote_marks:
                continue
            if char in opening_marks or (char == '"' and quote_anchor is None):
                quote_anchor = i
                is_opening = True
            elif char in closing_marks or char == '"':
                quote_target = quote_anchor
                quote_anchor = None
                previous_closed_quote = i
                is_closing = True

        quote_mass = 0.0
        if is_opening:
            sink = 0.70
            quote_target = None
        elif is_closing:
            sink = 0.24
        elif quote_target is not None:
            if pos in ("VERB", "NOUN", "ADP", "ADJ", "ADV"):
                sink = min(sink, 0.36)
                quote_mass = 0.43
            elif pos == "PRON" and dep in ("obj", "dobj", "pobj"):
                sink = 0.29
                quote_mass = 0.53
            elif pos in ("AUX", "PART"):
                sink = min(sink, 0.58)
                quote_mass = 0.20

        residual = np.exp(-np.arange(i, -1, -1, dtype=np.float64) / 5.0)
        residual[0] = 0.0
        residual[i] += 0.5

        if word is not None:
            for candidate in word.head.children:
                if candidate.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    eligible = [j for j in word_tokens[candidate.i] if 0 < j <= i]
                    if eligible:
                        residual[eligible[0]] += 2.0

        if is_closing:
            residual[i] += 5.0
        if not stripped and previous_closed_quote == i - 1:
            sink = 0.30
            residual[i - 1] += 8.0

        remaining = max(0.0, 1.0 - sink - quote_mass)
        attention[i, :i + 1] = remaining * residual / residual.sum()
        attention[i, 0] += sink
        if quote_target is not None and quote_target <= i:
            attention[i, quote_target] += quote_mass
        else:
            attention[i, 0] += quote_mass

    return "bos_sink_with_quote_anchors", make_row_stochastic(attention)
